CREATE TRIGGER [LMS].[tr_BatchDetailsInterfaceAPIModified]
   ON [LMS].[T_Batch_Details_Interface_API]
   AFTER UPDATE
AS BEGIN
    SET NOCOUNT ON;
    IF UPDATE (ActionStatus) OR UPDATE (NoofAttempts) OR UPDATE (StatusID) OR UPDATE (CompletedOn) OR UPDATE (Remarks)
    BEGIN
        INSERT INTO [LMS].[T_Batch_Details_Interface_API_A]
		SELECT [ID] 
		,[BrandID]
      ,[BrandName]
      ,[CentreID]
      ,[CentreCode]
      ,[CentreName]
      ,[BatchID]
      ,[BatchCode]
      ,[BatchName]
      ,[CourseID]
      ,[CourseName]
      ,[StudentStrength]
      ,[DayPreference]
      ,[BatchStartDate]
      ,[BatchEndDate]
      ,[BatchStatus]
      ,[TimeSlotsOffline]
      ,[TimeSlotsOnline]
      ,[TimeSlotsHandout]
      ,[ActionType]
      ,[ActionStatus]
      ,[NoofAttempts]
      ,[StatusID]
      ,[CreatedOn]
      ,[CompletedOn]
      ,[Remarks],
	  GETDATE(),
	  [ClassMode],
	  [MinBatchStrength]
	  FROM INSERTED I
    END 
END
GO
