											and CONVERT(DATE,TSBD.Dt_Valid_From)<=CONVERT(DATE,TTM.Dt_Schedule_Date)
											and CONVERT(DATE,ISNULL(TSBD.Dt_Valid_To,GETDATE()))>=CONVERT(DATE,TTM.Dt_Schedule_Date)
