--YTD

select CONVERT(DATE,TTM.Dt_Schedule_Date) as AttendanceDate,
TCHND.I_Center_ID,
TCHND.S_Center_Name,
TCM.I_Course_ID,
TCM.S_Course_Name,
TSBM.I_Batch_ID,
TSBM.S_Batch_Name,
TSBM.Dt_BatchStartDate,
TTM.I_TimeTable_ID,
