CASE WHEN TTM.I_ClassType=1 THEN 'Offline'
	 WHEN TTM.I_ClassType=2 THEN 'Online'
	 WHEN TTM.I_ClassType=3 OR TTM.I_ClassType IS NULL THEN 'N/A'
