tsm.I_Student_Marks_ID,
tsm.I_Student_Detail_ID,
TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '')
                + ' ' + TSD.S_Last_Name StudentName,
TSD.S_Student_ID,
tcm.I_Course_ID,
tcm.S_Course_Name,
TBEM.I_Batch_ID,
TSBM.S_Batch_Code,
TSBM.S_Batch_Name,
