PRINT N'Creating Function [EOS].[fnGetKRAEnquiryConvertionRate]...';


GO
-- =======================================================================
-- Author:		Swagatam Sarkar
-- Create date: 10/12/2007
-- Description:	This Function return a % Value of Enquiry Convertion KRA 
-- =======================================================================
CREATE FUNCTION [EOS].[fnGetKRAEnquiryConvertionRate]
(
	@iEmployeeID INT,
	@iCurrentMonth INT,
	@iCurrentYear INT
)

RETURNS  NUMERIC(18,2)

AS 

BEGIN

	DECLARE @EnquiryConvRate NUMERIC(18,2)
	DECLARE @EnquiryGen NUMERIC(18,2)
	DECLARE @EnrollmentGen NUMERIC(18,2)

	 SELECT @EnquiryGen=COUNT(*)
	   FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_User_Master UM
				ON ERD.S_Crtd_By=UM.S_Login_ID
				AND UM.I_Reference_ID=@iEmployeeID
				AND UM.S_User_Type='CE'
	  WHERE UM.I_Status<>0
		AND MONTH(ERD.Dt_Crtd_On)=@iCurrentMonth
		AND YEAR(ERD.Dt_Crtd_On)=@iCurrentYear

	SELECT @EnrollmentGen=COUNT(*)
	   FROM dbo.T_Student_Detail SD
			INNER JOIN dbo.T_User_Master UM
				ON SD.S_Crtd_By=UM.S_Login_ID
				AND UM.I_Reference_ID=@iEmployeeID
				AND UM.S_User_Type='CE'
	  WHERE UM.I_Status<>0
		AND MONTH(SD.Dt_Crtd_On)=@iCurrentMonth
		AND YEAR(SD.Dt_Crtd_On)=@iCurrentYear
	
	IF @EnquiryGen > 0
	BEGIN
		SET @EnquiryConvRate = ((@EnrollmentGen / @EnquiryGen) * 100)
	END
	ELSE
	BEGIN
		SET @EnquiryConvRate = 0
	END

	RETURN @EnquiryConvRate

END
GO
PRINT N'Creating Function [EOS].[fnGetKRAFacultyCertification]...';


GO
-- =============================================
-- Author:		Arindam Roy
-- Create date: '07/30/2007'
-- Description:	This Function return a Numeric Value of Faculty Certification KRA 
-- =============================================
CREATE FUNCTION [EOS].[fnGetKRAFacultyCertification]
(
	@iEmployeeID INT,
	@iCurtrentMonth INT,
	@iCurtrentYear INT
)

RETURNS  NUMERIC(18,2)

AS 

BEGIN

	DECLARE @FacultyCertification TABLE
	(
		I_Employee_ID INT,
		I_Centre_Id INT,
		I_Skill_ID INT,
		I_Exam_Component_ID INT
	)

	DECLARE @EmpID INT
	DECLARE @CenterID INT
	DECLARE @SkillID INT
	DECLARE @ExamComponentID INT
	DECLARE @SkillCount INT

	DECLARE FacultyCertification_cursor CURSOR FOR 
		 SELECT DISTINCT
				ED.I_Employee_ID,
				ED.I_Centre_Id,
				ESM.I_Skill_ID
		   FROM dbo.T_Employee_Dtls ED
				INNER JOIN EOS.T_Employee_Skill_Map ESM
					ON ED.I_Employee_ID=ESM.I_Employee_ID
		  WHERE ED.I_Employee_ID=@iEmployeeID

		OPEN FacultyCertification_cursor
		FETCH NEXT FROM FacultyCertification_cursor 
		INTO @EmpID,@CenterID,@SkillID

		WHILE @@FETCH_STATUS = 0
		BEGIN
			
			IF EXISTS ( SELECT I_Exam_Component_ID
						  FROM EOS.T_Skill_Exam_Map
						 WHERE I_Centre_ID=@CenterID
						   AND I_Skill_ID=@SkillID
					  )
			BEGIN
				SELECT @ExamComponentID=I_Exam_Component_ID
				  FROM EOS.T_Skill_Exam_Map
				 WHERE I_Centre_ID=@CenterID
				   AND I_Skill_ID=@SkillID
			END
			ELSE
			BEGIN
				SELECT @ExamComponentID=I_Exam_Component_ID
				  FROM EOS.T_Skill_Exam_Map
				 WHERE I_Centre_ID IS NULL
				   AND I_Skill_ID=@SkillID
			END

			INSERT INTO @FacultyCertification
			SELECT	@EmpID,@CenterID,@SkillID,@ExamComponentID

			FETCH NEXT FROM FacultyCertification_cursor 
			INTO @EmpID,@CenterID,@SkillID
		END
	CLOSE FacultyCertification_cursor
	DEALLOCATE FacultyCertification_cursor

	 SELECT @SkillCount=COUNT(DISTINCT I_Skill_ID)
	   FROM @FacultyCertification TMP
			INNER JOIN EOS.T_Employee_Exam_Result EER
				ON TMP.I_Exam_Component_ID=EER.I_Exam_Component_ID
				AND TMP.I_Employee_ID=EER.I_Employee_ID
	  WHERE EER.B_Passed=1
		AND MONTH(Dt_Crtd_On)=@iCurtrentMonth
		AND YEAR(Dt_Crtd_On)=@iCurtrentYear

	RETURN @SkillCount

END
GO
PRINT N'Creating Function [EOS].[fnGetKRAFacultyCompetency]...';


GO
-- =============================================
-- Author:		Arindam Roy
-- Create date: '07/30/2007'
-- Description:	This Function return a Numeric Value of Faculty Competency KRA 
-- =============================================
CREATE FUNCTION [EOS].[fnGetKRAFacultyCompetency]
(
	@iEmployeeID INT,
	@iCurtrentMonth INT,
	@iCurtrentYear INT
)

RETURNS  NUMERIC(18,2)

AS 

BEGIN

	DECLARE @FacultyCompetency TABLE
	(
		I_Centre_Id INT,
		I_Skill_ID INT,
		I_Exam_Component_ID INT
	)	

	DECLARE @FacultySkill TABLE
	(
		I_Skill_ID INT,
		FacultyCount INT
	)

	DECLARE @CenterID INT
	DECLARE @SkillID INT
	DECLARE @ExamComponentID INT
	DECLARE @SkillCount INT

	SELECT @CenterID=I_Centre_Id FROM dbo.T_Employee_Dtls WHERE I_Employee_ID=@iEmployeeID

	DECLARE FacultyCompetency_cursor CURSOR FOR 
	SELECT I_Skill_ID
	  FROM dbo.T_EOS_Skill_Master

	OPEN FacultyCompetency_cursor
	FETCH NEXT FROM FacultyCompetency_cursor 
	INTO @SkillID

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF EXISTS ( SELECT I_Exam_Component_ID
					  FROM EOS.T_Skill_Exam_Map
					 WHERE I_Centre_ID=@CenterID
					   AND I_Skill_ID=@SkillID
				  )
		BEGIN
			SELECT @ExamComponentID=I_Exam_Component_ID
			  FROM EOS.T_Skill_Exam_Map
			 WHERE I_Centre_ID=@CenterID
			   AND I_Skill_ID=@SkillID
		END
		ELSE
		BEGIN
			SELECT @ExamComponentID=I_Exam_Component_ID
			  FROM EOS.T_Skill_Exam_Map
			 WHERE I_Centre_ID IS NULL
			   AND I_Skill_ID=@SkillID
		END

		IF @ExamComponentID IS NOT NULL
		BEGIN
			INSERT INTO @FacultyCompetency
			SELECT	@CenterID,@SkillID,@ExamComponentID
		END
		SET @ExamComponentID=NULL

		FETCH NEXT FROM FacultyCompetency_cursor 
		INTO @SkillID
	END
	CLOSE FacultyCompetency_cursor
	DEALLOCATE FacultyCompetency_cursor

	INSERT INTO @FacultySkill
	 SELECT TMP.I_Skill_ID,COUNT(DISTINCT EER.I_Employee_ID) 
	   FROM EOS.T_Employee_Exam_Result EER
			INNER JOIN dbo.T_Employee_Dtls ED
				ON EER.I_Employee_ID=ED.I_Employee_ID
				AND ED.I_Centre_Id=@CenterID
			INNER JOIN @FacultyCompetency TMP
				ON EER.I_Exam_Component_ID=TMP.I_Exam_Component_ID
				AND ED.I_Centre_Id=TMP.I_Centre_Id
	  WHERE EER.B_Passed=1
--			AND ((YEAR(EER.Dt_Crtd_On)=@iCurtrentYear AND MONTH(EER.Dt_Crtd_On)<=@iCurtrentMonth) OR (YEAR(EER.Dt_Crtd_On)<=@iCurtrentYear))
   GROUP BY TMP.I_Skill_ID

	SELECT @SkillCount=COUNT(DISTINCT I_Skill_ID) 
	  FROM @FacultySkill 
	 WHERE FacultyCount>=2

	RETURN @SkillCount

END
GO
