PRINT N'Creating Function [EOS].[fnGetKRAStudentsAvgSalary]...';


GO
-- =====================================================================
-- Author:		Swagatam Sarkar
-- Create date: 10/12/2007'
-- Description:	This Function return a Numeric Value of Avg Salary KRA 
-- =====================================================================
CREATE FUNCTION [EOS].[fnGetKRAStudentsAvgSalary]
(
	@iEmployeeID INT,
	@iCurrentMonth INT,
	@iCurrentYear INT
)

RETURNS  NUMERIC(18,2)


AS 

BEGIN

	DECLARE @Salary NUMERIC(18,2)
	DECLARE @StudentNo NUMERIC(18,2)
	DECLARE @AvgSalary NUMERIC(18,2)

	 SELECT @Salary=ISNULL(SUM(TSS.N_Annual_Salary),0.00)
	   FROM PLACEMENT.T_Shortlisted_Students TSS
			INNER JOIN dbo.T_User_Master UM
				ON TSS.S_Crtd_By=UM.S_Login_ID
				AND UM.I_Reference_ID=@iEmployeeID
				AND UM.S_User_Type='CE'
	  WHERE TSS.I_Status<>0
		AND UM.I_Status<>0
		AND MONTH(TSS.Dt_Crtd_On)=@iCurrentMonth
		AND YEAR(TSS.Dt_Crtd_On)=@iCurrentYear

	SELECT @StudentNo=COUNT(*)
	   FROM PLACEMENT.T_Shortlisted_Students TSS
			INNER JOIN dbo.T_User_Master UM
				ON TSS.S_Crtd_By=UM.S_Login_ID
				AND UM.I_Reference_ID=@iEmployeeID
				AND UM.S_User_Type='CE'
	  WHERE TSS.I_Status<>0
		AND UM.I_Status<>0
		AND MONTH(TSS.Dt_Crtd_On)=@iCurrentMonth
		AND YEAR(TSS.Dt_Crtd_On)=@iCurrentYear

	IF @StudentNo > 0
	BEGIN
		SET @AvgSalary = ((@Salary / @StudentNo) / 1000.00)
	END

	RETURN @AvgSalary

END
GO
PRINT N'Creating Function [EOS].[fnGetKRAStudentsPlaced]...';


GO
-- ==========================================================================
-- Author:		Swagatam Sarkar
-- Create date: 10/12/2007'
-- Description:	This Function return a Numeric Value of Students Placed KRA 
-- ==========================================================================
CREATE FUNCTION [EOS].[fnGetKRAStudentsPlaced]
(
	@iEmployeeID INT,
	@iCurrentMonth INT,
	@iCurrentYear INT
)

RETURNS  NUMERIC(18,2)

AS 

BEGIN

	DECLARE @StudentRegd NUMERIC(18,2)
	DECLARE @StudentPlaced NUMERIC(18,2)
	DECLARE @Ratio NUMERIC(18,2)

	 SELECT @StudentPlaced = COUNT(*)
	   FROM PLACEMENT.T_Shortlisted_Students TSS
			INNER JOIN dbo.T_User_Master UM
				ON TSS.S_Crtd_By=UM.S_Login_ID
				AND UM.I_Reference_ID=@iEmployeeID
				AND UM.S_User_Type='CE'
	  WHERE TSS.I_Status<>0
		AND UM.I_Status<>0
		AND MONTH(TSS.Dt_Crtd_On)=@iCurrentMonth
		AND YEAR(TSS.Dt_Crtd_On)=@iCurrentYear

	SELECT @StudentRegd = COUNT(*)
	   FROM PLACEMENT.T_Placement_Registration TPR
			INNER JOIN dbo.T_User_Master UM
				ON TPR.S_Crtd_By=UM.S_Login_ID
				AND UM.I_Reference_ID=@iEmployeeID
				AND UM.S_User_Type='CE'
	  WHERE TPR.I_Status<>0
		AND UM.I_Status<>0
		AND MONTH(TPR.Dt_Crtd_On)=@iCurrentMonth
		AND YEAR(TPR.Dt_Crtd_On)=@iCurrentYear

	IF @StudentRegd > 0
	BEGIN
		SET @Ratio = ((@StudentPlaced / @StudentRegd) * 100.00)
	END

	RETURN @Ratio

END
GO
PRINT N'Creating Function [EXAMINATION].[fnCheckStudentCourseEnrollment]...';


GO
/****************************************************************************/

CREATE FUNCTION [EXAMINATION].[fnCheckStudentCourseEnrollment]
(
	@iStudentID INT,
	@iCourseID INT,
	@iTermID INT,
	@iModuleID INT = NULL
)
RETURNS CHAR(1)

AS
BEGIN
	DECLARE @cReturn CHAR(1)
	SET @cReturn = 'N'	
	
	IF (@iModuleID IS NULL OR @iModuleID = 0)
	BEGIN
		IF EXISTS(SELECT I_Student_Term_Detail_ID FROM dbo.T_Student_Term_Detail WHERE I_Student_Detail_ID = @iStudentID
					AND I_Course_ID = @iCourseID AND I_Term_ID = @iTermID AND I_Is_Completed = 0)
		BEGIN
			SET @cReturn = 'Y'
		END
	END
	ELSE
	BEGIN
		IF EXISTS(SELECT I_Student_Module_Detail_ID FROM dbo.T_Student_Module_Detail WHERE I_Student_Detail_ID = @iStudentID
					AND I_Course_ID = @iCourseID AND I_Term_ID = @iTermID AND I_Module_ID = @iModuleID AND I_Is_Completed = 0)
		BEGIN
			SET @cReturn = 'Y'
		END		
	END
	
	RETURN @cReturn
END
GO
