PRINT N'Creating Function [EXAMINATION].[ufnGetPreviousTermCompletionStatus]...';


GO
-- =============================================
-- Author:		Debarshi Basu
-- Create date: '24/05/2007'
-- Description:	Determines if the student has completed the 
--		previous terms successfully to appear for the next term evaluation exam
-- =============================================
CREATE FUNCTION [EXAMINATION].[ufnGetPreviousTermCompletionStatus]
(
	@iStudentID INT, 
	@iCourseID INT, 
	@iTermID INT
)
RETURNS  CHAR(1)

AS 
-- Returns the Student Status whether ACTIVE, ON LEAVE or DROPOUT.
BEGIN

DECLARE @cCompletionStatus CHAR(1)
DECLARE @iNoOfCompleteTerm INT, @iNoOfTotalTerms INT

SELECT @iNoOfTotalTerms = COUNT(DISTINCT I_Term_ID) 
FROM dbo.T_Student_Term_Detail WITH(NOLOCK)
WHERE I_Course_ID = @iCourseID
AND I_Term_ID IN (
					SELECT I_Term_ID 
					FROM dbo.T_Term_Course_Map WITH(NOLOCK)
					WHERE I_Course_ID = @iCourseID
					AND I_Status = 1
					AND I_Sequence < 
									(SELECT I_Sequence 
										FROM dbo.T_Term_Course_Map WITH(NOLOCK)
										WHERE I_Course_ID = @iCourseID
										AND I_Term_ID = @iTermID
										AND I_Status = 1 )
					)

SELECT @iNoOfCompleteTerm = COUNT(*) 
FROM dbo.T_Student_Term_Detail WITH(NOLOCK)
WHERE I_Course_ID = @iCourseID
AND I_Student_Detail_ID = @iStudentID
AND ISNULL(I_Is_Completed,0) = 1
AND I_Term_ID IN (
					SELECT I_Term_ID 
					FROM dbo.T_Term_Course_Map WITH(NOLOCK)
					WHERE I_Course_ID = @iCourseID
					AND I_Status = 1
					AND I_Sequence < 
									(SELECT I_Sequence 
										FROM dbo.T_Term_Course_Map WITH(NOLOCK)
										WHERE I_Course_ID = @iCourseID
										AND I_Term_ID = @iTermID
										AND I_Status = 1 )
					)

IF (@iNoOfCompleteTerm >= @iNoOfTotalTerms)
	BEGIN
		SET @cCompletionStatus = 'Y'
	END
ELSE
	BEGIN
		SET @cCompletionStatus = 'N'
	END

RETURN @cCompletionStatus
END
GO
PRINT N'Creating Function [EXAMINATION].[fnCheckFinancialCriteria]...';


GO
/************************************************************************************/

CREATE FUNCTION [EXAMINATION].[fnCheckFinancialCriteria]
(
	@iStudentID INT,
	@iCenterID INT,
	@iCourseID INT,
	@iTermID INT = NULL,
	@iModuleID INT = NULL,
	@TotalSession INT,
	@iSessionsUptoCurrentTerm INT
)
RETURNS  CHAR(1)

AS 
BEGIN
	DECLARE @cReturn CHAR(1), @nTotalAmount NUMERIC(18,2), @nTotalPayment NUMERIC(18,2)
	SET @cReturn = 'N'
	SET @nTotalAmount = 0.0
	SET @nTotalPayment = 0.0
	
	SELECT @nTotalAmount = @nTotalAmount + TICD.N_Amount_Due FROM dbo.T_Invoice_Child_Detail TICD WITH(NOLOCK)	
	WHERE I_Invoice_Child_Header_ID IN (
											SELECT DISTINCT	TICH.I_Invoice_Child_Header_ID 
											FROM	dbo.T_Invoice_Child_Header TICH WITH(NOLOCK)
											INNER JOIN dbo.T_Invoice_Parent TIP WITH(NOLOCK)
												ON	TICH.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
											WHERE	TICH.I_Course_ID = @iCourseID
													AND TIP.I_Student_Detail_ID = @iStudentID
										)
		
	SELECT @nTotalPayment = @nTotalPayment + TRCD.N_Amount_Paid
	FROM	dbo.T_Receipt_Header TRH WITH(NOLOCK)
		INNER JOIN	dbo.T_Receipt_Component_Detail TRCD WITH(NOLOCK)
				ON	TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
	WHERE I_Invoice_Header_ID IN (
											SELECT DISTINCT	TICH.I_Invoice_Header_ID 
											FROM	dbo.T_Invoice_Child_Header TICH WITH(NOLOCK)
											INNER JOIN dbo.T_Invoice_Parent TIP WITH(NOLOCK)
												ON	TICH.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
											WHERE	TICH.I_Course_ID = @iCourseID
													AND TIP.I_Student_Detail_ID = @iStudentID
										)
			
	IF (@TotalSession > 0 AND @nTotalPayment - (@nTotalAmount * (CAST(@iSessionsUptoCurrentTerm AS NUMERIC(18,2)) / CAST(@TotalSession AS NUMERIC(18,2)))) > -10)
	BEGIN
		SET @cReturn = 'Y'
	END
	ELSE IF (@TotalSession = 0 AND ABS(@nTotalPayment - @nTotalAmount) < 10)
	BEGIN
		SET @cReturn = 'Y'
	END
		
	RETURN @cReturn
END
GO
PRINT N'Creating Function [PSCERTIFICATE].[fnCheckCourseCompletion]...';


GO
/*******************************************************************************************************
* Author		:	Abhisek Bhattacharya
* Create date	:	27/06/2007
* Description	:	This Function checks whether the course
					for a student is completed
					This is determined based on the whether all the terms under the course
					is completed for the student 
* Return		:	Integer
*******************************************************************************************************/
CREATE FUNCTION [PSCERTIFICATE].[fnCheckCourseCompletion]
(
	@iStudentID INT,
	@iCourseID INT
)
RETURNS INT

AS
BEGIN
	DECLARE @iTemp INT
	
	IF EXISTS ( SELECT STD.I_Student_Term_Detail_ID
		FROM dbo.T_Student_Term_Detail STD
		INNER JOIN dbo.T_Term_Course_Map TCM
		ON STD.I_Course_ID = TCM.I_Course_ID
		AND STD.I_Term_ID = TCM.I_Term_ID
		AND TCM.I_Status = 1
		AND STD.I_Student_Detail_ID = @iStudentID
		AND STD.I_Course_ID = @iCourseID
		AND STD.I_Is_Completed = 0 )
	BEGIN
		SET @iTemp = 0
	END
	ELSE
	BEGIN
		SET @iTemp = 1
	END

	RETURN @iTemp
END
GO
PRINT N'Creating Function [PSCERTIFICATE].[fnGetTotalCourseDuration]...';


GO
CREATE FUNCTION [PSCERTIFICATE].[fnGetTotalCourseDuration]
(
	@iCourseId INT
)
RETURNS NUMERIC(18,2)
AS
BEGIN
	DECLARE @Duration NUMERIC(18,2)

	SELECT @Duration = ISNULL(SUM([TSM].[N_Session_Duration]),0)/60 
	FROM [dbo].[T_Term_Course_Map] AS TTCM	
	INNER JOIN [dbo].[T_Module_Term_Map] AS TMTM
	ON [TTCM].[I_Term_ID] = [TMTM].[I_Term_ID]
	AND [TMTM].[I_Status] = 1
	INNER JOIN [dbo].[T_Session_Module_Map] AS TSMM
	ON [TMTM].[I_Module_ID] = [TSMM].[I_Module_ID]
	AND [TSMM].[I_Status] = 1
	INNER JOIN [dbo].[T_Session_Master] AS TSM
	ON [tsmm].[I_Session_ID] = [TSM].[I_Session_ID]
	AND [TSM].[I_Status] = 1
	WHERE [TTCM].[I_Course_ID] = @iCourseId
	AND [TTCM].[I_Status] = 1
	
	RETURN @Duration
END
GO
PRINT N'Creating Function [PSCERTIFICATE].[uspGetPerformanceRating]...';


GO
CREATE FUNCTION [PSCERTIFICATE].[uspGetPerformanceRating]
(
	@iStudentID INT,
	@iCourseID INT
)
RETURNS VARCHAR(20)
AS
BEGIN
	DECLARE @iTotalTermCount INT, @iTotalMarks INT, @iWeightedMarks NUMERIC(18,2), @sGrade VARCHAR(20)
	
	SELECT @iTotalTermCount = COUNT([TSTD].[I_Student_Term_Detail_ID]) FROM [dbo].[T_Student_Term_Detail] AS TSTD
	WHERE [TSTD].[I_Student_Detail_ID] = @iStudentID AND [TSTD].[I_Course_ID] = @iCourseID
	AND [TSTD].[S_Term_Final_Marks] IS NOT NULL

	SELECT @iTotalMarks = SUM([TSTD].[S_Term_Final_Marks]) FROM [dbo].[T_Student_Term_Detail] AS TSTD
	WHERE [TSTD].[I_Student_Detail_ID] = @iStudentID AND [TSTD].[I_Course_ID] = @iCourseID
	AND [TSTD].[S_Term_Final_Marks] IS NOT NULL
	
	SELECT @iWeightedMarks = @iTotalMarks / @iTotalTermCount
	
	SELECT @sGrade = S_Grade_Type
	FROM dbo.T_Grading_Pattern_Detail
	WHERE I_Grading_Pattern_ID = (SELECT I_Grading_Pattern_ID FROM dbo.T_Course_Master WHERE I_Course_ID = @iCourseID)
	AND I_MinMarks <= @iWeightedMarks
	AND I_MaxMarks >= @iWeightedMarks
	
	RETURN @sGrade
END
GO
