			IF NOT EXISTS (SELECT I_MBP_Detail_ID FROM MBP.T_MBP_Detail	WHERE I_Month =@iMonth	AND I_Year = @iYear	AND I_Center_ID =@iCenterID	AND I_Type_ID=@iTypeID	AND	I_Product_ID=@iProductID)
