				AND I_Type_ID=@iTypeID
				AND	I_Product_ID=@iProductID
				AND I_MBP_Detail_Audit_ID=(SELECT MAX(I_MBP_Detail_Audit_ID) FROM MBP.T_MBP_Detail_Audit)
				)
			END
		END
	END
	IF @iType =3
