PRINT N'Creating Function [REPORT].[fnGetLastInstallmentAmtForReports]...';


GO
-- =============================================
-- Author:		Arindam Roy
-- Create date: '06/18/2007'
-- Description:	This Function return Last Installment Amount 
-- =============================================
CREATE FUNCTION [REPORT].[fnGetLastInstallmentAmtForReports]
(
	@I_Invoice_Header_ID INT,
	@I_Course_ID INT
)
RETURNS NUMERIC(18,2)

AS 

BEGIN

	DECLARE @I_Invoice_Child_Header_ID INT
	DECLARE @I_Receipt_Header_ID INT
	DECLARE @Amount_Paid NUMERIC(18,2)
	DECLARE @Tax_Paid NUMERIC(18,2)
	DECLARE @LastPaymentAmt NUMERIC(18,2)
	DECLARE @LastPaymentDate DATETIME

	SELECT @I_Invoice_Child_Header_ID=I_Invoice_Child_Header_ID
	   FROM dbo.T_Invoice_Child_Header
	  WHERE I_Invoice_Header_ID=@I_Invoice_Header_ID
		AND I_Course_ID=@I_Course_ID

	 SELECT @LastPaymentDate=MAX(Dt_Receipt_Date) 
	   FROM dbo.T_Receipt_Header
	  WHERE I_Invoice_Header_ID= @I_Invoice_Header_ID

	 SELECT @I_Receipt_Header_ID=I_Receipt_Header_ID
	   FROM dbo.T_Receipt_Header
	  WHERE I_Invoice_Header_ID= @I_Invoice_Header_ID
		AND Dt_Receipt_Date=@LastPaymentDate

	 SELECT @Amount_Paid=SUM(ISNULL(N_Amount_Paid,0.00))
	   FROM dbo.T_Invoice_Child_Detail ICD,
			dbo.T_Receipt_Component_Detail RCD
	  WHERE ICD.I_Invoice_Child_Header_ID=@I_Invoice_Child_Header_ID
		AND ICD.I_Invoice_Detail_ID=RCD.I_Invoice_Detail_ID
		AND RCD.I_Receipt_Detail_ID=@I_Receipt_Header_ID

	 SELECT @Tax_Paid=SUM(ISNULL(N_Tax_Paid,0.00))
	   FROM dbo.T_Invoice_Child_Detail ICD,
			dbo.T_Receipt_Component_Detail RCD
			LEFT OUTER JOIN dbo.T_Receipt_Tax_Detail RTD
			ON RCD.I_Receipt_Comp_Detail_ID=RTD.I_Receipt_Comp_Detail_ID
	  WHERE ICD.I_Invoice_Child_Header_ID=@I_Invoice_Child_Header_ID
		AND ICD.I_Invoice_Detail_ID=RCD.I_Invoice_Detail_ID
		AND RCD.I_Receipt_Detail_ID=@I_Receipt_Header_ID

	SET @LastPaymentAmt=@Amount_Paid + @Tax_Paid

	RETURN @LastPaymentAmt;

END
GO
PRINT N'Creating Function [REPORT].[fnGetTrainerFeedbackReports]...';


GO
-- =============================================
-- Author:		Arindam Roy
-- Create date: '07/20/2007'
-- Description:	This Function return a Numeric Value of Trainer Feedback with respect to Feedback Group
-- =============================================
CREATE FUNCTION [REPORT].[fnGetTrainerFeedbackReports]
(
	@iTrainingID INT,
	@iParticipantID INT,
	@iFeedbackGroupID INT
)

RETURNS  NUMERIC(8,2)

AS 

BEGIN

	DECLARE @TempTrainingFeedback TABLE
	(
		I_Feedback_Group_ID INT,
		Feedback NUMERIC(18,2)
	)

	DECLARE @TrainingFeedbackID INT
	DECLARE @AvgFeedbackTrainer NUMERIC(8,2)


	 SELECT @TrainingFeedbackID=I_Training_Feedback_ID
	   FROM	ACADEMICS.T_Training_Feedback
	  WHERE I_Training_ID=@iTrainingID
		AND Feedback_Provided_UserId=@iParticipantID
		AND I_Feedback_Type_ID=2


	INSERT INTO @TempTrainingFeedback
	 SELECT FM.I_Feedback_Group_ID,
			CASE FOM.S_Feedback_Option_Name
				WHEN 'Excellent' then 4.0
				WHEN 'Good' then 3.0
				WHEN 'Average' then 2.0
				ELSE 1.0
			END AS Feedback
	   FROM ACADEMICS.T_Training_Feedback_Details TFD
			INNER JOIN ACADEMICS.T_Feedback_Option_Master FOM
				ON TFD.I_Feedback_Option_Master_ID=FOM.I_Feedback_Option_Master_ID
			INNER JOIN ACADEMICS.T_Feedback_Master FM
				ON FOM.I_Feedback_Master_ID=FM.I_Feedback_Master_ID
	  WHERE I_Training_Feedback_ID=@TrainingFeedbackID
		AND I_Feedback_Group_ID=@iFeedbackGroupID


	 SELECT @AvgFeedbackTrainer=AVG(Feedback)
	   FROM @TempTrainingFeedback

	RETURN @AvgFeedbackTrainer;

END
GO
PRINT N'Creating Function [REPORT].[fnGetCycleTimeForCustomerCare]...';


GO
/*******************************************************************************************************
* Author		:	SHANKHA ROY
* Create date	:	24/01/2008
* Description	:	This Function checks calculate the Cycle time for Customer Care report
* Return		:	Integer
*******************************************************************************************************/
CREATE FUNCTION [REPORT].[fnGetCycleTimeForCustomerCare]
(
 @iUserAssignStatus INT,
 @CloseStatus INT,
 @ComplaintID INT
)
RETURNS INT

AS
BEGIN

DECLARE @dtFromDATE DATETIME
DECLARE @dtTODATE DATETIME
DECLARE @iCycleTime INT

SET @iCycleTime = 0

IF(@CloseStatus >= @iUserAssignStatus)
BEGIN	

	IF EXISTS(SELECT Dt_Upd_On FROM CUSTOMERCARE.T_Complaint_Request_Detail
	WHERE I_Status_ID = @CloseStatus
	AND I_Complaint_Req_ID = @ComplaintID
	AND I_Status_ID != 6
	AND I_Status_ID != 7)
	BEGIN
--		SET @dtTODATE = (SELECT MAX(Dt_Upd_On) FROM CUSTOMERCARE.T_Complaint_Request_Detail
--		WHERE I_Status_ID = @CloseStatus
--		AND I_Complaint_Req_ID = @ComplaintID)
	SET @dtTODATE =GETDATE()
	END
	ELSE
		BEGIN
			IF(@CloseStatus != 6 AND @CloseStatus != 7)
				BEGIN

					SET @dtTODATE = (SELECT MIN(Dt_Upd_On) FROM CUSTOMERCARE.T_Complaint_Audit_Trail
					WHERE I_Status_ID !=1 AND I_Complaint_Audit_ID = (SELECT TOP 1 B.I_Complaint_Audit_ID FROM CUSTOMERCARE.T_Complaint_Audit_Trail B
					WHERE  B.I_Complaint_Req_ID = @ComplaintID  AND B.I_Complaint_Audit_ID > (SELECT MIN(I_Complaint_Audit_ID) FROM CUSTOMERCARE.T_Complaint_Audit_Trail 
					WHERE  I_Complaint_Req_ID = @ComplaintID AND I_Status_ID = @CloseStatus) ORDER BY B.I_Complaint_Audit_ID ASC
					))
				END
			ELSE
				BEGIN
					SET @dtTODATE = (SELECT MAX(Dt_Upd_On) FROM CUSTOMERCARE.T_Complaint_Request_Detail
						WHERE I_Status_ID = 6 -- Closed by Customercare @CloseStatus
						AND I_Complaint_Req_ID = @ComplaintID)
				END	
		END

	-- This for get the date for Cycle Time Start
    SET @dtFromDATE =[REPORT].fnGetComplaintLoggedDate(@ComplaintID)

--Logic : Cycle Time = (Current Date - Assigne Date ) IF Complaint is not Close
-- If Close  Cycle Time =(Close Date - Assign Date)
  

	SET @iCycleTime =(SELECT CONVERT(INT,(DATEDIFF(DD,@dtFromDATE,@dtTODATE))))


END
ELSE
BEGIN
	SET @iCycleTime = 0
END


RETURN @iCycleTime;
END
GO
