PRINT N'Creating Function [dbo].[fnCalculateConvenienceCharge]...';


GO
CREATE FUNCTION [dbo].[fnCalculateConvenienceCharge]
    (
      @ReceiptAmount DECIMAL(18, 4),
      @BrandID INT,
      @ReceiptDate DATETIME,
      @PaymentMode INT
    )
RETURNS DECIMAL(18, 4)
AS 
    BEGIN
        DECLARE @ConvenienceCharge DECIMAL(18, 4)
        DECLARE @ConvienceChargePercentage DECIMAL(18,4)
        DECLARE @AdditionalAmount DECIMAL(18,4)
	
        SELECT  @ConvienceChargePercentage=ISNULL(N_Percentage,0.0) ,
                @AdditionalAmount=ISNULL(N_Addl_Amount,0.0)
        FROM    dbo.T_ConvenienceCharge_Matrix TCCM
        WHERE   I_PaymentMode_ID = @PaymentMode
                AND CONVERT(DATE, @ReceiptDate) BETWEEN CONVERT (DATE, Dt_valid_from)
                                             AND     CONVERT (DATE, Dt_valid_to)
                AND I_Status = 1
                AND @ReceiptAmount BETWEEN N_From_Amount AND N_To_Amount
                AND I_Brand_ID = @BrandID
                
                SET @ConvenienceCharge=(@ReceiptAmount*(@ConvienceChargePercentage/100))+@AdditionalAmount;
                
                RETURN @ConvenienceCharge
    END
GO
PRINT N'Creating Function [dbo].[fnCalculateConvenienceChargeTax]...';


GO
CREATE FUNCTION [dbo].[fnCalculateConvenienceChargeTax]
    (
      @ConvenienceChargeAmount DECIMAL(18, 4),
      @BrandID INT,
      @ReceiptDate DATETIME,
      --@PaymentMode INT,
      @TaxID INT=NULL
    )
RETURNS DECIMAL(18, 4)
AS 
    BEGIN
        DECLARE @Tax DECIMAL(18, 4)
        DECLARE @TaxAmount DECIMAL(18,4)
        --DECLARE @AdditionalAmount DECIMAL(18,2)
		
		IF(@TaxID IS NULL)
		BEGIN
			SELECT @Tax=SUM(ISNULL(N_Value,0.0)) FROM ERP.T_ConvenienceCharge_Tax_Master TCCTM
			WHERE
			I_Brand_ID=@BrandID AND I_Status=1
			AND CONVERT(DATE, @ReceiptDate) BETWEEN CONVERT (DATE, Dt_From_Date)
                                             AND     CONVERT (DATE, Dt_To_Date)
			
			SET @TaxAmount=@ConvenienceChargeAmount*(@Tax/100)
		END
		ELSE
		BEGIN
			SELECT @Tax=ISNULL(N_Value,0) FROM ERP.T_ConvenienceCharge_Tax_Master TCCTM
			WHERE
			I_Brand_ID=@BrandID AND I_Status=1 AND I_Tax_ID=@TaxID
			AND CONVERT(DATE, @ReceiptDate) BETWEEN CONVERT (DATE, Dt_From_Date)
                                             AND     CONVERT (DATE, Dt_To_Date)
			
			
			SET @TaxAmount=@ConvenienceChargeAmount*(@Tax/100)
		END
		
		RETURN @TaxAmount

    END
GO
PRINT N'Creating Function [dbo].[fnCalculateExamTypeMarks]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '08/17/2007'
-- Description:	This Function calculate the exam type marks
-- Return: INT
-- =============================================
CREATE FUNCTION [dbo].[fnCalculateExamTypeMarks]
(
	@iMarks NUMERIC(18,2),
	@iTotMarks NUMERIC(18,2),
	@iWTGMark NUMERIC(18,2)	
)
RETURNS NUMERIC(18,2)

AS
BEGIN

DECLARE @rtnMark NUMERIC(18,2)

IF((@iMarks IS NOT NULL ) AND (@iTotMarks IS NOT NULL) AND (@iWTGMark IS NOT NULL)
	AND (@iMarks <> 0 ) AND (@iTotMarks <> 0) AND (@iWTGMark <> 0) ) 
BEGIN
--marks = (marks*100/totalmarks)* (weightage(%))
-- that means marks = (marks*100/totalmarks)* (weightage/100)
  SET @rtnMark = CAST(((@iMarks*@iWTGMark)/(@iTotMarks)) AS NUMERIC(18,2))
END
ELSE
  BEGIN
  	SET @rtnMark = 0
  END

RETURN @rtnMark;
END
GO
PRINT N'Creating Function [dbo].[fnCalculateObtainMarks]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '08/17/2007'
-- Description:	This Function calculate the obtain marks
-- Return: INT
-- =============================================
CREATE FUNCTION [dbo].[fnCalculateObtainMarks]
(
	@iMarks NUMERIC(18,2),
	@iTotMarks NUMERIC(18,2)	
)
RETURNS NUMERIC(18,2)

AS
BEGIN

DECLARE @rtnObtainMark NUMERIC(18,2)

IF((@iMarks IS NOT NULL ) AND (@iTotMarks IS NOT NULL)
	AND (@iMarks <> 0 ) AND (@iTotMarks <> 0)) 
BEGIN
--percentage = Total marks obtained / Total marks *100
  SET @rtnObtainMark = CAST((@iMarks * 100 / @iTotMarks)AS NUMERIC(18,2)) 
END
ELSE
  BEGIN
  	SET @rtnObtainMark = 0
  END

RETURN @rtnObtainMark;
END
GO
