CREATE FUNCTION [dbo].[fnCenterList]
( @iSelectedHierarchyId INT,
  @iSelectedBrandId INT = NULL
 )
  RETURNS VARCHAR(MAX)

AS
BEGIN
	DECLARE @sSearchCenterList VARCHAR(MAX)
	DECLARE @sSearchCriteria varchar(MAX) 
	
	SET @sSearchCenterList = ''
	
	
	IF @iSelectedBrandId IS NULL    
     BEGIN    
       SET @iSelectedBrandId = 0    
     END    
     
 SELECT @sSearchCriteria = S_Hierarchy_Chain from T_Hierarchy_Mapping_Details where I_Hierarchy_detail_id = @iSelectedHierarchyId      
     
 IF @iSelectedBrandId = 0     
  BEGIN    
   SELECT  @sSearchCenterList=@sSearchCenterList + ',' + CONVERT(VARCHAR,TCHD.I_Center_Id)
   FROM T_CENTER_HIERARCHY_DETAILS TCHD,T_Centre_Master CM WHERE     
   TCHD.I_Hierarchy_Detail_ID IN     
   (SELECT I_HIERARCHY_DETAIL_ID FROM T_Hierarchy_Mapping_Details WHERE    
   S_Hierarchy_Chain LIKE @sSearchCriteria + '%' AND I_Status=1)     
   AND TCHD.I_Center_Id = CM.I_Centre_Id    
  END    
 ELSE    
  BEGIN    
   SELECT @sSearchCenterList=@sSearchCenterList + ',' + CONVERT(VARCHAR,TCHD.I_Center_Id) 
   FROM T_CENTER_HIERARCHY_DETAILS TCHD,T_BRAND_CENTER_DETAILS TBCD,T_Centre_Master CM WHERE    
   TCHD.I_Hierarchy_Detail_ID IN     
     (SELECT I_HIERARCHY_DETAIL_ID FROM T_Hierarchy_Mapping_Details WHERE S_Hierarchy_Chain LIKE @sSearchCriteria + '%' AND I_Status=1) AND    
   TBCD.I_Brand_ID=@iSelectedBrandId AND    
   TBCD.I_Centre_Id = TCHD.I_Center_Id    
   AND TCHD.I_Center_Id = CM.I_Centre_Id  
   AND TCHD.I_Status = 1    
   AND TBCD.I_Status = 1  
   AND CM.I_Status = 1  
        
  END    
  
	RETURN @sSearchCenterList
	
END
GO
PRINT N'Creating Function [dbo].[fnCheckReceiptValidity]...';


GO
CREATE FUNCTION [dbo].[fnCheckReceiptValidity]
(
@iStudentDetailID INT = NULL,
@iCentreID INT = NULL,
@iEnqRegnDtlID INT = NULL,
@iAmount Numeric(15,2)
)
RETURNS BIT

AS
BEGIN

DECLARE @bResult BIT
DECLARE @iDiffInMinute INT
DECLARE @DtLastCreationTime DATETIME

IF @iStudentDetailID IS NOT NULL
BEGIN
SELECT @DtLastCreationTime=ISNULL(max(Dt_Receipt_Date),'1/1/2002') FROM T_Receipt_Header WITH (NOLOCK)
WHERE I_Student_Detail_ID=@iStudentDetailID and CAST(N_Receipt_Amount AS Numeric(18,0)) = CAST(@iAmount AS Numeric(18,0))

SELECT @iDiffInMinute=DATEDIFF(n,@DtLastCreationTime,GETDATE())
IF @iDiffInMinute > 5
BEGIN
SET @bResult=1
END
ELSE
BEGIN
SET @bResult=0
END

END
ELSE
BEGIN
SELECT @DtLastCreationTime=ISNULL(max(Dt_Receipt_Date),'1/1/2002') FROM T_Receipt_Header WITH (NOLOCK)
WHERE I_Enquiry_Regn_ID=@iEnqRegnDtlID and I_Centre_Id=@iCentreID  and CAST(N_Receipt_Amount AS NUMERIC(18,0)) = CAST(@iAmount AS Numeric(18,0))

SELECT @iDiffInMinute=DATEDIFF(n,@DtLastCreationTime,GETDATE())
IF @iDiffInMinute > 5
BEGIN
SET @bResult=1
END
ELSE
BEGIN
SET @bResult=0
END

END

--RETURN @bResult
--this function is commented as in case user is creating two seperate registrations in different courses which has same
--registration fees it stops the user from doing so.
RETURN 1

END
GO
