					WHERE I_Fee_Component_ID IS NULL
					AND I_Course_ID IS NULL
					AND I_Center_ID IS NULL
					AND I_Country_ID = @iCountryID
					AND I_Brand_ID = @iBrandID
					AND Dt_Period_Start <= @dtReceiptDate
