GO
CREATE FUNCTION [dbo].[fnGetReceiptAmtfromXML] ( @XML XML )
RETURNS DECIMAL(14, 2)
AS
    BEGIN

        DECLARE @ReceiptAmount DECIMAL(14, 2)= 0.00
        DECLARE @count INT= 0
        DECLARE @startpos INT= 1
        
        --PRINT @ReceiptAmount

        SET @count = @XML.value('count((TblRctCompDtl/RowRctCompDtl))', 'int')

        WHILE ( @startpos <= @count )
            BEGIN

                DECLARE @ReceiptDetailXML XML

                SET @ReceiptDetailXML = @XML.query('/TblRctCompDtl/RowRctCompDtl[position()=sql:variable("@startpos")]')

                SET @ReceiptAmount = @ReceiptAmount
                    + ( SELECT  T.a.value('@N_Amount_Paid', 'decimal(14,2)')
                        FROM    @ReceiptDetailXML.nodes('/RowRctCompDtl') T ( a )
                      )
                      
                --PRINT @ReceiptAmount       
                                                       
                SET @startpos = @startpos + 1                                                       


            END



        RETURN @ReceiptAmount

    END
GO
PRINT N'Creating Function [dbo].[fnGetReceiptTaxAmtfromXML]...';


GO
CREATE FUNCTION [dbo].[fnGetReceiptTaxAmtfromXML] ( @XML XML )
RETURNS DECIMAL(14, 2)
AS
    BEGIN

        DECLARE @ReceiptTaxAmount DECIMAL(14, 2)= 0.00
        DECLARE @count INT= 0
        DECLARE @startpos INT= 1
        
        --PRINT @ReceiptTaxAmount

        SET @count = @XML.value('count((TblRctCompDtl/RowRctCompDtl))', 'int')

        WHILE ( @startpos <= @count )
            BEGIN

                DECLARE @ReceiptDetailXML XML
                DECLARE @InnerCount INT= 0
                DECLARE @innerstartpos INT= 1

                SET @ReceiptDetailXML = @XML.query('/TblRctCompDtl/RowRctCompDtl[position()=sql:variable("@startpos")]')
                
                SET @InnerCount  = @ReceiptDetailXML.value('count((RowRctCompDtl/TblRctTaxDtl/RowRctTaxDtl))',
                                                     'int')
                
                WHILE ( @innerstartpos <= @InnerCount )
                    BEGIN
                
                        DECLARE @TaxXML XML
                
                        SET @TaxXML = @ReceiptDetailXML.query('RowRctCompDtl/TblRctTaxDtl/RowRctTaxDtl[position()=sql:variable("@innerstartpos")]')
                
                        SET @ReceiptTaxAmount = @ReceiptTaxAmount
                            + ( SELECT  T.b.value('@N_Tax_Paid',
                                                  'decimal(14,2)')
                                FROM    @TaxXML.nodes('/RowRctTaxDtl') T ( b )
                              )
                        
                        
                        SET @innerstartpos = @innerstartpos + 1        
                
                    END
                
                
                

                      
                --PRINT @ReceiptAmount       
                                                       
                SET @startpos = @startpos + 1                                                       


            END



        RETURN @ReceiptTaxAmount

    END
GO
PRINT N'Creating Function [dbo].[fnGetSessionDayGap]...';


GO
-- =============================================
-- Author:		Swagata De
-- Create date: '23/04/2007'
-- Description:	This Function returns the session day gap for a particular student in a particular 
--				center AND FOR a particular course
-- Return: sessionday gap (int)
-- =============================================

CREATE FUNCTION [dbo].[fnGetSessionDayGap]
(
	@iStudentDetailId INT,
	@iCenterId INT,
	@iCourseId INT
)  
RETURNS  INT

AS
BEGIN 
DECLARE @iSessionDayGap INT
DECLARE @tblTemp TABLE
	(
		[ID] int identity(1,1),
		CourseID int,		
		DeliveryPatternId int,		
		SessionDayGapDP int		
	)

--Get all courses that a student has taken
	
	INSERT INTO @tblTemp(CourseID)
	SELECT I_Course_ID FROM dbo.T_Student_Course_Detail
	WHERE I_Student_Detail_ID=@iStudentDetailId

	UPDATE TT
	SET TT.DeliveryPatternId=TTEMP.I_Delivery_Pattern_ID
	FROM @tblTemp TT,
	(SELECT CDM.I_Delivery_Pattern_ID,CDM.I_Course_ID,CDM.N_Course_Duration 
	FROM dbo.T_Course_Delivery_Map CDM,(SELECT CCDF.I_Course_Delivery_ID FROM dbo.T_Course_Center_Delivery_FeePlan CCDF,
	(SELECT I_Course_Center_ID FROM dbo.T_Course_Center_Detail WHERE I_Centre_Id=@iCenterId
	AND I_Course_ID IN (SELECT CourseID FROM @tblTemp)) CCD WHERE CCDF.I_Course_Center_ID=CCD.I_Course_Center_ID)TCCD
	WHERE CDM.I_Course_Delivery_ID = TCCD.I_Course_Delivery_ID) TTEMP	
	WHERE TT.CourseID=TTEMP.I_Course_ID
--Get all delivery pattern Ids
	UPDATE TT
	SET TT.SessionDayGapDP=DPM.N_Session_Day_Gap
	FROM @tblTemp TT,dbo.T_Delivery_Pattern_Master DPM
	WHERE TT.DeliveryPatternId=DPM.I_Delivery_Pattern_ID AND DPM.I_Status<>0

	SET @iSessionDayGap=( SELECT SessionDayGapDP FROM @tblTemp WHERE CourseID=@iCourseId)
	RETURN @iSessionDayGap
END
GO
PRINT N'Creating Function [dbo].[fnGetStudentNo]...';


GO
-- =============================================
-- Author: Sandeep Acharyya
-- Create date: 03/02/2011
-- Description: This function returns the next student no for that particular brand
-- Return: student no (varchar)
-- =============================================
CREATE FUNCTION [dbo].[fnGetStudentNo]
(
@iCenterID INT
)
RETURNS VARCHAR(20)
AS

BEGIN

DECLARE @iBrandID INT, @BrandCode VARCHAR(20), @iMaxStudentID INT, @iMaxStudentNo INT, @sStudentNo VARCHAR(20)

SELECT TOP 1 @iBrandID = [TBCD].[I_Brand_ID] FROM [dbo].[T_Brand_Center_Details] AS TBCD
WHERE [TBCD].[I_Centre_Id] = @iCenterID

SELECT @BrandCode = [TBM].[S_Brand_Code]
FROM [dbo].[T_Brand_Master] AS TBM
WHERE [TBM].[I_Brand_ID] = @iBrandID

-- To be Removed
-- SET @BrandCode = 'Student'

--SELECT @iMaxStudentID = MAX([tsd].[I_Student_Detail_ID])
--FROM [dbo].[T_Student_Detail] AS TSD
--WHERE [TSD].[S_Student_ID] LIKE '' + @BrandCode + '%'

SELECT @iMaxStudentID = MAX([tscd].[I_Student_Detail_ID]) FROM [dbo].[T_Student_Center_Detail] AS TSCD
INNER JOIN [dbo].[T_Brand_Center_Details] AS TBCD
ON [TSCD].[I_Centre_Id] = [TBCD].[I_Centre_Id]
WHERE [TBCD].[I_Brand_ID] = @iBrandID

IF (@iMaxStudentID IS NOT NULL)
BEGIN
SELECT @iMaxStudentNo = CAST(REPLACE([TSD].[S_Student_ID],@BrandCode,'') AS INT)
FROM [dbo].[T_Student_Detail] AS TSD
WHERE [TSD].[I_Student_Detail_ID] = @iMaxStudentID

SET @iMaxStudentNo = @iMaxStudentNo + 1
END
ELSE
BEGIN
SET @iMaxStudentNo = 1
END

SET @sStudentNo = @BrandCode + CAST(@iMaxStudentNo AS VARCHAR(20))

IF (@sStudentNo IS NULL)
SET @sStudentNo = ''

RETURN @sStudentNo

END
GO
