 AND ((DATEDIFF(DD,ISNULL(@StartDate,HM.Dt_Submission_Date),HM.Dt_Submission_Date) >= 0   
 AND DATEDIFF(DD,ISNULL(@EndDate,HM.Dt_Submission_Date),HM.Dt_Submission_Date)<= 0))  
 AND ESM.I_Skill_ID=@iSkillID
 RETURN @iCount  
END
