PRINT N'Creating Function [ACADEMICS].[ufnGetStudentAcademicDropoutStatusBatch]...';


GO
CREATE FUNCTION [ACADEMICS].[ufnGetStudentAcademicDropoutStatusBatch]  
    (  
      @iStudentID int,  
      @iBatchID INT,
      @iCenterID int,  
      @iAllowedNumberOfNonAttendedDays int,  
      @dCurrenDate datetime  
    )  
RETURNS CHAR(1)  
AS   
   BEGIN  
  
    DECLARE @cDropoutStatus CHAR(1)  
    DECLARE @dDateCompare DATETIME  
  
    SELECT @dCurrenDate =dbo.fnGetDatePart(@dCurrenDate)  
  
    SET @cDropoutStatus = 'N'  
  
 --Check for a single Attendance has been given by the student  
 IF (ISNULL(( SELECT COUNT(*) FROM   
    DBO.T_STUDENT_ATTENDANCE_DETAILS WITH(NOLOCK)   
    WHERE I_STUDENT_DETAIL_ID =@iStudentID AND I_Centre_Id = @iCenterID AND I_Batch_ID = @iBatchID
   ),0)=0)  
 BEGIN  
   SET @cDropoutStatus = 'Y'  
   RETURN @cDropoutStatus   
 END  
   
 --Check All the Attendance for all session have been given by the student  
 DECLARE @iSessionCount INT  
 DECLARE @iTotalAttendanceCount INT  
  
 SELECT @iSessionCount=[dbo].[fnGetTotalSessionCount](@iBatchID,@iCenterID,NULL,NULL)
  
 SELECT @iTotalAttendanceCount = COUNT(*) FROM   
    DBO.T_STUDENT_ATTENDANCE_DETAILS WITH(NOLOCK)   
    WHERE I_STUDENT_DETAIL_ID =@iStudentID AND I_Centre_Id = @iCenterID AND I_Batch_ID = @iBatchID
  
 IF (@iSessionCount<=@iTotalAttendanceCount)  
 BEGIN  
   SET @cDropoutStatus = 'N'  
   RETURN @cDropoutStatus  
 END  
  
 -- Check if Student has given attendance within the configured number of days  
    IF ( ( SELECT   DATEDIFF(day,  
                                     ( SELECT   
                                                MAX(Dt_Attendance_Date)  
                                       FROM     dbo.T_Student_Attendance_Details WITH(NOLOCK)  
                                       WHERE    I_Student_Detail_ID = @iStudentID  
                                                AND I_Centre_Id = @iCenterID
                                                AND I_Batch_ID = @iBatchID  
                                     ), @dCurrenDate)  
                 ) >= @iAllowedNumberOfNonAttendedDays )   
    BEGIN  
        SET @cDropoutStatus = 'Y'  
  RETURN @cDropoutStatus  
    END  
  -- Return the information to the caller  
    RETURN @cDropoutStatus  
END
GO
PRINT N'Creating Function [dbo].[GetInstallmentDatesInFinancialYear]...';


GO
CREATE FUNCTION [dbo].[GetInstallmentDatesInFinancialYear]
(
    @FinancialYearStart DATE,
    @FinancialYearEnd DATE,
    @InstallmentStartDate DATE,
    @InstallmentFrequencyMonths INT
	--@AcademicSessionID Int
)

RETURNS TABLE
AS

RETURN
(

    WITH DateCTE AS
    (

        SELECT 
            @InstallmentStartDate AS InstallmentDate
        UNION ALL
        SELECT 
            DATEADD(MONTH, @InstallmentFrequencyMonths, InstallmentDate)
        FROM 
            DateCTE
        WHERE 
            DATEADD(MONTH, @InstallmentFrequencyMonths, InstallmentDate) <= @FinancialYearEnd
    )
    SELECT
	 InstallmentDate
        
    FROM 
        DateCTE
    WHERE 
        InstallmentDate >= @FinancialYearStart
)
;
GO
PRINT N'Creating Function [ACADEMICS].[ufnGetStudentFinancialDropoutStatusBatch]...';


GO
--THE FUNCTION HAS BEEN ALTERED FOR THE ABOVE STORED PROCEDURE   
CREATE FUNCTION [ACADEMICS].[ufnGetStudentFinancialDropoutStatusBatch]  
    (  
      @iStudentID INT,  
      @iCenterID INT,  
      @iAllowedNumberOfNonPaymentDays INT,  
      @dCurrenDate DATETIME,  
      @iNoOfRelaxedInstallment INT              
    )  
RETURNS @InvoiceWiseDropoutTable TABLE  
    (  
      I_Student_Detail_ID INT,  
      I_Center_Id INT,  
      I_Invoice_Header_Id INT,  
      S_Is_Dropout_Invoice CHAR(1),  
      S_Is_Reactivation_Fees_Paid VARCHAR(10)  
    )  
AS -- Returns the Student Financial Status Invoicewise.              
   BEGIN  
              
    SET @dCurrenDate = CAST(SUBSTRING(CAST(@dCurrenDate AS VARCHAR), 1, 11) AS DATETIME)               
              
    DECLARE @cDropoutStatus CHAR(1)              
    DECLARE @iInvoiceHeaderID INT              
    DECLARE @nInstallmentTotal NUMERIC(18, 2)              
    DECLARE @nTotalAmountPaid NUMERIC(18, 2)              
    DECLARE @dCutoffinstallmentDate DATETIME      
    DECLARE @iLeaveStatus INT      
    DECLARE @AllowedNumberOfDays INT  
    DECLARE @iBatchGracePeriod INT  
      
    SELECT @iBatchGracePeriod = MAX(I_Latefee_Grace_Day) FROM dbo.T_Student_Batch_Master AS tsbm  
    INNER JOIN dbo.T_Student_Batch_Details AS tsbd  
    ON tsbm.I_Batch_ID = tsbd.I_Batch_ID  
    WHERE I_Student_ID = @iStudentID  
      
    IF (@iBatchGracePeriod IS NULL)  
  SET @iBatchGracePeriod = 0  
      
    SET @AllowedNumberOfDays = @iAllowedNumberOfNonPaymentDays + @iBatchGracePeriod  
      
-- Create Cursor              
    DECLARE FINANCIAL_DROPOUT_CURSOR CURSOR  
        FOR SELECT  I_Invoice_Header_ID  
            FROM    dbo.T_Invoice_Parent WITH ( NOLOCK )  
            WHERE   I_Student_Detail_ID = @iStudentID  
                    AND I_Centre_Id = @iCenterID              
              
    SET @cDropoutStatus = 'N'              
              
    SET @dCutoffinstallmentDate = ( SELECT  DATEADD(DAY,  
                                                    - @AllowedNumberOfDays,  
                                                    GETDATE())  
                                  )              
    SET @dCutoffinstallmentDate = CAST(SUBSTRING(CAST(@dCutoffinstallmentDate AS VARCHAR),  
                                                 1, 11) AS DATETIME)              
                   
    OPEN FINANCIAL_DROPOUT_CURSOR              
    FETCH NEXT FROM FINANCIAL_DROPOUT_CURSOR INTO @iInvoiceHeaderID              
              
    WHILE @@FETCH_STATUS = 0              
        BEGIN         
            IF EXISTS ( SELECT  1  
                        FROM    dbo.T_Student_Batch_Details AS tsbd WITH ( NOLOCK )  
                        INNER JOIN dbo.T_Student_Center_Detail AS tscd  
                        ON tscd.I_Student_Detail_ID = tsbd.I_Student_ID  
                        INNER JOIN dbo.T_Center_Batch_Details AS tcbd  
                        ON tsbd.I_Batch_ID = tcbd.I_Batch_ID  
                        AND tcbd.I_Centre_Id = tscd.I_Centre_Id  
                        WHERE   tsbd.I_Student_ID = @iStudentID  
                                AND tsbd.I_Status = 1  
                                AND tcbd.I_Status <> 5  
                                AND C_Is_LumpSum = 'N' )   
                BEGIN          
             
                    INSERT  INTO @InvoiceWiseDropoutTable  
                            (  
                              I_Student_Detail_ID,  
                              I_Center_Id,  
                              I_Invoice_Header_Id,  
                              S_Is_Dropout_Invoice,  
                              S_Is_Reactivation_Fees_Paid  
                            )  
                    VALUES  (  
                              @iStudentID,  
                              @iCenterID,  
                              @iInvoiceHeaderID,  
                              'N',  
                              'NA'  
                            )             
             
                    DECLARE @iCurrentInstallmentNo INT          
                    DECLARE @nAmountPaidSoFar NUMERIC(18, 2)          
                    DECLARE @nSumofLastNAmount NUMERIC(18, 2)          
                    DECLARE @nCumAmountRecivable NUMERIC(18, 2)          
                    DECLARE @nOutstandingAmount NUMERIC(18, 2)          
             
             
                    SELECT  @nAmountPaidSoFar = ISNULL(SUM(N_Receipt_Amount),  
                                                       0)  
                    FROM    dbo.T_Receipt_Header  
                    WHERE   I_Invoice_Header_ID = @iInvoiceHeaderID  
                            AND CAST(SUBSTRING(CAST(Dt_Receipt_Date AS VARCHAR),  
                                               1, 11) AS DATETIME) <= @dCurrenDate  
                            AND I_Status <> 0          
             
     --------------------------------------------------          
                    SELECT  @iCurrentInstallmentNo = MAX(DISTINCT TICD.I_Installment_No)  
                    FROM    dbo.T_Invoice_Child_Detail TICD  
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID  
                            INNER JOIN dbo.T_Invoice_Parent TIP ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID          
     --WHERE  TIP.I_Status IN ( 1 , 3) -- 1 IS FOR ACTIVE INVOICE AND 3 IS FOR TRANSFER OUT INVOICES WHICH ARE ACTIVE AS WELL          
                                                                   AND TIP.I_Student_Detail_ID = @iStudentID  
                                                                   AND TIP.I_Invoice_Header_ID = @iInvoiceHeaderID  
                                                                   AND CAST(SUBSTRING(CAST(TICD.Dt_Installment_Date AS VARCHAR), 1, 11) AS DATETIME) <= @dCurrenDate          
               
     --PRINT @iCurrentInstallmentNo          
             
             
                    SELECT  @nSumofLastNAmount = SUM(TICD.N_Amount_Due)  
                    FROM    dbo.T_Invoice_Child_Detail TICD  
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID  
                            INNER JOIN dbo.T_Invoice_Parent TIP ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID          
     --WHERE  TIP.I_Status IN ( 1 , 3)          
                                                                   AND TIP.I_Student_Detail_ID = @iStudentID  
                                                                   AND TIP.I_Invoice_Header_ID = @iInvoiceHeaderID  
                                                                   AND CAST(SUBSTRING(CAST(TICD.Dt_Installment_Date AS VARCHAR), 1, 11) AS DATETIME) <= @dCurrenDate  
                                                                   AND TICD.I_Installment_No > = ( @iCurrentInstallmentNo - @iNoOfRelaxedInstallment)  
                                                                   AND TICD.I_Installment_No <= @iCurrentInstallmentNo          
               
                    SELECT  @nCumAmountRecivable = SUM(TICD.N_Amount_Due)  
                    FROM    dbo.T_Invoice_Child_Detail TICD  
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID  
                            INNER JOIN dbo.T_Invoice_Parent TIP ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID          
     --WHERE  TIP.I_Status IN ( 1 , 3)          
                                                                   AND TIP.I_Student_Detail_ID = @iStudentID  
                                                                   AND TIP.I_Invoice_Header_ID = @iInvoiceHeaderID  
                                                                   AND CAST(SUBSTRING(CAST(TICD.Dt_Installment_Date AS VARCHAR), 1, 11) AS DATETIME) <= @dCurrenDate  
                                                                   AND TICD.I_Installment_No <= @iCurrentInstallmentNo          
               
                    SET @nOutstandingAmount = @nCumAmountRecivable  
                        - @nAmountPaidSoFar          
             
     --***********************************************************          
                  
     -- Check if Student is Financial Dropout              
                    IF @nOutstandingAmount > @nSumofLastNAmount   
                        BEGIN              
           -- Check if Student is on leave               
                      
                            IF NOT EXISTS ( SELECT  A.I_Student_Leave_ID  
                                            FROM    dbo.T_Student_Leave_Request A  
                                                    WITH ( NOLOCK )  
                                                    INNER JOIN dbo.T_Student_Center_Detail B  
                                                    WITH ( NOLOCK ) ON A.I_Student_Detail_ID = B.I_Student_Detail_ID  
                                            WHERE   A.I_Student_Detail_ID = @iStudentID  
                                                    AND DATEDIFF(DAY, A.Dt_From_Date, @dCurrenDate) >= 0  
                                                    AND DATEDIFF(DAY, @dCurrenDate, A.Dt_To_Date) >= 0  
                                                    AND A.I_Status = 1  
                                                    AND B.I_Status = 1  
                                                    AND B.I_Centre_ID = @iCenterID )   
                                BEGIN                 
                                    UPDATE  @InvoiceWiseDropoutTable  
                                    SET     S_Is_Dropout_Invoice = 'Y',  
                                            S_Is_Reactivation_Fees_Paid = 'NA'  
                                    WHERE   I_Student_Detail_ID = @iStudentID  
                                            AND I_Center_Id = @iCenterID  
                                            AND I_Invoice_Header_Id = @iInvoiceHeaderID              
                                END       
                        END      
                    ELSE   
                        BEGIN      
          -- Check if Student Has Paid The Reactivation Fees        
                            IF EXISTS ( SELECT  'TRUE'  
                                        FROM    ACADEMICS.T_Dropout_Details TDD  
                                                WITH ( NOLOCK )  
                                                INNER JOIN dbo.T_Invoice_Parent TIP  
                                                WITH ( NOLOCK ) ON TIP.I_Invoice_Header_ID = TDD.I_Invoice_Header_ID  
                                        WHERE   TIP.I_Invoice_Header_Id = @iInvoiceHeaderID  
                                                AND TDD.I_Dropout_Status = 1 )   
                                BEGIN      
                                    IF NOT EXISTS ( SELECT  'TRUE'  
                                                    FROM    dbo.T_Receipt_Header RH  
                                                            WITH ( NOLOCK )  
                                                            INNER JOIN ACADEMICS.T_Dropout_Details TDD  
                                                            WITH ( NOLOCK ) ON TDD.I_Student_Detail_ID = RH.I_Student_Detail_ID  
                                                    WHERE   RH.I_Invoice_Header_ID IS NULL  
                                                            AND RH.I_Receipt_Type = 12  
                                                            AND RH.I_Student_Detail_ID = @iStudentID  
                                                            AND RH.Dt_Crtd_On > ISNULL(TDD.Dt_Upd_On, TDD.Dt_Crtd_On) )   
                                        BEGIN                 
                                            UPDATE  @InvoiceWiseDropoutTable  
                                            SET     S_Is_Dropout_Invoice = 'Y',  
                                                    S_Is_Reactivation_Fees_Paid = 'No'  
                                            WHERE   I_Student_Detail_ID = @iStudentID  
                                                    AND I_Center_Id = @iCenterID  
                                                    AND I_Invoice_Header_Id = @iInvoiceHeaderID              
                                        END      
                                    ELSE   
                                        BEGIN                 
                                            UPDATE  @InvoiceWiseDropoutTable  
                                            SET     S_Is_Dropout_Invoice = 'N',  
                                                    S_Is_Reactivation_Fees_Paid = 'Yes'  
                                            WHERE   I_Student_Detail_ID = @iStudentID  
                                                    AND I_Center_Id = @iCenterID  
                                                    AND I_Invoice_Header_Id = @iInvoiceHeaderID              
                                        END       
               
                                END      
                   
                    
                        END                    
                END        
            ELSE   
                BEGIN        
                    INSERT  INTO @InvoiceWiseDropoutTable  
                            (  
                              I_Student_Detail_ID,  
                              I_Center_Id,  
                              I_Invoice_Header_Id,  
                              S_Is_Dropout_Invoice,  
                              S_Is_Reactivation_Fees_Paid  
                            )  
                    VALUES  (  
                              @iStudentID,  
                              @iCenterID,  
                              @iInvoiceHeaderID,  
                              'N',  
                              'NA'  
                            )         
                END        
            FETCH NEXT FROM FINANCIAL_DROPOUT_CURSOR INTO @iInvoiceHeaderID              
        END              
               
    CLOSE FINANCIAL_DROPOUT_CURSOR              
    DEALLOCATE FINANCIAL_DROPOUT_CURSOR                   
              
-- Return the information to the caller              
    RETURN ;            
   END
GO
PRINT N'Creating Function [ECOMMERCE].[fnGetFeePlanDiscountDetails]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '08/17/2007'
-- Description:	This Function return a table 
-- constains Exam Module name List
-- Return: Table
-- =============================================
CREATE FUNCTION [ECOMMERCE].[fnGetFeePlanDiscountDetails]
(
	@feeplanid int,
	@paymentmode int,
	@discountschemeid int
)
RETURNS  @TblFeePlan TABLE
(
	ID INT IDENTITY(1,1),
	I_Course_Fee_Plan_Detail_ID INT ,
	I_Fee_Component_ID INT,
	I_Course_Fee_Plan_ID INT,
	I_Item_Value Decimal(14,2),
	N_Discount decimal(14,2),
	I_Installment_No INT,
	I_Sequence INT,
	C_Is_LumpSum varchar(1),
	I_Display_Fee_Component_ID INT
)

AS 
-- Return the Table containing the student course details.
BEGIN

	declare @discountperc decimal(14,2)=0
	declare @discountamount decimal(14,2)=0
	declare @sfromInstalment varchar(2)
	declare @ifromInstalment int=0
	declare @dincrement INT=1
	declare @dcount INT=0
	declare @i int=0
	declare @c int=0


	DECLARE @TblFeePlanDtl TABLE
	(
	ID INT IDENTITY(1,1),
	DiscountDetailID INT,
	DiscountSchemeID INT,
	DiscountRate Decimal(14,2),
	DiscountAmount decimal(14,2),
	IsApplicableOn INT,
	sFormInstalment Varchar(2),
	sFeeComponent varchar(max)
	)


	Insert into @TblFeePlan
	SELECT  I_Course_Fee_Plan_Detail_ID ,
			I_Fee_Component_ID ,
			I_Course_Fee_Plan_ID ,
			I_Item_Value ,
			ISNULL(N_CompanyShare, 0) AS N_CompanyShare ,
			I_Installment_No ,
			I_Sequence ,
			C_Is_LumpSum ,
			I_Display_Fee_Component_ID
	FROM    dbo.T_Course_Fee_Plan_Detail
	WHERE   I_Course_Fee_Plan_ID = @feeplanid
			AND I_Status = 1
	ORDER BY I_Installment_No,I_Sequence

	insert into @TblFeePlanDtl
	select * from T_Discount_Scheme_Details where I_Discount_Scheme_ID=@discountschemeid and I_IsApplicableOn=@paymentmode

	select @dcount=COUNT(*) from @TblFeePlanDtl

	while(@dincrement<=@dcount)
	begin

		declare @sFeeComponent varchar(max)=''

		declare @tblFeeComponent TABLE
		(
			FeeComponentID INT
		)

		select @discountperc=ISNULL(DiscountRate,0),@discountamount=ISNULL(DiscountAmount,0),@sfromInstalment=ISNULL(sFormInstalment,'F'),
				@sFeeComponent=ISNULL(sFeeComponent,'')
		from 
		@TblFeePlanDtl 
		where 
		DiscountSchemeID=@discountschemeid and IsApplicableOn=@paymentmode

		if(@sFeeComponent='')
		begin

			insert into @tblFeeComponent
			select Distinct I_Fee_Component_ID from @TblFeePlan
	
		end
		else
		begin

			insert into @tblFeeComponent
			select CAST(@sFeeComponent as INT)

		end




		IF(@sfromInstalment='F')
			select @ifromInstalment=MIN(I_Installment_No) from @TblFeePlan where C_Is_LumpSum='N'
		ELSE IF(@sfromInstalment='L')
			select @ifromInstalment=MAX(I_Installment_No) from @TblFeePlan where C_Is_LumpSum='N'
		ELSE
			set @ifromInstalment=cast(ISNULL(@sfromInstalment,'0') as INT)

		if(@sFeeComponent='')
		begin

			if(@paymentmode=1)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (N_TotalLumpSum*@discountperc)/100
					FROM    dbo.T_Course_Fee_Plan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							AND I_Status = 1 

				end

				--select @discountamount

			end
			else if(@paymentmode=2)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (N_TotalInstallment*@discountperc)/100
					FROM    dbo.T_Course_Fee_Plan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							AND I_Status = 1 

				end

				--select @discountamount

			end

		end
		else
		begin

			if(@paymentmode=1)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (SUM(I_Item_Value)*@discountperc)/100
					FROM    @TblFeePlan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							and I_Fee_Component_ID in
								(
									select FeeComponentID from @tblFeeComponent
								)
							and C_Is_LumpSum='Y'

				end

				--select @discountamount

			end
			else if(@paymentmode=2)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (SUM(I_Item_Value)*@discountperc)/100
					FROM    @TblFeePlan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							and I_Fee_Component_ID in
								(
									select FeeComponentID from @tblFeeComponent
								)
							and C_Is_LumpSum='N'

				end

				--select @discountamount

			end

		end

		if(@discountamount>0)
		begin

			declare @tempDiscount decimal(14,2)=@discountamount
	

			IF(@sfromInstalment='L')
			Begin

				select @c=1
				select @i=count(*) from @TblFeePlan

				while(@i>=@c)
				begin

					if(@paymentmode=1)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='Y' 
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='Y'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end
					else if(@paymentmode=2)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end

					set @i=@i-1

				end

			end
			else
			Begin
		
				set @i=@ifromInstalment
				select @c=count(*) from @TblFeePlan
	
				while(@i<=@c)
				begin

					if(@paymentmode=1)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='Y'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='Y'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end
					else if(@paymentmode=2)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end

					set @i=@i+1

				end

			end

		

		end

		--drop table #tblFeeComponent

		set @dincrement=@dincrement+1

	end

	RETURN;

END
GO
PRINT N'Creating Function [EOS].[fnGetKRAExamSchedule]...';


GO
-- =============================================
-- Author:		Arindam Roy
-- Create date: '07/30/2007'
-- Description:	This Function return a Numeric Value of Adherence to Exam Schedule KRA 
-- =============================================
CREATE FUNCTION [EOS].[fnGetKRAExamSchedule]
(
	@iEmployeeID INT,
	@iCurtrentMonth INT,
	@iCurtrentYear INT
)
RETURNS  @rtnTable TABLE
(
	TotalStudent INT,
	AppearedStudent INT
)

AS 

BEGIN

	DECLARE @CenterID INT
	DECLARE @TotalStudent INT
	DECLARE @AppearedStudent INT

	SELECT @CenterID=I_Centre_Id FROM dbo.T_Employee_Dtls WHERE I_Employee_ID=@iEmployeeID

--Total Student
	 SELECT @TotalStudent=COUNT(EL.I_Student_Detail_ID)
	   FROM EXAMINATION.T_Examination_Detail ED
			INNER JOIN EXAMINATION.T_Eligibility_List EL
			ON ED.I_Exam_ID=EL.I_Exam_ID
	  WHERE MONTH(ED.Dt_Exam_Date)=@iCurtrentMonth
		AND	YEAR(ED.Dt_Exam_Date)=@iCurtrentYear
		AND	ED.I_Centre_Id=@CenterID

--Appeared Student
	 SELECT @AppearedStudent=COUNT(EL.I_Student_Detail_ID)
	   FROM EXAMINATION.T_Examination_Detail ED
			INNER JOIN EXAMINATION.T_Eligibility_List EL
			ON ED.I_Exam_ID=EL.I_Exam_ID
			INNER JOIN EXAMINATION.T_Student_Marks SM
			ON ED.I_Exam_ID=SM.I_Exam_ID
			AND EL.I_Student_Detail_ID=SM.I_Student_Detail_ID
	  WHERE MONTH(ED.Dt_Exam_Date)=@iCurtrentMonth
		AND	YEAR(ED.Dt_Exam_Date)=@iCurtrentYear
		AND	ED.I_Centre_Id=@CenterID

	INSERT INTO @rtnTable
		SELECT	@TotalStudent,
				@AppearedStudent

	RETURN;

END
