PRINT N'Creating Function [dbo].[fnCourseListFromTemplateID]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '07/26/2007'
-- Description:	This Function return a table 
-- constains course id of given template id for print PS
-- Return: Table
-- =============================================
CREATE FUNCTION [dbo].[fnCourseListFromTemplateID]
(
	@iTemplate INT,
	@iFlag INT  -- This for track the template type like PS =1, Certificate =0 or TermCertificate=2
	
)
RETURNS @rtnTable TABLE
(
I_Course_ID INT
)

AS 
BEGIN

IF(@iFlag = 0)
	BEGIN
		-- for Certificate
		INSERT INTO @rtnTable
		SELECT I_Course_ID FROM dbo.T_Course_Master
		WHERE I_Certificate_ID IN (SELECT I_Certificate_ID FROM dbo.T_Certificate_Master
		WHERE I_Template_ID = @iTemplate)
	END
	-- for PS 
ELSE IF(@iFlag = 1)
	BEGIN
		INSERT INTO @rtnTable
		SELECT I_Course_ID FROM dbo.T_Term_Eval_Strategy
		WHERE I_Template_ID =@iTemplate
	END
	-- For Course term Certificate
ELSE
	BEGIN
		INSERT INTO @rtnTable
		SELECT I_Course_ID FROM dbo.T_Term_Course_Map
		WHERE I_Certificate_ID IN (
		SELECT I_Certificate_ID FROM dbo.T_Certificate_Master 
		WHERE S_Certificate_Type = 'Term'
		AND I_Template_ID = @iTemplate)
	END

	RETURN;
END
GO
PRINT N'Creating Function [dbo].[fnGetCenterIDFromHierarchy]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '11/26/2007'
-- Description:	This Function return a table 
-- constains center Id of HierarchyID 
-- Return: Table
-- =============================================
CREATE FUNCTION [dbo].[fnGetCenterIDFromHierarchy]
(
	@iSelectedHierarchyId INT,	
	@iBrandId INT
)
RETURNS  @TempCenter TABLE
	( 
		I_Center_ID int
	)

AS 
BEGIN
	DECLARE @sSearchCriteria varchar(100)
	IF @iSelectedHierarchyId IS NOT NULL	
	BEGIN

		SELECT @sSearchCriteria= S_Hierarchy_Chain from T_Hierarchy_Mapping_Details where I_Hierarchy_detail_id = @iSelectedHierarchyId  
		
		IF @iBrandId = 0 
			BEGIN
				INSERT INTO @TempCenter 
				SELECT TCHD.I_Center_Id FROM T_CENTER_HIERARCHY_DETAILS TCHD WHERE 
				TCHD.I_Hierarchy_Detail_ID IN 
				(SELECT I_HIERARCHY_DETAIL_ID FROM T_Hierarchy_Mapping_Details 
				WHERE I_Status = 1
				AND GETDATE() >= ISNULL(Dt_Valid_From,GETDATE())
				AND GETDATE() <= ISNULL(Dt_Valid_To,GETDATE())
				AND S_Hierarchy_Chain LIKE @sSearchCriteria + '%') 
				AND TCHD.I_Status = 1
			END
		ELSE
			BEGIN
				INSERT INTO @TempCenter 
				SELECT TCHD.I_Center_Id FROM T_CENTER_HIERARCHY_DETAILS TCHD,T_BRAND_CENTER_DETAILS TBCD WHERE
				TCHD.I_Hierarchy_Detail_ID IN 
			   (SELECT I_HIERARCHY_DETAIL_ID FROM T_Hierarchy_Mapping_Details 
				WHERE I_Status = 1
				AND GETDATE() >= ISNULL(Dt_Valid_From,GETDATE())
				AND GETDATE() <= ISNULL(Dt_Valid_To,GETDATE())
				AND S_Hierarchy_Chain LIKE @sSearchCriteria + '%') AND
				TBCD.I_Brand_ID=@iBrandId AND
				TBCD.I_Centre_Id = TCHD.I_Center_Id
				AND TCHD.I_Status = 1 			 
			END
	END
	ELSE
	BEGIN
		INSERT INTO @TempCenter
		SELECT I_Centre_ID FROM T_Centre_Master WHERE I_Status = 1
	END
 RETURN ;
END
GO
PRINT N'Creating Function [dbo].[fnGetCentersForReports]...';


GO
-- =============================================  
-- Author:  Abhisek Bhattacharya  
-- Create date: '06/06/2007'  
-- Description: This Function return a table   
-- consisting of brand, hierarchy Detail ID, center ID, center Code, center Name  
-- Return: Table  
-- =============================================  
CREATE FUNCTION [dbo].[fnGetCentersForReports]  
(  
 @sHierarchyChain VARCHAR(max),  
 @iBrandID INT  
)  
RETURNS  @rtnTable TABLE  
(  
 brandID INT,  
 hierarchyDetailID INT,  
 centerID INT,  
 centerCode VARCHAR(20),  
 centerName VARCHAR(100)  
)  
  
AS   
-- Returns the Table containing the center details.  
BEGIN  
  
 DECLARE @iHierarchyDetailID INT  
 DECLARE @iGetIndexHierarchy INT  
 DECLARE @sHierarchyDetailID VARCHAR(20)  
 DECLARE @iLengthHierarchy INT  
 DECLARE @sTempHierarchyChain VARCHAR(100)  
  
 -- Append a comma after the Hierarchy Chain  
 SET @sHierarchyChain = @sHierarchyChain + ','  
  
 -- Get the start index for Hierarchy  
 SET @iGetIndexHierarchy = CHARINDEX(',',LTRIM(RTRIM(@sHierarchyChain)),1)  
  
 -- If start index for Hierarchy is greater than 1  
 IF @iGetIndexHierarchy > 1  
 BEGIN  
  WHILE LEN(@sHierarchyChain) > 0  
  BEGIN  
   SET @iGetIndexHierarchy = CHARINDEX(',',@sHierarchyChain,1)  
   SET @iLengthHierarchy = LEN(@sHierarchyChain)  
   SET @iHierarchyDetailID = CAST(LTRIM(RTRIM(LEFT(@sHierarchyChain,@iGetIndexHierarchy-1))) AS int)  
  
   -- Get the hierarchy chain for the above Hierarchy Detail ID  
   SELECT @sTempHierarchyChain = S_Hierarchy_Chain   
   FROM dbo.T_Hierarchy_Mapping_Details  
   WHERE I_Hierarchy_Detail_ID = @iHierarchyDetailID  
   AND I_Status = 1  
   AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())  
   AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())  
  
   -- Append the chain with %  
   SET @sTempHierarchyChain = '%'+@sTempHierarchyChain + '%'  
  
   -- Insert the center wchich falls under the selected Hierarchy and Brand  
   INSERT INTO @rtnTable  
   SELECT @iBrandID,   
     @iHierarchyDetailID,  
     CM.I_Centre_Id,  
     CM.S_Center_Code,  
     CM.S_Center_Name  
   FROM dbo.T_Centre_Master CM  
   INNER JOIN dbo.T_Center_Hierarchy_Details CHD  
   ON CM.I_Centre_Id = CHD.I_Center_Id  
   AND CHD.I_Status = 1  
   AND GETDATE() >= ISNULL(CHD.Dt_Valid_From, GETDATE())  
   AND GETDATE() <= ISNULL(CHD.Dt_Valid_To, GETDATE())  
   INNER JOIN dbo.T_Brand_Center_Details BCD  
   ON CM.I_Centre_Id = BCD.I_Centre_Id  
   AND BCD.I_Brand_ID = @iBrandID  
   INNER JOIN dbo.T_Hierarchy_Mapping_Details HMD  
   ON CHD.I_Hierarchy_Detail_ID = HMD.I_Hierarchy_Detail_ID  
   AND HMD.S_Hierarchy_Chain LIKE @sTempHierarchyChain  
   AND HMD.I_Status = 1  
   AND GETDATE() >= ISNULL(HMD.Dt_Valid_From, GETDATE())  
   AND GETDATE() <= ISNULL(HMD.Dt_Valid_To, GETDATE())  
  
  
   SELECT @sHierarchyChain = SUBSTRING(@sHierarchyChain,@iGetIndexHierarchy + 1, @iLengthHierarchy - @iGetIndexHierarchy)  
   SELECT @sHierarchyChain = LTRIM(RTRIM(@sHierarchyChain))  
  END  
 END  
   
 RETURN;  
  
END
GO
PRINT N'Creating Function [dbo].[fnGetCHandASH]...';


GO
CREATE FUNCTION [dbo].[fnGetCHandASH]        
(        
  @iCenterId INT        
 ,@iRoleId INT        
)        
RETURNS @UserIDTable TABLE        
(        
  I_User_Id INT        
 ,S_Email_Id VARCHAR(200)        
)        
AS        
BEGIN        
        
IF @iRoleId = 8        
BEGIN        
    
IF EXISTS    
(    
SELECT UHD.I_User_Id        
  ,UM.S_Email_Id        
FROM dbo.T_Center_Hierarchy_Details CHD        
INNER JOIN dbo.T_Hierarchy_Mapping_Details HMD         
  ON CHD.I_Hierarchy_Detail_ID = HMD.I_Hierarchy_Detail_ID        
INNER JOIN dbo.T_User_Hierarchy_Details UHD        
  ON HMD.I_Hierarchy_Detail_ID = UHD.I_Hierarchy_Detail_ID        
INNER JOIN dbo.T_User_Role_Details URD        
  ON UHD.I_User_Id = URD.I_User_Id        
INNER JOIN dbo.T_User_Master UM        
  ON UHD.I_User_Id = UM.I_User_Id        
WHERE URD.I_Role_Id = @iRoleId AND CHD.I_Center_Id = @iCenterId        
AND CHD.I_Status = 1        
AND HMD.I_Status = 1        
AND UHD.I_Status = 1        
AND UM.I_Status = 1    
)    
 BEGIN    
  INSERT INTO @UserIDTable        
        
  SELECT UHD.I_User_Id        
    ,UM.S_Email_Id        
  FROM dbo.T_Center_Hierarchy_Details CHD        
  INNER JOIN dbo.T_Hierarchy_Mapping_Details HMD         
    ON CHD.I_Hierarchy_Detail_ID = HMD.I_Hierarchy_Detail_ID        
  INNER JOIN dbo.T_User_Hierarchy_Details UHD        
    ON HMD.I_Hierarchy_Detail_ID = UHD.I_Hierarchy_Detail_ID        
  INNER JOIN dbo.T_User_Role_Details URD        
    ON UHD.I_User_Id = URD.I_User_Id        
  INNER JOIN dbo.T_User_Master UM        
    ON UHD.I_User_Id = UM.I_User_Id        
  WHERE URD.I_Role_Id = @iRoleId AND CHD.I_Center_Id = @iCenterId        
  AND CHD.I_Status = 1        
  AND HMD.I_Status = 1        
  AND UHD.I_Status = 1        
  AND UM.I_Status = 1     
 END    
 ELSE    
 BEGIN    
  INSERT INTO @UserIDTable     
  SELECT UM.I_User_Id    
  ,UM.S_Login_ID+'@aptech.ac.in'    
  FROM dbo.T_User_Master UM    
  INNER JOIN dbo.T_User_Role_Details URD ON UM.I_User_Id = URD.I_User_Id    
  WHERE URD.I_Role_ID = 1    
 END       
       
        
END        
        
ELSE IF @iRoleId = 3        
BEGIN        
 DECLARE @iHierarchyDetailId INT         
 DECLARE @continue INT         
 SET @continue = 1        
        
 SELECT @iHierarchyDetailId = I_Hierarchy_Detail_Id        
 FROM dbo.T_Center_Hierarchy_Details        
 WHERE I_Center_Id = @iCenterId AND I_Status = 1        
        
 WHILE ( @continue = 1 )        
 BEGIN        
  IF EXISTS        
  (        
   SELECT UHD.I_User_Id        
   FROM dbo.T_User_Hierarchy_Details UHD        
   INNER JOIN dbo.T_User_Role_Details URD        
    ON UHD.I_User_Id = URD.I_User_Id        
   WHERE UHD.I_Hierarchy_Detail_Id = @iHierarchyDetailId        
   AND URD.I_Role_Id = @iRoleId        
   AND UHD.I_Status = 1        
   AND URD.I_Status = 1        
  )        
  BEGIN        
   INSERT INTO @UserIDTable(I_User_Id,S_Email_Id)        
   SELECT UHD.I_User_Id,ISNULL(UM.S_Email_Id,UM.S_Login_Id+'@aptech.ac.in')        
   FROM dbo.T_User_Hierarchy_Details UHD        
   INNER JOIN dbo.T_User_Role_Details URD        
    ON UHD.I_User_Id = URD.I_User_Id        
   INNER JOIN dbo.T_User_Master UM        
    ON UM.I_User_Id = UHD.I_User_Id        
   WHERE UHD.I_Hierarchy_Detail_Id = @iHierarchyDetailId        
   AND URD.I_Role_Id = @iRoleId        
   AND UHD.I_Status = 1        
   AND URD.I_Status = 1        
   AND UM.I_Status = 1        
           
   SET @continue = 0        
  END        
  ELSE        
  BEGIN        
   SELECT @iHierarchyDetailId = I_Parent_ID        
   FROM dbo.T_Hierarchy_Mapping_Details        
   WHERE I_Hierarchy_Detail_Id = @iHierarchyDetailId        
   AND I_Status = 1        
  END        
 END        
END        
RETURN;        
END
GO
