PRINT N'Creating Function [dbo].[fnGetExamModuleList]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '08/17/2007'
-- Description:	This Function return a table 
-- constains Exam Module name List
-- Return: Table
-- =============================================
CREATE FUNCTION [dbo].[fnGetExamModuleList]
(
	@iCourse INT ,
	@iTermID INT
)
RETURNS  @rtnTable TABLE
(
	S_Component_Name VARCHAR(2000)
)

AS 
-- Return the Table containing the student course details.
BEGIN
		DECLARE @tmpSub TABLE
		(
		sSubject VARCHAR(100)
		)
		DECLARE @getSubjects VARCHAR(2000)

		SET @getSubjects = ''

		INSERT INTO @tmpSub
		SELECT DISTINCT S_Module_Name FROM dbo.T_Module_Master MM
INNER JOIN dbo.T_Module_Term_Map MTM
ON MM.I_Module_ID=MTM.I_Module_ID
INNER JOIN dbo.T_Term_Course_Map TCM
ON TCM.I_Term_ID = MTM.I_Term_ID
WHERE TCM.I_Course_ID =COALESCE(@iCourse,TCM.I_Course_ID)
AND MTM.I_Term_ID = COALESCE(@iTermID,MTM.I_Term_ID)				

		

		SELECT @getSubjects = @getSubjects + CAST(sSubject AS VARCHAR(100))+ ' ,'
		FROM @tmpSub

		IF(@getSubjects <>'')
					BEGIN
					SET @getSubjects = SUBSTRING(@getSubjects,0,LEN(@getSubjects)-1)
					END
		
-- Insert Record in return table
		INSERT INTO @rtnTable (S_Component_Name)
		VALUES (@getSubjects)

	RETURN;

END
GO
PRINT N'Creating Function [dbo].[fnGetStudentCourseDetailForShortTermCourse]...';


GO
CREATE FUNCTION [dbo].[fnGetStudentCourseDetailForShortTermCourse]
(
	@StudentID INT,
	@iCourseID INT	
)
RETURNS @Temp TABLE
(
DtStartDate DATETIME,
DtEndDate DATETIME,
Duration INT
)

AS 
 --Return the Table containing the student marks details.
BEGIN

DECLARE @DtStartDate DATETIME
DECLARE @DtEndDate DATETIME
DECLARE @iSessionTime INT
DECLARE @Duration INT	

---- For start day 
	SET @DtStartDate = (SELECT  TOP 1(Dt_Attendance_Date)
	FROM dbo.T_Student_Attendance_Details
	WHERE I_Student_Detail_ID = @StudentID
	AND I_Has_Attended = 1
	AND I_Course_ID = ISNULL(@iCourseID,I_Course_ID))

-- Course end day

SET @DtEndDate =(SELECT Max(Dt_Crtd_On) FROM PSCERTIFICATE.T_Student_PS_Certificate
WHERE I_Student_Detail_ID = @StudentID
AND I_Course_ID = ISNULL(@iCourseID,I_Course_ID)
AND B_PS_Flag = 0)


SET @iSessionTime = (SELECT SUM(B.N_Session_Duration)
					FROM dbo.T_Session_Module_Map A
						INNER JOIN dbo.T_Session_Master B
						ON A.I_Session_ID = B.I_Session_ID
						INNER JOIN dbo.T_Module_Term_Map C
						ON A.I_Module_ID = C.I_Module_ID
						INNER JOIN dbo.T_Term_Course_Map D   
						ON C.I_Term_ID = D.I_Term_ID
						AND D.I_Course_ID = @iCourseID
						AND GETDATE() >= ISNULL(A.Dt_Valid_From, GETDATE())
						AND GETDATE() <= ISNULL(A.Dt_Valid_To, GETDATE())
						AND A.I_Status <> 0
						AND B.I_Status <> 0
						AND C.I_Status <> 0
						AND D.I_Status <> 0
						GROUP BY B.N_Session_Duration)


IF(@iSessionTime <> 0)
BEGIN
	SET @Duration = (SELECT ROUND((@iSessionTime/60),0))
END

INSERT INTO @Temp
SELECT @DtStartDate, @DtEndDate, ISNULL(@Duration,0)


	RETURN;
END
GO
