PRINT N'Creating Function [dbo].[ufnCheckIfQBankExists]...';


GO
CREATE function [dbo].[ufnCheckIfQBankExists]
(
	@iQBankID INT
)
RETURNS INT

AS
BEGIN

declare @sQBankID varchar(max)
DECLARE @iResult INT
SET @iResult = 0

	DECLARE _CURSOR CURSOR FOR
	SELECT DISTINCT S_Question_Bank_ID FROM EXAMINATION.T_Test_Design

		OPEN _CURSOR
		FETCH NEXT FROM _CURSOR INTO @sQBankID

		WHILE @@FETCH_STATUS = 0
		BEGIN

		IF EXISTS(SELECT * FROM dbo.fnString2Rows(@sQBankID,',') where val = @iQBankID )
		BEGIN			
			SET @iResult = 1
			BREAK;
		END

			FETCH NEXT FROM _CURSOR INTO @sQBankID
		END	
	
	CLOSE _CURSOR
	DEALLOCATE _CURSOR

RETURN @iResult

END
GO
PRINT N'Creating Function [ECOMMERCE].[fnValidateProductPayables]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '08/17/2007'
-- Description:	This Function return a table 
-- constains Exam Module name List
-- Return: Table
-- =============================================
CREATE FUNCTION [ECOMMERCE].[fnValidateProductPayables]
(
	@BrandID INT,
	@CouponCode VARCHAR(MAX),
	@PlanID INT,
	@ProductID INT,
	@CenterID INT,
	@PaymentMode INT
)
RETURNS  @rtnTable TABLE
(
	PayableAmount DECIMAL(14,2),
	PayableTax DECIMAL(14,2),
	IsCouponApplicable BIT
)

AS 
-- Return the Table containing the student course details.
BEGIN
	declare @couponid int=0
	declare @discountschemeid int=0
	declare @feeplanid int=0
	declare @flag bit=0

	DECLARE @TblFeePlanDtls TABLE
	(
		ID INT,
		I_Course_Fee_Plan_Detail_ID INT ,
		I_Fee_Component_ID INT,
		I_Course_Fee_Plan_ID INT,
		I_Item_Value Decimal(14,2),
		N_Discount decimal(14,2),
		I_Installment_No INT,
		I_Sequence INT,
		C_Is_LumpSum varchar(1),
		I_Display_Fee_Component_ID INT
	)

	select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID 
	from ECOMMERCE.T_Coupon_Master TCM
	inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
	inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
	inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
	inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
	inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
	inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
	inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
	inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
	inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
	inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
	where
	TCM.StatusID=1 and TDSM.I_Status=1
	and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
	and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
	and TCBM.BrandID=@BrandID
	and TPBM.BrandID=@BrandID
	and TCM.CouponCategoryID IN (1,2,3)
	and TCM.CouponCount>TCM.AssignedCount
	and TDSD.I_IsApplicableOn=@PaymentMode
	and TPM.ProductID=@ProductID
	and TPCM.PlanID=@PlanID
	and TDCD.I_Centre_ID=@CenterID
	and TCM.CouponCode=@CouponCode


	select @feeplanid=B.CourseFeePlanID from ECOMMERCE.T_Product_Center_Map A
	inner join ECOMMERCE.T_Product_FeePlan B on A.ProductCentreID=B.ProductCentreID
	inner join ECOMMERCE.T_Plan_Product_Map C on A.ProductID=C.ProductID
	where
	A.CenterID=@CenterID and A.ProductID=@ProductID and C.PlanID=@PlanID
	and C.StatusID=1

	--print @feeplanid


	insert into @TblFeePlanDtls
	select * from [ECOMMERCE].[fnGetFeePlanDiscountDetails] (@feeplanid,@PaymentMode,@discountschemeid)


	
	

	

	if(@couponid>0)
		set @flag=1




	IF(@PaymentMode=1)
	BEGIN
		
		insert into @rtnTable
		select SUM(P.PayableAmount) as PayableAmount,SUM(P.PayableTax) as PayableTax, @flag as IsCouponApplicable from
		(
			select T1.Amount as PayableAmount,((T1.Amount*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from @TblFeePlanDtls A
				where A.I_Installment_No=0
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P

	END
	ELSE IF(@PaymentMode=2)
	BEGIN

		DECLARE @MinInstNo INT

		select @MinInstNo=MIN(I_Installment_No) from @TblFeePlanDtls where I_Installment_No>0

		insert into @rtnTable
		select SUM(P.PayableAmount) as PayableAmount,SUM(P.PayableTax) as PayableTax, @flag as IsCouponApplicable 
		from
		(
			select T1.Amount as PayableAmount,((T1.Amount*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from @TblFeePlanDtls A
				where A.I_Installment_No=@MinInstNo
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P

	END

	RETURN;

END
GO
PRINT N'Creating Function [MBP].[fnGetProductIDFromCenterID]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '08/08/2007'
-- Description:	This Function return a table 
-- consisting of product id of given Center ID
-- Return: Table
-- =============================================
CREATE FUNCTION [MBP].[fnGetProductIDFromCenterID]
(
	@iCenterID INT,
	@iMonth INT,
	@iYear INT
)
RETURNS  @rtnTable TABLE
(
	iStudentID INT,
	iProductID INT,
	iCenterID INT
)

AS 
-- Returns the Table containing the Course details.
BEGIN
	DECLARE @iRow INT
	DECLARE @iCount INT
	DECLARE @iRow2 INT
	DECLARE @iCount2 INT
	SET @iCount = 1
	SET @iCount2 = 1

	DECLARE @iCourseID INT
	DECLARE @iStudentID INT
	--for store temp student id 
	DECLARE @temStudent TABLE
	(
	ID INT IDENTITY(1,1),
	iStudentID INT
	)
	DECLARE @temCourse TABLE
	(
	ID INT IDENTITY(1,1),
	iCourseID INT
	)
	DECLARE @temProduct TABLE
	(
	ID INT IDENTITY(1,1),
	iProductID INT
	)


	INSERT INTO @temStudent(iStudentID)
	SELECT I_Student_Detail_ID FROM dbo.T_Student_Center_Detail
	WHERE I_Centre_Id = @iCenterID
	AND (DATEPART(mm,Dt_Valid_From))  = @iMonth
	AND (DATEPART(yy,Dt_Valid_From))  = @iYear
	--AND (DATEPART(mm,Dt_Crtd_On))  = @iMonth
	--AND (DATEPART(yy,Dt_Crtd_On))  = @iYear
	
	SET @iRow = (SELECT COUNT(ID) FROM @temStudent)	


WHILE (@iCount <= @iRow )
			 BEGIN
				SET @iStudentID =(SELECT iStudentID FROM @temStudent WHERE ID = @iCount )

					INSERT INTO @temCourse(iCourseID)
					SELECT DISTINCT(I_Course_ID) 
					FROM dbo.T_Student_Course_Detail
					WHERE I_Student_Detail_ID = @iStudentID
									
					
					SET @iRow2 = (SELECT COUNT(*) FROM @temCourse)
					--SELECT @iRow2
					SET @iCount2 = 1
					WHILE (@iCount2 <= @iRow2 )
					BEGIN 
						SET @iCourseID =( SELECT iCourseID FROM @temCourse WHERE ID = @iCount)								

								INSERT INTO @temProduct(iProductID)
								SELECT iProductID FROM [MBP].[fnGetProductIDFromCourseID](@iCourseID)							
								SET @iCount2 = @iCount2 +1

					 END 

						INSERT INTO @rtnTable (iProductID,iStudentID,iCenterID)
					    SELECT  DISTINCT(iProductID), @iStudentID,@iCenterID  FROM @temProduct
						DELETE FROM @temProduct

           SET @iCount = @iCount +1
	END	

	RETURN;
END
GO
PRINT N'Creating Function [MBP].[fnGetYTDFORMBP]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '14/02/2008'
-- Description:	This Function return a table 
-- constains YTD For Enquiry, Enrollmet, Booking and Billing
-- Return: Table
-- =============================================
CREATE FUNCTION [MBP].[fnGetYTDFORMBP]
(
	@iMonth INT,
	@iYear INT,
	@iCenterID VARCHAR(2000),
	@iProductID INT
)
RETURNS  @TempYTDMBP TABLE
	( 
		I_Center_ID int,
		I_Target_Enquiry INT,
		I_Target_Booking NUMERIC(18,2),
		I_Target_Enrollment INT,
		I_Target_Billing NUMERIC(18,2),
		I_Target_RFF NUMERIC(18,2),
		I_Actual_Enquiry INT,
		I_Actual_Booking NUMERIC(18,2),
		I_Actual_Enrollment INT,
		I_Actual_Billing NUMERIC(18,2),
		I_Actual_RFF NUMERIC(18,2)			
		
	)

AS 
BEGIN
		DECLARE @I_Center_ID int
		DECLARE @I_Target_Enquiry INT
		DECLARE @I_Target_Booking NUMERIC(18,2)
		DECLARE @I_Target_Enrollment INT
		DECLARE @I_Target_Billing NUMERIC(18,2)
		DECLARE @I_Target_RFF NUMERIC(18,2)
		DECLARE @I_Target_Enquiry_Audit INT
		DECLARE @I_Target_Booking_Audit NUMERIC(18,2)
		DECLARE @I_Target_Enrollment_Audit INT
		DECLARE @I_Target_Billing_Audit NUMERIC(18,2)
		DECLARE @I_Target_RFF_Audit NUMERIC(18,2)
		DECLARE @I_Actual_Enquiry INT
		DECLARE @I_Actual_Booking NUMERIC(18,2)
		DECLARE @I_Actual_Enrollment INT
		DECLARE @I_Actual_Billing NUMERIC(18,2)
		DECLARE @I_Actual_RFF NUMERIC(18,2)	
	

DECLARE @temTable TABLE
(
ID INT IDENTITY(1,1),
I_Center_ID INT
)

DECLARE @iCount INT
DECLARE @iRow INT
DECLARE @iNewCenterID INT

INSERT INTO @temTable
SELECT ID FROM [dbo].[fnSplitter](@iCenterID)

SET @iCount = 1
SET @iRow = (SELECT COUNT(ID) FROM @temTable)

WHILE(@iCount <= @iRow)
 BEGIN
	SET @iNewCenterID = (SELECT I_Center_ID FROM @temTable WHERE ID = @iCount)

		-- FOR TARGET DATA
		SELECT @I_Target_Enquiry=SUM(ISNULL(MBP.I_Target_Enquiry,0)),@I_Target_Booking =SUM(ISNULL(MBP.I_Target_Booking,0)),
		 @I_Target_Enrollment = SUM(ISNULL(MBP.I_Target_Enrollment,0)) ,@I_Target_Billing =SUM(ISNULL(MBP.I_Target_Billing,0)),
		 @I_Target_RFF = SUM(ISNULL(MBP.I_Target_RFF,0))
		FROM MBP.T_MBP_Detail MBP
		WHERE MBP.I_Center_ID =@iNewCenterID
		AND MBP.I_Product_ID =@iProductID
		AND I_Month <= @iMonth
		AND MBP.I_Year = @iYear
		AND MBP.I_Type_ID = 4

		-- GETTING TARGET DATA FROM AUDIT TABLE 

			SELECT @I_Target_Enquiry_Audit=SUM(ISNULL(MDA.I_Target_Enquiry,0)),@I_Target_Booking_Audit =SUM(ISNULL(MDA.I_Target_Booking,0)),
			 @I_Target_Enrollment_Audit =  SUM(ISNULL(MDA.I_Target_Enrollment,0)) ,@I_Target_Billing_Audit =SUM(ISNULL(MDA.I_Target_Billing,0)),
			 @I_Target_RFF_Audit =SUM(ISNULL(MDA.I_Target_RFF,0))
			FROM MBP.T_MBP_Detail_Audit MDA
			WHERE MDA.I_MBP_Detail_ID IN (SELECT I_MBP_Detail_ID FROM MBP.T_MBP_Detail MBP WHERE
			 MBP.I_Center_ID =@iNewCenterID
			AND MBP.I_Product_ID =@iProductID
			AND I_Month <= @iMonth
			AND MBP.I_Year = @iYear
			AND MBP.I_Type_ID = 5)
			AND MDA.I_Type_ID = 4

			IF(@I_Target_Enquiry_Audit IS NOT NULL)
			 BEGIN
					SET @I_Target_Enquiry = (@I_Target_Enquiry + @I_Target_Enquiry_Audit)
			 END
			IF(@I_Target_Booking_Audit IS NOT NULL)
			 BEGIN
				SET @I_Target_Booking  = (@I_Target_Booking + @I_Target_Booking_Audit )
			 END
			IF(@I_Target_Enrollment_Audit IS NOT NULL)
			 BEGIN
				SET @I_Target_Enrollment=(@I_Target_Enrollment +@I_Target_Enrollment_Audit)
			 END
			IF(@I_Target_Billing_Audit IS NOT NULL)
			 BEGIN
				SET @I_Target_Billing =(@I_Target_Billing +@I_Target_Billing_Audit)
			 END
			IF(@I_Target_RFF_Audit IS NOT NULL)
			 BEGIN
				SET @I_Target_RFF =(@I_Target_RFF +@I_Target_RFF_Audit)
			 END

	

		-- FOR ACTUAL DATA
		SELECT @I_Actual_Enquiry=SUM(ISNULL(PER.I_Actual_Enquiry,0)),@I_Actual_Booking =SUM(ISNULL(PER.I_Actual_Booking,0)),
		@I_Actual_Enrollment = SUM(ISNULL(PER.I_Actual_Enrollment,0)) ,@I_Actual_Billing =SUM(ISNULL(PER.I_Actual_Billing,0)),
		@I_Actual_RFF =SUM(ISNULL(PER.I_Actual_RFF,0))
		FROM  MBP.T_MBPerformance PER
		WHERE PER.I_Center_ID =@iNewCenterID
		AND PER.I_Product_ID =@iProductID
		AND I_Month <= @iMonth
		AND PER.I_Year = @iYear
	
		INSERT INTO @TempYTDMBP(I_Center_ID,I_Target_Enquiry,I_Target_Booking,I_Target_Enrollment,I_Target_Billing,I_Target_RFF,I_Actual_Enquiry,I_Actual_Booking,I_Actual_Enrollment,I_Actual_Billing,I_Actual_RFF)
		SELECT @iNewCenterID,@I_Target_Enquiry,@I_Target_Booking,@I_Target_Enrollment,@I_Target_Billing,@I_Target_RFF,@I_Actual_Enquiry,@I_Actual_Booking,@I_Actual_Enrollment,@I_Actual_Billing,@I_Actual_RFF

SET @iCount = @iCount+1 
	
END

	
 RETURN ;
END
GO
PRINT N'Creating Function [dbo].[fnGetInstanceNameChainForReports]...';


GO
-- =============================================
-- Author:		Abhisek Bhattacharya
-- Create date: '06/06/2007'
-- Description:	This Function return a table 
-- consisting of hierarchy instance chain, hierarchy detail ID
-- Return: Table
-- =============================================
CREATE FUNCTION [dbo].[fnGetInstanceNameChainForReports]
(
	@sHierarchyChain VARCHAR(max),
	@iBrandID INT
)
RETURNS  @rtnTable TABLE
(
	hierarchyDetailID INT,
	instanceChain VARCHAR(5000)
)

AS 
-- Returns the Table containing the center details.
BEGIN

	DECLARE @iHierarchyDetailID INT
	DECLARE @iGetIndexHierarchy INT
	DECLARE @sHierarchyDetailID VARCHAR(20)
	DECLARE @iLengthHierarchy INT
	DECLARE @sTempHierarchyChain VARCHAR(100)
	DECLARE @sTempInstanceNameChain VARCHAR(5000)

	-- Append a comma after the Hierarchy Chain
	SET @sHierarchyChain = @sHierarchyChain + ','

	-- Get the start index for Hierarchy
	SET @iGetIndexHierarchy = CHARINDEX(',',LTRIM(RTRIM(@sHierarchyChain)),1)

	-- If start index for Hierarchy is greater than 1
	IF @iGetIndexHierarchy > 1
	BEGIN
		WHILE LEN(@sHierarchyChain) > 0
		BEGIN
			SET @iGetIndexHierarchy = CHARINDEX(',',@sHierarchyChain,1)
			SET @iLengthHierarchy = LEN(@sHierarchyChain)
			SET @iHierarchyDetailID = CAST(LTRIM(RTRIM(LEFT(@sHierarchyChain,@iGetIndexHierarchy-1))) AS int)

			-- Get the hierarchy chain for the above Hierarchy Detail ID
			SELECT @sTempHierarchyChain = S_Hierarchy_Chain	
			FROM dbo.T_Hierarchy_Mapping_Details
			WHERE I_Hierarchy_Detail_ID = @iHierarchyDetailID
			AND I_Status = 1
			AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())
			AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())

			-- Set the default value as empty string
			SET @sTempInstanceNameChain = ''

			-- Get the Brand code in insatnce name chain
			SELECT @sTempInstanceNameChain = 'Brand-' + BM.S_Brand_Code + ';  '
			FROM dbo.T_Brand_Master BM
			WHERE BM.I_Brand_ID = @iBrandID

			-- Get the instance name chain
			SELECT @sTempInstanceNameChain = @sTempInstanceNameChain + B.S_Hierarchy_Level_Name + '-' + A.S_Hierarchy_Name + ';  '
			FROM dbo.T_Hierarchy_Details A
			INNER JOIN dbo.T_Hierarchy_Level_Master B
			ON A.I_Hierarchy_Level_Id = B.I_Hierarchy_Level_Id	
			WHERE A.I_Hierarchy_Detail_ID IN (SELECT * FROM dbo.fnString2Rows(@sTempHierarchyChain,','))
						
			-- Truncate the last comma from the Instance Name chain
			SET @sTempInstanceNameChain = SUBSTRING(@sTempInstanceNameChain, 0, LEN(@sTempInstanceNameChain))

			-- Insert the center wchich falls under the selected Hierarchy and Brand
			INSERT INTO @rtnTable
			SELECT	@iHierarchyDetailID,
					@sTempInstanceNameChain

			SELECT @sHierarchyChain = SUBSTRING(@sHierarchyChain,@iGetIndexHierarchy + 1, @iLengthHierarchy - @iGetIndexHierarchy)
			SELECT @sHierarchyChain = LTRIM(RTRIM(@sHierarchyChain))
		END
	END
	
	RETURN;

END
GO
