GO
/*******************************************************
Description : Approve E-Project Extension Request
Author	:     Arindam Roy
Date	:	  05/25/2007
*********************************************************/

CREATE PROCEDURE [ACADEMICS].[uspApproveEProjectExtensionRequest] 
(
	@iEProjectGroupID int,
	@sExtensionReason varchar(500),
	@dExtentedDate datetime,
	@iStatus int,
	@sUser varchar(20),
	@dDate datetime
)

AS

BEGIN TRY 

		UPDATE ACADEMICS.T_E_Project_Extension
		   SET I_E_Project_Group_ID=@iEProjectGroupID,
			   S_Reason=@sExtensionReason,
			   Dt_New_End_Date=@dExtentedDate,
			   I_Status=0,
			   Dt_Upd_On=@dDate,
			   S_Upd_By=@sUser
		 WHERE I_E_Project_Group_ID=@iEProjectGroupID
		   AND I_Status=1
	

	INSERT INTO ACADEMICS.T_E_Project_Group_Audit
	(
			I_E_Project_Group_ID,
			S_Group_Desc,
			I_E_Project_Spec_ID,
			I_Center_ID,
			I_Course_ID,
			I_Term_ID,
			I_Module_ID,
			Dt_Project_Start_Date,
			Dt_Project_End_Date,
			Dt_Cancellation_Date,
			S_Cancellation_Reason,
			I_E_Project_File_ID,
			I_Report_File_ID,
			S_Crtd_By,
			S_Upd_By,
			Dt_Crtd_On,
			Dt_Upd_On,
			I_Status
	)
	SELECT  I_E_Project_Group_ID,
			S_Group_Desc,
			I_E_Project_Spec_ID,
			I_Center_ID,
			I_Course_ID,
			I_Term_ID,
			I_Module_ID,
			Dt_Project_Start_Date,
			Dt_Project_End_Date,
			Dt_Cancellation_Date,
			S_Cancellation_Reason,
			I_E_Project_File_ID,
			I_Report_File_ID,
			S_Crtd_By,
			S_Upd_By,
			Dt_Crtd_On,
			Dt_Upd_On,
			I_Status
	   FROM ACADEMICS.T_E_Project_Group
	  WHERE I_E_Project_Group_ID=@iEProjectGroupID
	
	IF @iStatus = 5   -- ProjectExtended
	BEGIN
		UPDATE ACADEMICS.T_E_Project_Group
		   SET I_Status=@iStatus,
			   Dt_Project_End_Date=@dExtentedDate,
			   S_Upd_By=@sUser,
			   Dt_Upd_On=@dDate
		 WHERE I_E_Project_Group_ID=@iEProjectGroupID
	END
	ELSE             -- (@iStatus = 8) ProjectExtensionCancelled
	BEGIN
		UPDATE ACADEMICS.T_E_Project_Group
		   SET I_Status=@iStatus,
			   S_Upd_By=@sUser,
			   Dt_Upd_On=@dDate
		 WHERE I_E_Project_Group_ID=@iEProjectGroupID
	END

	UPDATE ACADEMICS.T_Center_E_Project_Manual
	   SET I_Status=@iStatus,
		   S_Upd_By=@sUser,
		   Dt_Upd_On=@dDate
	 WHERE I_E_Project_Group_ID=@iEProjectGroupID
	   AND I_Status NOT IN (2,3)

END TRY
BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [ACADEMICS].[uspCalculateEprojectEndDate]...';


GO
/*****************************************************************************************************************
Created by:		Swagata De
Date:			11/9/07
Description:	This Stored procedure is used to calculate the end date for an e project on the basis of the start date
Parameters:		@iDeliveryPatternID int,
				@iModuleID int	
Returns:	
******************************************************************************************************************/

CREATE PROCEDURE [ACADEMICS].[uspCalculateEprojectEndDate] 
(
	@iDeliveryPatternID int,
	@iModuleID int	,
	@dtStartdate datetime
)

AS
BEGIN TRY 
	DECLARE @iNoOfSessionsInModule INT
	DECLARE	@iSessionDayGap NUMERIC(8,2)
	DECLARE	@iNoOfSessions NUMERIC(8,2)

	DECLARE @iDays INT
	DECLARE @nDays NUMERIC(8,2)
	
		
	  SELECT @iNoOfSessionsInModule = 
	  COUNT(DISTINCT I_Session_ID) FROM dbo.T_Session_Module_Map
	  WHERE I_Module_ID = @iModuleID 
	  AND I_Status <> 0
	  AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())
      AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())
	
	SELECT @iSessionDayGap = N_Session_Day_Gap , @iNoOfSessions = I_No_Of_Session
	FROM dbo.T_Delivery_Pattern_Master
	WHERE I_Delivery_Pattern_ID = @iDeliveryPatternID
	

	SELECT @iDays = CONVERT(INT,(@iNoOfSessionsInModule*@iSessionDayGap*1.25)/@iNoOfSessions)
	SELECT @nDays = (@iNoOfSessionsInModule*@iSessionDayGap*1.25)/@iNoOfSessions
	IF @nDays>@iDays
		SET @iDays = @iDays + 1		
		SELECT DATEADD(day,@iDays,@dtStartdate)
	
END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [ACADEMICS].[uspCheckIfManualNoCompulsory]...';


GO
/*****************************************************************************************************************
Created by:		Swagata De
Date:			11/9/07
Description:	This Stored procedure is used to check if manual no is compulsory for a given course/term/module
Parameters:		
				
Returns:	
******************************************************************************************************************/

CREATE PROCEDURE [ACADEMICS].[uspCheckIfManualNoCompulsory] 
(   @iCourseID int,
	@iTermID int,
	@iModuleID int,
	@iCenterID int
	
)

AS
BEGIN 

	DECLARE @iManualNoCompulsory INT
	SET @iManualNoCompulsory = (SELECT TOP 1 I_Is_Manual_No_Compulsory FROM ACADEMICS.T_E_Project_Manual_Master WHERE 
	I_Center_ID = @iCenterID AND I_Course_ID = @iCourseID AND  I_Term_ID = @iTermID AND I_Module_ID = @iModuleID )

	IF @iManualNoCompulsory IS NULL
		BEGIN
		SET @iManualNoCompulsory = 1
		SELECT @iManualNoCompulsory
		END
	ELSE
		SELECT @iManualNoCompulsory
	
END
