CREATE PROCEDURE [ACADEMICS].[uspGetStudentListForAttendance] --[ACADEMICS].[uspGetStudentListForAttendance] 3,1,0,'2012-12-17 00:00:00.000'              
    (
      @iTimeTableID INT ,
      @iCenterID INT ,
      @iFlag INT ,
      @DtScheduleDate DATETIME = NULL            
    )
AS 
    BEGIN                
        DECLARE @iBatchID INT          
        DECLARE @iTermID INT           
        DECLARE @iModuleID INT          
        DECLARE @iSessionID INT
        DECLARE @iSub_Batch_ID INT =0
        DECLARE @iSubBatch_Name varchar(100)            
                 
        SELECT  @iBatchID = TTTM.I_Batch_ID ,
                @iTermID = TTM.I_Term_ID ,
                @iModuleID = TMM.I_Module_ID ,
                @iSessionID = TTTM.I_Session_ID,
                @iSub_Batch_ID= ISNULL(TTTM.I_Sub_Batch_ID,0) ,
                @iSubBatch_Name=TSB.S_Sub_Batch_Name 

        FROM    dbo.T_TimeTable_Master AS TTTM
                INNER JOIN dbo.T_Term_Master AS TTM ON TTM.I_Term_ID = TTTM.I_Term_ID
                INNER JOIN dbo.T_Module_Master AS TMM ON TMM.I_module_ID = TTTM.I_module_ID
                LEFT OUTER  JOIN T_Student_Sub_Batch_Master  TSB ON  ISNULL(TSB.I_Sub_Batch_ID,0)=ISNULL(TTTM.I_Sub_Batch_ID,0)   AND TSB.I_Status = 1 
        WHERE   TTTM.I_TimeTable_ID = @iTimeTableID
                AND TTTM.I_Status = 1
                AND TTM.I_Status = 1
                AND TMM.I_Status = 1         
                  
        DECLARE @iCourseID INT           
        SELECT  @iCourseID = I_Course_ID
        FROM    dbo.T_Student_Batch_Master
        WHERE   I_Batch_ID = @iBatchID          
            
               
        IF @iFlag = 1 
            BEGIN          
                SELECT DISTINCT
                        ISNULL(SBD.I_RollNo,SD.I_RollNo) AS I_RollNo ,
                        SD.I_Student_Detail_ID ,
                        SD.S_Student_ID ,
                        SD.S_First_Name ,
                        SD.S_Middle_Name ,
                        SD.S_Last_Name ,
                        @iCenterID AS I_Centre_Id ,
                        @iBatchID AS I_Batch_ID ,
                        IsOnLeave = CASE WHEN ISNULL(TSLR.I_Student_Leave_ID,
                                                     0) > 0 THEN 1
                                         ELSE 0
                                    END
                FROM    dbo.T_Student_Detail SD
                        INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID = SBD.I_Student_ID
                                                              AND SBD.I_Batch_ID = @iBatchID
                        INNER JOIN dbo.T_Student_Center_Detail SCD ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Term_Detail STD ON STD.I_Student_Detail_ID = SD.I_Student_Detail_ID
                                                              AND STD.I_Term_ID = @iTermID
                                                              AND SCD.I_Centre_Id = @iCenterID
                                                              AND SCD.I_Status = 1
                                                              AND STD.I_Is_Completed = 0
                                                              AND SBD.I_Status = 1
                        LEFT OUTER JOIN dbo.T_Student_Leave_Request AS TSLR ON SD.I_Student_Detail_ID = TSLR.I_Student_Detail_ID
                                                              AND TSLR.I_Status = 1
                                                              AND @DtScheduleDate BETWEEN TSLR.Dt_From_Date
                                                              AND
                                                              TSLR.Dt_To_Date 
                        WHERE SD.I_Status=1                                      
               ORDER BY ISNULL(SBD.I_RollNo,SD.I_RollNo) 
        
            END  
            ELSE IF @iFlag=2
            BEGIN
                      
           SELECT DISTINCT
                        ISNULL(SBD.I_RollNo,SD.I_RollNo) AS I_RollNo ,
                        SD.I_Student_Detail_ID ,
                        SD.S_Student_ID ,
                        SD.S_First_Name ,
                        SD.S_Middle_Name ,
                        SD.S_Last_Name ,
                        @iCenterID AS I_Centre_Id ,
                        @iTimeTableID AS I_Batch_ID ,
                        IsOnLeave = CASE WHEN ISNULL(TSLR.I_Student_Leave_ID,
                                                     0) > 0 THEN 1
                                         ELSE 0
                                    END
        
                FROM    dbo.T_Student_Detail SD
                        INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID = SBD.I_Student_ID
                                                           AND SBD.I_Batch_ID = @iTimeTableID
                        INNER JOIN dbo.T_Student_Center_Detail SCD ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Term_Detail STD ON STD.I_Student_Detail_ID = SD.I_Student_Detail_ID
                                                              AND SCD.I_Centre_Id = @iCenterID
                                                              AND SCD.I_Status = 1
                                                              AND STD.I_Is_Completed = 0
                                                              AND SBD.I_Status = 1
                        LEFT OUTER JOIN dbo.T_Student_Leave_Request AS TSLR ON SD.I_Student_Detail_ID = TSLR.I_Student_Detail_ID
                                                              AND TSLR.I_Status = 1
                        WHERE SD.I_Status=1                                      
                   

            END
            IF @iFlag = 3 
            BEGIN  
            IF @iSub_Batch_ID<>0
            BEGIN        
                SELECT DISTINCT
                        ISNULL(SBD.I_RollNo,SD.I_RollNo) AS I_RollNo ,
                        SD.I_Student_Detail_ID ,
                        SD.S_Student_ID ,
                        SD.S_First_Name ,
                        SD.S_Middle_Name ,
                        SD.S_Last_Name ,
                        @iCenterID AS I_Centre_Id ,
                        @iBatchID AS I_Batch_ID ,
                        IsOnLeave = CASE WHEN ISNULL(TSLR.I_Student_Leave_ID,
                                                     0) > 0 THEN 1
                                         ELSE 0
                                    END,
                         @iSub_Batch_ID as I_Sub_Batch_ID,
                         @iSubBatch_Name as S_Sub_Batch_Name  
                FROM    dbo.T_Student_Detail SD
                        INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID = SBD.I_Student_ID
                                                              AND SBD.I_Batch_ID = @iBatchID
                        INNER JOIN dbo.T_Student_Center_Detail SCD ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Term_Detail STD ON STD.I_Student_Detail_ID = SD.I_Student_Detail_ID
                                                              AND STD.I_Term_ID = @iTermID
                                                              AND SCD.I_Centre_Id = @iCenterID
                                                              AND SCD.I_Status = 1
                                                              AND STD.I_Is_Completed = 0
                                                              AND SBD.I_Status = 1
                        LEFT OUTER JOIN dbo.T_Student_Leave_Request AS TSLR ON SD.I_Student_Detail_ID = TSLR.I_Student_Detail_ID
                                                              AND TSLR.I_Status = 1
                                                          
                        INNER  JOIN T_Student_Sub_Batch_Master  TSB ON  SBD.I_Batch_ID=TSB.I_Batch_ID
                        INNER JOIN T_Student_Sub_Batch_Student_Mapping TSBM ON  TSBM.I_Sub_Batch_ID=TSB.I_Sub_Batch_ID AND TSBM.I_Status = 1
                        AND  TSBM.I_Student_Detail_ID = SD.I_Student_Detail_ID 
                        AND TSB.I_Sub_Batch_ID=@iSub_Batch_ID
                         AND TSB.I_Status = 1 
                         WHERE SD.I_Status=1                                  
       
               ORDER BY ISNULL(SBD.I_RollNo,SD.I_RollNo) 
               END
               ELSE
               BEGIN
                SELECT DISTINCT
                        ISNULL(SBD.I_RollNo,SD.I_RollNo) AS I_RollNo ,
                        SD.I_Student_Detail_ID ,
                        SD.S_Student_ID ,
                        SD.S_First_Name ,
                        SD.S_Middle_Name ,
                        SD.S_Last_Name ,
                        @iCenterID AS I_Centre_Id ,
                        @iBatchID AS I_Batch_ID ,
                        IsOnLeave = CASE WHEN ISNULL(TSLR.I_Student_Leave_ID,
                                                     0) > 0 THEN 1
                                         ELSE 0
                                    END,
                         @iSub_Batch_ID as I_Sub_Batch_ID,
                         @iSubBatch_Name as S_Sub_Batch_Name  
                FROM    dbo.T_Student_Detail SD
                        INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID = SBD.I_Student_ID
                                                              AND SBD.I_Batch_ID = @iBatchID
                        INNER JOIN dbo.T_Student_Center_Detail SCD ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Term_Detail STD ON STD.I_Student_Detail_ID = SD.I_Student_Detail_ID
                                                              AND STD.I_Term_ID = @iTermID
                                                              AND SCD.I_Centre_Id = @iCenterID
                                                              AND SCD.I_Status = 1
                                                              AND STD.I_Is_Completed = 0
                                                              AND SBD.I_Status = 1
                        LEFT OUTER JOIN dbo.T_Student_Leave_Request AS TSLR ON SD.I_Student_Detail_ID = TSLR.I_Student_Detail_ID
                                                              AND TSLR.I_Status = 1
                                                              --akash
                                                              AND (@DtScheduleDate BETWEEN TSLR.Dt_From_Date
                                                              AND
                                                              TSLR.Dt_To_Date)
                                                              --akash
                        LEFT OUTER  JOIN T_Student_Sub_Batch_Master  TSB ON  SBD.I_Batch_ID=TSB.I_Sub_Batch_ID
                        AND TSB.I_Sub_Batch_ID=@iSub_Batch_ID   AND TSB.I_Status = 1 
                        WHERE SD.I_Status=1                                   
       
               ORDER BY ISNULL(SBD.I_RollNo,SD.I_RollNo)
               END
        
            END
        ELSE 
            BEGIN          
                SELECT DISTINCT
                        ISNULL(SBD.I_RollNo,SD.I_RollNo) AS I_RollNo ,
                        SD.I_Student_Detail_ID ,
                        SD.S_Student_ID ,
                        SD.S_First_Name ,
                        SD.S_Middle_Name ,
                        SD.S_Last_Name ,
                        @iCenterID AS I_Centre_Id ,
                        SBD.I_Batch_ID,
                        IsOnLeave = CASE WHEN ISNULL(TSLR.I_Student_Leave_ID,
                                                     0) > 0 THEN 1
                                         ELSE 0
                                    END
                FROM    dbo.T_Student_Detail SD
                        INNER JOIN dbo.T_Student_Center_Detail SCD ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID = SBD.I_Student_ID
                                                              AND SBD.I_Status = 1
                                                              AND [SBD].[I_Batch_ID] <> @iBatchID
                        INNER JOIN dbo.T_Student_Batch_Master AS TSBM ON SBD.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Center_Batch_Details AS TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
                                                              AND TCBD.I_Centre_Id = @iCenterID
                        INNER JOIN dbo.T_Student_Term_Detail STD ON STD.I_Student_Detail_ID = SD.I_Student_Detail_ID
                                                              AND SCD.I_Centre_Id = @iCenterID
                                                              AND SCD.I_Status = 1
                                                              AND STD.I_Is_Completed = 0
                        LEFT OUTER JOIN dbo.T_Student_Leave_Request AS TSLR ON SD.I_Student_Detail_ID = TSLR.I_Student_Detail_ID
                                                              AND TSLR.I_Status = 1
                                                              AND (@DtScheduleDate BETWEEN TSLR.Dt_From_Date
                                                              AND
                                                              TSLR.Dt_To_Date) 
                WHERE   STD.I_Term_ID = ISNULL(@iTermID, STD.I_Term_ID)
                        AND TSBM.I_Course_ID = @iCourseID
                        AND TCBD.I_Status IN ( 4, 5, 6 )
                        AND SD.I_Status=1
                ORDER BY SBD.I_Batch_ID,ISNULL(SBD.I_RollNo,SD.I_RollNo)
            END    
    END
GO
PRINT N'Creating Procedure [ACADEMICS].[uspGetStudentList]...';


GO
/*****************************************************************************************************************
Created by: Debman Mukherjee
Date: 02/05/2007
Description:Gets the list of Students based CenterID, TimeSlotID, 
			CourseID, TermID, ModuleID, 
			TimeSlotFlag = 1 for fetching student based on the TimeSlot
			0 = for fetching student not in that TimeSlot
			2 = for ignoring the TimeSlot while fetching the student
Parameters: CenterID, TimeSlotID,CourseID, TermID, ModuleID,TimeSlotFlag
Returns:	
Modified By: 
******************************************************************************************************************/

CREATE PROCEDURE [ACADEMICS].[uspGetStudentList]
(
	@iCenterID int,
	@iTimeSlotID int,
	@iCourseID int,
	@iTermID int,
	@iModuleID int,
	@iSessionID int,
	@iTimeSlotFlag int
)
AS

BEGIN

IF @iTimeSlotFlag=0

SELECT SD.I_Student_Detail_ID,
	   SD.S_Student_ID,
	   SD.S_First_Name,
	   SD.S_Middle_Name,
	   SD.S_Last_Name
FROM T_Student_Course_Detail SCD
INNER JOIN T_Student_Module_Detail SMD 
ON SCD.I_Student_Detail_ID = SMD.I_Student_Detail_ID
INNER JOIN T_Student_Detail SD
ON SCD.I_Student_Detail_ID = SD.I_Student_Detail_ID
LEFT JOIN T_Student_Attendance_Details SAD WITH(NOLOCK)
ON SCD.I_Student_Detail_ID = SAD.I_Student_Detail_ID
AND SCD.I_Course_ID = SAD.I_Course_ID
AND SCD.I_Course_ID = SMD.I_Course_ID
AND SCD.I_Course_ID = @iCourseID
AND SCD.I_TimeSlot_ID <> @iTimeSlotID
AND SCD.I_Status <> 0
AND SCD.I_Is_Completed = 0
AND SMD.I_Module_ID = @iModuleID
AND SMD.I_Term_ID = @iTermID
AND SMD.I_Is_Completed = 0
AND SAD.I_Module_ID = @iModuleID
AND SAD.I_Term_ID = @iTermID 
AND SAD.I_Session_ID = @iSessionID 
AND SD.I_Status<>0

ELSE IF @iTimeSlotFlag=1

SELECT SD.I_Student_Detail_ID,
	   SD.S_Student_ID,
	   SD.S_First_Name,
	   SD.S_Middle_Name,
	   SD.S_Last_Name
FROM T_Student_Course_Detail SCD
INNER JOIN T_Student_Module_Detail SMD 
ON SCD.I_Student_Detail_ID = SMD.I_Student_Detail_ID
INNER JOIN T_Student_Detail SD
ON SCD.I_Student_Detail_ID = SD.I_Student_Detail_ID
LEFT JOIN T_Student_Attendance_Details SAD WITH(NOLOCK)
ON SCD.I_Student_Detail_ID = SAD.I_Student_Detail_ID
AND SCD.I_Course_ID = SAD.I_Course_ID
AND SCD.I_Course_ID = SMD.I_Course_ID
AND SCD.I_Course_ID = @iCourseID
AND SCD.I_TimeSlot_ID = @iTimeSlotID
AND SCD.I_Status <> 0
AND SMD.I_Module_ID = @iModuleID
AND SMD.I_Term_ID = @iTermID
AND SCD.I_Is_Completed = 0
AND SMD.I_Is_Completed = 0
AND SAD.I_Module_ID = @iModuleID
AND SAD.I_Term_ID = @iTermID 
AND SAD.I_Session_ID = @iSessionID 
AND SD.I_Status<>0

ELSE IF @iTimeSlotFlag=2

SELECT SD.I_Student_Detail_ID,
	   SD.S_Student_ID,
	   SD.S_First_Name,
	   SD.S_Middle_Name,
	   SD.S_Last_Name
FROM T_Student_Course_Detail SCD
INNER JOIN T_Student_Module_Detail SMD
ON SCD.I_Student_Detail_ID = SMD.I_Student_Detail_ID
INNER JOIN T_Student_Detail SD
ON SCD.I_Student_Detail_ID = SD.I_Student_Detail_ID
LEFT JOIN T_Student_Attendance_Details SAD WITH(NOLOCK)
ON SCD.I_Student_Detail_ID = SAD.I_Student_Detail_ID
AND SCD.I_Course_ID = SAD.I_Course_ID
AND SCD.I_Course_ID = SMD.I_Course_ID
AND SCD.I_Course_ID = @iCourseID
AND SCD.I_Status <> 0
AND SMD.I_Module_ID = @iModuleID
AND SMD.I_Term_ID = @iTermID
AND SCD.I_Is_Completed = 0
AND SMD.I_Is_Completed = 0
AND SAD.I_Module_ID = @iModuleID
AND SAD.I_Term_ID = @iTermID 
AND SAD.I_Session_ID = @iSessionID 
AND SD.I_Status<>0

END
GO
PRINT N'Creating Procedure [ACADEMICS].[uspGetTrainingDetails]...';


GO
/*****************************************************************************************************************
Created by: Soumya Sikder
Date:15/06/2007
Description:Gets the list of Training Details for a particular training id
Parameters: TrainingId
******************************************************************************************************************/
CREATE PROCEDURE [ACADEMICS].[uspGetTrainingDetails]
(
	@iTrainingId int,
	@CurrentDate datetime
)
AS

BEGIN TRY 

	DECLARE @iTDMasterID INT
	
	-- Select TD Master ID from the system
	SELECT @iTDMasterID = I_Hierarchy_Master_ID
	FROM dbo.T_Hierarchy_Master
	WHERE S_Hierarchy_Type = 'RH'
	AND I_Status = 1

	-- Select list of finally approved faculty
	SELECT
		TC.I_Training_ID,
		TC.S_Training_Name,
		TC.Dt_Training_Date,
		TC.Dt_Training_End_Date,
		TC.S_Description,
		TC.S_Venue,
		TC.I_Status,
		TC.I_Document_ID,
		TC.I_User_ID,
		UM.S_Login_ID,
		UM.S_Title,
		UM.S_First_Name,
		UM.S_Middle_Name,
		UM.S_Last_Name,
		UM.S_Email_ID,
		UM.S_User_Type,
		UD.S_Document_Name,
		UD.S_Document_Type,
		UD.S_Document_Path,
		UD.S_Document_URL,
		UHD.I_Hierarchy_Detail_ID
	FROM Academics.T_Training_Calendar TC 
	INNER JOIN dbo.T_User_Master UM WITH(NOLOCK)
	ON TC.I_User_ID = UM.I_User_ID
	LEFT OUTER JOIN dbo.T_Upload_Document UD
	ON TC.I_Document_ID = UD.I_Document_ID
	AND UD.I_Status = 1
	LEFT OUTER JOIN dbo.T_User_Hierarchy_Details UHD
	ON TC.I_User_ID = UHD.I_User_ID
	AND UHD.I_Hierarchy_Master_ID = @iTDMasterID
	AND UHD.I_Status = 1
	AND @CurrentDate >= ISNULL(UHD.Dt_Valid_From, @CurrentDate)
	AND @CurrentDate <= ISNULL(UHD.Dt_Valid_To, @CurrentDate)
	WHERE TC.I_Training_ID = @iTrainingId
	--AND TC.I_Status <> 2
	AND UM.I_Status = 1

	--table 2
	SELECT T.I_Training_ID,
		   S.I_Skill_ID,
		   S.S_Skill_Desc,
		   S.S_Skill_No,
		   S.S_Skill_Type,
		   S.I_Status
	FROM ACADEMICS.T_Training_Skill T
	INNER JOIN dbo.T_EOS_Skill_Master S
	ON T.I_Skill_ID = S.I_Skill_ID
	WHERE T.I_Training_ID = @iTrainingId
	AND S.I_Status = 1
		
END TRY
BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
