CREATE PROCEDURE [ACADEMICS].[uspModifyConcernArea] 
(
	@iVisitID int,
	@iConcernAreaID int = null,
	@sDescription varchar(2000) = null,
	@iAssignedEmpID int,
	@dTargetDate datetime = null,
	@dActualDate datetime = null,
	@sUser varchar(20),
	@dDate datetime,
	@iFlag int
)
AS

BEGIN TRY 
	-- Inserting New Records in the table
	if(@iFlag = 1)
	BEGIN
		
		BEGIN TRAN T1

		INSERT INTO ACADEMICS.T_Concern_Areas
		(
			I_Academics_Visit_ID,
			S_Description,
			I_Assigned_EmpID,
			Dt_Target_Date,
			S_Crtd_By,
			Dt_Crtd_On
		)
		VALUES
		(
			@iVisitID,
			@sDescription,
			@iAssignedEmpID,
			@dTargetDate,
			@sUser,
			@dDate
		)

		SET @iConcernAreaID = SCOPE_IDENTITY()

		COMMIT TRAN T1

	END

	-- Updating Records in the Table
	if(@iFlag = 2)
	BEGIN

		BEGIN TRAN T2

		UPDATE ACADEMICS.T_Concern_Areas
