GO
CREATE PROCEDURE [ASSESSMENT].[uspGetStudentAssessmentMarksDetails]  --338347           
(            
 @iEnquiryID INT                
)            
AS                   
BEGIN     
    
SELECT * INTO #temp1    
  FROM    
   (SELECT tsam.I_Enquiry_Regn_ID,tpam.I_PreAssessment_ID,tpam.S_PreAssessment_Name,tecm.I_Exam_Component_ID,tecm.S_Component_Name,tecm.I_Exam_Type_Master_ID,tetm.S_Exam_Type_Name FROM ASSESSMENT.T_Student_Assessment_Map AS tsam    
INNER JOIN ASSESSMENT.T_PreAssessment_Master AS tpam    
ON tsam.I_PreAssessment_ID = tpam.I_PreAssessment_ID    
INNER JOIN dbo.T_Exam_Component_Master AS tecm    
ON  tsam.I_Exam_Component_ID=tecm.I_Exam_Component_ID    
INNER JOIN dbo.T_Exam_Type_Master AS tetm    
ON tecm.I_Exam_Type_Master_ID = tetm.I_Exam_Type_Master_ID    
WHERE tsam.I_Enquiry_Regn_ID = @iEnquiryID    
AND B_Is_Complete =1  
) T1    
        
      --SELECT * FROM #temp1 AS t1    
  
SELECT * INTO #temp2    
FROM    
(    
		SELECT I_Exam_Component_ID AS ECompId,N_Marks FROM EOS.T_Employee_Exam_Result AS teer  
		WHERE I_Enquiry_Regn_ID = @iEnquiryID 
		AND I_Exam_Component_ID IN (SELECT I_Exam_Component_ID from #temp1 WHERE I_Enquiry_Regn_ID = @iEnquiryID )
 ) T2    
      
      
      
  --SELECT * FROM #temp2 AS t2    
      
SELECT * INTO #temp3             
 FROM              
  (    
  SELECT I_Exam_Component_ID ,        
        SUM(I_Value) AS Rating FROM STUDENTFEATURES.T_Student_Feedback AS tsf        
INNER JOIN STUDENTFEATURES.T_Student_Feedback_Details AS tsfd        
ON tsf.I_Student_Feedback_ID = tsfd.I_Student_Feedback_ID        
INNER JOIN ACADEMICS.T_Feedback_Option_Master AS tfom        
ON tsfd.I_Feedback_Option_Master_ID = tfom.I_Feedback_Option_Master_ID        
INNER JOIN ACADEMICS.T_Feedback_Master AS tfm        
ON tfom.I_Feedback_Master_ID = tfm.I_Feedback_Master_ID        
WHERE I_Enquiry_Regn_ID =  @iEnquiryID    
group BY I_Enquiry_Regn_ID,I_Exam_Component_ID) T3        
    
--SELECT * FROM #temp3 AS t3    
    
 SELECT * INTO #tempMarks           
  FROM    
  (    
    SELECT *  FROM #temp1 AS t1     
    LEFT OUTER JOIN #temp2 AS t2    
    ON t1.I_Exam_Component_ID = t2.ECompId    
     
  ) AS T4    
      
 ---SELECT * FROM #tempMarks    
     
     
   SELECT I_Enquiry_Regn_ID,I_PreAssessment_ID,S_PreAssessment_Name,tm1.I_Exam_Component_ID,S_Component_Name,I_Exam_Type_Master_ID,S_Exam_Type_Name,N_Marks,Rating from #tempMarks  AS tm1    
   LEFT OUTER JOIN #temp3 AS t3    
   ON tm1.I_Exam_Component_ID = t3.I_Exam_Component_ID    
      
      
  DROP TABLE #tempMarks        
  DROP TABLE #temp3    
  DROP TABLE #temp2    
  DROP TABLE #temp1    

      
  END
GO
PRINT N'Creating Procedure [ASSESSMENT].[uspGetWorkflowHierarchyForAssessment]...';


GO
CREATE PROCEDURE [ASSESSMENT].[uspGetWorkflowHierarchyForAssessment]      
AS     
BEGIN    
 SELECT A.I_Assessment_Rule_Map_ID ,    
   A.I_PreAssessment_ID ,    
   C.S_PreAssessment_Name,    
   A.I_Rule_ID ,    
   B.S_Rule_Name,    
   A.S_Evaluated_True_Category ,    
   A.I_Evaluated_True_Assessment_ID ,    
   D.S_PreAssessment_Name AS S_Evaluated_True_Assessment_Name,    
   A.I_Evaluated_True_CourseList_ID,     
   dbo.fnGetCourseNameList(A.I_Evaluated_True_CourseList_ID) AS S_Evaluated_True_CourseNames, 
   A.I_Evaluated_True_Rule_ID,   
   TRM.S_Rule_Name AS S_Evaluated_True_Rule_Name,
   A.S_Evaluated_False_Category ,    
   A.I_Evaluated_False_Assessment_ID ,    
   H.S_PreAssessment_Name AS S_Evaluated_False_Assessment_Name,    
   A.I_Evaluated_False_CourseList_ID,    
   dbo.fnGetCourseNameList(A.I_Evaluated_False_CourseList_ID) AS S_Evaluated_False_CourseNames,
   A.I_Evaluated_False_Rule_ID,
   TRM2.S_Rule_Name AS S_Evaluated_False_Rule_Name    
  FROM ASSESSMENT.T_Assessment_Rule_Workflow A    
  INNER JOIN ASSESSMENT.T_Rule_Master B    
  ON A.I_Rule_ID = B.I_Rule_ID    
  INNER JOIN ASSESSMENT.T_PreAssessment_Master C    
  ON A.I_PreAssessment_ID = C.I_PreAssessment_ID    
  LEFT OUTER JOIN ASSESSMENT.T_PreAssessment_Master D    
  ON A.I_Evaluated_True_Assessment_ID = D.I_PreAssessment_ID    
  LEFT OUTER JOIN ASSESSMENT.T_Rule_CourseList_Map E    
  ON A.I_Evaluated_True_CourseList_ID = E.I_CourseList_ID   
  LEFT OUTER JOIN ASSESSMENT.T_Rule_Master AS TRM
  ON A.I_Evaluated_True_Rule_ID = TRM.I_Rule_ID 
  LEFT OUTER JOIN ASSESSMENT.T_PreAssessment_Master H    
  ON A.I_Evaluated_False_Assessment_ID = H.I_PreAssessment_ID    
  LEFT OUTER JOIN ASSESSMENT.T_Rule_CourseList_Map I    
  ON A.I_Evaluated_False_CourseList_ID = I.I_CourseList_ID  
  LEFT OUTER JOIN ASSESSMENT.T_Rule_Master AS TRM2
  ON A.I_Evaluated_False_Rule_ID = TRM2.I_Rule_ID  
  WHERE A.I_Status = 1    
END
GO
PRINT N'Creating Procedure [ASSESSMENT].[uspSaveAssessmentWorkflow]...';


GO
CREATE PROCEDURE [ASSESSMENT].[uspSaveAssessmentWorkflow]              
(            
 @iAssessmentID int,            
 @iRuleID INT,            
 @sEvaluatedTrueCategory varchar(20),            
 @iEvaluatedTrueAssessmentID INT = NULL,            
 @sEvaluatedTrueCourseListXML varchar(MAX) = NULL,        
 @iEvaluatedTrueRuleID INT = NULL,    
 @sEvaluatedFalseCategory VARCHAR(20),            
 @iEvaluatedFalseAssessmentID INT = NULL,            
 @sEvaluatedFalseCourseListXML varchar(MAX) = NULL,    
 @iEvaluatedFalseRuleID INT = NULL,           
 @iStatus int,            
 @sCrtdBy varchar(20) = NULL,            
 @sUpdtBy VARCHAR(20) = NULL,            
 @dtCrtdOn DATETIME = NULL,            
 @dtUpdtOn DATETIME = NULL             
)            
AS             
BEGIN TRY            
  DECLARE @iEvaluatedTrueCourseListID INT,@iEvaluatedFalseCourseListID INT            
              
  BEGIN TRANSACTION            
            
  IF(@sEvaluatedTrueCategory = 'ASSESSMENT')          
  BEGIN          
 IF NOT EXISTS(SELECT * FROM ASSESSMENT.T_Assessment_Rule_Workflow AS tarw WHERE tarw.I_PreAssessment_ID = @iEvaluatedTrueAssessmentID AND I_Status = 1)          
  BEGIN          
   RAISERROR          
     (N'The workflow for the selected assessment(s) is not complete. Please complete the workflow for the selected assessment test.',          
     16,          
     1);          
  END          
  END           
  ELSE IF(@sEvaluatedFalseCategory = 'ASSESSMENT')          
  BEGIN          
 IF NOT EXISTS(SELECT * FROM ASSESSMENT.T_Assessment_Rule_Workflow AS tarw WHERE tarw.I_PreAssessment_ID = @iEvaluatedFalseAssessmentID AND I_Status = 1)          
  BEGIN          
   RAISERROR          
     (N'The workflow for the selected assessment(s) is not complete. Please complete the workflow for the selected assessment test.',          
     16,          
     1);          
  END          
  END     
      
  IF(@sEvaluatedTrueCategory = 'RULE')          
  BEGIN          
 IF NOT EXISTS(SELECT * FROM ASSESSMENT.T_Assessment_Rule_Workflow AS tarw WHERE tarw.I_Rule_ID = @iEvaluatedTrueRuleID)          
   BEGIN          
    RAISERROR          
   (N'The workflow for the selected rule is not complete. Please complete the workflow for the selected rule.',          
   16,          
   1);          
   END          
  END          
  ELSE IF(@sEvaluatedFalseCategory = 'RULE')          
  BEGIN          
  IF NOT EXISTS(SELECT * FROM ASSESSMENT.T_Assessment_Rule_Workflow AS tarw WHERE tarw.I_Rule_ID = @iEvaluatedFalseRuleID)          
   BEGIN          
    RAISERROR          
   (N'The workflow for the selected rule is not complete. Please complete the workflow for the selected rule.',          
   16,          
   1);          
 END          
  END     
            
  UPDATE ASSESSMENT.T_Assessment_Rule_Workflow SET I_Status = 0,S_Updt_By = @sUpdtBy,Dt_Updt_On = @dtUpdtOn            
  WHERE I_PreAssessment_ID = @iAssessmentID AND I_Rule_ID = @iRuleID AND I_Status = 1            
              
  declare @xml_hndl int            
  IF(@sEvaluatedTrueCourseListXML IS NOT NULL)            
  BEGIN            
              
  UPDATE ASSESSMENT.T_Rule_CourseList_Map             
  SET I_Status = 0,S_Updt_By = @sUpdtBy,Dt_Updt_On = @dtUpdtOn            
  WHERE I_Rule_ID = @iRuleID AND I_Status = 1 AND B_Is_Evaluated_True = 1            
              
  INSERT INTO ASSESSMENT.T_Rule_CourseList_Map            
          ( I_Rule_ID ,            
            B_Is_Evaluated_True,            
            I_Status ,            
            S_Crtd_By ,            
            Dt_Crtd_On            
          )            
  VALUES  ( @iRuleID , -- I_Rule_ID - int            
            1 , -- I_Status - int            
            1,            
            @sCrtdBy , -- S_Crtd_By - varchar(20)            
            @dtCrtdOn -- Dt_Crtd_On - datetime            
          )            
              
  SELECT @iEvaluatedTrueCourseListID = @@IDENTITY            
              
  exec sp_xml_preparedocument @xml_hndl OUTPUT, @sEvaluatedTrueCourseListXML            
  INSERT INTO ASSESSMENT.T_Assessment_CourseList_Course_Map            
          ( I_Course_List_ID, I_Course_ID )            
   SELECT                
            @iEvaluatedTrueCourseListID,CourseID            
  FROM            
            OPENXML(@xml_hndl, '/Root/Course', 1)                
            With                
                        (                
       CourseID int '@ID'                
                        )                
                  
  END            
  IF(@sEvaluatedFalseCourseListXML IS NOT NULL)            
  BEGIN            
              
  UPDATE ASSESSMENT.T_Rule_CourseList_Map             
  SET I_Status = 0,S_Updt_By = @sUpdtBy,Dt_Updt_On = @dtUpdtOn            
  WHERE I_Rule_ID = @iRuleID AND I_Status = 1 AND B_Is_Evaluated_True = 0            
              
  INSERT INTO ASSESSMENT.T_Rule_CourseList_Map            
          ( I_Rule_ID ,            
      B_Is_Evaluated_True,            
            I_Status ,            
            S_Crtd_By ,            
            Dt_Crtd_On            
          )            
  VALUES  ( @iRuleID , -- I_Rule_ID - int            
            0 , -- I_Status - int            
            1,            
            @sCrtdBy , -- S_Crtd_By - varchar(20)            
            @dtCrtdOn -- Dt_Crtd_On - datetime            
          )            
             
  SELECT @iEvaluatedFalseCourseListID = @@IDENTITY            
              
  exec sp_xml_preparedocument @xml_hndl OUTPUT, @sEvaluatedFalseCourseListXML            
  INSERT INTO ASSESSMENT.T_Assessment_CourseList_Course_Map            
          ( I_Course_List_ID, I_Course_ID )            
   SELECT                
            @iEvaluatedFalseCourseListID,CourseID            
  FROM            
            OPENXML(@xml_hndl, '/Root/Course', 1)                
            With                
                        (                
       CourseID int '@ID'                
                       )                
                  
  END            
              
  INSERT INTO ASSESSMENT.T_Assessment_Rule_Workflow            
          ( I_PreAssessment_ID ,            
            I_Rule_ID ,            
            S_Evaluated_True_Category ,            
            I_Evaluated_True_Assessment_ID ,            
            I_Evaluated_True_CourseList_ID ,      
            I_Evaluated_True_Rule_ID ,          
            S_Evaluated_False_Category ,            
            I_Evaluated_False_Assessment_ID ,            
            I_Evaluated_False_CourseList_ID ,      
            I_Evaluated_False_Rule_ID ,          
            I_Status ,            
            S_Crtd_By ,            
            Dt_Crtd_On            
          )            
  VALUES  ( @iAssessmentID , -- I_PreAssessment_ID - int            
            @iRuleID , -- I_Rule_ID - int            
            @sEvaluatedTrueCategory , -- S_Evaluated_True_Category - varchar(20)            
            @iEvaluatedTrueAssessmentID , -- I_Evaluated_True_Assessment_ID - int            
            @iEvaluatedTrueCourseListID , -- I_Evaluated_True_CourseList_ID - int     
            @iEvaluatedTrueRuleID ,           
            @sEvaluatedFalseCategory , -- S_Evaluated_False_Category - varchar(20)            
            @iEvaluatedFalseAssessmentID , -- I_Evaluated_False_Assessment_ID - int            
            @iEvaluatedFalseCourseListID , -- I_Evaluated_False_CourseList_ID - int            
            @iEvaluatedFalseRuleID ,    
            1 , -- I_Status - int            
            @sCrtdBy , -- S_Crtd_By - varchar(20)            
            @dtCrtdOn  -- Dt_Crtd_On - datetime            
          )            
   COMMIT TRANSACTION            
END TRY             
BEGIN CATCH            
 --Error occurred:              
 ROLLBACK TRANSACTION            
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int            
 SELECT @ErrMsg = ERROR_MESSAGE(),            
   @ErrSeverity = ERROR_SEVERITY()            
            
 RAISERROR(@ErrMsg, @ErrSeverity, 1)            
END CATCH
