AND TAS.I_Status_ID = COALESCE(@iStatusAudit,TAS.[I_Status_ID]) 
AND TAS.I_User_ID =COALESCE(@iUserID,TAS.I_User_ID)    


SELECT I_Audit_Schedule_ID,Dt_Audit_Date FROM AUDIT.T_Audit_Schedule_Details 
