/*
-- =================================================================
-- Author:Sanjay Mitra
-- Create date:10/07/2007 
-- Description: Select From  [T_Audit_Schedule] used in GetCenterAuditDetails Method in AuditBuilder
-- =================================================================
*/
CREATE PROCEDURE [AUDIT].[uspGetScheduleDetail] 
(
		@iAuditScheduleID INT = 0		
)

AS
BEGIN

	SET NOCOUNT OFF;

	SELECT 
	   ISNULL([I_Audit_Schedule_ID],'') AS I_Audit_Schedule_ID
      ,ISNULL(AdtSeche.[I_Center_ID],'') AS I_Center_ID
      ,ISNULL(AdtSeche.[Dt_Audit_On],getDAte()) AS Dt_Audit_On
      ,ISNULL(AdtSeche.[I_User_ID],'') AS I_User_ID
      ,ISNULL(AdtSeche.[I_Audit_Type_ID],'') AS I_Audit_Type_ID
	  ,ISNULL(AudtType.[S_Audit_Type_Code],'') AS S_Audit_Type_Code
      ,ISNULL(AdtSeche.[I_Status_ID],'') AS I_Status_ID
      ,ISNULL(AdtSeche.[S_Crtd_By],'') AS S_Crtd_By
      ,ISNULL(AdtSeche.[S_Upd_By],'') AS S_Upd_By
      ,ISNULL(AdtSeche.[Dt_Crtd_On],getDAte()) AS Dt_Crtd_On
      ,ISNULL(AdtSeche.[Dt_Upd_On],getDAte()) AS Dt_Upd_On
      ,ISNULL(Center.[S_Center_Name],'') AS S_Center_Name
      ,ISNULL(_User.[S_Login_ID],'') AS S_Login_ID
	FROM  [AUDIT].[T_Audit_Schedule] AdtSeche
	
	LEFT JOIN [AUDIT].[T_Audit_Type] AudtType
	ON AdtSeche.[I_Audit_Type_ID] = AudtType.[I_Audit_Type_ID]
	LEFT JOIN dbo.[T_Centre_Master] Center
	ON AdtSeche.[I_Center_ID] = Center.[I_Centre_Id]
	LEFT JOIN dbo.[T_User_Master] _User
	ON AdtSeche.[I_User_ID] = _User.I_User_ID


	WHERE 
	AdtSeche.[I_Audit_Schedule_ID] =  @iAuditScheduleID
		
END
GO
PRINT N'Creating Procedure [AUDIT].[uspRequestListForNCRClosed]...';


GO
--sp_helptext '[AUDIT].[uspRequestListForNCRClosed]'  
  ---[AUDIT].[uspRequestListForNCRClosed] NULL,'01/Jan/2011','31/Mar/2011',1,3,0,NULL,2,1178
  
CREATE PROCEDURE [AUDIT].[uspRequestListForNCRClosed]     
(    
  @iCenterID  INT   = NULL ,    
  @dtFromDate  DATETIME = NULL  ,    
  @dtToDate  DATETIME = NULL  ,    
  @iFlag INT        ,   
  @iStatusAudit INT =NULL    ,   
  @iStatusChangeRequest INT =0   ,   
  @iAuditScheduleType  INT = NULL,    
  @iBrandID INT = NULL,  
  @iHierarchyDetailID INT = NULL,
  @iUserID INT = NULL
)    
  
AS    
BEGIN    
    IF @iFlag =1    
     BEGIN    
		   SELECT DISTINCT  ISNULL(ADS.[I_Audit_Schedule_ID],'') AS I_Audit_Schedule_ID  
			 ,ISNULL(ADS.[I_Center_ID],'') AS I_Center_ID    
			 ,ISNULL(Center.[S_Center_Name],'') AS S_Center_Name    
			 ,ISNULL(ADS.[Dt_Audit_On],getDAte()) AS Dt_Audit_On    
			 ,0 AS I_Status_ID    
			FROM [AUDIT].[T_Audit_Schedule] ADS
		    
		   INNER JOIN [AUDIT].[T_Audit_Result] ARSLT    
		   ON ADS.[I_Audit_Schedule_ID] = ARSLT.[I_Audit_Schedule_ID] 
		   INNER JOIN  AUDIT.T_Audit_Result_NCR ANCR 
		   ON ANCR.I_Audit_Result_ID = ARSLT.I_Audit_Result_ID   
		   INNER JOIN dbo.[T_Centre_Master] Center    
		   ON ADS.[I_Center_ID] = Center.[I_Centre_Id]
		   INNER JOIN dbo.[T_User_Master] UserTbl    
		   ON ADS.[I_User_ID] = UserTbl.[I_User_ID]
		   INNER JOIN dbo.T_Brand_Center_Details BCD    
		   ON BCD.I_Centre_Id  = Center.[I_Centre_Id]       
		     
		   WHERE     
		   ADS.[I_Center_ID] IN (SELECT I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@iHierarchyDetailID, @iBrandID))
		   AND    
		   ADS.[Dt_Audit_On] >= COALESCE(@dtFromDate,ADS.[Dt_Audit_On])    
		   AND     
		   ADS.[Dt_Audit_On] <= COALESCE(@dtToDate,ADS.[Dt_Audit_On])    
		   AND    
		   ANCR.[I_Status_ID] = COALESCE(@iStatusAudit,ANCR.[I_Status_ID])    
		   AND     
		   BCD.I_Brand_ID = COALESCE(@iBrandID,BCD.I_Brand_ID)     
		   AND 
		   UserTbl.I_User_ID = COALESCE(@iUserID,UserTbl.I_User_ID)    
		   ORDER BY S_Center_Name
		   
		   
		   
		   SELECT I_Audit_Schedule_ID,Dt_Audit_Date FROM AUDIT.T_Audit_Schedule_Details 
		   WHERE  I_Audit_Schedule_ID IN
		   (  
			 SELECT  DISTINCT ADS.[I_Audit_Schedule_ID]
		     FROM [AUDIT].[T_Audit_Schedule] ADS
		     INNER JOIN [AUDIT].[T_Audit_Result] ARSLT    
		     ON ADS.[I_Audit_Schedule_ID] = ARSLT.[I_Audit_Schedule_ID] 
		     INNER JOIN  AUDIT.T_Audit_Result_NCR ANCR 
		     ON ANCR.I_Audit_Result_ID = ARSLT.I_Audit_Result_ID   
		     INNER JOIN dbo.[T_Centre_Master] Center    
		     ON ADS.[I_Center_ID] = Center.[I_Centre_Id]
		     INNER JOIN dbo.[T_User_Master] UserTbl    
		     ON ADS.[I_User_ID] = UserTbl.[I_User_ID]
		     INNER JOIN dbo.T_Brand_Center_Details BCD    
		     ON BCD.I_Centre_Id  = Center.[I_Centre_Id]       
			   WHERE     
			   ADS.[I_Center_ID] IN (SELECT I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@iHierarchyDetailID, @iBrandID))
			   AND    
			   ADS.[Dt_Audit_On] >= COALESCE(@dtFromDate,ADS.[Dt_Audit_On])    
			   AND     
			   ADS.[Dt_Audit_On] <= COALESCE(@dtToDate,ADS.[Dt_Audit_On])    
			   AND    
			   ANCR.[I_Status_ID] = COALESCE(@iStatusAudit,ANCR.[I_Status_ID])    
			   AND     
			   BCD.I_Brand_ID = COALESCE(@iBrandID,BCD.I_Brand_ID)     
			   AND 
			   UserTbl.I_User_ID = COALESCE(@iUserID,UserTbl.I_User_ID)    
		   )
   
       END
       
       
       
       
   IF @iFlag =2    
     BEGIN    
		   SELECT DISTINCT  ISNULL(ADS.[I_Audit_Schedule_ID],'') AS I_Audit_Schedule_ID  
			 ,ISNULL(ADS.[I_Center_ID],'') AS I_Center_ID    
			 ,ISNULL(Center.[S_Center_Name],'') AS S_Center_Name    
			 ,ISNULL(ADS.[Dt_Audit_On],getDAte()) AS Dt_Audit_On    
			 ,0 AS I_Status_ID    
			FROM [AUDIT].[T_Audit_Schedule] ADS
		    
		   INNER JOIN [AUDIT].[T_Audit_Result] ARSLT    
		   ON ADS.[I_Audit_Schedule_ID] = ARSLT.[I_Audit_Schedule_ID] 
		   INNER JOIN  AUDIT.T_Audit_Result_NCR ANCR 
		   ON ANCR.I_Audit_Result_ID = ARSLT.I_Audit_Result_ID   
		   INNER JOIN dbo.[T_Centre_Master] Center    
		   ON ADS.[I_Center_ID] = Center.[I_Centre_Id]
		   INNER JOIN dbo.[T_User_Master] UserTbl    
		   ON ADS.[I_User_ID] = UserTbl.[I_User_ID]
		   INNER JOIN dbo.T_Brand_Center_Details BCD    
		   ON BCD.I_Centre_Id  = Center.[I_Centre_Id]       
		     
		   WHERE     
		   ADS.[I_Center_ID] IN (SELECT I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@iHierarchyDetailID, @iBrandID))
		   AND    
		   ADS.[Dt_Audit_On] >= COALESCE(@dtFromDate,ADS.[Dt_Audit_On])    
		   AND     
		   ADS.[Dt_Audit_On] <= COALESCE(@dtToDate,ADS.[Dt_Audit_On])    
		   AND    
		   ANCR.[I_Status_ID] != COALESCE(@iStatusAudit,ANCR.[I_Status_ID])    
		   AND     
		   BCD.I_Brand_ID = COALESCE(@iBrandID,BCD.I_Brand_ID)     
		   AND 
		   UserTbl.I_User_ID = COALESCE(@iUserID,UserTbl.I_User_ID)
		   AND [ARSLT].[I_Audit_Result_ID] NOT IN
				(SELECT DISTINCT TARN.[I_Audit_Result_ID] FROM [AUDIT].[T_Breach_Notice_NCR] AS TBNN
				INNER JOIN [AUDIT].[T_Audit_Result_NCR] AS TARN ON [TBNN].[I_Audit_Report_NCR_ID] = [TARN].[I_Audit_Report_NCR_ID])
				
		   ORDER BY S_Center_Name
		   
		   
		   
		   SELECT I_Audit_Schedule_ID,Dt_Audit_Date FROM AUDIT.T_Audit_Schedule_Details 
		   WHERE  I_Audit_Schedule_ID IN
		   (  
			 SELECT  DISTINCT ADS.[I_Audit_Schedule_ID]
		     FROM [AUDIT].[T_Audit_Schedule] ADS
		     INNER JOIN [AUDIT].[T_Audit_Result] ARSLT    
		     ON ADS.[I_Audit_Schedule_ID] = ARSLT.[I_Audit_Schedule_ID] 
		     INNER JOIN  AUDIT.T_Audit_Result_NCR ANCR 
		     ON ANCR.I_Audit_Result_ID = ARSLT.I_Audit_Result_ID   
		     INNER JOIN dbo.[T_Centre_Master] Center    
		     ON ADS.[I_Center_ID] = Center.[I_Centre_Id]
		     INNER JOIN dbo.[T_User_Master] UserTbl    
		     ON ADS.[I_User_ID] = UserTbl.[I_User_ID]
		     INNER JOIN dbo.T_Brand_Center_Details BCD    
		     ON BCD.I_Centre_Id  = Center.[I_Centre_Id]       
			   WHERE     
			   ADS.[I_Center_ID] IN (SELECT I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@iHierarchyDetailID, @iBrandID))
			   AND    
			   ADS.[Dt_Audit_On] >= COALESCE(@dtFromDate,ADS.[Dt_Audit_On])    
			   AND     
			   ADS.[Dt_Audit_On] <= COALESCE(@dtToDate,ADS.[Dt_Audit_On])    
			   AND    
			   ANCR.[I_Status_ID] != COALESCE(@iStatusAudit,ANCR.[I_Status_ID])    
			   AND     
			   BCD.I_Brand_ID = COALESCE(@iBrandID,BCD.I_Brand_ID)     
			   AND 
			   UserTbl.I_User_ID = COALESCE(@iUserID,UserTbl.I_User_ID)
			   AND [ARSLT].[I_Audit_Result_ID] NOT IN
				(SELECT DISTINCT TARN.[I_Audit_Result_ID] FROM [AUDIT].[T_Breach_Notice_NCR] AS TBNN
				INNER JOIN [AUDIT].[T_Audit_Result_NCR] AS TARN ON [TBNN].[I_Audit_Report_NCR_ID] = [TARN].[I_Audit_Report_NCR_ID])
		   )   
       END
       
   END
GO
PRINT N'Creating Procedure [AUDIT].[uspUpdateAuditRescheduleRequest]...';


GO
/*
-- =================================================================
-- Author:Babin SAha
-- Create date:07/09/2007 
-- Description:Update Schedule Request Into  [AUDIT].T_Schedule_Change_Request 
-- =================================================================
*/
CREATE PROCEDURE [AUDIT].[uspUpdateAuditRescheduleRequest]
(
		@iScheduleChangeRequestID	INT	,
		--@iFlag INT						,	-- @iFlag=2 Reject | @iFlag=1 Approve
		@iStatusAudit INT				,	--  Schedule = 1,ReScheduleRequested = 2,Visited = 3,Evaluated = 4
		@iStatusChangeRequest	INT		,	--Requested = 1,Approved = 2,Reject = 3 
											--*Note If @iFlag=2 Then it Must
		@Remarks VARCHAR(2000)		,
		@RequestUpdated VARCHAR(20)		,
		@RequestUpdateOn DATETIME		,
		@AuditScheduleUpdated VARCHAR(20),
		@AuditScheduleUpdateOn DATETIME
)

AS
BEGIN TRY
-- APPROVE Reschedule Request
IF @iStatusChangeRequest =2 
BEGIN
DECLARE @iAuditScheduleID_EXIST INT
,@dtRequestedDate DATETIME
SET @iAuditScheduleID_EXIST = 0
		IF EXISTS (SELECT I_Audit_Schedule_ID FROM [AUDIT].[T_schedule_change_request] WHERE I_Schedule_Change_Request_ID = @iScheduleChangeRequestID)
		BEGIN
			SELECT @iAuditScheduleID_EXIST=I_Audit_Schedule_ID FROM [AUDIT].[T_schedule_change_request] WHERE I_Schedule_Change_Request_ID = @iScheduleChangeRequestID
		END
DECLARE @iAuditScheduleHistoryID INT
SET @iAuditScheduleHistoryID = 0 
		IF @iAuditScheduleID_EXIST <> 0
		BEGIN	
			BEGIN TRANSACTION Tran_Adt_History
					-- Make a backup of Audit Schedule  in T_Audit_Schedule_History Table
					INSERT INTO [AUDIT].T_Audit_Schedule_History
							(	
							I_Audit_Schedule_ID	,
							I_Center_ID			,
							Dt_Audit_On			,
							I_User_ID			,
							I_Audit_Type_ID		,
							I_Status_ID			,
							S_Crtd_By			, 
							S_Upd_By			, 
							Dt_Crtd_On			, 
							Dt_Upd_On		 
							)
						
					SELECT I_Audit_Schedule_ID	,
							I_Center_ID			,
							Dt_Audit_On			,
							I_User_ID			,
							I_Audit_Type_ID		,
							I_Status_ID			,
							S_Crtd_By			, 
							S_Upd_By			, 
							Dt_Crtd_On			, 
							Dt_Upd_On	
					FROM [AUDIT].T_Audit_Schedule
					WHERE I_Audit_Schedule_ID = @iAuditScheduleID_EXIST
					
					--Get Current Entry AuditScheduleHistoryID
					SET @iAuditScheduleHistoryID = SCOPE_IDENTITY();
					IF (@iAuditScheduleHistoryID>0)
						BEGIN
							IF EXISTS(SELECT Dt_Requested_Date FROM [AUDIT].[T_schedule_change_request] WHERE I_Schedule_Change_Request_ID=@iScheduleChangeRequestID)
							BEGIN
								--Updates status to APPROVE in T_schedule_change_request
								UPDATE [AUDIT].[T_schedule_change_request]
								SET I_Status_ID = @iStatusChangeRequest ,S_Upd_By = @RequestUpdated ,Dt_Upd_On = @RequestUpdateOn,S_Remarks=@Remarks
								WHERE I_Schedule_Change_Request_ID = @iScheduleChangeRequestID
								
								--Get Changed Audit Date
								SELECT @dtRequestedDate=Dt_Requested_Date FROM [AUDIT].[T_schedule_change_request] WHERE I_Schedule_Change_Request_ID=@iScheduleChangeRequestID
								
								--Update T_Audit_Schedule
								UPDATE [AUDIT].T_Audit_Schedule
								SET  Dt_Audit_On  =	@dtRequestedDate ,I_Status_ID = @iStatusAudit	
								,S_Upd_By = @AuditScheduleUpdated ,Dt_Upd_On=@AuditScheduleUpdateOn
								WHERE I_Audit_Schedule_ID = @iAuditScheduleID_EXIST
								
								DELETE FROM AUDIT.T_Audit_Schedule_Details WHERE
								I_Audit_Schedule_ID = @iAuditScheduleID_EXIST
								
								INSERT INTO AUDIT.T_Audit_Schedule_Details
	                            ( 
	                              I_Audit_Schedule_ID ,
	                              Dt_Audit_Date
	                             )
	                            SELECT SCR.I_Audit_Schedule_ID,SCRD.Dt_Audit_Date FROM AUDIT.T_Schedule_Change_Request SCR
								INNER JOIN [AUDIT].T_Schedule_Change_Request_Details SCRD
								ON SCR.I_Schedule_Change_Request_ID = SCRD.I_Schedule_Change_Request_ID
								WHERE SCR.I_Schedule_Change_Request_ID=@iScheduleChangeRequestID
								
								COMMIT TRANSACTION Tran_Adt_History
							END
							ELSE
								BEGIN
									ROLLBACK TRANSACTION Tran_Adt_History
								END
						END
					ELSE
						BEGIN
							ROLLBACK TRANSACTION Tran_Adt_History
						END
					
		END 

END

IF @iStatusChangeRequest =3
BEGIN
	--Updates status to REJECT in T_schedule_change_request
	UPDATE [AUDIT].[T_schedule_change_request]
	SET I_Status_ID = 3,S_Remarks= @Remarks 
	WHERE I_Schedule_Change_Request_ID = @iScheduleChangeRequestID

	DECLARE @iAuditScheduleID_CHK INT
	SET @iAuditScheduleID_CHK =  (SELECT I_Audit_Schedule_ID FROM [AUDIT].[T_schedule_change_request] 
							 WHERE I_Schedule_Change_Request_ID = @iScheduleChangeRequestID)
	


	UPDATE AUDIT.T_Audit_Schedule
	SET I_Status_ID = 1 
	WHERE I_Audit_Schedule_ID = @iAuditScheduleID_CHK

END
END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
