PRINT N'Creating Procedure [ECOMMERCE].[uspActivateDeactivateProduct]...';


GO
CREATE procedure [ECOMMERCE].[uspActivateDeactivateProduct]
(
	@ProductID INT,
	@Flag BIT
)
AS
BEGIN

BEGIN TRY
	BEGIN TRANSACTION

		IF(@Flag=0)
		BEGIN

			IF EXISTS
			(
				select * from ECOMMERCE.T_Plan_Product_Map A
				inner join ECOMMERCE.T_Plan_Master B on A.PlanID=B.PlanID
				where
				B.IsPublished=1 and CONVERT(DATE,ISNULL(ValidTo,GETDATE()))>=CONVERT(DATE,GETDATE()) and B.StatusID=1
				and A.ProductID=@ProductID and A.StatusID=1
			)
			BEGIN

				RAISERROR('Product is attached to published plans. Cannot be deactivated.',11,1)

			END
			ELSE
			BEGIN

				UPDATE ECOMMERCE.T_Product_Master set IsPublished=@Flag where ProductID=@ProductID and StatusID=1

			END

		END
		ELSE
		BEGIN

			UPDATE ECOMMERCE.T_Product_Master set IsPublished=@Flag where ProductID=@ProductID and StatusID=1

		END

	COMMIT TRANSACTION
END TRY
BEGIN CATCH
--Error occurred:  
    ROLLBACK TRANSACTION
    DECLARE @ErrMsg NVARCHAR(4000) ,
        @ErrSeverity INT
    SELECT  @ErrMsg = ERROR_MESSAGE() ,
            @ErrSeverity = ERROR_SEVERITY()

    RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH

END
GO
PRINT N'Creating Procedure [ECOMMERCE].[uspCheckBatchAvailability]...';


GO
CREATE procedure [ECOMMERCE].[uspCheckBatchAvailability]
AS
BEGIN


	select DISTINCT A.*,G.RegID,G.FirstName,ISNULL(G.MiddleName,'') as MiddleName,G.LastName,B.ProductName,C.PlanName,B.BrandID
	from 
	ECOMMERCE.T_Batch_Availability_Notification A
	inner join ECOMMERCE.T_Product_Master B on A.ProductID=B.ProductID
	inner join ECOMMERCE.T_Plan_Master C on A.PlanID=C.PlanID
	inner join T_Student_Batch_Master D on B.CourseID=D.I_Course_ID
	inner join T_Center_Batch_Details E on A.CenterID=E.I_Centre_Id and D.I_Batch_ID=E.I_Batch_ID
	inner join T_Course_Master F on B.CourseID=F.I_Course_ID
	inner join ECOMMERCE.T_Registration G on A.CustomerID=G.CustomerID
	where
	D.Dt_BatchStartDate>=CONVERT(DATE,GETDATE()) and A.NotifiedOn IS NULL and A.StatusID=1



END
GO
