            )
        
        CREATE TABLE #tempTaxAmountGST
            (
              I_Invoice_Detail_ID INT ,
              Amount_Paid DECIMAL(14, 2) ,
              Tax_Amount DECIMAL(14, 2) ,
		
            )

        INSERT  INTO #temp
                ( I_Invoice_Child_Header_ID ,
                  S_Mobile_No ,
                  S_Student_ID ,
                  I_Roll_No ,
                  S_Student_Name ,
                  S_Invoice_No ,
                  Dt_Invoice_Date ,
                  I_Fee_Component_ID ,
                  S_Component_Name ,
                  S_Batch_Name ,
                  S_Course_Name ,
                  I_Center_ID ,
                  S_Center_Name ,
                  TypeofCentre ,
                  S_Brand_Name ,
                  S_Cost_Center ,
                  Due_Value ,
                  Dt_Installment_Date ,
                  I_Installment_No ,
                  I_Parent_Invoice_ID ,
                  I_Invoice_Detail_ID ,
                  Revised_Invoice_Date ,
                  Tax_Value ,
                  Total_Value ,
                  Amount_Paid ,
                  Tax_Paid ,
                  Total_Paid ,
                  Total_Due ,
                  IsGSTImplemented ,
                  I_Invoice_Header_ID
                )
                SELECT  B.I_Invoice_Child_Header_ID ,
                        E.S_Mobile_No ,
                        S_Student_ID ,
                        E.I_RollNo ,
                        E.S_First_Name + ' ' + ISNULL(S_Middle_Name, '') + ' '
                        + S_Last_Name AS S_Student_Name ,
                        A.S_Invoice_No ,
                        A.Dt_Invoice_Date ,
                        C.I_Fee_Component_ID ,
                        S_Component_Name ,
                        tsbm.S_Batch_Name ,
                        tcm.S_Course_Name ,
                        tcm2.I_Centre_Id ,
                        tcm2.S_Center_Name ,
                        CASE WHEN tcm2.S_Center_Code LIKE 'IAS T%' THEN 'IAS'
                             WHEN tcm2.S_Center_Code LIKE 'Judiciary T%'
                             THEN 'Judiciary'
                             WHEN tcm2.S_Center_Code = 'BRST' THEN 'AIPT'
                             WHEN tcm2.S_Center_Code LIKE 'FR-%'
                             THEN 'Franchise'
                             ELSE 'Own'
                        END AS TypeofCentre ,
                        S_Brand_Name ,
                        S_Cost_Center ,
                        ISNULL(C.N_Due, ISNULL(C.N_Amount_Due,0)) Due_Value ,
                        Dt_Installment_Date ,
                        I_Installment_No ,
                        A.I_Parent_Invoice_ID ,
                        C.I_Invoice_Detail_ID ,
                        CASE WHEN I_Parent_Invoice_ID IS NULL THEN NULL
                             ELSE A.Dt_Crtd_On
                        END AS Revised_Invoice_Date ,
                        ISNULL(SUM(ROUND(F.N_Tax_Value, 2)), 0) Tax_Value ,
                        ISNULL(C.N_Due, ISNULL(C.N_Amount_Due,0))
                        + ISNULL(SUM(ROUND(F.N_Tax_Value, 2)), 0) AS Total_Value ,
                        0.00 ,
                        0.00 ,
                        0.00 ,
                        0.00 ,
                        CASE WHEN DATEDIFF(dd, '2017-07-01',
                                           Dt_Installment_Date) >= 0 THEN 1
                             ELSE 0
                        END ,
                        A.I_Invoice_Header_ID
                FROM    T_Invoice_Parent A
                        INNER JOIN T_Invoice_Child_Header B ON A.I_Invoice_Header_ID = B.I_Invoice_Header_ID
                                                      --AND A.I_Status IN (1,3,2 )
                        INNER JOIN #tempinvoice ON #tempinvoice.I_Invoice_Header_ID = A.I_Invoice_Header_ID
                        INNER JOIN T_Invoice_Child_Detail C ON C.I_Invoice_Child_Header_ID = B.I_Invoice_Child_Header_ID
				------ Raj ----
                                                              AND ( A.I_Status IN (
                                                              1, 3, 2 )
                                                              OR ( A.I_Status = 0
                                                              AND C.I_Invoice_Detail_ID IN (
                                                              SELECT
                                                              tc.I_Invoice_Detail_ID
                                                              FROM
                                                              T_Receipt_Component_Detail
                                                              AS tc --Inner Join T_Receipt_Header as th on tc.I_Receipt_Detail_ID=th.I_Receipt_Header_ID and th.I_Status=0 and C.Dt_Installment_Date<th.Dt_Upd_On))
                                                              INNER JOIN T_Receipt_Header
                                                              AS th ON tc.I_Receipt_Detail_ID = th.I_Receipt_Header_ID --and th.I_Status=0 
				 --and (C.Dt_Installment_Date<A.Dt_Upd_On and C.Dt_Installment_Date<th.Dt_Upd_On)
                                                              AND ( ( C.Dt_Installment_Date < A.Dt_Upd_On
                                                              AND C.Dt_Installment_Date < th.Dt_Upd_On
                                                              )
                                                              OR ( C.Dt_Installment_Date > A.Dt_Upd_On )
                                                              ) 
				 --and ((CASE WHEN C.Dt_Installment_Date>=th.Dt_Upd_On Then C.Dt_Installment_Date ELSE th.Dt_Upd_On END)>='2017-07-01')
                                                              AND ( ( ( CASE
                                                              WHEN C.Dt_Installment_Date >= th.Dt_Upd_On
                                                              THEN C.Dt_Installment_Date
                                                              ELSE th.Dt_Upd_On
                                                              END ) >= '2017-07-01' )
                                                              OR ( ( CASE
                                                              WHEN A.Dt_Upd_On >= th.Dt_Upd_On
                                                              THEN A.Dt_Upd_On
                                                              ELSE th.Dt_Upd_On
                                                              END ) >= '2017-07-01' )
                                                              )
                                                              AND tc.I_Invoice_Detail_ID NOT IN (
                                                              SELECT
                                                              I_Invoice_Detail_ID
                                                              FROM
                                                              T_Credit_Note_Invoice_Child_Detail ) )
                                                              )
                                                              )
				------ Raj ----
                        INNER JOIN T_Fee_Component_Master D ON D.I_Fee_Component_ID = C.I_Fee_Component_ID
                                                              AND D.I_Status = 1
                        INNER JOIN T_Student_Detail E ON E.I_Student_Detail_ID = A.I_Student_Detail_ID
                        INNER JOIN dbo.T_Centre_Master AS tcm2 ON A.I_Centre_Id = tcm2.I_Centre_Id
                        INNER JOIN dbo.T_Brand_Center_Details AS tbcd ON tcm2.I_Centre_Id = tbcd.I_Centre_Id
                        INNER JOIN dbo.T_Brand_Master AS tbm ON tbcd.I_Brand_ID = tbm.I_Brand_ID
                        OUTER APPLY ( SELECT TOP 1
                                                tsbd.I_Student_Batch_ID ,
                                                tsbd.I_Status ,
                                                tsbd.I_Batch_ID
                                      FROM      dbo.T_Student_Batch_Details AS tsbd
                                      WHERE     tsbd.I_Student_ID = A.I_Student_Detail_ID
                                                AND tsbd.I_Status IN ( 1, 2 )
                                      ORDER BY  tsbd.I_Student_Batch_ID DESC
                                    ) tsbd
                        LEFT JOIN dbo.T_Student_Batch_Master AS tsbm ON tsbm.I_Batch_ID = tsbd.I_Batch_ID
                        LEFT JOIN dbo.T_Course_Master AS tcm ON tcm.I_Course_ID = tsbm.I_Course_ID
                        LEFT JOIN T_Invoice_Detail_Tax F ON F.I_Invoice_Detail_ID = C.I_Invoice_Detail_ID
                WHERE   A.I_Centre_Id IN (
                        SELECT  fnCenter.centerID
                        FROM    fnGetCentersForReports(@sHierarchyList,
                                                       @iBrandID) fnCenter )
                        AND DATEDIFF(dd, @dtUptoDate, Dt_Installment_Date) <= 0
                        AND E.I_Status = ISNULL(@StudentStatus, E.I_Status)
                        AND ISNULL(C.Flag_IsAdvanceTax, 'N') <> 'Y'
                        AND E.S_Student_ID = @sStdID
						AND A.I_Invoice_Header_ID=@FeeScheduleID
                GROUP BY B.I_Invoice_Child_Header_ID ,
                        S_Student_ID ,
                        E.S_Mobile_No ,
                        E.I_RollNo ,
                        A.S_Invoice_No ,
                        A.Dt_Invoice_Date ,
                        C.I_Fee_Component_ID ,
                        S_Component_Name ,
                        ISNULL(C.N_Due, ISNULL(C.N_Amount_Due,0)) ,
                        Dt_Installment_Date ,
                        I_Installment_No ,
                        A.I_Parent_Invoice_ID ,
                        A.Dt_Crtd_On ,
                        C.I_Invoice_Detail_ID ,
                        tsbm.S_Batch_Name ,
                        tcm.S_Course_Name ,
                        tcm2.I_Centre_Id ,
                        tcm2.S_Center_Name ,
                        CASE WHEN tcm2.S_Center_Code LIKE 'IAS T%' THEN 'IAS'
                             WHEN tcm2.S_Center_Code LIKE 'Judiciary T%'
                             THEN 'Judiciary'
                             WHEN tcm2.S_Center_Code = 'BRST' THEN 'AIPT'
                             WHEN tcm2.S_Center_Code LIKE 'FR-%'
                             THEN 'Franchise'
                             ELSE 'Own'
                        END ,
                        S_Brand_Name ,
                        S_Cost_Center ,
                        E.S_First_Name ,
                        E.S_Middle_Name ,
                        E.S_Last_Name ,
                        CASE WHEN DATEDIFF(dd, '2017-07-01',
                                           Dt_Installment_Date) >= 0 THEN 1
                             ELSE 0
                        END ,
                        A.I_Invoice_Header_ID
        
        INSERT  INTO #tempTaxAmountGST
                ( I_Invoice_Detail_ID ,
                  Amount_Paid ,
                  Tax_Amount
		        )
                SELECT  A.I_Invoice_Detail_ID ,
                        Amount_Paid ,
                        ISNULL(Tax_Amount, 0) AS Tax_Amount
                FROM    ( SELECT    RCD.I_Invoice_Detail_ID ,
                                    SUM(N_Amount_Paid) AS Amount_Paid
                          FROM      T_Receipt_Component_Detail RCD
                                    INNER JOIN T_Receipt_Header RH ON RCD.I_Receipt_Detail_ID = RH.I_Receipt_Header_ID
                                    INNER JOIN #temp T ON RCD.I_Invoice_Detail_ID = T.I_Invoice_Detail_ID
                                                          AND IsGSTImplemented = 1
                                                          AND DATEDIFF(dd,
                                                              '2017-07-01',
                                                              T.Dt_Installment_Date) >= 0
                                                          AND RH.I_Status = 1
                          GROUP BY  RCD.I_Invoice_Detail_ID
                        ) A
                        LEFT JOIN ( SELECT  RCD.I_Invoice_Detail_ID ,
                                            SUM(N_Tax_Paid) AS Tax_Amount
                                    FROM    T_Receipt_Tax_Detail RTD
                                            INNER JOIN T_Receipt_Component_Detail RCD ON RTD.I_Receipt_Comp_Detail_ID = RCD.I_Receipt_Comp_Detail_ID
                                            INNER JOIN T_Receipt_Header RH ON RCD.I_Receipt_Detail_ID = RH.I_Receipt_Header_ID
                                            INNER JOIN #temp T ON RCD.I_Invoice_Detail_ID = T.I_Invoice_Detail_ID
                                                              AND DATEDIFF(dd,
                                                              '2017-07-01',
                                                              T.Dt_Installment_Date) >= 0
                                                              AND RH.I_Status = 1
                                    GROUP BY RCD.I_Invoice_Detail_ID
                                  ) xx ON A.I_Invoice_Detail_ID = xx.I_Invoice_Detail_ID

		
        UPDATE  #temp
        SET     Tax_Value = ( CASE WHEN ( tmp.Due_Value
                                          - ISNULL(tmtaxAmt.Amount_Paid, 0) ) < 1
                                   THEN tmtaxAmt.Tax_Amount
                                   ELSE tmtaxAmt.Tax_Amount
                                        + ( SELECT  dbo.fnGetTaxAmtOnDue(tmp.I_Fee_Component_ID,
                                                              tmp.Dt_Installment_Date,
                                                              ( tmp.Due_Value
                                                              - ISNULL(tmtaxAmt.Amount_Paid,
                                                              0) ))
                                          )
                              END )
        FROM    #temp AS tmp
                INNER JOIN #tempTaxAmountGST AS tmtaxAmt ON tmp.I_Invoice_Detail_ID = tmtaxAmt.I_Invoice_Detail_ID

        UPDATE  #temp
        SET     Total_Value = ISNULL(Due_Value, 0) + ISNULL(Tax_Value, 0)
		  
        UPDATE  T1
        SET     T1.Amount_Paid = ISNULL(ROUND(T2.Amount_Paid, 2), 0)
        FROM    #temp T1
                INNER JOIN ( SELECT A.I_Invoice_Detail_ID ,
                                    SUM(N_Amount_Paid) Amount_Paid
                             FROM   T_Receipt_Component_Detail A
                                    INNER JOIN dbo.T_Receipt_Header AS trh ON A.I_Receipt_Detail_ID = trh.I_Receipt_Header_ID
                                                              AND ( I_Status <> 0
                                                              OR ( I_Status = 0
                                                              AND DATEDIFF(dd,
                                                              @dtUptoDate,
                                                              trh.Dt_Upd_On) > 0
                                                              )
                                                              )
                                                              AND DATEDIFF(dd,
                                                              Dt_Receipt_Date,
                                                              @dtUptoDate) >= 0
                                    INNER JOIN #temp T ON T.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
                             GROUP BY A.I_Invoice_Detail_ID
                           ) T2 ON T1.I_Invoice_Detail_ID = T2.I_Invoice_Detail_ID
                           
        UPDATE  T1
        SET     T1.Total_Paid = ISNULL(T1.Amount_Paid, 0)
                + ROUND(ISNULL(T2.N_Tax_Paid, 0), 2) ,
                T1.Tax_Paid = ROUND(ISNULL(T2.N_Tax_Paid, 0), 2)
        FROM    #temp T1
                INNER JOIN ( SELECT A.I_Invoice_Detail_ID ,
                                    SUM(ISNULL(trtd.N_Tax_Paid, 0)) N_Tax_Paid
                             FROM   T_Receipt_Component_Detail A
                                    INNER JOIN dbo.T_Receipt_Header AS trh ON A.I_Receipt_Detail_ID = trh.I_Receipt_Header_ID
                                                              AND ( I_Status <> 0
                                                              OR ( I_Status = 0
                                                              AND DATEDIFF(dd,
                                                              @dtUptoDate,
                                                              trh.Dt_Upd_On) > 0
                                                              )
                                                              )
                                                              AND DATEDIFF(dd,
                                                              Dt_Receipt_Date,
                                                              @dtUptoDate) >= 0
                                    INNER JOIN #temp T ON T.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
                                    LEFT OUTER JOIN dbo.T_Receipt_Tax_Detail
                                    AS trtd ON A.I_Receipt_Comp_Detail_ID = trtd.I_Receipt_Comp_Detail_ID
                             GROUP BY A.I_Invoice_Detail_ID
                           ) T2 ON T1.I_Invoice_Detail_ID = T2.I_Invoice_Detail_ID
                           
