        INSERT  INTO #temphistory
                ( I_Invoice_Child_Header_ID ,
                  S_Mobile_No ,
                  S_Student_ID ,
                  I_Roll_No ,
                  S_Student_Name ,
                  S_Invoice_No ,
                  Dt_Invoice_Date ,
                  I_Fee_Component_ID ,
                  S_Component_Name ,
                  S_Batch_Name ,
                  S_Course_Name ,
                  I_Center_ID ,
                  S_Center_Name ,
                  TypeofCentre ,
                  S_Brand_Name ,
                  S_Cost_Center ,
                  Due_Value ,
                  Dt_Installment_Date ,
                  I_Installment_No ,
                  I_Parent_Invoice_ID ,
                  I_Invoice_Detail_ID ,
                  Revised_Invoice_Date ,
                  Tax_Value ,
                  Total_Value ,
                  Amount_Paid ,
                  Tax_Paid ,
                  Total_Paid ,
                  Total_Due ,
                  IsGSTImplemented ,
                  I_Invoice_Header_ID
                )
                SELECT  B.I_Invoice_Child_Header_ID ,
                        E.S_Mobile_No ,
                        S_Student_ID ,
                        E.I_RollNo ,
                        E.S_First_Name + ' ' + ISNULL(S_Middle_Name, '') + ' '
                        + S_Last_Name AS S_Student_Name ,
                        A.S_Invoice_No ,
                        A.Dt_Invoice_Date ,
                        C.I_Fee_Component_ID ,
                        S_Component_Name ,
                        tsbm.S_Batch_Name ,
                        tcm.S_Course_Name ,
                        tcm2.I_Centre_Id ,
                        tcm2.S_Center_Name ,
                        CASE WHEN tcm2.S_Center_Code LIKE 'IAS T%' THEN 'IAS'
                             WHEN tcm2.S_Center_Code LIKE 'Judiciary T%'
                             THEN 'Judiciary'
                             WHEN tcm2.S_Center_Code = 'BRST' THEN 'AIPT'
                             WHEN tcm2.S_Center_Code LIKE 'FR-%'
                             THEN 'Franchise'
                             ELSE 'Own'
                        END AS TypeofCentre ,
                        --TypeofCentre,
                        S_Brand_Name ,
                        S_Cost_Center ,
                        ISNULL(C.N_Due, ISNULL(C.N_Amount_Due,0)) Due_Value ,
                        Dt_Installment_Date ,
                        I_Installment_No ,
                        A.I_Parent_Invoice_ID ,
                        C.I_Invoice_Detail_ID ,
                        CASE WHEN I_Parent_Invoice_ID IS NULL THEN NULL
                             ELSE A.Dt_Crtd_On
                        END AS Revised_Invoice_Date ,
                        ISNULL(SUM(ROUND(F.N_Tax_Value, 2)), 0) Tax_Value ,
                        ISNULL(C.N_Due, ISNULL(C.N_Amount_Due,0))
                        + ISNULL(SUM(ROUND(F.N_Tax_Value, 2)), 0) AS Total_Value ,
                        0.00 ,
                        0.00 ,
                        0.00 ,
                        0.00 ,
                        CASE WHEN DATEDIFF(dd, '2017-07-01',
                                           Dt_Installment_Date) >= 0 THEN 1
                             ELSE 0
                        END ,
                        A.I_Invoice_Header_ID
                FROM    T_Invoice_Parent A
                        INNER JOIN T_Invoice_Child_Header B ON A.I_Invoice_Header_ID = B.I_Invoice_Header_ID
                                                              AND A.I_Status = 0
                        INNER JOIN #tempinvoice ON #tempinvoice.I_Invoice_Header_ID = A.I_Invoice_Header_ID
                        INNER JOIN T_Invoice_Child_Detail C ON C.I_Invoice_Child_Header_ID = B.I_Invoice_Child_Header_ID
						-------- Raj ----
						--AND (A.I_Status IN (1,3,2 )
						--OR 
						--(A.I_Status=0 and C.I_Invoice_Detail_ID in(Select I_Invoice_Detail_ID From T_Receipt_Component_Detail as tc 
						-- Inner Join T_Receipt_Header as th on tc.I_Receipt_Detail_ID=th.I_Receipt_Header_ID and th.I_Status=0 and C.Dt_Installment_Date<th.Dt_Upd_On))
						--)
						-------- Raj ----
                        INNER JOIN T_Fee_Component_Master D ON D.I_Fee_Component_ID = C.I_Fee_Component_ID
                                                              AND D.I_Status = 1
                        INNER JOIN T_Student_Detail E ON E.I_Student_Detail_ID = A.I_Student_Detail_ID
                        INNER JOIN dbo.T_Centre_Master AS tcm2 ON A.I_Centre_Id = tcm2.I_Centre_Id
                        INNER JOIN dbo.T_Brand_Center_Details AS tbcd ON tcm2.I_Centre_Id = tbcd.I_Centre_Id
                        INNER JOIN dbo.T_Brand_Master AS tbm ON tbcd.I_Brand_ID = tbm.I_Brand_ID
                        OUTER APPLY ( SELECT TOP 1
                                                tsbd.I_Student_Batch_ID ,
                                                tsbd.I_Status ,
                                                tsbd.I_Batch_ID
                                      FROM      dbo.T_Student_Batch_Details AS tsbd
                                      WHERE     tsbd.I_Student_ID = A.I_Student_Detail_ID
                                                AND tsbd.I_Status IN ( 1, 2 )
                                      ORDER BY  tsbd.I_Student_Batch_ID DESC
                                    ) tsbd
                        LEFT JOIN dbo.T_Student_Batch_Master AS tsbm ON tsbm.I_Batch_ID = tsbd.I_Batch_ID
                        LEFT JOIN dbo.T_Course_Master AS tcm ON tcm.I_Course_ID = tsbm.I_Course_ID
                        LEFT JOIN T_Invoice_Detail_Tax F ON F.I_Invoice_Detail_ID = C.I_Invoice_Detail_ID
                WHERE   A.I_Centre_Id IN (
                        SELECT  fnCenter.centerID
                        FROM    fnGetCentersForReports(@sHierarchyList,
                                                       @iBrandID) fnCenter )
                        AND DATEDIFF(dd, @dtUptoDate, Dt_Installment_Date) <= 0
                        AND E.I_Status = ISNULL(@StudentStatus, E.I_Status)
                        AND DATEDIFF(dd, @dtUptoDate, A.Dt_Upd_On) > 0
                        AND ISNULL(C.Flag_IsAdvanceTax, 'N') <> 'Y'
                        AND E.S_Student_ID = @sStdID
						AND A.I_Invoice_Header_ID=@FeeScheduleID
                GROUP BY B.I_Invoice_Child_Header_ID ,
                        S_Student_ID ,
                        E.S_Mobile_No ,
                        E.I_RollNo ,
                        A.S_Invoice_No ,
                        A.Dt_Invoice_Date ,
                        C.I_Fee_Component_ID ,
                        S_Component_Name ,
                        ISNULL(C.N_Due, ISNULL(C.N_Amount_Due,0)) ,
                        Dt_Installment_Date ,
                        I_Installment_No ,
                        A.I_Parent_Invoice_ID ,
                        A.Dt_Crtd_On ,
                        C.I_Invoice_Detail_ID ,
                        tsbm.S_Batch_Name ,
                        tcm.S_Course_Name ,
                        tcm2.I_Centre_Id ,
                        tcm2.S_Center_Name ,
                        CASE WHEN tcm2.S_Center_Code LIKE 'IAS T%' THEN 'IAS'
                             WHEN tcm2.S_Center_Code LIKE 'Judiciary T%'
                             THEN 'Judiciary'
                             WHEN tcm2.S_Center_Code = 'BRST' THEN 'AIPT'
                             WHEN tcm2.S_Center_Code LIKE 'FR-%'
                             THEN 'Franchise'
                             ELSE 'Own'
                        END ,
                        S_Brand_Name ,
                        S_Cost_Center ,
                        E.S_First_Name ,
                        E.S_Middle_Name ,
                        E.S_Last_Name ,
                        CASE WHEN DATEDIFF(dd, '2017-07-01',
                                           Dt_Installment_Date) >= 0 THEN 1
                             ELSE 0
                        END ,
                        A.I_Invoice_Header_ID
		
        DELETE  FROM #tempTaxAmountGST
					
        INSERT  INTO #tempTaxAmountGST
                ( I_Invoice_Detail_ID ,
                  Amount_Paid ,
                  Tax_Amount
		        )
                SELECT  A.I_Invoice_Detail_ID ,
                        Amount_Paid ,
                        ISNULL(Tax_Amount, 0) AS Tax_Amount
                FROM    ( SELECT    RCD.I_Invoice_Detail_ID ,
                                    SUM(N_Amount_Paid) AS Amount_Paid
                          FROM      T_Receipt_Component_Detail RCD
                                    INNER JOIN T_Receipt_Header RH ON RCD.I_Receipt_Detail_ID = RH.I_Receipt_Header_ID
                                    INNER JOIN #temphistory T ON RCD.I_Invoice_Detail_ID = T.I_Invoice_Detail_ID
                                                              AND IsGSTImplemented = 1
                                                              AND DATEDIFF(dd,
                                                              '2017-07-01',
                                                              T.Dt_Installment_Date) >= 0
                                                              AND RH.I_Status = 1
                          GROUP BY  RCD.I_Invoice_Detail_ID
                        ) A
                        LEFT JOIN ( SELECT  RCD.I_Invoice_Detail_ID ,
                                            SUM(N_Tax_Paid) AS Tax_Amount
                                    FROM    T_Receipt_Tax_Detail RTD
                                            INNER JOIN T_Receipt_Component_Detail RCD ON RTD.I_Receipt_Comp_Detail_ID = RCD.I_Receipt_Comp_Detail_ID
                                            INNER JOIN T_Receipt_Header RH ON RCD.I_Receipt_Detail_ID = RH.I_Receipt_Header_ID
                                            INNER JOIN #temphistory T ON RCD.I_Invoice_Detail_ID = T.I_Invoice_Detail_ID
                                                              AND DATEDIFF(dd,
                                                              '2017-07-01',
                                                              T.Dt_Installment_Date) >= 0
                                                              AND RH.I_Status = 1
                                    GROUP BY RCD.I_Invoice_Detail_ID
                                  ) xx ON A.I_Invoice_Detail_ID = xx.I_Invoice_Detail_ID
		
        UPDATE  #temphistory
        SET     Tax_Value = ( CASE WHEN ( tmp.Due_Value
                                          - ISNULL(tmtaxAmt.Amount_Paid, 0) ) < 1
                                   THEN tmtaxAmt.Tax_Amount
                                   ELSE tmtaxAmt.Tax_Amount
                                        + ( SELECT  dbo.fnGetTaxAmtOnDue(tmp.I_Fee_Component_ID,
                                                              tmp.Dt_Installment_Date,
                                                              ( tmp.Due_Value
                                                              - ISNULL(tmtaxAmt.Amount_Paid,
                                                              0) ))
                                          )
                              END )
        FROM    #temphistory AS tmp
                INNER JOIN #tempTaxAmountGST AS tmtaxAmt ON tmp.I_Invoice_Detail_ID = tmtaxAmt.I_Invoice_Detail_ID
		
        UPDATE  #temphistory
        SET     Total_Value = ISNULL(Due_Value, 0) + ISNULL(Tax_Value, 0)
 
  
        UPDATE  T1
        SET     T1.Amount_Paid = ISNULL(ROUND(T2.Amount_Paid, 2), 0)
        FROM    #temphistory T1
                INNER JOIN ( SELECT A.I_Invoice_Detail_ID ,
                                    SUM(N_Amount_Paid) Amount_Paid
                             FROM   dbo.T_Receipt_Component_Detail_Archive A
                                    INNER JOIN dbo.T_Receipt_Header_Archive AS trh ON A.I_Receipt_Detail_ID = trh.I_Receipt_Header_ID
                                                              AND DATEDIFF(dd,
                                                              Dt_Receipt_Date,
                                                              @dtUptoDate) >= 0
                                    INNER JOIN dbo.T_Invoice_Parent TIP ON trh.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
                                                              AND ( TIP.Dt_Upd_On IS NULL
                                                              OR ( DATEDIFF(dd,
                                                              @dtUptoDate,
                                                              TIP.Dt_Upd_On) > 0
                                                              AND DATEDIFF(dd,
                                                              '2017-06-30',
                                                              TIP.Dt_Upd_On) <= 0
                                                              )
                                                              )
                                    INNER JOIN #temphistory T ON T.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
                             GROUP BY A.I_Invoice_Detail_ID
                           ) T2 ON T1.I_Invoice_Detail_ID = T2.I_Invoice_Detail_ID
                           
        UPDATE  T1
        SET     T1.Total_Paid = ISNULL(T1.Amount_Paid, 0)
                + ROUND(ISNULL(T2.N_Tax_Paid, 0), 2) ,
                T1.Tax_Paid = ROUND(ISNULL(T2.N_Tax_Paid, 0), 2)
        FROM    #temphistory T1
                INNER JOIN ( SELECT A.I_Invoice_Detail_ID ,
                                    SUM(ISNULL(trtd.N_Tax_Paid, 0)) N_Tax_Paid
                             FROM   T_Receipt_Component_Detail_Archive A
                                    INNER JOIN dbo.T_Receipt_Header_Archive AS trh ON A.I_Receipt_Detail_ID = trh.I_Receipt_Header_ID
                                                              --AND I_Status <> 0  
                                                              AND DATEDIFF(dd,
                                                              Dt_Receipt_Date,
                                                              @dtUptoDate) >= 0
                                    INNER JOIN dbo.T_Invoice_Parent TIP ON trh.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
                                                              AND ( TIP.Dt_Upd_On IS NULL
                                                              OR ( DATEDIFF(dd,
                                                              @dtUptoDate,
                                                              TIP.Dt_Upd_On) > 0
                                                              AND DATEDIFF(dd,
                                                              '2017-06-30',
                                                              TIP.Dt_Upd_On) <= 0
                                                              )
                                                              )
                                    INNER JOIN #temphistory T ON T.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
                                    LEFT OUTER JOIN dbo.T_Receipt_Tax_Detail_Archive
                                    AS trtd ON A.I_Receipt_Comp_Detail_ID = trtd.I_Receipt_Comp_Detail_ID
                             GROUP BY A.I_Invoice_Detail_ID
                           ) T2 ON T1.I_Invoice_Detail_ID = T2.I_Invoice_Detail_ID
                           
          
        UPDATE  T1
        SET     T1.Amount_Paid = ISNULL(T1.Amount_Paid, 0)
                + ISNULL(ROUND(T2.Amount_Paid, 2), 0)
        FROM    #temphistory T1
                INNER JOIN ( SELECT A.I_Invoice_Detail_ID ,
                                    SUM(N_Amount_Paid) Amount_Paid
                             FROM   dbo.T_Receipt_Component_Detail A
                                    INNER JOIN dbo.T_Receipt_Header AS trh ON A.I_Receipt_Detail_ID = trh.I_Receipt_Header_ID
                                                              --AND I_Status <> 0 
                                                              AND DATEDIFF(dd,
                                                              Dt_Receipt_Date,
                                                              @dtUptoDate) >= 0
                                                              AND ( trh.Dt_Upd_On IS NULL
                                                              OR DATEDIFF(dd,
                                                              @dtUptoDate,
                                                              trh.Dt_Upd_On) > 0
                                                              OR I_Status = 1
                                                              )
                                    INNER JOIN #temphistory T ON T.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
                             GROUP BY A.I_Invoice_Detail_ID
                           ) T2 ON T1.I_Invoice_Detail_ID = T2.I_Invoice_Detail_ID
                           
        UPDATE  T1
        SET     T1.Tax_Paid = ISNULL(T1.Tax_Paid, 0)
                + ROUND(ISNULL(T2.N_Tax_Paid, 0), 2)
        FROM    #temphistory T1
                INNER JOIN ( SELECT A.I_Invoice_Detail_ID ,
                                    SUM(ISNULL(trtd.N_Tax_Paid, 0)) N_Tax_Paid
                             FROM   T_Receipt_Component_Detail A
                                    INNER JOIN dbo.T_Receipt_Header AS trh ON A.I_Receipt_Detail_ID = trh.I_Receipt_Header_ID
                                                              --AND I_Status <> 0  
                                                              AND DATEDIFF(dd,
                                                              Dt_Receipt_Date,
                                                              @dtUptoDate) >= 0
                                                              AND ( trh.Dt_Upd_On IS NULL
                                                              OR DATEDIFF(dd,
                                                              @dtUptoDate,
                                                              trh.Dt_Upd_On) > 0
                                                              OR I_Status = 1
                                                              )
                                    INNER JOIN #temphistory T ON T.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
                                    LEFT OUTER JOIN dbo.T_Receipt_Tax_Detail
                                    AS trtd ON A.I_Receipt_Comp_Detail_ID = trtd.I_Receipt_Comp_Detail_ID
                             GROUP BY A.I_Invoice_Detail_ID
                           ) T2 ON T1.I_Invoice_Detail_ID = T2.I_Invoice_Detail_ID
        
        UPDATE  T1
        SET     T1.Total_Paid = ISNULL(T1.Amount_Paid, 0) + ISNULL(T1.Tax_Paid,
                                                              0)
        FROM    #temphistory T1
        
          
        INSERT  INTO #temp
                ( I_Invoice_Child_Header_ID ,
                  S_Mobile_No ,
                  S_Student_ID ,
                  I_Roll_No ,
                  S_Student_Name ,
                  S_Invoice_No ,
                  S_Receipt_No ,
                  Dt_Invoice_Date ,
                  I_Fee_Component_ID ,
                  S_Component_Name ,
                  S_Batch_Name ,
                  S_Course_Name ,
                  I_Center_ID ,
                  S_Center_Name ,
                  TypeofCentre ,
                  S_Brand_Name ,
                  S_Cost_Center ,
                  Due_Value ,
                  Dt_Installment_Date ,
                  I_Installment_No ,
                  I_Parent_Invoice_ID ,
                  I_Invoice_Detail_ID ,
                  Revised_Invoice_Date ,
                  Tax_Value ,
                  Total_Value ,
                  Amount_Paid ,
                  Tax_Paid ,
                  Total_Paid ,
                  Total_Due ,
                  IsGSTImplemented ,
                  I_Invoice_Header_ID
                )
                SELECT DISTINCT
                        I_Invoice_Child_Header_ID ,
                        S_Mobile_No ,
                        S_Student_ID ,
                        I_Roll_No ,
                        S_Student_Name ,
                        S_Invoice_No ,
                        S_Receipt_No ,
                        Dt_Invoice_Date ,
                        I_Fee_Component_ID ,
                        S_Component_Name ,
                        S_Batch_Name ,
                        S_Course_Name ,
                        I_Center_ID ,
                        S_Center_Name ,
                        TypeofCentre ,
                        S_Brand_Name ,
                        S_Cost_Center ,
                        Due_Value ,
                        Dt_Installment_Date ,
                        I_Installment_No ,
                        I_Parent_Invoice_ID ,
                        I_Invoice_Detail_ID ,
                        Revised_Invoice_Date ,
                        Tax_Value ,
                        Total_Value ,
                        Amount_Paid ,
                        Tax_Paid ,
                        Total_Paid ,
                        Total_Due ,
                        IsGSTImplemented ,
                        I_Invoice_Header_ID
                FROM    #temphistory
        
        
        UPDATE  #temp
        SET     Total_Due = ISNULL(Total_Value, 0) - ISNULL(Total_Paid, 0)
        
        --Fine Amount Calculation
        IF EXISTS ( SELECT  *
                    FROM    #temp
                            INNER JOIN dbo.T_Brand_Master AS TBM ON TBM.S_Brand_Name COLLATE DATABASE_DEFAULT = #temp.S_Brand_Name COLLATE DATABASE_DEFAULT
                    WHERE   ISNULL(Total_Due, 0) > 0
                            AND ( ISNULL(Due_Value, 0) - ISNULL(Amount_Paid, 0) ) > 0
                            AND TBM.I_Brand_ID IN ( 109, 110, 107 ) )
            BEGIN
        
                INSERT  INTO #temp
                        ( S_Brand_Name ,
                          I_Center_ID ,
                          S_Center_Name ,
                          S_Student_ID ,
                          S_Student_Name ,
                          I_Invoice_Header_ID ,
                          I_Invoice_Detail_ID ,
                          Dt_Installment_Date ,
                          I_Installment_No ,
                          I_Fee_Component_ID ,
                          S_Component_Name ,
                          Due_Value ,
                          Tax_Value ,
                          Total_Value ,
                          Amount_Paid ,
                          Tax_Paid ,
                          Total_Paid ,
                          Total_Due
                        )
                        SELECT DISTINCT T2.S_Brand_Name ,
                                T2.I_Center_ID ,
                                T2.S_Center_Name ,
                                T2.S_Student_ID ,
                                T2.S_Student_Name ,
                                -1 ,
                                -1 ,
                                GETDATE() ,
                                0 ,
                                CASE WHEN @iBrandID = 107 THEN 27
                                     WHEN @iBrandID = 110 THEN 55
                                     WHEN @iBrandID = 109 THEN 77
                                END ,
                                CASE WHEN @iBrandID=110 THEN 'Fine'
                                WHEN @iBrandID =107 THEN 'Fine'
                                WHEN @iBrandID=109 THEN 'Fine' END ,
                                SUM(ISNULL(T2.FineAmount, 0)) ,
                                SUM(ISNULL(T2.FineAmountTax, 0))  ,
                                SUM(ISNULL(T2.FineAmount, 0)+ISNULL(T2.FineAmountTax, 0)) ,
                                0 ,
                                0 ,
                                0 ,
                                SUM(ISNULL(T2.FineAmount, 0)+ISNULL(T2.FineAmountTax, 0))
                        FROM    ( SELECT DISTINCT
                                            T1.S_Student_ID ,
                                            T1.S_Student_Name ,
                                            T1.I_Center_ID ,
                                            T1.S_Center_Name ,
                                            T1.S_Brand_Name ,
                                            GETDATE() AS Dt_Installment_Date,--T1.Dt_Installment_Date ,
                                            CASE WHEN @iBrandID=109 THEN 0.00--dbo.fnGetFineAmountForAPI(@iBrandID,T1.Dt_Installment_Date)
                                            WHEN @iBrandID=107 THEN 0.00--dbo.fnGetFineAmountForAPI(@iBrandID,T1.Dt_Installment_Date)
                                            WHEN @iBrandID=110 THEN 0.00--dbo.fnGetFineAmountForAPI(@iBrandID,T1.Dt_Installment_Date) 
											END AS FineAmount ,
                                            dbo.fnGetFineAmountTaxForAPI(CASE
                                                              WHEN @iBrandID = 107
                                                              THEN 27
                                                              WHEN @iBrandID = 110
                                                              THEN 55
                                                              WHEN @iBrandID = 109
                                                              THEN 77
                                                              END,
                                                              CASE WHEN @iBrandID=109 THEN 0.00--dbo.fnGetFineAmountForAPI(@iBrandID,T1.Dt_Installment_Date)
															  WHEN @iBrandID=107 THEN 0.00--dbo.fnGetFineAmountForAPI(@iBrandID,T1.Dt_Installment_Date)
															  WHEN @iBrandID=110 THEN 0.00--dbo.fnGetFineAmountForAPI(@iBrandID,T1.Dt_Installment_Date) 
															  END) AS FineAmountTax
                                  FROM      #temp AS T1
                                  WHERE     ISNULL(Total_Due, 0) > 0
                                            AND ( ISNULL(Due_Value, 0)
                                                  - ISNULL(Amount_Paid, 0) ) > 0
                                ) T2
                        GROUP BY T2.S_Brand_Name ,
                                T2.I_Center_ID ,
                                T2.S_Center_Name ,
                                T2.S_Student_ID ,
                                T2.S_Student_Name
        
        
            END
        
        
        --------------***********----------------------
     
        SELECT  T1.S_Brand_Name COLLATE DATABASE_DEFAULT,
                T1.I_Center_ID ,
                T1.S_Center_Name COLLATE DATABASE_DEFAULT,
                T1.S_Course_Name COLLATE DATABASE_DEFAULT,
                T1.S_Batch_Name COLLATE DATABASE_DEFAULT,
                T1.S_Student_ID COLLATE DATABASE_DEFAULT,
                T1.S_Student_Name COLLATE DATABASE_DEFAULT,
                T1.I_Invoice_Header_ID ,
                T1.S_Invoice_No COLLATE DATABASE_DEFAULT,
                T1.I_Invoice_Child_Header_ID ,
                T1.I_Invoice_Detail_ID ,
                T1.Dt_Installment_Date ,
                T1.I_Installment_No ,
                T1.I_Fee_Component_ID ,
                T1.S_Component_Name COLLATE DATABASE_DEFAULT,
                T1.Due_Value AS BaseAmountDue ,
                T1.Tax_Value AS TaxDue ,
                T1.Total_Value AS TotalAmtPayable ,
                T1.Amount_Paid ,
                T1.Tax_Paid ,
                T1.Total_Paid ,
                T1.Total_Due AS CurrentDue
        FROM    ( SELECT DISTINCT
                            T.* ,
                            CAST(DATEDIFF(d, T.Dt_Installment_Date, GETDATE()) AS INT) AS Age ,
                            FN2.instanceChain
                  FROM      #temp T
                            INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList,
                                                              @iBrandID) FN1 ON T.I_Center_ID = FN1.centerID
                            INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList,
                                                              @iBrandID) FN2 ON FN1.hierarchyDetailID = FN2.hierarchyDetailID
                  WHERE     ISNULL(Total_Due, 0) > 0
                            AND ( ISNULL(T.Due_Value, 0)
                                  - ISNULL(T.Amount_Paid, 0) ) > 0
                ) T1
        ORDER BY T1.S_Center_Name ,
                T1.S_Batch_Name 
            --I_Roll_No;


        DROP TABLE #tempinvoice
        DROP TABLE #temp
        DROP TABLE #temphistory
        DROP TABLE #tempTaxAmountGST
   
   
    END
GO
PRINT N'Creating Procedure [ECOMMERCE].[uspGetIndividualIstallmentInvoice]...';


GO
/*--------------------------------------------------------------------------------------------------------------------------------------  
SP NAME        -  [dbo].[uspGetIndividualIstallmentInvoice]  
CREATED DATE   -  26th Jume 2017  
EXEC EXAMPLE   -  [dbo].[uspGetIndividualIstallmentInvoice] 161389,4,0.00,2800.00  
      [dbo].[uspGetIndividualIstallmentInvoice] 161389,4,1800.00,0.00  
      [dbo].[uspGetIndividualIstallmentInvoice] 'RICE/932890'  
      [dbo].[uspGetIndividualIstallmentInvoice] 'RC19C04170452395', 'C'             
--------------------------------------------------------------------------------------------------------------------------------------*/  
CREATE PROCEDURE [ECOMMERCE].[uspGetIndividualIstallmentInvoice]  
(   
 @SInvoiceNo VARCHAR(256)  
 ,@InvoiceType VARCHAR(256)  
)  
AS  
BEGIN  
 DECLARE @row INT = 1 --ROW COUNTER FOR WHILE LOOP  
 DECLARE @count INT --TOTAL ROW COUNT OF #T  
   
 CREATE TABLE #TRIN  
 (  
  ID INT IDENTITY(1,1),  
  S_Reff_Invoice_No VARCHAR(256),  
  --09/05/2017  
  S_Reff_Invoice_Date VARCHAR(256)   
 )  
  
 IF (@InvoiceType='C')  
 BEGIN  
  CREATE TABLE #T  
  (  
   ID INT IDENTITY(1,1),  
   I_Credit_Note_Invoice_Child_Detail_ID INT,  
   I_Invoice_Detail_ID INT,  
   I_Invoice_Child_Header_ID INT,  
   I_Installment_No INT,  
   Dt_Installment_Date DATETIME,  
   N_Amount_Due NUMERIC(18,2),  
   N_Discount_Amount NUMERIC(18,2),  
   N_Amount_Adv_Coln NUMERIC(18,2),  
   S_Invoice_No VARCHAR(256),  
   S_Reff_Invoice_No VARCHAR(256),  
   --09/05/2017  
   S_Reff_Invoice_Date VARCHAR(256)   
  )  
    
  --SECOND TEMPORARY TABLE FOR INCLUSION OF INSTALLMENT WISE TAX DETAILS  
  CREATE TABLE #TT  
  (  
   ID INT IDENTITY(1,1),  
   I_Invoice_Detail_ID INT,  
   I_Tax_ID INT NULL,  
   N_TAX_Amount NUMERIC(18,2) NULL  
  )  
  INSERT INTO #T   
  (  
   I_Credit_Note_Invoice_Child_Detail_ID,  
   I_Invoice_Detail_ID,  
   I_Invoice_Child_Header_ID,  
   I_Installment_No,  
   Dt_Installment_Date,  
   N_Amount_Due,  
   N_Discount_Amount,  
   N_Amount_Adv_Coln,  
   S_Invoice_No,  
   S_Reff_Invoice_No,  
   --09/05/2017  
   S_Reff_Invoice_Date  
  )  
  SELECT   
   ICCD.I_Credit_Note_Invoice_Child_Detail_ID,  
   ICD.I_Invoice_Detail_ID,  
   ICD.I_Invoice_Child_Header_ID,  
   ICD.I_Installment_No,  
   CONVERT(DATE,CASE WHEN CONVERT(DATE, ICD.Dt_Installment_Date) > CONVERT(DATE, ICCD.Dt_Crtd_On) THEN ICD.Dt_Installment_Date  
     ELSE ICCD.Dt_Crtd_On  
   END) AS Dt_Installment_Date,  
   CASE WHEN ISNULL(ICD.Flag_IsAdvanceTax,'N') = 'N' THEN ISNULL(ICCD.N_Amount_Due,0.00)  
     ELSE 0.00  
   END N_Amount_Due,  
   ICD.N_Discount_Amount,  
   CASE WHEN ISNULL(ICD.Flag_IsAdvanceTax,'N') = 'N' THEN ISNULL(ICCD.N_Amount_Adv,0.00)  
     ELSE ISNULL(ICCD.N_Amount,0.00)  
   END,  
   ICCD.S_Invoice_Number,  
   ICD.S_Invoice_Number AS S_Reff_Invoice_No,  
   --09/05/2017  
   --CONVERT(DATE, ICD.Dt_Installment_Date) as S_Reff_Invoice_Date  
   REPLACE(CONVERT(NVARCHAR(256),ICD.Dt_Installment_Date,106),' ','/')as S_Reff_Invoice_Date  
  FROM dbo.T_Credit_Note_Invoice_Child_Detail ICCD   
  INNER JOIN dbo.T_Invoice_Child_Detail ICD ON ICCD.I_Invoice_Detail_ID = ICD.I_Invoice_Detail_ID  
  INNER JOIN dbo.T_Invoice_Child_Header ICH  
  ON ICD.I_Invoice_Child_Header_ID = ICH.I_Invoice_Child_Header_ID   
  AND ICCD.S_Invoice_Number = @SInvoiceNo  
    
  DECLARE @ICreditNoteInvoiceChildDetailID INT  
    
  SET @row = 1  
  SELECT @count=COUNT(ID) FROM #T  
  
  WHILE(@row <= @count)  
  BEGIN   
   --SELECTION OF INVOICE DETAIL ID FOR EACH ROW IN TEMP TABLE #T  
   SELECT @ICreditNoteInvoiceChildDetailID = I_Credit_Note_Invoice_Child_Detail_ID FROM #T WHERE ID = @row    
   --INSERTION OF TAX DETAIL AGAINST EVERY INSTALLMENT  
   INSERT INTO #TT   
   (    
    I_Invoice_Detail_ID,  
    I_Tax_ID,  
    N_TAX_Amount  
   )  
   SELECT   
    T.I_Invoice_Detail_ID,  
    ISNULL(IDT.I_Tax_ID,0),  
    ISNULL(IDT.N_Tax_Value,0.00)  
   FROM #T AS T  
   INNER JOIN dbo.T_Credit_Note_Invoice_Child_Detail_Tax AS IDT ON T.I_Credit_Note_Invoice_Child_Detail_ID = IDT.I_Credit_Note_Invoice_Child_Detail_ID  
   WHERE T.I_Credit_Note_Invoice_Child_Detail_ID = @ICreditNoteInvoiceChildDetailID    
   --WHILE LOOP COUNTER  
   SET @row = @row + 1   
  END  
    
  DECLARE @CGSTAmt NUMERIC(18,2)  
  DECLARE @SGSTAmt NUMERIC(18,2)  
  DECLARE @IGSTAmt NUMERIC(18,2)  
  DECLARE @TAXAmt NUMERIC(18,2)  
    
  SELECT  
   @SGSTAmt = SUM(ISNULL(T.N_SGST_Amount,0.00)),  
   @CGSTAmt = SUM(ISNULL(T.N_CGST_Amount,0.00)),  
   @IGSTAmt = SUM(ISNULL(T.N_IGST_Amount,0.00)),  
   @TAXAmt = SUM(ISNULL(T.N_Tax_Amount,0.00))   
  FROM(SELECT    
   T.I_Invoice_Detail_ID,  
   CASE WHEN TM.S_Tax_Code = 'SGST'  
    THEN  T.N_TAX_Amount END N_SGST_Amount,  
   CASE WHEN TM.S_Tax_Code = 'CGST'  
    THEN  T.N_TAX_Amount END N_CGST_Amount,  
   CASE WHEN TM.S_Tax_Code = 'IGST'  
    THEN  T.N_TAX_Amount END N_IGST_Amount,  
   CASE WHEN TM.S_Tax_Code NOT IN ('SGST','CGST')  
    THEN  T.N_TAX_Amount END N_Tax_Amount    
  FROM #TT AS T  
  LEFT OUTER JOIN dbo.T_Tax_Master AS TM ON T.I_Tax_ID = TM.I_Tax_ID) T  
    
  SELECT FST.I_Installment_No,  
   REPLACE(CONVERT(NVARCHAR(256),FST.Dt_Installment_Date,106),' ','/') Dt_Installment_Date,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FST.N_Amount_Due,0)) N_Amount_Due,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FST.N_Discount_Amount,0)) N_Discount_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FST.N_Amount_Adv_Coln,0)) N_Amount_Adv_Coln,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * ISNULL(@SGSTAmt,0) N_SGST_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * ISNULL(@CGSTAmt,0) N_CGST_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * ISNULL(@IGSTAmt,0) N_IGST_Amount ,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * ISNULL(@TAXAmt,0) N_Tax_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END *   
   CASE WHEN SUM(ISNULL(FST.N_Amount_Due,0.00)) > 0   
   THEN (SUM(ISNULL(FST.N_Amount_Due,0.00))-SUM(ISNULL(FST.N_Discount_Amount,0.00))) - SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00))  
   ELSE SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00)) END N_Net_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END *   
   CASE WHEN SUM(ISNULL(FST.N_Amount_Due,0.00)) > 0   
   THEN (SUM(ISNULL(FST.N_Amount_Due,0.00))-SUM(ISNULL(FST.N_Discount_Amount,0.00))) - SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00)) + ISNULL(@SGSTAmt,0) + ISNULL(@CGSTAmt,0) + ISNULL(@IGSTAmt,0) + ISNULL(@TAXAmt,0)  
   ELSE SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00)) + ISNULL(@SGSTAmt,0) + ISNULL(@CGSTAmt,0) + ISNULL(@IGSTAmt,0) + ISNULL(@TAXAmt,0)  
   END N_Total_Amount  
  FROM #T AS FST  
  GROUP BY FST.I_Installment_No, REPLACE(CONVERT(NVARCHAR(256),FST.Dt_Installment_Date,106),' ','/')  
    
  --09/05/2017  
  --INSERT INTO #TRIN(S_Reff_Invoice_No)  
  --SELECT DISTINCT S_Reff_Invoice_No FROM #T  
  INSERT INTO #TRIN(S_Reff_Invoice_No,S_Reff_Invoice_Date)  
  SELECT DISTINCT S_Reff_Invoice_No,REPLACE(CONVERT(NVARCHAR(256),S_Reff_Invoice_Date,106),' ','/')FROM #T  
    
  DROP TABLE #T  
  DROP TABLE #TT  
 END  
 ELSE  
 BEGIN  
  CREATE TABLE #T1  
  (  
   ID INT IDENTITY(1,1),  
   I_Invoice_Detail_ID INT,  
   I_Invoice_Child_Header_ID INT,  
   I_Installment_No INT,  
   Dt_Installment_Date DATETIME,  
   N_Amount_Due NUMERIC(18,2),  
   N_Discount_Amount NUMERIC(18,2),  
   N_Amount_Adv_Coln NUMERIC(18,2),  
   S_Invoice_No VARCHAR(256)    
  )  
    
  --SECOND TEMPORARY TABLE FOR INCLUSION OF INSTALLMENT WISE TAX DETAILS  
  CREATE TABLE #TT1  
  (  
   ID INT IDENTITY(1,1),  
   I_Invoice_Detail_ID INT,  
   I_Tax_ID INT NULL,  
   N_TAX_Amount NUMERIC(18,2) NULL  
  )  
  INSERT INTO #T1  
  (  
   I_Invoice_Detail_ID,  
   I_Invoice_Child_Header_ID,  
   I_Installment_No,  
   Dt_Installment_Date,  
   N_Amount_Due,  
   N_Discount_Amount,  
   N_Amount_Adv_Coln,  
   S_Invoice_No  
  )  
  SELECT   
   ICD.I_Invoice_Detail_ID,  
   ICD.I_Invoice_Child_Header_ID,  
   ICD.I_Installment_No,  
   CONVERT(DATE,ICD.Dt_Installment_Date),  
   ISNULL(ICD.N_Amount_Due,0.00),  
   ICD.N_Discount_Amount,  
   ISNULL(ICD.N_Amount_Adv_Coln,0.00),  
   ICD.S_Invoice_Number  
  FROM dbo.T_Invoice_Child_Detail ICD  
  INNER JOIN dbo.T_Invoice_Child_Header ICH  
  ON ICD.I_Invoice_Child_Header_ID = ICH.I_Invoice_Child_Header_ID   
  AND ICD.S_Invoice_Number = @SInvoiceNo   
    
  DECLARE @InvoiceDetailID INT  
  
  SET @row = 1  
  SELECT @count=COUNT(ID) FROM #T1  
  
  WHILE(@row <= @count)  
  BEGIN   
   --SELECTION OF INVOICE DETAIL ID FOR EACH ROW IN TEMP TABLE #T  
   SELECT @InvoiceDetailID = I_Invoice_Detail_ID FROM #T1 WHERE ID = @row    
   --INSERTION OF TAX DETAIL AGAINST EVERY INSTALLMENT  
   INSERT INTO #TT1  
   (    
    I_Invoice_Detail_ID,  
    I_Tax_ID,  
    N_TAX_Amount  
   )  
   SELECT   
    T.I_Invoice_Detail_ID,  
    ISNULL(IDT.I_Tax_ID,0),  
    ISNULL(IDT.N_Tax_Value_Scheduled,0.00)  
   FROM #T1 AS T  
   INNER JOIN dbo.T_Invoice_Detail_Tax AS IDT  
   ON T.I_Invoice_Detail_ID = IDT.I_Invoice_Detail_ID  
   WHERE T.I_Invoice_Detail_ID = @InvoiceDetailID    
   --WHILE LOOP COUNTER  
   SET @row = @row + 1   
  END  
    
  SELECT  
   FST.I_Installment_No,  
   REPLACE(CONVERT(NVARCHAR(256),FST.Dt_Installment_Date,106),' ','/') Dt_Installment_Date,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FST.N_Amount_Due,0)) N_Amount_Due,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FST.N_Discount_Amount,0)) N_Discount_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FST.N_Amount_Adv_Coln,0)) N_Amount_Adv_Coln,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FT.N_SGST_Amount,0)) N_SGST_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FT.N_CGST_Amount,0)) N_CGST_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FT.N_IGST_Amount,0)) N_IGST_Amount ,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END * SUM(ISNULL(FT.N_Tax_Amount,0)) N_Tax_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END *   
   CASE WHEN SUM(ISNULL(FST.N_Amount_Due,0.00)) > 0   
   THEN (SUM(ISNULL(FST.N_Amount_Due,0.00))-SUM(ISNULL(FST.N_Discount_Amount,0.00))) - SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00))  
   ELSE SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00)) END N_Net_Amount,  
   CASE WHEN @InvoiceType = 'C' THEN (-1) ELSE 1 END *   
   CASE WHEN SUM(ISNULL(FST.N_Amount_Due,0.00)) > 0   
   THEN (SUM(ISNULL(FST.N_Amount_Due,0.00))-SUM(ISNULL(FST.N_Discount_Amount,0.00))) - SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00)) + SUM(ISNULL(FT.N_SGST_Amount,0.00)) + SUM(ISNULL(FT.N_CGST_Amount,0.00)) + SUM(ISNULL(FT.N_IGST_Amount,0.00)) + SUM(ISNULL(FT.N_Tax_Amount,0.00))  
   ELSE SUM(ISNULL(FST.N_Amount_Adv_Coln,0.00)) + SUM(ISNULL(FT.N_SGST_Amount,0.00)) + SUM(ISNULL(FT.N_CGST_Amount,0.00)) + SUM(ISNULL(FT.N_IGST_Amount,0.00)) + SUM(ISNULL(FT.N_Tax_Amount,0.00))  
   END N_Total_Amount  
  FROM #T1 AS FST  
  LEFT JOIN (SELECT   
   T.I_Invoice_Detail_ID,  
   SUM(ISNULL(T.N_SGST_Amount,0.00)) AS N_SGST_Amount,  
   SUM(ISNULL(T.N_CGST_Amount,0.00)) AS N_CGST_Amount,  
   SUM(ISNULL(T.N_IGST_Amount,0.00)) AS N_IGST_Amount,  
   SUM(ISNULL(T.N_Tax_Amount,0.00)) AS N_Tax_Amount   
  FROM(SELECT    
   T.I_Invoice_Detail_ID,  
   CASE WHEN TM.S_Tax_Code = 'SGST'  
    THEN  T.N_TAX_Amount END N_SGST_Amount,  
   CASE WHEN TM.S_Tax_Code = 'CGST'  
    THEN  T.N_TAX_Amount END N_CGST_Amount,  
   CASE WHEN TM.S_Tax_Code = 'IGST'  
    THEN  T.N_TAX_Amount END N_IGST_Amount,  
   CASE WHEN TM.S_Tax_Code NOT IN ('SGST','CGST')  
    THEN  T.N_TAX_Amount END N_Tax_Amount    
  FROM #TT1 AS T  
  LEFT OUTER JOIN dbo.T_Tax_Master AS TM ON T.I_Tax_ID = TM.I_Tax_ID) T  
  GROUP BY T.I_Invoice_Detail_ID  
  ) FT ON FST.I_Invoice_Detail_ID = FT.I_Invoice_Detail_ID  
  GROUP BY FST.I_Installment_No, REPLACE(CONVERT(NVARCHAR(256),FST.Dt_Installment_Date,106),' ','/')  
    
  DROP TABLE #T1  
  DROP TABLE #TT1  
 END  
   
 CREATE TABLE #TTT  
 (  
  ID INT IDENTITY(1,1),  
  S_Receipt_No VARCHAR(256),  
  Dt_Receipt_Date DATE  
 )  
 INSERT INTO #TTT  
    
 SELECT DISTINCT B.S_Receipt_No,REPLACE(CONVERT(NVARCHAR(256),B.Dt_Receipt_Date,106),' ','/') Dt_Receipt_Date   
 FROM T_Invoice_Child_Detail A   
 INNER JOIN T_Advance_Receipt_Mapping ACM ON A.I_Invoice_Detail_ID = ACM.I_Invoice_Detail_ID  
 INNER JOIN T_Receipt_Header B ON ACM.I_Receipt_Header_ID=B.I_Receipt_Header_ID  
 WHERE S_Invoice_Number=@SInvoiceNo  
 AND A.Flag_IsAdvanceTax='Y'  
  
 DECLARE @rnrow int = 1  
 DECLARE @rncount INT  
 DECLARE @srecptNO VARCHAR(256)  
 DECLARE @recptNO VARCHAR(256)  
 DECLARE @recptDate VARCHAR(256)  
  
 SELECT @rncount = COUNT(ID) FROM #TTT  
 SET @srecptNO = '';  
 WHILE (@rnrow <= @rncount)  
 BEGIN  
  SELECT @recptNO = S_Receipt_No,  
    @recptDate = Dt_Receipt_Date  
  FROM #TTT WHERE ID = @rnrow  
  IF (@rnrow=1)  
   SET @srecptNO = @srecptNO + @recptNO  
  ELSE  
   SET @srecptNO = @srecptNO + ',' + @recptNO  
  SET @rnrow = @rnrow + 1  
 END  
   
 --SELECT @srecptNO AS S_Receipt_No, @recptDate AS Dt_Receipt_Date  
   
   
 SET @rnrow = 1  
 DECLARE @S_Tot_Reff_Invoice_No VARCHAR(256) = ''  
 DECLARE @S_Reff_Invoice_No NVARCHAR(256) = ''  
 --09/05/2017  
 DECLARE @S_Tot_Reff_Invoice_Date VARCHAR(256) = ''  
 DECLARE @S_Reff_Invoice_Date NVARCHAR(256) = ''  
   
 SELECT @rncount = COUNT(ID) FROM #TRIN  
   
 WHILE (@rnrow <= @rncount)  
 BEGIN  
  SELECT @S_Reff_Invoice_No = S_Reff_Invoice_No,  
    @S_Reff_Invoice_Date = S_Reff_Invoice_Date  
  FROM #TRIN WHERE ID = @rnrow  
  IF (@rnrow=1)  
   BEGIN  
    SET @S_Tot_Reff_Invoice_No = @S_Tot_Reff_Invoice_No + @S_Reff_Invoice_No  
    --09/05/2017  
    SET @S_Tot_Reff_Invoice_Date = @S_Tot_Reff_Invoice_Date + @S_Reff_Invoice_Date  
   END  
  ELSE  
   BEGIN  
    SET @S_Tot_Reff_Invoice_No = @S_Tot_Reff_Invoice_No + ',' + @S_Reff_Invoice_No  
    --09/05/2017  
    SET @S_Tot_Reff_Invoice_Date = @S_Tot_Reff_Invoice_Date + ',' + @S_Reff_Invoice_Date  
   END  
  SET @rnrow = @rnrow + 1  
 END  
   
 --SELECT @S_Tot_Reff_Invoice_No AS S_Reff_Invoice_Nos,REPLACE(CONVERT(NVARCHAR(256),@S_Tot_Reff_Invoice_Date,106),' ','/') AS S_Reff_Invoice_Date  
 --@S_Tot_Reff_Invoice_Date AS S_Reff_Invoice_Date   
   
 --DROPING THE CREATED TEMP TABLES   
 DROP TABLE #TTT  
 DROP TABLE #TRIN  
END
