				--	where S_Mobile_No = (select MobileNo from ECOMMERCE.T_Registration where CustomerID=@CustomerID and StatusID=1)
				--end
				--IF (@iI_City_ID is not null and @iI_City_ID > 0)--add > by susmita instead of =
				--begin
