			--added by susmita

			select S_Student_ID from T_Student_Detail 
								where S_Mobile_No = (select MobileNo from 
								ECOMMERCE.T_Registration where CustomerID=@CustomerID and StatusID=1)
		-------------------------------------END----------------------------------------------


		end
		else
