PRINT N'Creating Procedure [ECOMMERCE].[uspValidateCouponCodeForPlan]...';


GO
CREATE procedure [ECOMMERCE].[uspValidateCouponCodeForPlan]
(
	@BrandID INT,
	@CouponCode VARCHAR(MAX),
	@PlanID INT,
	@ProductID INT,
	@CenterID INT,
	@PaymentMode INT,
	@PurchaseAmount DECIMAL(14,2)=0,
	@CustomerID VARCHAR(MAX)=NULL
)
AS
BEGIN

	--RSMRT463

	declare @couponid int=0
	declare @discountschemeid int=0
	declare @feeplanid int=0
	declare @flag bit=0
	declare @totalInstalmentPayable DECIMAL(14,0)=0
	declare @totalInstalmentPayableTax DECIMAL(14,0)=0
	DECLARE @perstudentcouponcount INT=0

	create table #TblFeePlanDtls
	(
		ID INT,
		I_Course_Fee_Plan_Detail_ID INT ,
		I_Fee_Component_ID INT,
		I_Course_Fee_Plan_ID INT,
		I_Item_Value Decimal(14,2),
		N_Discount decimal(14,2),
		I_Installment_No INT,
		I_Sequence INT,
		C_Is_LumpSum varchar(1),
		I_Display_Fee_Component_ID INT,
		InstalmentDate Datetime,
		ActualInstalmentNo INT
	)

	SELECT @perstudentcouponcount=ISNULL(COUNT(DISTINCT A.TransactionID),0) 
	FROM ECOMMERCE.T_Transaction_Master A
	INNER JOIN ECOMMERCE.T_Transaction_Plan_Details B ON B.TransactionID = A.TransactionID
	INNER JOIN ECOMMERCE.T_Transaction_Product_Details C ON C.TransactionPlanDetailID = B.TransactionPlanDetailID
	WHERE
    A.CustomerID COLLATE DATABASE_DEFAULT=ISNULL(@CustomerID,'') COLLATE DATABASE_DEFAULT
	AND A.StatusID=1 
	AND A.TransactionStatus!='Failure'
	AND C.CouponCode IS NOT NULL 
	AND C.CouponCode COLLATE DATABASE_DEFAULT=@CouponCode COLLATE DATABASE_DEFAULT



	IF(@CustomerID IS NOT NULL)
	BEGIN

		PRINT 'Customer'

		select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID 
		FROM ECOMMERCE.T_Coupon_Master TCM
		inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
		inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
		inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
		inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
		inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
		inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
		inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
		inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
		inner join ECOMMERCE.T_Registration TR on TR.CustomerID=TCM.CustomerID
		inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
		inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
		where
		TCM.StatusID=1 and TDSM.I_Status=1
		and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
		and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
		and TCBM.BrandID=@BrandID
		and TPBM.BrandID=@BrandID
		and TCM.CouponCategoryID=3
		and TCM.CouponCount>TCM.AssignedCount
		and TDSD.I_IsApplicableOn=@PaymentMode
		and TPM.ProductID=@ProductID
		and TPCM.PlanID=@PlanID
		and TDCD.I_Centre_ID=@CenterID
		and TCM.CouponCode=@CouponCode
		and TCM.CustomerID=@CustomerID

		PRINT @couponid

	END

	IF(@PurchaseAmount IS NOT NULL and @PurchaseAmount>0 and @couponid<=0)
	BEGIN

		PRINT 'Purchase'

		select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID 
		FROM ECOMMERCE.T_Coupon_Master TCM
		inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
		inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
		inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
		inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
		inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
		inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
		inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
		inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
		inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
		inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
		where
		TCM.StatusID=1 and TDSM.I_Status=1
		and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
		and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
		and TCBM.BrandID=@BrandID
		and TPBM.BrandID=@BrandID
		and TCM.CouponCategoryID=2
		and TCM.CouponCount>TCM.AssignedCount
		and TDSD.I_IsApplicableOn=@PaymentMode
		and TPM.ProductID=@ProductID
		and TPCM.PlanID=@PlanID
		and TDCD.I_Centre_ID=@CenterID
		and TCM.CouponCode=@CouponCode
		and TCM.GreaterThanAmount<@PurchaseAmount
		AND ISNULL(TCM.PerStudentCount,1)>@perstudentcouponcount

		PRINT @couponid

	END

	IF(@couponid<=0)
	BEGIN

	PRINT 'Plan'

	select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID from ECOMMERCE.T_Coupon_Master TCM
	inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
	inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
	inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
	inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
	inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
	inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
	inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
	inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
	inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
	inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
	where
	TCM.StatusID=1 and TDSM.I_Status=1
	and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
	and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
	and TCBM.BrandID=@BrandID
	and TPBM.BrandID=@BrandID
	and TCM.CouponCategoryID=1
	and TCM.CouponCount>TCM.AssignedCount
	and TDSD.I_IsApplicableOn=@PaymentMode
	and TPM.ProductID=@ProductID
	and TPCM.PlanID=@PlanID
	and TDCD.I_Centre_ID=@CenterID
	and TCM.CouponCode=@CouponCode
	AND ISNULL(TCM.PerStudentCount,1)>@perstudentcouponcount

	PRINT @couponid

	END


	select @feeplanid=B.CourseFeePlanID from ECOMMERCE.T_Product_Center_Map A
	inner join ECOMMERCE.T_Product_FeePlan B on A.ProductCentreID=B.ProductCentreID
	inner join ECOMMERCE.T_Plan_Product_Map C on A.ProductID=C.ProductID
	where
	A.CenterID=@CenterID and A.ProductID=@ProductID and C.PlanID=@PlanID
	and C.StatusID=1

	print @feeplanid


	insert into #TblFeePlanDtls
	exec ECOMMERCE.uspGetFeePlanDiscountDetails @feeplanid,@PaymentMode,@discountschemeid,NULL


	
	

	

	if(@couponid>0)
		set @flag=1


	select @totalInstalmentPayable=SUM(ISNULL(P.PayableAmount,0)),@totalInstalmentPayableTax=SUM(ISNULL(P.PayableTax,0)) 
		from
		(
			select ISNULL(T1.Amount,0) as PayableAmount,((ISNULL(T1.Amount,0)*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from #TblFeePlanDtls A
				where A.I_Installment_No>0
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P




	IF(@PaymentMode=1)
	BEGIN
		
		select SUM(P.PayableAmount) as PayableAmount,SUM(P.PayableTax) as PayableTax, @flag as IsCouponApplicable,0 as TotalInstalmentPayable,0 as TotalInstalmentPayableTax
		from
		(
			select T1.Amount as PayableAmount,((T1.Amount*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from #TblFeePlanDtls A
				where A.I_Installment_No=0
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P

	END
	ELSE IF(@PaymentMode=2)
	BEGIN

		DECLARE @MinInstNo INT

		select @MinInstNo=MIN(I_Installment_No) from #TblFeePlanDtls where I_Installment_No>0

		select SUM(P.PayableAmount) as PayableAmount,SUM(P.PayableTax) as PayableTax, @flag as IsCouponApplicable,@totalInstalmentPayable as TotalInstalmentPayable,@totalInstalmentPayableTax as TotalInstalmentPayableTax 
		from
		(
			select T1.Amount as PayableAmount,((T1.Amount*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from #TblFeePlanDtls A
				where A.I_Installment_No=@MinInstNo
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P

	END


END
GO
PRINT N'Creating Procedure [ECOMMERCE].[uspValidateCouponCodeForPlan_BySomaForTest]...';


GO
create procedure [ECOMMERCE].[uspValidateCouponCodeForPlan_BySomaForTest]
--(
--	@BrandID INT,
--	@CouponCode VARCHAR(MAX),
--	@PlanID INT,
--	@ProductID INT,
--	@CenterID INT,
--	@PaymentMode INT,
--	@PurchaseAmount DECIMAL(14,2)=0,
--	@CustomerID VARCHAR(MAX)=NULL
--)
AS
declare @BrandID INT=109,
	@CouponCode VARCHAR(MAX)='HOLI',
	@PlanID INT=17,
	@ProductID INT=18,
	@CenterID INT=132,
	@PaymentMode INT=1,
	@PurchaseAmount DECIMAL(14,2)=6999,
	@CustomerID VARCHAR(MAX)=NULL

BEGIN

	--RSMRT463

	declare @couponid int=0
	declare @discountschemeid int=0
	declare @feeplanid int=0
	declare @flag bit=0
	declare @totalInstalmentPayable DECIMAL(14,0)=0
	declare @totalInstalmentPayableTax DECIMAL(14,0)=0
	DECLARE @perstudentcouponcount INT=0

	create table #TblFeePlanDtls
	(
		ID INT,
		I_Course_Fee_Plan_Detail_ID INT ,
		I_Fee_Component_ID INT,
		I_Course_Fee_Plan_ID INT,
		I_Item_Value Decimal(14,2),
		N_Discount decimal(14,2),
		I_Installment_No INT,
		I_Sequence INT,
		C_Is_LumpSum varchar(1),
		I_Display_Fee_Component_ID INT,
		InstalmentDate Datetime,
		ActualInstalmentNo INT
	)

	SELECT @perstudentcouponcount=ISNULL(COUNT(DISTINCT A.TransactionID),0) 
	FROM ECOMMERCE.T_Transaction_Master A
	INNER JOIN ECOMMERCE.T_Transaction_Plan_Details B ON B.TransactionID = A.TransactionID
	INNER JOIN ECOMMERCE.T_Transaction_Product_Details C ON C.TransactionPlanDetailID = B.TransactionPlanDetailID
	WHERE
    A.CustomerID COLLATE DATABASE_DEFAULT=ISNULL(@CustomerID,'') COLLATE DATABASE_DEFAULT
	AND A.StatusID=1 
	AND A.TransactionStatus!='Failure'
	AND C.CouponCode IS NOT NULL 
	AND C.CouponCode COLLATE DATABASE_DEFAULT=@CouponCode COLLATE DATABASE_DEFAULT



	IF(@CustomerID IS NOT NULL)
	BEGIN

		PRINT 'Customer'

		select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID 
		FROM ECOMMERCE.T_Coupon_Master TCM
		inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
		inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
		inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
		inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
		inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
		inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
		inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
		inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
		inner join ECOMMERCE.T_Registration TR on TR.CustomerID=TCM.CustomerID
		inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
		inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
		where
		TCM.StatusID=1 and TDSM.I_Status=1
		and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
		and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
		and TCBM.BrandID=@BrandID
		and TPBM.BrandID=@BrandID
		and TCM.CouponCategoryID=3
		and TCM.CouponCount>TCM.AssignedCount
		and TDSD.I_IsApplicableOn=@PaymentMode
		and TPM.ProductID=@ProductID
		and TPCM.PlanID=@PlanID
		and TDCD.I_Centre_ID=@CenterID
		and TCM.CouponCode=@CouponCode
		and TCM.CustomerID=@CustomerID

		PRINT @couponid

	END

	IF(@PurchaseAmount IS NOT NULL and @PurchaseAmount>0 and @couponid<=0)
	BEGIN

		PRINT 'Purchase'

		select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID 
		FROM ECOMMERCE.T_Coupon_Master TCM
		inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
		inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
		inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
		inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
		inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
		inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
		inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
		inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
		inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
		inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
		where
		TCM.StatusID=1 and TDSM.I_Status=1
		and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
		and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
		and TCBM.BrandID=@BrandID
		and TPBM.BrandID=@BrandID
		and TCM.CouponCategoryID=2
		and TCM.CouponCount>TCM.AssignedCount
		and TDSD.I_IsApplicableOn=@PaymentMode
		and TPM.ProductID=@ProductID
		and TPCM.PlanID=@PlanID
		and TDCD.I_Centre_ID=@CenterID
		and TCM.CouponCode=@CouponCode
		and TCM.GreaterThanAmount<@PurchaseAmount
		AND ISNULL(TCM.PerStudentCount,1)>@perstudentcouponcount

		PRINT @couponid

	END

	IF(@couponid<=0)
	BEGIN

	PRINT 'Plan'

	select TOP 1 @couponid=TCM.CouponID,@discountschemeid=TDSM.I_Discount_Scheme_ID from ECOMMERCE.T_Coupon_Master TCM
	inner join T_Discount_Scheme_Master TDSM on TCM.DiscountSchemeID=TDSM.I_Discount_Scheme_ID
	inner join T_Discount_Scheme_Details TDSD on TDSD.I_Discount_Scheme_ID=TCM.DiscountSchemeID
	inner join T_Discount_Center_Detail TDCD on TDCD.I_Discount_Scheme_ID=TCM.DiscountSchemeID and TDCD.I_Status=1
	inner join T_Discount_Course_Detail TDCD2 on TDCD.I_Discount_Center_Detail_ID=TDCD2.I_Discount_Centre_Detail_ID and TDCD2.I_Status=1
	inner join ECOMMERCE.T_Product_Master TPM on  TPM.CourseID=TDCD2.I_Course_ID
	inner join ECOMMERCE.T_Product_Center_Map TPCM2 on TPM.ProductID=TPCM2.ProductID and TPCM2.StatusID=1 and TPCM2.CenterID=@CenterID
	inner join ECOMMERCE.T_Plan_Coupon_Map TPCM on TPCM.CouponID=TCM.CouponID and TPCM.StatusID=1
	inner join ECOMMERCE.T_Plan_Product_Map TPPM on TPPM.PlanID=TPCM.PlanID and TPPM.ProductID=TPM.ProductID and TPPM.StatusID=1
	inner join ECOMMERCE.T_Coupon_Brand_Map TCBM on TCBM.CouponID=TCM.CouponID
	inner join ECOMMERCE.T_Plan_Brand_Map TPBM on TPCM.PlanID=TPBM.PlanID and TPBM.StatusID=1
	where
	TCM.StatusID=1 and TDSM.I_Status=1
	and CONVERT(DATE,TCM.ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TCM.ValidTo)>=CONVERT(DATE,GETDATE())
	and CONVERT(DATE,TDSM.Dt_Valid_From)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,TDSM.Dt_Valid_To)>=CONVERT(DATE,GETDATE())
	and TCBM.BrandID=@BrandID
	and TPBM.BrandID=@BrandID
	and TCM.CouponCategoryID=1
	and TCM.CouponCount>TCM.AssignedCount
	and TDSD.I_IsApplicableOn=@PaymentMode
	and TPM.ProductID=@ProductID
	and TPCM.PlanID=@PlanID
	and TDCD.I_Centre_ID=@CenterID
	and TCM.CouponCode=@CouponCode
	AND ISNULL(TCM.PerStudentCount,1)>@perstudentcouponcount

	PRINT @couponid

	END


	select @feeplanid=B.CourseFeePlanID from ECOMMERCE.T_Product_Center_Map A
	inner join ECOMMERCE.T_Product_FeePlan B on A.ProductCentreID=B.ProductCentreID
	inner join ECOMMERCE.T_Plan_Product_Map C on A.ProductID=C.ProductID
	where
	A.CenterID=@CenterID and A.ProductID=@ProductID and C.PlanID=@PlanID
	and C.StatusID=1

	print @feeplanid


	insert into #TblFeePlanDtls
	exec ECOMMERCE.uspGetFeePlanDiscountDetails @feeplanid,@PaymentMode,@discountschemeid,NULL


	
	

	

	if(@couponid>0)
		set @flag=1


	select @totalInstalmentPayable=SUM(ISNULL(P.PayableAmount,0)),@totalInstalmentPayableTax=SUM(ISNULL(P.PayableTax,0)) 
		from
		(
			select ISNULL(T1.Amount,0) as PayableAmount,((ISNULL(T1.Amount,0)*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from #TblFeePlanDtls A
				where A.I_Installment_No>0
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P




	IF(@PaymentMode=1)
	BEGIN
		
		select SUM(P.PayableAmount) as PayableAmount,SUM(P.PayableTax) as PayableTax, @flag as IsCouponApplicable,0 as TotalInstalmentPayable,0 as TotalInstalmentPayableTax
		from
		(
			select T1.Amount as PayableAmount,((T1.Amount*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from #TblFeePlanDtls A
				where A.I_Installment_No=0
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P

	END
	ELSE IF(@PaymentMode=2)
	BEGIN

		DECLARE @MinInstNo INT

		select @MinInstNo=MIN(I_Installment_No) from #TblFeePlanDtls where I_Installment_No>0

		select SUM(P.PayableAmount) as PayableAmount,SUM(P.PayableTax) as PayableTax, @flag as IsCouponApplicable,@totalInstalmentPayable as TotalInstalmentPayable,@totalInstalmentPayableTax as TotalInstalmentPayableTax 
		from
		(
			select T1.Amount as PayableAmount,((T1.Amount*T2.TaxRate)/100) as PayableTax
			from
			(
				select A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID,SUM(A.I_Item_Value-A.N_Discount) as Amount 
				from #TblFeePlanDtls A
				where A.I_Installment_No=@MinInstNo
				group by A.I_Course_Fee_Plan_ID,A.I_Fee_Component_ID
			) T1
			left join
			(
				select A.I_Fee_Component_ID,SUM(ISNULL(A.N_Tax_Rate,0)) as TaxRate 
				from T_Tax_Country_Fee_Component A 
				where A.Dt_Valid_To>=GETDATE()
				group by A.I_Fee_Component_ID
			) T2 on T1.I_Fee_Component_ID=T2.I_Fee_Component_ID
		) P

	END


END
GO
PRINT N'Creating Procedure [ECOMMERCE].[uspValidatePayOutPayment]...';


GO
CREATE procedure [ECOMMERCE].[uspValidatePayOutPayment](@FeeScheduleID INT,@PaidAmount DECIMAL(14,2), @PaidTax DECIMAL(14,2))
AS
BEGIN
	
	DECLARE @ErrMessage NVARCHAR(MAX)

	DECLARE @BrandID INT=NULL
	DECLARE @BrandName VARCHAR(MAX)=''
	DECLARE @StudentID VARCHAR(MAX)=NULL
	DECLARE @CourseID INT

		CREATE TABLE #Due
		(
			S_Brand_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			I_Center_ID INT,
			S_Center_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Course_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Batch_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Student_ID VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Student_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			I_Invoice_Header_ID INT,
			S_Invoice_No VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			I_Invoice_Child_Header_ID INT,
			I_Invoice_Detail_ID INT,
			Dt_Installment_Date DATETIME,
			I_Installment_No INT,
			I_Fee_Component_ID INT,
			S_Component_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			BaseAmountDue DECIMAL(14,2),
			TaxDue DECIMAL(14,2),
			TotalAmtPayable DECIMAL(14,2),
			Amount_Paid DECIMAL(14,2),
			Tax_Paid DECIMAL(14,2),
			Total_Paid DECIMAL(14,2),
			CurrentDue DECIMAL(14,2)
		)

BEGIN TRY

	BEGIN TRANSACTION

		select @BrandID=C.I_Brand_ID,@StudentID=D.S_Student_ID,@CourseID=B.I_Course_ID 
		from
		T_Invoice_Parent A
		inner join T_Invoice_Child_Header B on A.I_Invoice_Header_ID=B.I_Invoice_Header_ID and B.I_Course_ID IS NOT NULL
		inner join T_Center_Hierarchy_Name_Details C on A.I_Centre_Id=C.I_Center_ID
		inner join T_Student_Detail D on A.I_Student_Detail_ID=D.I_Student_Detail_ID
		where
		A.I_Invoice_Header_ID=@FeeScheduleID and A.I_Status in (1,3)

		PRINT @BrandID
		PRINT @StudentID
		PRINT @CourseID

		IF(@BrandID IS NULL OR @StudentID IS NULL)
		BEGIN

			SELECT @ErrMessage='Invalid FeeScheduleID: '+CAST(@FeeScheduleID AS VARCHAR(MAX))

			RAISERROR(@ErrMessage,11,1)

		END

		IF(@BrandID=109)
			set @BrandName='RICE'

		insert into #Due
		EXEC [ECOMMERCE].[uspGetIndividualStudentDueForPayOut] @BrandName,@StudentID,@FeeScheduleID

		--select * from #Due

		IF NOT EXISTS
		(
			select TOP 1 INV.I_Invoice_Header_ID 
			from
			(
				select T1.I_Invoice_Header_ID,SUM(ISNULL(T1.CurrentDue,0)) as TotalDue 
				from #Due T1
				inner join T_Invoice_Batch_Map T2 on T1.I_Invoice_Child_Header_ID=T2.I_Invoice_Child_Header_ID
				inner join T_Student_Batch_Master T3 on T2.I_Batch_ID=T3.I_Batch_ID
				group by T1.I_Invoice_Header_ID
				having SUM(T1.CurrentDue)=(@PaidAmount+@PaidTax)
			) INV
		)
		BEGIN

			SELECT @ErrMessage='Due Amount does not match Paid Amount. FeeScheduleID: '+CAST(@FeeScheduleID AS VARCHAR(MAX))

			RAISERROR(@ErrMessage,11,1)

		END

		

		

		select ISNULL(@FeeScheduleID,0) as FeeScheduleID

		COMMIT TRANSACTION

	END TRY
    BEGIN CATCH
	--Error occurred:  
        ROLLBACK TRANSACTION
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()

        RAISERROR(@ErrMsg, @ErrSeverity, 1)
    END CATCH

END
GO
PRINT N'Creating Procedure [ECOMMERCE].[uspValidateSubscriptionPayment]...';


GO
CREATE procedure [ECOMMERCE].[uspValidateSubscriptionPayment](@SubscriptionID INT, @TransactionNo VARCHAR(MAX)=NULL,@DueDate DATETIME=NULL,@FeeSchID INT=0, 
																	@PaidAmount DECIMAL(14,2), @PaidTax DECIMAL(14,2))
AS
BEGIN
	
	DECLARE @ErrMessage NVARCHAR(MAX)

	DECLARE @BrandID INT=NULL
	DECLARE @BrandName VARCHAR(MAX)=''
	DECLARE @StudentID VARCHAR(MAX)=NULL
	DECLARE @CourseID INT
	DECLARE @FeeScheduleID INT=NULL

		CREATE TABLE #Due
		(
			S_Brand_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			I_Center_ID INT,
			S_Center_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Course_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Batch_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Student_ID VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			S_Student_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			I_Invoice_Header_ID INT,
			S_Invoice_No VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			I_Invoice_Child_Header_ID INT,
			I_Invoice_Detail_ID INT,
			Dt_Installment_Date DATETIME,
			I_Installment_No INT,
			I_Fee_Component_ID INT,
			S_Component_Name VARCHAR(MAX) COLLATE DATABASE_DEFAULT,
			BaseAmountDue DECIMAL(14,2),
			TaxDue DECIMAL(14,2),
			TotalAmtPayable DECIMAL(14,2),
			Amount_Paid DECIMAL(14,2),
			Tax_Paid DECIMAL(14,2),
			Total_Paid DECIMAL(14,2),
			CurrentDue DECIMAL(14,2)
		)

BEGIN TRY

	BEGIN TRANSACTION

		IF(@TransactionNo IS NULL)
		BEGIN

			select @BrandID=T1.I_Brand_ID,@StudentID=T1.StudentID,@CourseID=T1.I_Course_ID 
			from
			(
				select A.CustomerID,C.StudentID,F.I_Brand_ID,E.I_Course_ID,D.AuthKey,D.SubscriptionDetailID,D.TotalBillingAmount,
				ISNULL(ST.PrevPaidAmount,0) as PrevPaidAmount
				from ECOMMERCE.T_Transaction_Master A
				inner join ECOMMERCE.T_Transaction_Plan_Details B on A.TransactionID=B.TransactionID
				inner join ECOMMERCE.T_Transaction_Product_Details C on B.TransactionPlanDetailID=C.TransactionPlanDetailID
				inner join ECOMMERCE.T_Transaction_Product_Subscription_Details D on C.TransactionProductDetailID=D.TransactionProductDetailID
				inner join T_Student_Batch_Master E on C.BatchID=E.I_Batch_ID
				inner join T_Course_Master F on F.I_Course_ID=E.I_Course_ID
				left join
				(
					select SubscriptionDetailID,SUM(ISNULL(TransactionAmount,0)+ISNULL(TransactionTax,0)) as PrevPaidAmount 
					from ECOMMERCE.T_Subscription_Transaction TST
					where SubscriptionDetailID=@SubscriptionID and StatusID=1
					group by SubscriptionDetailID
				) ST on D.SubscriptionDetailID=ST.SubscriptionDetailID
				where
				A.StatusID=1 and (C.StudentID IS NOT NULL and C.StudentID!='') and ISNULL(D.AuthKey,'')!='' and D.StatusID=1 
				and D.SubscriptionDetailID=@SubscriptionID
			) T1
			where
			(T1.TotalBillingAmount-T1.PrevPaidAmount)>=(@PaidAmount+@PaidTax)

			--PRINT @BrandID
			--Print @StudentID
			--Print @CourseID
			--Print @DueDate

			IF(@BrandID IS NULL OR @StudentID IS NULL)
			BEGIN

				SELECT @ErrMessage='Invalid Subscription: '+CAST(@SubscriptionID AS VARCHAR(MAX))

				RAISERROR(@ErrMessage,11,1)

			END

			IF(@BrandID=109)
				set @BrandName='RICE'

			insert into #Due
			EXEC [ECOMMERCE].[uspGetIndividualStudentDueForSubscription] @BrandName,@StudentID,@DueDate,@FeeSchID

			--select * from #Due

			select TOP 1 @FeeScheduleID= INV.I_Invoice_Header_ID 
			from
			(
				select T1.I_Invoice_Header_ID,SUM(ISNULL(T1.CurrentDue,0)) as TotalDue 
				from #Due T1
				inner join T_Invoice_Batch_Map T2 on T1.I_Invoice_Child_Header_ID=T2.I_Invoice_Child_Header_ID
				inner join T_Student_Batch_Master T3 on T2.I_Batch_ID=T3.I_Batch_ID
				where
				T3.I_Course_ID=@CourseID
				and T1.I_Invoice_Header_ID=@FeeSchID
				group by T1.I_Invoice_Header_ID
				having SUM(T1.CurrentDue)>=(@PaidAmount+@PaidTax)
			) INV


			IF(@FeeScheduleID IS NULL)
			BEGIN

				SELECT @ErrMessage='Due Amount is less than Paid Amount. SubscriptionID: '+CAST(@SubscriptionID AS VARCHAR(MAX))

				RAISERROR(@ErrMessage,11,1)

			END

		

		END
		ELSE IF(ISNULL(@TransactionNo,'')!='')
		BEGIN

			select @BrandID=T1.I_Brand_ID,@StudentID=T1.StudentID,@CourseID=T1.I_Course_ID 
			from
			(
				select A.CustomerID,C.StudentID,F.I_Brand_ID,E.I_Course_ID,D.AuthKey,D.SubscriptionDetailID,D.TotalBillingAmount,
				ISNULL(ST.PrevPaidAmount,0) as PrevPaidAmount
				from ECOMMERCE.T_Transaction_Master A
				inner join ECOMMERCE.T_Transaction_Plan_Details B on A.TransactionID=B.TransactionID
				inner join ECOMMERCE.T_Transaction_Product_Details C on B.TransactionPlanDetailID=C.TransactionPlanDetailID
				inner join ECOMMERCE.T_Transaction_Product_Subscription_Details D on C.TransactionProductDetailID=D.TransactionProductDetailID
				inner join T_Student_Batch_Master E on C.BatchID=E.I_Batch_ID
				inner join T_Course_Master F on F.I_Course_ID=E.I_Course_ID
				left join
				(
					select SubscriptionDetailID,SUM(ISNULL(TransactionAmount,0)+ISNULL(TransactionTax,0)) as PrevPaidAmount 
					from ECOMMERCE.T_Subscription_Transaction TST
					where SubscriptionDetailID=@SubscriptionID and StatusID=1 and TST.TransactionNo NOT IN (@TransactionNo)
					group by SubscriptionDetailID
				) ST on D.SubscriptionDetailID=ST.SubscriptionDetailID
				where
				A.StatusID=1 and (C.StudentID IS NOT NULL and C.StudentID!='') and ISNULL(D.AuthKey,'')!='' and D.StatusID=1 
				and D.SubscriptionDetailID=@SubscriptionID
			) T1
			where
			(T1.TotalBillingAmount-T1.PrevPaidAmount)>=(@PaidAmount+@PaidTax)

			IF(@BrandID IS NULL OR @StudentID IS NULL)
			BEGIN

				SELECT @ErrMessage='Invalid Subscription'

				RAISERROR(@ErrMessage,11,1)

			END

			IF(@BrandID=109)
				set @BrandName='RICE'

			insert into #Due
			EXEC [ECOMMERCE].[uspGetIndividualStudentDueForSubscription] @BrandName,@StudentID,NULL,@FeeSchID

			select TOP 1 @FeeScheduleID=INV.I_Invoice_Header_ID 
			from
			(
				select T1.I_Invoice_Header_ID,SUM(ISNULL(T1.CurrentDue,0)) as TotalDue 
				from #Due T1
				inner join T_Invoice_Batch_Map T2 on T1.I_Invoice_Child_Header_ID=T2.I_Invoice_Child_Header_ID
				inner join T_Student_Batch_Master T3 on T2.I_Batch_ID=T3.I_Batch_ID
				where
				T3.I_Course_ID=@CourseID
				and T1.I_Invoice_Header_ID=@FeeSchID
				group by T1.I_Invoice_Header_ID
				having SUM(T1.CurrentDue)>=(@PaidAmount+@PaidTax)
			) INV


			IF(@FeeScheduleID IS NULL)
			BEGIN

				SELECT @ErrMessage='Due Amount is less than Paid Amount'

				RAISERROR(@ErrMessage,11,1)

			END

		

		END

		select ISNULL(@FeeScheduleID,0) as FeeScheduleID

		COMMIT TRANSACTION

	END TRY
    BEGIN CATCH
	--Error occurred:  
        ROLLBACK TRANSACTION
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()

        RAISERROR(@ErrMsg, @ErrSeverity, 1)
    END CATCH

END
GO
PRINT N'Creating Procedure [EOS].[uspActivateEmployeeBatch]...';


GO
CREATE PROCEDURE [EOS].[uspActivateEmployeeBatch] 
(
	@iFacultyRoleID INT = NULL
)
AS

BEGIN TRY
BEGIN TRAN T1

	SET NOCOUNT ON;

	Declare @I_Process_ID_Max Int
	Declare @Comments Varchar(2000)
	Declare @Center_Name Varchar(500)
	Declare @Employee_Name Varchar(500)
	Declare @Role_Name Varchar(500)
	Declare @fnCheckEmployeeExamStatus Varchar(500)
	Declare @fnCheckEmployeeTrainingStatus Varchar(500)

	--Declare @I_Batch_Process_ID Int
	--Select @I_Batch_Process_ID=I_Batch_Process_ID From dbo.T_Batch_Master Where S_Batch_Process_Name='EMPLOYEE_ACTIVATION' And I_Status=1

	--Select @I_Process_ID_Max=ISNULL(Max(I_Process_ID),0)+1 From dbo.T_Batch_Log Where S_Batch_Process_Name='EMPLOYEE_ACTIVATION'
	
	DECLARE @iCount INT, @iRoleCounter INT, @sRoles VARCHAR(1000), @iEmpID INT, @iUserID INT,
			 @iActualRowCount INT, @iRoleRowCount INT, @iRoleID INT, @iCenterID INT, @iRolePassCount INT
	SET @iCount = 1
	SET @iRoleCounter = 1
	
	CREATE TABLE #tempEmployee
	(	
		ID INT IDENTITY(1,1),
		I_Emp_ID INT,
		I_User_ID INT,
		S_Employee_Roles VARCHAR(1000)		
	)
	
	CREATE TABLE #tempRoles
	(
		ID INT IDENTITY(1,1),
		I_Role_ID INT
	)
	
	INSERT INTO #tempEmployee
	SELECT	EMP.I_Employee_ID,
			U.I_User_ID,
			EOS.[fnEmployeeRoleDetails](EMP.I_Employee_ID)			
	FROM dbo.T_Employee_Dtls EMP WITH(NOLOCK)
	INNER JOIN dbo.T_User_Master U WITH(NOLOCK)
		ON U.I_Reference_ID = EMP.I_Employee_ID AND S_User_Type = 'CE'
	WHERE (EMP.I_Status = 2 OR EMP.I_Status = 6 OR EMP.I_Status = 3)--for Employees with status Active and Additional Roles Assigned
		AND EOS.[fnEmployeeRoleDetails](EMP.I_Employee_ID) <> [EOS].[fnUserRoleDetails](U.I_User_ID)
		AND LTRIM(RTRIM(EOS.[fnEmployeeRoleDetails](EMP.I_Employee_ID)))<>''
	
	SELECT @iActualRowCount = COUNT(ID) FROM #tempEmployee
	
	WHILE (@iCount <= @iActualRowCount)
	BEGIN
		SELECT	@sRoles = S_Employee_Roles,
				@iEmpID = I_Emp_ID,
				@iUserID = I_User_ID
		FROM #tempEmployee WHERE ID = @iCount
		
		SELECT @iCenterID = I_Centre_ID FROM dbo.T_Employee_Dtls WHERE I_Employee_ID = @iEmpID
		
		SET @sRoles = SUBSTRING(@sRoles,2,LEN(@sRoles) - 2)
		
		INSERT INTO #tempRoles
		SELECT * FROM dbo.fnString2Rows(@sRoles,',')
	
		SELECT @iRoleRowCount = COUNT(ID) FROM #tempRoles
		SET @iRolePassCount = 0
		
		WHILE (@iRoleCounter <= @iRoleRowCount)
		BEGIN
			SELECT @iRoleID = I_Role_ID FROM #tempRoles WHERE ID = @iRoleCounter
		
			SELECT @CENTER_NAME=S_CENTER_NAME FROM dbo.T_CENTRE_MASTER WHERE I_CENTRE_ID=@ICENTERID
			SELECT @Employee_Name=ISNULL(S_FIRST_NAME,'')+' '+ISNULL(S_MIDDLE_NAME,'')+' '+ISNULL(S_LAST_NAME,'') FROM dbo.T_EMPLOYEE_DTLS WHERE I_Employee_ID = @iEmpID
			SELECT @Role_Name=S_Role_Desc FROM dbo.T_Role_Master WHERE I_Role_ID=@iRoleID

			IF ((EOS.fnCheckEmployeeExamStatus(@iEmpID,@iRoleID,@iCenterID,@iFacultyRoleID) = 1) AND (EOS.fnCheckEmployeeTrainingStatus(@iEmpID,@iRoleID,@iFacultyRoleID) = 1))
				BEGIN
					UPDATE dbo.T_Employee_Dtls SET I_Status = 6, S_Upd_By = 'SYSTEM_BATCH', Dt_Upd_On = GETDATE() WHERE I_Employee_ID = @iEmpID
					UPDATE dbo.T_User_Master SET S_User_Type = 'CE', S_Upd_By = 'SYSTEM_BATCH', Dt_Upd_On = GETDATE() WHERE I_Reference_ID = @iEmpID AND S_User_Type NOT IN ('ST','EM')
	--				UPDATE dbo.T_User_Role_Details SET I_Status = 0 WHERE I_User_ID = @iUserID AND I_Role_ID = @iFacultyRoleID
				
					-------------------Update the User Role Table--------------------
					IF EXISTS(SELECT * FROM dbo.T_User_Role_Details	WHERE I_User_ID = @iUserID AND I_Role_ID = @iRoleID)
					BEGIN
						UPDATE	dbo.T_User_Role_Details
						SET		I_Status = 1, S_Upd_By = 'SYSTEM_BATCH', Dt_Upd_On = GETDATE()
						WHERE	I_User_ID = @iUserID
							AND	I_Role_ID = @iRoleID
					END
					ELSE
					BEGIN
						INSERT INTO dbo.T_User_Role_Details
							(	
								I_Role_ID, 
								I_User_ID,
								I_Status, 
								S_Crtd_By, 
								Dt_Crtd_On 
							)
						SELECT @iRoleID,@iUserID,1,'SYSTEM_BATCH',GETDATE()
					END
										
					Set @Comments=@Center_Name+'('+cast(@iCenterID as varchar)+')> '+@Employee_Name+'('+cast(@iUserID as varchar)+')> '+@Role_Name+'('+cast(@iRoleID as varchar)+') - Activated'
					--EXEC uspWriteBatchProcessLog_New @I_Process_ID_Max,'EMPLOYEE_ACTIVATION',@Comments,'Success',0
					
					SET @iRolePassCount = @iRolePassCount + 1
				END
			ELSE
				BEGIN
					IF(EOS.fnCheckEmployeeExamStatus(@iEmpID,@iRoleID,@iCenterID,@iFacultyRoleID) = 0)
					BEGIN
						SET @fnCheckEmployeeExamStatus='Exam Not Cleared'
					END

					IF(EOS.fnCheckEmployeeTrainingStatus(@iEmpID,@iRoleID,@iFacultyRoleID) = 0)
					BEGIN
						SET @fnCheckEmployeeTrainingStatus='Training nor Cleared'
					END
					
					Set @Comments=@Center_Name+'('+cast(@iCenterID as varchar)+')> '+@Employee_Name+'('+cast(@iUserID as varchar)+')> '+@Role_Name+'('+cast(@iRoleID as varchar)+') - Not Activated because '+@fnCheckEmployeeExamStatus+','+@fnCheckEmployeeTrainingStatus
					--EXEC uspWriteBatchProcessLog_New @I_Process_ID_Max,'EMPLOYEE_ACTIVATION',@Comments,'Faliure',0
				END
								
			SET @iRoleCounter = @iRoleCounter + 1
		END
		
		IF (@iRoleRowCount = @iRolePassCount)
		BEGIN
			UPDATE dbo.T_Employee_Dtls SET I_Status = 3, S_Upd_By = 'SYSTEM_BATCH', Dt_Upd_On = GETDATE() WHERE I_Employee_ID = @iEmpID
		END
		
		TRUNCATE TABLE #tempRoles
		SET @iRoleCounter = 1
		SET @iCount = @iCount + 1
	END
	
	TRUNCATE TABLE #tempEmployee
	
COMMIT TRAN T1
END TRY

BEGIN CATCH
--Error occurred:
	ROLLBACK  TRAN T1
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT @ErrMsg = ERROR_MESSAGE(),
	@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [EOS].[uspCheckResitAllowedAndTestDesign]...';


GO
CREATE PROCEDURE [EOS].[uspCheckResitAllowedAndTestDesign]
(
	@iEmployeeID INT,
	@iExamComponentID INT
)
AS
BEGIN

	DECLARE @N_FULL_MARKS INT
	DECLARE @N_MARKS_CUTOFF INT
	DECLARE @N_PASS_MARKS INT
	DECLARE @N_MAXIMUM_RESIT_ALLOWED INT
	DECLARE @N_ALREADY_APPEARED INT
	DECLARE @SkillCleared CHAR(1)

	CREATE TABLE #TAB
	(
		cTEstDegnPresent CHAR(1),
		cResitAllowed CHAR(1),
		iFullMarks INT,
		cSkillCleared CHAR(1)
	)
		
	INSERT INTO #TAB VALUES(NULL,NULL,NULL,NULL)

	SET NOCOUNT ON;

	SELECT @N_FULL_MARKS=SUM(ISNULL(N_MARKS,0)*ISNULL(I_NO_OF_QUESTIONS,0)) FROM EXAMINATION.T_TEST_DESIGN_PATTERN WHERE I_TEST_DESIGN_ID IN
	(
		SELECT I_TEST_DESIGN_ID FROM EXAMINATION.T_TEST_DESIGN WHERE I_EXAM_COMPONENT_ID=@iExamComponentID
	)

	IF (@N_FULL_MARKS IS NOT NULL)
		BEGIN
			UPDATE #TAB SET cTEstDegnPresent='Y',iFullMarks=@N_FULL_MARKS
		END
	ELSE
		BEGIN
			UPDATE #TAB SET cTEstDegnPresent='N'
		END

	--CENTER
	SELECT @N_MAXIMUM_RESIT_ALLOWED=I_Number_Of_Resits FROM EOS.T_Skill_Exam_Map WHERE [I_Exam_Component_ID]=@iExamComponentID
	AND [I_Centre_ID] IN
	(
		SELECT [I_CENTRE_ID] FROM [T_EMPLOYEE_DTLS] WHERE [I_EMPLOYEE_ID]=@iEmployeeID
	)

	--GLOBAL
	IF( @N_MAXIMUM_RESIT_ALLOWED IS NULL)
	BEGIN
		SELECT @N_MAXIMUM_RESIT_ALLOWED=I_Number_Of_Resits FROM EOS.T_Skill_Exam_Map WHERE [I_Exam_Component_ID]=@iExamComponentID
		AND [I_Centre_ID] IS NULL
	END

	SELECT @N_ALREADY_APPEARED=COUNT(*) FROM [EOS].[T_Employee_Exam_Result] WHERE [I_Employee_ID]=@iEmployeeID AND [I_Exam_Component_ID]=@iExamComponentID
	
	IF(@N_MAXIMUM_RESIT_ALLOWED<=@N_ALREADY_APPEARED)
		BEGIN
			UPDATE #TAB SET cResitAllowed='N'
		END
	ELSE
		BEGIN
			UPDATE #TAB SET cResitAllowed='Y'
		END

	SELECT @SkillCleared=[I_Status] FROM EOS.T_Employee_Skill_Map WHERE [I_Employee_ID]=@iEmployeeID AND [I_Skill_ID] IN(SELECT [I_Skill_ID]
	FROM  EOS.[T_Skill_Exam_Map] WHERE [I_Exam_Component_ID]=@iExamComponentID AND [I_Status]=1 )

	IF (@SkillCleared=1)
		BEGIN
			UPDATE #TAB SET cSkillCleared='Y'
		END
	ELSE
		BEGIN
			UPDATE #TAB SET cSkillCleared='N'
		END

	SELECT * FROM #TAB
	DROP TABLE #TAB

END
GO
