CREATE PROCEDURE [EOS].[uspGetEmployeeListForActivation]
(	
 @iCenterID INT,
 @iStatus INT = NULL
)
	
AS
BEGIN
	SELECT  TED.I_Employee_ID,
		TED.I_Centre_Id,
		TED.S_Title,
		TED.S_First_Name,
		TED.S_Middle_Name,
		TED.S_Last_Name,
		TUM.I_User_ID,
		TUM.S_Login_ID,
		TUM.S_User_Type,
		TED.I_Status
	FROM dbo.T_Employee_Dtls TED WITH(NOLOCK) 
