PRINT N'Creating Procedure [EOS].[uspGetUserOnHierarchyRoleWise]...';


GO
/*****************************************************************************************************************            
Created by: Utpal      
Date: 18/08/2011          
Description: GET User Details For Video List         
Parameters:             
Returns:             
Modified By:             
******************************************************************************************************************/            
    
CREATE PROCEDURE [EOS].[uspGetUserOnHierarchyRoleWise] --1204,'2,3,8'             
(                    
 -- Add the parameters for the stored procedure here                    
 @iHierarchyDetailID INT,            
 @sRoleIDs VARCHAR(50) = NULL                      
)                    
AS                    
BEGIN         
        
  
SELECT DISTINCT tum.I_User_ID,tum.S_First_Name,tum.S_Middle_Name,tum.S_Last_Name,tuhd.I_Hierarchy_Detail_ID,thd.S_Hierarchy_Name,turd.I_Role_ID,trm.S_Role_Code    
INTO #temp     
FROM dbo.T_User_Master AS tum    
INNER JOIN dbo.T_User_Hierarchy_Details AS tuhd    
ON tum.I_User_ID = tuhd.I_User_ID    
INNER JOIN dbo.T_Hierarchy_Details AS thd      
ON tuhd.I_Hierarchy_Detail_ID = thd.I_Hierarchy_Detail_ID    
INNER JOIN dbo.T_User_Role_Details AS turd    
ON tum.I_User_ID = turd.I_User_ID    
INNER JOIN dbo.T_Role_Master AS trm    
ON turd.I_Role_ID = trm.I_Role_ID    
WHERE tuhd.I_Hierarchy_Detail_ID IN (SELECT I_Hierarchy_Detail_ID FROM dbo.T_Hierarchy_Mapping_Details AS THMD WHERE THMD.S_Hierarchy_Chain  LIKE '%' + CAST(@iHierarchyDetailID AS VARCHAR(10)) + '%' )     
AND turd.I_Role_ID IN (SELECT * FROM dbo.fnString2Rows(@sRoleIDs,',') AS fsr)    
    
SELECT  DISTINCT t2.I_User_ID,t2.S_First_Name,t2.S_Middle_Name,t2.S_Last_Name,t2.I_Hierarchy_Detail_ID,t2.S_Hierarchy_Name ,    
 RoleIds = STUFF((SELECT ','+CAST(t1.I_Role_ID AS VARCHAR(5))      
 FROM #temp AS t1      
 WHERE  t1.I_User_ID = t2.I_User_ID    
 ORDER BY t1.I_User_ID      
 FOR XML PATH('')),1,1,'')   ,    
 RoleName = STUFF((SELECT ', '+t1.S_Role_Code      
 FROM #temp AS t1      
 WHERE t1.I_User_ID = t2.I_User_ID    
 ORDER BY t1.I_User_ID      
 FOR XML PATH('')),1,1,'')    
     
 FROM #temp AS t2    
       
DROP TABLE #temp      
      
END
GO
PRINT N'Creating Procedure [EOS].[uspModifyKRAMaster]...';


GO
-- ===========================================================
-- Author:		Swagatam Sarkar
-- Create date: 27/11/2007
-- Description:	Modifies the KRA Master
-- ===========================================================

CREATE PROCEDURE [EOS].[uspModifyKRAMaster] 
(
	@iKRAID int = null,
	@iKRAIndexID int = NULL,
	@sKRADesc varchar(200),
	@iKRAType int = NULL,
	@sCreatedBy varchar(50),
	@dtCreatedOn datetime,
    @iFlag int
)
AS
BEGIN TRY

	SET NOCOUNT OFF;
	DECLARE @iResult INT
	
	set @iResult = 0 -- set to default zero 

    IF @iFlag = 1
	BEGIN
		INSERT INTO EOS.T_KRA_Master(I_KRA_Index_ID, S_KRA_Desc, I_KRA_Type, I_Status, S_Crtd_By, Dt_Crtd_On)
		VALUES(@iKRAIndexID, @sKRADesc, @iKRAType, 1, @sCreatedBy, @dtCreatedOn)   
		SET @iResult = 1  -- Insertion successful 
	END
	ELSE IF @iFlag = 2
	BEGIN
		UPDATE EOS.T_KRA_Master
		SET I_KRA_Index_ID = @iKRAIndexID,
		S_KRA_Desc = @sKRADesc,
		I_KRA_Type = @iKRAType,
		S_Upd_By = @sCreatedBy,
		Dt_Upd_On = @dtCreatedOn
		where  I_KRA_ID = @iKRAID
		SET @iResult = 1  -- Updation successful
	END
	-- Deletion of Master Data
	ELSE IF @iFlag = 3
	BEGIN
		IF EXISTS(SELECT I_KRA_ID FROM EOS.T_KRA_Master WHERE I_KRA_ID = @iKRAID)
			BEGIN
				UPDATE EOS.T_KRA_Master
				SET I_Status = 0,
				S_Upd_By = @sCreatedBy,
				Dt_Upd_On = @dtCreatedOn
				where I_KRA_ID = @iKRAID
				SET @iResult = 1  -- Deletion successful
			END
	END
	SELECT @iResult Result
END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [EOS].[uspModifyMeasuringIndex]...';


GO
-- ===========================================================
-- Author:		Swagatam Sarkar
-- Create date: 26/11/2007
-- Description:	Modifies the Measuring Index of KRA's
-- ===========================================================

CREATE PROCEDURE [EOS].[uspModifyMeasuringIndex] 
(
	@iKRAIndexID int = NULL,
	@sMeasuringIndex varchar(200),
	@sCreatedBy varchar(50),
	@dtCreatedOn datetime,
    @iFlag int
)
AS
BEGIN TRY

	SET NOCOUNT OFF;
	DECLARE @iResult INT
	
	set @iResult = 0 -- set to default zero 

    IF @iFlag = 1
	BEGIN
		INSERT INTO EOS.T_KRA_Index_Master(S_KRA_Index_Desc, I_Status, S_Crtd_By, Dt_Crtd_On)
		VALUES(@sMeasuringIndex, 1, @sCreatedBy, @dtCreatedOn)   
		SET @iResult = 1  -- Insertion successful 
	END
	ELSE IF @iFlag = 2
	BEGIN
		UPDATE EOS.T_KRA_Index_Master
		SET S_KRA_Index_Desc = @sMeasuringIndex,
		S_Upd_By = @sCreatedBy,
		Dt_Upd_On = @dtCreatedOn
		where  I_KRA_Index_ID = @iKRAIndexID
		SET @iResult = 1  -- Updation successful
	END
	-- Deletion of Master Data
	-- Check if the required value is used, if yes - deletion not allowed
	ELSE IF @iFlag = 3
	BEGIN
		IF NOT EXISTS(SELECT I_KRA_Index_ID FROM EOS.T_Role_KRA_Map WHERE I_KRA_Index_ID = @iKRAIndexID)
			BEGIN
				UPDATE EOS.T_KRA_Index_Master
				SET I_Status = 0,
				S_Upd_By = @sCreatedBy,
				Dt_Upd_On = @dtCreatedOn
				where I_KRA_Index_ID = @iKRAIndexID
				SET @iResult = 1  -- Deletion successful
			END
		ELSE
			BEGIN
				SET @iResult = 2  -- Deletion not allowed due to Foreign Key Constraint
			END
	END
	SELECT @iResult Result
END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
