		AND tttm.I_Transaction_Nature_ID = 6
	WHERE DATEDIFF(dd,trh.Dt_Receipt_Date,@dtExecutionDate) = 0
	AND trh.I_Invoice_Header_ID IS NULL
	AND tbcd.I_Brand_ID=@iBrandID
	
	END
		
END
