CREATE PROCEDURE [EXAMINATION].[uspGetAISStudentMarksForAPI_WithStudentCourseBatchDetails20221412](@BrandID INT, @CentreID INT, @CourseID INT, @StudentDetailID INT, @TermID INT=NULL)
AS
BEGIN

--EXEC EXAMINATION.uspGetStudentMarksForAPI @BrandID = 107,@CentreID = 1,@BatchID = 9677, @StudentDetailID=44354-- int

CREATE TABLE #temp
(
StudentID VARCHAR(MAX),
StudentDetailID INT,
