HighestGrade VARCHAR(10),
SequenceNo INT,
TermAttendance INT,
NoofDays INT,
CumMarks DECIMAL(14,2),
ClassTeacherRemarks VARCHAR(MAX),
Student_Rank INT
)

CREATE TABLE #tblGradeMst 
