        ( FromMarks, ToMarks, Grade ) 
VALUES  ( 60, 69, 'B' ) 
INSERT  INTO #tblGradeMst 
        ( FromMarks, ToMarks, Grade ) 
VALUES  ( 70, 79, 'B+' ) 
INSERT  INTO #tblGradeMst 
        ( FromMarks, ToMarks, Grade ) 
VALUES  ( 80, 89, 'A' ) 
INSERT  INTO #tblGradeMst 
        ( FromMarks, ToMarks, Grade ) 
VALUES  ( 90, 100, 'A+' ) 



