CREATE PROCEDURE [EXAMINATION].[uspGetBulkAISStudentMarksForAPI](@BrandID INT, @CentreID INT, @CourseID INT,@BatchID INT, @StudentDetailIDList VARCHAR(MAX)=NULL, @TermID INT=NULL)
