IF(@StudentDetailIDList IS NOT NULL)
BEGIN

	insert into @Std
	select CAST(Val as INT) from fnString2Rows(@StudentDetailIDList,',')

END
ELSE
BEGIN

	insert into @Std
	SELECT DISTINCT TSBD.I_Student_ID 
	FROM 
	dbo.T_Student_Batch_Details AS TSBD
	INNER JOIN
	(
		SELECT TSBM.I_Course_ID,TSBD.I_Student_ID,MAX(TSBD.I_Student_Batch_ID) AS StdBatchID 
		FROM dbo.T_Student_Batch_Details AS TSBD
		INNER JOIN dbo.T_Student_Batch_Master AS TSBM ON TSBM.I_Batch_ID = TSBD.I_Batch_ID
		WHERE TSBD.I_Status IN (0,1,2) AND TSBM.I_Course_ID=@CourseID
		GROUP BY TSBM.I_Course_ID,TSBD.I_Student_ID
	) T1 ON TSBD.I_Student_Batch_ID=T1.StdBatchID
	where
	TSBD.I_Batch_ID=@BatchID

END


