       T.CourseID,
       T.BatchID,
       T.TermID,
       T.TermName,
       T.ModuleID,
       T.ModuleName,
       T.ExamComponentID,
       REPLACE(REPLACE(REPLACE(T.ExamComponentName,'T_',''),'N_',''),'K_','') AS ExamComponentName,
	   REPLACE(T.SubExamComponentName,'_T2','') as SubExamComponentName,
