 SELECT TSBD.I_Student_ID AS Student_ID,TSD.S_Student_ID,TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,'') + ' ' + TSD.S_Last_Name AS [StudentName],    
 TSD.I_RollNo AS RollNo,  
 THS.Dt_Submission_Date AS SubmissionDate ,  
