PRINT N'Creating Procedure [EXAMINATION].[uspSaveAssessmentExam]...';


GO
/**************************************************************************************************************              
Created by  : Soumyopriyo              
Date  : 25.06.2011              
Description : This SP will save the user response of the online exam              
Parameters  : iExamComponentID              
Returns     : Dataset              
**************************************************************************************************************/              
              
CREATE PROCEDURE [EXAMINATION].[uspSaveAssessmentExam]              
(              
 @iExamComponentID INT,              
 @iEnquiryID INT = NULL,              
 @DtTestDate DATETIME,              
 @N_Marks NUMERIC(8,2),              
 @B_Has_Passed BIT,              
 @sAnswer XML = NULL,              
 @sCreatedBy VARCHAR(20) = NULL,              
 @sUpdatedBy VARCHAR(20) = NULL,              
 @dtCreatedOn DATETIME = NULL,              
 @dtUpdatedOn DATETIME = NULL      
)              
AS              
BEGIN TRY            
BEGIN TRAN T1           
 --INSERT INTO dbo.T_Enquiry_Test VALUES (@iExamComponentID,@iEnquiryRegnID,@DtTestDate,@N_Marks,@sAnswer)              
 IF EXISTS(SELECT * FROM EOS.T_Employee_Exam_Result               
    WHERE I_Enquiry_Regn_ID= @iEnquiryID AND I_Exam_Component_ID = @iExamComponentID              
    AND DATEDIFF(ss, Dt_Crtd_On, @DtTestDate) = 0)              
 BEGIN              
  UPDATE EOS.T_Employee_Exam_Result              
   SET I_No_Of_Attempts = ISNULL(I_No_Of_Attempts,0) + 1,              
    N_Marks = @N_Marks,              
    B_Passed = @B_Has_Passed,              
    S_Answer_XML = @sAnswer,              
    S_Upd_By = @sUpdatedBy,              
    Dt_Upd_On = @dtUpdatedOn              
  WHERE I_Enquiry_Regn_ID = @iEnquiryID              
   AND I_Exam_Component_ID = @iExamComponentID              
   AND DATEDIFF(ss, Dt_Crtd_On, @DtTestDate) = 0              
 END              
 ELSE              
 BEGIN              
  INSERT INTO EOS.T_Employee_Exam_Result              
  (I_Enquiry_Regn_ID, I_Exam_Component_ID, I_No_Of_Attempts, N_Marks, B_Passed, S_Answer_XML,S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On)               
  VALUES(@iEnquiryID,@iExamComponentID,1,@N_Marks,@B_Has_Passed,@sAnswer,@sCreatedBy,@sUpdatedBy,@dtCreatedOn,@dtUpdatedOn)              
 END              
       
 UPDATE ASSESSMENT.T_Student_Assessment_Map SET B_Is_Complete = 1,Total_Marks = @N_Marks WHERE I_Exam_Component_ID = @iExamComponentID AND I_Enquiry_Regn_ID = @iEnquiryID          
   
 COMMIT TRAN T1          
     
END TRY          
BEGIN CATCH              
 --Error occurred:                
 ROLLBACK TRAN T1             
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int              
 SELECT @ErrMsg = ERROR_MESSAGE(),              
   @ErrSeverity = ERROR_SEVERITY()              
              
 RAISERROR(@ErrMsg, @ErrSeverity, 1)              
END CATCH
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveBankPoolMapping]...';


GO
/**************************************************************************************************************
Created by  : Swagata De
Date		: 09.05.2007
Description : This SP will save the new question bank pool mapping
Parameters  : 
Returns     : 
**************************************************************************************************************/

CREATE PROCEDURE [EXAMINATION].[uspSaveBankPoolMapping]
	(
		@iQuestionBankID INT,
		@sQuestionPoolXML XML ,
		@sCreatedBy VARCHAR(20),
		@DtCreatedOn DATETIME ,
		@sUpdatedBy VARCHAR(20),
		@DtUpdatedOn DATETIME 
		
	)
AS

BEGIN TRY
	SET NOCOUNT ON;	
	DECLARE
	@AdjPosition SMALLINT, 
	@AdjCount SMALLINT,
	@KeyValueXml XML ,
	@iQPoolID INT, 
    @sQPoolDesc VARCHAR(200)
    
    DELETE FROM EXAMINATION.T_Bank_Pool_Mapping 
	WHERE I_Question_Bank_ID=@iQuestionBankID
	
	SET @AdjPosition = 1
	SET @AdjCount = @sQuestionPoolXML.value('count((QPoolList/QPool))','int')
	
	WHILE(@AdjPosition<=@AdjCount)
	BEGIN		
		--Get the Adjustment node for the Current Position
			SET @KeyValueXml = @sQuestionPoolXML.query('/QPoolList/QPool[position()=sql:variable("@AdjPosition")]')
			SELECT	@iQPoolID = T.a.value('@I_Pool_ID','int'),
					@sQPoolDesc = T.a.value('@S_Pool_Desc','varchar(200)')		
			FROM @KeyValueXml.nodes('/QPool') T(a)
			
			--Add the new mapping entries
		INSERT INTO EXAMINATION.T_Bank_Pool_Mapping 
		(
			I_Pool_ID,
			I_Question_Bank_ID,
			S_Crtd_By,
			S_Upd_By,
			Dt_Crtd_On,
			Dt_Upd_On
		)
		VALUES
		(
		@iQPoolID,
		@iQuestionBankID,
		@sCreatedBy,
		@sUpdatedBy,
		@DtCreatedOn,
		@DtUpdatedOn
		)	
		SET @AdjPosition = @AdjPosition + 1		
	
  END
	
	
	
	
		 
END TRY	
	
BEGIN CATCH
--Error occurred:  

DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
SELECT	@ErrMsg = ERROR_MESSAGE(),
		@ErrSeverity = ERROR_SEVERITY()

RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveEligibilityList]...';


GO
/**************************************************************************************************************
Created by  : Debarshi Basu
Date		: 09.05.2007
Description : This SP will save the Eligibility List for Examination
Parameters  : 
Returns     : 
**************************************************************************************************************/
CREATE PROCEDURE [EXAMINATION].[uspSaveEligibilityList] 
	@iExamID int,
	@sRegistrationNumber VARCHAR(20),
	@sStudentList xml,
	@sCreatedBy varchar(20),
	@DtCreatedOn datetime,
	@sUpdatedBy  varchar(20),
	@DtUpdatedOn datetime
AS
BEGIN

	CREATE TABLE #tempTable
	(            
		I_Student_Detail_ID int
	)

	INSERT INTO #tempTable
	SELECT T.c.value('@ID','int')     
	FROM   @sStudentList.nodes('/Registration/Student') T(c)

	DELETE FROM EXAMINATION.T_Eligibility_List
	WHERE I_Student_Detail_ID NOT IN 
		(SELECT I_Student_Detail_ID FROM #tempTable )
		AND I_Exam_ID = @iExamID
	
	INSERT INTO EXAMINATION.T_Eligibility_List
	(I_Student_Detail_ID,
	I_Exam_ID,
	S_Registration_No,
	S_Crtd_By,
	S_Upd_By,
	Dt_Crtd_On,
	Dt_Upd_On,
	C_Appeared_For_Exam)
	SELECT I_Student_Detail_ID,
	@iExamID,null,@sCreatedBy,@sUpdatedBy,
	@DtCreatedOn,@DtUpdatedOn,'N'
	FROM #tempTable
	WHERE I_Student_Detail_ID NOT IN 
	(SELECT I_Student_Detail_ID FROM EXAMINATION.T_Eligibility_List WHERE I_Exam_ID = @iExamID)

	TRUNCATE TABLE #tempTable
	DROP TABLE #tempTable

END
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveExamDesign]...';


GO
CREATE PROCEDURE [EXAMINATION].[uspSaveExamDesign]
	@iExamComponentID int,
	@iEvalStrategyID int = NULL,
	@sQuestionBankID varchar(500),
	@sQuestionPattern xml,
	@sCreatedBy varchar(20),
	@DtCreatedOn datetime,
	@sUpdatedBy  varchar(20),
	@DtUpdatedOn datetime,
	@iCourseID int,
	@iTermID int,
	@iModuleID int
AS
BEGIN
	DECLARE @iTestDesignID INT, @RowCount INT, @iCourseFamilyID INT, @iBrandID INT, @iCertificateID INT
	
	SELECT	@iBrandID = I_Brand_ID,
			@iCourseFamilyID = I_CourseFamily_ID,
			@iCertificateID = I_Certificate_ID
	FROM
		dbo.T_Course_Master WITH(NOLOCK)
	WHERE	I_Course_ID = @iCourseID
		
	DECLARE @tblCourse TABLE(I_Course_ID INT)
	
	INSERT INTO @tblCourse
	SELECT I_Course_ID FROM dbo.T_Course_Master 
	WHERE	I_Brand_ID = @iBrandID
		AND I_CourseFamily_ID = @iCourseFamilyID
		AND I_Certificate_ID = ISNULL(@iCertificateID,I_Certificate_ID)
		
	DECLARE @tblEvalStrategy TABLE(ID INT IDENTITY(1,1), I_Eval_Strategy_ID INT)
	
	IF (@iModuleID IS NULL OR @iModuleID = 0)
		BEGIN
			INSERT INTO @tblEvalStrategy
			SELECT I_Term_Strategy_ID 
			FROM dbo.T_Term_Eval_Strategy TES WITH(NOLOCK)
			INNER JOIN @tblCourse TC
			ON TES.I_Course_ID = TC.I_Course_ID
			WHERE	I_Term_ID = @iTermID
			AND I_Exam_Component_ID = @iExamComponentID
		END
	ELSE
		BEGIN
			INSERT INTO @tblEvalStrategy
			SELECT I_Module_Strategy_ID 
			FROM dbo.T_Module_Eval_Strategy TMS WITH(NOLOCK)
			INNER JOIN @tblCourse TC
			ON TMS.I_Course_ID = TC.I_Course_ID
			WHERE	I_Term_ID = @iTermID
			AND		I_Module_ID = @iModuleID
			AND I_Exam_Component_ID = @iExamComponentID
		END
						
--	Before any update insert the values in the Audit table
	INSERT INTO EXAMINATION.T_Test_Design_Audit
	(I_Test_Design_ID,I_Exam_Component_ID,I_Eval_Strategy_ID,
	I_Bank_Pool_Mapping_ID,I_No_Of_Questions,I_Complexity_ID,N_Marks,
	I_Status_ID,S_Crtd_By,S_Upd_by,Dt_Crtd_On,Dt_Upd_On)
	SELECT 
	TD.I_Test_Design_ID,TD.I_Exam_Component_ID,TD.I_Eval_Strategy_ID,
	BPM.I_Bank_Pool_Mapping_ID,TDP.I_No_Of_Questions,TDP.I_Complexity_ID,
	TDP.N_Marks,TD.I_Status_ID,@sCreatedBy,@sUpdatedBy,@DtCreatedOn,@DtUpdatedOn
	FROM EXAMINATION.T_Test_Design TD WITH(NOLOCK)
	INNER JOIN EXAMINATION.T_Test_Design_Pattern TDP WITH(NOLOCK)
	ON TD.I_Test_Design_ID = TDP.I_Test_Design_ID
	INNER JOIN EXAMINATION.T_Bank_Pool_Mapping BPM
	ON BPM.I_Pool_ID = TDP.I_Pool_ID
	WHERE TD.I_Exam_Component_ID = @iExamComponentID
	AND TD.I_Eval_Strategy_ID IN (SELECT I_Eval_Strategy_ID FROM @tblEvalStrategy)

--	Delete relevant rows from Design Pattern table
	DELETE FROM EXAMINATION.T_Test_Design_Pattern
	WHERE I_Test_Design_ID IN
	(SELECT I_Test_Design_ID FROM EXAMINATION.T_Test_Design
		WHERE I_Exam_Component_ID = @iExamComponentID
		AND I_Eval_Strategy_ID IN (SELECT I_Eval_Strategy_ID FROM @tblEvalStrategy) )
	
	
	DECLARE @iEvalStratCount INT, @iLoopCount INT
	SELECT @iEvalStratCount = COUNT(I_Eval_Strategy_ID) FROM @tblEvalStrategy
	SET @iLoopCount = 1
	
	--	Create Temporary Table To store values from XML
		CREATE TABLE #tempTable
		(            
			I_Pool_ID int,
			I_No_Of_Questions int,
			I_Complexity_ID int,
			N_Marks numeric(8,2)
		)

	--	INsert Values into Temporary Table
		INSERT INTO #tempTable
		SELECT T.c.value('@QuestionPoolID','int'),
				T.c.value('@NoOfQuestion','int'),
				T.c.value('@Complexity','int'),
				T.c.value('@Marks','numeric(8,2)')
		FROM   @sQuestionPattern.nodes('/ExamDesign/QuestionPattern') T(c)
	
	WHILE (@iLoopCount <= @iEvalStratCount)
	BEGIN
		SELECT @iEvalStrategyID = I_Eval_Strategy_ID FROM @tblEvalStrategy WHERE ID = @iLoopCount
	
		--	Delete relevant rows from Test design Table
		IF EXISTS (SELECT I_Exam_Component_ID FROM EXAMINATION.T_Test_Design
					WHERE I_Exam_Component_ID = @iExamComponentID
					AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID))
		BEGIN
			UPDATE EXAMINATION.T_Test_Design
			SET S_Question_Bank_ID = @sQuestionBankID,
				S_Upd_By = @sUpdatedBy,
				Dt_Upd_On = @DtUpdatedOn		
			WHERE I_Exam_Component_ID = @iExamComponentID
				AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID)

			SELECT @iTestDesignID = I_Test_Design_ID 
			FROM EXAMINATION.T_Test_Design
			WHERE I_Exam_Component_ID = @iExamComponentID
				AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID)
		END
		ELSE
		BEGIN
			--	INSERT into the test design table
			INSERT INTO EXAMINATION.T_Test_Design
			(I_Exam_Component_ID,I_Eval_Strategy_ID,S_Question_Bank_ID,
			I_Status_ID,S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On)
			VALUES
			(@iExamComponentID,@iEvalStrategyID,@sQuestionBankID,
			1,@sCreatedBy,@sUpdatedBy,@DtCreatedOn,@DtUpdatedOn)

			SELECT @iTestDesignID = @@IDENTITY 
		END

	--	Insert values into the test design pattern table from temporary table
		INSERT INTO EXAMINATION.T_Test_Design_Pattern
		(I_Test_Design_ID,I_Pool_ID,I_No_Of_Questions,I_Complexity_ID,
		N_Marks,S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On)
		SELECT 
		@iTestDesignID,I_Pool_ID,I_No_Of_Questions,I_Complexity_ID,
		N_Marks,@sCreatedBy,@sUpdatedBy,@DtCreatedOn,@DtUpdatedOn 
		FROM #tempTable
		
		SET @iLoopCount = @iLoopCount + 1
				
	END
	TRUNCATE TABLE #tempTable
	DROP TABLE #tempTable
END
GO
