  CREATE PROCEDURE [EXAMINATION].[uspSaveOfflineExam]
(
	@iExamID INT,
	@iStudentDetailID INT,
	@sAnswerXML XML,
	@nMarks NUMERIC(8,2),
	@sUpdBy VARCHAR(20),
	@DtUpdOn DATETIME
)
AS
BEGIN	
	UPDATE Examination.T_Student_Question_Answer
	SET S_Answer_XML = @sAnswerXML,
		N_Marks = @nMarks,
		I_No_Of_Attempts = ISNULL(I_No_Of_Attempts,0) + 1,
