PRINT N'Creating Procedure [EXAMINATION].[uspSaveOfflineQuestions]...';


GO
/**************************************************************************************************************
Created by  : Swagata De
Date		: 09.05.2007
Description : This SP will save the questions of the offline examination in the local database of destination center
			  after downloading
Parameters  : 
Returns     : 
**************************************************************************************************************/

CREATE PROCEDURE [EXAMINATION].[uspSaveOfflineQuestions]
	(
		@iExamID INT,
		@iExamComponentID INT ,
		@sExamComponentName VARCHAR(50),
		@dtExamDate DATETIME,
		@sRegistrationNo VARCHAR(20),
		@sQuestionPaperXML XML	
		
	)
AS

BEGIN TRY
	SET NOCOUNT ON;
	
	IF EXISTS(SELECT * FROM EXAMINATION.T_Offline_Examination_Master WHERE I_Exam_ID=@iExamID)
		BEGIN
		--Update an existing entry
		UPDATE 	EXAMINATION.T_Offline_Examination_Master 
		SET I_Exam_Component_ID=@iExamComponentID,
			S_Component_Name=@sExamComponentName,
			S_Registration_No=@sRegistrationNo,
			S_Question_XML=@sQuestionPaperXML,
			Dt_Exam_Date=@dtExamDate
		WHERE I_Exam_ID=@iExamID
		END
		
	ELSE
		BEGIN
		--Insert a new entry
		INSERT INTO EXAMINATION.T_Offline_Examination_Master 
		(
			I_Exam_ID,
			I_Exam_Component_ID,
			S_Component_Name,
			S_Registration_No,
			S_Question_XML,
			Dt_Exam_Date
		)
		VALUES
		(
			@iExamID,
			@iExamComponentID,
			@sExamComponentName,
			@sRegistrationNo,
			@sQuestionPaperXML,
			@dtExamDate
		)	
		END
END TRY	
	
BEGIN CATCH
--Error occurred:  

DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
SELECT	@ErrMsg = ERROR_MESSAGE(),
		@ErrSeverity = ERROR_SEVERITY()

RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveOfflineQuestionsForCenter]...';


GO
/**************************************************************************************************************
Created by  : Debarshi Basu
Date		: 01.05.2007
Description : This SP will get the offline Question Paper for center
Parameters  : 		@iExamID int,
					@iStudentID int
**************************************************************************************************************/


CREATE PROCEDURE [EXAMINATION].[uspSaveOfflineQuestionsForCenter]
(
	@iCenterID int,
	@iExamID int,
	@iExamComponentID int,
	@sExamComponentName varchar(50),
	@sRegistrationNo varchar(20),
	@sQuestionPaperXML xml
)
AS
BEGIN		
	UPDATE EXAMINATION.T_Offline_Examination_Master
	SET S_Component_Name = @sExamComponentName,
		S_Registration_No = @sRegistrationNo,
		S_Question_XML = @sQuestionPaperXML
	WHERE I_Center_ID = @iCenterID
		AND I_Exam_ID = @iExamID
		AND I_Exam_Component_ID = @iExamComponentID

	IF NOT EXISTS (SELECT I_Center_Offline_Exam_ID 
					FROM EXAMINATION.T_Offline_Examination_Master
						WHERE I_Center_ID = @iCenterID	
						AND I_Exam_ID = @iExamID 
						AND I_Exam_Component_ID = @iExamComponentID)
	BEGIN
		INSERT INTO EXAMINATION.T_Offline_Examination_Master
		(I_Center_ID,I_Exam_ID,S_Registration_No,I_Exam_Component_ID,
		 S_Component_Name,S_Question_XML)
		VALUES
		(@iCenterID,@iExamID,@sRegistrationNo,@iExamComponentID,
		@sExamComponentName,@sQuestionPaperXML)
	END
END
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveOfflineStudentList]...';


GO
/**************************************************************************************************************
Created by  : Swagata De
Date		: 09.05.2007
Description : This SP will save the student list for offline exam
Parameters  : 
Returns     : 
**************************************************************************************************************/

CREATE PROCEDURE [EXAMINATION].[uspSaveOfflineStudentList]
	(
		@iExamID INT,	
		@sStudentXML XML,
		@sCrtdBy VARCHAR(20),
		@sUpdBy VARCHAR(20),
		@dtCrtdDt DATETIME,
		@dtUpdDt DATETIME		
	)
AS

BEGIN TRY
	SET NOCOUNT ON;	
	DECLARE	
	@iStudentID VARCHAR(200), 
    @sStudentCode VARCHAR(500)
   

	--	Create Temporary Table To store offline student attributes from XML
	CREATE TABLE #tempTable
	( 
		I_Exam_ID int,           
		I_Student_ID int,
		S_Student_Code varchar(500)		
	)

--	Insert Values into Temporary Table
	INSERT INTO #tempTable(I_Student_ID,S_Student_Code)
	SELECT T.c.value('@I_Student_ID','int'),
			T.c.value('@S_Student_Code','varchar(500)')			
	FROM   @sStudentXML.nodes('/OfflineStudentList/Student') T(c)
	
	UPDATE  #tempTable
	SET  I_Exam_ID=@iExamID
		--Check if student list for the particular exam already present in table or not
		IF EXISTS(SELECT * FROM EXAMINATION.T_Student_Question_Answer WHERE I_Exam_ID=  @iExamID)
		BEGIN	
		--Update the student entries already present in the table
			UPDATE TSQA
			SET 
			TSQA.I_Student_Detail_ID=TEMP1.I_Student_ID	,
			TSQA.S_Upd_By=	@sUpdBy,
			TSQA.Dt_Upd_On=	@dtUpdDt
			FROM EXAMINATION.T_Student_Question_Answer  TSQA ,#tempTable TEMP1
			WHERE TSQA.I_Exam_ID = TEMP1.I_Exam_ID
		END
		ELSE
		BEGIN		
		--Insert the student list in the table	
			INSERT INTO EXAMINATION.T_Student_Question_Answer 
			(
				I_Exam_ID,
				I_Student_Detail_ID						
			
			)
			SELECT I_Exam_ID,I_Student_ID FROM #tempTable 
			
			UPDATE EXAMINATION.T_Student_Question_Answer 
			SET S_Crtd_By=@sCrtdBy,
				Dt_Crtd_On=@dtCrtdDt
			WHERE I_Exam_ID=@iExamID
	   END		

END TRY	
	
BEGIN CATCH
--Error occurred:  

DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
SELECT	@ErrMsg = ERROR_MESSAGE(),
		@ErrSeverity = ERROR_SEVERITY()

RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveOfflineStudentListForCenter]...';


GO
/**************************************************************************************************************
Created by  : Debarshi Basu
Date		: 09.05.2007
Description : This SP will save the student list for offline exam for each center
Parameters  : 
Returns     : 
**************************************************************************************************************/

CREATE PROCEDURE [EXAMINATION].[uspSaveOfflineStudentListForCenter]
	(
		@iCenterID INT,
		@iExamID INT,	
		@sStudentXML XML,
		@sCrtdBy VARCHAR(20),
		@sUpdBy VARCHAR(20),
		@dtCrtdDt DATETIME,
		@dtUpdDt DATETIME		
	)
AS

BEGIN TRY
	SET NOCOUNT ON;	
	DECLARE	
	@iStudentID VARCHAR(200), 
    @sStudentCode VARCHAR(500)
   

	--	Create Temporary Table To store offline student attributes from XML
	CREATE TABLE #tempTable
	( 
		ID INT IDENTITY(1,1),
		I_Exam_ID int,           
		I_Student_ID int,
		S_Student_Code varchar(500)		
	)

--	Insert Values into Temporary Table
	INSERT INTO #tempTable(I_Student_ID,S_Student_Code)
	SELECT T.c.value('@I_Student_ID','int'),
			T.c.value('@S_Student_Code','varchar(500)')			
	FROM   @sStudentXML.nodes('/OfflineStudentList/Student') T(c)
	
	UPDATE  #tempTable
	SET  I_Exam_ID=@iExamID
	
	DECLARE @iCount INT, @iActualCount INT
	SET @iCount = 1
	SELECT @iActualCount = COUNT(*) FROM #tempTable
	
	WHILE (@iCount <= @iActualCount)
	BEGIN
		SELECT @iStudentID = I_Student_ID FROM #tempTable WHERE ID = @ICount
		--Check if student list for the particular exam already present in table or not
		IF EXISTS(SELECT * FROM EXAMINATION.T_Student_Question_Answer WHERE I_Exam_ID=  @iExamID 
							AND I_Student_Detail_ID = @iStudentID AND I_Center_ID =@iCenterID )
		BEGIN	
		--Update the student entries already present in the table
			UPDATE TSQA
			SET 			
			TSQA.S_Upd_By=	@sUpdBy,
			TSQA.Dt_Upd_On=	@dtUpdDt
			FROM EXAMINATION.T_Student_Question_Answer  TSQA ,#tempTable TEMP1
			WHERE TSQA.I_Exam_ID = TEMP1.I_Exam_ID
			AND TSQA.I_Center_ID = @iCenterID
			AND I_Student_Detail_ID = @iStudentID
		END
		ELSE
		BEGIN		
		--Insert the student list in the table	
			INSERT INTO EXAMINATION.T_Student_Question_Answer 
			(
				I_Center_ID,
				I_Exam_ID,
				I_Student_Detail_ID,						
				S_Crtd_By,
				Dt_Crtd_On
			)
			VALUES(@iCenterID,@iExamID,@iStudentID,@sCrtdBy,@dtCrtdDt)
	   END	
	   
	   SET @iCount = @iCount + 1	
	END
END TRY	
	
BEGIN CATCH
--Error occurred:  

DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
SELECT	@ErrMsg = ERROR_MESSAGE(),
		@ErrSeverity = ERROR_SEVERITY()

RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveOnlineExam]...';


GO
/**************************************************************************************************************
Created by  : Sandeep
Date		: 05.05.2007
Description : This SP will save the user response of the online exam
Parameters  : iExamComponentID
Returns     : Dataset
**************************************************************************************************************/

CREATE PROCEDURE [EXAMINATION].[uspSaveOnlineExam]
(
	@iExamComponentID INT,
	@iEmployeeID INT = NULL,
	@DtTestDate DATETIME,
	@N_Marks NUMERIC(8,2),
	@B_Has_Passed BIT,
	@sAnswer XML = NULL,
	@sCreatedBy VARCHAR(20) = NULL,
	@sUpdatedBy VARCHAR(20) = NULL,
	@dtCreatedOn DATETIME = NULL,
	@dtUpdatedOn DATETIME = NULL
)
AS
BEGIN
	--INSERT INTO dbo.T_Enquiry_Test VALUES (@iExamComponentID,@iEnquiryRegnID,@DtTestDate,@N_Marks,@sAnswer)
	IF EXISTS(SELECT * FROM EOS.T_Employee_Exam_Result 
				WHERE I_Employee_ID= @iEmployeeID AND I_Exam_Component_ID = @iExamComponentID
				AND DATEDIFF(ss, Dt_Crtd_On, @DtTestDate) = 0)
	BEGIN
		UPDATE EOS.T_Employee_Exam_Result
			SET	I_No_Of_Attempts = ISNULL(I_No_Of_Attempts,0) + 1,
				N_Marks = @N_Marks,
				B_Passed = @B_Has_Passed,
				S_Answer_XML = @sAnswer,
				S_Upd_By = @sUpdatedBy,
				Dt_Upd_On = @dtUpdatedOn
		WHERE	I_Employee_ID = @iEmployeeID
			AND	I_Exam_Component_ID = @iExamComponentID
			AND DATEDIFF(ss, Dt_Crtd_On, @DtTestDate) = 0
	END
	ELSE
	BEGIN
		INSERT INTO EOS.T_Employee_Exam_Result
		(I_Employee_ID, I_Exam_Component_ID, I_No_Of_Attempts, N_Marks, B_Passed, S_Answer_XML,S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On) 
		VALUES(@iEmployeeID,@iExamComponentID,1,@N_Marks,@B_Has_Passed,@sAnswer,@sCreatedBy,@sUpdatedBy,@dtCreatedOn,@dtUpdatedOn)
	END
END
GO
PRINT N'Creating Procedure [EXAMINATION].[uspSaveOnlineExamDesign]...';


GO
/**************************************************************************************************************
Created by  : Debarshi Basu
Date		: 01.05.2007
Description : This SP will save the exam Design
Parameters  : @iExamComponentID,@iEvalStrategyID,@iQuestionBankID,@sQuestionPattern
**************************************************************************************************************/


CREATE PROCEDURE [EXAMINATION].[uspSaveOnlineExamDesign]
	@iExamComponentID int,
	@iEvalStrategyID int = NULL,
	@sQuestionBankID varchar(50),
	@sQuestionPattern xml,
	@sCreatedBy varchar(20),
	@DtCreatedOn datetime,
	@sUpdatedBy  varchar(20),
	@DtUpdatedOn datetime
AS
BEGIN

	DECLARE @iTestDesignID INT, @RowCount INT

--	Before any update insert the values in the Audit table
	INSERT INTO EXAMINATION.T_Test_Design_Audit
	(I_Test_Design_ID,I_Exam_Component_ID,I_Eval_Strategy_ID,
	I_Bank_Pool_Mapping_ID,I_No_Of_Questions,I_Complexity_ID,N_Marks,
	I_Status_ID,S_Crtd_By,S_Upd_by,Dt_Crtd_On,Dt_Upd_On)
	SELECT 
	TD.I_Test_Design_ID,TD.I_Exam_Component_ID,TD.I_Eval_Strategy_ID,
	BPM.I_Bank_Pool_Mapping_ID,TDP.I_No_Of_Questions,TDP.I_Complexity_ID,
	TDP.N_Marks,TD.I_Status_ID,@sCreatedBy,@sUpdatedBy,@DtCreatedOn,@DtUpdatedOn
	FROM EXAMINATION.T_Test_Design TD WITH(NOLOCK)
	INNER JOIN EXAMINATION.T_Test_Design_Pattern TDP WITH(NOLOCK)
	ON TD.I_Test_Design_ID = TDP.I_Test_Design_ID
	INNER JOIN EXAMINATION.T_Bank_Pool_Mapping BPM
	ON BPM.I_Pool_ID = TDP.I_Pool_ID
	WHERE TD.I_Exam_Component_ID = @iExamComponentID
	AND TD.I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID)

--	Delete relevant rows from Design Pattern table
	DELETE FROM EXAMINATION.T_Test_Design_Pattern
	WHERE I_Test_Design_ID IN
	(SELECT I_Test_Design_ID FROM EXAMINATION.T_Test_Design
		WHERE I_Exam_Component_ID = @iExamComponentID
		AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID) )
	
--	Delete relevant rows from Test design Table
	IF EXISTS (SELECT I_Exam_Component_ID FROM EXAMINATION.T_Test_Design
				WHERE I_Exam_Component_ID = @iExamComponentID
				AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID))
	BEGIN
		UPDATE EXAMINATION.T_Test_Design
		SET S_Question_Bank_ID = @sQuestionBankID,
			S_Upd_By = @sUpdatedBy,
			Dt_Upd_On = @DtUpdatedOn		
		WHERE I_Exam_Component_ID = @iExamComponentID
			AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID)

		SELECT @iTestDesignID = I_Test_Design_ID 
		FROM EXAMINATION.T_Test_Design
		WHERE I_Exam_Component_ID = @iExamComponentID
			AND I_Eval_Strategy_ID = ISNULL(@iEvalStrategyID,I_Eval_Strategy_ID)
	END
	ELSE
	BEGIN
		--	INSERT into the test design table
		INSERT INTO EXAMINATION.T_Test_Design
		(I_Exam_Component_ID,I_Eval_Strategy_ID,S_Question_Bank_ID,
		I_Status_ID,S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On)
		VALUES
		(@iExamComponentID,@iEvalStrategyID,@sQuestionBankID,
		1,@sCreatedBy,@sUpdatedBy,@DtCreatedOn,@DtUpdatedOn)

		SELECT @iTestDesignID = @@IDENTITY 
	END

--	Create Temporary Table To store values from XML
	CREATE TABLE #tempTable
	(            
		I_Pool_ID int,
		I_No_Of_Questions int,
		I_Complexity_ID int,
		N_Marks numeric(8,2)
	)

--	INsert Values into Temporary Table
	INSERT INTO #tempTable
	SELECT T.c.value('@QuestionPoolID','int'),
			T.c.value('@NoOfQuestion','int'),
			T.c.value('@Complexity','int'),
			T.c.value('@Marks','numeric(8,2)')
	FROM   @sQuestionPattern.nodes('/ExamDesign/QuestionPattern') T(c)

	
--	Insert values into the test design pattern table from temporary table
	INSERT INTO EXAMINATION.T_Test_Design_Pattern
	(I_Test_Design_ID,I_Pool_ID,I_No_Of_Questions,I_Complexity_ID,
	N_Marks,S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On)
	SELECT 
	@iTestDesignID,I_Pool_ID,I_No_Of_Questions,I_Complexity_ID,
	N_Marks,@sCreatedBy,@sUpdatedBy,@DtCreatedOn,@DtUpdatedOn 
	FROM #tempTable
	
	TRUNCATE TABLE #tempTable
	DROP TABLE #tempTable
END
GO
