AS
BEGIN	
	IF EXISTS (SELECT 1 FROM EOS.T_Employee_Training_Details WHERE I_Employee_ID = @iEmployeeID
					AND I_Training_ID = @iTrainingID)
	BEGIN
		UPDATE EOS.T_Employee_Training_Details
		SET I_Document_ID = @iDocumentID,
