		)
		SELECT @StudentID,LOWER(@StatusName),@StatusFlag,'STATUS UPDATE',0,0,1,GETDATE(),@DefaulterDate

	END

	update T_Student_Detail set IsPaymentDue=@StatusFlag where S_Student_ID=@StudentID

END


end 


