)

AS
BEGIN
IF(@iBrandID <> 55)
BEGIN
IF (@CourseID IS NOT NULL)
BEGIN
	SELECT DISTINCT
		ISNULL(LM.I_Logistics_ID,0) AS I_Logistics_ID,
		ISNULL(LM.I_Logistics_Type_ID,0) AS I_Logistic_Type_ID,
		ISNULL(LM.I_Logistics_ID,0) AS I_Logistics_ID,
