                                LEFT OUTER JOIN dbo.T_Upload_Document UD ON LM.I_Document_ID = UD.I_Document_ID
                        WHERE   LM.I_Logistics_Type_ID = COALESCE(@iLogisticsType,
                                                              LM.I_Logistics_Type_ID)
                                AND LM.S_Item_Grade = COALESCE(@sItemGrade,
                                                              LM.S_Item_Grade)
