                                ISNULL(LM.S_Item_Grade, '') AS S_Item_Grade ,
                                ISNULL(LM.S_Remarks, '') AS S_Remarks ,  
  --ISNULL(LM.I_Brand_ID,0) AS I_Brand_ID,  
