                                ISNULL(UD.S_Document_Name, ' ') AS S_Document_Name ,
                                ISNULL(UD.S_Document_Path, ' ') AS S_Document_Path ,
                                ISNULL(UD.S_Document_Type, ' ') AS S_Document_Type ,
                                ISNULL(UD.S_Document_URL, ' ') AS S_Document_URL ,
                                ISNULL(UD.I_Document_ID, 0) AS I_Document_ID
                        FROM    dbo.T_Course_Center_Detail CCD
                                LEFT OUTER JOIN LOGISTICS.T_Logistics_Master LM ON LM.I_Course_ID = CCD.I_Course_ID  
  --LOGISTICS.T_Logistics_Master LM  
                                LEFT OUTER JOIN LOGISTICS.T_Logistics_Type_Master LTM ON LTM.I_Logistics_Type_ID = LM.I_Logistics_Type_ID
                                LEFT OUTER JOIN dbo.T_Upload_Document UD ON LM.I_Document_ID = UD.I_Document_ID
                        WHERE   CCD.I_Centre_Id = COALESCE(@iCenterID,
                                                           CCD.I_Centre_Id)
                                AND LM.I_Logistics_Type_ID = COALESCE(@iLogisticsType,
