                                AND LM.S_Item_Desc LIKE '%'
                                + COALESCE(@sItemName, LM.S_Item_Desc) + '%'
                                AND ISNULL(LM.I_Course_ID, 0) = COALESCE(@CourseID,
                                                              ISNULL(LM.I_Course_ID,
