PRINT N'Creating Procedure [MBP].[uspGetMBPPerformanceDetail]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: 19/07/2007
-- Description:	This sp return the detail of upload document
-- =============================================
CREATE procedure [MBP].[uspGetMBPPerformanceDetail]
(  
 @iYear INT = NULL,
 @iMonth INT = NULL,
 @iCenterID VARCHAR(8000)  = NULL,
 @iProduct VARCHAR(2000)	 = NULL
-- @iProduct INT	 = NULL
)
AS
	BEGIN TRY
	
	DECLARE @tblProduct TABLE
	(
		ID INT IDENTITY(1,1),
		I_Product_ID INT
	)
	
	DECLARE @tblCenter TABLE
	(
		ID INT IDENTITY(1,1),
		I_Center_ID INT
	)
	
	DECLARE @tblMBPPerformance TABLE
	(
		I_Product_ID INT,
		I_Center_ID INT,
		I_Year INT,
		I_Month INT,
		I_Actual_Enquiry INT,
		I_Actual_Booking NUMERIC(18,2),
		I_Actual_Enrollment INT,
		I_Actual_Billing NUMERIC(18,2),
		I_Actual_RFF NUMERIC(18,2),
		S_Remarks VARCHAR(2000)
	)
	
	
	INSERT INTO @tblProduct( [I_Product_ID] )
	SELECT ID FROM [dbo].[fnSplitter](@iProduct)
	
	INSERT INTO @tblCenter( [I_Center_ID] )
	SELECT ID FROM [dbo].[fnSplitter](@iCenterID)
	
	DECLARE @iIndexCenter INT, @iIndexProduct INT, @iRowCountCenter INT, @iRowCountProduct INT
	DECLARE @iCntID INT, @iPrdID INT
	
	SELECT @iIndexCenter = 1, @iRowCountCenter = COUNT([TC].[I_Center_ID]) FROM @tblCenter AS TC	
	SELECT @iIndexProduct = 1, @iRowCountProduct = COUNT([TP].[I_Product_ID]) FROM @tblProduct AS TP
	
	WHILE (@iIndexCenter <= @iRowCountCenter)	
	BEGIN
		SELECT @iCntID = [TC].[I_Center_ID] FROM @tblCenter AS TC WHERE [TC].[ID] = @iIndexCenter
		SET @iIndexProduct = 1	
			
		WHILE (@iIndexProduct <= @iRowCountProduct)
		BEGIN
			SELECT @iPrdID = [TP].[I_Product_ID] FROM @tblProduct AS TP WHERE [TP].[ID] = @iIndexProduct
			
			IF EXISTS (SELECT * FROM MBP.T_MBPerformance
			WHERE I_Year = COALESCE( @iYear,I_Year)	AND I_Month = COALESCE(@iMonth,I_Month)
			AND I_Center_ID = @iCntID AND I_Product_ID = @iPrdID)
			BEGIN
				INSERT INTO @tblMBPPerformance
					( [I_Product_ID] ,[I_Center_ID] ,[I_Year] ,[I_Month] ,[I_Actual_Enquiry] ,
					  [I_Actual_Booking] ,[I_Actual_Enrollment] ,[I_Actual_Billing] ,[I_Actual_RFF] ,[S_Remarks])
				SELECT 
				I_Product_ID,I_Center_ID,I_Year,I_Month,ISNULL(I_Actual_Enquiry,0) AS I_Actual_Enquiry,
				ISNULL(I_Actual_Booking,0) AS I_Actual_Booking,
				ISNULL(I_Actual_Enrollment,0) AS I_Actual_Enrollment,
				ISNULL(I_Actual_Billing,0) AS I_Actual_Billing,
				ISNULL(I_Actual_RFF,0) AS I_Actual_RFF,
				ISNULL(S_Remarks,'') AS S_Remarks
				FROM MBP.T_MBPerformance
				WHERE 
				I_Year = COALESCE( @iYear,I_Year)
				AND I_Month = COALESCE(@iMonth,I_Month)
				AND I_Center_ID = @iCntID
				AND I_Product_ID = @iPrdID
			END
			ELSE
			BEGIN
				INSERT INTO @tblMBPPerformance
				        ( [I_Product_ID] ,
				          [I_Center_ID] ,
				          [I_Year] ,
				          [I_Month] ,
				          [I_Actual_Enquiry] ,
				          [I_Actual_Booking] ,
				          [I_Actual_Enrollment] ,
				          [I_Actual_Billing] ,
				          [I_Actual_RFF] ,
				          [S_Remarks]
				        )
				VALUES  ( @iPrdID , -- I_Product_ID - int
				          @iCntID , -- I_Center_ID - int
				          @iYear , -- I_Year - int
				          @iMonth , -- I_Month - int
				          0 , -- I_Actual_Enquiry - int
				          0 , -- I_Actual_Booking - int
				          0 , -- I_Actual_Enrollment - int
				          0 , -- I_Actual_Billing - numeric
				          0 , -- I_Actual_RFF - numeric
				          ''  -- S_Remarks - varchar(2000)
				        )
			END
			
			SET @iIndexProduct = @iIndexProduct + 1
		END
		
		SET @iIndexCenter = @iIndexCenter + 1
	END
	
	SELECT * FROM @tblMBPPerformance AS TMP

END TRY
BEGIN CATCH
--Error occurred:  
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()
	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [MBP].[uspGetMBPDetailForYTD]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: '14/02/2008'
-- Description:	This store procedure 
-- constains YTD For Enquiry, Enrollmet, Booking and Billing
-- Return: Table
-- =============================================



CREATE procedure [MBP].[uspGetMBPDetailForYTD]
(  
 @iYear INT = NULL,
 @iMonth INT = NULL,
 @iCenterID VARCHAR(8000)  = NULL,
 --@iProduct VARCHAR(2000)	 = NULL,
 @iProduct INT	 = NULL,
 @iStatus INT = NULL
 --,@iMBPPlanType INT = NULL
)
AS

BEGIN TRY 

SELECT	MBP.I_Center_ID,
		ISNULL(MBP.I_Target_Enquiry,0) AS 'YTD_T_Enq',
		ISNULL(MBP.I_Target_Booking,0) AS 'YTD_T_Book',
		ISNULL(MBP.I_Target_Enrollment,0) AS 'YTD_T_Enrol',
		ISNULL(MBP.I_Target_Billing ,0) AS 'YTD_T_Bill',
		ISNULL(MBP.I_Target_RFF ,0) AS 'YTD_T_RFF',		

		ISNULL(MBP.I_Actual_Enquiry,0) AS 'YTD_A_Enq',
		ISNULL(MBP.I_Actual_Booking,0) AS 'YTD_A_Book',
		ISNULL(MBP.I_Actual_Enrollment,0) AS 'YTD_A_Enrol',
		ISNULL(MBP.I_Actual_Billing,0) AS 'YTD_A_Bill',
		ISNULL(MBP.I_Actual_Billing,0) AS 'YTD_A_RFF',

		ISNULL(((MBP.I_Actual_Enquiry)/@iMonth),0) AS 'YTD_Avg_Enq', 
		ISNULL(((MBP.I_Actual_Booking)/@iMonth),0) AS 'YTD_Avg_Book',
		ISNULL(((MBP.I_Actual_Enrollment)/@iMonth),0) AS 'YTD_Avg_Enrol',
		ISNULL(((MBP.I_Actual_Billing)/@iMonth),0) AS 'YTD_Avg_Bill',
		ISNULL(((MBP.I_Actual_Billing)/@iMonth),0) AS 'YTD_Avg_RFF'		

 FROM [MBP].[fnGetYTDFORMBP](@iMonth,@iYear,@iCenterID,@iProduct)  MBP




	END TRY
	BEGIN CATCH
	--Error occurred:  
		DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
		SELECT	@ErrMsg = ERROR_MESSAGE(),
				@ErrSeverity = ERROR_SEVERITY()
		RAISERROR(@ErrMsg, @ErrSeverity, 1)
	END CATCH
GO
PRINT N'Creating Procedure [MBP].[uspGetMBPDetail]...';


GO
-- =============================================  
-- Author:  Shankha Roy  
-- Create date: 19/07/2007  
-- Description: This sp return the detail of upload document  
-- =============================================  
CREATE procedure [MBP].[uspGetMBPDetail]  
(      
 @iYear INT = NULL,  
 @iMonth INT = NULL,  
 --@iCenterID INT  = NULL,  
 @iCenterID VARCHAR(8000)  = NULL,  
 @sProduct VARCHAR(50)  = NULL,  
 @iProduct VARCHAR(2000)  = NULL,  
 @iStatusID INT = NULL,  
 @iMBPPlanType INT = NULL,  
 @iHierarchyDetailID INT = NULL,  
 @iBrandID INT = NULL  
)  
AS  
 BEGIN TRY    
 ---PRINT @iCenterID  
IF @iMBPPlanType = 4 -- For only MBP DATA    
BEGIN -- MBP DATA  
  
 -- DECLARE NEW table for get data for Audit table  
 DECLARE @TblABP TABLE  
 (  
 ID INT IDENTITY (1,1),  
 I_MBP_Detail_ID INT,  
 I_Product_ID INT,  
 I_Center_ID INT,  
 I_Year INT,  
 I_Month INT,  
 I_Target_Enquiry INT,  
 I_Target_Booking NUMERIC(18,2),  
 I_Target_Enrollment INT,  
 I_Target_Billing NUMERIC(18,2),  
 I_Target_RFF NUMERIC(18,2),  
 I_Status_ID INT,  
 I_Type_ID INT,  
 S_Remarks VARCHAR(500),  
 S_Center_Name VARCHAR(100),  
 S_Center_Code VARCHAR(50),  
 S_Product_Name VARCHAR(100),   
 S_Currency_Code VARCHAR(20),  
 I_Currency_ID INT  
 )  
  
  
-- Check the dummy product id for enquiry   
IF(@sProduct IS NOT NULL)  
BEGIN  
 SET @iProduct = (SELECT DISTINCT(PM.I_Product_ID) FROM MBP.T_Product_Master PM  
 INNER JOIN MBP.T_Product_Component PC  
 ON PM.I_Product_ID=PC.I_Product_ID   
 LEFT OUTER JOIN dbo.T_Course_Master CM  
 ON CM.I_Course_ID = PC.I_Course_ID  
 LEFT OUTER JOIN dbo.T_CourseFamily_Master CFM  
 ON CFM.I_CourseFamily_ID = PC.I_Course_Family_ID  
 WHERE PM.S_Product_Name = @sProduct  
 AND CM.I_Brand_ID  =@iBrandID)  
END  
  
  
-- Check for Type Is it ABP or MBP   
  INSERT INTO  @TblABP  
   (  
   I_MBP_Detail_ID ,  
   I_Product_ID ,  
   I_Center_ID ,  
   I_Year ,  
   I_Month,  
   I_Target_Enquiry ,  
   I_Target_Booking ,  
   I_Target_Enrollment ,  
   I_Target_Billing ,  
   I_Target_RFF,  
   I_Status_ID ,  
   I_Type_ID,  
   S_Remarks,  
   S_Center_Name,  
   S_Center_Code,  
   S_Product_Name,     
   S_Currency_Code ,  
   I_Currency_ID   
   )  
   SELECT   
   ISNULL(MBP.I_MBP_Detail_ID,0) AS I_MBP_Detail_ID,  
   MBP.I_Product_ID,  
   MBP.I_Center_ID,  
   MBP.I_Year,  
   MBP.I_Month,  
   ISNULL(MBP.I_Target_Enquiry,0)AS I_Target_Enquiry,  
   ISNULL(MBP.I_Target_Booking,0) AS I_Target_Booking,  
   ISNULL(MBP.I_Target_Enrollment,0) AS I_Target_Enrollment,  
   ISNULL(MBP.I_Target_Billing,0) AS I_Target_Billing,  
   ISNULL(MBP.I_Target_RFF,0) AS I_Target_RFF,  
   MBP.I_Status_ID,  
   MBP.I_Type_ID ,  
   ISNULL(MBP.S_Remarks,'') AS S_Remarks,  
   ISNULL(CEN.S_Center_Name,'') AS S_Center_Name,  
   ISNULL(CEN.S_Center_Code,'') AS S_Center_Code,  
   PROD.S_Product_Name  AS S_Product_Name,  
   CURM.S_Currency_Code AS S_Currency_Code,  
   TCM.I_Currency_ID  
   FROM MBP.T_MBP_Detail MBP     
   LEFT OUTER JOIN dbo.T_Centre_Master CEN  
   ON MBP.I_Center_ID = CEN.I_Centre_ID  
   LEFT OUTER JOIN MBP.T_Product_Master PROD  
   ON MBP.I_Product_ID = PROD.I_Product_ID  
   INNER JOIN dbo.T_Country_Master TCM  
   ON CEN.I_Country_ID = TCM.I_Country_ID  
   INNER JOIN dbo.T_Currency_Master CURM  
   ON CURM.I_Currency_ID = TCM.I_Currency_ID  
   WHERE   
   MBP.I_Year = COALESCE( @iYear,I_Year)  
   AND MBP.I_Month = COALESCE(@iMonth,I_Month)  
   AND MBP.I_Center_ID IN (SELECT ID FROM [dbo].[fnSplitter](@iCenterID))  
   AND MBP.I_Product_ID = COALESCE(@iProduct,MBP.I_Product_ID)  
   --AND MBP.I_Product_ID IN (SELECT ID FROM [dbo].[fnSplitter](@iProduct))  
   AND MBP.I_Status_ID = COALESCE(@iStatusID,MBP.I_Status_ID)  
   AND I_Type_ID = COALESCE(@iMBPPlanType,I_Type_ID)  
  
  
  -- for Aduit table data  
  INSERT INTO  @TblABP  
   (  
   I_MBP_Detail_ID ,  
   I_Product_ID ,  
   I_Center_ID ,  
   I_Year ,  
   I_Month,  
   I_Target_Enquiry ,  
   I_Target_Booking ,  
   I_Target_Enrollment ,  
   I_Target_Billing ,  
   I_Target_RFF ,  
   I_Status_ID ,  
   I_Type_ID,  
   S_Remarks,  
   S_Center_Name,  
   S_Center_Code,  
   S_Product_Name,     
   S_Currency_Code,  
   I_Currency_ID   
   )  
   SELECT   
   ISNULL(MBP.I_MBP_Detail_ID,0) AS I_MBP_Detail_ID,  
   MBP.I_Product_ID,  
   MBP.I_Center_ID,  
   MBP.I_Year,  
   MBP.I_Month,  
   ISNULL(MBP.I_Target_Enquiry,0)AS I_Target_Enquiry,  
   ISNULL(MBP.I_Target_Booking,0) AS I_Target_Booking,  
   ISNULL(MBP.I_Target_Enrollment,0) AS I_Target_Enrollment,  
   ISNULL(MBP.I_Target_Billing,0) AS I_Target_Billing,  
   ISNULL(MBP.I_Target_RFF,0) AS I_Target_RFF,  
   MBP.I_Status_ID,  
   MBP.I_Type_ID ,  
   ISNULL(MBP.S_Remarks,'') AS S_Remarks,  
   ISNULL(CEN.S_Center_Name,'') AS S_Center_Name,  
   ISNULL(CEN.S_Center_Code,'') AS S_Center_Code,     
   PROD.S_Product_Name  AS S_Product_Name,  
   CURM.S_Currency_Code AS S_Currency_Code,  
   TCM.I_Currency_ID  
   FROM MBP.T_MBP_Detail_Audit MBP     
   LEFT OUTER JOIN dbo.T_Centre_Master CEN  
   ON MBP.I_Center_ID = CEN.I_Centre_ID  
   LEFT OUTER JOIN MBP.T_Product_Master PROD  
   ON MBP.I_Product_ID = PROD.I_Product_ID  
   INNER JOIN dbo.T_Country_Master TCM  
   ON CEN.I_Country_ID = TCM.I_Country_ID  
   INNER JOIN dbo.T_Currency_Master CURM  
   ON CURM.I_Currency_ID = TCM.I_Currency_ID  
   WHERE   
   MBP.I_Year = COALESCE( @iYear,I_Year)  
   AND MBP.I_Month = COALESCE(@iMonth,I_Month)  
   AND MBP.I_Center_ID IN (SELECT ID FROM [dbo].[fnSplitter](@iCenterID))  
   --AND MBP.I_Product_ID IN (SELECT ID FROM [dbo].[fnSplitter](@iProduct))  
   AND MBP.I_Product_ID = COALESCE(@iProduct,MBP.I_Product_ID)  
   AND MBP.I_Status_ID = COALESCE(@iStatusID,MBP.I_Status_ID)  
   AND I_Type_ID = COALESCE(@iMBPPlanType,I_Type_ID)  
  
           SELECT * from @TblABP ORDER BY I_MBP_Detail_ID  
  
END   
ELSE  
BEGIN  
  SELECT DISTINCT  
  ISNULL(MBP.I_MBP_Detail_ID,0) AS I_MBP_Detail_ID,  
  MBP.I_Product_ID,  
  MBP.I_Center_ID,  
  MBP.I_Year,  
  MBP.I_Month,  
  ISNULL(MBP.I_Target_Enquiry, 0) AS I_Target_Enquiry ,  
  ISNULL(MBP.I_Target_Booking,0) AS I_Target_Booking,  
  ISNULL(MBP.I_Target_Enrollment,0) AS I_Target_Enrollment,  
  ISNULL(MBP.I_Target_Billing,0) AS I_Target_Billing,  
  ISNULL(MBP.I_Target_RFF,0) AS I_Target_RFF,  
  MBP.I_Status_ID,  
  ISNULL(MBP.S_Remarks,'') AS S_Remarks,  
  ISNULL(CEN.S_Center_Name,'') AS S_Center_Name,  
  ISNULL(CEN.S_Center_Code,'') AS S_Center_Code,  
  PROD.S_Product_Name  AS S_Product_Name,  
  CURM.S_Currency_Code AS S_Currency_Code,  
  TCM.I_Currency_ID  
  FROM MBP.T_MBP_Detail MBP  
    
  LEFT OUTER JOIN dbo.T_Centre_Master CEN  
  ON MBP.I_Center_ID = CEN.I_Centre_ID  
  LEFT OUTER JOIN MBP.T_Product_Master PROD  
  ON MBP.I_Product_ID = PROD.I_Product_ID  
  INNER JOIN dbo.T_Country_Master TCM  
  ON CEN.I_Country_ID = TCM.I_Country_ID  
  INNER JOIN dbo.T_Currency_Master CURM  
  ON CURM.I_Currency_ID = TCM.I_Currency_ID  
  
  WHERE   
  MBP.I_Year = COALESCE( @iYear,I_Year)  
  AND MBP.I_Month = COALESCE(@iMonth,I_Month)  
  --AND MBP.I_Center_ID = COALESCE(@iCenterID,MBP.I_Center_ID)  
  AND MBP.I_Center_ID IN (SELECT ID FROM [dbo].[fnSplitter](@iCenterID))  
  --AND MBP.I_Product_ID IN (SELECT ID FROM [dbo].[fnSplitter](@iProduct))  
  AND MBP.I_Product_ID = COALESCE(@iProduct,MBP.I_Product_ID)  
  AND MBP.I_Status_ID = COALESCE(@iStatusID,MBP.I_Status_ID)  
  AND I_Type_ID = COALESCE(@iMBPPlanType,I_Type_ID)  
  --AND I_Type_ID IS NULL  
  --AND MBP.I_Center_ID<>0  
 END   
  
  
 END TRY  
   BEGIN CATCH  
   --Error occurred:    
    DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int  
    SELECT @ErrMsg = ERROR_MESSAGE(),  
      @ErrSeverity = ERROR_SEVERITY()  
    RAISERROR(@ErrMsg, @ErrSeverity, 1)  
   END CATCH
GO
