	@iHierarchyDetailID int,
	@iProductID int = null,
	@iYear int,
	@iMonth int,
	@iCenterID int,
	@sDefaultProduct varchar(2000) = null
)
AS

BEGIN

	SET NOCOUNT ON;
	
		DECLARE @tblHD TABLE
	(
		ID INT IDENTITY(1,1),
		I_Hierarchy_Detail_ID int,
		S_Hierarchy_Name VARCHAR(200)
	)
	DECLARE @tblSum TABLE
	(
		I_Hierarchy_Detail_ID int,
		S_Hierarchy_Name VARCHAR(200),
		I_Product_ID INT,
		I_Year INT,
		I_Month INT,
		I_Target_Enquiry int,
		I_Actual_Enquiry int,
		I_Target_Booking int,
		I_Actual_Booking int,
		I_Target_Enrollment int,
		I_Actual_Enrollment int,
		I_Target_Billing int,
		I_Actual_Billing int
	)
	DECLARE @tblEnquirySum TABLE
	(
		I_Hierarchy_Detail_ID int,
		I_Year INT,
		I_Month INT,
		I_Target_Enquiry int,
		I_Actual_Enquiry int
	)
	DECLARE @iDefaultProductID INT
	DECLARE @iCount INT, @iRow INT
	DECLARE @iHierachyDetailID INT
	DECLARE @sHierarchyName VARCHAR(200)
	DECLARE @iMBPType INT
	
	-- determining the Default Product ID
	IF(@sDefaultProduct IS NOT NULL)
	BEGIN
		SET @iDefaultProductID = (SELECT DISTINCT(PM.I_Product_ID) FROM MBP.T_Product_Master PM
		INNER JOIN MBP.T_Product_Component PC
		ON PM.I_Product_ID=PC.I_Product_ID 
		LEFT OUTER JOIN dbo.T_Course_Master CM
		ON CM.I_Course_ID = PC.I_Course_ID
		LEFT OUTER JOIN dbo.T_CourseFamily_Master CFM
		ON CFM.I_CourseFamily_ID = PC.I_Course_Family_ID
		WHERE PM.S_Product_Name = @sDefaultProduct
		AND CM.I_Brand_ID  =@iBrandID)
	END
	
	IF(@iCenterID = 0)
	BEGIN
		INSERT INTO @tblHD
		SELECT HMD.I_Hierarchy_Detail_ID, HD.S_Hierarchy_Name 
		FROM dbo.T_Hierarchy_Mapping_Details HMD
		INNER JOIN dbo.T_Hierarchy_Details HD 
		ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID
		WHERE HMD.I_Parent_ID = @iHierarchyDetailID AND HMD.I_Status = 1
	END
	ELSE
	BEGIN
		INSERT INTO @tblHD
		SELECT HMD.I_Hierarchy_Detail_ID, HD.S_Hierarchy_Name 
		FROM dbo.T_Hierarchy_Mapping_Details HMD
		INNER JOIN dbo.T_Hierarchy_Details HD 
		ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID
		WHERE HMD.I_Hierarchy_Detail_ID = @iHierarchyDetailID AND HMD.I_Status = 1
	END

	SELECT * FROM @tblHD

	SET @iCount = 1
	SET @iRow = (SELECT COUNT(*) FROM @tblHD)

	WHILE @iCount <= @iRow
	BEGIN
		SET @iHierachyDetailID = (SELECT I_Hierarchy_Detail_ID FROM @tblHD WHERE ID = @iCount)
		SET @sHierarchyName = (SELECT S_Hierarchy_Name FROM @tblHD WHERE ID = @iCount)
		SET @iMBPType = (SELECT DISTINCT(I_Type_ID) FROM MBP.T_MBP_Detail 
						 WHERE I_Product_ID = @iProductID
						 AND I_Center_ID IN (SELECT * FROM dbo.fnGetCenterIDFromHierarchy(@iHierachyDetailID,@iBrandID))
						 AND I_Year = @iYear
						 AND I_Month = @iMonth)
		
		IF (@iMBPType = 5)
		BEGIN
		-- Inserting Taget and Actual Values other than Enquiry from Audit table 
		INSERT INTO @tblSUM
		(
			I_Hierarchy_Detail_ID,
			S_Hierarchy_Name,
			I_Product_ID,
			I_Year,
			I_Month,
			I_Target_Enquiry,
			I_Actual_Enquiry,
			I_Target_Booking,
			I_Actual_Booking,
			I_Target_Enrollment,
			I_Actual_Enrollment,
			I_Target_Billing,
			I_Actual_Billing
		)
		SELECT @iHierachyDetailID, 
			   @sHierarchyName, 
			   @iProductID,
			   @iYear,
			   @iMonth,
			   NULL, 
			   NULL,
			   SUM(MDA.I_Target_Booking),
			   SUM(MP.I_Actual_Booking), 
			   SUM(MDA.I_Target_Enrollment), 
			   SUM(MP.I_Actual_Enrollment),
			   SUM(MDA.I_Target_Billing),
			   SUM(MP.I_Actual_Billing)
		FROM MBP.T_MBP_Detail MD
		INNER JOIN MBP.T_MBP_Detail_Audit MDA
		ON MDA.I_MBP_Detail_ID = MD.I_MBP_Detail_ID
		LEFT OUTER JOIN MBP.T_MBPerformance MP
		ON MP.I_Product_ID = MD.I_Product_ID
		AND MP.I_Center_ID = MD.I_Center_ID
		AND MP.I_Year = MD.I_Year
		AND MP.I_Month = MD.I_Month
		WHERE MD.I_Product_ID = ISNULL(@iProductID,MD.I_Product_ID)
		AND MD.I_Year = @iYear
		AND MD.I_Month = @iMonth
		AND MD.I_Center_ID IN
		(SELECT * FROM dbo.fnGetCenterIDFromHierarchy(@iHierachyDetailID,@iBrandID))
		AND MD.I_Status_ID = 1
		AND MDA.I_Status_ID = 1
		
		INSERT INTO @tblEnquirySum
		(
			I_Hierarchy_Detail_ID,
			I_Year,
			I_Month,
			I_Target_Enquiry,
			I_Actual_Enquiry
		)
		SELECT @iHierachyDetailID,
			   @iYear,
			   @iMonth,
			   SUM(MD.I_Target_Enquiry),
			   SUM(MP.I_Actual_Enquiry)
		FROM MBP.T_MBP_Detail MD
		--INNER JOIN MBP.T_MBP_Detail_Audit MDA
		--ON MDA.I_MBP_Detail_ID = MD.I_MBP_Detail_ID
		LEFT OUTER JOIN MBP.T_MBPerformance MP
		ON MP.I_Product_ID = MD.I_Product_ID
		AND MP.I_Center_ID = MD.I_Center_ID
		AND MP.I_Year = MD.I_Year
		AND MP.I_Month = MD.I_Month
		WHERE MD.I_Product_ID = ISNULL(@iDefaultProductID,MD.I_Product_ID)
		AND MD.I_Year = @iYear
		AND MD.I_Month = @iMonth
		AND MD.I_Center_ID IN
		(SELECT * FROM dbo.fnGetCenterIDFromHierarchy(@iHierachyDetailID,@iBrandID))
		AND MD.I_Status_ID = 1
		--AND MDA.I_Status_ID = 1 

		--Updating the Enquiry Target and Actual Value from audit table
		UPDATE @tblSUM
		SET I_Target_Enquiry = ES.I_Target_Enquiry,
			I_Actual_Enquiry = ES.I_Actual_Enquiry
		FROM @tblEnquirySum ES
		WHERE ES.I_Hierarchy_Detail_ID = @iHierachyDetailID
		AND ES.I_Year = @iYear
		AND ES.I_Month = @iMonth
		
		END
		ELSE
		BEGIN
		--Inserting Target and Actual Values other than Enquiry from Detail Table
		INSERT INTO @tblSUM
		(
			I_Hierarchy_Detail_ID,
			S_Hierarchy_Name,
			I_Product_ID,
			I_Year,
			I_Month,
			I_Target_Enquiry,
			I_Actual_Enquiry,
			I_Target_Booking,
			I_Actual_Booking,
			I_Target_Enrollment,
			I_Actual_Enrollment,
			I_Target_Billing,
			I_Actual_Billing
		)
		SELECT @iHierachyDetailID, 
			   @sHierarchyName, 
			   @iProductID,
			   @iYear,
			   @iMonth,
			   NULL, 
			   NULL,
			   SUM(MD.I_Target_Booking),
			   SUM(MP.I_Actual_Booking), 
			   SUM(MD.I_Target_Enrollment), 
			   SUM(MP.I_Actual_Enrollment),
			   SUM(MD.I_Target_Billing),
			   SUM(MP.I_Actual_Billing)
		FROM MBP.T_MBP_Detail MD
		LEFT OUTER JOIN MBP.T_MBPerformance MP
		ON MP.I_Product_ID = MD.I_Product_ID
		AND MP.I_Center_ID = MD.I_Center_ID
		AND MP.I_Year = MD.I_Year
		AND MP.I_Month = MD.I_Month
		WHERE MD.I_Product_ID = ISNULL(@iProductID,MD.I_Product_ID)
		AND MD.I_Year = @iYear
		AND MD.I_Month = @iMonth
		AND MD.I_Center_ID IN
		(SELECT * FROM dbo.fnGetCenterIDFromHierarchy(@iHierachyDetailID,@iBrandID))
		AND MD.I_Status_ID = 1

		INSERT INTO @tblEnquirySum
		(
			I_Hierarchy_Detail_ID,
			I_Year,
			I_Month,
			I_Target_Enquiry,
			I_Actual_Enquiry
		)
		SELECT @iHierachyDetailID,
			   @iYear,
			   @iMonth,
			   SUM(MD.I_Target_Enquiry),
			   SUM(MP.I_Actual_Enquiry)
		FROM MBP.T_MBP_Detail MD
		LEFT OUTER JOIN MBP.T_MBPerformance MP
		ON MP.I_Product_ID = MD.I_Product_ID
		AND MP.I_Center_ID = MD.I_Center_ID
		AND MP.I_Year = MD.I_Year
		AND MP.I_Month = MD.I_Month
		WHERE MD.I_Product_ID = ISNULL(@iDefaultProductID,MD.I_Product_ID)
		AND MD.I_Year = @iYear
		AND MD.I_Month = @iMonth
		AND MD.I_Center_ID IN
		(SELECT * FROM dbo.fnGetCenterIDFromHierarchy(@iHierachyDetailID,@iBrandID))
		AND MD.I_Status_ID = 1

		--Updating the Enquiry Target and Actual Value from audit table
		UPDATE @tblSUM
		SET I_Target_Enquiry = ES.I_Target_Enquiry,
			I_Actual_Enquiry = ES.I_Actual_Enquiry
		FROM @tblEnquirySum ES
		WHERE ES.I_Hierarchy_Detail_ID = @iHierachyDetailID
		AND ES.I_Year = @iYear
		AND ES.I_Month = @iMonth

		END

		SET @iCount = @iCount + 1
	END
	SELECT * FROM @tblSUM
	
END
GO
PRINT N'Creating Procedure [MBP].[uspGetTargetActualSummary]...';


GO
CREATE PROCEDURE [MBP].[uspGetTargetActualSummary]          
(          
 @iBrandID INT,          
 @iHierarchyDetailID INT,          
 @sProductMonthInfo VARCHAR(8000),          
 @iYear INT,                  
 @iCenterID INT,          
 @sDefaultProduct VARCHAR(2000) = NULL ,
 @sCurrency VARCHAR(100)         
)          
AS          
          
BEGIN          
 SET NOCOUNT ON;           
           
 DECLARE @tblHD TABLE          
  (          
   ID INT IDENTITY(1,1),          
   I_Hierarchy_Detail_ID int,          
   S_Hierarchy_Name VARCHAR(200)          
  )    
 DECLARE @tblSum TABLE    
  (    
   I_Hierarchy_Detail_ID int,          
   S_Hierarchy_Name VARCHAR(200),          
   I_Product_ID INT,          
   I_Year INT,          
   I_Month INT,          
   I_Target_Enquiry numeric(18,2),          
   I_Actual_Enquiry int,          
   I_Target_Booking numeric(18,2),          
   I_Actual_Booking numeric(18,2),          
   I_Target_Enrollment int,          
   I_Actual_Enrollment int,          
   I_Target_Billing numeric(18,2),          
   I_Actual_Billing numeric(18,2),      
   I_Target_RFF numeric(18,2),      
   I_Actual_RFF numeric(18,2)    
  )         
  
 CREATE TABLE #ProductTable (I_Product_Id INT)  
 CREATE TABLE #MonthTable (I_Month_Id INT)  
   
 DECLARE @hDoc INT  
 EXEC sp_xml_preparedocument @hDoc OUTPUT,@sProductMonthInfo  
  
 INSERT INTO #ProductTable  
 SELECT ProductTable.I_Product_Id FROM  
 OPENXML (@hDoc,'/INFO/ProductTable',2)  
 WITH( I_Product_Id INT) AS ProductTable  
  
   
 INSERT INTO #MonthTable  
 SELECT MonthTable.I_Month_Id FROM  
 OPENXML (@hDoc,'/INFO/MonthTable',2)  
 WITH( I_Month_Id INT) AS MonthTable  
  
  
 IF(@iCenterID = 0)          
  BEGIN          
   INSERT INTO @tblHD          
   SELECT HMD.I_Hierarchy_Detail_ID, HD.S_Hierarchy_Name           
   FROM dbo.T_Hierarchy_Mapping_Details HMD          
   INNER JOIN dbo.T_Hierarchy_Details HD           
   ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID          
   WHERE HMD.I_Parent_ID = @iHierarchyDetailID AND HMD.I_Status = 1          
  END          
  ELSE          
  BEGIN          
   INSERT INTO @tblHD          
   SELECT HMD.I_Hierarchy_Detail_ID, HD.S_Hierarchy_Name           
   FROM dbo.T_Hierarchy_Mapping_Details HMD          
   INNER JOIN dbo.T_Hierarchy_Details HD           
   ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID          
   WHERE HMD.I_Hierarchy_Detail_ID = @iHierarchyDetailID AND HMD.I_Status = 1          
  END          
          
  
DECLARE @iMonthId INT  
DECLARE @iProductId INT  
  
DECLARE PRODUCT_CURSOR CURSOR FOR   
 SELECT I_Product_Id  
 FROM #ProductTable  
  
 OPEN PRODUCT_CURSOR   
 FETCH NEXT FROM PRODUCT_CURSOR   
 INTO @iProductId  
      
 WHILE @@FETCH_STATUS = 0      
 BEGIN  
  --------------------------------  
  DECLARE MONTH_CURSOR CURSOR FOR   
  SELECT I_Month_Id  
  FROM #MonthTable  
  OPEN MONTH_CURSOR   
  FETCH NEXT FROM MONTH_CURSOR   
  INTO @iMonthId  
       
  WHILE @@FETCH_STATUS = 0      
  BEGIN  
  -----------------------------------------------  
  insert into @tblSum  
  SELECT * FROM [dbo].[fnGetTargetSummary]  
   (@iBrandID,@iHierarchyDetailID,@iProductId,@iYear,@iMonthId,@iCenterID,@sDefaultProduct,@sCurrency)  
  -----------------------------------------------  
  FETCH NEXT FROM MONTH_CURSOR   
      INTO @iMonthId  
  END  
  CLOSE MONTH_CURSOR   
  DEALLOCATE MONTH_CURSOR   
  --------------------------------  
 FETCH NEXT FROM PRODUCT_CURSOR   
     INTO @iProductId  
 END  
CLOSE PRODUCT_CURSOR   
DEALLOCATE PRODUCT_CURSOR   
  
SELECT * FROM @tblHD  
ORDER BY I_Hierarchy_Detail_ID  

DECLARE @iProdCount INT
SELECT  @iProdCount = COUNT(DISTINCT I_Product_Id) FROM #ProductTable

SELECT * FROM @tblSum AS TS
 
SELECT   
  I_Hierarchy_Detail_ID							AS  I_Hierarchy_Detail_ID        
  ,S_Hierarchy_Name								AS  S_Hierarchy_Name  
  ,null											AS  I_Product_ID      
  ,@iYear										AS  I_Year          
  ,SUM(I_Month)									AS  I_Month          
  ,SUM(I_Target_Enquiry)/@iProdCount			AS  I_Target_Enquiry 
  ,SUM(I_Actual_Enquiry)/@iProdCount			AS  I_Actual_Enquiry 
  ,SUM(I_Target_Booking)						AS  I_Target_Booking  
  ,SUM(I_Actual_Booking)						AS  I_Actual_Booking  
  ,SUM(I_Target_Enrollment)						AS  I_Target_Enrollment  
  ,SUM(I_Actual_Enrollment)						AS  I_Actual_Enrollment  
  ,SUM(I_Target_Billing)/@iProdCount			AS  I_Target_Billing  
  ,SUM(I_Actual_Billing)/@iProdCount			AS  I_Actual_Billing  
  ,SUM(I_Target_RFF)/@iProdCount				AS  I_Target_RFF      
  ,SUM(I_Actual_RFF)/@iProdCount				AS  I_Actual_RFF   
FROM @tblSum  
GROUP BY I_Hierarchy_Detail_ID  
,S_Hierarchy_Name  
ORDER BY I_Hierarchy_Detail_ID  
   
DROP TABLE #ProductTable   
DROP TABLE #MonthTable  
  
END
GO
PRINT N'Creating Procedure [MBP].[uspGetSumForExcelReportHierarchyNewCenter]...';


GO
CREATE PROCEDURE [MBP].[uspGetSumForExcelReportHierarchyNewCenter]
(	
	@iBrandID int,
	@iHierarchyDetailID int,
	@iYear int	
)
AS
BEGIN
DECLARE @iCount INT, @iRow INT
DECLARE @iHierachyDetailID INT
DECLARE @CenterName VARCHAR(200)
DECLARE @sHierachyChains VARCHAR(200)
DECLARE @iRowCount INT
DECLARE @iRowCount1 INT
DECLARE @iRowCount2 INT
DECLARE @iRowCount3 INT
DECLARE @iCounter INT
SET @iRowCount=0;
SET @iRowCount1=0;
SET @iRowCount2=0;
SET @iRowCount3=0;
SET @iCounter=0;

DECLARE @MSG VARCHAR(200)

SET @iHierachyDetailID = @iHierarchyDetailID
DECLARE @tblHD TABLE
	(
		ID INT IDENTITY(1,1),
		I_Hierarchy_Detail_ID int,	
		S_Hierarchy_Name VARCHAR(200),
		S_Hierarchy_Chain VARCHAR(200),	
		S_Hierarchy_Level_Chain VARCHAR(200),
		I_Hierarchy_Level_Id int,
		I_Hierarchy_Master_ID int,
		I_Status VARCHAR(2),
		I_Parent_ID INT			
	)

	INSERT INTO @tblHD
	SELECT	HMD.I_Hierarchy_Detail_ID,
			HD.S_Hierarchy_Name,
			HMD.S_Hierarchy_Chain,
			HMD.S_Hierarchy_Level_Chain,
			HD.I_Hierarchy_Level_Id,
			HD.I_Hierarchy_Master_ID,
			HD.I_Status,
			HMD.I_Parent_ID
	FROM dbo.T_Hierarchy_Mapping_Details HMD
	INNER JOIN dbo.T_Hierarchy_Details HD 
	ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID
	WHERE HMD.I_Parent_ID = @iHierachyDetailID AND HMD.I_Status = 1


	DECLARE @tblHD1 TABLE
	(
		ID INT IDENTITY(1,1),
		I_Hierarchy_Detail_ID int,	
		S_Hierarchy_Name VARCHAR(200),
		S_Hierarchy_Chain VARCHAR(200),	
		S_Hierarchy_Level_Chain VARCHAR(200),
		I_Hierarchy_Level_Id int,
		I_Hierarchy_Master_ID int,
		I_Status VARCHAR(2),
		I_Parent_ID INT			
	)	

	SET @iCount = 1
	SET @iRow = (SELECT COUNT(*) FROM @tblHD)
	WHILE @iCount <= @iRow
	BEGIN
		
		SET @iHierachyDetailID = (SELECT I_Hierarchy_Detail_ID FROM @tblHD WHERE ID = @iCount)						
		INSERT INTO @tblHD1	
			SELECT	HMD.I_Hierarchy_Detail_ID,
			HD.S_Hierarchy_Name,
			HMD.S_Hierarchy_Chain,
			HMD.S_Hierarchy_Level_Chain,
			HD.I_Hierarchy_Level_Id,
			HD.I_Hierarchy_Master_ID,
			HD.I_Status,
			HMD.I_Parent_ID
	FROM dbo.T_Hierarchy_Mapping_Details HMD
	INNER JOIN dbo.T_Hierarchy_Details HD 
	ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID

	WHERE HMD.I_Parent_ID =@iHierachyDetailID AND HMD.I_Status = 1

	SET @iCount = @iCount + 1
	END



	DECLARE @tblHD2 TABLE
	(
		ID INT IDENTITY(1,1),
		I_Hierarchy_Detail_ID int,	
		S_Hierarchy_Name VARCHAR(200),
		S_Hierarchy_Chain VARCHAR(200),	
		S_Hierarchy_Level_Chain VARCHAR(200),
		I_Hierarchy_Level_Id int,
		I_Hierarchy_Master_ID int,
		I_Status VARCHAR(2),
		I_Parent_ID INT			
	)	

	SET @iCount = 1
	SET @iRow = (SELECT COUNT(*) FROM @tblHD1)
	WHILE @iCount <= @iRow
	BEGIN
		
		SET @iHierachyDetailID = (SELECT I_Hierarchy_Detail_ID FROM @tblHD1 WHERE ID = @iCount)						
		INSERT INTO @tblHD2	
			SELECT	HMD.I_Hierarchy_Detail_ID,
			HD.S_Hierarchy_Name,
			HMD.S_Hierarchy_Chain,
			HMD.S_Hierarchy_Level_Chain,
			HD.I_Hierarchy_Level_Id,
			HD.I_Hierarchy_Master_ID,
			HD.I_Status,
			HMD.I_Parent_ID
	FROM dbo.T_Hierarchy_Mapping_Details HMD
	INNER JOIN dbo.T_Hierarchy_Details HD 
	ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID

	WHERE HMD.I_Parent_ID =@iHierachyDetailID AND HMD.I_Status = 1

	SET @iCount = @iCount + 1
	END

DECLARE @tblHD3 TABLE
	(
		ID INT IDENTITY(1,1),
		I_Hierarchy_Detail_ID int,	
		S_Hierarchy_Name VARCHAR(200),
		S_Hierarchy_Chain VARCHAR(200),	
		S_Hierarchy_Level_Chain VARCHAR(200),
		I_Hierarchy_Level_Id int,
		I_Hierarchy_Master_ID int,
		I_Status VARCHAR(2),
		I_Parent_ID INT			
	)	

	SET @iCount = 1
	SET @iRow = (SELECT COUNT(*) FROM @tblHD2)
	WHILE @iCount <= @iRow
	BEGIN
		
		SET @iHierachyDetailID = (SELECT I_Hierarchy_Detail_ID FROM @tblHD2 WHERE ID = @iCount)						
		INSERT INTO @tblHD3	
			SELECT	HMD.I_Hierarchy_Detail_ID,
			HD.S_Hierarchy_Name,
			HMD.S_Hierarchy_Chain,
			HMD.S_Hierarchy_Level_Chain,
			HD.I_Hierarchy_Level_Id,
			HD.I_Hierarchy_Master_ID,
			HD.I_Status,
			HMD.I_Parent_ID
	FROM dbo.T_Hierarchy_Mapping_Details HMD
	INNER JOIN dbo.T_Hierarchy_Details HD 
	ON HMD.I_Hierarchy_Detail_ID = HD.I_Hierarchy_Detail_ID

	WHERE HMD.I_Parent_ID =@iHierachyDetailID AND HMD.I_Status = 1

	SET @iCount = @iCount + 1
	END



SET @iRowCount =(SELECT COUNT(*) FROM @tblHD)
IF @iRowCount > 0
BEGIN
UPDATE @tblHD
SET I_Hierarchy_Detail_ID = CONVERT(VARCHAR(50),I_Hierarchy_Detail_ID)+'01'
--select * from @tblHD
SET @iCounter= 0;
END

SET @iRowCount1 =(SELECT COUNT(*) FROM @tblHD1)
IF @iRowCount1 > 0
BEGIN
UPDATE @tblHD1
SET I_Hierarchy_Detail_ID = CONVERT(VARCHAR(50),I_Hierarchy_Detail_ID)+'01'
--select * from @tblHD1
SET @iCounter= 1;
END

SET @iRowCount2 =(SELECT COUNT(*) FROM @tblHD2)
IF @iRowCount2 > 0
BEGIN
SET @iCounter= 2;
UPDATE @tblHD2
SET I_Hierarchy_Detail_ID = CONVERT(VARCHAR(50),I_Hierarchy_Detail_ID)+'01'
--select * from @tblHD2
END

SET @iRowCount3 =(SELECT COUNT(*) FROM @tblHD3)
IF @iRowCount3 > 0
BEGIN
UPDATE @tblHD3
SET I_Hierarchy_Detail_ID = CONVERT(VARCHAR(50),I_Hierarchy_Detail_ID)+'01'
--select * from @tblHD3
SET @iCounter= 3;
END

--SELECT @iCounter




DECLARE @tblCenter TABLE
	(
		ID INT IDENTITY(1,1),
		I_Center_ID int,	
		S_Hierarchy_Name VARCHAR(200)
	)


IF @iCounter = 3
BEGIN
INSERT INTO @tblCenter
SELECT DISTINCT MD.I_Center_ID,S_Hierarchy_Name 
FROM @tblHD2 tblHD2
INNER JOIN MBP.T_MBP_Detail MD 
ON MD.I_Center_ID = tblHD2.I_Hierarchy_Detail_ID

END

IF @iCounter = 2
BEGIN
INSERT INTO @tblCenter
SELECT DISTINCT MD.I_Center_ID,S_Hierarchy_Name 
FROM @tblHD1 tblHD1
INNER JOIN MBP.T_MBP_Detail MD 
ON MD.I_Center_ID = tblHD1.I_Hierarchy_Detail_ID
END

IF @iCounter = 1
BEGIN
INSERT INTO @tblCenter
SELECT DISTINCT MD.I_Center_ID,S_Hierarchy_Name 
FROM @tblHD tblHD
INNER JOIN MBP.T_MBP_Detail MD 
ON MD.I_Center_ID = tblHD.I_Hierarchy_Detail_ID
END


	
SELECT * FROM @tblCenter



DECLARE @tblSum TABLE
	(
		I_MBP_Detail_ID INT,
		I_Product_ID INT,
		I_Hierarchy_Detail_ID INT,
		I_Center_ID INT,
		I_Year INT,
		I_Status_ID INT,
		I_Month INT,
		I_Target_Enquiry INT,		
		I_Target_Booking INT,		
		I_Target_Enrollment INT,		
		I_Target_Billing INT,
		I_Target_RFF INT,	
		S_Remarks VARCHAR(200)	
	)



	DECLARE @iCount2 INT, @iRow2 INT
	DECLARE @iCenterID INT
	DECLARE @sCenterHierarchyID VARCHAR(200)

SET @iCount2 = 1
	SET @iRow2 = (SELECT COUNT(*) FROM @tblCenter)	
	WHILE @iCount2 <= @iRow2
	BEGIN

		SET @iCenterID = (SELECT I_Center_ID FROM @tblCenter WHERE ID = @iCount2)						
		


DECLARE @iCount1 INT
SET @iCount1 = 1
	
	WHILE @iCount1 <= 12
	BEGIN
		
		INSERT INTO @tblSUM
		(
			I_MBP_Detail_ID ,
			I_Product_ID ,
			I_Hierarchy_Detail_ID ,
			I_Center_ID ,
			I_Year ,
			I_Status_ID,
			I_Month ,
			I_Target_Enquiry ,		
			I_Target_Booking ,		
			I_Target_Enrollment ,		
			I_Target_Billing ,
			I_Target_RFF,
			S_Remarks	
		)
		SELECT I_MBP_Detail_ID,I_Product_ID,I_Hierarchy_Detail_ID,I_Center_ID,I_Year,I_Status_ID,		
		I_Month,I_Target_Enquiry,I_Target_Booking,I_Target_Enrollment,I_Target_Billing,I_Target_RFF
		,@iHierarchyDetailID
		FROM MBP.T_MBP_Detail MD		
		WHERE MD.I_Month =@iCount1
		AND MD.I_Year = @iYear 
		AND	MD.I_Center_ID = @iCenterID 		
		SET @iCount1 = @iCount1 + 1
END
	
SET @iCount2 = @iCount2 + 1
END
	
SELECT 
		I_Product_ID ,
		I_Hierarchy_Detail_ID ,
		--I_Center_Id,
		I_Year ,
		I_Status_ID ,
		I_Month ,
		Sum(I_Target_Enquiry) as I_Target_Enquiry ,		
		Sum(I_Target_Booking) as I_Target_Booking ,		
		Sum(I_Target_Enrollment) as I_Target_Enrollment ,		
		Sum(I_Target_Billing) as I_Target_Billing ,
		Sum(I_Target_RFF) as I_Target_RFF,
		S_Remarks as I_Center_Id
		FROM @tblSUM
Group By I_Product_ID,
		S_Remarks ,
		I_Month ,        
		I_Hierarchy_Detail_ID ,
		I_Year ,
		I_Status_ID Order By I_Product_ID,S_Remarks,I_Month	
END
GO
