	WHERE HMD.I_Parent_ID =@iHierachyDetailID AND HMD.I_Status = 1

	SET @iCount = @iCount + 1
	END



	DECLARE @tblHD2 TABLE
	(
		ID INT IDENTITY(1,1),
		I_Hierarchy_Detail_ID int,	
		S_Hierarchy_Name VARCHAR(200),
		S_Hierarchy_Chain VARCHAR(200),	
