-- =============================================
-- Author:		Debarshi Basu
-- Create date: 22/03/2007
-- Description:	Get the List of all Agreement Templates
-- =============================================

CREATE PROCEDURE [NETWORK].[uspGetAgreementTemplateList]
	@iAgreementTempID INT= NULL,
	@iCountryID INT = NULL,
	@sCode varchar(20) = NULL
AS
BEGIN
	SET NOCOUNT ON;

	SELECT I_Agreement_Template_ID,
		S_Agreement_Template_Code,
		I_Country_ID,
		I_Status
	FROM NETWORK.T_Agreement_Template_Master
	WHERE ISNULL(@iAgreementTempID,I_Agreement_Template_ID) = I_Agreement_Template_ID
	AND ISNULL(@iCountryID,I_Country_ID) = I_Country_ID
	AND ISNULL(@sCode,S_Agreement_Template_Code) = S_Agreement_Template_Code
	AND I_Status <> 0
	
END
GO
PRINT N'Creating Procedure [NETWORK].[uspGetAgreementsForCenterCreation]...';


GO
-- =============================================
-- Author:		Debarshi Basu
-- Create date: 22/03/2007
-- Description:	Get the List of all Agreements for center creation 
-- =============================================

CREATE PROCEDURE [NETWORK].[uspGetAgreementsForCenterCreation]
	@iStatusApproved INT
AS
BEGIN

	SELECT AD.I_Agreement_ID,
		   AD.S_Company_Name,AD.S_Agreement_Code,
		   AD.Dt_Agreement_date,
		   BP.S_BP_Type,
		   AD.I_Status,
		   AD.I_Brand_ID
	FROM NETWORK.T_Agreement_Details AD
	INNER JOIN NETWORK.T_BP_Master BP
	ON AD.I_BP_ID = BP.I_BP_ID
	WHERE AD.I_Status = @iStatusApproved
	AND AD.I_Agreement_ID NOT IN
		(SELECT I_Agreement_ID FROM NETWORK.T_Agreement_Center)
	ORDER BY AD.Dt_Agreement_date DESC

	
END
GO
PRINT N'Creating Procedure [NETWORK].[uspGetAgreements]...';


GO
CREATE PROCEDURE [NETWORK].[uspGetAgreements]
	@sCompanyName varchar(100)=NULL,
	@iBPType int=NULL,
	@iBPUserID INT = NULL,
	@iBrandId INT=NULL
AS
BEGIN

	SELECT AD.I_Agreement_ID,
		   AD.S_Company_Name,
		   AD.S_Agreement_Code,
		   AD.Dt_Agreement_date,
		   BP.S_BP_Type,
		   AD.I_Brand_ID,
		   AD.I_Status
	FROM NETWORK.T_Agreement_Details AD
	INNER JOIN NETWORK.T_BP_Master BP
	ON AD.I_BP_ID = BP.I_BP_ID
	WHERE AD.I_Status <> 0
	AND AD.S_Company_Name LIKE '%'+ ISNULL(@sCompanyName,'')+'%'
	AND ISNULL(@iBPType,AD.I_BP_ID) = AD.I_BP_ID
	--AND ISNULL(@iBPUserID,AD.I_BP_User_ID) = AD.I_BP_User_ID
	AND AD.I_Brand_ID=@iBrandId
	ORDER BY AD.Dt_Agreement_date DESC
	
END
GO
