			INNER JOIN dbo.T_Brand_Center_Details BCD
			ON BCD.I_Centre_Id = CM.I_Centre_Id
		WHERE AR.I_Status = @iStatus
			AND BCD.I_Status = 1
	END
	ELSE
	BEGIN
		SELECT 
