CREATE PROCEDURE [NETWORK].[uspModifyBusinessPartner]
	@iUserID int,
	@sLoginID varchar(200),
	@sPassword varchar(200)=NULL,
	@sTitle varchar(20)=NULL,
	@sFirstName varchar(100),
	@sMiddleName varchar(100)=NULL,
	@sLastName varchar(100)=NULL,
	@sEmailID varchar(200)=NULL,
	@sUserType varchar(20),	
	@sCreatedBy varchar(20),
	@DOB DATETIME,
	@iflag int
AS
BEGIN TRY
	
	SET NOCOUNT ON;
	DECLARE @iTempUserID int;
	DECLARE @iSequence int
	SET @iTempUserID = NULL
	IF @iFlag = 1
	BEGIN

		SELECT @iSequence = MAX(I_User_ID) FROM dbo.T_User_Master
		SET @sLoginID = @sLoginID + CAST((@iSequence + 1) AS VARCHAR(20))

		INSERT INTO dbo.T_User_Master
		(
			S_Login_ID, 
			S_Password,
			S_Title,
			S_First_Name,
			S_Middle_Name,
			S_Last_Name,
			S_Email_ID,
			S_User_Type,
			I_Status,
			S_Crtd_By,
			Dt_Crtd_On,
			Dt_Date_Of_Birth 
		)
		VALUES
		(	
			@sLoginID,
			@sPassword,
			@sTitle,
			@sFirstName,
			@sMiddleName,
			@sLastName,
			@sEmailID,
			@sUserType,
			1,
			@sCreatedBy,
			GETDATE(),
			@DOB
		)    
		
		SET @iTempUserID=SCOPE_IDENTITY()

	END
--	ELSE IF @iFlag = 2
--	Begin
--	--Not required for BP user
--	END
--	ELSE IF @iFlag = 3
--	Begin
--	--Not required for BP user
--	End
	
	SELECT @sLoginID AS LoginID, ISNULL(@iTempUserID, @iUserID) AS USERID

END TRY
BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [NETWORK].[uspModifyAgreementTemplateMaster]...';


GO
-- =============================================
-- Author:		Debarshi Basu
-- Create date: 23/03/2007
-- Description:	Modifies the Agreement Template master table
-- =============================================
CREATE PROCEDURE [NETWORK].[uspModifyAgreementTemplateMaster] 

	@iTemplateID INT,
	@sTemplateCode VARCHAR(20),
	@iCountryID INT,
	@iDocumentID INT,
	@sCreatedBy VARCHAR(20),
	@dCreatedOn DATETIME,	
	@iFlag INT
AS
BEGIN TRY

	SET NOCOUNT OFF;

	IF(@iFlag=1)
		BEGIN
			INSERT INTO NETWORK.T_Agreement_Template_Master (
											S_Agreement_Template_Code,
											I_Country_ID,
											I_Document_ID,
											S_Crtd_By,
											Dt_Crtd_On,
											I_Status
											)
			VALUES (
					@sTemplateCode,
					@iCountryID,
					@iDocumentID,
					@sCreatedBy,	
					@dCreatedOn,
					1
					)

		END
	IF(@iFlag=2)
		BEGIN
			UPDATE NETWORK.T_Agreement_Template_Master SET
			S_Agreement_Template_Code = @sTemplateCode,
			I_Country_ID = @iCountryID,
			I_Document_ID = @iDocumentID,
			S_Upd_By = @sCreatedBy,
			Dt_Upd_On = @dCreatedOn
			WHERE I_Agreement_Template_ID = @iTemplateID
				AND I_Status = 1
		END

	IF(@iFlag=3)
		BEGIN
			UPDATE NETWORK.T_Agreement_Template_Master SET
			I_Status=0,
			S_Upd_By=@sCreatedBy,
			Dt_Upd_On=@dCreatedOn
			WHERE I_Agreement_Template_ID = @iTemplateID
				AND I_Status = 1
		END
	
END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
