	@sCreatedBy varchar(20),
	@dtCreatedOn datetime,
	@iFlag int
AS
BEGIN TRY
	BEGIN
		-- SET NOCOUNT ON added to prevent extra result sets from
		-- interfering with SELECT statements.
		SET NOCOUNT ON;
		-- Insert NETWORK.T_Termination_Request
		IF(@iFlag = 1)
		BEGIN
			INSERT INTO NETWORK.T_Termination_Request_Audit
			(
			I_Center_Termination_ID,
			I_Centre_Id,
			I_Document_ID,
			S_Reason,
			I_Status,
			S_Crtd_By,
			S_Upd_By,
			Dt_Crtd_On,
			Dt_Upd_On
			)
			SELECT *
			FROM NETWORK.T_Termination_Request
			WHERE I_Centre_Id = @iCenterID

			DELETE FROM NETWORK.T_Termination_Request
			WHERE I_Centre_Id = @iCenterID
			
			INSERT INTO NETWORK.T_Termination_Request
			(
			I_Centre_Id,
			I_Document_ID,
			S_Reason,
			I_Status,
			S_Crtd_By,
			Dt_Crtd_On	
			)
			VALUES
			(
			@iCenterID,
			@iDocumentID,
			@sReason,
			@iStatus,
			@sCreatedBy,
			@dtCreatedOn
			)
		END
--		Insert NETWORK.T_Termination_Request_Audit AND Update NETWORK.T_Termination_Request
		ELSE IF (@iFlag = 2)
		BEGIN
			INSERT INTO NETWORK.T_Termination_Request_Audit
			(
			I_Center_Termination_ID,
			I_Centre_Id,
			I_Document_ID,
			S_Reason,
			I_Status,
			S_Crtd_By,
			S_Upd_By,
