PRINT N'Creating Procedure [PLACEMENT].[uspCheckBusinessRule]...';


GO
/*
-- =================================================================
-- Author:Shankha Roy
-- Create date:12/05/2007 
-- Description:Insert Check business rule for student placement registration 
-- =================================================================
*/
CREATE PROCEDURE [PLACEMENT].[uspCheckBusinessRule]
(
@iStudentDetailID INT,
@iAge INT = null,
@iTime INT = NULL
)
AS
BEGIN

DECLARE @RtValid VARCHAR (1)
	
IF EXISTS(SELECT TS.S_Student_ID,TS.S_Age,TSC.Dt_Course_Start_Date,	TSC.Dt_Course_Expected_End_Date
	FROM T_Student_Detail TS INNER JOIN T_Student_Course_Detail TSC ON TS.I_Student_Detail_ID = TSC.I_Student_Detail_ID 
	WHERE TS.S_Age < @iAge	AND DATEDIFF(year,TSC.Dt_Course_Start_Date , TSC.Dt_Course_Expected_End_Date) >= @iTime
	AND TS.I_Student_Detail_ID = @iStudentDetailID )
BEGIN
	SET @RtValid ='T'
END
ELSE
 BEGIN
	SET @RtValid = 'F'
  END
SELECT @RtValid



END
GO
PRINT N'Creating Procedure [PLACEMENT].[uspChkVacancyOpen]...';


GO
/*
-- =================================================================
-- Author:Shankha Roy
-- Create date:12/05/2007 
-- Description:Insert Check business rule for student placement registration for 
-- VacancyOpen  and Vacancy Fill
-- =================================================================
*/
CREATE PROCEDURE [PLACEMENT].[uspChkVacancyOpen]
(
@iVacancyID  INT
)
AS
BEGIN

DECLARE @RtValid VARCHAR (1)


IF EXISTS(SELECT I_No_Of_Openings from PLACEMENT.T_Vacancy_Detail
WHERE I_Vacancy_ID =@iVacancyID
AND I_No_Of_Openings >=(SELECT COUNT(*) FROM PLACEMENT.T_Shortlisted_Students
WHERE I_Vacancy_ID =@iVacancyID AND C_Interview_Status ='S'))
BEGIN
	SET @RtValid ='T'
END
ELSE
 BEGIN
	SET @RtValid = 'F'
  END
SELECT @RtValid

END
GO
