PRINT N'Creating Procedure [PLACEMENT].[uspGetDetailVacancy]...';


GO
/*
-- =================================================================
-- Author:Shankha Roy
-- Create date:12/05/2007
-- Description:Get vacancy record From T_Vacancy_Detail table
-- Parameter :
 	   @iVacancyID
-- ================================================================= 	   
*/

CREATE PROCEDURE [PLACEMENT].[uspGetDetailVacancy]
-- Input parameter
(
	   @iVacancyID INT
)
AS
BEGIN 

	SELECT 
			I_Employer_ID, 
			ISNULL(S_Min_Height,' ') AS S_Min_Height, 
			ISNULL(S_Max_Height,' ') AS S_Max_Height,
			ISNULL(S_Min_Weight,' ') AS S_Min_Weight,
			ISNULL(S_Height_UOM,' ') AS S_Height_UOM,
			ISNULL(S_Max_Weight,' ') AS S_Max_Weight,
			ISNULL(C_Gender,' ') AS C_Gender, 
			ISNULL(I_No_Of_Openings,0) AS I_No_Of_Openings,
			ISNULL(S_Weight_UOM,' ') AS S_Weight_UOM,
			ISNULL(S_Job_Type, ' ') AS S_Job_Type,
			ISNULL(S_Pay_Scale,' ') AS S_Pay_Scale, 
			ISNULL(S_Vacancy_Description,' ') AS S_Vacancy_Description, 
			ISNULL(S_Remarks,' ') AS S_Remarks,
			B_Transport, 
			ISNULL(S_Role_Designation,' ') AS S_Role_Designation,
			ISNULL(Dt_Date_Of_Interview,' ') AS Dt_Date_Of_Interview,
			ISNULL(I_Nature_Of_Business,' ') AS I_Nature_Of_Business,
			B_Fresher_Allowed,
			ISNULL(S_Work_Experience,' ') AS S_Work_Experience,
			B_Shift
	FROM  [PLACEMENT].T_Vacancy_Detail
	WHERE
			I_Vacancy_ID = @iVacancyID
	AND
			I_Status=1
			
-- Selecting qualification for vacancy
	SELECT 
			I_Qualification_NAME_ID
    FROM    [PLACEMENT].T_Vacancy_Qualifications
    
    WHERE
			I_Vacancy_ID = @iVacancyID
	AND
			I_Status=1
	
-- Selecting Skill for vacancy 

   SELECT 
   			I_Skills_ID, 
			B_Soft_Skill, 
			B_Mandatory, 
			B_Technical_Skill  
   FROM  [PLACEMENT].T_Vacancy_Skills
   WHERE
			I_Vacancy_ID = @iVacancyID
	AND
			I_Status=1
			
END
GO
PRINT N'Creating Procedure [PLACEMENT].[uspGetEligibleStudentList]...';


GO
/*  
-- ======================================================================================================================  
-- Author:Ujjwal Sinha  
-- Create date:22/05/2007   
-- Description:Select combined List from T_Shortlisted_Student,T_Vacanct_Detail,T_Business_Master,T_Employer_detail table   
-- Parameters: @iEmployerID , @dtDateofInterview  
-- ======================================================================================================================  
*/  
  
CREATE PROCEDURE [PLACEMENT].[uspGetEligibleStudentList]  
(  
 @iEmployerID  INT = null,  
 @dtDateofInterview DATETIME =null,  
 @iVacancyID INT = NULL  
)  
AS  
BEGIN  
 SELECT ISNULL(A.S_Student_ID,' ') AS S_Student_ID   ,  
           ISNULL(A.S_First_Name,' ') AS S_First_Name   ,  
           ISNULL(A.S_Middle_Name,' ') AS S_Middle_Name ,  
           ISNULL(A.S_Last_Name,' ') AS S_Last_Name     ,  
           ISNULL(B.S_Center_Code,' ') AS S_Center_Code ,  
     ISNULL(B.S_Center_Name,' ') AS S_Center_Name ,   
     ISNULL(J.C_Interview_Status,' ') AS C_Interview_Status,  
     ISNULL(J.I_Shortlisted_Student_ID,0) AS I_Shortlisted_Student_ID,  
     ISNULL(J.I_Student_Detail_ID,0) AS I_Student_Detail_ID  
          FROM [dbo].T_Student_Detail                  A,  
        [dbo].T_Centre_Master                       B,  
               [PLACEMENT].T_Vacancy_Detail            C,  
               [dbo].T_Student_Center_Detail           I,  
      [PLACEMENT].T_Shortlisted_Students       J  
     WHERE I.I_Student_Detail_ID = A.I_Student_Detail_ID  
     AND I.I_Student_Detail_ID = J.I_Student_Detail_ID  
     AND J.C_Student_Acknowledgement='A'  
     AND ISNULL(J.C_Interview_Status, 'O') = 'O'
              AND I.I_Centre_Id = B.I_Centre_Id  
     AND C.I_Vacancy_ID = J.I_Vacancy_ID  
     AND J.I_Student_Detail_ID = A.I_Student_Detail_ID  
              AND C.I_Employer_ID = @iEmployerID  
              AND C.Dt_Date_Of_Interview = COALESCE(@DtDateofInterview,C.Dt_Date_Of_Interview)  
     AND C.I_Vacancy_ID = COALESCE(@iVacancyID,C.I_Vacancy_ID)  
           AND A.I_Status = 1   
              AND B.I_Status = 1   
              AND C.I_Status = 1   
              AND I.I_Status = 1   
     AND J.I_Status = 1  
  
 SELECT * FROM  
  (SELECT ISNULL(F.I_Skills_ID,0) AS I_Skills_ID,  
           ISNULL(I.S_Skill_Desc,' ') AS S_Skill_Desc,  
           ISNULL(F.S_Skill_Proficiency,' ') AS S_Skill_Proficiency,  
                  F.B_Soft_Skill,  
                  F.B_Technical_Skill,  
           ISNULL(F.I_Student_Detail_ID,0) AS I_Student_Detail_ID   
          FROM   
               [PLACEMENT].T_Vacancy_Detail    E,  
               [PLACEMENT].T_Placement_Skills          F,   
               [PLACEMENT].T_Placement_Registration    H,  
               [dbo].T_EOS_Skill_Master                I,   
               [PLACEMENT].T_Shortlisted_Students    J  
     WHERE   
              E.I_EMPLOYER_ID=@iEmployerID  
              AND E.I_Vacancy_ID = J.I_Vacancy_ID  
              AND J.I_Student_Detail_ID = H.I_Student_Detail_ID  
              AND F.I_Student_Detail_ID = H.I_Student_Detail_ID  
              AND I.I_Skill_ID = F.I_Skills_ID  
              AND F.I_Status = 1   
              AND H.I_Status = 1   
              AND I.I_Status = 1   
     AND E.I_Status = 1   
     AND E.I_Vacancy_ID = COALESCE(@iVacancyID,E.I_Vacancy_ID)  
              AND E.Dt_Date_Of_Interview = COALESCE(@DtDateofInterview,E.Dt_Date_Of_Interview)  
              ) A LEFT OUTER JOIN  
   [PLACEMENT].T_Educational_Qualification G  
   ON G.I_Student_Detail_ID = A.I_Student_Detail_ID AND G.I_Status = 1   
   
  
 SELECT ISNULL(G.I_Qualification_Name_ID,0) AS I_Qualification_Name_ID,  
           ISNULL(G.I_Student_Detail_ID,0) AS I_Student_Detail_ID,  
           ISNULL(G.I_Year_Of_Passing,0) AS I_Year_Of_Passing,  
           ISNULL(G.S_Percentage_Of_Marks,' ') AS S_Percentage_Of_Marks,  
           ISNULL(I.S_Qualification_Name,0) AS S_Qualification_Name  
          FROM [PLACEMENT].T_Vacancy_Detail    E,  
               [PLACEMENT].T_Placement_Registration    H,  
               [PLACEMENT].T_Educational_Qualification G,   
               [dbo].T_Qualification_Name_Master       I ,  
               [PLACEMENT].T_Shortlisted_Students    J  
     WHERE   
             E.I_EMPLOYER_ID=@iEmployerID  
    AND E.Dt_Date_Of_Interview = COALESCE(@DtDateofInterview,E.Dt_Date_Of_Interview)  
     AND E.I_Vacancy_ID = J.I_Vacancy_ID  
              AND E.I_Vacancy_ID = COALESCE(@iVacancyID,E.I_Vacancy_ID)  
     AND J.I_Student_Detail_ID = H.I_Student_Detail_ID  
              AND G.I_Student_Detail_ID = H.I_Student_Detail_ID  
              AND G.I_Qualification_Name_ID = I.I_Qualification_Name_ID  
              AND H.I_Status = 1   
              AND I.I_Status = 1   
     AND E.I_Status = 1   
              AND G.I_Status = 1   
     AND J.I_Status = 1  
  
  
 SELECT ISNULL(I.S_Certificate_Name,' ') AS S_Certificate_Name,  
           ISNULL(I.S_Certificate_Vender_Name, ' ') AS S_Certificate_Vender_Name,   
           ISNULL(G.I_Student_Detail_ID,0) AS I_Student_Detail_ID,  
     I.I_International_Certificate_ID  
          FROM [PLACEMENT].T_Vacancy_Detail     E,  
               [PLACEMENT].T_Placement_Registration   H,  
               [PLACEMENT].T_International_Certificate  G,   
               [PLACEMENT].T_Intnal_Certificate_Master      I,  
               [PLACEMENT].T_Shortlisted_Students   J  
     WHERE   
             E.I_EMPLOYER_ID=@iEmployerID  
    AND E.Dt_Date_Of_Interview = COALESCE(@DtDateofInterview,E.Dt_Date_Of_Interview)  
              AND E.I_Vacancy_ID = J.I_Vacancy_ID  
     AND E.I_Vacancy_ID = COALESCE(@iVacancyID,E.I_Vacancy_ID)  
              AND J.I_Student_Detail_ID = H.I_Student_Detail_ID  
              AND G.I_Student_Detail_ID = H.I_Student_Detail_ID  
              AND G.I_International_Certificate_ID = I.I_International_Certificate_ID  
              AND H.I_Status = 1   
              AND I.I_Status = 1   
     AND E.I_Status = 1   
              AND G.I_Status = 1   
     AND J.I_Status = 1  
  
   
  
END
GO
PRINT N'Creating Procedure [PLACEMENT].[uspGetEmployerList]...';


GO
/*
-- =================================================================
-- Author:Shankha Roy
-- Create date:12/05/2007 
-- Description: Select employer from T_Employer_Detail tabel
-- Parameter : @sCompanyName,@sCompanyCode , @dtFirstEnquiryDate 
-- =================================================================
*/


CREATE PROCEDURE [PLACEMENT].[uspGetEmployerList]
(
@sCompanyName VARCHAR(250)= null,
@sCompanyCode VARCHAR(50) = null,
@dtFirstEnquiryDate DATETIME =null,
@iEmployerID INT = null,
@iBrandID INT =null
)
AS
BEGIN

DECLARE @CompanyName VARCHAR(250)
DECLARE @CompanyCode VARCHAR(50)

IF(@sCompanyName IS null)
 SET @CompanyName=''
IF(@sCompanyCode IS null)
 SET @CompanyCode=''

SET @CompanyName= @sCompanyName+'%'
SET @CompanyCode= @sCompanyCode+'%'

 SELECT 
        ISNULL(ED.I_Employer_ID,0) AS  I_Employer_ID,
        ISNULL(ED.I_State_ID,0) AS I_State_ID  ,
        ISNULL(ED.I_Nature_of_Business,0) AS I_Nature_of_Business,
        ISNULL(ED.I_Country_ID,0) AS I_Country_ID ,
        ISNULL(ED.I_City_ID,0) AS I_City_ID,
        ISNULL(ED.S_Company_Code,' ') AS S_Company_Code,
        ISNULL(ED.S_Company_Name,' ') AS S_Company_Name,
        ISNULL(ED.Dt_First_Enquiry_Date,' ') AS Dt_First_Enquiry_Date,
        ISNULL(ED.S_Group_Company_Code,' ') AS S_Group_Company_Code,
        ISNULL(ED.S_Address,' ') AS S_Address ,
        ISNULL(ED.S_Pincode,' ') AS S_Pincode,
		ISNULL(UM.S_Login_ID,' ') AS S_Login_ID
         FROM [PLACEMENT].T_Employer_Detail ED
		 INNER JOIN dbo.T_User_Master UM
		 ON UM.I_Reference_ID = ED.I_Employer_ID
		 AND UM.S_User_Type = 'EM'		
         WHERE ED.I_Status = 1
		 AND
	     S_Company_Code LIKE COALESCE(@CompanyCode,S_Company_Code) AND 
	     S_Company_Name LIKE COALESCE(@CompanyName,S_Company_Name) AND 
	     Dt_First_Enquiry_Date LIKE COALESCE(@dtFirstEnquiryDate,Dt_First_Enquiry_Date)
		 AND I_Employer_ID = COALESCE(@iEmployerID,I_Employer_ID)
		 AND UM.I_User_ID IN (SELECT I_User_ID FROM [Placement].[fnGetUserIDFormBrand](@iBrandID))
		ORDER BY S_Company_Name

END
GO
