PRINT N'Creating Procedure [PLACEMENT].[uspGetVacancyList]...';


GO
/*  
-- =================================================================  
-- Author:Shankha Roy  
-- Create date:12/05/2007  
-- Description:Get vacancy record From T_Vacancy_Detail table  
-- Parameter :     
-- =================================================================       
*/  
  
CREATE PROCEDURE [PLACEMENT].[uspGetVacancyList]  
(  
@iEmployerID INT = null,  
@dtDateofInterview DATETIME = NULL  
)  
AS  
BEGIN   
  
  
		DECLARE @V_STUDID INT
		DECLARE @V_TMPSTUDID INT
		DECLARE @V_CITY VARCHAR(50)
		DECLARE @V_OPENING INT
		DECLARE @V_LOCATION VARCHAR(1000)

		SET @V_STUDID = 0
		SET @V_TMPSTUDID = 0
		SET @V_CITY = ''
		SET @V_OPENING = 0
		SET @V_LOCATION = ''

		DECLARE @TBLOPENING TABLE  (STUDID INT, LOCATION VARCHAR(2000) )

		DECLARE CUR_PREFLOC CURSOR FOR  
		SELECT L.I_VACANCY_ID, CM.S_City_Name as CityName, L.I_VACANCY  
		FROM [PLACEMENT].T_Job_Opening L  
		INNER JOIN T_City_Master CM      
		ON L.I_CITY_ID=CM.I_City_ID  
		WHERE L.I_VACANCY_ID IN 
		(SELECT I_Vacancy_ID FROM [PLACEMENT].T_Vacancy_Detail WHERE I_Employer_ID = @iEmployerID AND I_Status=1 AND   Dt_Date_Of_Interview =  COALESCE(@dtDateofInterview,Dt_Date_Of_Interview))
		ORDER BY 1
		OPEN CUR_PREFLOC  
		FETCH NEXT FROM CUR_PREFLOC INTO @V_STUDID, @V_CITY, @V_OPENING  
		WHILE @@FETCH_STATUS=0  
		BEGIN  
		  
		 IF (@V_TMPSTUDID = @V_STUDID)  
		 BEGIN  
		  SET @V_LOCATION = @V_LOCATION + ', ' + @V_CITY + '(' +  CAST(@V_OPENING AS VARCHAR) + ')'  
		 END  
		 ELSE  
		 BEGIN  
		  SET @V_LOCATION = @V_CITY + '(' +  CAST(@V_OPENING AS VARCHAR) + ')'
		 END
		 IF EXISTS(SELECT * FROM @TBLOPENING WHERE STUDID = @V_STUDID)
		 BEGIN
			UPDATE @TBLOPENING SET LOCATION = @V_LOCATION WHERE STUDID = @V_STUDID
		 END
		 ELSE
		 BEGIN
			INSERT INTO @TBLOPENING VALUES (@V_STUDID, @V_LOCATION)
		 END
		 SET @V_TMPSTUDID = @V_STUDID  
		FETCH NEXT FROM CUR_PREFLOC INTO @V_STUDID, @V_CITY, @V_OPENING  
		END  
		CLOSE CUR_PREFLOC   
		DEALLOCATE CUR_PREFLOC   

  
 SELECT ISNULL(I_Employer_ID,0) AS I_Employer_ID ,  
     ISNULL(I_Vacancy_ID,0)   AS I_Vacancy_ID  ,  
           ISNULL(S_Min_Height,' ') AS S_Min_Height ,  
           ISNULL(S_Max_Height,' ') AS S_Max_Height ,  
           ISNULL(S_Min_Weight,' ') AS S_Min_Weight ,  
           ISNULL(S_Height_UOM,' ') AS S_Height_UOM ,   
        ISNULL(S_Max_Weight,' ') AS  S_Max_Weight ,  
           ISNULL(C_Gender,' ') AS  C_Gender ,  
           ISNULL(I_No_Of_Openings,0) AS I_No_Of_Openings ,  
           ISNULL(S_Weight_UOM,' ') AS S_Weight_UOM ,  
           ISNULL(S_Job_Type,' ') AS  S_Job_Type ,   
        ISNULL(S_Pay_Scale,' ') AS S_Pay_Scale ,  
           ISNULL(S_Vacancy_Description,' ') AS S_Vacancy_Description ,  
           ISNULL(S_Remarks,' ') AS  S_Remarks ,  
                  B_Transport ,  
           ISNULL(S_Role_Designation,' ') AS S_Role_Designation ,   
        ISNULL(Dt_Date_Of_Interview,' ') AS Dt_Date_Of_Interview ,  
           ISNULL(I_Nature_Of_Business,0) AS I_Nature_Of_Business ,  
                  B_Fresher_Allowed ,  
           ISNULL(S_Work_Experience,' ') AS S_Work_Experience ,  
            B_Shift, 
            ISNULL(B.LOCATION, ' ')  AS CITYWISELOCATION
 FROM  [PLACEMENT].T_Vacancy_Detail A INNER JOIN @TBLOPENING B ON  A.I_Vacancy_ID = B.STUDID
 WHERE I_Status=1  
    AND   I_Employer_ID = @iEmployerID  
 AND   Dt_Date_Of_Interview =  COALESCE(@dtDateofInterview,Dt_Date_Of_Interview)  
      
END
GO
PRINT N'Creating Procedure [PLACEMENT].[uspGetVacancyDetail]...';


GO
/*  
-- ======================================================================================================================  
-- Author:Ujjwal Sinha  
-- Create date:26/05/2007   
-- Description:Select combined List from T_Shortlisted_Student,T_Vacanct_Detail,T_Business_Master,T_Employer_detail table   
-- ======================================================================================================================  
*/  
  
CREATE PROCEDURE [PLACEMENT].[uspGetVacancyDetail]  
(  
 @iVacancyID  INT  
   
)  
AS  
BEGIN  
 SELECT ISNULL(I_Employer_ID,0) AS I_Employer_ID ,  
               ISNULL(S_Min_Height,' ') AS S_Min_Height ,  
               ISNULL(S_Max_Height,' ') AS S_Max_Height ,  
               ISNULL(S_Height_UOM,' ') AS S_Height_UOM ,  
               ISNULL(S_Min_Weight,' ') AS S_Min_Weight ,  
               ISNULL(S_Max_Weight,' ') AS S_Max_Weight ,  
               ISNULL(S_Weight_UOM,' ') AS S_Weight_UOM ,  
               ISNULL(C_Gender,' ') AS C_Gender ,  
               ISNULL(I_No_Of_Openings,0) AS I_No_Of_Openings ,  
               ISNULL(S_Job_Type,' ') AS S_Job_Type ,  
               ISNULL(S_Pay_Scale,' ') AS S_Pay_Scale ,  
               ISNULL(S_Vacancy_Description,' ') AS S_Vacancy_Description ,  
               ISNULL(S_Remarks,' ') AS S_Remarks ,  
               ISNULL(S_Role_Designation,' ') AS S_Role_Designation ,  
               ISNULL(Dt_Date_Of_Interview,' ') AS Dt_Date_Of_Interview ,  
               B_Fresher_allowed,  
               ISNULL(S_Work_Experience,' ') AS S_Work_Experience ,  
               B_Shift,  
               ISNULL(I_Nature_Of_Business,0) AS I_Nature_Of_Business ,  
               B_Transport                 
                
          FROM [PLACEMENT].T_Vacancy_Detail   
                 
     WHERE I_Vacancy_ID = COALESCE(@iVacancyID , I_Vacancy_ID)  
              AND I_Status = 1   
               
  
-- Skill set for Vacancy  
  
SELECT     ISNULL(I_Vacancy_ID,0) AS I_Vacancy_ID,   
ISNULL(I_Skills_ID ,0) AS I_Skills_ID,   
ISNULL(B_Soft_Skill,0) AS B_Soft_Skill,   
ISNULL(B_Mandatory,0) AS  B_Mandatory,  
ISNULL(B_Technical_Skill,0) AS B_Technical_Skill  
FROM  PLACEMENT.T_Vacancy_Skills  
WHERE I_Vacancy_ID =@iVacancyID   
AND I_Status = 1   
  
-- QUALIFICATION SET FOR VACANCY  
SELECT       
ISNULL(I_Qualification_Name_ID,0) AS  I_Qualification_Name_ID,  
ISNULL(I_Vacancy_ID,0) AS I_Vacancy_ID  
FROM   PLACEMENT.T_Vacancy_Qualifications  
WHERE I_Vacancy_ID =@iVacancyID   
AND I_Status = 1   
  
-- Location wise VACANCY  list
SELECT   
a.I_Vacancy_ID,  
a.I_CITY_ID, 
b.S_City_Name,  
a.I_VACANCY
FROM   [PLACEMENT].T_JOB_OPENING A inner join T_City_Master B
on a.I_CITY_ID = B.I_City_ID
WHERE a.I_Vacancy_ID =@iVacancyID   
  

END
GO
PRINT N'Creating Procedure [PLACEMENT].[uspGetVacancyData]...';


GO
/*
-- ======================================================================================================================
-- Author:Ujjwal Sinha
-- Create date:22/05/2007 
-- Description:Select combined List from T_Shortlisted_Student,T_Vacanct_Detail,T_Business_Master,T_Employer_detail table 
-- ======================================================================================================================
*/

CREATE PROCEDURE [PLACEMENT].[uspGetVacancyData]
(
	@iVacancyID		INT,
	@DtDateofInterview	DATETIME = null
	
)
AS
BEGIN
	SELECT ISNULL(Q.S_Qualification_Name,' ') AS S_Qualification_Name ,
           ISNULL(S.S_Skill_Desc,' ') AS S_Skill_Desc ,
           ISNULL(V.I_Qualification_Name_ID,0) AS I_Qualification_Name_ID ,
           ISNULL(K.I_Skills_ID,0) AS I_Skills_ID
          FROM [dbo].T_Qualification_Name_Master Q,
	       [dbo].T_EOS_Skill_Master S,
	       [PLACEMENT].T_Vacancy_Qualifications V,
	       [PLACEMENT].T_Vacancy_Detail D,
               [PLACEMENT].T_Vacancy_Skills K
	    WHERE V.I_Vacancy_ID = D.I_Vacancy_ID
              AND Q.I_Qualification_Name_ID = V.I_Qualification_Name_ID
              AND K.I_Vacancy_ID = D.I_Vacancy_ID
              AND S.I_Skill_ID = K.I_Skills_ID
              AND D.I_Vacancy_ID = COALESCE(@iVacancyID ,D.I_Vacancy_ID)
              AND D.Dt_Date_Of_Interview = COALESCE(@DtDateofInterview,D.Dt_Date_Of_Interview)
              AND D.I_Status = 1 
              AND Q.I_Status = 1 
              AND S.I_Status = 1 
              AND V.I_Status = 1 
              AND K.I_Status = 1   	
END
GO
