PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetAllCertificateQuery]...';


GO
CREATE PROCEDURE [PSCERTIFICATE].[uspGetAllCertificateQuery] 
(		
	@dtFromDate DATETIME = NULL,
	@dtToDate DATETIME = NULL,
	@HierarchyDetailID INT = NULL,
	@BrandID INT = NULL,
	@iStudentDetailID INT = NULL
)

AS
BEGIN

SET NOCOUNT ON 

IF(@dtToDate IS NOT NULL)
	BEGIN
	SET @dtTodate = DATEADD(dd,1,@dtTodate)
	END


DECLARE @User TABLE
(
 I_User_ID INT
)

DECLARE @Centre TABLE
(
 I_Center_Id INT
)

INSERT INTO @CENTRE
SELECT I_CENTER_ID FROM DBO.FNGETCENTERIDFROMHIERARCHY(@HIERARCHYDETAILID,@BrandID)

IF(@HierarchyDetailID IS NOT NULL )
BEGIN
	INSERT INTO @User
	SELECT distinct UM.I_User_ID FROM dbo.T_User_Master UM
	INNER JOIN dbo.T_User_Hierarchy_Details UHD
	on UM.I_User_ID=UHD.I_User_ID
	inner join T_Center_Hierarchy_Details CHD
	on UHD.I_Hierarchy_Detail_ID=CHD.I_Hierarchy_Detail_ID
	and UHD.I_Hierarchy_Master_ID = CHD.I_Hierarchy_Master_ID
	WHERE CHD.I_Center_Id in 
	(select I_Center_Id from @Centre)
	AND CHD.I_Status <> 0
	AND UHD.I_Status <> 0
	AND UM.I_Status <> 0	

END
IF (@iStudentDetailID IS NOT NULL)
BEGIN

	INSERT INTO @User
	select @iStudentDetailID
END

DECLARE @TempTable TABLE
(
ID INT IDENTITY(1,1),
I_Certificate_Query_ID INT,
I_Student_Detail_ID INT,
S_Replied_By VARCHAR(100),
S_Crtd_By VARCHAR(100),
Dt_Crtd_On DATETIME,
Dt_Upd_On DATETIME,
S_Query VARCHAR(5000),
S_Reply VARCHAR(2000),
I_Status INT,
B_PS_Flag INT,
S_Title VARCHAR(250),
S_First_Name VARCHAR(100),
S_Middle_Name VARCHAR(100),
S_Last_Name VARCHAR(100),
S_Student_ID VARCHAR(100),
S_Center_Name VARCHAR(250)
)

INSERT INTO @TempTable
SELECT DISTINCT
		  ISNULL(A.I_Certificate_Query_ID, ' ') AS I_Certificate_Query_ID,
		  ISNULL(A.I_Student_Detail_ID,0) AS I_Student_Detail_ID,
		  ISNULL(A.S_Replied_By,' ') AS S_Replied_By,
		  ISNULL(A.S_Crtd_By,' ') AS S_Crtd_By,
		  ISNULL(A.Dt_Crtd_On,' ') AS Dt_Crtd_On,
		  ISNULL(A.Dt_Upd_On,' ') AS Dt_Upd_On,
		  ISNULL(A.S_Query, ' ') AS S_Query,
		  ISNULL(A.S_Reply, ' ') AS S_Reply,
		  ISNULL(A.I_Status,0) AS I_Status,
		  ISNULL(A.B_PS_Flag, 0) AS B_PS_Flag,
		  ISNULL(UM.S_Title, ' ') AS S_Title,
		  ISNULL(UM.S_First_Name, ' ') AS S_First_Name,
		  ISNULL(UM.S_Middle_Name, ' ') AS S_Middle_Name,
		  ISNULL(UM.S_Last_Name, ' ') AS S_Last_Name,
		  ISNULL(UM.S_Login_Id, ' ') AS S_Student_ID,	
			''
	 FROM [PSCERTIFICATE].T_Certificate_Query A		      
		INNER JOIN dbo.T_User_Master UM
		ON UM.I_User_ID = A.I_Student_Detail_ID
		INNER JOIN dbo.T_User_Hierarchy_Details UHD
		on UM.I_User_ID=UHD.I_User_ID
		inner join T_Center_Hierarchy_Details CHD
		on UHD.I_Hierarchy_Detail_ID=CHD.I_Hierarchy_Detail_ID
		and UHD.I_Hierarchy_Master_ID = CHD.I_Hierarchy_Master_ID
	   WHERE 		 
		  A.Dt_Crtd_On >= COALESCE(@dtFromDate, A.Dt_Crtd_On)
		  AND A.Dt_Crtd_On <= COALESCE(@dtToDate, A.Dt_Crtd_On)	
		  AND A.I_Student_Detail_ID IN (SELECT I_User_ID FROM @User )
		  and CHD.I_Center_Id in
		 (SELECT I_Center_Id from @Centre)

	UPDATE @TEMPTABLE 
	SET S_CENTER_NAME=CM.S_CENTER_NAME
	FROM @TEMPTABLE TMP
	inner join dbo.T_User_Master UM
	on tmp.i_student_detail_id=um.i_user_id
	INNER JOIN dbo.T_User_Hierarchy_Details UHD
	on UM.I_User_ID=UHD.I_User_ID
	inner join T_Center_Hierarchy_Details CHD
	on UHD.I_Hierarchy_Detail_ID=CHD.I_Hierarchy_Detail_ID
	and UHD.I_Hierarchy_Master_ID = CHD.I_Hierarchy_Master_ID
	inner join t_centre_master CM 
	on CHD.i_center_id = CM.i_centre_id
	WHERE CHD.I_Center_Id in 
	(select I_Center_Id from @Centre)
	and CHD.I_Status <> 0
	and UHD.I_Status <> 0
	and UM.I_Status <> 0
	and CM.I_Status <> 0


SELECT * FROM @TempTable ORDER BY Dt_Crtd_On DESC

END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetApproveRejectList]...';


GO
/*
-- =================================================================
-- Author:Chandan Dey
-- Modified By : 
-- Create date:06/24/2007 
-- Description:Select List Approve & Reject Request List record in T_Student_Certificate_Request table 
-- =================================================================
*/

CREATE PROCEDURE [PSCERTIFICATE].[uspGetApproveRejectList]
(
	@iCenterID		INT,
	@iCourseID		INT,
	@iTermID		INT,
	@iPSCert        INT
)
AS
BEGIN
IF (@iPSCert = 0 AND @iTermID IS NULL)
BEGIN
   SELECT 
		ISNULL(A.I_Student_Cert_Request_ID,0) AS  I_Student_Cert_Request_ID ,
		ISNULL(A.I_Student_Certificate_ID,0) AS I_Student_Certificate_ID ,
		ISNULL(A.S_Student_FName,' ') AS  S_Student_Name ,
        ISNULL(A.S_Reiss_Reason,' ') AS  S_Reiss_Reason ,
        ISNULL(A.I_Status,0) AS I_Status  ,
        ISNULL(A.S_Crtd_By,' ') AS  S_Crtd_By ,
		ISNULL(A.S_Upd_By,' ') AS  S_Upd_By ,
		ISNULL(A.Dt_Crtd_On,' ') AS Dt_Crtd_On ,
		ISNULL(A.Dt_Upd_On,' ') AS Dt_Upd_On ,
	    ISNULL(B.I_Student_Detail_ID,0) AS I_Student_Detail_ID ,
		ISNULL(C.S_First_Name,' ') AS S_First_Name ,
		ISNULL(C.S_Middle_Name,' ') AS S_Middle_Name ,
		ISNULL(C.S_Last_Name,' ') AS S_Last_Name
     FROM [PSCERTIFICATE].T_Student_Certificate_Request A,
		  [PSCERTIFICATE].T_Student_PS_Certificate B,
		  [dbo].T_Student_Detail C,
		  [dbo].T_Student_Center_Detail F
       WHERE
			A.I_Student_Certificate_ID = B.I_Student_Certificate_ID
		AND	B.I_Student_Detail_ID = C.I_Student_Detail_ID
		AND	B.I_Student_Detail_ID = F.I_Student_Detail_ID
		AND F.I_Centre_ID = COALESCE(@iCenterID, F.I_Centre_ID)
		AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)
		AND B.I_Term_ID IS NULL --= COALESCE(@iTermID, B.I_Term_ID)
		AND (A.I_Status = 5 OR A.I_Status = 6)
		AND B.B_PS_Flag = 0
END
ELSE IF (@iPSCert = 1)
BEGIN
   SELECT 
		ISNULL(A.I_Student_Cert_Request_ID,0) AS  I_Student_Cert_Request_ID ,
		ISNULL(A.I_Student_Certificate_ID,0) AS I_Student_Certificate_ID ,
		ISNULL(A.S_Student_FName,' ') AS  S_Student_Name ,
        ISNULL(A.S_Reiss_Reason,' ') AS  S_Reiss_Reason ,
        ISNULL(A.I_Status,0) AS I_Status  ,
        ISNULL(A.S_Crtd_By,' ') AS  S_Crtd_By ,
		ISNULL(A.S_Upd_By,' ') AS  S_Upd_By ,
		ISNULL(A.Dt_Crtd_On,' ') AS Dt_Crtd_On ,
		ISNULL(A.Dt_Upd_On,' ') AS Dt_Upd_On ,
	    ISNULL(B.I_Student_Detail_ID,0) AS I_Student_Detail_ID ,
		ISNULL(C.S_First_Name,' ') AS S_First_Name ,
		ISNULL(C.S_Middle_Name,' ') AS S_Middle_Name ,
		ISNULL(C.S_Last_Name,' ') AS S_Last_Name
     FROM [PSCERTIFICATE].T_Student_Certificate_Request A,
		  [PSCERTIFICATE].T_Student_PS_Certificate B,
		  [dbo].T_Student_Detail C,
		  [dbo].T_Student_Center_Detail F
       WHERE
			A.I_Student_Certificate_ID = B.I_Student_Certificate_ID
		AND	B.I_Student_Detail_ID = C.I_Student_Detail_ID
		AND	B.I_Student_Detail_ID = F.I_Student_Detail_ID
		AND F.I_Centre_ID = COALESCE(@iCenterID, F.I_Centre_ID)
		AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)
		AND B.I_Term_ID = COALESCE(@iTermID, B.I_Term_ID)
		AND (A.I_Status = 5 OR A.I_Status = 6)
		AND B.B_PS_Flag = 1
END
ELSE
BEGIN
   SELECT 
		ISNULL(A.I_Student_Cert_Request_ID,0) AS  I_Student_Cert_Request_ID ,
		ISNULL(A.I_Student_Certificate_ID,0) AS I_Student_Certificate_ID ,
		ISNULL(A.S_Student_FName,' ') AS  S_Student_Name ,
        ISNULL(A.S_Reiss_Reason,' ') AS  S_Reiss_Reason ,
        ISNULL(A.I_Status,0) AS I_Status  ,
        ISNULL(A.S_Crtd_By,' ') AS  S_Crtd_By ,
		ISNULL(A.S_Upd_By,' ') AS  S_Upd_By ,
		ISNULL(A.Dt_Crtd_On,' ') AS Dt_Crtd_On ,
		ISNULL(A.Dt_Upd_On,' ') AS Dt_Upd_On ,
	    ISNULL(B.I_Student_Detail_ID,0) AS I_Student_Detail_ID ,
		ISNULL(C.S_First_Name,' ') AS S_First_Name ,
		ISNULL(C.S_Middle_Name,' ') AS S_Middle_Name ,
		ISNULL(C.S_Last_Name,' ') AS S_Last_Name
     FROM [PSCERTIFICATE].T_Student_Certificate_Request A,
		  [PSCERTIFICATE].T_Student_PS_Certificate B,
		  [dbo].T_Student_Detail C,
		  [dbo].T_Student_Center_Detail F
       WHERE
			A.I_Student_Certificate_ID = B.I_Student_Certificate_ID
		AND	B.I_Student_Detail_ID = C.I_Student_Detail_ID
		AND	B.I_Student_Detail_ID = F.I_Student_Detail_ID
		AND F.I_Centre_ID = COALESCE(@iCenterID, F.I_Centre_ID)
		AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)
		AND B.I_Term_ID = COALESCE(@iTermID, B.I_Term_ID)
		AND (A.I_Status = 5 OR A.I_Status = 6)
		AND B.B_PS_Flag = 0
END
END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetCertificateToBePrinted]...';


GO
-- =============================================
-- Author:		NN
-- Create date: 05/06/2007
-- Description:	
-- =============================================
CREATE PROCEDURE [PSCERTIFICATE].[uspGetCertificateToBePrinted] 
	-- Add the parameters for the stored procedure here
	@iStatus int = 0, 
	@fromDate datetime = null,
	@toDate datetime = null
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT ISNULL(A.I_student_Certificate_ID,0) AS  I_student_Certificate_ID,
           ISNULL(A.I_Student_Detail_ID,0) AS I_Student_Detail_ID			,
           ISNULL(B.S_First_Name,' ') AS  S_First_Name						,
           ISNULL(B.S_Middle_Name,' ') AS S_Middle_Name						,
           ISNULL(B.S_Last_Name,' ') AS S_Last_Name
	FROM T_Student_PS_Certificate A INNER JOIN T_Student_Detail B
	ON A.I_Student_Detail_ID = B.I_Student_Detail_ID
	AND A.I_Status = @iStatus
	AND A.Dt_Certificate_Issue_Date >= COALESCE(@fromDate, A.Dt_Certificate_Issue_Date)
    AND A.Dt_Certificate_Issue_Date <= COALESCE(@toDate, A.Dt_Certificate_Issue_Date)
END
