PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetCertificateQuery]...';


GO
CREATE PROCEDURE [PSCERTIFICATE].[uspGetCertificateQuery] 
(	
	@dtFromDate DATETIME = NULL,
	@dtToDate DATETIME = NULL,
	@HierarchyDetailID INT = null,
	@BRANDID INT = null
)
AS
BEGIN

SET NOCOUNT ON

IF(@dtToDate IS NOT NULL)
	BEGIN
	SET @dtTodate = DATEADD(dd,1,@dtTodate)
	END

DECLARE @User TABLE
(
 I_User_ID INT
)

DECLARE @Centre TABLE
(
 I_Center_Id INT
)

INSERT INTO @CENTRE
SELECT I_CENTER_ID FROM DBO.FNGETCENTERIDFROMHIERARCHY(@HIERARCHYDETAILID,@BRANDID)

IF(@HierarchyDetailID IS NOT NULL)
BEGIN 
	INSERT INTO @User
	SELECT UM.I_User_ID FROM dbo.T_User_Master UM
	INNER JOIN dbo.T_User_Hierarchy_Details UHD
	on UM.I_User_ID=UHD.I_User_ID
	inner join T_Center_Hierarchy_Details CHD
	on UHD.I_Hierarchy_Detail_ID=CHD.I_Hierarchy_Detail_ID
	and UHD.I_Hierarchy_Master_ID = CHD.I_Hierarchy_Master_ID
	WHERE CHD.I_Center_Id in 
	(select I_Center_Id from @Centre)
	and CHD.I_Status <> 0
	and UHD.I_Status <> 0
	and UM.I_Status <> 0
	
END

DECLARE @TempTable TABLE
(
ID INT IDENTITY(1,1),
I_Certificate_Query_ID INT,
I_Student_Detail_ID INT,
S_Replied_By VARCHAR(100),
S_Crtd_By VARCHAR(100),
Dt_Crtd_On DATETIME,
Dt_Upd_On DATETIME,
S_Query VARCHAR(5000),
S_Reply VARCHAR(2000),
I_Status INT,
B_PS_Flag INT,
S_Title VARCHAR(250),
S_First_Name VARCHAR(100),
S_Middle_Name VARCHAR(100),
S_Last_Name VARCHAR(100),
S_Student_ID VARCHAR(100),
S_Center_Name VARCHAR(250)
)

INSERT INTO @TempTable
SELECT DISTINCT
		  ISNULL(A.I_Certificate_Query_ID, ' ') AS I_Certificate_Query_ID,
		  ISNULL(A.I_Student_Detail_ID,0) AS I_Student_Detail_ID,
          ISNULL(A.S_Replied_By,' ') AS S_Replied_By,
	      ISNULL(A.S_Crtd_By,' ') AS S_Crtd_By,
		  ISNULL(A.Dt_Crtd_On,' ') AS Dt_Crtd_On,
		  ISNULL(A.Dt_Upd_On,' ') AS Dt_Upd_On,
          ISNULL(A.S_Query, ' ') AS S_Query,
          ISNULL(A.S_Reply, ' ') AS S_Reply,
		  ISNULL(A.I_Status,0) AS I_Status,
		  ISNULL(A.B_PS_Flag, 0) AS B_PS_Flag,
		  ISNULL(UM.S_Title, ' ') AS S_Title,
		  ISNULL(UM.S_First_Name, ' ') AS S_First_Name,
	      ISNULL(UM.S_Middle_Name, ' ') AS S_Middle_Name,
		  ISNULL(UM.S_Last_Name, ' ') AS S_Last_Name,
		  ISNULL(UM.S_Login_Id, ' ') AS S_Student_ID,	
			''
		FROM [PSCERTIFICATE].T_Certificate_Query A
		INNER JOIN dbo.T_User_Master UM
		ON UM.I_User_ID = A.I_Student_Detail_ID
		INNER JOIN dbo.T_User_Hierarchy_Details UHD
		on UM.I_User_ID=UHD.I_User_ID
		inner join T_Center_Hierarchy_Details CHD
		on UHD.I_Hierarchy_Detail_ID=CHD.I_Hierarchy_Detail_ID
		and UHD.I_Hierarchy_Master_ID = CHD.I_Hierarchy_Master_ID
	   WHERE 		 
		  A.Dt_Crtd_On >= COALESCE(@dtFromDate, A.Dt_Crtd_On)
		  AND A.Dt_Crtd_On <= COALESCE(@dtToDate, A.Dt_Crtd_On)	
		  AND A.I_Student_Detail_ID IN (SELECT I_User_ID FROM @User) 
		  AND CHD.I_Center_Id in (SELECT I_Center_Id from @Centre)	
		  AND A.S_Reply IS NULL

	UPDATE @TEMPTABLE 
	SET S_CENTER_NAME=CM.S_CENTER_NAME
	FROM @TEMPTABLE TMP
	inner join dbo.T_User_Master UM
	on tmp.i_student_detail_id=um.i_user_id
	INNER JOIN dbo.T_User_Hierarchy_Details UHD
	on UM.I_User_ID=UHD.I_User_ID
	inner join T_Center_Hierarchy_Details CHD
	on UHD.I_Hierarchy_Detail_ID=CHD.I_Hierarchy_Detail_ID
	and UHD.I_Hierarchy_Master_ID = CHD.I_Hierarchy_Master_ID
	inner join t_centre_master CM 
	on CHD.i_center_id = CM.i_centre_id
	WHERE CHD.I_Center_Id in 
	(select I_Center_Id from @Centre)
	and CHD.I_Status <> 0
	and UHD.I_Status <> 0
	and UM.I_Status <> 0
	and CM.I_Status <> 0

SELECT * FROM @TempTable ORDER BY Dt_Crtd_On DESC

END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetCertificateDetails]...';


GO
CREATE PROCEDURE [PSCERTIFICATE].[uspGetCertificateDetails]
(
	@sCertIDs VARCHAR(8000)
)
AS
BEGIN
	SELECT	[TSD].[S_Title], [TSD].[S_First_Name], [TSD].[S_Middle_Name], [TSD].[S_Last_Name],
			[TSD].[S_Student_ID], [TCM].[S_Course_Name], 
			ISNULL([TCBD].[Dt_Upd_On],ISNULL([TSBM].[Dt_Course_Actual_End_Date],[TSBM].[Dt_Course_Expected_End_Date])) AS BatchEndDate,
			[TCM2].[S_Center_Name], [PSCERTIFICATE].fnGetTotalCourseDuration(TSPC.[I_Course_ID]) AS Duration,
			[PSCERTIFICATE].uspGetPerformanceRating(TSPC.[I_Student_Detail_ID], TSPC.[I_Course_ID]) AS Rating
	FROM [PSCERTIFICATE].[T_Student_PS_Certificate] AS TSPC
	INNER JOIN [dbo].[T_Student_Detail] AS TSD
	ON [TSPC].[I_Student_Detail_ID] = [TSD].[I_Student_Detail_ID]
	INNER JOIN [dbo].[T_Student_Course_Detail] AS TSCD
	ON [TSD].[I_Student_Detail_ID] = [TSCD].[I_Student_Detail_ID]
	AND [TSCD].[I_Course_ID] = [TSPC].[I_Course_ID]
	INNER JOIN [dbo].[T_Course_Master] AS TCM
	ON [TSPC].[I_Course_ID] = [TCM].[I_Course_ID]
	INNER JOIN [dbo].[T_Centre_Master] AS TCM2
	ON [TCM2].[I_Centre_Id] = [TSCD].[I_Centre_Id]
	INNER JOIN [dbo].[T_Student_Batch_Master] AS TSBM
	ON [TSBM].[I_Batch_ID] = [TSCD].[I_Batch_ID]
	INNER JOIN [dbo].[T_Center_Batch_Details] AS TCBD
	ON [TSCD].[I_Centre_Id] = [TCBD].[I_Centre_Id]
	AND [TCBD].[I_Batch_ID] = [TSBM].[I_Batch_ID]
	WHERE [TSPC].[I_Student_Certificate_ID] IN
	(SELECT [FSR].[Val] FROM [dbo].[fnString2Rows](@sCertIDs,',') AS FSR)
END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetConfirmAuthenticity]...';


GO
/*
-- =================================================================
-- Author:Chandan Dey
-- Modified By : 
-- Create date:12/07/2007 
-- Description:Select List Student Certificate in T_Student_PS_Certificate table 
-- =================================================================
*/

CREATE PROCEDURE [PSCERTIFICATE].[uspGetConfirmAuthenticity]
(
	@sCertSrlNo	VARCHAR(20),
	@sFirstName			VARCHAR(50),
	@sMiddleName		VARCHAR(50) = NULL,
	@sLastName			VARCHAR(50) = NULL,
	@iPSCert		INT = NULL
)
AS
BEGIN
 SELECT DISTINCT
	ISNULL(TCM.S_Certificate_Name,' ') AS S_Certificate_Name,
	ISNULL(SPC.Dt_Crtd_On,' ') AS Dt_Crtd_On,
	ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,
	ISNULL(SD.S_First_Name,' ') AS S_First_Name,
	ISNULL(SD.S_Middle_Name,' ') AS S_Middle_Name,
	ISNULL(SD.S_Last_Name,' ') AS S_Last_Name,
	ISNULL(CM.S_Course_Name,' ') AS S_Course_Name,
	ISNULL(TM.S_Term_Name,' ') AS S_Term_Name,
	B_PS_Flag AS B_PS_Flag ,
	ISNULL(TCMT.S_Certificate_Name,' ') AS T_Certificate_Name ,
	SCOD.I_Batch_ID  
	   FROM 
			[PSCERTIFICATE].T_Student_PS_Certificate SPC 
			INNER JOIN [PSCERTIFICATE].T_Certificate_Logistic CL
			ON CL.I_Student_Certificate_ID = SPC.I_Student_Certificate_ID
	        INNER JOIN [dbo].T_Student_Detail SD
			ON SPC.I_Student_Detail_ID = SD.I_Student_Detail_ID  -- 3102 = 3102
			INNER JOIN [dbo].T_Student_Center_Detail SCD
			ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID  -- 3102 = 3102
			INNER JOIN dbo.T_Student_Course_Detail SCOD
			ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID
			AND SPC.I_Course_ID = SCOD.I_Course_ID
			AND SCOD.I_Status = 1
			INNER JOIN [dbo].T_Course_Master CM
            ON CM.I_Course_ID = SPC.I_Course_ID   -- 308 = 308
			INNER JOIN [dbo].T_Certificate_Master TCM
			ON TCM.I_Certificate_ID = CM.I_Certificate_ID  -- 28 = 28
			LEFT OUTER JOIN [dbo].T_Term_Master TM
			ON TM.I_Term_ID = SPC.I_Term_ID  -- 186 = 186
			LEFT OUTER JOIN [dbo].T_Certificate_Master TCMT
			ON TCM.I_Certificate_ID = TCMT.I_Certificate_ID  -- 28 = 28
	   WHERE 
			CL.S_Logistic_Serial_No LIKE '%-'+@sCertSrlNo
			AND CL.I_Status =1
			AND SD.S_First_Name = @sFirstName
			AND SD.S_Middle_Name = COALESCE(@sMiddleName, SD.S_Middle_Name)
			AND SD.S_Last_Name = @sLastName
			AND B_PS_Flag = COALESCE(@iPSCert,B_PS_Flag)
END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetDespatchInfoList]...';


GO
/*    
-- =================================================================    
-- Author:Ujjwal Sinha    
-- Modified By :    
-- Create date:12/06/2007    
-- Description:Select List Despatch Information List in T_Certificate_Despatch_Info table    
-- =================================================================    
*/    
CREATE PROCEDURE [PSCERTIFICATE].[uspGetDespatchInfoList]  
(     
 @iCenterID INT,    
 @iCourseID INT = NULL,    
 @iTermID INT = NULL,    
 @sCertSrlNo VARCHAR(100)= NULL,    
 @sRegistrationNo VARCHAR(20) = NULL,    
 @iStudentDetailID INT = NULL,    
 @dtFromDate DATETIME = NULL,    
 @dtToDate DATETIME = NULL,    
 @iflag INT = NULL    
)    
AS    
BEGIN    
    IF @iflag IS NULL    
		BEGIN    
 IF(@iCourseID IS NOT NULL AND @iTermID IS NOT NULL)    
BEGIN    
  SELECT     
  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
  ISNULL(SD.S_Title,'') AS S_Title,    
  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
  SPSC.I_Status AS I_Status,    
  SCOD.I_Batch_ID    
  FROM     
  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
  INNER JOIN dbo.T_Courier_Master TCM    
  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
  INNER JOIN dbo.T_Student_Detail SD    
  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  INNER JOIN dbo.T_Student_Center_Detail SCD    
  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
  INNER JOIN dbo.T_Course_Master CM    
  ON CM.I_Course_ID = SPSC.I_Course_ID    
  INNER JOIN dbo.T_Student_Course_Detail SCOD    
  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
  AND SCOD.I_Status = 1    
  LEFT OUTER JOIN dbo.T_Term_Master TM    
  ON TM.I_Term_ID = SPSC.I_Term_ID    
  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
  ON ED.I_Exam_ID = EL.I_Exam_ID    
  WHERE    
   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
  AND CL.I_Status = 1    
  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
  AND SPSC.I_Term_ID = COALESCE(@iTermID, SPSC.I_Term_ID)      
  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)    
  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
END    
ELSE IF(@iCourseID IS NOT NULL AND @iTermID IS NULL)    
 BEGIN    
 SELECT     
  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
  ISNULL(SD.S_Title,'') AS S_Title,    
  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
  SPSC.I_Status AS I_Status,    
  SCOD.I_Batch_ID    
  FROM     
  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
  INNER JOIN dbo.T_Courier_Master TCM    
  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
  INNER JOIN dbo.T_Student_Detail SD    
  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  INNER JOIN dbo.T_Student_Center_Detail SCD    
  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
  INNER JOIN dbo.T_Course_Master CM    
  ON CM.I_Course_ID = SPSC.I_Course_ID    
  INNER JOIN dbo.T_Student_Course_Detail SCOD    
  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
  AND SCOD.I_Status = 1    
  LEFT OUTER JOIN dbo.T_Term_Master TM    
  ON TM.I_Term_ID = SPSC.I_Term_ID    
  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
  ON ED.I_Exam_ID = EL.I_Exam_ID    
  WHERE    
   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
  AND CL.I_Status = 1    
  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
  AND SPSC.I_Term_ID IS NULL --= COALESCE(@iTermID, SPSC.I_Term_ID)    
  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)      
  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
END    
ELSE --IF(@iCourseID IS NOT NULL AND @iTermID IS NULL)    
 BEGIN    
 SELECT     
  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
  ISNULL(SD.S_Title,'') AS S_Title,    
  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
  SPSC.I_Status AS I_Status,    
  SCOD.I_Batch_ID    
  FROM     
  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
  INNER JOIN dbo.T_Courier_Master TCM    
  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
  INNER JOIN dbo.T_Student_Detail SD    
  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  INNER JOIN dbo.T_Student_Center_Detail SCD    
  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
  INNER JOIN dbo.T_Course_Master CM    
  ON CM.I_Course_ID = SPSC.I_Course_ID    
  INNER JOIN dbo.T_Student_Course_Detail SCOD    
  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
  AND SCOD.I_Status = 1    
  LEFT OUTER JOIN dbo.T_Term_Master TM    
  ON TM.I_Term_ID = SPSC.I_Term_ID    
  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
  ON ED.I_Exam_ID = EL.I_Exam_ID    
  WHERE    
   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
  AND CL.I_Status = 1    
  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)      
  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
END    
END    
	ELSE IF @iflag = 1    
		BEGIN    
			IF(@iCourseID IS NOT NULL AND @iTermID IS NOT NULL)    
				BEGIN    
  SELECT     
  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
  ISNULL(SD.S_Title,'') AS S_Title,    
  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
  SPSC.I_Status AS I_Status,    
  SCOD.I_Batch_ID    
  FROM     
  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
  INNER JOIN dbo.T_Courier_Master TCM    
  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
  INNER JOIN dbo.T_Student_Detail SD    
  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  INNER JOIN dbo.T_Student_Center_Detail SCD    
  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
  INNER JOIN dbo.T_Course_Master CM    
  ON CM.I_Course_ID = SPSC.I_Course_ID    
  INNER JOIN dbo.T_Student_Course_Detail SCOD    
  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
  AND SCOD.I_Status = 1    
  LEFT OUTER JOIN dbo.T_Term_Master TM    
  ON TM.I_Term_ID = SPSC.I_Term_ID    
  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
  ON ED.I_Exam_ID = EL.I_Exam_ID    
  WHERE    
   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
  --AND CL.I_Status = 1    
  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
  AND SPSC.I_Term_ID = COALESCE(@iTermID, SPSC.I_Term_ID)      
  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)    
  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
END    
			ELSE IF(@iCourseID IS NOT NULL AND @iTermID IS NULL)    
				BEGIN    
 SELECT     
  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
  ISNULL(SD.S_Title,'') AS S_Title,    
  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
  SPSC.I_Status AS I_Status,    
  SCOD.I_Batch_ID    
  FROM     
  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
  INNER JOIN dbo.T_Courier_Master TCM    
  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
  INNER JOIN dbo.T_Student_Detail SD    
  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  INNER JOIN dbo.T_Student_Center_Detail SCD    
  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
  INNER JOIN dbo.T_Course_Master CM    
  ON CM.I_Course_ID = SPSC.I_Course_ID    
  INNER JOIN dbo.T_Student_Course_Detail SCOD    
  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
  AND SCOD.I_Status = 1    
  LEFT OUTER JOIN dbo.T_Term_Master TM    
  ON TM.I_Term_ID = SPSC.I_Term_ID    
  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
  ON ED.I_Exam_ID = EL.I_Exam_ID    
  WHERE    
   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
  --AND CL.I_Status = 1    
  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
  AND SPSC.I_Term_ID IS NULL --= COALESCE(@iTermID, SPSC.I_Term_ID)    
  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)      
  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
END    
			ELSE 
				BEGIN    
					SELECT     
  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
  ISNULL(SD.S_Title,'') AS S_Title,    
  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
  SPSC.I_Status AS I_Status,    
  SCOD.I_Batch_ID    
  FROM     
  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
  INNER JOIN dbo.T_Courier_Master TCM    
  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
  INNER JOIN dbo.T_Student_Detail SD    
  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  INNER JOIN dbo.T_Student_Center_Detail SCD    
  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
  INNER JOIN dbo.T_Course_Master CM    
  ON CM.I_Course_ID = SPSC.I_Course_ID    
  INNER JOIN dbo.T_Student_Course_Detail SCOD    
  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
  AND SCOD.I_Status = 1    
  LEFT OUTER JOIN dbo.T_Term_Master TM    
  ON TM.I_Term_ID = SPSC.I_Term_ID    
  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
  ON ED.I_Exam_ID = EL.I_Exam_ID    
  WHERE    
   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
  --AND CL.I_Status = 1    
  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)      
  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
				END    
		END    
    ELSE IF @iflag = 0
		BEGIN
			SELECT     
		  DISTINCT(CDI.I_Despatch_ID) AS I_Despatch_ID ,    
		  CDI.Dt_Dispatch_Date AS Dt_Dispatch_Date,    
		  ISNULL(CDI.S_Docket_No,'') AS S_Docket_No,    
		  ISNULL(CL.S_Logistic_Serial_No,'') AS S_Certificate_Serial_No,    
		  ISNULL(SD.S_First_Name,'') AS S_First_Name,    
		  ISNULL(SD.S_Middle_Name,'') AS S_Middle_Name,    
		  ISNULL(SD.S_Last_Name,'') AS S_Last_Name,    
		  ISNULL(SD.S_Title,'') AS S_Title,    
		  ISNULL(CM.S_Course_Name,'') AS S_Course_Name,    
		  ISNULL(CM.S_Course_Code,'') AS S_Course_Code,    
		  ISNULL(TM.S_Term_Name,'') AS S_Term_Name,    
		  ISNULL(TCM.S_Courier_Name,' ') AS S_Courier_Name,    
		  ISNULL(SD.S_Student_ID,' ') AS S_Student_ID,    
		  SPSC.I_Status AS I_Status,    
		  SCOD.I_Batch_ID    
		  FROM     
		  PSCERTIFICATE.T_Certificate_Despatch_Info CDI    
		  INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL    
		  ON CDI.I_Logistic_ID = CL.I_Logistic_ID    
		  INNER JOIN dbo.T_Courier_Master TCM    
		  ON TCM.I_Courier_ID = CDI.I_Courier_ID    
		  INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPSC    
		  ON CL.I_Student_Certificate_ID = SPSC.I_Student_Certificate_ID    
		  INNER JOIN dbo.T_Student_Detail SD    
		  ON SD.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
		  INNER JOIN dbo.T_Student_Center_Detail SCD    
		  ON SD.I_Student_Detail_ID = SCD.I_Student_Detail_ID    
		  INNER JOIN dbo.T_Course_Master CM    
		  ON CM.I_Course_ID = SPSC.I_Course_ID    
		  INNER JOIN dbo.T_Student_Course_Detail SCOD    
		  ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID    
		  AND SPSC.I_Course_ID = SCOD.I_Course_ID    
		  AND SCOD.I_Status = 1    
		  LEFT OUTER JOIN dbo.T_Term_Master TM    
		  ON TM.I_Term_ID = SPSC.I_Term_ID    
		  LEFT OUTER JOIN EXAMINATION.T_Eligibility_List EL    
		  ON EL.I_Student_Detail_ID = SPSC.I_Student_Detail_ID     
		  LEFT OUTER JOIN EXAMINATION.T_Examination_Detail ED    
		  ON ED.I_Exam_ID = EL.I_Exam_ID    
		  WHERE    
		   SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)    
		  --AND CL.I_Status = 1    
		  AND SPSC.I_Course_ID = COALESCE(@iCourseID, SPSC.I_Course_ID)    
		  AND SPSC.I_Student_Detail_ID = COALESCE(@iStudentDetailID, SPSC.I_Student_Detail_ID)    
		  AND CDI.Dt_Dispatch_Date >= COALESCE(@dtFromDate, CDI.Dt_Dispatch_Date)    
		  AND CDI.Dt_Dispatch_Date <= COALESCE(@dtToDate, CDI.Dt_Dispatch_Date)      
		  AND [CL].[S_Logistic_Serial_No] = COALESCE(@sCertSrlNo, [CL].[S_Logistic_Serial_No])    
		END
