GO
/*
-- =================================================================
-- Author:Chandan Dey
-- Modified By :
-- Create date:13/09/2007
-- Description: Select List Approve/Reject/Pending Status from Re-Issue Request List record in T_Student_Certificate_Request table
-- =================================================================
*/
CREATE PROCEDURE [PSCERTIFICATE].[uspGetReIssueStatusList]
(
	@iCenterID		INT = NULL,
	@iCourseID		INT = NULL,
	@iTermID		INT = NULL,
	@dtFromDate		DATETIME,
	@dtToDate		DATETIME,
	@HierarchyDetailID INT =NULL,
	@iBrandID		INT,
	@CourseFamilyIDList INT = NULL
 
)
AS
BEGIN

IF(@dtTodate IS NOT NULL)
BEGIN
	SET @dtTodate = DATEADD(dd,1,@dtTodate)
END 

--Get course list from course family
DECLARE @TempCourse TABLE
(
 I_Course_ID INT
)

IF( @CourseFamilyIDList IS NOT NULL)
 BEGIN
	INSERT INTO @TempCourse
	SELECT I_Course_ID FROM dbo.T_Course_Master 
	WHERE I_CourseFamily_ID = @CourseFamilyIDList
	AND I_Course_ID= COALESCE(@iCourseID, I_Course_ID)
 END
ELSE
	BEGIN
		INSERT INTO @TempCourse
		SELECT I_Course_ID FROM dbo.T_Course_Master 
		--WHERE I_Course_IDI_CourseFamily_ID = @CourseFamilyIDList
	END



IF(@iTermID IS NOT NULL)
	BEGIN
	   SELECT 
			DISTINCT(SD.I_Student_Detail_ID) AS  I_Student_Detail_ID
			,ISNULL(SD.S_First_Name,'') AS  S_First_Name
			,ISNULL(SD.S_Middle_Name,'') AS  S_Middle_Name
			,ISNULL(SD.S_Last_Name,'') AS  S_Last_Name
			,ISNULL(CM.S_Center_Name,'') AS  S_Center_Name
			,ISNULL(COM.S_Course_Name,'') AS S_Course_Name
			,ISNULL(TM.S_Term_Name,'') AS  S_Term_Name
			,ISNULL(SCR.Dt_Crtd_On,'') AS  Dt_Crtd_On
			,ISNULL(SPC.B_PS_Flag,0) AS B_PS_Flag
			,ISNULL(SCR.I_Status,0) AS I_Status
			,SCOD.I_Batch_ID
		 FROM [PSCERTIFICATE].T_Student_Certificate_Request SCR
			  INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate SPC
			  ON SPC.I_Student_Certificate_ID = SCR.I_Student_Certificate_ID
			  INNER JOIN dbo.T_Student_Detail SD
			  ON SD.I_Student_Detail_ID = SPC.I_Student_Detail_ID
			  INNER JOIN dbo.T_Student_Center_Detail SCD
			  ON SCD.I_Student_Detail_ID = SPC.I_Student_Detail_ID
			  INNER JOIN dbo.T_Centre_Master CM
			  ON CM.I_Centre_Id = SCD.I_Centre_Id
			  INNER JOIN dbo.T_Student_Course_Detail SCOD
				ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID
				AND SPC.I_Course_ID = SCOD.I_Course_ID
				AND SCOD.I_Status = 1
			  INNER JOIN dbo.T_Course_Master COM
			  ON COM.I_Course_ID = SPC.I_Course_ID
			  LEFT OUTER JOIN dbo.T_Term_Master TM
			  ON TM.I_Term_ID = SPC.I_Term_ID
	     
		 WHERE
			  SCR.I_Status IN(4,5,6)
			  --AND SCD.I_Centre_ID = COALESCE(@iCenterID, SCD.I_Centre_ID)
			  AND SCD.I_Centre_ID IN ( SELECT FN1.I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@HierarchyDetailID,@iBrandID) FN1)
			  AND SPC.I_Course_ID = COALESCE(@iCourseID, SPC.I_Course_ID)
			  --AND SPC.I_Course_ID IN (SELECT I_Course_ID FROM @TempCourse)
			  AND SPC.I_Term_ID = COALESCE(@iTermID, SPC.I_Term_ID)
			  AND SCR.Dt_Crtd_On BETWEEN @dtFromDate AND @dtToDate  -->= COALESCE(@fromDate, SCR.Dt_Crtd_On)
			  --AND SCR.Dt_Crtd_On <= COALESCE(@toDate, SCR.Dt_Crtd_On)
	END
ELSE IF(@iCourseID IS NULL AND @iTermID IS NULL)
	BEGIN
	   SELECT 
			DISTINCT(SD.I_Student_Detail_ID) AS  I_Student_Detail_ID
			,ISNULL(SD.S_First_Name,'') AS  S_First_Name
			,ISNULL(SD.S_Middle_Name,'') AS  S_Middle_Name
			,ISNULL(SD.S_Last_Name,'') AS  S_Last_Name
			,ISNULL(CM.S_Center_Name,'') AS  S_Center_Name
			,ISNULL(COM.S_Course_Name,'') AS S_Course_Name
			,ISNULL(TM.S_Term_Name,'') AS  S_Term_Name
			,ISNULL(SCR.Dt_Crtd_On,'') AS  Dt_Crtd_On
			,ISNULL(SPC.B_PS_Flag,0) AS B_PS_Flag
			,ISNULL(SCR.I_Status,0) AS I_Status
			,SCOD.I_Batch_ID
		 FROM [PSCERTIFICATE].T_Student_Certificate_Request SCR
			  INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate SPC
			  ON SPC.I_Student_Certificate_ID = SCR.I_Student_Certificate_ID
			  INNER JOIN dbo.T_Student_Detail SD
			  ON SD.I_Student_Detail_ID = SPC.I_Student_Detail_ID
			  INNER JOIN dbo.T_Student_Center_Detail SCD
			  ON SCD.I_Student_Detail_ID = SPC.I_Student_Detail_ID
			  INNER JOIN dbo.T_Centre_Master CM
			  ON CM.I_Centre_Id = SCD.I_Centre_Id
			  INNER JOIN dbo.T_Student_Course_Detail SCOD
				ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID
				AND SPC.I_Course_ID = SCOD.I_Course_ID
				AND SCOD.I_Status = 1
			  INNER JOIN dbo.T_Course_Master COM
			  ON COM.I_Course_ID = SPC.I_Course_ID
			  LEFT OUTER JOIN dbo.T_Term_Master TM
			  ON TM.I_Term_ID = SPC.I_Term_ID
	     
		 WHERE
			  SCR.I_Status IN(4,5,6)
			  AND SCD.I_Centre_ID IN ( SELECT FN1.I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@HierarchyDetailID,@iBrandID) FN1)
			  AND SCR.Dt_Crtd_On BETWEEN @dtFromDate AND @dtToDate  -->= COALESCE(@fromDate, SCR.Dt_Crtd_On)
			  AND SPC.I_Course_ID IN (SELECT I_Course_ID FROM @TempCourse)	
	END
ELSE IF(@iTermID IS NULL)
	BEGIN
	   SELECT 
			DISTINCT(SD.I_Student_Detail_ID) AS  I_Student_Detail_ID
			,ISNULL(SD.S_First_Name,'') AS  S_First_Name
			,ISNULL(SD.S_Middle_Name,'') AS  S_Middle_Name
			,ISNULL(SD.S_Last_Name,'') AS  S_Last_Name
			,ISNULL(CM.S_Center_Name,'') AS  S_Center_Name
			,ISNULL(COM.S_Course_Name,'') AS S_Course_Name
			,ISNULL(TM.S_Term_Name,'') AS  S_Term_Name
			,ISNULL(SCR.Dt_Crtd_On,'') AS  Dt_Crtd_On
			,ISNULL(SPC.B_PS_Flag,0) AS B_PS_Flag
			,ISNULL(SCR.I_Status,0) AS I_Status
			,SCOD.I_Batch_ID
		 FROM [PSCERTIFICATE].T_Student_Certificate_Request SCR
			  INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate SPC
			  ON SPC.I_Student_Certificate_ID = SCR.I_Student_Certificate_ID
			  INNER JOIN dbo.T_Student_Detail SD
			  ON SD.I_Student_Detail_ID = SPC.I_Student_Detail_ID
			  INNER JOIN dbo.T_Student_Center_Detail SCD
			  ON SCD.I_Student_Detail_ID = SPC.I_Student_Detail_ID
			  INNER JOIN dbo.T_Centre_Master CM
			  ON CM.I_Centre_Id = SCD.I_Centre_Id
			  INNER JOIN dbo.T_Student_Course_Detail SCOD
				ON SD.I_Student_Detail_ID = SCOD.I_Student_Detail_ID
				AND SPC.I_Course_ID = SCOD.I_Course_ID
				AND SCOD.I_Status = 1
			  INNER JOIN dbo.T_Course_Master COM
			  ON COM.I_Course_ID = SPC.I_Course_ID
			  LEFT OUTER JOIN dbo.T_Term_Master TM
			  ON TM.I_Term_ID = SPC.I_Term_ID
	     
		 WHERE
			  SCR.I_Status IN(4,5,6)
			  AND SCD.I_Centre_ID IN ( SELECT FN1.I_Center_ID FROM [dbo].[fnGetCenterIDFromHierarchy](@HierarchyDetailID,@iBrandID) FN1)
			  AND SPC.I_Course_ID = COALESCE(@iCourseID, SPC.I_Course_ID)
			  AND SPC.I_Term_ID IS NULL
			  AND SCR.Dt_Crtd_On BETWEEN @dtFromDate AND @dtToDate  -->= COALESCE(@fromDate, SCR.Dt_Crtd_On)
			 
	END
END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetStudentCertificateRequestList]...';


GO
/*
-- =================================================================
-- Author:Chandan Dey
-- Modified By : 
-- Create date:06/18/2007 
-- Description:Select List StudentCertificateRequestList record in T_Student_Certificate_Request table 
-- =================================================================
*/

CREATE PROCEDURE [PSCERTIFICATE].[uspGetStudentCertificateRequestList]
(
    
	@iCenterID		INT = null,
	@iHierarchyDetailID INT = null,
	@iCourseID		INT = null,
	@iTermID		INT = null,
	@iPSCert		INT = null,
	@iStatusID		INT,
	@iBrandID INT = null,
	@iFlag INT = NULL
)
AS 
    BEGIN

-- For Get the center using hierarchy id 

        DECLARE @sSearchCriteria varchar(20)
        CREATE TABLE #TempCenter ( I_Center_ID int )

        IF @iHierarchyDetailID IS NOT NULL 
            BEGIN

                SELECT  @sSearchCriteria = S_Hierarchy_Chain
                from    T_Hierarchy_Mapping_Details
                where   I_Hierarchy_detail_id = @iHierarchyDetailID  
		
                IF @iBrandId = 0 
                    BEGIN
                        INSERT  INTO #TempCenter
                                SELECT  TCHD.I_Center_Id
                                FROM    T_CENTER_HIERARCHY_DETAILS TCHD
                                WHERE   TCHD.I_Hierarchy_Detail_ID IN (
                                        SELECT  I_HIERARCHY_DETAIL_ID
                                        FROM    T_Hierarchy_Mapping_Details
                                        WHERE   I_Status = 1
                                                AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())
                                                AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())
                                                AND S_Hierarchy_Chain LIKE @sSearchCriteria
                                                + '%' ) 
                    END
                ELSE 
                    BEGIN
                        INSERT  INTO #TempCenter
                                SELECT  TCHD.I_Center_Id
                                FROM    T_CENTER_HIERARCHY_DETAILS TCHD,
                                        T_BRAND_CENTER_DETAILS TBCD
                                WHERE   TCHD.I_Hierarchy_Detail_ID IN (
                                        SELECT  I_HIERARCHY_DETAIL_ID
                                        FROM    T_Hierarchy_Mapping_Details
                                        WHERE   I_Status = 1
                                                AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())
                                                AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())
                                                AND S_Hierarchy_Chain LIKE @sSearchCriteria
                                                + '%' )
                                        AND TBCD.I_Brand_ID = @iBrandId
                                        AND TBCD.I_Centre_Id = TCHD.I_Center_Id 			 
                    END
            END
        ELSE 
            BEGIN
                INSERT  INTO #TempCenter
                        SELECT  I_Centre_ID
                        FROM    T_Centre_Master
                        WHERE   I_Status = 1
                                AND I_Centre_ID = @iCenterID  
            END


        IF ( @iPSCert = 0
             AND @iTermID IS NULL
             AND @iFlag IS NULL
           ) 
            BEGIN
                SELECT DISTINCT ISNULL(A.I_Student_Cert_Request_ID, 0) AS I_Student_Cert_Request_ID,
                        ISNULL(A.I_Student_Certificate_ID, 0) AS I_Student_Certificate_ID,
                        ( ISNULL(A.S_Student_FName, ' ')
                          + ISNULL(A.S_Student_MName, ' ')
                          + ISNULL(A.S_Student_LName, ' ') ) AS S_Student_Name,
                        ISNULL(A.S_Reiss_Reason, ' ') AS S_Reiss_Reason,
                        ISNULL(A.I_Status, 0) AS I_Status,
                        ISNULL(A.S_Crtd_By, ' ') AS S_Crtd_By,
                        ISNULL(A.S_Upd_By, ' ') AS S_Upd_By,
                        ISNULL(A.Dt_Crtd_On, ' ') AS Dt_Crtd_On,
                        ISNULL(A.Dt_Upd_On, ' ') AS Dt_Upd_On,
                        ISNULL(B.I_Student_Detail_ID, 0) AS I_Student_Detail_ID,
                        ISNULL(C.S_First_Name, '') AS S_First_Name,
                        ISNULL(C.S_Middle_Name, '') AS S_Middle_Name,
                        ISNULL(C.S_Last_Name, '') AS S_Last_Name,
                        ISNULL(B.S_Certificate_Serial_No, '') AS S_Certificate_Serial_No,
                        ISNULL(CM.S_Center_Name, '') AS S_Center_Name,
                        CM.I_Centre_ID AS I_Center_ID,
                        ISNULL(COM.S_Course_Name, '') AS S_Course_Name,
                        ISNULL(TM.S_Term_Name, '') AS S_Term_Name,
                        SCD.I_Batch_ID
                FROM    [PSCERTIFICATE].T_Student_Certificate_Request A
                        INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate B ON A.I_Student_Certificate_ID = B.I_Student_Certificate_ID
                        INNER JOIN [dbo].T_Student_Detail C ON B.I_Student_Detail_ID = C.I_Student_Detail_ID
                        INNER JOIN [dbo].T_Student_Center_Detail F ON C.I_Student_Detail_ID = F.I_Student_Detail_ID
                        INNER JOIN dbo.T_Centre_Master CM ON CM.I_Centre_Id = F.I_Centre_Id
                        INNER JOIN dbo.T_Student_Course_Detail SCD ON SCD.I_Student_Detail_ID = B.I_Student_Detail_ID
                        AND [SCD].[I_Course_ID] = [B].[I_Course_ID]
                        INNER JOIN dbo.T_Course_Master COM ON COM.I_Course_ID = SCD.I_Course_ID
                        LEFT OUTER JOIN [dbo].T_Term_Master TM ON TM.I_Term_ID = B.I_Term_ID
                WHERE   
                        F.I_Centre_ID IN ( SELECT   I_Center_ID
                                           FROM     #TempCenter )
                        AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)
                        AND B.I_Term_ID IS NULL 
                        AND A.I_Status = COALESCE(@iStatusID, A.I_Status)
                        AND B.B_PS_Flag = 0
		
            END
        ELSE 
            IF ( @iPSCert = 1 ) 
                BEGIN
                    SELECT DISTINCT ISNULL(A.I_Student_Cert_Request_ID, 0) AS I_Student_Cert_Request_ID,
                            ISNULL(A.I_Student_Certificate_ID, 0) AS I_Student_Certificate_ID,
                            ( ISNULL(A.S_Student_FName, ' ')
                              + ISNULL(A.S_Student_MName, ' ')
                              + ISNULL(A.S_Student_LName, ' ') ) AS S_Student_Name,
                            ISNULL(A.S_Reiss_Reason, ' ') AS S_Reiss_Reason,
                            ISNULL(A.I_Status, 0) AS I_Status,
                            ISNULL(A.S_Crtd_By, ' ') AS S_Crtd_By,
                            ISNULL(A.S_Upd_By, ' ') AS S_Upd_By,
                            ISNULL(A.Dt_Crtd_On, ' ') AS Dt_Crtd_On,
                            ISNULL(A.Dt_Upd_On, ' ') AS Dt_Upd_On,
                            ISNULL(B.I_Student_Detail_ID, 0) AS I_Student_Detail_ID,
                            ISNULL(C.S_First_Name, '') AS S_First_Name,
                            ISNULL(C.S_Middle_Name, '') AS S_Middle_Name,
                            ISNULL(C.S_Last_Name, '') AS S_Last_Name,
                            ISNULL(B.S_Certificate_Serial_No, '') AS S_Certificate_Serial_No,
                            ISNULL(CM.S_Center_Name, '') AS S_Center_Name,
                            CM.I_Centre_ID AS I_Center_ID,
                            ISNULL(COM.S_Course_Name, '') AS S_Course_Name,
                            ISNULL(TM.S_Term_Name, '') AS S_Term_Name,
                            SCD.I_Batch_ID
                    FROM    [PSCERTIFICATE].T_Student_Certificate_Request A
                            INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate B ON A.I_Student_Certificate_ID = B.I_Student_Certificate_ID
                            INNER JOIN [dbo].T_Student_Detail C ON B.I_Student_Detail_ID = C.I_Student_Detail_ID
                            INNER JOIN [dbo].T_Student_Center_Detail F ON C.I_Student_Detail_ID = F.I_Student_Detail_ID
                            INNER JOIN dbo.T_Centre_Master CM ON CM.I_Centre_Id = F.I_Centre_Id
                            INNER JOIN dbo.T_Student_Course_Detail SCD ON SCD.I_Student_Detail_ID = B.I_Student_Detail_ID
                            AND [SCD].[I_Course_ID] = [B].[I_Course_ID]
                            INNER JOIN dbo.T_Course_Master COM ON COM.I_Course_ID = SCD.I_Course_ID
                            LEFT OUTER JOIN [dbo].T_Term_Master TM ON TM.I_Term_ID = B.I_Term_ID
                    WHERE  
                            F.I_Centre_ID IN ( SELECT   I_Center_ID
                                               FROM     #TempCenter )
                            AND B.I_Course_ID = COALESCE(@iCourseID,
                                                         B.I_Course_ID)
                            AND B.I_Term_ID = COALESCE(@iTermID, B.I_Term_ID)
                            AND A.I_Status = COALESCE(@iStatusID, A.I_Status)
                            AND B.B_PS_Flag = 1
		
                END
            ELSE 
                BEGIN
                    SELECT DISTINCT ISNULL(A.I_Student_Cert_Request_ID, 0) AS I_Student_Cert_Request_ID,
                            ISNULL(A.I_Student_Certificate_ID, 0) AS I_Student_Certificate_ID,
                            ( ISNULL(A.S_Student_FName, ' ')
                              + ISNULL(A.S_Student_MName, ' ')
                              + ISNULL(A.S_Student_LName, ' ') ) AS S_Student_Name,
                            ISNULL(A.S_Reiss_Reason, ' ') AS S_Reiss_Reason,
                            ISNULL(A.I_Status, 0) AS I_Status,
                            ISNULL(A.S_Crtd_By, ' ') AS S_Crtd_By,
                            ISNULL(A.S_Upd_By, ' ') AS S_Upd_By,
                            ISNULL(A.Dt_Crtd_On, ' ') AS Dt_Crtd_On,
                            ISNULL(A.Dt_Upd_On, ' ') AS Dt_Upd_On,
                            ISNULL(B.I_Student_Detail_ID, 0) AS I_Student_Detail_ID,
                            ISNULL(C.S_First_Name, '') AS S_First_Name,
                            ISNULL(C.S_Middle_Name, '') AS S_Middle_Name,
                            ISNULL(C.S_Last_Name, '') AS S_Last_Name,
                            ISNULL(B.S_Certificate_Serial_No, '') AS S_Certificate_Serial_No,
                            ISNULL(CM.S_Center_Name, '') AS S_Center_Name,
                            CM.I_Centre_ID AS I_Center_ID,
                            ISNULL(COM.S_Course_Name, '') AS S_Course_Name,
                            ISNULL(TM.S_Term_Name, '') AS S_Term_Name,
                            SCD.I_Batch_ID
                    FROM    [PSCERTIFICATE].T_Student_Certificate_Request A
                            INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate B ON A.I_Student_Certificate_ID = B.I_Student_Certificate_ID
                            INNER JOIN [dbo].T_Student_Detail C ON B.I_Student_Detail_ID = C.I_Student_Detail_ID
                            INNER JOIN [dbo].T_Student_Center_Detail F ON C.I_Student_Detail_ID = F.I_Student_Detail_ID
                            INNER JOIN dbo.T_Centre_Master CM ON CM.I_Centre_Id = F.I_Centre_Id
                            INNER JOIN dbo.T_Student_Course_Detail SCD ON SCD.I_Student_Detail_ID = B.I_Student_Detail_ID
                            AND [SCD].[I_Course_ID] = [B].[I_Course_ID]
                            INNER JOIN dbo.T_Course_Master COM ON COM.I_Course_ID = SCD.I_Course_ID
                            LEFT OUTER JOIN [dbo].T_Term_Master TM ON TM.I_Term_ID = B.I_Term_ID
                    WHERE   
                            F.I_Centre_ID IN ( SELECT   I_Center_ID
                                               FROM     #TempCenter )
	                        AND B.I_Term_ID IS NOT NULL
                            AND A.I_Status = COALESCE(@iStatusID, A.I_Status)
                            AND B.B_PS_Flag = 0
                END		
    END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetTemplateList]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: 23/08/2007
-- Description:	This SP for getting the template name for
--				Certificate or PS 
-- =============================================

CREATE PROCEDURE [PSCERTIFICATE].[uspGetTemplateList]--406,208
(
@iCourseID INT =NULL,
@iTermID INT = NULL,
@iPSCert INT = NULL,
@iCourseFamilyID INT
)
AS
BEGIN
		DECLARE @TemCourse TABLE
		(
		I_Course_ID INT
		)


		IF(@iCourseID IS NULL)
		BEGIN
			INSERT INTO @TemCourse 
			SELECT I_Course_ID FROM dbo.T_Course_Master
			WHERE I_CourseFamily_ID = @iCourseFamilyID
		END
		ELSE
		BEGIN
			INSERT INTO @TemCourse(I_Course_ID) VALUES(@iCourseID)
		END

		
		-- This for Course Certificate Code
		IF(@iPSCert = 0)
					BEGIN  
							-- This for Certificate Template
					SELECT DISTINCT S_Template_Code,S_File_Location,TM.I_Template_ID AS I_Template_ID FROM dbo.T_Template_Master TM
					INNER JOIN dbo.T_Certificate_Master CM 
					ON TM.I_Template_ID = CM.I_Template_ID
					INNER JOIN dbo.T_Course_Master COM
					ON CM.I_Certificate_ID = COM.I_Certificate_ID
					WHERE 
					--COM.I_Course_ID = @iCourseID 
					COM.I_Course_ID IN (SELECT I_Course_ID FROM @TemCourse)
					AND TM.I_Status = 1
					--ORDER BY TM.Dt_Crtd_On DESC
					END


		-- This for Course PS
		ELSE IF (@iPSCert = 1)
					BEGIN 
						-- This For PS Template
							SELECT DISTINCT S_Template_Code,S_File_Location,TM.I_Template_ID AS I_Template_ID  FROM dbo.T_Template_Master TM
							INNER JOIN 	dbo.T_Term_Eval_Strategy TES
							ON TM.I_Template_ID = TES.I_Template_ID
							WHERE TES.I_Course_ID IN (SELECT I_Course_ID FROM @TemCourse)
							--AND   TES.I_Term_ID = @iTermID	
							AND TM.I_Status = 1	
							AND TM.S_Template_Type = 2
							--ORDER BY TM.Dt_Crtd_On DESC	
					END

		-- This For Term Certificate Code
		ELSE
			BEGIN  
					--THIS IS FOR TERM LAVEL CERTIFICATE
							SELECT DISTINCT S_Template_Code,S_File_Location,TM.I_Template_ID AS I_Template_ID  FROM dbo.T_Template_Master TM
							INNER JOIN dbo.T_Certificate_Master CM 
							ON TM.I_Template_ID = CM.I_Template_ID
							INNER JOIN dbo.T_Term_Course_Map TCM
							ON CM.I_Certificate_ID = TCM.I_Certificate_ID
							WHERE 
							--TCM.I_Course_ID =  @iCourseID 
							TCM.I_Course_ID IN (SELECT I_Course_ID FROM @TemCourse)
							--AND TCM.I_Term_ID = @iTermID	
							AND TM.I_Status = 1
							AND CM.S_Certificate_Type = 'Term'
							AND TM.S_Template_Type = 1

	END
END
GO
PRINT N'Creating Procedure [PSCERTIFICATE].[uspGetTemplate]...';


GO
-- =============================================
-- Author:		Shankha Roy
-- Create date: 23/08/2007
-- Description:	This SP for getting the template name for
--				Certificate or PS 
-- =============================================

CREATE PROCEDURE [PSCERTIFICATE].[uspGetTemplate]--406,208
(
@iCourseID INT,
@iTermID INT = NULL,
@iPSCert INT = NULL

)
AS
BEGIN

	IF @iTermID IS NULL
		BEGIN
			-- This for Certificate Template
			SELECT S_Template_Code,S_File_Location FROM dbo.T_Template_Master TM
			INNER JOIN dbo.T_Certificate_Master CM 
			ON TM.I_Template_ID = CM.I_Template_ID
			INNER JOIN dbo.T_Course_Master COM
			ON CM.I_Certificate_ID = COM.I_Certificate_ID
			WHERE COM.I_Course_ID = @iCourseID 
			AND TM.I_Status = 1
			ORDER BY TM.Dt_Crtd_On DESC
		END
	ELSE
		BEGIN
			
			IF(@iPSCert = 1)
			BEGIN 
					--THIS IS FOR TERM LAVEL CERTIFICATE
					SELECT S_Template_Code,S_File_Location FROM dbo.T_Template_Master TM
					INNER JOIN dbo.T_Certificate_Master CM 
					ON TM.I_Template_ID = CM.I_Template_ID
					INNER JOIN dbo.T_Term_Course_Map TCM
					ON CM.I_Certificate_ID = TCM.I_Certificate_ID
					WHERE 
					TCM.I_Course_ID =  @iCourseID 
					AND TCM.I_Term_ID = @iTermID	
					AND TM.I_Status = 1
					AND CM.S_Certificate_Type = 'Term'
			END 
			ELSE
				BEGIN
						-- This For PS Template
					SELECT DISTINCT S_Template_Code,S_File_Location FROM dbo.T_Template_Master TM
					INNER JOIN 	dbo.T_Term_Eval_Strategy TES
					ON TM.I_Template_ID = TES.I_Template_ID
					WHERE TES.I_Course_ID = @iCourseID
					AND   TES.I_Term_ID = @iTermID	
					AND TM.I_Status = 1	
					--ORDER BY TM.Dt_Crtd_On DESC	
				END


		END



END
GO
