(
BrandName,
CenterName,
ReceiptHeaderID,
ReceiptNo,
InvoiceHeaderID,
ReceiptDate,
StudentDetailID,
PaymentMode,
CenterID,
EnquiryID,
ReceiptAmount,
FundTransferStatus,
StatusID,
