GO
CREATE PROCEDURE REPORT.uspGetAccrualvsAdjustmentwithAging
(
@sHierarchyListID VARCHAR(MAX),
@iBrandID INT,
@dtStartDate DATETIME,
@dtEndDate DATETIME,
@iVal INT
)
AS

BEGIN

DECLARE @i INT

SET @i=0

CREATE TABLE #temp
(
CenterName VARCHAR(MAX),
CourseName VARCHAR(MAX),
BatchName VARCHAR(MAX),
StudentID VARCHAR(MAX),
StudentName VARCHAR(MAX),
ContactNo VARCHAR(MAX),
RollNo INT,
InvHeaderID INT,
InvNo VARCHAR(MAX),
InvDetID INT,
InstNo INT,
InstDate DATE,
MonthYear VARCHAR(MAX),
Aging INT,
ComponentName VARCHAR(MAX),
AmountDue DECIMAL(14,2),
AmountPaid DECIMAL(14,2),
TaxDue DECIMAL(14,2),
TaxPaid DECIMAL(14,2),
AmtDiff DECIMAL(14,2),
TaxDiff DECIMAL(14,2),
TotalDiff DECIMAL(14,2)
)

WHILE (@i<=@iVal)

BEGIN

INSERT INTO #temp
        ( CenterName ,
          CourseName ,
          BatchName ,
          StudentID ,
          StudentName ,
          ContactNo ,
          RollNo ,
          InvHeaderID ,
          InvNo ,
          InvDetID ,
          InstNo ,
          InstDate ,
          MonthYear ,
          Aging ,
          ComponentName ,
          AmountDue ,
          AmountPaid ,
          TaxDue ,
          TaxPaid ,
          AmtDiff ,
          TaxDiff ,
          TotalDiff
        )
SELECT Final.S_Center_Name ,
                Final.S_Course_Name ,
                Final.S_Batch_Name ,
                Final.S_Student_ID ,
                Final.StudentName ,
                Final.ContactNo,
                Final.I_RollNo ,
                Final.I_Invoice_Header_ID ,
                Final.S_Invoice_No ,
                Final.I_Invoice_Detail_ID ,
                Final.I_Installment_No ,
                Final.Dt_Installment_Date ,
                DATENAME(MONTH,Final.Dt_Installment_Date)+' '+CAST(DATEPART(YYYY,Final.Dt_Installment_Date) AS VARCHAR) AS MonthYear,
                DATEDIFF(m,Final.Dt_Installment_Date,GETDATE()) AS Ageing,
                Final.S_Component_Name ,
                Final.N_Amount_Due ,
                Final.ReceiptCompAmount ,
                Final.TotalTax ,
                Final.ReceiptCompTax,
                Final.BaseAmtDiff,
                Final.TaxDiff,
                Final.BaseAmtDiff+Final.TaxDiff AS TotalDiff
		FROM
		(
        SELECT  InvoiceDue.S_Center_Name ,
                InvoiceDue.S_Course_Name ,
                InvoiceDue.S_Batch_Name ,
                InvoiceDue.S_Student_ID ,
                InvoiceDue.StudentName ,
                InvoiceDue.ContactNo,
                InvoiceDue.I_RollNo ,
                InvoiceDue.I_Invoice_Header_ID ,
                InvoiceDue.S_Invoice_No ,
                InvoiceDue.I_Invoice_Detail_ID ,
                InvoiceDue.I_Installment_No ,
                InvoiceDue.Dt_Installment_Date ,
                InvoiceDue.S_Component_Name ,
                InvoiceDue.N_Amount_Due ,
                ReceiptAmt.ReceiptCompAmount ,
                InvoiceTax.TotalTax ,
                ReceiptTax.ReceiptCompTax ,
                ( InvoiceDue.N_Amount_Due
                  - ISNULL(ReceiptAmt.ReceiptCompAmount, 0.0) ) AS BaseAmtDiff ,
                ( ISNULL(InvoiceTax.TotalTax, 0.0)
                  - ISNULL(ReceiptTax.ReceiptCompTax, 0.0) ) AS TaxDiff
        FROM    ( SELECT    TCHND.S_Center_Name ,
                            TCM.S_Course_Name ,
                            TSBM.S_Batch_Name ,
                            TSD.S_Student_ID ,
                            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,
                                                            '') + ' '
                            + TSD.S_Last_Name AS StudentName ,
                            TSD.S_Mobile_No AS ContactNo,
                            TSD.I_RollNo ,
                            TIP.I_Invoice_Header_ID ,
                            TIP.S_Invoice_No ,
                            TICD.I_Invoice_Detail_ID ,
                            TICD.I_Installment_No ,
                            TICD.Dt_Installment_Date ,
                            TFCM.S_Component_Name ,
                            TICD.N_Amount_Due
                  FROM      dbo.T_Invoice_Parent TIP
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Invoice_Child_Detail TICD ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID
                            INNER JOIN dbo.T_Fee_Component_Master TFCM ON TICD.I_Fee_Component_ID = TFCM.I_Fee_Component_ID
                            INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN ( SELECT T1.I_Student_ID ,
                                                T2.I_Batch_ID
                                         FROM   ( SELECT    TSBD2.I_Student_ID ,
                                                            MAX(TSBD2.I_Student_Batch_ID) AS ID
                                                  FROM      dbo.T_Student_Batch_Details TSBD2
                                                  WHERE     TSBD2.I_Status IN (
                                                            1, 3 ,2,0)
                                                  GROUP BY  TSBD2.I_Student_ID
                                                ) T1
                                                INNER JOIN ( SELECT
                                                              TSBD3.I_Student_ID ,
                                                              TSBD3.I_Student_Batch_ID AS ID ,
                                                              TSBD3.I_Batch_ID
                                                             FROM
                                                              dbo.T_Student_Batch_Details TSBD3
                                                             WHERE
                                                              TSBD3.I_Status IN (
                                                              1, 3 ,2,0)
                                                           ) T2 ON T1.I_Student_ID = T2.I_Student_ID
                                                              AND T1.ID = T2.ID
                                       ) TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                                                 AND TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                            INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                            INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                  WHERE     TICD.Dt_Installment_Date >= DATEADD(d,-(@i*360),@dtStartDate)
                            AND TICD.Dt_Installment_Date < DATEADD(d,1,DATEADD(d,-(@i*360),@dtEndDate))
                            --AND TSD.S_Student_ID='1314/AC/1376'
                            AND TCHND.I_Center_ID IN (
                            SELECT  FGCFR.centerID
                            FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) FGCFR )
                            AND TIP.I_Status IN ( 1, 3 )
--ORDER BY TSD.S_Student_ID,TIP.I_Invoice_Header_ID,TICD.Dt_Installment_Date,TICD.I_Installment_No,TFCM.S_Component_Name
                  
                ) InvoiceDue
                LEFT JOIN ( SELECT  I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(N_Tax_Value, 0.0)), 0.0) AS TotalTax
                            FROM    dbo.T_Invoice_Detail_Tax TIDT
                            GROUP BY I_Invoice_Detail_ID
                          ) InvoiceTax ON InvoiceDue.I_Invoice_Detail_ID = InvoiceTax.I_Invoice_Detail_ID
                LEFT JOIN ( SELECT  TRCD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(TRCD.N_Amount_Paid), 0.0) AS ReceiptCompAmount
                            FROM    dbo.T_Receipt_Component_Detail TRCD
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                            WHERE   TRH.I_Status = 1
                            GROUP BY TRCD.I_Invoice_Detail_ID
                          ) ReceiptAmt ON InvoiceDue.I_Invoice_Detail_ID = ReceiptAmt.I_Invoice_Detail_ID
                LEFT JOIN ( SELECT  TRTD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0.0)),
                                           0.0) AS ReceiptCompTax
                            FROM    dbo.T_Receipt_Tax_Detail TRTD
                                    INNER JOIN dbo.T_Receipt_Component_Detail TRCD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                            WHERE   TRH.I_Status = 1
                            GROUP BY TRTD.I_Invoice_Detail_ID
                          ) ReceiptTax ON InvoiceDue.I_Invoice_Detail_ID = ReceiptTax.I_Invoice_Detail_ID
        --ORDER BY InvoiceDue.S_Student_ID ,
        --        InvoiceDue.I_Invoice_Header_ID ,
        --        InvoiceDue.I_Installment_No ,
        --        InvoiceDue.Dt_Installment_Date ,
        --        InvoiceDue.S_Component_Name 
        ) Final
        --WHERE
        --(Final.TaxDiff+Final.BaseAmtDiff)!=0
        ORDER BY Final.S_Center_Name,Final.S_Course_Name,Final.S_Batch_Name,Final.S_Student_ID ,
                Final.I_Invoice_Header_ID ,
                Final.I_Installment_No ,
                Final.Dt_Installment_Date ,
                Final.S_Component_Name
                
                
                SET @i=@i+1
                
                END
                
                SELECT * FROM #temp WHERE TotalDiff>0.00;
                
                
                END
GO
PRINT N'Creating Procedure [REPORT].[uspGetACAdmissionList_RTMS]...';


GO

CREATE PROCEDURE [REPORT].[uspGetACAdmissionList_RTMS]
    (
      @sHierarchyList VARCHAR(MAX) ,
      @iBrandID INT ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS 
    BEGIN

        IF ( @iBrandID = 111 ) 
            BEGIN
                SELECT  TCHND.S_Brand_Name,TCHND.I_Center_ID,TCHND.S_Center_Name ,
						CASE WHEN TCM2.S_Center_Code LIKE 'Judiciary T%'
                                     THEN 'Judiciary'
                                     WHEN TCM2.S_Center_Code LIKE 'IAS T%'
                                     THEN 'IAS'
                                     WHEN TCM2.S_Center_Code = 'BRST'
                                     THEN 'AIPT'
                                     WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN 'Franchise'
                                     ELSE 'Own'
                                END AS TypeofCentre,
                        TCM.S_Course_Name ,
                        TSD.S_Student_ID ,
                        TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '')
                        + ' ' + TSD.S_Last_Name AS StdName ,
                        CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                        DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS InvoiceMonthYear ,
                        TIP.S_Invoice_No ,
                        CONVERT(DATE,TSD.Dt_Crtd_On) AS AdmissionDate,
                        CASE WHEN ( SELECT  TBR.I_Student_Detail_ID
                                    FROM    dbo.T_Booking_Record TBR
                                    WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                            AND TBR.Dt_Booking_Date <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                  ) IS NOT NULL THEN 'YES'
                             WHEN ( SELECT  TBR.I_Student_Detail_ID
                                    FROM    dbo.T_Booking_Record TBR
                                    WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                            AND TBR.Dt_Booking_Date = TBR.Dt_Reg_Conversion_Date
                                  ) IS NOT NULL THEN 'NO'
                             WHEN ( SELECT  TBR.I_Student_Detail_ID
                                    FROM    dbo.T_Booking_Record TBR
                                    WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                  ) IS NULL THEN 'NO'
                        END AS IsBooking ,
                        CASE WHEN TSD.Dt_Crtd_On BETWEEN @dtStartDate
                                                 AND     DATEADD(d, 1,
                                                              @dtEndDate)
                             THEN 'New Admission/Booking'
                             WHEN TSD.Dt_Crtd_On NOT BETWEEN @dtStartDate
                                                 AND         DATEADD(d, 1,
                                                              @dtEndDate)
                             THEN 'Repeater Student'
                        END AS AdmStatus ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%' THEN 'NO'
                             WHEN TCM2.S_Center_Code NOT LIKE 'FR-%'
                             THEN 'YES'
                        END IsOwnCentre,
                        TSD.S_Mobile_No,
                        TSBM.S_Batch_Name,
                        TSBM.Dt_BatchStartDate,
                        TISM.S_Info_Source_Name,
                        TSD.Dt_Birth_Date,
                        TICH.C_Is_LumpSum,
						ISNULL(TSD.B_HasTakenLoan,0) as HasTakenLoan,
						ISNULL(A.S_Discount_Desc,'No Discount') as DiscountType,
						B.InfoSource,
						B.InfoMedium,
						B.InfoCampaign,
						TSD.S_Email_ID,
						TUS.S_Sex_Name,
						TERD.S_Form_No,
						TIP.I_Invoice_Header_ID,
						(TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0))-ISNULL(TIP.N_Discount_Amount,0) as PayableAmount,--added Discount calculation by susmita : 2023-Jan-28
						--TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0) as PayableAmount,
						1 AS IsAdmission,
						ISNULL(TDM.S_Discount_Scheme_Name,'') as PromoCode,--added by susmita : 2023-Jan-28
						TICH.N_Discount_Amount as DiscountAmount,--added by susmita : 2023-Jan-28
						ISNULL(TRH.Total_Receipt_Amount,0)+ISNULL(TRH.Total_Tax_Amount,0) as TotalPaidAmount--added by susmita : 2023-Jan-28
        --FROM    dbo.T_Invoice_Parent TIP
        --        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
        --        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
        --        INNER JOIN dbo.T_Student_Batch_Details TSBD ON TIBM.I_Batch_ID = TSBD.I_Batch_ID
        --                                                      AND TSBD.I_Student_ID = TIP.I_Student_Detail_ID
        --        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
        --        INNER JOIN dbo.T_Course_Master TCM ON TCHND.I_Brand_ID = TCM.I_Brand_ID
        --                                              AND TSBM.I_Course_ID = TCM.I_Course_ID
        --        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                FROM    dbo.T_Invoice_Parent TIP
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Centre_Master TCM2 ON TCHND.I_Center_ID = TCM2.I_Centre_Id
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
						left join T_Discount_Type A on A.I_Discount_Type_ID=TSD.I_DiscountType_ID
						left join T_Enquiry_External_Additional_Details B on TERD.I_Enquiry_Regn_ID=B.PreEnquiryID
						left join T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
						left join T_Discount_Scheme_Master as TDM on TDM.I_Discount_Scheme_ID=TICH.I_Discount_Scheme_ID --susmita paul : 2023-Jan-28 : use for Discount
						left join(--/* added by susmita : 2023-Jan-28
								select SUM(N_Receipt_Amount) as Total_Receipt_Amount,SUM(ISNULL(N_Tax_Amount,0)) as Total_Tax_Amount,I_Invoice_Header_ID
								from T_Receipt_Header where I_Status=1 group by I_Invoice_Header_ID
								)as TRH on TRH.I_Invoice_Header_ID=TIP.I_Invoice_Header_ID ----added by susmita : 2023-Jan-28 */
                WHERE   TIP.I_Status IN ( 0, 1 )
                        AND TIP.I_Parent_Invoice_ID IS NULL
                --AND TSBD.I_Status IN (0,1,2)
                        AND ( TIP.Dt_Crtd_On >= @dtStartDate
                              AND TIP.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                            )
                        AND TIP.I_Centre_Id IN (
                        SELECT  fnCenter.centerID
                        FROM    fnGetCentersForReports(@sHierarchyList,
                                                       @iBrandID) fnCenter )
                --AND TSD.S_Student_ID='1415/AC/1526'
            END
                
        ELSE 
            IF ( @iBrandID = 110
                 OR @iBrandID = 107
                 OR @iBrandID = 112
                 OR @iBrandID = 108
               ) 
                BEGIN
                    SELECT  TCHND.S_Brand_Name,TCHND.I_Center_ID,TCHND.S_Center_Name ,
							CASE WHEN TCM3.S_Center_Code LIKE 'Judiciary T%'
                                     THEN 'Judiciary'
                                     WHEN TCM3.S_Center_Code LIKE 'IAS T%'
                                     THEN 'IAS'
                                     WHEN TCM3.S_Center_Code = 'BRST'
                                     THEN 'AIPT'
                                     WHEN TCM3.S_Center_Code LIKE 'FR-%'
                                     THEN 'Franchise'
                                     ELSE 'Own'
                                END AS TypeofCentre,
                            TCM.S_Course_Name ,
                            TSD.S_Student_ID ,
                            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,
                                                            '') + ' '
                            + TSD.S_Last_Name AS StdName ,
                            CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                            DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                            + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS InvoiceMonthYear ,
                            TIP.S_Invoice_No ,
                            CONVERT(DATE,TSD.Dt_Crtd_On) AS AdmissionDate,
                            CASE WHEN ( SELECT  TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                      ) IS NOT NULL THEN 'YES'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date = TBR.Dt_Reg_Conversion_Date
                                      ) IS NOT NULL THEN 'NO'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                      ) IS NULL THEN 'NO'
                            END AS IsBooking ,
                            'New Admission/Booking' AS AdmStatus ,
                            CASE WHEN TCM3.S_Center_Code LIKE 'FR-%' THEN 'NO'
                                 WHEN TCM3.S_Center_Code NOT LIKE 'FR-%'
                                 THEN 'YES'
                            END IsOwnCentre,
                            TSD.S_Mobile_No,
                            TSBM.S_Batch_Name,
                            TSBM.Dt_BatchStartDate,
                            TISM.S_Info_Source_Name,
                            TSD.Dt_Birth_Date,
                            TICH.C_Is_LumpSum,
							ISNULL(TSD.B_HasTakenLoan,0) as HasTakenLoan,
							ISNULL(A.S_Discount_Desc,'No Discount') as DiscountType,
							B.InfoSource,
							B.InfoMedium,
							B.InfoCampaign,
							TSD.S_Email_ID,
							TUS.S_Sex_Name,
							TERD.S_Form_No,
							TIP.I_Invoice_Header_ID,
							(TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0))-ISNULL(TIP.N_Discount_Amount,0) as PayableAmount,--added Discount calculation by susmita : 2023-Jan-28
							1 AS IsAdmission,
							ISNULL(TDM.S_Discount_Scheme_Name,'') as PromoCode,--added by susmita : 2023-Jan-28
							TICH.N_Discount_Amount as DiscountAmount,--added by susmita : 2023-Jan-28
							ISNULL(TRH.Total_Receipt_Amount,0)+ISNULL(TRH.Total_Tax_Amount,0) as TotalPaidAmount--added by susmita : 2023-Jan-28
        --FROM    dbo.T_Invoice_Parent TIP
        --        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
        --        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
        --        INNER JOIN dbo.T_Student_Batch_Details TSBD ON TIBM.I_Batch_ID = TSBD.I_Batch_ID
        --                                                      AND TSBD.I_Student_ID = TIP.I_Student_Detail_ID
        --        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
        --        INNER JOIN dbo.T_Course_Master TCM ON TCHND.I_Brand_ID = TCM.I_Brand_ID
        --                                              AND TSBM.I_Course_ID = TCM.I_Course_ID
        --        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                    FROM    dbo.T_Invoice_Parent TIP
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                            INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                            INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                            INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                            INNER JOIN dbo.T_Centre_Master TCM3 ON TCHND.I_Center_ID = TCM3.I_Centre_Id
                            INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
							LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
							left join T_Discount_Type A on A.I_Discount_Type_ID=TSD.I_DiscountType_ID
							left join T_Enquiry_External_Additional_Details B on TERD.I_Enquiry_Regn_ID=B.PreEnquiryID
							left join T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
							left join T_Discount_Scheme_Master as TDM on TDM.I_Discount_Scheme_ID=TICH.I_Discount_Scheme_ID --susmita paul : 2023-Jan-28 : use for Discount
							left join(--/* added by susmita : 2023-Jan-28
								select SUM(N_Receipt_Amount) as Total_Receipt_Amount,SUM(ISNULL(N_Tax_Amount,0)) as Total_Tax_Amount,I_Invoice_Header_ID
								from T_Receipt_Header where I_Status=1 group by I_Invoice_Header_ID
								)as TRH on TRH.I_Invoice_Header_ID=TIP.I_Invoice_Header_ID ----added by susmita : 2023-Jan-28 */
                    WHERE   TIP.I_Status IN ( 0, 2, 1 )
                            AND TIP.I_Parent_Invoice_ID IS NULL
                --AND TSBD.I_Status IN (0,1,2)
                            AND ( TIP.Dt_Crtd_On >= @dtStartDate
                                  AND TIP.Dt_Crtd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                )
                            AND TIP.I_Centre_Id IN (
                            SELECT  fnCenter.centerID
                            FROM    fnGetCentersForReports(@sHierarchyList,
                                                           @iBrandID) fnCenter )
                            AND CONVERT(DATE, TIP.Dt_Invoice_Date) = CONVERT(DATE, TSD.Dt_Crtd_On)
                            AND CONVERT(DATE,TIBM.Dt_Crtd_On)=CONVERT(DATE,TSD.Dt_Crtd_On)
                            AND TICH.I_Course_ID IS NOT NULL
                            --AND DATEADD(MI, DATEDIFF(MI, 0, TIP.Dt_Invoice_Date), 0)=DATEADD(MI, DATEDIFF(MI, 0, TSD.Dt_Crtd_On), 0)
                END
				ELSE IF (@iBrandID = 109)
				BEGIN

					select  * from
(
SELECT  TCHND.S_Brand_Name,TCHND.I_Center_ID,TCHND.S_Center_Name ,
							CASE WHEN TCM3.S_Center_Code LIKE 'Judiciary T%'
                                     THEN 'Judiciary'
                                     WHEN TCM3.S_Center_Code LIKE 'IAS T%'
                                     THEN 'IAS'
                                     WHEN TCM3.S_Center_Code = 'BRST'
                                     THEN 'AIPT'
                                     WHEN TCM3.S_Center_Code LIKE 'FR-%'
                                     THEN 'Franchise'
                                     ELSE 'Own'
                                END AS TypeofCentre,
                            TCM.S_Course_Name ,
                            TSD.S_Student_ID ,
                            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,
                                                            '') + ' '
                            + TSD.S_Last_Name AS StdName ,
                            CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                            DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                            + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS InvoiceMonthYear ,
                            TIP.S_Invoice_No ,
                            CONVERT(DATE,TSD.Dt_Crtd_On) AS AdmissionDate,
                            CASE WHEN ( SELECT  TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                      ) IS NOT NULL THEN 'YES'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date = TBR.Dt_Reg_Conversion_Date
                                      ) IS NOT NULL THEN 'NO'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                      ) IS NULL THEN 'NO'
                            END AS IsBooking ,
                            'New Admission/Booking' AS AdmStatus ,
                            CASE WHEN TCM3.S_Center_Code LIKE 'FR-%' THEN 'NO'
                                 WHEN TCM3.S_Center_Code NOT LIKE 'FR-%'
                                 THEN 'YES'
                            END IsOwnCentre,
                            TSD.S_Mobile_No,
                            TSBM.S_Batch_Name,
                            TSBM.Dt_BatchStartDate,
                            TISM.S_Info_Source_Name,
                            TSD.Dt_Birth_Date,
                            TICH.C_Is_LumpSum,
							ISNULL(TSD.B_HasTakenLoan,0) as HasTakenLoan,
							ISNULL(A.S_Discount_Desc,'No Discount') as DiscountType,
							B.InfoSource,
							B.InfoMedium,
							B.InfoCampaign,
							TSD.S_Email_ID,
							TUS.S_Sex_Name,
							TERD.S_Form_No,
							TIP.I_Invoice_Header_ID,
							(TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0))-ISNULL(TIP.N_Discount_Amount,0) as PayableAmount,--added Discount calculation by susmita : 2023-Jan-28
							--TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0) as PayableAmount,
							CASE WHEN TCM.I_Course_ID in (520,519,730,728) and T1.InvHeaderID IS NOT NULL THEN 1
								 WHEN TCM.I_Course_ID in (520,519,730,728) and T1.InvHeaderID IS NULL THEN 0
								 ELSE 1 END AS IsAdmission,
							ISNULL(TDM.S_Discount_Scheme_Name,'') as PromoCode,--added by susmita : 2023-Jan-28
							TICH.N_Discount_Amount as DiscountAmount,--added by susmita : 2023-Jan-28
							ISNULL(TRH.Total_Receipt_Amount,0)+ISNULL(TRH.Total_Tax_Amount,0) as TotalPaidAmount--added by susmita : 2023-Jan-28
                    FROM    dbo.T_Invoice_Parent TIP
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                            INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                            INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                            INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                            INNER JOIN dbo.T_Centre_Master TCM3 ON TCHND.I_Center_ID = TCM3.I_Centre_Id
                            INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
							LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
							left join T_Discount_Type A on A.I_Discount_Type_ID=TSD.I_DiscountType_ID
							left join T_Enquiry_External_Additional_Details B on TERD.I_Enquiry_Regn_ID=B.PreEnquiryID
							left join T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
							left join
							(
								select A.I_Student_Detail_ID,MIN(A.I_Invoice_Header_ID) as InvHeaderID 
								from T_Invoice_Parent A
								inner join T_Invoice_Child_Header B on A.I_Invoice_Header_ID=B.I_Invoice_Header_ID
								where A.I_Parent_Invoice_ID IS NULL
								group by A.I_Student_Detail_ID
								--where B.I_Course_ID=730
							) T1 ON T1.InvHeaderID=TIP.I_Invoice_Header_ID and T1.I_Student_Detail_ID=TSD.I_Student_Detail_ID --and T1.I_Course_ID=TICH.I_Course_ID
							left join T_Discount_Scheme_Master as TDM on TDM.I_Discount_Scheme_ID=TICH.I_Discount_Scheme_ID --susmita paul : 2023-Jan-28 : use for Discount
							left join(--/* added by susmita : 2023-Jan-28
								select SUM(N_Receipt_Amount) as Total_Receipt_Amount,SUM(ISNULL(N_Tax_Amount,0)) as Total_Tax_Amount,I_Invoice_Header_ID
								from T_Receipt_Header where I_Status=1 group by I_Invoice_Header_ID
								)as TRH on TRH.I_Invoice_Header_ID=TIP.I_Invoice_Header_ID ----added by susmita : 2023-Jan-28 */
							WHERE   TIP.I_Status IN ( 0, 2, 1 )
                            AND TIP.I_Parent_Invoice_ID IS NULL
                --AND TSBD.I_Status IN (0,1,2)
                            AND ( TIP.Dt_Crtd_On >= @dtStartDate
                                  AND TIP.Dt_Crtd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                )
                            AND TIP.I_Centre_Id IN (
                            SELECT  fnCenter.centerID
                            FROM    fnGetCentersForReports(@sHierarchyList,
                                                           @iBrandID) fnCenter )
                            --AND CONVERT(DATE, TIP.Dt_Invoice_Date) = CONVERT(DATE, TSD.Dt_Crtd_On)
                            --AND CONVERT(DATE,TIBM.Dt_Crtd_On)=CONVERT(DATE,TSD.Dt_Crtd_On)
                            --AND TICH.I_Course_ID IS NOT NULL
							AND ISNULL(TCM.B_IsAdmissionCourse,1)=1
							--and TSD.S_Student_ID='2122/RICE/1130'
							--AND TCHND.I_Center_ID=132
							) ADM 
							where IsAdmission=1

				END

    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetACAdmissionList]...';


GO
CREATE PROCEDURE [REPORT].[uspGetACAdmissionList]
    (
      @sHierarchyList VARCHAR(MAX) ,
      @iBrandID INT ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS 
    BEGIN

        IF ( @iBrandID = 111 ) 
            BEGIN
                SELECT  TCHND.S_Brand_Name,TCHND.I_Center_ID,TCHND.S_Center_Name ,
						CASE WHEN TCM2.S_Center_Code LIKE 'Judiciary T%'
                                     THEN 'Judiciary'
                                     WHEN TCM2.S_Center_Code LIKE 'IAS T%'
                                     THEN 'IAS'
                                     WHEN TCM2.S_Center_Code = 'BRST'
                                     THEN 'AIPT'
                                     WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN 'Franchise'
                                     ELSE 'Own'
                                END AS TypeofCentre,
                        TCM.S_Course_Name ,
                        TSD.S_Student_ID ,
                        TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '')
                        + ' ' + TSD.S_Last_Name AS StdName ,
                        CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                        DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS InvoiceMonthYear ,
                        TIP.S_Invoice_No ,
                        CONVERT(DATE,TSD.Dt_Crtd_On) AS AdmissionDate,
                        CASE WHEN ( SELECT  TBR.I_Student_Detail_ID
                                    FROM    dbo.T_Booking_Record TBR
                                    WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                            AND TBR.Dt_Booking_Date <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                  ) IS NOT NULL THEN 'YES'
                             WHEN ( SELECT  TBR.I_Student_Detail_ID
                                    FROM    dbo.T_Booking_Record TBR
                                    WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                            AND TBR.Dt_Booking_Date = TBR.Dt_Reg_Conversion_Date
                                  ) IS NOT NULL THEN 'NO'
                             WHEN ( SELECT  TBR.I_Student_Detail_ID
                                    FROM    dbo.T_Booking_Record TBR
                                    WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                  ) IS NULL THEN 'NO'
                        END AS IsBooking ,
                        CASE WHEN TSD.Dt_Crtd_On BETWEEN @dtStartDate
                                                 AND     DATEADD(d, 1,
                                                              @dtEndDate)
                             THEN 'New Admission/Booking'
                             WHEN TSD.Dt_Crtd_On NOT BETWEEN @dtStartDate
                                                 AND         DATEADD(d, 1,
                                                              @dtEndDate)
                             THEN 'Repeater Student'
                        END AS AdmStatus ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%' THEN 'NO'
                             WHEN TCM2.S_Center_Code NOT LIKE 'FR-%'
                             THEN 'YES'
                        END IsOwnCentre,
                        TSD.S_Mobile_No,
                        TSBM.S_Batch_Name,
                        TSBM.Dt_BatchStartDate,
                        TISM.S_Info_Source_Name,
                        TSD.Dt_Birth_Date,
                        TICH.C_Is_LumpSum,
						ISNULL(TSD.B_HasTakenLoan,0) as HasTakenLoan,
						ISNULL(A.S_Discount_Desc,'No Discount') as DiscountType,
						B.InfoSource,
						B.InfoMedium,
						B.InfoCampaign,
						TSD.S_Email_ID,
						TUS.S_Sex_Name,
						TERD.S_Form_No,
						TIP.I_Invoice_Header_ID,
						TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0) as PayableAmount,
						1 AS IsAdmission
						,ISNULL(ESD.S_Referer_Mobile_No,'NA') as RefererMobileNo --susmita : 2023Nov29
						,ISNULL(ESD.S_Referer_Name,'NA') as RefererName --susmita : 2023Nov29
        --FROM    dbo.T_Invoice_Parent TIP
        --        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
        --        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
        --        INNER JOIN dbo.T_Student_Batch_Details TSBD ON TIBM.I_Batch_ID = TSBD.I_Batch_ID
        --                                                      AND TSBD.I_Student_ID = TIP.I_Student_Detail_ID
        --        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
        --        INNER JOIN dbo.T_Course_Master TCM ON TCHND.I_Brand_ID = TCM.I_Brand_ID
        --                                              AND TSBM.I_Course_ID = TCM.I_Course_ID
        --        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                FROM    dbo.T_Invoice_Parent TIP
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Centre_Master TCM2 ON TCHND.I_Center_ID = TCM2.I_Centre_Id
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
						left join dbo.Enquiry_Source_Details ESD on ESD.I_Enquiry_ID=TERD.I_Enquiry_Regn_ID and ESD.I_Status=1 ---added by susmita: 2023-Nov-29 : enquiry details
						left join T_Discount_Type A on A.I_Discount_Type_ID=TSD.I_DiscountType_ID
						left join T_Enquiry_External_Additional_Details B on TERD.I_Enquiry_Regn_ID=B.PreEnquiryID
						left join T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
                WHERE   TIP.I_Status IN ( 0, 1 )
                        AND TIP.I_Parent_Invoice_ID IS NULL
                --AND TSBD.I_Status IN (0,1,2)
                        AND ( TIP.Dt_Crtd_On >= @dtStartDate
                              AND TIP.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                            )
                        AND TIP.I_Centre_Id IN (
                        SELECT  fnCenter.centerID
                        FROM    fnGetCentersForReports(@sHierarchyList,
                                                       @iBrandID) fnCenter )
                --AND TSD.S_Student_ID='1415/AC/1526'
            END
                
        ELSE 
            IF ( @iBrandID = 110
                 OR @iBrandID = 107
                 OR @iBrandID = 112
                 OR @iBrandID = 108
               ) 
                BEGIN
                    SELECT  TCHND.S_Brand_Name,TCHND.I_Center_ID,TCHND.S_Center_Name ,
							CASE WHEN TCM3.S_Center_Code LIKE 'Judiciary T%'
                                     THEN 'Judiciary'
                                     WHEN TCM3.S_Center_Code LIKE 'IAS T%'
                                     THEN 'IAS'
                                     WHEN TCM3.S_Center_Code = 'BRST'
                                     THEN 'AIPT'
                                     WHEN TCM3.S_Center_Code LIKE 'FR-%'
                                     THEN 'Franchise'
                                     ELSE 'Own'
                                END AS TypeofCentre,
                            TCM.S_Course_Name ,
                            TSD.S_Student_ID ,
                            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,
                                                            '') + ' '
                            + TSD.S_Last_Name AS StdName ,
                            CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                            DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                            + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS InvoiceMonthYear ,
                            TIP.S_Invoice_No ,
                            CONVERT(DATE,TSD.Dt_Crtd_On) AS AdmissionDate,
                            CASE WHEN ( SELECT  TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                      ) IS NOT NULL THEN 'YES'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date = TBR.Dt_Reg_Conversion_Date
                                      ) IS NOT NULL THEN 'NO'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                      ) IS NULL THEN 'NO'
                            END AS IsBooking ,
                            'New Admission/Booking' AS AdmStatus ,
                            CASE WHEN TCM3.S_Center_Code LIKE 'FR-%' THEN 'NO'
                                 WHEN TCM3.S_Center_Code NOT LIKE 'FR-%'
                                 THEN 'YES'
                            END IsOwnCentre,
                            TSD.S_Mobile_No,
                            TSBM.S_Batch_Name,
                            TSBM.Dt_BatchStartDate,
                            TISM.S_Info_Source_Name,
                            TSD.Dt_Birth_Date,
                            TICH.C_Is_LumpSum,
							ISNULL(TSD.B_HasTakenLoan,0) as HasTakenLoan,
							ISNULL(A.S_Discount_Desc,'No Discount') as DiscountType,
							B.InfoSource,
							B.InfoMedium,
							B.InfoCampaign,
							TSD.S_Email_ID,
							TUS.S_Sex_Name,
							TERD.S_Form_No,
							TIP.I_Invoice_Header_ID,
							TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0) as PayableAmount,
							1 AS IsAdmission
							,ISNULL(ESD.S_Referer_Mobile_No,'NA') as RefererMobileNo --susmita : 2023Nov29
							,ISNULL(ESD.S_Referer_Name,'NA') as RefererName --susmita : 2023Nov29
        --FROM    dbo.T_Invoice_Parent TIP
        --        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
        --        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
        --        INNER JOIN dbo.T_Student_Batch_Details TSBD ON TIBM.I_Batch_ID = TSBD.I_Batch_ID
        --                                                      AND TSBD.I_Student_ID = TIP.I_Student_Detail_ID
        --        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
        --        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
        --        INNER JOIN dbo.T_Course_Master TCM ON TCHND.I_Brand_ID = TCM.I_Brand_ID
        --                                              AND TSBM.I_Course_ID = TCM.I_Course_ID
        --        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                    FROM    dbo.T_Invoice_Parent TIP
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                            INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                            INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                            INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                            INNER JOIN dbo.T_Centre_Master TCM3 ON TCHND.I_Center_ID = TCM3.I_Centre_Id
                            INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
							LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
							left join dbo.Enquiry_Source_Details ESD on ESD.I_Enquiry_ID=TERD.I_Enquiry_Regn_ID and ESD.I_Status=1 ---added by susmita: 2023-Nov-29 : enquiry details
							left join T_Discount_Type A on A.I_Discount_Type_ID=TSD.I_DiscountType_ID
							left join T_Enquiry_External_Additional_Details B on TERD.I_Enquiry_Regn_ID=B.PreEnquiryID
							left join T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
                    WHERE   TIP.I_Status IN ( 0, 2, 1 )
                            AND TIP.I_Parent_Invoice_ID IS NULL
                --AND TSBD.I_Status IN (0,1,2)
                            AND ( TIP.Dt_Crtd_On >= @dtStartDate
                                  AND TIP.Dt_Crtd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                )
                            AND TIP.I_Centre_Id IN (
                            SELECT  fnCenter.centerID
                            FROM    fnGetCentersForReports(@sHierarchyList,
                                                           @iBrandID) fnCenter )
                            AND CONVERT(DATE, TIP.Dt_Invoice_Date) = CONVERT(DATE, TSD.Dt_Crtd_On)
                            AND CONVERT(DATE,TIBM.Dt_Crtd_On)=CONVERT(DATE,TSD.Dt_Crtd_On)
                            AND TICH.I_Course_ID IS NOT NULL
                            --AND DATEADD(MI, DATEDIFF(MI, 0, TIP.Dt_Invoice_Date), 0)=DATEADD(MI, DATEDIFF(MI, 0, TSD.Dt_Crtd_On), 0)
                END
				ELSE IF (@iBrandID = 109)
				BEGIN

					select  * from
(
SELECT  TCHND.S_Brand_Name,TCHND.I_Center_ID,TCHND.S_Center_Name ,
							CASE WHEN TCM3.S_Center_Code LIKE 'Judiciary T%'
                                     THEN 'Judiciary'
                                     WHEN TCM3.S_Center_Code LIKE 'IAS T%'
                                     THEN 'IAS'
                                     WHEN TCM3.S_Center_Code = 'BRST'
                                     THEN 'AIPT'
                                     WHEN TCM3.S_Center_Code LIKE 'FR-%'
                                     THEN 'Franchise'
                                     ELSE 'Own'
                                END AS TypeofCentre,
                            TCM.S_Course_Name ,
                            TSD.S_Student_ID ,
                            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,
                                                            '') + ' '
                            + TSD.S_Last_Name AS StdName ,
                            CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                            DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                            + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS InvoiceMonthYear ,
                            TIP.S_Invoice_No ,
                            CONVERT(DATE,TSD.Dt_Crtd_On) AS AdmissionDate,
                            CASE WHEN ( SELECT  TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                      ) IS NOT NULL THEN 'YES'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                AND TBR.Dt_Booking_Date = TBR.Dt_Reg_Conversion_Date
                                      ) IS NOT NULL THEN 'NO'
                                 WHEN ( SELECT TOP 1 TBR.I_Student_Detail_ID
                                        FROM    dbo.T_Booking_Record TBR
                                        WHERE   TBR.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                      ) IS NULL THEN 'NO'
                            END AS IsBooking ,
                            'New Admission/Booking' AS AdmStatus ,
                            CASE WHEN TCM3.S_Center_Code LIKE 'FR-%' THEN 'NO'
                                 WHEN TCM3.S_Center_Code NOT LIKE 'FR-%'
                                 THEN 'YES'
                            END IsOwnCentre,
                            TSD.S_Mobile_No,
                            TSBM.S_Batch_Name,
                            TSBM.Dt_BatchStartDate,
                            TISM.S_Info_Source_Name,
                            TSD.Dt_Birth_Date,
                            TICH.C_Is_LumpSum,
							ISNULL(TSD.B_HasTakenLoan,0) as HasTakenLoan,
							ISNULL(A.S_Discount_Desc,'No Discount') as DiscountType,
							B.InfoSource,
							B.InfoMedium,
							B.InfoCampaign,
							TSD.S_Email_ID,
							TUS.S_Sex_Name,
							TERD.S_Form_No,
							TIP.I_Invoice_Header_ID,
							TIP.N_Invoice_Amount+ISNULL(TIP.N_Tax_Amount,0) as PayableAmount,
							CASE WHEN TCM.I_Course_ID in (520,519,730,728) and T1.InvHeaderID IS NOT NULL THEN 1
								 WHEN TCM.I_Course_ID in (520,519,730,728) and T1.InvHeaderID IS NULL THEN 0
								 ELSE 1 END AS IsAdmission
							,ISNULL(ESD.S_Referer_Mobile_No,'NA') as RefererMobileNo --susmita : 2023Nov29
							,ISNULL(ESD.S_Referer_Name,'NA') as RefererName --susmita : 2023Nov29

                    FROM    dbo.T_Invoice_Parent TIP
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                            INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                            INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                            INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                            INNER JOIN dbo.T_Centre_Master TCM3 ON TCHND.I_Center_ID = TCM3.I_Centre_Id
                            INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
							LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
							left join dbo.Enquiry_Source_Details ESD on ESD.I_Enquiry_ID=TERD.I_Enquiry_Regn_ID and ESD.I_Status=1 ---added by susmita: 2023-Nov-29 : enquiry details
							left join T_Discount_Type A on A.I_Discount_Type_ID=TSD.I_DiscountType_ID
							left join T_Enquiry_External_Additional_Details B on TERD.I_Enquiry_Regn_ID=B.PreEnquiryID
							left join T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
							left join
							(
								select A.I_Student_Detail_ID,MIN(A.I_Invoice_Header_ID) as InvHeaderID 
								from T_Invoice_Parent A
								inner join T_Invoice_Child_Header B on A.I_Invoice_Header_ID=B.I_Invoice_Header_ID
								where A.I_Parent_Invoice_ID IS NULL
								group by A.I_Student_Detail_ID
								--where B.I_Course_ID=730
							) T1 ON T1.InvHeaderID=TIP.I_Invoice_Header_ID and T1.I_Student_Detail_ID=TSD.I_Student_Detail_ID --and T1.I_Course_ID=TICH.I_Course_ID
                    WHERE   TIP.I_Status IN ( 0, 2, 1 )
                            AND TIP.I_Parent_Invoice_ID IS NULL
                --AND TSBD.I_Status IN (0,1,2)
                            AND ( TIP.Dt_Crtd_On >= @dtStartDate
                                  AND TIP.Dt_Crtd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                )
                            AND TIP.I_Centre_Id IN (
                            SELECT  fnCenter.centerID
                            FROM    fnGetCentersForReports(@sHierarchyList,
                                                           @iBrandID) fnCenter )
                            --AND CONVERT(DATE, TIP.Dt_Invoice_Date) = CONVERT(DATE, TSD.Dt_Crtd_On)
                            --AND CONVERT(DATE,TIBM.Dt_Crtd_On)=CONVERT(DATE,TSD.Dt_Crtd_On)
                            --AND TICH.I_Course_ID IS NOT NULL
							AND ISNULL(TCM.B_IsAdmissionCourse,1)=1
							--and TSD.S_Student_ID='2122/RICE/1130'
							--AND TCHND.I_Center_ID=132
							) ADM 
							where IsAdmission=1

				END

    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetAISPROGRESSREPORTNewAkash]...';


GO

--exec [REPORT].[uspGetAISPROGRESSREPORTNewAkash] 127,109,754
CREATE PROCEDURE [REPORT].[uspGetAISPROGRESSREPORTNewAkash]
    (
      @sHierarchyList varchar(MAX),
      @iBrandID int,
      @iBatchID INT, 
      @iTermID int =Null,
      @iStudentID int =Null
   
    )
AS 
    BEGIN
    Declare @iCourseID INT,
			@sCourierName varchar(50),
			@sBatchName varchar(100),
			@sClass Varchar(10),
			@iBatchExamID Int,
			@iModuleID int,
			@iExamComponentID int,
			@sStudentName VARCHAR(250),
			@sStudentID VARCHAR(250),
			@t1 int=375,--Akash
			@t2 int=376,--Akash
			@t3 int=NULL--Akash

	SELECT  @iCourseID=tsbm.I_Course_ID,
			@sBatchName=tsbm.S_Batch_Name,
			@sCourierName=tcm.S_Course_Name,
			@sClass=tcm.s_course_desc
	FROM dbo.T_Student_Batch_Master AS tsbm
	INNER JOIN T_Course_Master tcm on tcm.I_Course_ID=tsbm.I_Course_ID
	where tsbm.I_Batch_ID=@iBatchID

  CREATE TABLE #tbltempResult 
            (
              I_Center_ID INT ,
              I_Batch_Exam_ID INT,
              I_Batch_ID INT,
              I_Course_ID INT,
              courseSequence INT,
              I_Term_ID INT,
              I_Module_ID INT,
              S_Module_Name Varchar(250),
              I_Exam_Component_ID INT,
              S_Component_Name varchar(250),
              GradeSequence INT,
              I_Student_Detail_ID INT,
              I_Exam_Total Numeric(8,2),
              ModuleID1 INT,
              ModuleID1Marks Numeric(8,2),
			  ModuleID2 INT,
			  ModuleID2Marks Numeric(8,2),
			  ModuleID3 INT,
		      ModuleID3Marks Numeric(8,2),
		      ModuleID4 INT,
	 	     ModuleID4Marks Numeric(8,2),
              B_Optional BIT
            )


     CREATE TABLE #tblResult 
            (
              I_Student_Detail_ID INT ,
              S_Student_ID VARCHAR(250) ,
              S_Student_Name VARCHAR(150) ,
              I_Course_ID INT ,
              S_Course_Name VARCHAR(250) ,
              I_Batch_ID INT ,
              S_Batch_Name VARCHAR(250) ,
              I_Term_ID INT ,
              S_Term_Name VARCHAR(250) ,
              I_Exam_Component_ID INT ,
              S_Exam_Component_Name VARCHAR(200) ,
              I_Module_ID1 INT,
              ModuleID1FullMarks INT,
			  I_Exam_Total1 Numeric(8,2),
			  I_Module_ID2 INT,
			  ModuleID2FullMarks INT,
			  I_Exam_Total2 Numeric(8,2),
			  I_Module_ID3 INT,
			  ModuleID3FullMarks INT,
			  I_Exam_Total3 Numeric(8,2),
			  I_Module_ID4 INT,
			  ModuleID4FullMarks INT,
			  I_Exam_Total4 Numeric(8,2),
			  TotalMarks Numeric(8,2),
			 totalGrade varchar(5),
			  HighestMarks Numeric(8,2),
			  HighestGrade varchar(5),
			  classname varchar(15) ,
			  Term1TotalMarks numeric(8,2),
			  Term2TotalMarks numeric(8,2),
			  Term3TotalMarks numeric(8,2),
			  Cum1 numeric(8,2),
			  cum2 numeric(8,2),
			  cum3 numeric(8,2),
			  cumTotal numeric(8,2),
			  T2M1 numeric(8,2),
			  T2M2 numeric(8,2),
			  T2M3 numeric(8,2),
			  T2M4 numeric(8,2),
			  TermOne numeric(8,2),
			  
			  totalgradeT1 varchar(5),
			  totalgradeT2 varchar(5),
              B_Optional BIT
            )
            
            
            INSERT INTO #tblResult(
            I_Student_Detail_ID  ,
              S_Student_ID  ,
              S_Student_Name  ,
              I_Course_ID  ,
              S_Course_Name  ,
              I_Batch_ID  ,
              S_Batch_Name , 
              I_Term_ID  ,
              S_Term_Name  ,
              I_Exam_Component_ID  ,
              S_Exam_Component_Name ,
              classname,
			  B_Optional
            )
            SELECT distinct tsd.I_Student_Detail_ID,
            TSD.S_Student_ID,
            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '')+ ' ' + TSD.S_Last_Name StudentName,
            @iCourseID,
            @sCourierName,
            @iBatchID,
            @sBatchName,
            TBEM.I_Term_ID,
			TTM.S_Term_Name,
			TBEM.I_Exam_Component_ID,
			tecm.S_Component_Name,
            @sClass,
            tbem.B_Optional     
            
  FROM EXAMINATION.T_Batch_Exam_Map AS tbem with(NOLOCK)
  INNER JOIN EXAMINATION.T_Student_Marks TSM with(NOLOCK) ON tsm.I_Batch_Exam_ID=tbem.I_Batch_Exam_ID
  INNER JOIN dbo.T_Student_Detail AS tsd with(NOLOCK) ON tsm.I_Student_Detail_ID=tsd.I_Student_Detail_ID
  INNER JOIN dbo.T_Student_Batch_Details TSBD WITH (NOLOCK) ON  TSD.I_Student_Detail_ID=TSBD.I_Student_ID AND TSBD.I_Status=1
  INNER JOIN dbo.T_Term_Master TTM with(NOLOCK) ON TBEM.I_Term_ID=TTM.I_Term_ID
  INNER JOIN dbo.T_Exam_Component_Master  AS tecm with(NOLOCK) ON TBEM.I_Exam_Component_ID = tecm.I_Exam_Component_ID
  where tbem.I_Batch_ID=@iBatchID and tbem.I_Term_ID=ISNULL(@iTermID,tbem.I_Term_ID) and TSM.I_Student_Detail_ID=ISNULL(@istudentid,TSM.I_Student_Detail_ID)
  ORDER BY tsd.I_Student_Detail_ID,TBEM.I_Exam_Component_ID
  
  
  --Update #tblResult SET I_Exam_Total1=isnull(I_Exam_Total1,0)+isnull(I_Exam_Total2,0)+isnull(I_Exam_Total3,0)
  --  where   I_Exam_Component_ID =24
    
  --Update #tblResult SET I_Exam_Total2 =null,I_Exam_Total3=NULL
  --  where   I_Exam_Component_ID =24
  
  INSERT INTO #tbltempResult 
            (
              I_Center_ID  ,
              I_Batch_Exam_ID ,
              I_Batch_ID ,
              I_Course_ID ,
              courseSequence ,
              I_Term_ID ,
              I_Module_ID ,
              S_Module_Name ,
              I_Exam_Component_ID ,
              S_Component_Name ,
              GradeSequence ,
              I_Student_Detail_ID ,
              I_Exam_Total ,
              ModuleID1 ,
			  ModuleID1Marks ,
			  ModuleID2 ,
			  ModuleID2Marks ,
			  ModuleID3 ,
		      ModuleID3Marks ,
		      ModuleID4 ,
		     ModuleID4Marks 
                         
            )
 select  TSM.I_Center_ID,
		TSM.I_Batch_Exam_ID,
		TBEM.I_Batch_ID, 
		tsbm.I_Course_ID,
		ttcm.I_Sequence courseSequence,
		TBEM.I_Term_ID,
		TBEM.I_Module_ID,
		tmm.S_Module_Name,
		TBEM.I_Exam_Component_ID,
		tecm.S_Component_Name, 
		 tmtm.I_Sequence GradeSequence,
		TSM.I_Student_Detail_ID,
		TSM.I_Exam_Total ,
		Case when tmtm.I_Sequence=1 then TBEM.I_Module_ID else Null end ModuleID1,
		Case when tmtm.I_Sequence=1 then TSM.I_Exam_Total else Null end ModuleID1Marks,
		Case when tmtm.I_Sequence=2 then TBEM.I_Module_ID else Null end ModuleID2,
		Case when tmtm.I_Sequence=2 then TSM.I_Exam_Total else Null end ModuleID2Marks,
		Case when tmtm.I_Sequence=3 then TBEM.I_Module_ID else Null end ModuleID3,
		Case when tmtm.I_Sequence=3 then TSM.I_Exam_Total else Null end ModuleID3Marks,
		Case when tmtm.I_Sequence=4 then TBEM.I_Module_ID else Null end ModuleID4,
		Case when tmtm.I_Sequence=4 then TSM.I_Exam_Total else Null end ModuleID4Marks
		from EXAMINATION.T_Student_Marks TSM with(NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map TBEM with(NOLOCK) ON TBEM.I_Batch_Exam_ID = TSM.I_Batch_Exam_ID
		INNER JOIN dbo.T_Exam_Component_Master AS tecm with(NOLOCK) ON tbem.I_Exam_Component_ID = tecm.I_Exam_Component_ID
		INNER JOIN  dbo.T_Module_Master AS tmm with(NOLOCK) ON TBEM.I_Module_ID =tmm.I_Module_ID
		INNER JOIN dbo.T_Module_Term_Map AS tmtm with(NOLOCK) ON tbem.I_Module_ID = tmtm.I_Module_ID AND tbem.I_Term_ID = tmtm.I_Term_ID	 AND tmtm.I_Status = 1
		INNER JOIN dbo.T_Term_Course_Map AS ttcm with(NOLOCK) ON tmtm.I_Term_ID = ttcm.I_Term_ID AND ttcm.I_Status = 1
		INNER JOIN dbo.T_Student_Batch_Master tsbm with(NOLOCK) ON tsbm.I_Batch_ID = tbem.I_Batch_ID	
		INNER JOIN #tblResult A ON TSM.I_Student_Detail_ID=A.I_Student_Detail_ID
  
  
  
  --select * from #tbltempResult
  
  UPDATE T SET  I_Module_ID1 =V.ModuleID1,
			  I_Exam_Total1 =V.ModuleID1Marks  FROM #tblResult T INNER JOIN #tbltempResult V ON T.I_Course_ID=V.I_Course_ID and T.I_Term_ID =V.I_Term_ID and T.I_Student_Detail_ID=V.I_Student_Detail_ID and T.I_Exam_Component_ID=V.I_Exam_Component_ID and V.GradeSequence=1 AND T.I_Batch_ID = V.I_Batch_ID
            
 
  UPDATE T SET  I_Module_ID2 =V.ModuleID2,
			  I_Exam_Total2 =V.ModuleID2Marks  FROM #tblResult T INNER JOIN #tbltempResult V ON T.I_Course_ID=V.I_Course_ID and T.I_Term_ID =V.I_Term_ID and T.I_Student_Detail_ID=V.I_Student_Detail_ID and T.I_Exam_Component_ID=V.I_Exam_Component_ID and V.GradeSequence=2 AND T.I_Batch_ID = V.I_Batch_ID
			  
  UPDATE T SET  I_Module_ID3 =V.ModuleID3,
			  I_Exam_Total3 =V.ModuleID3Marks  FROM #tblResult T INNER JOIN #tbltempResult V ON T.I_Course_ID=V.I_Course_ID and T.I_Term_ID =V.I_Term_ID and T.I_Student_Detail_ID=V.I_Student_Detail_ID and T.I_Exam_Component_ID=V.I_Exam_Component_ID and V.GradeSequence=3 AND T.I_Batch_ID = V.I_Batch_ID
			  
  UPDATE T SET  I_Module_ID4 =V.ModuleID4,
			  I_Exam_Total4 =V.ModuleID4Marks  FROM #tblResult T INNER JOIN #tbltempResult V ON T.I_Course_ID=V.I_Course_ID and T.I_Term_ID =V.I_Term_ID and T.I_Student_Detail_ID=V.I_Student_Detail_ID and T.I_Exam_Component_ID=V.I_Exam_Component_ID and V.GradeSequence=4 AND T.I_Batch_ID = V.I_Batch_ID
  
          
 UPDATE #tblResult SET   TotalMarks=ROUND(ISNULL(I_Exam_Total1,0),0)+ROUND(ISNULL(I_Exam_Total2,0),0)+ROUND(ISNULL(I_Exam_Total3,0),0)+ROUND(ISNULL(I_Exam_Total4,0),0)
 UPDATE #tblResult SET   TotalMarks= NULL WHERE I_Exam_Total1 IS NULL AND I_Exam_Total2 IS NULL AND I_Exam_Total3 IS NULL AND I_Exam_Total4 IS NULL	
 
 
     --Akash Modifications
     
        
      UPDATE  #tblResult SET   Term1TotalMarks=ROUND(ISNULL(I_Exam_Total1,0),0)+ROUND(ISNULL(I_Exam_Total2,0),0)+ROUND(ISNULL(I_Exam_Total3,0),0)+ROUND(ISNULL(I_Exam_Total4,0),0) where I_Term_ID=@t1--(select distinct I_Term_ID from (select ROW_NUMBER() over (order by I_Term_ID asc) as rownumber,I_Term_ID from #tblResult)as foo1
      --where rownumber=1)
 UPDATE #tblResult SET   Term1TotalMarks= NULL WHERE I_Exam_Total1 IS NULL AND I_Exam_Total2 IS NULL AND I_Exam_Total3 IS NULL AND I_Exam_Total4 IS NULL
 
  UPDATE  #tblResult SET   Term2TotalMarks=ROUND(ISNULL(I_Exam_Total1,0),0)+ROUND(ISNULL(I_Exam_Total2,0),0)+ROUND(ISNULL(I_Exam_Total3,0),0)+ROUND(ISNULL(I_Exam_Total4,0),0) where I_Term_ID=@t2--(select distinct I_Term_ID from (select ROW_NUMBER() over (order by I_Term_ID asc) as rownumber,I_Term_ID from #tblResult)as foo2
      --where rownumber=2)
 UPDATE #tblResult SET   Term2TotalMarks= NULL WHERE I_Exam_Total1 IS NULL AND I_Exam_Total2 IS NULL AND I_Exam_Total3 IS NULL AND I_Exam_Total4 IS NULL
 
  UPDATE  #tblResult SET   Term3TotalMarks=ROUND(ISNULL(I_Exam_Total1,0),0)+ROUND(ISNULL(I_Exam_Total2,0),0)+ROUND(ISNULL(I_Exam_Total3,0),0)+ROUND(ISNULL(I_Exam_Total4,0),0) where I_Term_ID=@t3--(select distinct I_Term_ID from (select ROW_NUMBER() over (order by I_Term_ID asc) as rownumber,I_Term_ID from #tblResult)as foo3
    --  where rownumber=3)
 UPDATE #tblResult SET   Term3TotalMarks= NULL WHERE I_Exam_Total1 IS NULL AND I_Exam_Total2 IS NULL AND I_Exam_Total3 IS NULL AND I_Exam_Total4 IS NULL
 
 update #tblResult set TermOne=#tblResult.Term1TotalMarks	
        
    update #tblResult set Cum1=ROUND(0.5*isnull(Term1TotalMarks,0),0)
    update #tblResult set Cum1=NULL where Term1TotalMarks is null
    
    update #tblResult set cum2=ROUND(0.5*isnull(Term2TotalMarks,0),0)
    update #tblResult set cum2=NULL where Term2TotalMarks is null
    
   update #tblResult set cum3=ROUND(0.5*isnull(Term3TotalMarks,0),0)
    update #tblResult set cum3=NULL where Term3TotalMarks is null
    
    update #tblResult set cumTotal=ROUND(ISNULL(Cum1,0),0)+ROUND(ISNULL(cum2,0),0)+ROUND(ISNULL(cum3,0),0)
    
    update #tblResult set T2M1=round(isnull(I_Exam_Total1,0),0) where I_Term_ID=@t2
    update #tblResult set T2M1=null where I_Exam_Total1 is null and I_Term_ID=@t2
    
    update #tblResult set T2M2=round(isnull(I_Exam_Total2,0),0) where I_Term_ID=@t2
    update #tblResult set T2M2=null where I_Exam_Total2 is null and I_Term_ID=@t2
    
    update #tblResult set T2M3=round(isnull(I_Exam_Total3,0),0) where I_Term_ID=@t2
    update #tblResult set T2M3=null where I_Exam_Total3 is null and I_Term_ID=@t2
    
    update #tblResult set T2M4=round(isnull(I_Exam_Total4,0),0) where I_Term_ID=@t2
    update #tblResult set T2M4=null where I_Exam_Total4 is null and I_Term_ID=@t2
    
    
    ---Akash modifications
         
       Update T set HighestMarks =VR.Marks FROM #tblResult    T INNER JOIN 
         (select V.I_Course_ID,V.I_Term_ID,V.I_Exam_Component_ID,MAX(V.Marks)Marks  from ( 
         SELECT tsbm.I_Course_ID,tmtm.I_Term_ID,tbem.I_Exam_Component_ID ,tsm.I_Student_Detail_ID,sum(ROUND(ISNULL(I_Exam_Total,0),0)) Marks
		FROM EXAMINATION.T_Student_Marks AS tsm with(NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map tbem with(NOLOCK) ON tbem.I_Batch_Exam_ID = tsm.I_Batch_Exam_ID
		INNER JOIN dbo.T_Student_Batch_Details AS tsbd ON tsbd.I_Batch_ID = tbem.I_Batch_ID AND tsbd.I_Student_ID = tsm.I_Student_Detail_ID AND tsbd.I_Status = 1
		INNER JOIN dbo.T_Student_Batch_Master tsbm with(NOLOCK) ON tsbm.I_Batch_ID = tbem.I_Batch_ID
		INNER JOIN dbo.T_Module_Term_Map AS tmtm with(NOLOCK) ON tbem.I_Module_ID = tmtm.I_Module_ID AND tbem.I_Term_ID = tmtm.I_Term_ID AND tmtm.I_Status = 1
		INNER JOIN dbo.T_Module_Eval_Strategy AS tmes with(NOLOCK) ON tmes.I_Module_ID = tbem.I_Module_ID AND tmes.I_Term_ID = tbem.I_Term_ID AND tmes.I_Exam_Component_ID = tbem.I_Exam_Component_ID and tmes.I_Status=1
		INNER JOIN dbo.T_Exam_Component_Master AS tecm with(NOLOCK) ON tbem.I_Exam_Component_ID = tecm.I_Exam_Component_ID
		Group BY  tsbm.I_Course_ID,tmtm.I_Term_ID,tbem.I_Exam_Component_ID,tsm.I_Student_Detail_ID)V 
		Group BY V.I_Course_ID,V.I_Term_ID,V.I_Exam_Component_ID ) VR
		ON T.I_Course_ID=VR.I_Course_ID and T.I_Term_ID=VR.I_Term_ID
		and VR.I_Exam_Component_ID=T.I_Exam_Component_ID
          
          
              
    --Update #tblResult SET  I_Exam_Total1 =null,I_Exam_Total2 =null,I_Exam_Total3=NULL,I_Exam_Total4=NULL WHERE B_Optional = 1


    IF(upper(rtrim(ltrim(@sClass)))=upper('Class 9') or upper(rtrim(ltrim(@sClass)))=upper('Class 12') or upper(rtrim(ltrim(@sClass)))=upper('Class 10') or upper(rtrim(ltrim(@sClass)))=upper('Class 11') )
    BEGIN
    
		------Update #tblResult SET  I_Exam_Total1 =null,I_Exam_Total2 =null,I_Exam_Total3=NULL,I_Exam_Total4=NULL
		------where   I_Exam_Component_ID IN (25,46)
		    
		CREATE TABLE #tblGradeMst 
            (
              ID INT identity,
              FromMarks Numeric(8,2),
              ToMarks Numeric(8,2),
              Grade varchar(5)
              )
              
              
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(0,40,'F')
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(40,50,'C')
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(50,60,'C+')
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(60,70,'B')
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(70,80,'B+')
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(80,90,'A')
		INSERT INTO  #tblGradeMst  (FromMarks ,ToMarks ,Grade ) Values(90,100,'A+')
		
		UPDATE #tblResult SET  totalGrade= (select Grade from #tblGradeMst where cast(round(TotalMarks,0) as int)>=FromMarks and cast(round(TotalMarks,0) as int)<ToMarks) where       I_Exam_Component_ID IN (25,46)
				UPDATE #tblResult SET  totalGrade= 'A+' where cast(round(TotalMarks,0) as int)=100 and I_Exam_Component_ID IN (25,46)
				UPDATE #tblResult SET  HighestGrade= (select Grade from #tblGradeMst where cast(round(HighestMarks,0) as int)>=FromMarks and cast(round(HighestMarks,0) as int)<ToMarks) where       I_Exam_Component_ID IN (25,46)
				
				--Akash Modifications
				
				UPDATE #tblResult SET  totalgradeT1= (select Grade from #tblGradeMst where cast(round(Term1TotalMarks,0) as int)>=FromMarks and cast(round(Term1TotalMarks,0) as int)<ToMarks) where       I_Exam_Component_ID IN (25,46) and I_Term_ID=@t1
				UPDATE #tblResult SET  totalgradeT1= 'A+' where cast(round(Term1TotalMarks,0) as int)=100 and I_Exam_Component_ID IN (25,46) and I_Term_ID=@t1
				
				
				UPDATE #tblResult SET  totalgradeT2= (select Grade from #tblGradeMst where cast(round(Term2TotalMarks,0) as int)>=FromMarks and cast(round(Term2TotalMarks,0) as int)<ToMarks) where       I_Exam_Component_ID IN (25,46) and I_Term_ID=@t2
				UPDATE #tblResult SET  totalgradeT2= 'A+' where cast(round(Term2TotalMarks,0) as int)=100 and I_Exam_Component_ID IN (25,46) and I_Term_ID=@t2
		
				
				--Akash Modifications
   
				UPDATE #tblResult SET  HighestGrade= 'A+' where cast(round(HighestMarks,0) as int)=100 and I_Exam_Component_ID IN (25,46)
		
		UPDATE #tblResult SET I_Exam_Total1 = 0, TotalMarks = 0 WHERE I_Exam_Component_ID IN (25,46)
		UPDATE #tblResult SET I_Exam_Total1 = 0, Term1TotalMarks = 0 WHERE I_Exam_Component_ID IN (25,46)
		UPDATE #tblResult SET I_Exam_Total1 = 0, Term2TotalMarks = 0 WHERE I_Exam_Component_ID IN (25,46)
		UPDATE #tblResult SET I_Exam_Total1 = 0, Term3TotalMarks = 0 WHERE I_Exam_Component_ID IN (25,46)

   END 
		SELECT     I_Student_Detail_ID  ,
              S_Student_ID  ,
              S_Student_Name  ,
              I_Course_ID  ,
              S_Course_Name  ,
              I_Batch_ID ,
              S_Batch_Name  ,
              I_Term_ID  ,
              S_Term_Name  ,
              I_Exam_Component_ID  ,
              S_Exam_Component_Name  ,
              I_Module_ID1 ,
			  cast(round(ModuleID1FullMarks,0) as int) ModuleID1FullMarks,
			  cast(round(I_Exam_Total1,0) as int) I_Exam_Total1,
			  I_Module_ID2 ,
			  cast(round(ModuleID4FullMarks,0) as int) ModuleID2FullMarks,
			  cast(round(I_Exam_Total2,0) as int) I_Exam_Total2,
			  I_Module_ID3 ,
			  cast(round(ModuleID3FullMarks,0) as int) ModuleID3FullMarks,
			  cast(round(I_Exam_Total3,0) as int) I_Exam_Total3,
			  I_Module_ID4 ,
			  cast(round(ModuleID4FullMarks,0) as int) ModuleID4FullMarks,
			  cast(round(I_Exam_Total4,0) as int) I_Exam_Total4,
			  
			  
			  cast(round(TotalMarks,0) as int) TotalMarks,
			  cast(round(Term1TotalMarks,0) as int) Term1TotalMarks,
			  cast(round(Term2TotalMarks,0) as int) Term2TotalMarks,
			  cast(round(Term3TotalMarks,0) as int) Term3TotalMarks,
			  cast(round(Cum1,0) as int) Cumulative1,
			  cast(round(cum2,0) as int) Cumulative2,
			  cast(round(cum3,0) as int) Cumulative3,
			  cast(round(cumTotal,0) as int) CumulativeTotal,
			  CAST(round(T2M1,0) as int) T2M1,
			  CAST(round(T2M2,0) as int) T2M2,
			  CAST(round(T2M3,0) as int) T2M3,
			  CAST(round(T2M4,0) as int) T2M4,
			  CAST(round(TermOne,0) as int) TermOne,
			  totalGrade ,
			  totalgradeT1,
			  totalgradeT2,
			  cast(round(HighestMarks,0) as int) HighestMarks,
			  HighestGrade ,
			  classname,
			  REPORT.fnGetStudentAttendanceDetails(I_Student_Detail_ID,I_Term_ID,I_Batch_ID) AS Attendance,
			  REPORT.fnGetStudentConductDetails(I_Student_Detail_ID,I_Term_ID,I_Batch_ID) AS Conduct,
			  B_Optional
			   FROM #tblResult AS tr   
			   order by I_Term_ID desc --added to get the highestmasrks and attendance                         
    END
GO
