                ( BatchID ,
                  BatchName ,
                  TermID ,
                  TermName ,
                  ModuleID ,
                  ModuleName ,
                  ExamComponentID ,
                  ExamComponentName ,
                  FacultyID ,
                  FacultyName ,
                  FullMarks
                )
                SELECT DISTINCT
                        TSBM.I_Batch_ID ,
