                           ) T2 ON T2.BatchID = T1.BatchID


        UPDATE  T1
        SET     T1.StudentAttn = T2.Attn
        FROM    #MRKDTLS AS T1
                INNER JOIN ( SELECT TBEM.I_Batch_ID ,
                                    TBEM.I_Term_ID ,
                                    TBEM.I_Module_ID ,
                                    TBEM.I_Exam_Component_ID ,
                                    COUNT(DISTINCT TSM.I_Student_Detail_ID) AS Attn
                             FROM   EXAMINATION.T_Student_Marks AS TSM
