                                                    WITH ( NOLOCK ) ON RCD.I_Invoice_Detail_ID = ICD.I_Invoice_Detail_ID
                                            WHERE   ICD.I_Fee_Component_ID = 4
                                                    AND RH.I_Receipt_Header_ID = RCD.I_Receipt_Detail_ID
