                        LEFT OUTER JOIN DBO.T_User_Master TUM ON RH.S_Crtd_By = TUM.S_Login_ID
                WHERE   CAST(SUBSTRING(CAST(RH.Dt_Upd_On AS VARCHAR), 1, 11) AS DATETIME) BETWEEN @dtStartDate
