CREATE PROCEDURE [REPORT].[uspGetCollectionRegisterBreakup_OnAccount]
    (
      @sHierarchyList VARCHAR(MAX) ,
      @iBrandID INT ,
      @startDate DATE ,
      @endDate DATE
    )
AS
    BEGIN

        SELECT  RH.I_Centre_Id ,
                TCHND.S_Center_Name ,
                SD.I_Student_Detail_ID ,
                SD.S_Student_ID ,
                SD.S_First_Name + ' ' + ISNULL(SD.S_Middle_Name, '') + ' '
                + SD.S_Last_Name AS NAME ,
                SM.S_Status_Desc ,
                RH.S_Receipt_No ,
                RH.N_Receipt_Amount ,
                RH.N_Tax_Amount ,
                RH.Dt_Receipt_Date ,
                RH.S_Bank_Name ,
                RH.S_ChequeDD_No ,
                RH.Dt_ChequeDD_Date ,
                PM.S_PaymentMode_Name ,
                RH.S_Narration ,
                RH.I_Status ,
