        FROM    T_Receipt_Header RH
                LEFT JOIN T_Status_Master SM ON SM.I_Status_Value = RH.I_Receipt_Type
                INNER JOIN T_Student_Detail SD ON RH.I_Student_Detail_ID = SD.I_Student_Detail_ID
