        --        'Conversion Collection' AS Category ,
        --        SUM(T1.NValue) AS Value
        --FROM    #temp T1
        --INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID=T1.I_FeeComponent_ID
        --WHERE TFCM.S_Type_Of_Component='M'
        --AND T1.I_Instalment_No=1 AND T1.I_Course_ID IN (519,520,11,12) 
        --AND (T1.I_Center_ID IN (19,18) 
        --AND T1.I_Center_ID IN (SELECT FGCFR.centerID FROM dbo.fnGetCentersForReports(@sHierarchyListID,@iBrandID) AS FGCFR))
        ----WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        --GROUP BY T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name
        --UNION ALL
        --SELECT  T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name ,
        --        'MTF Collection From Lumpsum' AS Category ,
        --        SUM(T1.NValue) AS Value
        --FROM    #temp T1
        --INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID=T1.I_FeeComponent_ID
        --WHERE TFCM.S_Type_Of_Component='M' AND T1.TypeofPayment='Y' --AND T1.I_Instalment_No=1
        ----WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        --GROUP BY T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name                
        UNION ALL
        SELECT  T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name ,
                'MTF Collection (Dues)' AS Category ,
                SUM(T1.NValue) AS Value
        FROM    #temp T1
                INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
        WHERE   TFCM.S_Type_Of_Component = 'M' AND TFCM.I_Fee_Component_ID NOT IN(3,29,89)
                AND T1.InstalmentDate <= DATEADD(d, -DAY(@dtStartDate),
                                                 @dtStartDate)
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        GROUP BY T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name
        UNION ALL
        SELECT  T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name ,
                'MTF Collection (Current)' AS Category ,
                SUM(T1.NValue) AS Value
        FROM    #temp T1
                INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
        WHERE   TFCM.S_Type_Of_Component = 'M' AND TFCM.I_Fee_Component_ID NOT IN(3,29,89)
                AND ( T1.InstalmentDate >= DATEADD(d, -DAY(@dtStartDate) + 1,
                                                   @dtStartDate)
                      AND T1.InstalmentDate < DATEADD(d,
                                                      -DAY(DATEADD(m, 1,
                                                              @dtEndDate)) + 1,
                                                      DATEADD(m, 1, @dtEndDate))
                    )
        GROUP BY T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name
        UNION ALL
        SELECT  T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name ,
                'MTF Collection (Advance)' AS Category ,
                SUM(T1.NValue) AS Value
        FROM    #temp T1
                INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
        WHERE   TFCM.S_Type_Of_Component = 'M' AND TFCM.I_Fee_Component_ID NOT IN(3,29,89)
                AND T1.InstalmentDate >= DATEADD(d,
                                                 -DAY(DATEADD(m, 1, @dtEndDate))
                                                 + 1,
                                                 DATEADD(m, 1, @dtEndDate))
        GROUP BY T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name
                        UNION ALL
        SELECT  T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name ,
                'Re-Admission Fee Collection' AS Category ,
                SUM(T1.NValue) AS Value
        FROM    #temp T1
                INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
        WHERE   TFCM.S_Type_Of_Component = 'M' AND TFCM.I_Fee_Component_ID IN(3,29,89)
        GROUP BY T1.I_Center_ID ,
                T1.S_Center_Name ,
                T1.MonthYear ,
                T1.I_Course_ID ,
                T1.S_Course_Name
        UNION ALL
        SELECT  TCHND.I_Center_ID ,
                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                     THEN TCHND.S_Center_Name + ' (Franchise)'
                     ELSE TCHND.S_Center_Name + ' (Own)'
                END AS S_Center_Name ,
                DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) AS MonthYear ,
                TCM.I_Course_ID ,
                TCM.S_Course_Name ,
                'Sale of Diary (OnAcc)' AS Category ,
                SUM(ISNULL(TRH.N_Receipt_Amount,0.00)) AS Value
        FROM    dbo.T_Receipt_Header TRH
                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TRH.I_Centre_Id = TCHND.I_Center_ID
                INNER JOIN dbo.T_Student_Detail AS TSD ON TSD.I_Student_Detail_ID = TRH.I_Student_Detail_ID
                INNER JOIN dbo.T_Enquiry_Regn_Detail AS TERD ON TERD.I_Enquiry_Regn_ID = TSD.I_Enquiry_Regn_ID
                INNER JOIN ( SELECT TSBD.I_Student_ID ,
                                    MAX(TSBD.I_Student_Batch_ID) AS MinBatchID
                             FROM   dbo.T_Student_Batch_Details TSBD
                             GROUP BY TSBD.I_Student_ID
                           ) TSBD1 ON TSD.I_Student_Detail_ID = TSBD1.I_Student_ID
                INNER JOIN dbo.T_Student_Batch_Details TSBD2 ON TSBD1.I_Student_ID = TSBD2.I_Student_ID
                                                              AND TSBD2.I_Student_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD1.MinBatchID = TSBD2.I_Student_Batch_ID
                INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD2.I_Batch_ID = TSBM.I_Batch_ID
                INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
        WHERE   TRH.I_Status = 1
                AND TCHND.I_Center_ID IN (
                SELECT  FGCFR.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                   @iBrandID) FGCFR )
                AND TRH.I_Receipt_Type IN ( 96, 99 )
                AND TRH.Dt_Crtd_On >= @dtStartDate
                AND TRH.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                --AND TISM.I_Info_Source_ID != 3
        GROUP BY TCHND.I_Center_ID ,
                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                     THEN TCHND.S_Center_Name + ' (Franchise)'
                     ELSE TCHND.S_Center_Name + ' (Own)'
                END ,
                DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) ,
                TCM.I_Course_ID ,
                TCM.S_Course_Name
        UNION ALL
        SELECT  TCHND.I_Center_ID ,
                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                     THEN TCHND.S_Center_Name + ' (Franchise)'
                     ELSE TCHND.S_Center_Name + ' (Own)'
                END AS S_Center_Name ,
                DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) AS MonthYear ,
                TCM.I_Course_ID ,
                TCM.S_Course_Name ,
                'Security Deposit (OnAcc)' AS Category ,
                SUM(ISNULL(TRH.N_Receipt_Amount,0.00)) AS Value
        FROM    dbo.T_Receipt_Header TRH
                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TRH.I_Centre_Id = TCHND.I_Center_ID
                INNER JOIN dbo.T_Student_Detail AS TSD ON TSD.I_Student_Detail_ID = TRH.I_Student_Detail_ID
                INNER JOIN dbo.T_Enquiry_Regn_Detail AS TERD ON TERD.I_Enquiry_Regn_ID = TSD.I_Enquiry_Regn_ID
                INNER JOIN ( SELECT TSBD.I_Student_ID ,
                                    MAX(TSBD.I_Student_Batch_ID) AS MinBatchID
                             FROM   dbo.T_Student_Batch_Details TSBD
                             GROUP BY TSBD.I_Student_ID
                           ) TSBD1 ON TSD.I_Student_Detail_ID = TSBD1.I_Student_ID
                INNER JOIN dbo.T_Student_Batch_Details TSBD2 ON TSBD1.I_Student_ID = TSBD2.I_Student_ID
                                                              AND TSBD2.I_Student_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD1.MinBatchID = TSBD2.I_Student_Batch_ID
                INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD2.I_Batch_ID = TSBM.I_Batch_ID
                INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
        WHERE   TRH.I_Status = 1
                AND TCHND.I_Center_ID IN (
                SELECT  FGCFR.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                   @iBrandID) FGCFR )
                AND TRH.I_Receipt_Type IN ( 100, 101 )
                AND TRH.Dt_Crtd_On >= @dtStartDate
                AND TRH.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                --AND TISM.I_Info_Source_ID != 3
        GROUP BY TCHND.I_Center_ID ,
                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                     THEN TCHND.S_Center_Name + ' (Franchise)'
                     ELSE TCHND.S_Center_Name + ' (Own)'
                END ,
                DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) ,
                TCM.I_Course_ID ,
                TCM.S_Course_Name                      
        
        
        
      
	
    END
GO
