                            CAST(trh.Dt_Crtd_On AS DATE) Dt_Crtd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No = 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Crtd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No = 1
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Crtd_On = t.MonthDate 
		
        UPDATE  T
        SET     T.AdmissionFeesWithoutTax = T.AdmissionFeesWithoutTax
                - C.AdmissionFeesWithoutTax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRCD.N_Amount_Paid, 0)) AdmissionFeesWithoutTax ,
                            b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE) Dt_Upd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No = 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Upd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND trh.I_Status = 0
                            AND ticd.I_Installment_No = 1
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Upd_On = t.MonthDate 
		
        UPDATE  T
        SET     T.AdmissionFeesTax = C.AdmissionFeesTax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRTD.N_Tax_Paid, 0)) AdmissionFeesTax ,
                            b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE) Dt_Crtd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No = 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD WITH ( NOLOCK ) ON trcd.I_Receipt_Comp_Detail_ID = TRTD.I_Receipt_Comp_Detail_ID
                            AND trcd.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Crtd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No = 1
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Crtd_On = t.MonthDate 
		
        UPDATE  T
        SET     T.AdmissionFeesTax = T.AdmissionFeesTax - C.AdmissionFeesTax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRTD.N_Tax_Paid, 0)) AdmissionFeesTax ,
                            b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE) Dt_Upd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No = 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD WITH ( NOLOCK ) ON trcd.I_Receipt_Comp_Detail_ID = TRTD.I_Receipt_Comp_Detail_ID
                            AND trcd.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Upd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No = 1
                            AND trh.I_Status = 0
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Upd_On = t.MonthDate 
		
-- MonthlyFees
  
		
        UPDATE  T
        SET     T.MonthlyFeeswithouttax = C.MonthlyFeeswithouttax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRCD.N_Amount_Paid, 0)) MonthlyFeeswithouttax ,
                            b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE) Dt_Crtd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No <> 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Crtd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No <> 1
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Crtd_On = t.MonthDate 
		
        UPDATE  T
        SET     T.MonthlyFeeswithouttax = T.MonthlyFeeswithouttax
                - C.MonthlyFeeswithouttax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRCD.N_Amount_Paid, 0)) MonthlyFeeswithouttax ,
                            b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE) Dt_Upd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No <> 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Upd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No <> 1
                            AND trh.I_Status = 0
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Upd_On = t.MonthDate
		
        UPDATE  T
        SET     T.MonthlyFeestax = C.MonthlyFeestax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRTD.N_Tax_Paid, 0)) MonthlyFeestax ,
                            b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE) Dt_Crtd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No <> 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD WITH ( NOLOCK ) ON trcd.I_Receipt_Comp_Detail_ID = TRTD.I_Receipt_Comp_Detail_ID
                            AND trcd.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Crtd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No <> 1
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Crtd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Crtd_On = t.MonthDate 
		
        UPDATE  T
        SET     T.MonthlyFeestax = T.MonthlyFeestax - C.MonthlyFeestax
        FROM    @DailyCollection AS T ,
                ( SELECT    SUM(ISNULL(TRTD.N_Tax_Paid, 0)) MonthlyFeestax ,
                            b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE) Dt_Upd_On
                  FROM      dbo.T_Invoice_Parent AS tip
                            INNER JOIN dbo.T_Invoice_Child_Header AS tich ON tip.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Receipt_Header AS trh ON TIP.I_Invoice_Header_ID = trh.I_Invoice_Header_ID
                            INNER JOIN T_Invoice_Child_Detail TICD WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                                              AND TICD.I_Installment_No <> 1
                            INNER JOIN t_receipt_component_detail TRCD WITH ( NOLOCK ) ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND trh.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                            INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD WITH ( NOLOCK ) ON trcd.I_Receipt_Comp_Detail_ID = TRTD.I_Receipt_Comp_Detail_ID
                            AND trcd.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                            INNER JOIN @DailyCollection b ON tip.I_Centre_Id = b.centreId
                                                             AND CAST(trh.Dt_Upd_On AS DATE) = b.MonthDate
                  WHERE     I_Course_ID IN ( 11, 12, 13 )
                            AND tich.C_Is_LumpSum <> 'Y'
                            AND ticd.I_Installment_No <> 1
                            AND trh.I_Status = 0
                            AND tip.N_Invoice_Amount > 0
                  GROUP BY  b.centreId ,
                            CAST(trh.Dt_Upd_On AS DATE)
                ) AS C
        WHERE   c.centreId = T.centreId
                AND C.Dt_Upd_On = t.MonthDate 
		
	
        UPDATE  @DailyCollection
        SET     TotalCollectionWithoutTax = ISNULL(LumpsumFeesWithoutTax, 0)
                + ISNULL(AdmissionFeesWithoutTax, 0)
                + ISNULL(MonthlyFeeswithouttax, 0)
                + ISNULL(counseling_fees,0)
                + ISNULL(prospectus_fees,0)
                + ISNULL(other_onaccount_fees,0)
                - ISNULL(onaccount_tax,0)
											
        UPDATE  @DailyCollection
        SET     TotalCollectionTax = ISNULL(LumpsumFeesTax, 0)
                + ISNULL(AdmissionFeesTax, 0) + ISNULL(MonthlyFeestax, 0) + ISNULL(onaccount_tax, 0)
											
        UPDATE  @DailyCollection
        SET     TotalCollection = ISNULL(LumpsumFeesWithoutTax, 0)
                + ISNULL(LumpsumFeesTax, 0) + ISNULL(AdmissionFeesWithoutTax,0)
                + ISNULL(AdmissionFeesTax, 0) + ISNULL(MonthlyFeeswithouttax,0)
                + ISNULL(MonthlyFeestax, 0) + ISNULL(counseling_fees,0)
                + ISNULL(prospectus_fees,0) + ISNULL(other_onaccount_fees,0)

        SELECT  *
        FROM    @DailyCollection A 
        ORDER BY id

    END TRY

    BEGIN CATCH
	
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT

        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()

        RAISERROR(@ErrMsg, @ErrSeverity, 1)
    END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetDailyAcademicReport]...';


GO
CREATE PROCEDURE [REPORT].[uspGetDailyAcademicReport]
    (
      @iBrandID INT ,
      @sHierarchyIDList VARCHAR(MAX) ,
      @dtStartDate DATE ,
      @dtEndDate DATE ,
      @sBatchID VARCHAR(MAX) = NULL
    )
AS 
    BEGIN

        IF ( @sBatchID IS NULL ) 
            BEGIN

                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        T1.I_Batch_ID ,
                        T1.S_Batch_Name ,
                        T1.BatchStrength ,
                        T2.AllottedClass ,
                        T3.TotalAttendance ,
                        T4.AllottedHW ,
                        T5.TotalHWSubmission ,
                        CAST(( ( CAST(T3.TotalAttendance AS DECIMAL(14, 2))
                                 / ( CAST(T1.BatchStrength AS DECIMAL(14, 2))
                                     * CAST(T2.AllottedClass AS DECIMAL(14, 2)) ) )
                               * 100 ) AS DECIMAL(14, 2)) AS AttendancePercentage ,
                        CAST(( ( CAST(T5.TotalHWSubmission AS DECIMAL(14, 2))
                                 / ( CAST(T1.BatchStrength AS DECIMAL(14, 2))
                                     * CAST(T4.AllottedHW AS DECIMAL(14, 2)) ) )
                               * 100 ) AS DECIMAL(14, 2)) AS HWSubmissionPercentage
                FROM    ( SELECT    TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TCM.I_Course_ID ,
                                    TCM.S_Course_Name ,
                                    TSBM.I_Batch_ID ,
                                    TSBM.S_Batch_Name ,
                                    COUNT(DISTINCT TSD.S_Student_ID) AS BatchStrength
                          FROM      dbo.T_Student_Detail TSD
                                    INNER JOIN dbo.T_Student_Batch_Details TSBD
                                    WITH ( NOLOCK ) ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                                    INNER JOIN dbo.T_Student_Batch_Master TSBM
                                    WITH ( NOLOCK ) ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                                    INNER JOIN dbo.T_Center_Batch_Details TCBD
                                    WITH ( NOLOCK ) ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND
                                    WITH ( NOLOCK ) ON TCBD.I_Centre_Id = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Course_Master TCM WITH ( NOLOCK ) ON TSBM.I_Course_ID = TCM.I_Course_ID
                                    INNER JOIN ( SELECT TSSDA.I_Student_Detail_ID
                                                 FROM   dbo.T_Student_Status_Details_Archive TSSDA
                                                        WITH ( NOLOCK )
                                                 WHERE  I_Student_Status_ID = 1
                                                        AND I_Status = 1 AND CONVERT(DATE,TSSDA.Dt_Crtd_On)=CONVERT(DATE,@dtEndDate)
                                               ) TTT ON TSD.I_Student_Detail_ID = TTT.I_Student_Detail_ID
                          WHERE     TSBD.I_Status = 1
                                    AND TCHND.I_Center_ID IN (
                                    SELECT  FGCFR.centerID
                                    FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                          GROUP BY  TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TCM.I_Course_ID ,
                                    TCM.S_Course_Name ,
                                    TSBM.I_Batch_ID ,
                                    TSBM.S_Batch_Name
                        ) T1
                        LEFT JOIN ( SELECT  TTTM.I_Batch_ID ,
                                            COUNT(DISTINCT TTTM.I_TimeTable_ID) AS AllottedClass
                                    FROM    dbo.T_TimeTable_Master TTTM WITH ( NOLOCK )
                                    WHERE   TTTM.I_Status = 1
                                            AND ( TTTM.Dt_Schedule_Date >= @dtStartDate
                                                  AND TTTM.Dt_Schedule_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                )
                                            AND TTTM.I_Center_ID IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                    GROUP BY TTTM.I_Batch_ID
                                  ) T2 ON T1.I_Batch_ID = T2.I_Batch_ID
                        LEFT JOIN ( SELECT  TT.I_Batch_ID ,
                                            SUM(TT.TotalAttendance) AS TotalAttendance
                                    FROM    ( SELECT    TTTM.I_Batch_ID ,
                                                        TTTM.I_TimeTable_ID ,
                                                        COUNT(DISTINCT TSA.I_Student_Detail_ID) AS TotalAttendance
                                              FROM      dbo.T_TimeTable_Master TTTM
                                                        WITH ( NOLOCK )
                                                        INNER JOIN dbo.T_Student_Attendance TSA
                                                        WITH ( NOLOCK ) ON TTTM.I_TimeTable_ID = TSA.I_TimeTable_ID
                                                        INNER JOIN dbo.T_Student_Batch_Details TSBD2
                                                        WITH ( NOLOCK ) ON TTTM.I_Batch_ID = TSBD2.I_Batch_ID
                                                              AND TSBD2.I_Student_ID = TSA.I_Student_Detail_ID
                                              WHERE     TTTM.I_Status = 1
                                                        AND ( TTTM.Dt_Schedule_Date >= @dtStartDate
                                                              AND TTTM.Dt_Schedule_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                            )
                                                        AND TTTM.I_Center_ID IN (
                                                        SELECT
                                                              FGCFR.centerID
                                                        FROM  dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                                        AND TSBD2.I_Status = 1
                                              GROUP BY  TTTM.I_Batch_ID ,
                                                        TTTM.I_TimeTable_ID
                                            ) TT
                                    GROUP BY TT.I_Batch_ID
                                  ) T3 ON T1.I_Batch_ID = T3.I_Batch_ID
                        LEFT JOIN ( SELECT  THM.I_Batch_ID ,
                                            COUNT(DISTINCT THM.I_Homework_ID) AS AllottedHW
                                    FROM    EXAMINATION.T_Homework_Master THM
                                            WITH ( NOLOCK )
                                    WHERE   THM.I_Status = 1
                                            AND ( THM.Dt_Submission_Date >= @dtStartDate
                                                  AND THM.Dt_Submission_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                )
                                            AND THM.I_Center_ID IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                    GROUP BY THM.I_Batch_ID
                                  ) T4 ON T1.I_Batch_ID = T4.I_Batch_ID
                        LEFT JOIN ( SELECT  THM.I_Batch_ID ,
                                            COUNT(THS.I_Student_Detail_ID) AS TotalHWSubmission
                                    FROM    EXAMINATION.T_Homework_Master THM
                                            WITH ( NOLOCK )
                                            INNER JOIN EXAMINATION.T_Homework_Submission THS
                                            WITH ( NOLOCK ) ON THM.I_Homework_ID = THS.I_Homework_ID
                                            INNER JOIN dbo.T_Student_Batch_Details TSBD3
                                            WITH ( NOLOCK ) ON THS.I_Student_Detail_ID = TSBD3.I_Student_ID
                                                              AND THM.I_Batch_ID = TSBD3.I_Batch_ID
                                    WHERE   THM.I_Status = 1
                                            AND ( THM.Dt_Submission_Date >= @dtStartDate
                                                  AND THM.Dt_Submission_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                )
                                            AND THM.I_Center_ID IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                            AND TSBD3.I_Status = 1
                                    GROUP BY THM.I_Batch_ID
                                  ) T5 ON T1.I_Batch_ID = T5.I_Batch_ID
                  
            END
                  
        ELSE 
            BEGIN
                  
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        T1.I_Batch_ID ,
                        T1.S_Batch_Name ,
                        T1.BatchStrength ,
                        T2.AllottedClass ,
                        T3.TotalAttendance ,
                        T4.AllottedHW ,
                        T5.TotalHWSubmission ,
                        CAST(( ( CAST(T3.TotalAttendance AS DECIMAL(14, 2))
                                 / ( CAST(T1.BatchStrength AS DECIMAL(14, 2))
                                     * CAST(T2.AllottedClass AS DECIMAL(14, 2)) ) )
                               * 100 ) AS DECIMAL(14, 2)) AS AttendancePercentage ,
                        CAST(( ( CAST(T5.TotalHWSubmission AS DECIMAL(14, 2))
                                 / ( CAST(T1.BatchStrength AS DECIMAL(14, 2))
                                     * CAST(T4.AllottedHW AS DECIMAL(14, 2)) ) )
                               * 100 ) AS DECIMAL(14, 2)) AS HWSubmissionPercentage
                FROM    ( SELECT    TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TCM.I_Course_ID ,
                                    TCM.S_Course_Name ,
                                    TSBM.I_Batch_ID ,
                                    TSBM.S_Batch_Name ,
                                    COUNT(DISTINCT TSD.S_Student_ID) AS BatchStrength
                          FROM      dbo.T_Student_Detail TSD
                                    INNER JOIN dbo.T_Student_Batch_Details TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                                    INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                                    INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                                    INNER JOIN ( SELECT TSSD.I_Student_Detail_ID
                                                 FROM   dbo.T_Student_Status_Details_Archive TSSD
                                                        WITH ( NOLOCK )
                                                 WHERE  I_Student_Status_ID = 1
                                                        AND I_Status = 1 AND CONVERT(DATE,TSSD.Dt_Crtd_On)=CONVERT(DATE,@dtEndDate)
                                               ) TTT ON TSD.I_Student_Detail_ID = TTT.I_Student_Detail_ID
                          WHERE     TSBD.I_Status = 1
                                    AND TSBD.I_Batch_ID IN (
                                    SELECT  CAST(FSR.Val AS INT)
                                    FROM    dbo.fnString2Rows(@sBatchID, ',') FSR )
                                    AND TCHND.I_Center_ID IN (
                                    SELECT  FGCFR.centerID
                                    FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                          GROUP BY  TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TCM.I_Course_ID ,
                                    TCM.S_Course_Name ,
                                    TSBM.I_Batch_ID ,
                                    TSBM.S_Batch_Name
                        ) T1
                        LEFT JOIN ( SELECT  TTTM.I_Batch_ID ,
                                            COUNT(DISTINCT TTTM.I_TimeTable_ID) AS AllottedClass
                                    FROM    dbo.T_TimeTable_Master TTTM
                                    WHERE   TTTM.I_Status = 1
                                            AND ( TTTM.Dt_Schedule_Date >= @dtStartDate
                                                  AND TTTM.Dt_Schedule_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                )
                                            AND TTTM.I_Center_ID IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                    GROUP BY TTTM.I_Batch_ID
                                  ) T2 ON T1.I_Batch_ID = T2.I_Batch_ID
                        LEFT JOIN ( SELECT  TT.I_Batch_ID ,
                                            SUM(TT.TotalAttendance) AS TotalAttendance
                                    FROM    ( SELECT    TTTM.I_Batch_ID ,
                                                        TTTM.I_TimeTable_ID ,
                                                        COUNT(DISTINCT TSA.I_Student_Detail_ID) AS TotalAttendance
                                              FROM      dbo.T_TimeTable_Master TTTM
                                                        WITH ( NOLOCK )
                                                        INNER JOIN dbo.T_Student_Attendance TSA
                                                        WITH ( NOLOCK ) ON TTTM.I_TimeTable_ID = TSA.I_TimeTable_ID
                                                        INNER JOIN dbo.T_Student_Batch_Details TSBD2
                                                        WITH ( NOLOCK ) ON TTTM.I_Batch_ID = TSBD2.I_Batch_ID
                                                              AND TSBD2.I_Student_ID = TSA.I_Student_Detail_ID
                                              WHERE     TTTM.I_Status = 1
                                                        AND ( TTTM.Dt_Schedule_Date >= @dtStartDate
                                                              AND TTTM.Dt_Schedule_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                            )
                                                        AND TTTM.I_Center_ID IN (
                                                        SELECT
                                                              FGCFR.centerID
                                                        FROM  dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                                        AND TSBD2.I_Status = 1
                                              GROUP BY  TTTM.I_Batch_ID ,
                                                        TTTM.I_TimeTable_ID
                                            ) TT
                                    GROUP BY TT.I_Batch_ID
                                  ) T3 ON T1.I_Batch_ID = T3.I_Batch_ID
                        LEFT JOIN ( SELECT  THM.I_Batch_ID ,
                                            COUNT(DISTINCT THM.I_Homework_ID) AS AllottedHW
                                    FROM    EXAMINATION.T_Homework_Master THM
                                    WHERE   THM.I_Status = 1
                                            AND ( THM.Dt_Submission_Date >= @dtStartDate
                                                  AND THM.Dt_Submission_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                )
                                            AND THM.I_Center_ID IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                    GROUP BY THM.I_Batch_ID
                                  ) T4 ON T1.I_Batch_ID = T4.I_Batch_ID
                        LEFT JOIN ( SELECT  THM.I_Batch_ID ,
                                            COUNT(THS.I_Student_Detail_ID) AS TotalHWSubmission
                                    FROM    EXAMINATION.T_Homework_Master THM
                                            INNER JOIN EXAMINATION.T_Homework_Submission THS ON THM.I_Homework_ID = THS.I_Homework_ID
                                            INNER JOIN dbo.T_Student_Batch_Details TSBD ON THS.I_Student_Detail_ID = TSBD.I_Student_ID
                                                              AND THM.I_Batch_ID = TSBD.I_Batch_ID
                                    WHERE   THM.I_Status = 1
                                            AND ( THM.Dt_Submission_Date >= @dtStartDate
                                                  AND THM.Dt_Submission_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                )
                                            AND THM.I_Center_ID IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyIDList,
                                                              @iBrandID) FGCFR )
                                            AND TSBD.I_Status = 1
                                    GROUP BY THM.I_Batch_ID
                                  ) T5 ON T1.I_Batch_ID = T5.I_Batch_ID
                  	
            END
                  
    END
GO
