 AND (DATEDIFF(DD,TSD.Dt_Crtd_On,@dtStartDate) <= 0 AND DATEDIFF(DD,@dtEndDate,TSD.Dt_Crtd_On) <= 0)
 GROUP BY A.I_CENTRE_ID,TC.CourseID,B.YEAR,B.MONTH 
 ) AS Z  
 ON P.I_CENTRE_ID = Z.CID  
 AND P.I_Course_ID = [Z].CourseID  
 AND P.MONTH = Z.M  
 AND P.YEAR = Z.Y
