 --UPDATE @EEBCANALYSIS SET TOTAL_REGISTRATION = ISNULL(Z.CNT,0)  
 --FROM @EEBCANALYSIS P INNER JOIN  
 --(  
 --SELECT A.I_CENTRE_ID CID,TC.CourseID,TB.BatchID,COUNT(DISTINCT SRD.I_ENQUIRY_REGN_ID) CNT  
 --FROM @EEBCINITIAL A  
