CREATE PROCEDURE [REPORT].[uspGetEnquiryLabelsReport]      
(          
 -- Add the parameters for the stored procedure here          
 @sHierarchyList varchar(MAX),          
 @iBrandID INT,          
 @sCourseIDs VARCHAR(MAX),          
-- @iEnquiryID INT =NULL,          
 @sEnquiryID VARCHAR(MAX)=NULL,        
 @dtFromDate DATETIME = NULL,          
 @dtToDate DATETIME = NULL,          
 @sSourceIDs VARCHAR(MAX),          
 @sEnquiryTypeIDs VARCHAR(MAX),        
 @dtFollowupFromDate DATETIME=NULL,        
 @dtFollowupToDate  DATETIME=NULL,        
 @sEnquiryStatus VARCHAR(MAX)        
)          
AS          
BEGIN          
 SET NOCOUNT ON;          
           
 DECLARE @Enquiry TABLE          
  (          
   I_Enquiry_Regn_ID INT,          
   S_Title VARCHAR(10),          
   S_First_Name VARCHAR(50),          
   S_Middle_Name Varchar(50),          
   S_Last_Name Varchar(50),          
   S_Curr_Address1 Varchar(200),          
   S_Curr_Address2 Varchar(200),          
   S_Curr_Area Varchar(50),          
   S_City_Name Varchar(200),          
   S_Phone_No Varchar(20),          
   S_Mobile_No Varchar(20),         
   CenterCode varchar(200),         
   CenterName Varchar(200),          
   InstanceChain varchar(200),        
   S_Course_Name Varchar(250),        
   S_Enquiry_Type_Desc varchar(200),        
   S_Info_Source_Name varchar(200),        
   S_Enquiry_No varchar(20),        
   S_Email_ID varchar(200),        
   I_Enquiry_Status_Code int,        
   Dt_Crtd_On datetime,        
   Dt_Followup_Date datetime,        
   I_Feedback_Count int,        
   S_Comment varchar(Max)        
  )           
 IF @sCourseIDs Is NOT null          
  BEGIN          
  INSERT INTO @Enquiry        
  (          
   I_Enquiry_Regn_ID ,          
   S_Title ,          
   S_First_Name,          
   S_Middle_Name ,          
   S_Last_Name ,          
   S_Curr_Address1 ,          
   S_Curr_Address2,          
   S_Curr_Area,          
   S_City_Name ,          
   S_Phone_No,          
   S_Mobile_No ,         
   CenterCode ,         
   CenterName ,          
   InstanceChain ,        
   S_Course_Name ,        
   S_Enquiry_Type_Desc,        
   S_Info_Source_Name,        
   S_Enquiry_No,        
   S_Email_ID,        
   I_Enquiry_Status_Code ,        
   Dt_Crtd_On      
  )           
    SELECT DISTINCT A.I_Enquiry_Regn_ID,          
     A.S_Title,          
     A.S_First_Name,          
     A.S_Middle_Name,          
     A.S_Last_Name,          
     A.S_Curr_Address1,          
     A.S_Curr_Address2,          
     A.S_Curr_Area,          
     B.S_City_Name,          
     A.S_Phone_No,          
     A.S_Mobile_No,          
     FN1.CenterCode,          
     FN1.CenterName,          
     FN2.InstanceChain,          
     [TCM].[S_Course_Name],          
     ISNULL(ET.S_Enquiry_Type_Desc,''),          
     ISNULL(ISM.S_Info_Source_Name,''),          
     A.S_Enquiry_No,          
     A.S_Email_ID,        
     A.I_Enquiry_Status_Code,        
     A.Dt_Crtd_On         
      FROM T_Enquiry_Regn_Detail A WITH(NOLOCK)          
     INNER JOIN T_City_Master B WITH(NOLOCK)          
     ON A.I_Curr_City_ID = B.I_City_ID          
     INNER JOIN T_Enquiry_Course C WITH(NOLOCK)          
     ON A.I_Enquiry_Regn_ID = C.I_Enquiry_Regn_ID          
     INNER JOIN [dbo].[T_Course_Master] AS TCM WITH(NOLOCK)          
     ON [C].[I_Course_ID] = [TCM].[I_Course_ID]          
     INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1          
     ON A.I_Centre_Id=FN1.CenterID          
     INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2          
     ON FN1.HierarchyDetailID=FN2.HierarchyDetailID          
     LEFT JOIN DBO.T_Enquiry_Type ET ON A.I_Enquiry_Type_ID=ET.I_Enquiry_Type_ID          
     LEFT JOIN DBO.T_Information_Source_Master ISM ON A.I_Info_Source_ID=ISM.I_Info_Source_ID          
     INNER JOIN dbo.T_Enquiry_Regn_Followup AS TERF ON A.I_Enquiry_Regn_ID=TERF.I_Enquiry_Regn_ID        
    WHERE  A.I_Enquiry_Status_Code =1 --Open Enquiry Only          
     AND 
     B.I_Status<> 0          
    AND C.I_Course_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sCourseIDs, ',') AS FSR)          
    --AND A.I_Enquiry_Regn_ID=ISNULL(@iEnquiryID,A.I_Enquiry_Regn_ID)          
    AND(@sEnquiryID IS NULL OR A.I_Enquiry_Regn_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sEnquiryID, ',') AS FSR) )       
    AND DATEDIFF(dd,[A].[Dt_Crtd_On],ISNULL(@dtFromDate,[A].[Dt_Crtd_On])) <= 0          
    AND DATEDIFF(dd,[A].[Dt_Crtd_On],ISNULL(@dtToDate,[A].[Dt_Crtd_On])) >= 0          
    AND DATEDIFF(dd,[TERF].[Dt_Followup_Date],ISNULL(@dtFollowupFromDate,[TERF].[Dt_Followup_Date])) <= 0          
    AND DATEDIFF(dd,[TERF].[Dt_Followup_Date],ISNULL(@dtFollowupToDate,[TERF].[Dt_Followup_Date])) >= 0          
    AND I_Corporate_ID IS NULL          
    AND [A].[I_Enquiry_Regn_ID] NOT IN (          
    SELECT [TERD].[I_Enquiry_Regn_ID] FROM [dbo].[T_Enquiry_Regn_Detail] AS TERD          
    INNER JOIN [dbo].[T_Student_Detail] AS TSD          
    ON [TERD].[I_Enquiry_Regn_ID] = [TSD].[I_Enquiry_Regn_ID]          
    WHERE [TSD].[I_Student_Detail_ID] IN           
    (SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM))          
    AND (a.I_Enquiry_Type_ID IS NULL OR a.I_Enquiry_Type_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sEnquiryTypeIDs, ',') AS FSR))  
    AND (a.I_Info_Source_ID IS NULL OR a.I_Info_Source_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sSourceIDs, ',') AS FSR))          
    AND A.I_Enquiry_Status_Code IN (SELECT Val FROM [dbo].[fnString2Rows](@sEnquiryStatus, ',') AS FSR)          
   END          
  ELSE          
   BEGIN          
   INSERT INTO @Enquiry        
  (          
   I_Enquiry_Regn_ID ,          
   S_Title ,          
   S_First_Name,          
   S_Middle_Name ,          
   S_Last_Name ,          
   S_Curr_Address1 ,          
   S_Curr_Address2,          
   S_Curr_Area,          
   S_City_Name ,          
   S_Phone_No,          
   S_Mobile_No ,         
   CenterCode ,         
   CenterName ,          
   InstanceChain ,        
   S_Course_Name ,        
   S_Enquiry_Type_Desc,        
   S_Info_Source_Name,        
   S_Enquiry_No,        
   S_Email_ID,        
   I_Enquiry_Status_Code ,        
   Dt_Crtd_On      
  )           
    SELECT DISTINCT A.I_Enquiry_Regn_ID,          
     A.S_Title,          
     A.S_First_Name,          
     A.S_Middle_Name,          
     A.S_Last_Name,          
     A.S_Curr_Address1,          
     A.S_Curr_Address2,          
     A.S_Curr_Area,          
     B.S_City_Name,          
     A.S_Phone_No,          
     A.S_Mobile_No,          
     FN1.CenterCode,          
     FN1.CenterName,          
     FN2.InstanceChain,          
     [TCM].[S_Course_Name],          
     ISNULL(ET.S_Enquiry_Type_Desc,''),          
     ISNULL(ISM.S_Info_Source_Name,''),          
     A.S_Enquiry_No,          
     A.S_Email_ID,        
     A.I_Enquiry_Status_Code,        
     A.Dt_Crtd_On          
      FROM T_Enquiry_Regn_Detail A WITH(NOLOCK)          
     INNER JOIN T_City_Master B WITH(NOLOCK)          
     ON A.I_Curr_City_ID = B.I_City_ID          
     INNER JOIN T_Enquiry_Course C WITH(NOLOCK)          
     ON A.I_Enquiry_Regn_ID = C.I_Enquiry_Regn_ID          
     INNER JOIN [dbo].[T_Course_Master] AS TCM WITH(NOLOCK)          
     ON [C].[I_Course_ID] = [TCM].[I_Course_ID]          
     INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1          
     ON A.I_Centre_Id=FN1.CenterID          
     INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2          
     ON FN1.HierarchyDetailID=FN2.HierarchyDetailID          
     LEFT JOIN DBO.T_Enquiry_Type ET ON A.I_Enquiry_Type_ID=ET.I_Enquiry_Type_ID          
     LEFT JOIN DBO.T_Information_Source_Master ISM ON A.I_Info_Source_ID=ISM.I_Info_Source_ID          
     INNER JOIN dbo.T_Enquiry_Regn_Followup AS TERF ON A.I_Enquiry_Regn_ID=TERF.I_Enquiry_Regn_ID        
    WHERE A.I_Enquiry_Status_Code =1 --Open Enquiry Only          
     AND
     B.I_Status<>0          
    --AND A.I_Enquiry_Regn_ID=ISNULL(@iEnquiryID,A.I_Enquiry_Regn_ID)         
    AND(@sEnquiryID IS NULL OR A.I_Enquiry_Regn_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sEnquiryID, ',') AS FSR))           
    AND DATEDIFF(dd,[A].[Dt_Crtd_On],ISNULL(@dtFromDate,[A].[Dt_Crtd_On])) <= 0          
    AND DATEDIFF(dd,[A].[Dt_Crtd_On],ISNULL(@dtToDate,[A].[Dt_Crtd_On])) >= 0          
    AND DATEDIFF(dd,[TERF].[Dt_Followup_Date],ISNULL(@dtFollowupFromDate,[TERF].[Dt_Followup_Date])) <= 0          
    AND DATEDIFF(dd,[TERF].[Dt_Followup_Date],ISNULL(@dtFollowupToDate,[TERF].[Dt_Followup_Date])) >= 0          
    AND I_Corporate_ID IS NULL          
    AND [A].[I_Enquiry_Regn_ID] NOT IN (          
    SELECT [TERD].[I_Enquiry_Regn_ID] FROM [dbo].[T_Enquiry_Regn_Detail] AS TERD          
    INNER JOIN [dbo].[T_Student_Detail] AS TSD          
    ON [TERD].[I_Enquiry_Regn_ID] = [TSD].[I_Enquiry_Regn_ID]          
    WHERE [TSD].[I_Student_Detail_ID] IN           
    (SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM))          
    AND (a.I_Enquiry_Type_ID  IS NULL OR a.I_Enquiry_Type_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sEnquiryTypeIDs, ',') AS FSR)    )      
    AND (a.I_Enquiry_Type_ID  IS NULL OR a.I_Info_Source_ID IN (SELECT Val FROM [dbo].[fnString2Rows](@sSourceIDs, ',') AS FSR)        )  
    AND A.I_Enquiry_Status_Code IN (SELECT Val FROM [dbo].[fnString2Rows](@sEnquiryStatus, ',') AS FSR)         
         
   END          
            
   UPDATE @Enquiry SET I_Feedback_Count = FCount        
   FROM @Enquiry AS E        
   INNER JOIN         
   (SELECT I_Enquiry_Regn_ID,COUNT(I_Followup_ID)AS FCount FROM dbo.T_Enquiry_Regn_Followup AS TERF WHERE         
   DATEDIFF(dd,[TERF].[Dt_Followup_Date],ISNULL(@dtFollowupFromDate,[TERF].[Dt_Followup_Date])) <= 0          
   AND DATEDIFF(dd,[TERF].[Dt_Followup_Date],ISNULL(@dtFollowupToDate,[TERF].[Dt_Followup_Date])) >= 0  GROUP BY I_Enquiry_Regn_ID)AS Followup        
   ON E.I_Enquiry_Regn_ID = Followup.I_Enquiry_Regn_ID        
         
   UPDATE @Enquiry SET S_Comment = FComment      
   FROM @Enquiry AS E        
   INNER JOIN        
   (SELECT  STUFF(( SELECT  ',' + S_Followup_Remarks      
                        FROM    T_Enquiry_Regn_Followup      
                        WHERE   I_Enquiry_Regn_ID = Enquiry.I_Enquiry_Regn_ID AND       
                        DATEDIFF(dd,[Dt_Followup_Date],ISNULL(@dtFollowupFromDate,Dt_Followup_Date)) <= 0          
      AND DATEDIFF(dd,Dt_Followup_Date,ISNULL(@dtFollowupToDate,Dt_Followup_Date)) >= 0       
                      FOR      
                        XML PATH('')      
                      ), 1, 1, '') AS FComment ,I_Enquiry_Regn_ID      
          
    FROM @Enquiry AS Enquiry      
    GROUP BY Enquiry.I_Enquiry_Regn_ID ) AS Comment ON E.I_Enquiry_Regn_ID=Comment.I_Enquiry_Regn_ID      
          
    UPDATE @Enquiry SET Dt_Followup_Date = SUBSTRING(FDate+',',1,(CHARINDEX(',',FDate+',',1)-1))      
    FROM  @Enquiry AS E       
   INNER JOIN        
   (SELECT  STUFF(( SELECT  ',' + CAST (Dt_Followup_Date AS VARCHAR(23) )      
                        FROM    T_Enquiry_Regn_Followup      
                        WHERE   I_Enquiry_Regn_ID = Enquiry.I_Enquiry_Regn_ID      
                        AND DATEDIFF(dd,[Dt_Followup_Date],ISNULL(@dtFollowupFromDate,Dt_Followup_Date)) <= 0          
      AND DATEDIFF(dd,Dt_Followup_Date,ISNULL(@dtFollowupToDate,Dt_Followup_Date)) >= 0       
                        ORDER BY Dt_Followup_Date desc      
                      FOR      
                        XML PATH('')      
                      ), 1, 1, '') AS FDate ,I_Enquiry_Regn_ID      
          
    FROM @Enquiry AS Enquiry      
    GROUP BY Enquiry.I_Enquiry_Regn_ID ) AS Comment ON E.I_Enquiry_Regn_ID=Comment.I_Enquiry_Regn_ID      
          
          
   SELECT * FROM @Enquiry            
END       
      
      
--EXEC report.uspGetEnquiryLabelsReport  1,2,NULL,null,NULL,NULL,'88,4,97','3,4',NULL,NULL,'1,2,3' 
GO
PRINT N'Creating Procedure [REPORT].[uspGetEnquiryFollowupReport]...';


GO
CREATE PROCEDURE [REPORT].[uspGetEnquiryFollowupReport]
    (
      @sHierarchyID VARCHAR(MAX) ,
      @StartDate DATE ,
      @EndDate DATE ,
      @iBrandID INT ,
      @iFlag INT
    )
AS
    BEGIN

        IF ( @iFlag = 0 )
            BEGIN
                SELECT  T1.* ,
                        CONVERT(DATE, T2.Dt_Receipt_Date) AS FormSaleDate,
                        ISNULL(T3.AmtCollected,0) AS AmountCollected
                FROM    ( SELECT    TCHND.I_Brand_ID ,
                                    TCHND.S_Brand_Name ,
                                    TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TUM.S_First_Name + ' '
                                    + ISNULL(TUM.S_Middle_Name, '') + ' '
                                    + TUM.S_Last_Name AS CouncellorName ,
                                    TERD.S_First_Name + ' '
                                    + ISNULL(TERD.S_Middle_Name, '') + ' '
                                    + TERD.S_Last_Name AS StudentName ,
                                    COALESCE(TERD.S_Mobile_No, TERD.S_Phone_No,
                                             TERD.S_Guardian_Mobile_No, '') AS ContactNo ,
                                    TERD.S_Father_Name,
                                    TERD.S_Mother_Name,         
                                    '`'+TERD.S_Curr_Address1 AS CurrAddress ,
                                    TERD.S_Curr_Pincode AS Pincode ,
                                    TERD.I_Enquiry_Regn_ID AS PreEnquiry ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code IS NOT NULL
                                         THEN TERD.I_Enquiry_Regn_ID
                                         ELSE NULL
                                    END AS Enquiry ,
                                    CASE WHEN TERD.S_Form_No IS NOT NULL
                                         THEN TERD.S_Form_No
                                         ELSE NULL
                                    END AS FormSale ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code = 3
                                         THEN TSD.S_Student_ID
                                         ELSE NULL
                                    END AS Admission ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code=1 OR TERD.I_Enquiry_Status_Code=3 THEN  CONVERT(DATE, ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) END AS EnquiryDate ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code=1 OR TERD.I_Enquiry_Status_Code=3 THEN DATENAME(MONTH,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On))+' '+CAST(DATEPART(YYYY,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) AS VARCHAR) END AS  EnqMonthYear,
                                    CONVERT(DATE, TSD.Dt_Crtd_On) AS DateofAdmission ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code IS NULL THEN CONVERT(DATE,TERD.Dt_Crtd_On) ELSE CONVERT(DATE, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) END AS PreEnquiryDate,
                                    CASE WHEN TERD.I_Enquiry_Status_Code IS NULL THEN DATENAME(MONTH,CONVERT(DATE,ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)))+' '+CAST(DATEPART(YYYY,CONVERT(DATE,ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On))) AS VARCHAR)
                                    --ELSE DATENAME(MONTH,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On))+' '+CAST(DATEPART(YYYY,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) AS VARCHAR) 
                                    END AS PreEnqMonthYear,
                                    CASE WHEN TERD.I_Relevence_ID = 0
                                         THEN 'Not Relevent'
                                         WHEN TERD.I_Relevence_ID = 1
                                         THEN 'Relevent'
                                    END AS Relevence ,
                                    TISM.S_Info_Source_Name ,
                                    TCM.S_Course_Name AS EnquiryCourse ,
                                    CASE WHEN ISNULL(TBR.Dt_Booking_Date,
                                                     '1990-01-01') = ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                         THEN 'NO'
                                         WHEN ISNULL(TBR.Dt_Booking_Date,
                                                     '1990-01-01') <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                         THEN 'YES'
                                         ELSE 'NO'
                                    END AS IsPartPaymentAdmission ,
                                    CAST(DATEPART(dd,
                                                  TBR.Dt_Reg_Conversion_Date) AS VARCHAR)
                                    + '/'
                                    + CAST(TBR.Dt_Reg_Conversion_Date AS CHAR(3))
                                    + '/'
                                    + CAST(DATEPART(YYYY,
                                                    TBR.Dt_Reg_Conversion_Date) AS VARCHAR) FullPaymentMadeOn,
                                    ED.S_Education_CurrentStatus_Description,
									TEEAD.MobileNo as ExtMobileNo,
									TEEAD.EmailID as ExtEmailID,
									TEEAD.InfoCampaign,
									TEEAD.InfoMedium,
									TEEAD.InfoSource,
									TEEAD.LeadCreatedBy,
									TEEAD.Counsellor,
									TEEAD.UserRegistrationDate,
									TEEAD.Origin,
									TEEAD.PrimaryTrafficChannel,
									TEEAD.PrimaryTrafficChannel+'/'+TEEAD.InfoSource+'/'+TEEAD.InfoMedium+'/'+TEEAD.InfoCampaign as InfoSourceMediumCampaign,
									TEEAD.SalesDisposition,
									TEEAD.DateofMaturitySales,
									TUS.S_Sex_Name
                          FROM      dbo.T_Enquiry_Regn_Detail TERD WITH (NOLOCK)
                                    INNER JOIN dbo.T_User_Master TUM WITH (NOLOCK) ON ISNULL(TERD.Enquiry_Crtd_By,TERD.S_Crtd_By) = TUM.S_Login_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND WITH (NOLOCK) ON TERD.I_Centre_Id = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Enquiry_Course TEC WITH (NOLOCK) ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                                    INNER JOIN dbo.T_Course_Master TCM WITH (NOLOCK) ON TEC.I_Course_ID = TCM.I_Course_ID
                                    LEFT JOIN dbo.T_Information_Source_Master TISM WITH (NOLOCK) ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                                    LEFT JOIN dbo.T_Student_Detail TSD WITH (NOLOCK) ON TERD.I_Enquiry_Regn_ID = TSD.I_Enquiry_Regn_ID
                                    LEFT JOIN dbo.T_Booking_Record TBR WITH (NOLOCK) ON TSD.I_Student_Detail_ID = TBR.I_Student_Detail_ID
									Left join T_Enquiry_External_Additional_Details TEEAD WITH (NOLOCK) on TERD.I_Enquiry_Regn_ID=TEEAD.PreEnquiryID
									LEFT JOIN T_User_Sex TUS WITH (NOLOCK) on TERD.I_Sex_ID=TUS.I_Sex_ID
                                    LEFT JOIN 
                                    (
                                    SELECT TEECS.I_Enquiry_Regn_ID,TECS.S_Education_CurrentStatus_Description 
									FROM dbo.T_Enquiry_Education_CurrentStatus AS TEECS WITH (NOLOCK)
                                    INNER JOIN dbo.T_Education_CurrentStatus AS TECS WITH (NOLOCK) ON TECS.I_Education_CurrentStatus_ID = TEECS.I_Education_CurrentStatus_ID
                                    ) ED ON ED.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                          WHERE     ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On) >= @StartDate
                                    AND ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On) < DATEADD(d, 1,
                                                              @EndDate)
                                    AND TCHND.I_Center_ID IN (
                                    SELECT  centerID
                                    FROM    dbo.fnGetCentersForReports(@sHierarchyID,
                                                              @iBrandID) FGCFR )
                        ) T1
                        LEFT JOIN ( SELECT  TRH.I_Enquiry_Regn_ID ,
                                            TRH.Dt_Receipt_Date
                                    FROM    dbo.T_Receipt_Header TRH WITH (NOLOCK)
                                    WHERE   I_Receipt_Type IN ( 31, 32, 50, 51,
                                                              57, 85 )
                                            AND I_Status = 1
                                  ) T2 ON T1.PreEnquiry = T2.I_Enquiry_Regn_ID
                        LEFT JOIN ( SELECT  TSD2.I_Enquiry_Regn_ID ,
                                            SUM(ISNULL(TRH2.N_Receipt_Amount,
                                                       0)
                                                + ISNULL(TRH2.N_Tax_Amount, 0)) AS AmtCollected
                                    FROM    dbo.T_Receipt_Header AS TRH2 WITH (NOLOCK)
                                            INNER JOIN dbo.T_Student_Detail AS TSD2 WITH (NOLOCK) ON TSD2.I_Student_Detail_ID = TRH2.I_Student_Detail_ID
                                    WHERE   TRH2.I_Invoice_Header_ID IS NOT NULL
                                            AND TRH2.I_Status = 1
                                            AND TRH2.Dt_Crtd_On < DATEADD(d, 1,
                                                              @EndDate)
                                    GROUP BY TSD2.I_Enquiry_Regn_ID                          
                                  ) T3 ON T1.PreEnquiry = T3.I_Enquiry_Regn_ID
                ORDER BY T1.I_Brand_ID ,
                        T1.I_Center_ID ,
                        T1.PreEnquiry

				OPTION (RECOMPILE)
            END
        ELSE
            BEGIN
                SELECT  T1.* ,
                        CONVERT(DATE, T2.Dt_Receipt_Date) AS FormSaleDate,
                        ISNULL(T3.AmtCollected,0) AS AmountCollected
                FROM    ( SELECT    TCHND.I_Brand_ID ,
                                    TCHND.S_Brand_Name ,
                                    TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TUM.S_First_Name + ' '
                                    + ISNULL(TUM.S_Middle_Name, '') + ' '
                                    + TUM.S_Last_Name AS CouncellorName ,
                                    TERD.S_First_Name + ' '
                                    + ISNULL(TERD.S_Middle_Name, '') + ' '
                                    + TERD.S_Last_Name AS StudentName ,
                                    COALESCE(TERD.S_Mobile_No, TERD.S_Phone_No,
                                             TERD.S_Guardian_Mobile_No, '') AS ContactNo ,
                                    TERD.S_Father_Name,
                                    TERD.S_Mother_Name,         
                                    TERD.S_Curr_Address1 AS CurrAddress ,
                                    TERD.S_Curr_Pincode AS Pincode ,
                                    TERD.I_Enquiry_Regn_ID AS PreEnquiry ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code IS NOT NULL
                                         THEN TERD.I_Enquiry_Regn_ID
                                         ELSE NULL
                                    END AS Enquiry ,
                                    CASE WHEN TERD.S_Form_No IS NOT NULL
                                         THEN TERD.S_Form_No
                                         ELSE NULL
                                    END AS FormSale ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code = 3
                                         THEN TSD.S_Student_ID
                                         ELSE NULL
                                    END AS Admission ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code=1 OR TERD.I_Enquiry_Status_Code=3 THEN  CONVERT(DATE, ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) END AS EnquiryDate ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code=1 OR TERD.I_Enquiry_Status_Code=3 THEN DATENAME(MONTH,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On))+' '+CAST(DATEPART(YYYY,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) AS VARCHAR) END AS  EnqMonthYear,
                                    CONVERT(DATE, TSD.Dt_Crtd_On) AS DateofAdmission ,
                                    CASE WHEN TERD.I_Enquiry_Status_Code IS NULL THEN CONVERT(DATE,ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) --ELSE CONVERT(DATE, ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) 
                                    END AS PreEnquiryDate,
                                    CASE WHEN TERD.I_Enquiry_Status_Code IS NULL THEN DATENAME(MONTH,CONVERT(DATE,ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)))+' '+CAST(DATEPART(YYYY,CONVERT(DATE,ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On))) AS VARCHAR)
                                    --ELSE DATENAME(MONTH,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On))+' '+CAST(DATEPART(YYYY,ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On)) AS VARCHAR) 
                                    END AS PreEnqMonthYear,
                                    CASE WHEN TERD.I_Relevence_ID = 0
                                         THEN 'Not Relevent'
                                         WHEN TERD.I_Relevence_ID = 1
                                         THEN 'Relevent'
                                    END AS Relevence ,
                                    TISM.S_Info_Source_Name ,
                                    TCM.S_Course_Name AS EnquiryCourse ,
                                    CASE WHEN ISNULL(TBR.Dt_Booking_Date,
                                                     '1990-01-01') = ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                         THEN 'NO'
                                         WHEN ISNULL(TBR.Dt_Booking_Date,
                                                     '1990-01-01') <> ISNULL(TBR.Dt_Reg_Conversion_Date,
                                                              '1990-01-01')
                                         THEN 'YES'
                                         ELSE 'NO'
                                    END AS IsPartPaymentAdmission ,
                                    CAST(DATEPART(dd,
                                                  TBR.Dt_Reg_Conversion_Date) AS VARCHAR)
                                    + '/'
                                    + CAST(TBR.Dt_Reg_Conversion_Date AS CHAR(3))
                                    + '/'
                                    + CAST(DATEPART(YYYY,
                                                    TBR.Dt_Reg_Conversion_Date) AS VARCHAR) FullPaymentMadeOn,
                                    ED.S_Education_CurrentStatus_Description,
									TEEAD.MobileNo as ExtMobileNo,
									TEEAD.EmailID as ExtEmailID,
									TEEAD.InfoCampaign,
									TEEAD.InfoMedium,
									TEEAD.InfoSource,
									TEEAD.LeadCreatedBy,
									TEEAD.Counsellor,
									TEEAD.UserRegistrationDate,
									TEEAD.Origin,
									TEEAD.PrimaryTrafficChannel,
									TEEAD.PrimaryTrafficChannel+'/'+TEEAD.InfoSource+'/'+TEEAD.InfoMedium+'/'+TEEAD.InfoCampaign as InfoSourceMediumCampaign,
									TEEAD.SalesDisposition,
									TEEAD.DateofMaturitySales,
									TUS.S_Sex_Name
                          FROM      dbo.T_Enquiry_Regn_Detail TERD
                                    INNER JOIN dbo.T_User_Master TUM ON ISNULL(TERD.Enquiry_Crtd_By,TERD.S_Crtd_By) = TUM.S_Login_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TERD.I_Centre_Id = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Enquiry_Course TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                                    INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                                    LEFT JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                                    LEFT JOIN dbo.T_Student_Detail TSD ON TERD.I_Enquiry_Regn_ID = TSD.I_Enquiry_Regn_ID
                                    LEFT JOIN dbo.T_Booking_Record TBR ON TSD.I_Student_Detail_ID = TBR.I_Student_Detail_ID
									Left join T_Enquiry_External_Additional_Details TEEAD on TERD.I_Enquiry_Regn_ID=TEEAD.PreEnquiryID
									LEFT JOIN T_User_Sex TUS on TERD.I_Sex_ID=TUS.I_Sex_ID
                                    LEFT JOIN 
                                    (
                                    SELECT TEECS.I_Enquiry_Regn_ID,TECS.S_Education_CurrentStatus_Description FROM dbo.T_Enquiry_Education_CurrentStatus AS TEECS
                                    INNER JOIN dbo.T_Education_CurrentStatus AS TECS ON TECS.I_Education_CurrentStatus_ID = TEECS.I_Education_CurrentStatus_ID
                                    ) ED ON ED.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                          WHERE     ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On) >= @StartDate
                                    AND ISNULL(TERD.Enquiry_Date,TERD.Dt_Crtd_On) < DATEADD(d, 1,
                                                              @EndDate)
                                    AND TCHND.I_Center_ID IN (
                                    SELECT  centerID
                                    FROM    dbo.fnGetCentersForReports(@sHierarchyID,
                                                              @iBrandID) FGCFR )
                                    AND TERD.I_Relevence_ID = 1
                                    AND ( TERD.I_Enquiry_Status_Code IS NULL
                                          OR TERD.I_Enquiry_Status_Code = 1
                                        )
                        ) T1
                        LEFT JOIN ( SELECT  TRH.I_Enquiry_Regn_ID ,
                                            TRH.Dt_Receipt_Date
                                    FROM    dbo.T_Receipt_Header TRH
                                    WHERE   I_Receipt_Type IN ( 31, 32, 50, 51,
                                                              57, 85 )
                                            AND I_Status = 1
                                  ) T2 ON T1.PreEnquiry = T2.I_Enquiry_Regn_ID
                        LEFT JOIN ( SELECT  TSD2.I_Enquiry_Regn_ID ,
                                            SUM(ISNULL(TRH2.N_Receipt_Amount,
                                                       0)
                                                + ISNULL(TRH2.N_Tax_Amount, 0)) AS AmtCollected
                                    FROM    dbo.T_Receipt_Header AS TRH2
                                            INNER JOIN dbo.T_Student_Detail AS TSD2 ON TSD2.I_Student_Detail_ID = TRH2.I_Student_Detail_ID
                                    WHERE   TRH2.I_Invoice_Header_ID IS NOT NULL
                                            AND TRH2.I_Status = 1
                                            AND TRH2.Dt_Crtd_On < DATEADD(d, 1,
                                                              @EndDate)
                                    GROUP BY TSD2.I_Enquiry_Regn_ID                          
                                  ) T3 ON T1.PreEnquiry = T3.I_Enquiry_Regn_ID
                ORDER BY T1.I_Brand_ID ,
                        T1.I_Center_ID ,
                        T1.PreEnquiry

				OPTION (RECOMPILE)

            END

			
        
    END
GO
