CREATE PROCEDURE [REPORT].[uspGetFeeAccrualReport]
    (
      -- Add the parameters for the stored procedure here
      @sHierarchyList VARCHAR(MAX) ,
      @iBrandID INT ,
      @dtFromDate DATETIME ,
      @dtToDate DATETIME
    )
AS 
    BEGIN

        SET NOCOUNT ON ;

        SELECT  B.I_Invoice_Child_Header_ID ,
                S_Student_ID ,
                E.I_RollNo ,
                E.S_First_Name + ' ' + ISNULL(S_Middle_Name, '') + ' '
                + S_Last_Name AS S_Student_Name ,
                A.S_Invoice_No ,
                A.Dt_Invoice_Date ,
                S_Component_Name ,
                tsbm.S_Batch_Name ,
                tcm.S_Course_Name ,
                tcm2.S_Center_Name ,
                S_Brand_Name ,
                S_Cost_Center ,
                C.N_Amount_Due ,
                Dt_Installment_Date ,
                I_Installment_No ,
                A.I_Parent_Invoice_ID ,
                C.I_Invoice_Detail_ID ,
                CASE WHEN I_Parent_Invoice_ID IS NULL THEN NULL
                     ELSE A.Dt_Crtd_On
                END AS Revised_Invoice_Date,
                FN2.instanceChain
        FROM    T_Invoice_Parent A
                INNER JOIN T_Invoice_Child_Header B ON A.I_Invoice_Header_ID = B.I_Invoice_Header_ID
                                                       AND A.I_Status IN (1,3)
                INNER JOIN T_Invoice_Child_Detail C ON C.I_Invoice_Child_Header_ID = B.I_Invoice_Child_Header_ID
                INNER JOIN T_Fee_Component_Master D ON D.I_Fee_Component_ID = C.I_Fee_Component_ID
                                                       AND D.I_Status = 1
                INNER JOIN T_Student_Detail E ON E.I_Student_Detail_ID = A.I_Student_Detail_ID
                INNER JOIN dbo.T_Centre_Master AS tcm2 ON A.I_Centre_Id = tcm2.I_Centre_Id
                INNER JOIN dbo.T_Brand_Center_Details AS tbcd ON tcm2.I_Centre_Id = tbcd.I_Centre_Id
                INNER JOIN dbo.T_Brand_Master AS tbm ON tbcd.I_Brand_ID = tbm.I_Brand_ID
                INNER JOIN dbo.T_Student_Batch_Details AS tsbd ON tsbd.I_Student_ID = a.I_Student_Detail_ID
                                                              AND tsbd.I_Status = 1
                INNER JOIN dbo.T_Student_Batch_Master AS tsbm ON tsbm.I_Batch_ID = tsbd.I_Batch_ID
                INNER JOIN dbo.T_Course_Master AS tcm ON tcm.I_Course_ID = tsbm.I_Course_ID
                INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON tcm2.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
        WHERE   A.I_Centre_Id IN (
                SELECT  fnCenter.centerID
                FROM    fnGetCentersForReports(@sHierarchyList, @iBrandID) fnCenter )
                AND DATEDIFF(dd, @dtFromDate, Dt_Installment_Date) >= 0
                AND DATEDIFF(dd, @dtToDate, Dt_Installment_Date) <= 0
               -- AND I_Installment_No<>1
        GROUP BY B.I_Invoice_Child_Header_ID ,
                S_Student_ID ,
                E.I_RollNo ,
                A.S_Invoice_No ,
                A.Dt_Invoice_Date ,
                S_Component_Name ,
                C.N_Amount_Due ,
                Dt_Installment_Date ,
                I_Installment_No ,
                A.I_Parent_Invoice_ID ,
                A.Dt_Crtd_On ,
                C.I_Invoice_Detail_ID ,
                tsbm.S_Batch_Name ,
                tcm.S_Course_Name ,
                tcm2.S_Center_Name ,
                S_Brand_Name ,
                S_Cost_Center ,
                E.S_First_Name ,
                E.S_Middle_Name ,
                E.S_Last_Name,
                FN2.instanceChain
        ORDER BY S_Center_Name, S_Batch_Name, S_Student_ID
		
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetFacultyUtilizationSlotwise]...';


GO
/*CREATE TABLE #temp
(
sBranch VARCHAR(20),
sFaculty VARCHAR(100),
sSubject VARCHAR(50),
iBatchId INT,
sBatch VARCHAR(20),
iBatchStrength INT,
iAttn INT,
dtDate DATE,
sPeriod VARCHAR(50)
)

INSERT INTO #temp
        ( sBranch ,
          sFaculty ,
          sSubject ,
          iBatchId,
          sBatch,
          sPeriod,
          dtDate 
        )
        */
CREATE PROCEDURE [REPORT].[uspGetFacultyUtilizationSlotwise]
    @iBrandID INT ,
    @sHierarchyListID VARCHAR(MAX) ,
    @dtStartDate DATE ,
    @dtEndDate DATE ,
    @iEmployeeID INT=NULL
AS 
    BEGIN
    
                SELECT  xx.sCenter ,
                        xx.TimeTable ,
                        xx.sFaculty ,
                        xx.sSub ,
                        xx.iBatch ,
                        xx.Batch ,
                        xx.sPeriod ,
                        xx.sDate ,
                        xx.BatchStr ,
                        COUNT(DISTINCT TSA.I_Student_Detail_ID) AS StdAttn
                FROM    ( SELECT    TT.Center AS sCenter ,
                                    TT.itTable AS TimeTable ,
                                    TT.Faculty AS sFaculty ,
                                    TT.Sub AS sSub ,
                                    TT.iBatchID AS iBatch ,
                                    TT.sBatch AS Batch ,
                                    TT.Period AS sPeriod ,
                                    TT.dtDate AS sDate ,
                                    COUNT(DISTINCT TSD.S_Student_ID) AS BatchStr
                          FROM      ( SELECT    TCHND.S_Center_Name AS Center ,
                                                TTTM.I_TimeTable_ID AS itTable ,
                                                TED.S_First_Name+' '+
                                                + ISNULL(TED.S_Middle_Name,
                                                         ' ')+' '+
                                                + TED.S_Last_Name AS Faculty ,
                                                TESM.S_Skill_Desc AS Sub ,
                                                TTTM.I_Batch_ID AS iBatchID ,
                                                TSBM.S_Batch_Name AS sBatch ,
                                                CAST(CAST(LEFT(CONVERT(TIME, TCTM.Dt_Start_Time),
                                                              5) AS VARCHAR)
                                                + '  to '
                                                + CAST(LEFT(CONVERT(TIME, TCTM.Dt_End_Time),
                                                            5) AS VARCHAR) AS VARCHAR) AS Period ,
                                                CONVERT(DATE, TTTM.Dt_Schedule_Date) AS dtDate
                                      FROM      dbo.T_Employee_Dtls TED
                                                INNER JOIN dbo.T_TimeTable_Faculty_Map TTTFM ON TED.I_Employee_ID = TTTFM.I_Employee_ID
                                                INNER JOIN dbo.T_TimeTable_Master TTTM ON TTTFM.I_TimeTable_ID = TTTM.I_TimeTable_ID
                                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TTTM.I_Center_ID = TCHND.I_Center_ID
                                                INNER JOIN dbo.T_Session_Master TSM ON TTTM.I_Session_ID = TSM.I_Session_ID
                                                INNER JOIN dbo.T_EOS_Skill_Master TESM ON TSM.I_Skill_ID = TESM.I_Skill_ID
                                                INNER JOIN dbo.T_Center_Timeslot_Master TCTM ON TTTM.I_TimeSlot_ID = TCTM.I_TimeSlot_ID
                                                              AND TTTM.I_Center_ID = TCTM.I_Center_ID
                                                INNER JOIN dbo.T_Student_Batch_Master TSBM ON TTTM.I_Batch_ID = TSBM.I_Batch_ID
                                      WHERE     TTTFM.B_Is_Actual = 1
                                                AND TCHND.I_Brand_ID = @iBrandID
                                                AND TTTM.I_Center_ID IN (
                                                SELECT  fnCenter.centerID
                                                FROM    fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) fnCenter )
                                                AND TTTM.I_Status = 1
                                                AND TTTM.Dt_Schedule_Date >= @dtStartDate
                                                AND TTTM.Dt_Schedule_Date < DATEADD(d,
                                                              1, @dtEndDate)
                                                AND TED.I_Employee_ID = ISNULL(@iEmployeeID,TED.I_Employee_ID)
--ORDER BY CONVERT(DATE, TTTM.Dt_Schedule_Date) ,
--        TCHND.S_Center_Name ,
--        TED.S_First_Name + ISNULL(TED.S_Middle_Name, ' ') + TED.S_Last_Name
                                      
                                    ) TT
                                    INNER JOIN dbo.T_Student_Batch_Details TSBD ON TT.iBatchID = TSBD.I_Batch_ID
                                    INNER JOIN dbo.T_Student_Detail TSD ON TSBD.I_Student_ID = TSD.I_Student_Detail_ID
                          WHERE     TSBD.I_Status = 1
                                    AND TSD.I_Status = 1
                          GROUP BY  TT.Center ,
                                    TT.itTable ,
                                    TT.Faculty ,
                                    TT.Sub ,
                                    TT.iBatchID ,
                                    TT.sBatch ,
                                    TT.Period ,
                                    TT.dtDate
                        ) XX
                        INNER JOIN dbo.T_TimeTable_Master TTTM2 ON XX.iBatch = TTTM2.I_Batch_ID
                                                              AND xx.TimeTable = TTTM2.I_TimeTable_ID
                        INNER JOIN dbo.T_Student_Attendance TSA ON TTTM2.I_TimeTable_ID = TSA.I_TimeTable_ID
                WHERE   TTTM2.I_Status = 1
                GROUP BY xx.sCenter ,
                        xx.TimeTable ,
                        xx.sFaculty ,
                        xx.sSub ,
                        xx.iBatch ,
                        xx.Batch ,
                        xx.sPeriod ,
                        xx.sDate ,
                        xx.BatchStr
            
            
        
    END
        --SELECT * FROM #temp T;
        
        --DROP TABLE #temp;
GO
