GO
CREATE PROCEDURE [REPORT].[uspGetFinancialDefaultersDetailsReport]
(
	-- Add the parameters for the stored procedure here
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@dtUptoDate datetime
)
AS
BEGIN TRY

		DECLARE @dtUptoDate1 DATETIME
		SET @dtUptoDate1 = DATEADD(d,1,@dtUptoDate)


		 SELECT IP.I_Invoice_Header_ID,
				IP.I_Centre_Id,
				IP.I_Student_Detail_ID,
				SD.S_Student_ID,
				SD.S_Title,
				SD.S_First_Name,
				SD.S_Middle_Name,
				SD.S_Last_Name,
				IP.S_Invoice_No AS Invoice_No,
				IP.Dt_Invoice_Date AS Invoice_Date,
				ISNULL(IP.N_Invoice_Amount,0.00) AS Invoice_Amount,
				ISNULL(IP.N_Tax_Amount,0.00) AS Tax_Amount,
				ISNULL(IP.N_Discount_Amount,0.00) AS N_Discount_Amount,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain,
				CUM.S_Currency_Code,
				--SUM(ISNULL(RH.N_Receipt_Amount,0.00)) AS Receipt_Amount,
				(Select SUM(ISNULL(N_Receipt_Amount,0.00)) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=IP.I_Invoice_Header_ID AND I_Status <> 0)  AS Receipt_Amount,
				(ISNULL(IP.N_Invoice_Amount,0.00) 
				--- SUM(ISNULL(RH.N_Receipt_Amount,0.00))) AS Outstanding_Amt,
				-(Select ISNULL(SUM(ISNULL(N_Receipt_Amount,0.00)),0) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=IP.I_Invoice_Header_ID AND I_Status <> 0)) AS Outstanding_Amt,
				--MAX(RH.Dt_Receipt_Date) AS Last_Install_Date
				(Select MAX(Dt_Receipt_Date) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=IP.I_Invoice_Header_ID AND I_Status <> 0)  AS Last_Install_Date
		   INTO #TmpOutStandingRpt1
		   FROM ACADEMICS.T_Dropout_Details DD
				INNER JOIN dbo.T_Student_Detail SD
				ON DD.I_Student_Detail_ID = SD.I_Student_Detail_ID
				INNER JOIN dbo.T_Invoice_Parent IP
			    ON SD.I_Student_Detail_ID = IP.I_Student_Detail_ID
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON IP.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
				LEFT OUTER JOIN dbo.T_Receipt_Header RH
				ON IP.I_Invoice_Header_ID=RH.I_Invoice_Header_ID
				INNER JOIN dbo.T_Centre_Master CEM
				ON FN1.CenterID=CEM.I_Centre_Id
				INNER JOIN dbo.T_Country_Master COM
				ON CEM.I_Country_ID=COM.I_Country_ID
				INNER JOIN dbo.T_Currency_Master CUM
				ON COM.I_Currency_ID=CUM.I_Currency_ID
		  WHERE IP.Dt_Invoice_Date <= @dtUptoDate
			AND (RH.Dt_Receipt_Date <= @dtUptoDate OR RH.Dt_Receipt_Date IS NULL)
			AND SD.I_Status = 0
			AND DD.I_Dropout_Status = 1
			AND DD.I_Dropout_Type_ID = 2
			AND DD.Dt_Dropout_Date <= @dtUptoDate1
			AND	[SD].[I_Student_Detail_ID] NOT IN 
			(SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM)

	   GROUP BY IP.I_Invoice_Header_ID,
				IP.I_Centre_Id,
				IP.I_Student_Detail_ID,
				SD.S_Student_ID,
				SD.S_Title,
				SD.S_First_Name,
				SD.S_Middle_Name,
				SD.S_Last_Name,
				IP.S_Invoice_No,
				IP.Dt_Invoice_Date,
				IP.N_Invoice_Amount,
				IP.N_Tax_Amount,
				IP.N_Discount_Amount,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain,
				CUM.S_Currency_Code
				
--select * from #TmpOutStandingRpt1

		 SELECT TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--ICH.I_Course_ID,
				ICH.I_Invoice_Child_Header_ID,
				--CM.S_Course_Code AS Course_Code,
				--CM.S_Course_Name AS Course_Name,
				--SUM(ISNULL(RH.N_Receipt_Amount,0.00)) AS Last_Install_Amount,
				(Select SUM(ISNULL(N_Receipt_Amount,0.00)) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=TMP.I_Invoice_Header_ID AND I_Status <> 0 AND Dt_Receipt_Date=TMP.Last_Install_Date)  AS Last_Install_Amount,

				[REPORT].[fnGetStudentStatusForDefaulterReports](TMP.I_Student_Detail_ID,TMP.I_Centre_Id,@dtUptoDate1) AS Student_Status
		   INTO #TmpOutStandingRpt2
		   FROM #TmpOutStandingRpt1 TMP
				INNER JOIN dbo.T_Invoice_Child_Header ICH
				ON TMP.I_Invoice_Header_ID=ICH.I_Invoice_Header_ID
				--INNER JOIN dbo.T_Course_Master CM
				--ON ICH.I_Course_ID=CM.I_Course_ID		
				LEFT OUTER JOIN dbo.T_Receipt_Header RH
				ON TMP.I_Invoice_Header_ID=RH.I_Invoice_Header_ID
				AND TMP.Last_Install_Date=RH.Dt_Receipt_Date
		  WHERE [REPORT].[fnGetStudentStatusForDefaulterReports](TMP.I_Student_Detail_ID,TMP.I_Centre_Id,@dtUptoDate1) LIKE '%FINANCIAL%'
		    --AND TMP.Outstanding_Amt > 10
--		    AND RH.I_Status <> 0
	   GROUP BY TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--ICH.I_Course_ID,
				ICH.I_Invoice_Child_Header_ID--,
				--CM.S_Course_Code,
				--CM.S_Course_Name
				
		--Finding Last Date of the Month
		DECLARE @vOutputDate DATETIME
		SET @vOutputDate = CAST(YEAR(@dtUptoDate) AS VARCHAR(4)) + '/' + CAST(MONTH(@dtUptoDate) AS VARCHAR(2)) + '/01'
		SET @vOutputDate = DATEADD(DD, -1, DATEADD(M, 1, @vOutputDate))


		SELECT TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status,
				SUM(ISNULL(ICD.N_Amount_Due,0.00)) AS Amount_Due_LM
		INTO #TmpOutStandingRpt3
		FROM #TmpOutStandingRpt2 TMP
				INNER JOIN dbo.T_Invoice_Child_Detail ICD
				ON TMP.I_Invoice_Child_Header_ID = ICD.I_Invoice_Child_Header_ID
				--AND DATEPART(month,ICD.Dt_Installment_Date) <= DATEPART(month, @dtUptoDate)
				--AND DATEPART(year,ICD.Dt_Installment_Date) <= DATEPART(year, @dtUptoDate)
				AND ICD.Dt_Installment_Date <=  @vOutputDate
		GROUP BY TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status
				
		--Finding Last Date of the Next Month
		SET @dtUptoDate=DATEADD(month,1,@dtUptoDate)
		DECLARE @vOutputDate1 DATETIME
		SET @vOutputDate1 = CAST(YEAR(@dtUptoDate) AS VARCHAR(4)) + '/' + CAST(MONTH(@dtUptoDate) AS VARCHAR(2)) + '/01'
		SET @vOutputDate1= DATEADD(DD, -1, DATEADD(M, 1, @vOutputDate1))


	SELECT TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status,
				SUM(ISNULL(ICD.N_Amount_Due,0.00)) AS Amount_Due_CM
		INTO #TmpOutStandingRpt4
		FROM #TmpOutStandingRpt2 TMP
				INNER JOIN dbo.T_Invoice_Child_Detail ICD
				ON TMP.I_Invoice_Child_Header_ID = ICD.I_Invoice_Child_Header_ID
				--AND DATEPART(month,ICD.Dt_Installment_Date) <= DATEPART(month, (DATEADD(month,1,@dtUptoDate)))
				--AND DATEPART(year,ICD.Dt_Installment_Date) <= DATEPART(year, @dtUptoDate)
				AND ICD.Dt_Installment_Date <= @vOutputDate1
		GROUP BY TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status

	SELECT TMP1.I_Invoice_Header_ID,
				TMP1.I_Centre_Id,
				TMP1.I_Student_Detail_ID,
				TMP1.S_Student_ID,
				TMP1.S_Title,
				TMP1.S_First_Name,
				TMP1.S_Middle_Name,
				TMP1.S_Last_Name,
				TMP1.Invoice_No,
				TMP1.Invoice_Date,
				TMP1.Invoice_Amount,
				TMP1.Tax_Amount,
				TMP1.N_Discount_Amount,
				TMP1.CenterCode,
				TMP1.CenterName,
				TMP1.InstanceChain,
				TMP1.S_Currency_Code,
				TMP1.Receipt_Amount,
				FLOOR(TMP1.Outstanding_Amt) Outstanding_Amt,
				TMP1.Last_Install_Date,
				CM.I_Course_ID,
				CM.S_Course_Code AS Course_Code,
				CM.S_Course_Name AS Course_Name,
				TMP1.Last_Install_Amount,
				TMP1.Student_Status,
				TMP1.Amount_Due_LM,
				TMP2.Amount_Due_CM,
				tsbm.S_Batch_Name
		FROM #TmpOutStandingRpt3 TMP1
				INNER JOIN #TmpOutStandingRpt4 TMP2
				ON TMP1.I_Invoice_Header_ID = TMP2.I_Invoice_Header_ID
				AND TMP1.I_Centre_Id = TMP2.I_Centre_Id
				AND TMP1.I_Student_Detail_ID = TMP2.I_Student_Detail_ID
				INNER JOIN dbo.T_Student_Batch_Details AS tsbd ON tsbd.I_Student_ID = TMP1.I_Student_Detail_ID
				INNER JOIN dbo.T_Student_Batch_Master AS tsbm ON tsbm.I_Batch_ID = tsbd.I_Batch_ID			
				INNER JOIN dbo.T_COURSE_MASTER CM ON CM.I_Course_ID = tsbm.I_Course_ID
				INNER JOIN dbo.T_INVOICE_CHILD_HEADER ICH ON ICH.I_Course_ID = tsbm.I_Course_ID
				INNER JOIN dbo.T_INVOICE_PARENT IP ON IP.I_Invoice_Header_ID=ICH.I_Invoice_Header_ID
				AND IP.I_Invoice_Header_ID=TMP2.I_Invoice_Header_ID
		GROUP BY TMP1.I_Invoice_Header_ID,
				TMP1.I_Centre_Id,
				TMP1.I_Student_Detail_ID,
				TMP1.S_Student_ID,
				TMP1.S_Title,
				TMP1.S_First_Name,
				TMP1.S_Middle_Name,
				TMP1.S_Last_Name,
				TMP1.Invoice_No,
				TMP1.Invoice_Date,
				TMP1.Invoice_Amount,
				TMP1.Tax_Amount,
				TMP1.N_Discount_Amount,
				TMP1.CenterCode,
				TMP1.CenterName,
				TMP1.InstanceChain,
				TMP1.S_Currency_Code,
				TMP1.Receipt_Amount,
				TMP1.Outstanding_Amt,
				TMP1.Last_Install_Date,
				CM.I_Course_ID,
				CM.S_Course_Code,
				CM.S_Course_Name,
				TMP1.Last_Install_Amount,
				TMP1.Student_Status,
				TMP1.Amount_Due_LM,
				TMP2.Amount_Due_CM,
				tsbm.S_Batch_Name

	 DROP TABLE #TmpOutStandingRpt1
	 DROP TABLE #TmpOutStandingRpt2
	 DROP TABLE #TmpOutStandingRpt3
	 DROP TABLE #TmpOutStandingRpt4
	 
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetHomeWorkAttendanceTeacherWise]...';


GO


  
-- =============================================    
-- Author:  Shubhrangshu Nag    
-- Create date: 09/12/2013    
-- Description: To get HomeWork Attendance Report TeacherWise   
-- =============================================    
    
CREATE PROCEDURE [REPORT].[uspGetHomeWorkAttendanceTeacherWise] --'88',109,NULL,'2013-08-15','2013-09-11'  
(    
-- Add the parameters for the stored procedure here    
 @sHierarchyList varchar(MAX),  
    @iBrandID int,  
    @iEmployeeID INT  = NULL,  
 @FromDate DATETIME,    
 @ToDate  DATETIME      
)    
AS    
    
BEGIN TRY    
 BEGIN     
    
 -- SET NOCOUNT ON added to prevent extra result sets from    
 -- interfering with SELECT statements.    
 SET NOCOUNT ON;    
  
 Declare @temp table(S_Skill_Desc VARCHAR(100),I_Skill_ID INT,S_Batch_Name VARCHAR(100),I_Batch_ID INT,I_Employee_ID INT, EmpName VARCHAR(250),Prcnt90 INT, Prcnt9070 INT,Prcnt7050 INT,Prcnt50 INT,Prcnt0 INT)  
 Declare @temp1 table(S_Skill_Desc VARCHAR(100),I_Skill_ID INT,S_Batch_Name VARCHAR(100),I_Batch_ID INT,I_Employee_ID INT, EmpName VARCHAR(250),Prcnt90 INT, Prcnt9070 INT,Prcnt7050 INT,Prcnt50 INT)  
  
 Declare @Final table(S_Skill_Desc VARCHAR(100),I_Skill_ID INT,S_Batch_Name VARCHAR(100),I_Batch_ID INT,I_Employee_ID INT, EmpName VARCHAR(250),Prcnt90 INT, HWPrcnt90 INT, Prcnt9070 INT,HWPrcnt9070 INT,Prcnt7050 INT,HWPrcnt7050 INT,Prcnt50 INT,HWPrcnt50 INT,Prcnt0 INT)  
  
  
   
    
 INSERT INTO @temp (S_Skill_Desc ,I_Skill_ID,S_Batch_Name,I_Batch_ID ,I_Employee_ID , EmpName,Prcnt90 , Prcnt9070 ,Prcnt7050 ,Prcnt50,Prcnt0)  
 SELECT    
   S_Skill_Desc,  
   I_Skill_ID,  
 S_Batch_Name,  
 I_Batch_ID,  
 I_Employee_ID, EmpName,  
 SUM(PERCENTAGE90) Prcnt90,  
 SUM(PERCENTAGE9070) Prcnt9070,  
 SUM(PERCENTAGE7050) Prcnt7050,  
 SUM(PERCENTAGE50) Prcnt50,  
 (TotalStudentCount - SUM(PERCENTAGE90) - SUM(PERCENTAGE9070) - SUM(PERCENTAGE7050) - SUM(PERCENTAGE50)) Prcnt0   
  FROM  
  
(SELECT DISTINCT No_Atteded_Session, S_Student_ID ,   
   S_Skill_Desc,  
   I_Skill_ID,  
 S_Batch_Name,  
 I_Batch_ID,  
 I_Employee_ID, EmpName,  
 CASE   
 WHEN SessionCount = 0 THEN NULL  
      WHEN (CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) >=0.9 THEN 1   
      ELSE 0   
 END PERCENTAGE90,  
 CASE   
 WHEN SessionCount = 0 THEN NULL  
  WHEN (CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) >=0.7 AND (CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) < 0.9 THEN 1   
      ELSE 0   
 END PERCENTAGE9070   
 ,  
 CASE   
 WHEN SessionCount = 0 THEN NULL  
  WHEN (CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) >=0.5 AND (CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) < 0.7 THEN 1   
      ELSE 0   
 END PERCENTAGE7050,  
  
 CASE   
   WHEN SessionCount = 0 THEN NULL  
      WHEN (CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) < 0.5 THEN 1   
      ELSE 0   
 END  PERCENTAGE50   
      
  ,SessionCount  
  ,TotalStudentCount  
FROM  
 (SELECT   
  Count(DISTINCT SA.I_Attendance_Detail_ID) AS No_Atteded_Session,  
   SD.S_Student_ID ,  
   --TM.S_Session_Name ,  
   ESM.S_Skill_Desc,  
   ESM.I_Skill_ID,  
 TSBM.S_Batch_Name,  
 TSBM.I_Batch_ID,  
 TED.I_Employee_ID,TED.S_First_Name +' '+ ISNULL(TED.S_Middle_Name,'') +' '+ TED.S_Last_Name as EmpName,  
 dbo.[fnGetTotalStudentCount](TSBM.I_Batch_ID) TotalStudentCount ,  
 [dbo].[fnGetTotalSessionCountTeacherWise](TED.I_Employee_ID,TSBM.I_Batch_ID,SC.I_Centre_Id,ESM.I_Skill_ID,@FromDate,@ToDate) SessionCount   
 FROM dbo.T_Student_Detail SD    
 INNER JOIN dbo.T_Student_Batch_Details AS TSBD    
    ON SD.I_Student_Detail_ID = TSBD.I_Student_ID    
    AND TSBD.I_Status = 1    
    AND SD.I_Status = 1   
 INNER JOIN dbo.T_Student_Center_Detail SC    
    ON SC.I_Student_Detail_ID = TSBD.I_Student_ID    
    AND SC.I_Status = 1    
   INNER JOIN dbo.T_Center_Batch_Details AS TCBD  
   ON TSBD.I_Batch_ID = TCBD.I_Batch_ID  
   AND SC.I_Centre_Id = TCBD.I_Centre_Id  
   AND ISNULL(TCBD.I_Status,2) <> 5  
   INNER JOIN dbo.T_Student_Batch_Master AS TSBM  
   ON TCBD.I_Batch_ID = TSBM.I_Batch_ID   
   INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1    
   ON SC.I_Centre_Id=FN1.CenterID    
   INNER JOIN [dbo].[T_TimeTable_Master] TM  
   ON TM.I_Center_ID=FN1.CenterID    
   AND TM.I_Batch_ID=TSBM.I_Batch_ID   
   INNER JOIN [dbo].[T_TimeTable_Faculty_Map] TFM  
   ON TM.I_TimeTable_ID=TFM.I_TimeTable_ID   
   INNER JOIN [dbo].[T_Employee_Dtls] TED  
   ON TFM.I_Employee_ID=TED.I_Employee_ID   
   INNER JOIN dbo.T_Session_Master SM    
   ON SM.I_Session_ID=TM.I_Session_ID  
   INNER JOIN dbo.T_EOS_SKILL_MASTER ESM    
   ON ESM.I_Skill_ID=SM.I_Skill_ID  
   INNER JOIN  [dbo].[T_Student_Attendance] SA  
   ON SA.I_TimeTable_ID=TM.I_TimeTable_ID  
   AND SA.I_Student_Detail_ID=TSBD.[I_Student_ID]   
   WHERE  TM.Dt_Schedule_Date >= @FromDate  
 AND TM.Dt_Schedule_Date <= @ToDate  
 --AND TSBM.I_Batch_ID=497  
   AND TFM.I_Employee_ID=ISNULL(@iEmployeeID,TFM.I_Employee_ID)  
   GROUP BY  TED.I_Employee_ID,SD.S_Student_ID ,ESM.S_Skill_Desc ,ESM.I_Skill_ID,TSBM.S_Batch_Name,TSBM.I_Batch_ID,SC.I_Centre_Id,TED.S_First_Name ,TED.S_Middle_Name ,TED.S_Last_Name) a )b  
   GROUP BY I_Employee_ID, EmpName,S_Skill_Desc,I_Skill_ID,S_Batch_Name,I_Batch_ID,TotalStudentCount  
   ORDER BY I_Employee_ID  
  
  
INSERT INTO @temp1 (S_Skill_Desc ,I_Skill_ID,S_Batch_Name,I_Batch_ID ,I_Employee_ID , EmpName,Prcnt90 , Prcnt9070 ,Prcnt7050 ,Prcnt50)  
 SELECT    
 S_Skill_Desc,  
 I_Skill_ID,  
 S_Batch_Name,  
 I_Batch_ID,  
 I_Employee_ID, EmpName,  
 SUM(PERCENTAGE90) Prcnt90,  
 SUM(PERCENTAGE9070) Prcnt9070,  
 SUM(PERCENTAGE7050) Prcnt7050,  
 SUM(PERCENTAGE50) Prcnt50  
  FROM  
 (SELECT DISTINCT No_HW_Submission, S_Student_ID ,   
   S_Skill_Desc,  
   I_Skill_ID,  
 S_Batch_Name,  
 I_Batch_ID,  
 --(CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) fraction,  
 CASE   
 WHEN HomeWorkCount = 0 THEN NULL  
      WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) >=0.9 THEN 1   
      ELSE 0   
 END PERCENTAGE90,  
 CASE   
 WHEN HomeWorkCount = 0 THEN NULL  
  WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) >=0.7 AND (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) < 0.9 THEN 1   
      ELSE 0   
 END PERCENTAGE9070   
 ,  
 CASE   
 WHEN HomeWorkCount = 0 THEN NULL  
  WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) >=0.5 AND (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) < 0.7 THEN 1   
      ELSE 0   
 END PERCENTAGE7050,  
  
 CASE   
   WHEN HomeWorkCount = 0 THEN NULL  
      WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) < 0.5 THEN 1   
      ELSE 0   
 END  PERCENTAGE50   
  ,I_Employee_ID, EmpName    
  ,HomeWorkCount  
   
FROM  
 (SELECT      
 --COUNT( DISTINCT SD.S_Student_ID) as No_Atteded_Student,   
 Count(DISTINCT HS.I_Homework_Submission_ID) AS No_HW_Submission,  
  SD.S_Student_ID,  
   TSBM.S_Batch_Name,TSBM.I_Batch_ID,  
   TED.I_Employee_ID,TED.S_First_Name +' '+ ISNULL(TED.S_Middle_Name,'') +' '+ TED.S_Last_Name as EmpName,  
   --SM.S_Session_Name,  
 ESM.S_Skill_Desc,  
 ESM.I_Skill_ID,   
 [dbo].[fnGetTotalHomeWorkCountTeacherWise](TED.I_Employee_ID,TSBM.I_Batch_ID,SC.I_Centre_Id,ESM.I_Skill_ID,@FromDate,@ToDate) HomeWorkCount    
  FROM     
   dbo.T_Student_Detail SD    
   INNER JOIN dbo.T_Student_Batch_Details AS TSBD    
    ON SD.I_Student_Detail_ID = TSBD.I_Student_ID    
    AND TSBD.I_Status = 1    
    AND SD.I_Status = 1   
   INNER JOIN dbo.T_Student_Center_Detail SC    
    ON SC.I_Student_Detail_ID = TSBD.I_Student_ID    
    AND SC.I_Status = 1    
   INNER JOIN dbo.T_Center_Batch_Details AS TCBD  
   ON TSBD.I_Batch_ID = TCBD.I_Batch_ID  
   AND SC.I_Centre_Id = TCBD.I_Centre_Id  
   AND ISNULL(TCBD.I_Status,2) <> 5  
   INNER JOIN dbo.T_Student_Batch_Master AS TSBM  
   ON TCBD.I_Batch_ID = TSBM.I_Batch_ID   
   INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1    
   ON SC.I_Centre_Id=FN1.CenterID    
   INNER JOIN [EXAMINATION].[T_Homework_Submission] HS  
   ON HS.I_Student_Detail_ID=SD.I_Student_Detail_ID   
   INNER JOIN [EXAMINATION].[T_Homework_Master]  HM  
   ON HS.I_Homework_ID=HM.I_Homework_ID  
   INNER JOIN dbo.T_Session_Master SM    
   ON SM.I_Session_ID=HM.I_Session_ID  
   INNER JOIN dbo.T_EOS_SKILL_MASTER ESM    
   ON ESM.I_Skill_ID=SM.I_Skill_ID  
   INNER JOIN [dbo].[T_Employee_Dtls] TED  
   ON HS.I_Employee_ID=TED.I_Employee_ID   
   WHERE HM.Dt_Submission_Date>=@FromDate
 AND HM.Dt_Submission_Date <= @ToDate  
   AND HS.I_Employee_ID=ISNULL(@iEmployeeID,TED.I_Employee_ID)  
   GROUP BY  TED.I_Employee_ID,SD.S_Student_ID ,ESM.S_Skill_Desc ,ESM.I_Skill_ID,TSBM.S_Batch_Name,TSBM.I_Batch_ID,SC.I_Centre_Id,TED.S_First_Name ,TED.S_Middle_Name, TED.S_Last_Name) a) b  
   GROUP BY I_Employee_ID, EmpName,S_Skill_Desc,I_Skill_ID,S_Batch_Name,I_Batch_ID  
 ORDER BY I_Employee_ID  
  
  
  
  
 INSERT INTO @Final (S_Skill_Desc ,I_Skill_ID,S_Batch_Name,I_Batch_ID ,I_Employee_ID , EmpName,Prcnt90 , Prcnt9070 ,Prcnt7050 ,Prcnt50,Prcnt0)  
 SELECT * FROM @temp  
  
 UPDATE F  
 SET F.HWPrcnt90=T.Prcnt90,  
  F.HWPrcnt9070=T.Prcnt9070,  
  F.HWPrcnt7050=T.Prcnt7050,  
  F.HWPrcnt50=T.Prcnt50  
 FROM @Final F  
 INNER JOIN @temp1 T  
 ON F.I_Batch_ID=T.I_Batch_ID  
 AND F.I_Skill_ID=T.I_Skill_ID  
  
 SELECT * FROM @Final  
  
  
 END    
END TRY    
    
BEGIN CATCH    
     
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int    
    
 SELECT @ErrMsg = ERROR_MESSAGE(),    
   @ErrSeverity = ERROR_SEVERITY()    
    
 RAISERROR(@ErrMsg, @ErrSeverity, 1)    
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetHomeWorkAttendanceBatchWise]...';


GO

-- =============================================  
-- Author:  Shubhrangshu Nag  
-- Create date: 09/10/2013  
-- Description: To get HomeWork Attendance Report BatchWise 
-- =============================================  
  
CREATE PROCEDURE [REPORT].[uspGetHomeWorkAttendanceBatchWise] --'88',109,NULL,'2013-08-15','2013-09-11'
(  
-- Add the parameters for the stored procedure here  
	@sHierarchyList varchar(MAX),
    @iBrandID int,
    @iBatchID INT  = NULL,
	@FromDate DATETIME,  
	@ToDate  DATETIME    
)  
AS  
  
BEGIN TRY  
 BEGIN   
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 SET NOCOUNT ON;  

	Declare @temp table(S_Skill_Desc VARCHAR(100),I_Skill_ID INT,S_Batch_Name VARCHAR(100),I_Batch_ID INT,Prcnt90 INT, Prcnt9070 INT,Prcnt7050 INT,Prcnt50 INT,Prcnt0 INT,TotalStudentCount INT)
	Declare @temp1 table(S_Skill_Desc VARCHAR(100),I_Skill_ID INT,S_Batch_Name VARCHAR(100),I_Batch_ID INT,Prcnt90 INT, Prcnt9070 INT,Prcnt7050 INT,Prcnt50 INT)

	Declare @Final table(S_Skill_Desc VARCHAR(100),I_Skill_ID INT,S_Batch_Name VARCHAR(100),I_Batch_ID INT,Prcnt90 INT, HWPrcnt90 INT, Prcnt9070 INT,HWPrcnt9070 INT,Prcnt7050 INT,HWPrcnt7050 INT,Prcnt50 INT,HWPrcnt50 INT, Prcnt0 INT,TotalStudentCount INT)


	
		
	INSERT INTO @temp (S_Skill_Desc ,I_Skill_ID,S_Batch_Name,I_Batch_ID ,Prcnt90 , Prcnt9070 ,Prcnt7050 ,Prcnt50,Prcnt0 ,TotalStudentCount)
	SELECT 	
	  S_Skill_Desc,
	  I_Skill_ID,
	S_Batch_Name,
	I_Batch_ID,
	SUM(PERCENTAGE90) Prcnt90,
	SUM(PERCENTAGE9070) Prcnt9070,
	SUM(PERCENTAGE7050) Prcnt7050,
	SUM(PERCENTAGE50) Prcnt50,
	(TotalStudentCount - SUM(PERCENTAGE90) - SUM(PERCENTAGE9070) - SUM(PERCENTAGE7050) - SUM(PERCENTAGE50)) Prcnt0 ,
	TotalStudentCount

	 FROM

(SELECT DISTINCT No_Atteded_Session, S_Student_ID ,	
	  S_Skill_Desc,
	  I_Skill_ID,
	S_Batch_Name,
	I_Batch_ID,
	--(CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) fraction,
	CASE 
	WHEN SessionCount = 0 THEN NULL
      WHEN (CAST(No_Atteded_Session AS FLOAT)/ CAST(SessionCount AS FLOAT)) >=0.9 THEN 1 
      ELSE 0 
	END PERCENTAGE90,
	CASE 
	WHEN SessionCount = 0 THEN NULL
	 WHEN (CAST(No_Atteded_Session AS FLOAT)/ CAST(SessionCount AS FLOAT)) >=0.7 AND (CAST(No_Atteded_Session AS FLOAT)/ CAST(SessionCount AS FLOAT)) < 0.9 THEN 1 
      ELSE 0 
	END PERCENTAGE9070	
	,
	CASE 
	WHEN SessionCount = 0 THEN NULL
	 WHEN (CAST(No_Atteded_Session AS FLOAT)/ CAST(SessionCount AS FLOAT)) >=0.5 AND (CAST(No_Atteded_Session AS FLOAT)/ CAST(SessionCount AS FLOAT)) < 0.7 THEN 1 
      ELSE 0 
	END PERCENTAGE7050,

	CASE 
	  WHEN SessionCount = 0 THEN NULL
      WHEN (CAST(No_Atteded_Session AS FLOAT)/ CAST(SessionCount AS FLOAT)) < 0.5 THEN 1 
      ELSE 0 
	END  PERCENTAGE50	
	 	 
	 ,SessionCount
	 ,TotalStudentCount
from
	(SELECT 
	 COUNT(SA.I_Attendance_Detail_ID) AS No_Atteded_Session,
	  SD.S_Student_ID ,
	  --TM.S_Session_Name ,
	  ESM.S_Skill_Desc,
	  ESM.I_Skill_ID,
	TSBM.S_Batch_Name,
	TSBM.I_Batch_ID,
	dbo.[fnGetTotalStudentCount](TSBM.I_Batch_ID) TotalStudentCount ,
	--dbo.[fnGetTotalSessionCount](TSBM.I_Batch_ID,SC.I_Centre_Id,'2013-06-01','2013-06-30') TotalSessionCount ,
	dbo.[fnGetTotalSessionCountSubjectWise](TSBM.I_Batch_ID,SC.I_Centre_Id,ESM.I_Skill_ID,@FromDate,@ToDate) SessionCount 
	FROM dbo.T_Student_Detail SD  
	INNER JOIN dbo.T_Student_Batch_Details AS TSBD  
    ON SD.I_Student_Detail_ID = TSBD.I_Student_ID  
    AND TSBD.I_Status = 1  
    AND SD.I_Status = 1 
	INNER JOIN dbo.T_Student_Center_Detail SC  
    ON SC.I_Student_Detail_ID = TSBD.I_Student_ID  
    AND SC.I_Status = 1  
   INNER JOIN dbo.T_Center_Batch_Details AS TCBD
   ON TSBD.I_Batch_ID = TCBD.I_Batch_ID
   AND SC.I_Centre_Id = TCBD.I_Centre_Id
   AND ISNULL(TCBD.I_Status,2) <> 5
   INNER JOIN dbo.T_Student_Batch_Master AS TSBM
   ON TCBD.I_Batch_ID = TSBM.I_Batch_ID 
   INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1  
   ON SC.I_Centre_Id=FN1.CenterID  
   INNER JOIN [dbo].[T_TimeTable_Master] TM
   ON TM.I_Center_ID=FN1.CenterID  
   AND TM.I_Batch_ID=TSBM.I_Batch_ID 
   --INNER JOIN [dbo].[T_TimeTable_Faculty_Map] TFM
   --ON TM.I_TimeTable_ID=TFM.I_TimeTable_ID 
   INNER JOIN dbo.T_Session_Master SM  
   ON SM.I_Session_ID=TM.I_Session_ID
   INNER JOIN dbo.T_EOS_SKILL_MASTER ESM  
   ON ESM.I_Skill_ID=SM.I_Skill_ID
   INNER JOIN  [dbo].[T_Student_Attendance] SA
   ON SA.I_TimeTable_ID=TM.I_TimeTable_ID
   AND SA.I_Student_Detail_ID=TSBD.[I_Student_ID] 
   WHERE  TM.Dt_Schedule_Date >= @FromDate
	AND TM.Dt_Schedule_Date <= @ToDate
	AND TSBM.I_Batch_ID=ISNULL(@iBatchID,TSBM.I_Batch_ID)
   --AND TFM.I_Employee_ID=@EmployeeID
   GROUP BY  SD.S_Student_ID ,ESM.S_Skill_Desc ,ESM.I_Skill_ID,TSBM.S_Batch_Name,TSBM.I_Batch_ID,SC.I_Centre_Id) a ) b
   GROUP BY S_Skill_Desc,I_Skill_ID,S_Batch_Name,I_Batch_ID,TotalStudentCount
	ORDER BY S_Batch_Name


INSERT INTO @temp1 (S_Skill_Desc ,I_Skill_ID,S_Batch_Name,I_Batch_ID ,Prcnt90 , Prcnt9070 ,Prcnt7050 ,Prcnt50)
	SELECT 	
	  S_Skill_Desc,
	  I_Skill_ID,
	S_Batch_Name,
	I_Batch_ID,
	SUM(PERCENTAGE90) Prcnt90,
	SUM(PERCENTAGE9070) Prcnt9070,
	SUM(PERCENTAGE7050) Prcnt7050,
	SUM(PERCENTAGE50) Prcnt50
	 FROM
	(SELECT DISTINCT No_HW_Submission, S_Student_ID ,	
	  S_Skill_Desc,
	  I_Skill_ID,
	S_Batch_Name,
	I_Batch_ID,
	--(CAST(No_Atteded_Session as float)/ CAST(SessionCount as float)) fraction,
	CASE 
	WHEN HomeWorkCount = 0 THEN NULL
      WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) >=0.9 THEN 1 
      ELSE 0 
	END PERCENTAGE90,
	CASE 
	WHEN HomeWorkCount = 0 THEN NULL
	 WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) >=0.7 AND (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) < 0.9 THEN 1 
      ELSE 0 
	END PERCENTAGE9070	
	,
	CASE 
	WHEN HomeWorkCount = 0 THEN NULL
	 WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) >=0.5 AND (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) < 0.7 THEN 1 
      ELSE 0 
	END PERCENTAGE7050,

	CASE 
	  WHEN HomeWorkCount = 0 THEN NULL
      WHEN (CAST(No_HW_Submission as float)/ CAST(HomeWorkCount as float)) < 0.5 THEN 1 
      ELSE 0 
	END  PERCENTAGE50	
	 	 
	 ,HomeWorkCount
	
from
	(SELECT    
	--COUNT( DISTINCT SD.S_Student_ID) as No_Atteded_Student, 
	Count(HS.I_Homework_Submission_ID) AS No_HW_Submission,
	 SD.S_Student_ID,
   TSBM.S_Batch_Name,TSBM.I_Batch_ID,
   --SM.S_Session_Name,
   ESM.S_Skill_Desc,
	  ESM.I_Skill_ID,
	  dbo.[fnGetTotalStudentCount](TSBM.I_Batch_ID) TotalStudentCount,
	  [dbo].[fnGetTotalHomeWorkCountSubjectWise](TSBM.I_Batch_ID,SC.I_Centre_Id,ESM.I_Skill_ID,@FromDate,@ToDate) HomeWorkCount  
  FROM   
   dbo.T_Student_Detail SD  
   INNER JOIN dbo.T_Student_Batch_Details AS TSBD  
    ON SD.I_Student_Detail_ID = TSBD.I_Student_ID  
    AND TSBD.I_Status = 1  
    AND SD.I_Status = 1 
   INNER JOIN dbo.T_Student_Center_Detail SC  
    ON SC.I_Student_Detail_ID = TSBD.I_Student_ID  
    AND SC.I_Status = 1  
   INNER JOIN dbo.T_Center_Batch_Details AS TCBD
   ON TSBD.I_Batch_ID = TCBD.I_Batch_ID
   AND SC.I_Centre_Id = TCBD.I_Centre_Id
   AND ISNULL(TCBD.I_Status,2) <> 5
   INNER JOIN dbo.T_Student_Batch_Master AS TSBM
   ON TCBD.I_Batch_ID = TSBM.I_Batch_ID 
   INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1  
   ON SC.I_Centre_Id=FN1.CenterID  
   INNER JOIN [EXAMINATION].[T_Homework_Submission] HS
   ON HS.I_Student_Detail_ID=SD.I_Student_Detail_ID 
   INNER JOIN [EXAMINATION].[T_Homework_Master]  HM
   ON HS.I_Homework_ID=HM.I_Homework_ID
   INNER JOIN dbo.T_Session_Master SM  
   ON SM.I_Session_ID=HM.I_Session_ID
   INNER JOIN dbo.T_EOS_SKILL_MASTER ESM  
   ON ESM.I_Skill_ID=SM.I_Skill_ID
   WHERE HM.Dt_Submission_Date>= @FromDate
	AND HM.Dt_Submission_Date <= @ToDate
	AND TSBM.I_Batch_ID=ISNULL(@iBatchID,TSBM.I_Batch_ID)
   --AND HS.I_Employee_ID=@EmployeeID
   GROUP BY  SD.S_Student_ID ,ESM.S_Skill_Desc ,ESM.I_Skill_ID,TSBM.S_Batch_Name,TSBM.I_Batch_ID,SC.I_Centre_Id) a) b
   GROUP BY S_Skill_Desc,I_Skill_ID,S_Batch_Name,I_Batch_ID
	ORDER BY S_Batch_Name




	INSERT INTO @Final (S_Skill_Desc ,I_Skill_ID,S_Batch_Name,I_Batch_ID ,Prcnt90 , Prcnt9070 ,Prcnt7050 ,Prcnt50,Prcnt0,TotalStudentCount)
	SELECT * FROM @temp

	UPDATE F
	SET F.HWPrcnt90=T.Prcnt90,
		F.HWPrcnt9070=T.Prcnt9070,
		F.HWPrcnt7050=T.Prcnt7050,
		F.HWPrcnt50=T.Prcnt50
	FROM @Final F
	INNER JOIN @temp1 T
	ON F.I_Batch_ID=T.I_Batch_ID
	AND F.I_Skill_ID=T.I_Skill_ID

	SELECT * FROM @Final

	--SELECT s_batch_name ,dt, sum(m1) No_St, sum(m2) No_ht
	--FROM(
	--SELECT s_batch_name ,dt, No_St m1, 0 m2  FROM @temp
	--UNION 
	--SELECT s_batch_name ,dt, 0 m1, No_St m2  FROM @temp1
	--) a
	--GROUP BY  s_batch_name ,dt	
	


 END  
END TRY  
  
BEGIN CATCH  
   
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int  
  
 SELECT @ErrMsg = ERROR_MESSAGE(),  
   @ErrSeverity = ERROR_SEVERITY()  
  
 RAISERROR(@ErrMsg, @ErrSeverity, 1)  
END CATCH
