CREATE PROCEDURE [REPORT].[uspGetInvoiceRegisterReport]
(
	-- Add the parameters for the stored procedure here
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@dtStartDate datetime,
	@dtEndDate datetime,
	@sCounselorCond varchar(20)
)
AS
BEGIN TRY
	
--	IF (@dtEndDate IS NOT NULL)
--	BEGIN
--		SET @dtEndDate = DATEADD(dd,1,@dtEndDate)
--	END
	
	DECLARE @InvoiceDetail TABLE
	(
		I_Invoice_Header_ID INT,
		S_Student_ID VARCHAR(500),
		S_Title VARCHAR(10),
		S_First_Name VARCHAR(50),
		S_Middle_Name VARCHAR(50),
		S_Last_Name VARCHAR(50),
		I_Status INT,
		S_Invoice_No VARCHAR(50),
		Dt_Invoice_Date DATETIME,
		Invoice_Amount NUMERIC(18,2),
		Tax_Amount NUMERIC(18,2),
		N_Discount_Amount NUMERIC(18,2),
		Invoice_Status VARCHAR(20),
		S_Discount_Scheme_Name VARCHAR(250),
		Coun_Title VARCHAR(10),
		Coun_First_Name VARCHAR(50),
		Coun_Middle_Name VARCHAR(50),
		Coun_Last_Name VARCHAR(50),
		CenterCode VARCHAR(50),
		CenterName VARCHAR(50),
		InstanceChain VARCHAR(200),
		S_Currency_Code VARCHAR(50),
		S_Form_Sold_By VARCHAR(300),
		S_Batch_Name VARCHAR(100)
	)
	
	IF @sCounselorCond ='ALL'
	BEGIN		 
		INSERT INTO @InvoiceDetail
		 SELECT B.I_Invoice_Header_ID,
				A.S_Student_ID,
				A.S_Title,
				A.S_First_Name,
				A.S_Middle_Name,
				A.S_Last_Name,
				A.I_Status,
				B.S_Invoice_No,
				B.Dt_Invoice_Date,
				ISNULL(B.N_Invoice_Amount,0.00) AS Invoice_Amount,
				ISNULL(B.N_Tax_Amount,0.00) AS Tax_Amount,
				ISNULL(B.N_Discount_Amount,0.00) AS N_Discount_Amount,
				'Active',
				C.S_Discount_Scheme_Name,
				D.S_Title AS Coun_Title,
				D.S_First_Name AS Coun_First_Name,
				D.S_Middle_Name AS Coun_Middle_Name,
				D.S_Last_Name AS Coun_Last_Name,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain,
				CUM.S_Currency_Code,
				TUM.S_First_Name + ISNULL(TUM.S_Middle_Name,'') + ISNULL(TUM.S_Last_Name,'') AS FormSoldBy,
				TSBM.S_Batch_Name
		   FROM dbo.T_Student_Detail A
				INNER JOIN dbo.T_Invoice_Parent B
			    ON A.I_Student_Detail_ID = B.I_Student_Detail_ID

				Inner JOIN dbo.T_Student_Batch_Details TSBD 
				ON B.I_Student_Detail_ID=TSBD.I_Student_ID
				Inner JOIN dbo.T_Student_Batch_Master TSBM 
				ON TSBD.I_Batch_ID=TSBM.I_Batch_ID

			    LEFT OUTER JOIN dbo.T_Discount_Scheme_Master C
			    ON B.I_Discount_Scheme_ID=C.I_Discount_Scheme_ID
				LEFT OUTER JOIN dbo.T_User_Master D
				ON B.S_Crtd_By=D.S_Login_ID
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON B.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
				INNER JOIN dbo.T_Centre_Master CEM
				ON FN1.CenterID=CEM.I_Centre_Id
				INNER JOIN dbo.T_Country_Master COM
				ON CEM.I_Country_ID=COM.I_Country_ID
				INNER JOIN dbo.T_Currency_Master CUM
				ON COM.I_Currency_ID=CUM.I_Currency_ID
				INNER JOIN T_Enquiry_Regn_Detail TERD
				ON TERD.I_Enquiry_Regn_ID = A.I_Enquiry_Regn_ID
				LEFT OUTER JOIN T_Receipt_Header TRH
				ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
				and I_Receipt_Type IN (31,32,50,51,	57)
				LEFT OUTER JOIN T_User_Master TUM
				ON TUM.S_Login_ID = TRH.S_Crtd_By
			WHERE DATEDIFF(dd,B.Dt_Invoice_Date,@dtStartDate) <= 0 AND DATEDIFF(dd,B.Dt_Invoice_Date,@dtEndDate) >= 0 
			and TRH.I_Status=1 --succesfully executed receipt(by susmita) 
			--WHERE CAST(SUBSTRING(CAST(B.Dt_Invoice_Date AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
			--and B.I_status=1
		 -- WHERE B.Dt_Invoice_Date BETWEEN @dtStartDate AND @dtEndDate

	UNION ALL

		 SELECT B.I_Invoice_Header_ID,
				A.S_Student_ID,
				A.S_Title,
				A.S_First_Name,
				A.S_Middle_Name,
				A.S_Last_Name,
				A.I_Status,
				B.S_Invoice_No,
				ISNULL(B.Dt_Upd_On,B.Dt_Invoice_Date),
				ISNULL(B.N_Invoice_Amount,0.00) AS Invoice_Amount,
				ISNULL(B.N_Tax_Amount,0.00) AS Tax_Amount,
				ISNULL(B.N_Discount_Amount,0.00) AS N_Discount_Amount,
				'Cancelled',
				C.S_Discount_Scheme_Name,
				D.S_Title AS Coun_Title,
				D.S_First_Name AS Coun_First_Name,
				D.S_Middle_Name AS Coun_Middle_Name,
				D.S_Last_Name AS Coun_Last_Name,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain,
				CUM.S_Currency_Code,
				TUM.S_First_Name + ISNULL(TUM.S_Middle_Name,'') + ISNULL(TUM.S_Last_Name,'') AS FormSoldBy,
				TSBM.S_Batch_Name
		   FROM dbo.T_Student_Detail A
				INNER JOIN dbo.T_Invoice_Parent B
			    ON A.I_Student_Detail_ID = B.I_Student_Detail_ID

				Inner JOIN dbo.T_Student_Batch_Details TSBD 
				ON B.I_Student_Detail_ID=TSBD.I_Student_ID
				Inner JOIN dbo.T_Student_Batch_Master TSBM 
				ON TSBD.I_Batch_ID=TSBM.I_Batch_ID

			    LEFT OUTER JOIN dbo.T_Discount_Scheme_Master C
			    ON B.I_Discount_Scheme_ID=C.I_Discount_Scheme_ID
				LEFT OUTER JOIN dbo.T_User_Master D
				ON B.S_Crtd_By=D.S_Login_ID
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON B.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
				INNER JOIN dbo.T_Centre_Master CEM
				ON FN1.CenterID=CEM.I_Centre_Id
				INNER JOIN dbo.T_Country_Master COM
				ON CEM.I_Country_ID=COM.I_Country_ID
				INNER JOIN dbo.T_Currency_Master CUM
				ON COM.I_Currency_ID=CUM.I_Currency_ID
				INNER JOIN T_Enquiry_Regn_Detail TERD
				ON TERD.I_Enquiry_Regn_ID = A.I_Enquiry_Regn_ID
				LEFT OUTER JOIN T_Receipt_Header TRH
				ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
				and I_Receipt_Type IN (31,32,50,51,	57)
				LEFT OUTER JOIN T_User_Master TUM
				ON TUM.S_Login_ID = TRH.S_Crtd_By
			WHERE DATEDIFF(dd,B.Dt_Upd_On,@dtStartDate) <= 0 AND DATEDIFF(dd,B.Dt_Upd_On,@dtEndDate) >= 0
			and TRH.I_Status=1 --succesfully executed receipt(by susmita) 
			--CAST(SUBSTRING(CAST(B.Dt_Upd_On AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
			--AND CAST(SUBSTRING(CAST(B.Dt_Invoice_Date AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
			--and B.I_status=0
		  --WHERE B.Dt_Upd_On BETWEEN @dtStartDate AND @dtEndDate


	
	END
	ELSE
	BEGIN

		INSERT INTO @InvoiceDetail
		 SELECT B.I_Invoice_Header_ID,
				A.S_Student_ID,
				A.S_Title,
				A.S_First_Name,
				A.S_Middle_Name,
				A.S_Last_Name,
				A.I_Status,
				B.S_Invoice_No,
				B.Dt_Invoice_Date,
				ISNULL(B.N_Invoice_Amount,0.00) AS Invoice_Amount,
				ISNULL(B.N_Tax_Amount,0.00) AS Tax_Amount,
				ISNULL(B.N_Discount_Amount,0.00) AS N_Discount_Amount,
				'Active',
				C.S_Discount_Scheme_Name,
				D.S_Title AS Coun_Title,
				D.S_First_Name AS Coun_First_Name,
				D.S_Middle_Name AS Coun_Middle_Name,
				D.S_Last_Name AS Coun_Last_Name,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain,
				CUM.S_Currency_Code,
				TUM.S_First_Name + ISNULL(TUM.S_Middle_Name,'') + ISNULL(TUM.S_Last_Name,'') AS FormSoldBy,
				TSBM.S_Batch_Name
		   FROM dbo.T_Student_Detail A
				INNER JOIN dbo.T_Invoice_Parent B
			    ON A.I_Student_Detail_ID = B.I_Student_Detail_ID

				Inner JOIN dbo.T_Student_Batch_Details TSBD 
				ON B.I_Student_Detail_ID=TSBD.I_Student_ID
				Inner JOIN dbo.T_Student_Batch_Master TSBM 
				ON TSBD.I_Batch_ID=TSBM.I_Batch_ID

			    LEFT OUTER JOIN dbo.T_Discount_Scheme_Master C
			    ON B.I_Discount_Scheme_ID=C.I_Discount_Scheme_ID
				LEFT OUTER JOIN dbo.T_User_Master D
				ON B.S_Crtd_By=D.S_Login_ID
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON B.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
				INNER JOIN dbo.T_Centre_Master CEM
				ON FN1.CenterID=CEM.I_Centre_Id
				INNER JOIN dbo.T_Country_Master COM
				ON CEM.I_Country_ID=COM.I_Country_ID
				INNER JOIN dbo.T_Currency_Master CUM
				ON COM.I_Currency_ID=CUM.I_Currency_ID
				INNER JOIN T_Enquiry_Regn_Detail TERD
				ON TERD.I_Enquiry_Regn_ID = A.I_Enquiry_Regn_ID
				LEFT OUTER JOIN T_Receipt_Header TRH
				ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
				and I_Receipt_Type IN (31,32,50,51,	57)
				LEFT OUTER JOIN T_User_Master TUM
				ON TUM.S_Login_ID = TRH.S_Crtd_By
			WHERE DATEDIFF(dd,B.Dt_Invoice_Date,@dtStartDate) <= 0 AND DATEDIFF(dd,B.Dt_Invoice_Date,@dtEndDate) >= 0
			and TRH.I_Status=1 --succesfully executed receipt(by susmita) 
			--CAST(SUBSTRING(CAST(B.Dt_Invoice_Date AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
		  --WHERE B.Dt_Invoice_Date BETWEEN @dtStartDate AND @dtEndDate
			AND	TRH.S_Crtd_By=@sCounselorCond
			--and B.I_status=1
	UNION ALL

		 SELECT B.I_Invoice_Header_ID,
				A.S_Student_ID,
				A.S_Title,
				A.S_First_Name,
				A.S_Middle_Name,
				A.S_Last_Name,
				A.I_Status,
				B.S_Invoice_No,
				ISNULL(B.Dt_Upd_On,B.Dt_Invoice_Date),
				ISNULL(B.N_Invoice_Amount,0.00) AS Invoice_Amount,
				ISNULL(B.N_Tax_Amount,0.00) AS Tax_Amount,
				ISNULL(B.N_Discount_Amount,0.00) AS N_Discount_Amount,
				'Cancelled',
				C.S_Discount_Scheme_Name,
				D.S_Title AS Coun_Title,
				D.S_First_Name AS Coun_First_Name,
				D.S_Middle_Name AS Coun_Middle_Name,
				D.S_Last_Name AS Coun_Last_Name,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain,
				CUM.S_Currency_Code,
				TUM.S_First_Name + ISNULL(TUM.S_Middle_Name,'') + ISNULL(TUM.S_Last_Name,'') AS FormSoldBy,
				TSBM.S_Batch_Name
		   FROM dbo.T_Student_Detail A
				INNER JOIN dbo.T_Invoice_Parent B
			    ON A.I_Student_Detail_ID = B.I_Student_Detail_ID

				Inner JOIN dbo.T_Student_Batch_Details TSBD 
				ON B.I_Student_Detail_ID=TSBD.I_Student_ID
				Inner JOIN dbo.T_Student_Batch_Master TSBM 
				ON TSBD.I_Batch_ID=TSBM.I_Batch_ID

			    LEFT OUTER JOIN dbo.T_Discount_Scheme_Master C
			    ON B.I_Discount_Scheme_ID=C.I_Discount_Scheme_ID
				LEFT OUTER JOIN dbo.T_User_Master D
				ON B.S_Crtd_By=D.S_Login_ID
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON B.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
				INNER JOIN dbo.T_Centre_Master CEM
				ON FN1.CenterID=CEM.I_Centre_Id
				INNER JOIN dbo.T_Country_Master COM
				ON CEM.I_Country_ID=COM.I_Country_ID
				INNER JOIN dbo.T_Currency_Master CUM
				ON COM.I_Currency_ID=CUM.I_Currency_ID
				INNER JOIN T_Enquiry_Regn_Detail TERD
				ON TERD.I_Enquiry_Regn_ID = A.I_Enquiry_Regn_ID
				LEFT OUTER JOIN T_Receipt_Header TRH
				ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
				and I_Receipt_Type IN (31,32,50,51,	57)
				LEFT OUTER JOIN T_User_Master TUM
				ON TUM.S_Login_ID = TRH.S_Crtd_By
			WHERE DATEDIFF(dd,B.Dt_Upd_On,@dtStartDate) <= 0 AND DATEDIFF(dd,B.Dt_Upd_On,@dtEndDate) >= 0
			and TRH.I_Status=1 --succesfully executed receipt(by susmita) 
			--CAST(SUBSTRING(CAST(B.Dt_Upd_On AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
			--AND CAST(SUBSTRING(CAST(B.Dt_Invoice_Date AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
			AND	TRH.S_Crtd_By=@sCounselorCond
--and B.I_status=0

	END

		 SELECT F.S_Student_ID,
				F.S_Title,
				F.S_First_Name,
				F.S_Middle_Name,
				F.S_Last_Name,
				F.I_Status,
				F.S_Invoice_No,
				F.Dt_Invoice_Date,
				F.Invoice_Amount,
				F.Tax_Amount,
				F.N_Discount_Amount,
				F.Invoice_Status,
				F.S_Discount_Scheme_Name,
				F.Coun_Title,
				F.Coun_First_Name,
				F.Coun_Middle_Name,
				F.Coun_Last_Name,
				F.CenterCode,
				F.CenterName,
				F.InstanceChain,
				F.S_Currency_Code,
				B.I_Invoice_Header_ID,
				D.S_Course_Code,
				D.S_Course_Name,
				E.S_Fee_Plan_Name,
				Course_Fee = 
						CASE 
							WHEN F.Invoice_Status =  'Active' THEN 
								ISNULL((SElECT SUM(ISNULL(N_Amount_Due,0.00)) 
								FROM dbo.T_Invoice_Child_Detail AA
								WHERE I_Fee_Component_ID = 21
								AND AA.I_Invoice_Child_Header_ID = A.I_Invoice_Child_Header_ID),0.00)
							WHEN F.Invoice_Status =  'Cancelled' THEN 
								ISNULL((SElECT SUM(ISNULL(N_Amount_Due,0.00)) 
								FROM dbo.T_Invoice_Child_Detail AA
								WHERE I_Fee_Component_ID = 21
								AND AA.I_Invoice_Child_Header_ID = A.I_Invoice_Child_Header_ID),0.00) 
						END,
				Exam_Fee =   
						CASE 
							WHEN F.Invoice_Status =  'Active' THEN 
								ISNULL((SElECT SUM(ISNULL(N_Amount_Due,0.00)) 
								FROM dbo.T_Invoice_Child_Detail AA
								WHERE I_Fee_Component_ID = 4
								AND AA.I_Invoice_Child_Header_ID = A.I_Invoice_Child_Header_ID),0.00)
							WHEN F.Invoice_Status =  'Cancelled' THEN 
								ISNULL((SElECT SUM(ISNULL(N_Amount_Due,0.00)) 
								FROM dbo.T_Invoice_Child_Detail AA
								WHERE I_Fee_Component_ID = 4
								AND AA.I_Invoice_Child_Header_ID = A.I_Invoice_Child_Header_ID),0.00) 
						END,
				Others_Fee = 
						CASE 
							WHEN F.Invoice_Status =  'Active' THEN 
								ISNULL((SElECT SUM(ISNULL(N_Amount_Due,0.00)) 
								FROM dbo.T_Invoice_Child_Detail AA
								WHERE I_Fee_Component_ID NOT IN (21,4)
								AND AA.I_Invoice_Child_Header_ID = A.I_Invoice_Child_Header_ID),0.00)
							WHEN F.Invoice_Status =  'Cancelled' THEN 
								ISNULL((SElECT SUM(ISNULL(N_Amount_Due,0.00)) 
								FROM dbo.T_Invoice_Child_Detail AA
								WHERE I_Fee_Component_ID NOT IN (21,4)
								AND AA.I_Invoice_Child_Header_ID = A.I_Invoice_Child_Header_ID),0.00)
						END,
				Tax_Component=
						CASE
							WHEN F.Invoice_Status =  'Active' THEN 
								SUM(N_Tax_Value)
							WHEN F.Invoice_Status =  'Cancelled' THEN 
								SUM(N_Tax_Value)
						END,
				F.S_Form_Sold_By,
				F.S_Batch_Name
		   FROM dbo.T_Invoice_Child_Detail A
				INNER JOIN dbo.T_Invoice_Child_Header B
				ON A.I_Invoice_Child_Header_ID=B.I_Invoice_Child_Header_ID
				LEFT OUTER JOIN dbo.T_Invoice_Detail_Tax C
				ON A.I_Invoice_Detail_ID=C.I_Invoice_Detail_ID
				INNER JOIN dbo.T_Course_Master D
				ON B.I_Course_ID=D.I_Course_ID
				INNER JOIN dbo.T_Course_Fee_Plan E
				ON B.I_Course_FeePlan_ID=E.I_Course_Fee_Plan_ID
				INNER JOIN @InvoiceDetail F
				ON B.I_Invoice_Header_ID=F.I_Invoice_Header_ID

	   GROUP BY B.I_Invoice_Header_ID, 
				A.I_Invoice_Child_Header_ID, 
				D.S_Course_Code,
				D.S_Course_Name,
				E.S_Fee_Plan_Name,
				F.I_Invoice_Header_ID,
				F.S_Student_ID,
				F.S_Title,
				F.S_First_Name,
				F.S_Middle_Name,
				F.S_Last_Name,
				F.I_Status,
				F.S_Invoice_No,
				F.Dt_Invoice_Date,
				F.Invoice_Amount,
				F.Tax_Amount,
				F.N_Discount_Amount,
				F.Invoice_Status,
				F.S_Discount_Scheme_Name,
				F.Coun_Title,
				F.Coun_First_Name,
				F.Coun_Middle_Name,
				F.Coun_Last_Name,
				F.CenterCode,
				F.CenterName,
				F.InstanceChain,
				F.S_Currency_Code,
				F.S_Form_Sold_By,
				F.S_Batch_Name
	   ORDER BY F.InstanceChain,
				F.CenterName,
				F.Coun_Title,
				F.Coun_First_Name,
				F.Coun_Middle_Name,
				F.Coun_Last_Name,
				F.S_Student_ID,
				F.S_Invoice_No

END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetMarksDistributionReport]...';


GO
/****************************************************************
Author	:     Swagatam Sarkar
Date	:	  02/Jan/2008
Description : This SP retrieves the Marks Distribution of a Term
				
****************************************************************/

CREATE PROCEDURE [REPORT].[uspGetMarksDistributionReport]
(
	-- Add the parameters for the stored procedure here
	@sHierarchyList varchar(100),
	@iBrandID int,
	@DtFrmDate datetime,
	@DtToDate datetime,
	@iCourseFamilyID int,
	@svCourseFamilyName varchar(50),
	@iCourseID int,
	@svCourseName varchar(50),
	@iTermID INT = NULL,
	@svTermName varchar(50) = NULL
)
AS
BEGIN TRY
	BEGIN
		
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	
	DECLARE @StudentMarks TABLE
	(
		I_Centre_ID INT,
		S_Center_Name VARCHAR(50),
		S_Course_Name VARCHAR(50),
		S_Term_Name VARCHAR(50),
		I_Student_Detail_ID INT,
		S_Title VARCHAR(10),
		S_First_Name VARCHAR(50),
		S_Middle_Name VARCHAR(50),
		S_Last_Name VARCHAR(50),
		S_Term_Final_Marks INT
	)

	DECLARE @CenterReport TABLE
	(
		I_Centre_ID INT,
		S_Center_Name VARCHAR(50),
		S_Course_Family_Name VARCHAR(50),
		S_Course_Name VARCHAR(50),
		S_Term_Name VARCHAR(50),
		Total_Students INT,
		Total_LT_40 INT,
		Total_LT_50 INT,
		Total_LT_60 INT,
		Total_LT_70 INT,
		Total_LT_80 INT,
		Total_LT_90 INT,
		Total_LT_95 INT,
		Total_LT_100 INT
	)

	DECLARE @iTotalStudents INT, @iTotalLT40 INT, @iTotalLT50 INT, @iTotalLT60 INT, @iTotalLT70 INT
	DECLARE @iTotalLT80 INT, @iTotalLT90 INT, @iTotalLT95 INT, @iTotalLT100 INT
	DECLARE @sCourseFamilyName VARCHAR(50)
	SET @sCourseFamilyName = (SELECT S_CourseFamily_Name FROM dbo.T_CourseFamily_Master WHERE I_CourseFamily_ID = @iCourseFamilyID)

	IF (@DtToDate IS NOT NULL)
	BEGIN
		SET @DtToDate = DATEADD(dd,1,@DtToDate)
	END

	DECLARE @iCenterID INT

	DECLARE CenterList CURSOR FOR
	SELECT CenterID FROM [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID)

	OPEN CenterList
	FETCH NEXT FROM CenterList INTO @iCenterID
	
	WHILE @@FETCH_STATUS = 0
	BEGIN

		DELETE FROM @StudentMarks

		INSERT INTO @StudentMarks
		SELECT DISTINCT TCM.I_Centre_Id,TCM.S_Center_Name,CM.S_Course_Name,TM.S_Term_Name,
			STD.I_Student_Detail_ID,SD.S_Title,SD.S_First_Name,SD.S_Middle_Name,SD.S_Last_Name,
			STD.S_Term_Final_Marks
		FROM dbo.T_Student_Term_Detail STD
		INNER JOIN dbo.T_Student_Detail SD 
			ON STD.I_Student_Detail_ID = SD.I_Student_Detail_ID
		INNER JOIN dbo.T_Student_Center_Detail SCEN 
			ON SD.I_Student_Detail_ID=SCEN.I_Student_Detail_ID
			AND SCEN.I_Centre_Id = @iCenterID
		INNER JOIN PSCERTIFICATE.T_Student_PS_Certificate SPC 
			ON SPC.I_Student_Detail_ID = SD.I_Student_Detail_ID 
			AND SPC.I_Course_ID = STD.I_Course_ID AND ISNULL(SPC.I_Term_ID,STD.I_Term_ID) = STD.I_Term_ID
			AND SPC.Dt_Certificate_Issue_Date BETWEEN @DtFrmDate AND @DtToDate
			--AND SPC.B_PS_Flag = 1
		INNER JOIN PSCERTIFICATE.T_Certificate_Logistic CL
			ON CL.I_Student_Certificate_ID = SPC.I_Student_Certificate_ID
			AND CL.I_Status = 1
		INNER JOIN dbo.T_Course_Master CM
			ON STD.I_Course_ID = CM.I_Course_ID
		INNER JOIN dbo.T_Term_Master TM
			ON STD.I_Term_ID = TM.I_Term_ID
		INNER JOIN dbo.T_Centre_Master TCM
			ON SCEN.I_Centre_Id = TCM.I_Centre_Id
		WHERE STD.S_Term_Final_Marks IS NOT NULL AND STD.S_Term_Final_Marks < 100
			AND STD.I_Course_ID = @iCourseID
			AND STD.I_Term_ID = ISNULL(@iTermID,STD.I_Term_ID)
		ORDER BY STD.S_Term_Final_Marks DESC

		SET @iTotalStudents = (SELECT COUNT(*) FROM @StudentMarks)
		SET @iTotalLT40 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks < 40)
		SET @iTotalLT50 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 40 AND S_Term_Final_Marks < 50)
		SET @iTotalLT60 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 50 AND S_Term_Final_Marks < 60)
		SET @iTotalLT70 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 60 AND S_Term_Final_Marks < 70)
		SET @iTotalLT80 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 70 AND S_Term_Final_Marks < 80)
		SET @iTotalLT90 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 80 AND S_Term_Final_Marks < 90)
		SET @iTotalLT95 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 90 AND S_Term_Final_Marks < 95)
		SET @iTotalLT100 = (SELECT COUNT(*) FROM @StudentMarks WHERE S_Term_Final_Marks >= 95 AND S_Term_Final_Marks < 100)

		INSERT INTO @CenterReport
		SELECT DISTINCT I_Centre_Id,S_Center_Name,@sCourseFamilyName,S_Course_Name,S_Term_Name,
						@iTotalStudents AS Total_Students,@iTotalLT40 AS Total_LT_40,
						@iTotalLT50 AS Total_LT_50,@iTotalLT60 AS Total_LT_60,
						@iTotalLT70 AS Total_LT_70,@iTotalLT80 AS Total_LT_80,
						@iTotalLT90 AS Total_LT_90,@iTotalLT95 AS Total_LT_95,
						@iTotalLT100 AS Total_LT_100
		FROM @StudentMarks

		FETCH NEXT FROM CenterList INTO @iCenterID

	END
	
	CLOSE CenterList
	DEALLOCATE CenterList

	SELECT CR.*,FN2.InstanceChain FROM @CenterReport CR
	INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
		ON CR.I_Centre_Id=FN1.CenterID
	INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
		ON FN1.HierarchyDetailID=FN2.HierarchyDetailID

	END
END TRY

BEGIN CATCH
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()
	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetLogisticsSalesListingReport]...';


GO
/*
-- =================================================================
-- Author: Chandan Dey
-- Create date:08/21/2007 
-- Description: SP For Logistics Sales Listing Report
-- =================================================================
*/
CREATE PROCEDURE [REPORT].[uspGetLogisticsSalesListingReport]
(
	@iBrandID INT = NULL,
	--@sHierarchyList VARCHAR(100) = NULL,
	@iDomInt INT = NULL,
	@sDomIntType VARCHAR(50) = NULL,
	@iCategoryID INT = NULL,
	@sCategoryName VARCHAR(50) = NULL,
	@dtStartDate DATETIME,
	@dtEndDate DATETIME
)
AS
BEGIN TRY

DECLARE @BrandName VARCHAR (1000)
--DECLARE @ItemTypeName VARCHAR (1000)

SELECT @BrandName=S_Brand_Name FROM dbo.T_Brand_Master WHERE I_Brand_ID = @iBrandID
--SELECT @ItemTypeName=S_Logistics_Type_Desc FROM LOGISTICS.T_Logistics_Type_Master WHERE I_Logistics_Type_ID = @iCategoryID

SELECT
		@BrandName AS BrandName
		,ISNULL(LTM.S_Logistics_Type_Desc,'') AS S_Logistics_Type_Desc
		,ISNULL(LM.S_Item_Code,'') AS S_Item_Code
		,ISNULL(LM.S_Item_Desc,'') AS S_Item_Desc
		,SUM(LM.I_Item_Price_INR) AS I_Item_Price_INR
		,SUM(LM.I_Item_Price_USD) AS I_Item_Price_USD
		--,FN2.InstanceChain AS InstanceChain
		--,FN1.CenterName AS CenterName
		--,(SUBSTRING(REPLACE((REPLACE(FN2.InstanceChain,' ','')),' ',''),(CHARINDEX('n-',(REPLACE(FN2.InstanceChain,' ','')),0) + 2),(CHARINDEX(';C',(REPLACE(FN2.InstanceChain,' ','')),0) - (CHARINDEX('n-',(REPLACE(FN2.InstanceChain,' ','')),0)+2)))) AS RegionName
		,SUM(LOL.I_Item_Qty) AS I_Item_Qty
FROM	
		LOGISTICS.T_Logistics_Order_Line LOL
		LEFT OUTER JOIN LOGISTICS.T_Logistics_Order LO
		ON LO.I_Logistic_Order_ID = LOL.I_Logistics_Order_ID
		LEFT OUTER JOIN LOGISTICS.T_Logistics_Master LM
		ON LM.I_Logistics_ID = LOL.I_Logistics_ID
		LEFT OUTER JOIN LOGISTICS.T_Logistics_Type_Master LTM
		ON LTM.I_Logistics_Type_ID = LM.I_Logistics_Type_ID
		LEFT OUTER JOIN dbo.T_Centre_Master CM
		ON CM.I_Centre_Id = LO.I_Center_ID
WHERE
		DATEDIFF(dd, ISNULL(@dtStartDate, LO.Order_Date),  LO.Order_Date) >= 0
		AND DATEDIFF(dd, ISNULL(@dtEndDate, LO.Order_Date),  LO.Order_Date) <= 0
		AND LTM.I_Logistics_Type_ID = COALESCE(@iCategoryID, LTM.I_Logistics_Type_ID)
		AND CM.I_Country_ID = COALESCE(@iDomInt, CM.I_Country_ID)
GROUP BY
		--@BrandName
		LTM.S_Logistics_Type_Desc
		,LM.S_Item_Code
		,LM.S_Item_Desc
		
END TRY

BEGIN CATCH
	--Error occurred:

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetLogisticsSalesAnalysisReport]...';


GO
/*
-- =================================================================
-- Author: Chandan Dey
-- Create date:08/21/2007 
-- Description: SP For Logistics Sales Analysis Report
-- =================================================================
*/
CREATE PROCEDURE [REPORT].[uspGetLogisticsSalesAnalysisReport]
(
	@iBrandID INT = NULL,
	@iDomInt INT = NULL,
	@sDomIntType VARCHAR(50) = NULL,
	@iCategoryID INT = NULL,
	@sCategoryName VARCHAR(50) = NULL,
	@dtStartMonth DATETIME,
	@dtEndMonth DATETIME
)
AS
BEGIN TRY

DECLARE @BrandName VARCHAR (1000)

SELECT @BrandName=S_Brand_Name FROM dbo.T_Brand_Master WHERE I_Brand_ID = @iBrandID

SELECT	
		 @BrandName AS BrandName
		,ISNULL(LTM.S_Logistics_Type_Desc,'') AS S_Logistics_Type_Desc
		,SUM(LOL.I_Item_Qty) AS I_Item_Qty
		,SUM(LOL.I_Item_Amount) AS I_Item_Amount
		--,SUM(LOL.I_Item_Qty)/DATEDIFF(dd,@dtStartMonth,@dtEndMonth) AS Avg_I_Item_Qty -- Chandan
		--,SUM(LOL.I_Item_Amount)/DATEDIFF(dd,@dtStartMonth,@dtEndMonth) AS Avg_I_Item_Amount-- Chandan
		,SUM(LOL.I_Item_Qty)/DATEDIFF(mm,@dtStartMonth,@dtEndMonth) AS Avg_I_Item_Qty --babin
		,SUM(LOL.I_Item_Amount)/DATEDIFF(mm,@dtStartMonth,@dtEndMonth) AS Avg_I_Item_Amount --babin
FROM	
		LOGISTICS.T_Logistics_Order_Line LOL
		
		LEFT OUTER JOIN LOGISTICS.T_Logistics_Order LO
		ON LO.I_Logistic_Order_ID = LOL.I_Logistics_Order_ID
		LEFT OUTER JOIN LOGISTICS.T_Logistics_Master LM
		ON LM.I_Logistics_ID = LOL.I_Logistics_ID
		LEFT OUTER JOIN LOGISTICS.T_Logistics_Type_Master LTM
		ON LTM.I_Logistics_Type_ID = LM.I_Logistics_Type_ID
WHERE
		LO.Order_Date >= @dtStartMonth 
		AND LO.Order_Date <= @dtEndMonth 
		AND LM.I_Logistics_Type_ID = COALESCE(@iCategoryID, LM.I_Logistics_Type_ID)
		
GROUP BY
		LTM.S_Logistics_Type_Desc

END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetLogisticsCycleTimeAnalysisReport]...';


GO
/*
-- =================================================================
-- Author: Chandan Dey
-- Create date:08/21/2007 
-- Description: SP For Logistics Item Indent Track Report
-- =================================================================
*/
CREATE PROCEDURE [REPORT].[uspGetLogisticsCycleTimeAnalysisReport]
(
	@iBrandID INT = NULL,
	@sHierarchyList VARCHAR(MAX) = NULL,
	@dtStartDate DATETIME,
	@dtEndDate DATETIME
)
AS
BEGIN TRY

SELECT	
		 		
		FN2.InstanceChain AS InstanceChain
		,FN1.CenterName AS CenterName
		--,(SUBSTRING(REPLACE((REPLACE(FN2.InstanceChain,' ','')),' ',''),(CHARINDEX('n-',(REPLACE(FN2.InstanceChain,' ','')),0) + 2),(CHARINDEX(';C',(REPLACE(FN2.InstanceChain,' ','')),0) - (CHARINDEX('n-',(REPLACE(FN2.InstanceChain,' ','')),0)+2)))) AS RegionName
		,(LO.Order_Date) AS Order_Date
		,ISNULL(LP.Dt_Issue_Date, ' ') AS Dt_Issue_Date
		--,COALESCE(LP.Dt_Issue_Date, Dt_Issue_Date) AS Dt_Issue_Date
		,(LDI.Dt_Despatch_Date) AS Dt_Despatch_Date
		,(LDI.S_Docket_No) AS S_Docket_No
		,(LDI.Dt_Crtd_On) AS Dt_Crtd_On

		FROM LOGISTICS.T_Logistics_Order LO
		RIGHT JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
		ON LO.I_Center_ID =FN1.CenterID
		RIGHT JOIN  [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
		ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
		--RIGHT JOIN 
		,LOGISTICS.T_Logistics_Payment LP
		--ON LP.I_Logistics_Order_ID = LO.I_Logistic_Order_ID
		--RIGHT JOIN 
		,LOGISTICS.T_Logistics_Despatch_Info LDI
		--ON LDI.I_Logistics_Order_ID = LO.I_Logistic_Order_ID

		WHERE DATEDIFF(dd, ISNULL(@dtStartDate, LO.Order_Date),  LO.Order_Date) >= 0
		AND DATEDIFF(dd, ISNULL(@dtEndDate, LO.Order_Date),  LO.Order_Date) <= 0
		AND LP.I_Logistics_Order_ID = LO.I_Logistic_Order_ID
		AND LDI.I_Logistics_Order_ID = LO.I_Logistic_Order_ID

END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
