GO
CREATE PROCEDURE [REPORT].[uspGetMonthlyCollectableReport_temp]
    (
      @iBrandID INT ,
      @sHierarchyListID VARCHAR(MAX) ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS 
    BEGIN
    
    SET @dtEndDate=DATEADD(d,1,@dtEndDate)
		
		SELECT Final.S_Center_Name ,
                Final.S_Course_Name ,
                Final.S_Batch_Name ,
                Final.S_Student_ID ,
                Final.StudentName ,
                Final.ContactNo,
                Final.I_RollNo ,
                Final.I_Invoice_Header_ID ,
                Final.S_Invoice_No ,
                Final.I_Invoice_Detail_ID ,
                Final.I_Installment_No ,
                Final.Dt_Installment_Date ,
                Final.S_Component_Name ,
                Final.N_Amount_Due ,
                Final.S_Tax_Desc,
                Final.ReceiptCompAmount ,
                Final.TotalTax ,
                Final.ReceiptCompTax,
                Final.BaseAmtDiff,
                Final.TaxDiff,
                Final.BaseAmtDiff+Final.TaxDiff AS TotalDiff
		FROM
		(
        SELECT  InvoiceDue.S_Center_Name ,
                InvoiceDue.S_Course_Name ,
                InvoiceDue.S_Batch_Name ,
                InvoiceDue.S_Student_ID ,
                InvoiceDue.StudentName ,
                InvoiceDue.ContactNo,
                InvoiceDue.I_RollNo ,
                InvoiceDue.I_Invoice_Header_ID ,
                InvoiceDue.S_Invoice_No ,
                InvoiceDue.I_Invoice_Detail_ID ,
                InvoiceDue.I_Installment_No ,
                InvoiceDue.Dt_Installment_Date ,
                InvoiceDue.S_Component_Name ,
                InvoiceDue.N_Amount_Due ,
                InvoiceTax.S_Tax_Desc,
                ReceiptAmt.ReceiptCompAmount ,
                InvoiceTax.TotalTax ,
                ReceiptTax.ReceiptCompTax ,
                ( InvoiceDue.N_Amount_Due
                  - ISNULL(ReceiptAmt.ReceiptCompAmount, 0.0) ) AS BaseAmtDiff ,
                ( ISNULL(InvoiceTax.TotalTax, 0.0)
                  - ISNULL(ReceiptTax.ReceiptCompTax, 0.0) ) AS TaxDiff
        FROM    ( SELECT    TCHND.S_Center_Name ,
                            TCM.S_Course_Name ,
                            TSBM.S_Batch_Name ,
                            TSD.S_Student_ID ,
                            TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name,
                                                            '') + ' '
                            + TSD.S_Last_Name AS StudentName ,
                            TSD.S_Mobile_No AS ContactNo,
                            TSD.I_RollNo ,
                            TIP.I_Invoice_Header_ID ,
                            TIP.S_Invoice_No ,
                            TICD.I_Invoice_Detail_ID ,
                            TICD.I_Installment_No ,
                            TICD.Dt_Installment_Date ,
                            TFCM.S_Component_Name ,
                            TICD.N_Amount_Due
                  FROM      dbo.T_Invoice_Parent TIP
                            INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                            INNER JOIN dbo.T_Invoice_Child_Detail TICD ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID
                            INNER JOIN dbo.T_Fee_Component_Master TFCM ON TICD.I_Fee_Component_ID = TFCM.I_Fee_Component_ID
                            INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN ( SELECT T1.I_Student_ID ,
                                                T2.I_Batch_ID
                                         FROM   ( SELECT    TSBD2.I_Student_ID ,
                                                            MAX(TSBD2.I_Student_Batch_ID) AS ID
                                                  FROM      dbo.T_Student_Batch_Details TSBD2
                                                  WHERE     TSBD2.I_Status IN (
                                                            1, 3 )
                                                  GROUP BY  TSBD2.I_Student_ID
                                                ) T1
                                                INNER JOIN ( SELECT
                                                              TSBD3.I_Student_ID ,
                                                              TSBD3.I_Student_Batch_ID AS ID ,
                                                              TSBD3.I_Batch_ID
                                                             FROM
                                                              dbo.T_Student_Batch_Details TSBD3
                                                             WHERE
                                                              TSBD3.I_Status IN (
                                                              1, 3 )
                                                           ) T2 ON T1.I_Student_ID = T2.I_Student_ID
                                                              AND T1.ID = T2.ID
                                       ) TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                                                 AND TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                            INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                            INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                            INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                  WHERE     (TICD.Dt_Installment_Date >= @dtStartDate
                            AND TICD.Dt_Installment_Date < @dtEndDate)
                            AND TCHND.I_Center_ID IN (
                            SELECT  FGCFR.centerID
                            FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) FGCFR )
                            AND TIP.I_Status IN ( 1, 3 )
                            AND TSD.S_Student_ID='1415/RICE/12145'
--ORDER BY TSD.S_Student_ID,TIP.I_Invoice_Header_ID,TICD.Dt_Installment_Date,TICD.I_Installment_No,TFCM.S_Component_Name
                  
                ) InvoiceDue
                LEFT JOIN ( SELECT  I_Invoice_Detail_ID ,TTM.I_Tax_ID,TTM.S_Tax_Desc,
                                    ISNULL(SUM(ISNULL(TIDT.N_Tax_Value, 0.0)), 0.0) AS TotalTax
                            FROM    dbo.T_Invoice_Detail_Tax TIDT
                            LEFT JOIN dbo.T_Tax_Master AS TTM ON TTM.I_Tax_ID = TIDT.I_Tax_ID
                            GROUP BY I_Invoice_Detail_ID,TTM.I_Tax_ID,TTM.S_Tax_Desc
                          ) InvoiceTax ON InvoiceDue.I_Invoice_Detail_ID = InvoiceTax.I_Invoice_Detail_ID
                LEFT JOIN ( SELECT  TRCD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(TRCD.N_Amount_Paid), 0.0) AS ReceiptCompAmount
                            FROM    dbo.T_Receipt_Component_Detail TRCD
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                            WHERE   TRH.I_Status = 1
                            GROUP BY TRCD.I_Invoice_Detail_ID
                          ) ReceiptAmt ON InvoiceDue.I_Invoice_Detail_ID = ReceiptAmt.I_Invoice_Detail_ID
                LEFT JOIN ( SELECT  TRTD.I_Invoice_Detail_ID ,TTM.I_Tax_ID,TTM.S_Tax_Desc,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0.0)),
                                           0.0) AS ReceiptCompTax
                            FROM    dbo.T_Receipt_Tax_Detail TRTD
                                    INNER JOIN dbo.T_Receipt_Component_Detail TRCD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                                    LEFT JOIN dbo.T_Tax_Master AS TTM ON TTM.I_Tax_ID = TRTD.I_Tax_ID
                            WHERE   TRH.I_Status = 1
                            GROUP BY TRTD.I_Invoice_Detail_ID,TTM.I_Tax_ID,TTM.S_Tax_Desc
                          ) ReceiptTax ON InvoiceDue.I_Invoice_Detail_ID = ReceiptTax.I_Invoice_Detail_ID
        --ORDER BY InvoiceDue.S_Student_ID ,
        --        InvoiceDue.I_Invoice_Header_ID ,
        --        InvoiceDue.I_Installment_No ,
        --        InvoiceDue.Dt_Installment_Date ,
        --        InvoiceDue.S_Component_Name 
        ) Final
        WHERE
        (Final.TaxDiff+Final.BaseAmtDiff)!=0
        ORDER BY Final.S_Center_Name,Final.S_Course_Name,Final.S_Batch_Name,Final.S_Student_ID ,
                Final.I_Invoice_Header_ID ,
                Final.I_Installment_No ,
                Final.Dt_Installment_Date ,
                Final.S_Component_Name 
        
        
        
        --SELECT TSD.S_Student_ID,TRH.I_Invoice_Header_ID,SUM(TRH.N_Receipt_Amount)+SUM(TRH.N_Tax_Amount) AS TotalPaid FROM dbo.T_Receipt_Header TRH
        --INNER JOIN dbo.T_Student_Detail TSD ON TRH.I_Student_Detail_ID = TSD.I_Student_Detail_ID
        --WHERE
        --TRH.I_Status=1 AND TSD.S_Student_ID=@StudentID AND TRH.I_Invoice_Header_ID IS NOT NULL
        --GROUP BY TSD.S_Student_ID,TRH.I_Invoice_Header_ID
        
        OPTION(RECOMPILE);
        
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetMonthlyCollectableReport]...';


GO
CREATE PROCEDURE [REPORT].[uspGetMonthlyCollectableReport]
    (
      @iBrandID INT ,
      @sHierarchyListID VARCHAR(MAX) ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS
    BEGIN
    
        SET @dtEndDate = DATEADD(d, 1, @dtEndDate)
    
    
        CREATE TABLE #INVDET
            (
              S_Center_Name VARCHAR(MAX) ,
              TypeOfCentre VARCHAR(MAX) ,
              S_Course_Name VARCHAR(MAX) ,
              S_Batch_Name VARCHAR(MAX) ,
              S_Student_ID VARCHAR(MAX) ,
              StudentName VARCHAR(MAX) ,
              ContactNo VARCHAR(MAX) ,
              I_RollNo INT ,
              I_Invoice_Header_ID INT ,
              S_Invoice_No VARCHAR(MAX) ,
			  InvoiceCreationDate DATETIME,
              I_Invoice_Detail_ID INT ,
              I_Installment_No INT ,
              Dt_Installment_Date DATETIME ,
              S_Component_Name VARCHAR(MAX) ,
              N_Amount_Due DECIMAL(14, 2) ,
              TaxDue DECIMAL(14, 2) ,
              TaxPaidAdvBeforeGST DECIMAL(14, 2) ,
              TaxPaidAdvAfterGST DECIMAL(14, 2) ,
              TotalTax DECIMAL(14, 2) ,
              ReceiptCompAmount DECIMAL(14, 2) ,
              ReceiptCompTax DECIMAL(14, 2) ,
              CreditNoteNo VARCHAR(MAX) ,
              CreditNoteDate DATE ,
              CreditNoteAmt DECIMAL(14, 2) ,
              CreditNoteTax DECIMAL(14, 2) ,
              BaseAmtDiff DECIMAL(14, 2) ,
              TaxDiff DECIMAL(14, 2) ,
              TotalDiff DECIMAL(14, 2)
            )

        INSERT  INTO #INVDET
                ( S_Center_Name ,
                  TypeOfCentre ,
                  S_Course_Name ,
                  S_Batch_Name ,
                  S_Student_ID ,
                  StudentName ,
                  ContactNo ,
                  I_RollNo ,
                  I_Invoice_Header_ID ,
                  S_Invoice_No ,
				  InvoiceCreationDate,
                  I_Invoice_Detail_ID ,
                  I_Installment_No ,
                  Dt_Installment_Date ,
                  S_Component_Name ,
                  N_Amount_Due
                )
                SELECT  TCHND.S_Center_Name ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'IAS T%' THEN 'IAS'
                             WHEN TCM2.S_Center_Code LIKE 'Judiciary T%'
                             THEN 'Judiciary'
                             WHEN TCM2.S_Center_Code = 'BRST' THEN 'AIPT'
                             WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN 'Franchise'
                             ELSE 'Own'
                        END AS TypeofCentre ,
                        TCM.S_Course_Name ,
                        REPLACE(REPLACE(REPLACE(TSBM.S_Batch_Name, CHAR(9), ''), CHAR(10), ''), CHAR(13), '') ,
                        TSD.S_Student_ID ,
                        TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '')
                        + ' ' + TSD.S_Last_Name AS StudentName ,
                        TSD.S_Mobile_No AS ContactNo ,
                        TSD.I_RollNo ,
                        TIP.I_Invoice_Header_ID ,
                        TICD.S_Invoice_Number ,
						TIP.Dt_Crtd_On,
                        TICD.I_Invoice_Detail_ID ,
                        TICD.I_Installment_No ,
                        TICD.Dt_Installment_Date ,
                        TFCM.S_Component_Name ,
                        TICD.N_Amount_Due
                FROM    dbo.T_Invoice_Parent TIP
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Invoice_Child_Detail TICD ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Fee_Component_Master TFCM ON TICD.I_Fee_Component_ID = TFCM.I_Fee_Component_ID
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        --INNER JOIN ( SELECT T1.I_Student_ID ,
                        --                    T2.I_Batch_ID
                        --             FROM   ( SELECT    TSBD2.I_Student_ID ,
                        --                                MAX(TSBD2.I_Student_Batch_ID) AS ID
                        --                      FROM      dbo.T_Student_Batch_Details TSBD2
                        --                      WHERE     TSBD2.I_Status IN ( 1,
                        --                                      3 )
                        --                      GROUP BY  TSBD2.I_Student_ID
                        --                    ) T1
                        --                    INNER JOIN ( SELECT
                        --                                      TSBD3.I_Student_ID ,
                        --                                      TSBD3.I_Student_Batch_ID AS ID ,
                        --                                      TSBD3.I_Batch_ID
                        --                                 FROM dbo.T_Student_Batch_Details TSBD3
                        --                                 WHERE
                        --                                      TSBD3.I_Status IN (
                        --                                      1, 3 )
                        --                               ) T2 ON T1.I_Student_ID = T2.I_Student_ID
                        --                                      AND T1.ID = T2.ID
                        --           ) TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                        --                     AND TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN ( SELECT DISTINCT TIP1.I_Student_Detail_ID ,
                                            TIP1.I_Invoice_Header_ID ,
                                            TIBM.I_Batch_ID
                                     FROM   dbo.T_Invoice_Parent AS TIP1
                                            INNER JOIN dbo.T_Invoice_Child_Header
                                            AS TICH ON TICH.I_Invoice_Header_ID = TIP1.I_Invoice_Header_ID
                                            INNER JOIN dbo.T_Invoice_Batch_Map
                                            AS TIBM ON TIBM.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID AND TIBM.I_Status=1
                                     WHERE  --TIP.I_Invoice_Header_ID=119262 AND TIP.I_Student_Detail_ID=44346 --AND TIBM.I_Status=1
                                            TIP1.I_Centre_Id IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR ) --AND TIP1.I_Invoice_Header_ID=260338
                                   ) AS TSBD ON TSBD.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
                                                AND TSBD.I_Student_Detail_ID = TIP.I_Student_Detail_ID
                                                AND TSBD.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                                                              AND TIP.I_Centre_Id = TCM2.I_Centre_Id
                WHERE   ( TICD.Dt_Installment_Date >= @dtStartDate
                          AND TICD.Dt_Installment_Date < @dtEndDate
                        )
                        AND TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TIP.I_Status IN ( 0, 1, 3 )
                        AND TICD.I_Installment_No <> 0
                        AND ( TIP.Dt_Upd_On IS NULL
                              OR TIP.Dt_Upd_On >= '2017-07-01'
                            )
                --AND TSD.S_Student_ID = @StudentID
                            
        UPDATE  T1
        SET     T1.TaxDue = T2.TaxDue
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TIDT.I_Invoice_Detail_ID ,
                                    CASE WHEN TICD.Dt_Installment_Date < '2017-07-01'
                                         THEN ISNULL(SUM(ISNULL(TIDT.N_Tax_Value,
                                                              0)), 0)
                                         ELSE ISNULL(SUM(ISNULL(TIDT.N_Tax_Value_Scheduled,
                                                              0)), 0)
                                    END AS TaxDue
                             FROM   dbo.T_Invoice_Detail_Tax AS TIDT
                                    INNER JOIN dbo.T_Invoice_Child_Detail AS TICD ON TICD.I_Invoice_Detail_ID = TIDT.I_Invoice_Detail_ID
                             GROUP BY TIDT.I_Invoice_Detail_ID ,
                                    TICD.Dt_Installment_Date
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID


        UPDATE  T1
        SET     T1.TaxPaidAdvBeforeGST = T2.TaxPaidBeforeGST
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TICD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0)), 0) AS TaxPaidBeforeGST
                             FROM   dbo.T_Receipt_Header AS TRH
                                    INNER JOIN dbo.T_Receipt_Component_Detail
                                    AS TRCD ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                                    INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                                              AND TRTD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                    INNER JOIN dbo.T_Invoice_Child_Detail AS TICD ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND TICD.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                             WHERE  TRH.I_Status = 1
                                    AND TRH.Dt_Crtd_On < '2017-07-01'
                                    AND TICD.Dt_Installment_Date >= '2017-07-01'
                             GROUP BY TICD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID 


        UPDATE  T1
        SET     T1.TaxPaidAdvAfterGST = T2.TaxPaidAfterGST
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TICD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0)), 0) AS TaxPaidAfterGST
                             FROM   dbo.T_Receipt_Header AS TRH
                                    INNER JOIN dbo.T_Receipt_Component_Detail
                                    AS TRCD ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                                    INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                                              AND TRTD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                    INNER JOIN dbo.T_Invoice_Child_Detail AS TICD ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND TICD.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                             WHERE  TRH.I_Status = 1
                                    AND TRH.Dt_Crtd_On >= '2017-07-01'
                                    AND TICD.Dt_Installment_Date >= '2017-07-01'
                                    AND CONVERT(DATE, TRH.Dt_Crtd_On) < CONVERT(DATE, TICD.Dt_Installment_Date)
                             GROUP BY TICD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID 

        UPDATE  #INVDET
        SET     TotalTax = ISNULL(TaxDue, 0) + ISNULL(TaxPaidAdvBeforeGST, 0)
                + ISNULL(TaxPaidAdvAfterGST, 0)

        UPDATE  T1
        SET     T1.ReceiptCompAmount = T2.ReceiptCompAmount
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TRCD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(TRCD.N_Amount_Paid), 0.0) AS ReceiptCompAmount
                             FROM   dbo.T_Receipt_Component_Detail TRCD
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                             WHERE  TRH.I_Status = 1 --AND TRH.Dt_Crtd_On>='2019-02-01'
                             GROUP BY TRCD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID
                   
        UPDATE  T1
        SET     T1.ReceiptCompTax = T2.ReceiptCompTax
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TRTD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0.0)),
                                           0.0) AS ReceiptCompTax
                             FROM   dbo.T_Receipt_Tax_Detail TRTD
                                    INNER JOIN dbo.T_Receipt_Component_Detail TRCD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                             WHERE  TRH.I_Status = 1 --AND TRH.Dt_Crtd_On>='2019-02-01'
                             GROUP BY TRTD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID
                   
        UPDATE  T1
        SET     T1.CreditNoteAmt = T2.CreditNoteAmt ,
                T1.CreditNoteNo = T2.CreditNoteNo ,
                T1.CreditNoteDate = CASE WHEN CONVERT(DATE, T1.Dt_Installment_Date) > CONVERT(DATE, T2.Dt_Crtd_On)
                                         THEN T1.Dt_Installment_Date
                                         ELSE CONVERT(DATE, T2.Dt_Crtd_On)
                                    END
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number AS CreditNoteNo ,
                                    TCNICD.Dt_Crtd_On ,
                                    ISNULL(SUM(ISNULL(TCNICD.N_Amount, 0)), 0) AS CreditNoteAmt
                             FROM   dbo.T_Credit_Note_Invoice_Child_Detail AS TCNICD
                                    WITH ( NOLOCK )
                             GROUP BY TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number ,
                                    TCNICD.Dt_Crtd_On
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID 


        UPDATE  T1
        SET     T1.CreditNoteTax = T2.CreditNoteTax
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number AS CreditNoteNo ,
                                    ISNULL(SUM(ISNULL(TCNICDT.N_Tax_Value, 0)),
                                           0) AS CreditNoteTax
                             FROM   dbo.T_Credit_Note_Invoice_Child_Detail_Tax
                                    AS TCNICDT
                                    INNER JOIN dbo.T_Credit_Note_Invoice_Child_Detail
                                    AS TCNICD ON TCNICD.I_Invoice_Detail_ID = TCNICDT.I_Invoice_Detail_ID
                                                 AND TCNICD.I_Credit_Note_Invoice_Child_Detail_ID = TCNICDT.I_Credit_Note_Invoice_Child_Detail_ID
                             GROUP BY TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID
                                   AND T2.CreditNoteNo = T1.CreditNoteNo                 
                   
                   
        UPDATE  #INVDET
        SET     BaseAmtDiff = N_Amount_Due - ISNULL(ReceiptCompAmount, 0)
                - ISNULL(CreditNoteAmt, 0)
        UPDATE  #INVDET
        SET     TaxDiff = ISNULL(TotalTax, 0) - ISNULL(ReceiptCompTax, 0)
                - ISNULL(CreditNoteTax, 0)
        UPDATE  #INVDET
        SET     TotalDiff = BaseAmtDiff + TaxDiff
        OPTION  ( RECOMPILE )                                  
                            
        SELECT  *
        FROM    #INVDET AS I
        ORDER BY I.S_Center_Name ,
                I.S_Course_Name ,
                I.S_Batch_Name ,
                I.S_Student_ID ,
                I.I_Invoice_Header_ID ,
                I.I_Installment_No 




--OPTION(RECOMPILE);
    
		




        
        
        
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetMonthwiseInvoiceAmountTemp]...';


GO
CREATE PROCEDURE REPORT.uspGetMonthwiseInvoiceAmountTemp
(
@iBrandID INT,
@sHierarchyListID VARCHAR(MAX),
@dtStartDate DATE,
@dtEndDate DATE
)

AS 
    BEGIN

        CREATE TABLE #temp
            (
              BrandName VARCHAR(MAX) ,
              CenterName VARCHAR(MAX) ,
              CourseName VARCHAR(MAX) ,
              BatchID INT,
              BatchName VARCHAR(MAX) ,
              BatchStartDate DATE ,
              BatchStartMonth VARCHAR(MAX),
              StudentID VARCHAR(MAX) ,
              --AdmissionDate DATE,
              --AdmissionMonth VARCHAR(MAX),
              InvoiceHeaderID INT ,
              InvoiceDate DATE ,
              InvoiceNo VARCHAR(MAX) ,
              InvoiceAmount DECIMAL(14, 2) ,
              AmountPaidBeforeBatchStart DECIMAL(14, 2) ,
              AmountPaidAtBatchStart DECIMAL(14, 2) ,
              AmountPaidAfterBatchStart DECIMAL(14, 2) ,
              AmountRemaining DECIMAL(14, 2)
            )

        INSERT  INTO #temp
                ( BrandName ,
                  CenterName ,
                  CourseName ,
                  BatchID,
                  BatchName ,
                  BatchStartDate ,
                  BatchStartMonth,
                  StudentID ,
                  --AdmissionDate,
                  --AdmissionMonth,
                  InvoiceHeaderID ,
                  InvoiceDate ,
                  InvoiceNo ,
                  InvoiceAmount
                )
                SELECT	DISTINCT
                        TCHND.S_Brand_Name ,
                        TCHND.S_Center_Name ,
                        TCM.S_Course_Name ,
                        TSBM.I_Batch_ID,
                        TSBM.S_Batch_Name ,
                        CONVERT(DATE, TSBM.Dt_BatchStartDate) AS BatchStartDate ,
                        CAST(DATENAME(MONTH,TSBM.Dt_BatchStartDate)+' '+CAST(DATEPART(YYYY,TSBM.Dt_BatchStartDate) AS VARCHAR) AS VARCHAR) AS BatchStartMonth,
                        TSD.S_Student_ID ,
                        --CONVERT(DATE, TSD.Dt_Crtd_On) AS AdmissionDate ,
                        --CAST(DATENAME(MONTH,TSD.Dt_Crtd_On)+' '+CAST(DATEPART(YYYY,TSD.Dt_Crtd_On) AS VARCHAR) AS VARCHAR) AS AdmissionMonth,
                        TIP.I_Invoice_Header_ID ,
                        CONVERT(DATE, TIP.Dt_Crtd_On) AS InvoiceDate ,
                        TIP.S_Invoice_No ,
                        TIP.N_Invoice_Amount
                FROM    dbo.T_Student_Batch_Master TSBM
                        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TSBM.I_Batch_ID = TIBM.I_Batch_ID
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIBM.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Invoice_Parent TIP ON TICH.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Student_Batch_Details TSBD ON TSBM.I_Batch_ID = TSBD.I_Batch_ID
                                                              AND TIBM.I_Batch_ID = TSBD.I_Batch_ID
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD.I_Student_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        --INNER JOIN dbo.T_Invoice_Child_Detail TICD ON TICH.I_Invoice_Child_Header_ID=TICD.I_Invoice_Child_Header_ID
                    --INNER JOIN dbo.T_Receipt_Header TRH ON TIP.I_Invoice_Header_ID = TRH.I_Invoice_Header_ID
                WHERE   TCHND.I_Brand_ID =@iBrandID
                        AND TIP.I_Status IN ( 1, 3 )
                        AND TSBD.I_Status = 1
                        AND ( TSBM.Dt_BatchStartDate >= @dtStartDate
                              AND TSBM.Dt_BatchStartDate < DATEADD(d,1,@dtEndDate)
                            )
                        AND TCHND.I_Center_ID IN (SELECT FGCFR.centerID FROM dbo.fnGetCentersForReports(@sHierarchyListID,@iBrandID) FGCFR)    
                ORDER BY TCHND.S_Brand_Name ,
                        TCHND.S_Center_Name ,
                        TCM.S_Course_Name ,
                        TSBM.S_Batch_Name ,
                        TSD.S_Student_ID
                    
        UPDATE  T2
        SET     T2.AmountPaidBeforeBatchStart = T3.ReceiptAmountBeforeBatchStart
        FROM    #temp T2
                INNER JOIN ( 
                
                SELECT TRH.I_Invoice_Header_ID ,
                                    SUM(ISNULL(TRH.N_Receipt_Amount, 0.00)) AS ReceiptAmountBeforeBatchStart
                             FROM   dbo.T_Receipt_Header TRH
                                    INNER JOIN #temp T1 ON TRH.I_Invoice_Header_ID = T1.InvoiceHeaderID
                             WHERE  TRH.I_Status = 1
                                    AND DATEDIFF(m, T1.BatchStartDate,
                                                 TRH.Dt_Receipt_Date) < 0
                             GROUP BY TRH.I_Invoice_Header_ID
                             
                            
                           ) T3 ON T2.InvoiceHeaderID = T3.I_Invoice_Header_ID
                           
                           
                           
                           
                    
                    
        UPDATE  T2
        SET     T2.AmountPaidAtBatchStart = T3.ReceiptAmountAtBatchStart
        FROM    #temp T2
                INNER JOIN ( SELECT TRH.I_Invoice_Header_ID ,
                                    SUM(ISNULL(TRH.N_Receipt_Amount, 0.00)) AS ReceiptAmountAtBatchStart
                             FROM   dbo.T_Receipt_Header TRH
                                    INNER JOIN #temp T1 ON TRH.I_Invoice_Header_ID = T1.InvoiceHeaderID
                             WHERE  TRH.I_Status = 1
                                    AND DATEDIFF(m, T1.BatchStartDate,
                                                 TRH.Dt_Receipt_Date) = 0
                             GROUP BY TRH.I_Invoice_Header_ID
                           ) T3 ON T2.InvoiceHeaderID = T3.I_Invoice_Header_ID
                    
                    
        UPDATE  T2
        SET     T2.AmountPaidAfterBatchStart = T3.ReceiptAmountAfterBatchStart
        FROM    #temp T2
                INNER JOIN ( SELECT TRH.I_Invoice_Header_ID ,
                                    SUM(ISNULL(TRH.N_Receipt_Amount, 0.00)) AS ReceiptAmountAfterBatchStart
                             FROM   dbo.T_Receipt_Header TRH
                                    INNER JOIN #temp T1 ON TRH.I_Invoice_Header_ID = T1.InvoiceHeaderID
                             WHERE  TRH.I_Status = 1
                                    AND DATEDIFF(m, T1.BatchStartDate,
                                                 TRH.Dt_Receipt_Date) > 0
                             GROUP BY TRH.I_Invoice_Header_ID
                           ) T3 ON T2.InvoiceHeaderID = T3.I_Invoice_Header_ID
                    
                    
        UPDATE  #temp
        SET     AmountRemaining = InvoiceAmount
                - ISNULL(AmountPaidBeforeBatchStart, 0.00)
                - ISNULL(AmountPaidAtBatchStart, 0.00)
                - ISNULL(AmountPaidAfterBatchStart, 0.00)
                        
                        
                        
        SELECT  *
        FROM    #temp T1
 
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetMonthlyExamPerformanceAnalysisReport]...';


GO
CREATE PROC [REPORT].[uspGetMonthlyExamPerformanceAnalysisReport]
    (
      @dtStartDate DATE ,
      @dtEndDate DATE ,
      @sHierarchyID VARCHAR(MAX) ,
      @iBrandID INT ,
      @iStudentID INT = NULL ,
      @iBatchID INT ,
      @sExamComponentID VARCHAR(MAX) = NULL
    )
AS 
    BEGIN

        CREATE TABLE #examComp ( ExamCompID INT )

        INSERT  INTO #examComp
                ( ExamCompID 
                )
                SELECT  FSR.Val
                FROM    dbo.fnString2Rows(@sExamComponentID, ',') FSR

        IF ( SELECT COUNT(ExamCompID)
             FROM   #examComp EC
           ) = 0 
            BEGIN
                INSERT  INTO #examComp
                        ( ExamCompID 
                        )
                        SELECT  I_Exam_Component_ID
                        FROM    dbo.T_Exam_Component_Master TECM
                        WHERE   I_Brand_ID = @iBrandID
                                AND I_Status = 1

            END

        CREATE TABLE #studentid ( StudentID INT )

        IF @iStudentID IS NULL 
            BEGIN
                INSERT  INTO #studentid
                        ( StudentID 
                        )
                        SELECT  TSD.I_Student_Detail_ID
                        FROM    dbo.T_Student_Detail TSD
                                INNER JOIN dbo.T_Student_Batch_Details TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                        WHERE   TSBD.I_Status = 1
                                AND TSBD.I_Batch_ID = @iBatchID 
            END
        ELSE 
            BEGIN
                INSERT  INTO #studentid
                        ( StudentID )
                VALUES  ( @iStudentID  -- StudentID - int
                          )
            END

--SELECT * FROM #studentid S;

--SELECT * FROM #examComp EC;



        SELECT  TCHND.I_Center_ID ,
                TCHND.S_Center_Name ,
                TSD.I_Student_Detail_ID ,
                TSD.S_Student_ID ,
                TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '') + ' '
                + TSD.S_Last_Name AS StudentName ,
                TSD.S_Mobile_No,
                TSD.S_Phone_No,
                TTM.I_Term_ID ,
                TTM.S_Term_Name ,
                TSBM.I_Batch_ID ,
                TSBM.S_Batch_Name ,
                TECM.I_Exam_Component_ID ,
                TECM.S_Component_Name ,
                TSM.I_Exam_Total ,
                TTES.I_TotMarks ,
                TECM.S_Component_Name + ' ('
                + CAST(TTES.I_TotMarks AS VARCHAR) + ')' AS ExamTot
        FROM    EXAMINATION.T_Student_Marks TSM
                INNER JOIN EXAMINATION.T_Batch_Exam_Map TBEM ON TSM.I_Batch_Exam_ID = TBEM.I_Batch_Exam_ID
                INNER JOIN dbo.T_Student_Batch_Master TSBM ON TBEM.I_Batch_ID = TSBM.I_Batch_ID
                INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCHND.I_Center_ID = TCBD.I_Centre_Id
                INNER JOIN dbo.T_Student_Detail TSD ON TSM.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                INNER JOIN dbo.T_Term_Master TTM ON TBEM.I_Term_ID = TTM.I_Term_ID
--INNER JOIN dbo.T_Term_Eval_Strategy TTES ON TBEM.I_Exam_Component_ID=TTES.I_Exam_Component_ID
                INNER JOIN dbo.T_Exam_Component_Master TECM ON TBEM.I_Exam_Component_ID = TECM.I_Exam_Component_ID
                INNER JOIN dbo.T_Term_Eval_Strategy TTES ON TECM.I_Exam_Component_ID = TTES.I_Exam_Component_ID
                                                            AND TCM.I_Course_ID = TTES.I_Course_ID
                                                            AND TTM.I_Term_ID = TTES.I_Term_ID
        WHERE   TCHND.I_Center_ID IN (
                SELECT  FGCFR.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyID, @iBrandID) FGCFR )
                AND TSM.Dt_Exam_Date >= @dtStartDate
                AND TSM.Dt_Exam_Date < DATEADD(d,1,@dtEndDate)
                --AND TSBM.I_Batch_ID=@iBatchID
                AND TCM.I_Status = 1
                AND TTM.I_Status = 1
                AND TECM.I_Status = 1
                AND TSD.I_Student_Detail_ID IN ( SELECT S.StudentID
                                                 FROM   #studentid S )
                AND TECM.I_Exam_Component_ID IN ( SELECT    EC.ExamCompID
                                                  FROM      #examComp EC )
                AND TTES.I_Status = 1
        ORDER BY TCHND.I_Center_ID ,
                TSD.I_Student_Detail_ID ,
                TTM.I_Term_ID ,
                TECM.I_Exam_Component_ID
        --END
        
        
    END
GO
