--                        ) TEMP ON A.I_Student_Detail_ID = TEMP.I_Student_Detail_ID
--                                  AND C.I_Batch_ID = TEMP.I_Batch_ID
--                WHERE   --B.I_Batch_ID LIKE COALESCE(@ibatchID,B.I_Batch_ID)   
--                        ( @sBatchIDs IS NULL
--                          OR B.I_Batch_ID IN (
