CREATE PROCEDURE [REPORT].[uspGetMonthlyCollectableReportHistorical]
    (
      @iBrandID INT ,
      @sHierarchyListID VARCHAR(MAX) ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS
    BEGIN
    
        SET @dtEndDate = DATEADD(d, 1, @dtEndDate)
    
    
        CREATE TABLE #INVDET
            (
              S_Center_Name VARCHAR(MAX) ,
              TypeOfCentre VARCHAR(MAX) ,
              S_Course_Name VARCHAR(MAX) ,
              S_Batch_Name VARCHAR(MAX) ,
              S_Student_ID VARCHAR(MAX) ,
              StudentName VARCHAR(MAX) ,
              ContactNo VARCHAR(MAX) ,
              I_RollNo INT ,
              I_Invoice_Header_ID INT ,
              S_Invoice_No VARCHAR(MAX) ,
			  InvoiceCreationDate DATETIME,
              I_Invoice_Detail_ID INT ,
              I_Installment_No INT ,
              Dt_Installment_Date DATETIME ,
              S_Component_Name VARCHAR(MAX) ,
              N_Amount_Due DECIMAL(14, 2) ,
              TaxDue DECIMAL(14, 2) ,
              TaxPaidAdvBeforeGST DECIMAL(14, 2) ,
              TaxPaidAdvAfterGST DECIMAL(14, 2) ,
              TotalTax DECIMAL(14, 2) ,
              ReceiptCompAmount DECIMAL(14, 2) ,
              ReceiptCompTax DECIMAL(14, 2) ,
              CreditNoteNo VARCHAR(MAX) ,
              CreditNoteDate DATE ,
              CreditNoteAmt DECIMAL(14, 2) ,
              CreditNoteTax DECIMAL(14, 2) ,
              BaseAmtDiff DECIMAL(14, 2) ,
              TaxDiff DECIMAL(14, 2) ,
              TotalDiff DECIMAL(14, 2)
            )

        INSERT  INTO #INVDET
                ( S_Center_Name ,
                  TypeOfCentre ,
                  S_Course_Name ,
                  S_Batch_Name ,
                  S_Student_ID ,
                  StudentName ,
                  ContactNo ,
                  I_RollNo ,
                  I_Invoice_Header_ID ,
                  S_Invoice_No ,
				  InvoiceCreationDate,
                  I_Invoice_Detail_ID ,
                  I_Installment_No ,
                  Dt_Installment_Date ,
                  S_Component_Name ,
                  N_Amount_Due
                )
                SELECT  TCHND.S_Center_Name ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'IAS T%' THEN 'IAS'
                             WHEN TCM2.S_Center_Code LIKE 'Judiciary T%'
                             THEN 'Judiciary'
                             WHEN TCM2.S_Center_Code = 'BRST' THEN 'AIPT'
                             WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN 'Franchise'
                             ELSE 'Own'
                        END AS TypeofCentre ,
                        TCM.S_Course_Name ,
                        REPLACE(REPLACE(REPLACE(TSBM.S_Batch_Name, CHAR(9), ''), CHAR(10), ''), CHAR(13), '') ,
                        TSD.S_Student_ID ,
                        TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '')
                        + ' ' + TSD.S_Last_Name AS StudentName ,
                        TSD.S_Mobile_No AS ContactNo ,
                        TSD.I_RollNo ,
                        TIP.I_Invoice_Header_ID ,
                        TICD.S_Invoice_Number ,
						TIP.Dt_Crtd_On,
                        TICD.I_Invoice_Detail_ID ,
                        TICD.I_Installment_No ,
                        TICD.Dt_Installment_Date ,
                        TFCM.S_Component_Name ,
                        TICD.N_Amount_Due
                FROM    dbo.T_Invoice_Parent TIP
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Invoice_Child_Detail TICD ON TICH.I_Invoice_Child_Header_ID = TICD.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Fee_Component_Master TFCM ON TICD.I_Fee_Component_ID = TFCM.I_Fee_Component_ID
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        --INNER JOIN ( SELECT T1.I_Student_ID ,
                        --                    T2.I_Batch_ID
                        --             FROM   ( SELECT    TSBD2.I_Student_ID ,
                        --                                MAX(TSBD2.I_Student_Batch_ID) AS ID
                        --                      FROM      dbo.T_Student_Batch_Details TSBD2
                        --                      WHERE     TSBD2.I_Status IN ( 1,
                        --                                      3 )
                        --                      GROUP BY  TSBD2.I_Student_ID
                        --                    ) T1
                        --                    INNER JOIN ( SELECT
                        --                                      TSBD3.I_Student_ID ,
                        --                                      TSBD3.I_Student_Batch_ID AS ID ,
                        --                                      TSBD3.I_Batch_ID
                        --                                 FROM dbo.T_Student_Batch_Details TSBD3
                        --                                 WHERE
                        --                                      TSBD3.I_Status IN (
                        --                                      1, 3 )
                        --                               ) T2 ON T1.I_Student_ID = T2.I_Student_ID
                        --                                      AND T1.ID = T2.ID
                        --           ) TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                        --                     AND TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN ( SELECT DISTINCT TIP1.I_Student_Detail_ID ,
                                            TIP1.I_Invoice_Header_ID ,
                                            TIBM.I_Batch_ID
                                     FROM   dbo.T_Invoice_Parent AS TIP1
                                            INNER JOIN dbo.T_Invoice_Child_Header
                                            AS TICH ON TICH.I_Invoice_Header_ID = TIP1.I_Invoice_Header_ID
                                            INNER JOIN dbo.T_Invoice_Batch_Map
                                            AS TIBM ON TIBM.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID AND TIBM.I_Status in (1,0)
                                     WHERE  --TIP.I_Invoice_Header_ID=119262 AND TIP.I_Student_Detail_ID=44346 --AND TIBM.I_Status=1
                                            TIP1.I_Centre_Id IN (
                                            SELECT  FGCFR.centerID
                                            FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR ) --AND TIP1.I_Invoice_Header_ID=260338
                                   ) AS TSBD ON TSBD.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
                                                AND TSBD.I_Student_Detail_ID = TIP.I_Student_Detail_ID
                                                AND TSBD.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                                                              AND TIP.I_Centre_Id = TCM2.I_Centre_Id
                WHERE   ( TICD.Dt_Installment_Date >= @dtStartDate
                          AND TICD.Dt_Installment_Date < @dtEndDate
                        )
                        AND TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TIP.I_Status IN ( 0, 1, 3 )
                        AND TICD.I_Installment_No <> 0
                        AND ( TIP.Dt_Upd_On IS NULL
                              OR TIP.Dt_Upd_On >= '2017-07-01'
                            )
                --AND TSD.S_Student_ID = @StudentID
                            
        UPDATE  T1
        SET     T1.TaxDue = T2.TaxDue
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TIDT.I_Invoice_Detail_ID ,
                                    CASE WHEN TICD.Dt_Installment_Date < '2017-07-01'
                                         THEN ISNULL(SUM(ISNULL(TIDT.N_Tax_Value,
                                                              0)), 0)
                                         ELSE ISNULL(SUM(ISNULL(TIDT.N_Tax_Value_Scheduled,
                                                              0)), 0)
                                    END AS TaxDue
                             FROM   dbo.T_Invoice_Detail_Tax AS TIDT
                                    INNER JOIN dbo.T_Invoice_Child_Detail AS TICD ON TICD.I_Invoice_Detail_ID = TIDT.I_Invoice_Detail_ID
                             GROUP BY TIDT.I_Invoice_Detail_ID ,
                                    TICD.Dt_Installment_Date
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID


        UPDATE  T1
        SET     T1.TaxPaidAdvBeforeGST = T2.TaxPaidBeforeGST
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TICD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0)), 0) AS TaxPaidBeforeGST
                             FROM   dbo.T_Receipt_Header AS TRH
                                    INNER JOIN dbo.T_Receipt_Component_Detail
                                    AS TRCD ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                                    INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                                              AND TRTD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                    INNER JOIN dbo.T_Invoice_Child_Detail AS TICD ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND TICD.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                             WHERE  TRH.I_Status = 1
                                    AND TRH.Dt_Crtd_On < '2017-07-01'
                                    AND TICD.Dt_Installment_Date >= '2017-07-01'
                             GROUP BY TICD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID 


        UPDATE  T1
        SET     T1.TaxPaidAdvAfterGST = T2.TaxPaidAfterGST
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TICD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0)), 0) AS TaxPaidAfterGST
                             FROM   dbo.T_Receipt_Header AS TRH
                                    INNER JOIN dbo.T_Receipt_Component_Detail
                                    AS TRCD ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                                    INNER JOIN dbo.T_Receipt_Tax_Detail AS TRTD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                                              AND TRTD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                    INNER JOIN dbo.T_Invoice_Child_Detail AS TICD ON TICD.I_Invoice_Detail_ID = TRCD.I_Invoice_Detail_ID
                                                              AND TICD.I_Invoice_Detail_ID = TRTD.I_Invoice_Detail_ID
                             WHERE  TRH.I_Status = 1
                                    AND TRH.Dt_Crtd_On >= '2017-07-01'
                                    AND TICD.Dt_Installment_Date >= '2017-07-01'
                                    AND CONVERT(DATE, TRH.Dt_Crtd_On) < CONVERT(DATE, TICD.Dt_Installment_Date)
                             GROUP BY TICD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID 

        UPDATE  #INVDET
        SET     TotalTax = ISNULL(TaxDue, 0) + ISNULL(TaxPaidAdvBeforeGST, 0)
                + ISNULL(TaxPaidAdvAfterGST, 0)

        UPDATE  T1
        SET     T1.ReceiptCompAmount = T2.ReceiptCompAmount
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TRCD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(TRCD.N_Amount_Paid), 0.0) AS ReceiptCompAmount
                             FROM   dbo.T_Receipt_Component_Detail TRCD
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                             WHERE  TRH.I_Status = 1 --AND TRH.Dt_Crtd_On>='2019-02-01'
                             GROUP BY TRCD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID
                   
        UPDATE  T1
        SET     T1.ReceiptCompTax = T2.ReceiptCompTax
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TRTD.I_Invoice_Detail_ID ,
                                    ISNULL(SUM(ISNULL(TRTD.N_Tax_Paid, 0.0)),
                                           0.0) AS ReceiptCompTax
                             FROM   dbo.T_Receipt_Tax_Detail TRTD
                                    INNER JOIN dbo.T_Receipt_Component_Detail TRCD ON TRTD.I_Receipt_Comp_Detail_ID = TRCD.I_Receipt_Comp_Detail_ID
                                    INNER JOIN dbo.T_Receipt_Header TRH ON TRCD.I_Receipt_Detail_ID = TRH.I_Receipt_Header_ID
                             WHERE  TRH.I_Status = 1 --AND TRH.Dt_Crtd_On>='2019-02-01'
                             GROUP BY TRTD.I_Invoice_Detail_ID
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID
                   
        UPDATE  T1
        SET     T1.CreditNoteAmt = T2.CreditNoteAmt ,
                T1.CreditNoteNo = T2.CreditNoteNo ,
                T1.CreditNoteDate = CASE WHEN CONVERT(DATE, T1.Dt_Installment_Date) > CONVERT(DATE, T2.Dt_Crtd_On)
                                         THEN T1.Dt_Installment_Date
                                         ELSE CONVERT(DATE, T2.Dt_Crtd_On)
                                    END
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number AS CreditNoteNo ,
                                    TCNICD.Dt_Crtd_On ,
                                    ISNULL(SUM(ISNULL(TCNICD.N_Amount, 0)), 0) AS CreditNoteAmt
                             FROM   dbo.T_Credit_Note_Invoice_Child_Detail AS TCNICD
                                    WITH ( NOLOCK )
                             GROUP BY TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number ,
                                    TCNICD.Dt_Crtd_On
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID 


        UPDATE  T1
        SET     T1.CreditNoteTax = T2.CreditNoteTax
        FROM    #INVDET AS T1
                INNER JOIN ( SELECT TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number AS CreditNoteNo ,
                                    ISNULL(SUM(ISNULL(TCNICDT.N_Tax_Value, 0)),
                                           0) AS CreditNoteTax
                             FROM   dbo.T_Credit_Note_Invoice_Child_Detail_Tax
                                    AS TCNICDT
                                    INNER JOIN dbo.T_Credit_Note_Invoice_Child_Detail
                                    AS TCNICD ON TCNICD.I_Invoice_Detail_ID = TCNICDT.I_Invoice_Detail_ID
                                                 AND TCNICD.I_Credit_Note_Invoice_Child_Detail_ID = TCNICDT.I_Credit_Note_Invoice_Child_Detail_ID
                             GROUP BY TCNICD.I_Invoice_Detail_ID ,
                                    TCNICD.S_Invoice_Number
                           ) T2 ON T2.I_Invoice_Detail_ID = T1.I_Invoice_Detail_ID
                                   AND T2.CreditNoteNo = T1.CreditNoteNo                 
                   
                   
        UPDATE  #INVDET
        SET     BaseAmtDiff = N_Amount_Due - ISNULL(ReceiptCompAmount, 0)
                - ISNULL(CreditNoteAmt, 0)
        UPDATE  #INVDET
        SET     TaxDiff = ISNULL(TotalTax, 0) - ISNULL(ReceiptCompTax, 0)
                - ISNULL(CreditNoteTax, 0)
        UPDATE  #INVDET
        SET     TotalDiff = BaseAmtDiff + TaxDiff
        OPTION  ( RECOMPILE )                                  
                            
        SELECT  *
        FROM    #INVDET AS I
        ORDER BY I.S_Center_Name ,
                I.S_Course_Name ,
                I.S_Batch_Name ,
                I.S_Student_ID ,
                I.I_Invoice_Header_ID ,
                I.I_Installment_No 




--OPTION(RECOMPILE);
    
		




        
        
        
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetOutstandingStatementSummaryForGraph]...';


GO
--EXEC [REPORT].[uspGetOutstandingStatementReport] '104',22,'29-Aug-2008'
CREATE PROCEDURE [REPORT].[uspGetOutstandingStatementSummaryForGraph]
(
	-- Add the parameters for the stored procedure here
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@sCenterIDs VARCHAR(MAX),
	@dtUptoDate datetime,
	@sStatus Varchar(100)
)
AS
BEGIN TRY

	SET NOCOUNT ON;

	Declare @StudentStatus Int

	If (@sStatus='ALL')
		Begin
			Set @StudentStatus=NULL
		End	
	Else If(@sStatus='Active')
		Begin
			Set @StudentStatus=1
		End
	Else If(@sStatus='Dropped Out')
		Begin
			Set @StudentStatus=0
		End
	
	DECLARE @index INT, @rowCount INT, @iTempCenterID INT
	DECLARE @tblCenter TABLE(ID INT IDENTITY(1,1), CenterId INT)

	DECLARE @iHierarchDetailID INT, @sHierarchyChain VARCHAR(100)
	DECLARE @CenterName VARCHAR(100), @BrandID INT, @BrandName VARCHAR(100), @RegionID INT, 
		@RegionName VARCHAR(100), @TerritoryID INT, @TerritoryName VARCHAR(100), @CityID INT, @CityName VARCHAR(100)
		
	DECLARE @tblTempHierarchy TABLE (ID INT)

	INSERT INTO @tblCenter
	SELECT CAST([Val] AS INT) FROM [dbo].[fnString2Rows](@sCenterIDs, ',') AS FSR
	
	IF ((SELECT COUNT(ID) FROM @tblCenter) = 0)
	BEGIN
		INSERT INTO @tblCenter
		SELECT [I_Center_ID] FROM [dbo].[fnGetCenterIDFromHierarchy](@sHierarchyList, @iBrandID) AS FGCIFH
	END
	
	 SELECT IP.I_Invoice_Header_ID,
			IP.I_Centre_Id,
			IP.I_Student_Detail_ID,
			SD.S_Student_ID,
			SD.S_Title,
			SD.S_First_Name,
			SD.S_Middle_Name,
			SD.S_Last_Name,
			IP.S_Invoice_No AS Invoice_No,
			IP.Dt_Invoice_Date AS Invoice_Date,
			ISNULL(IP.N_Invoice_Amount,0.00) AS Invoice_Amount,
			ISNULL(IP.N_Tax_Amount,0.00) AS Tax_Amount,
			ISNULL(IP.N_Discount_Amount,0.00) AS N_Discount_Amount,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code,
			--SUM(ISNULL(RH.N_Receipt_Amount,0.00)) AS Receipt_Amount,
			(Select SUM(ISNULL(N_Receipt_Amount,0.00)) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=IP.I_Invoice_Header_ID AND I_Status <> 0)  AS Receipt_Amount,
			(ISNULL(IP.N_Invoice_Amount,0.00) 
			--- SUM(ISNULL(RH.N_Receipt_Amount,0.00))) AS Outstanding_Amt,
			-(Select ISNULL(SUM(ISNULL(N_Receipt_Amount,0.00)),0) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=IP.I_Invoice_Header_ID AND I_Status <> 0)) AS Outstanding_Amt,
			--MAX(RH.Dt_Receipt_Date) AS Last_Install_Date
			(Select MAX(Dt_Receipt_Date) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=IP.I_Invoice_Header_ID AND I_Status <> 0)  AS Last_Install_Date
	   INTO #TmpOutStandingRpt1
	   FROM dbo.T_Student_Detail SD WITH(NOLOCK)
			INNER JOIN dbo.T_Invoice_Parent IP WITH(NOLOCK)
		    ON SD.I_Student_Detail_ID = IP.I_Student_Detail_ID
			INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
			ON IP.I_Centre_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
			ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
			LEFT OUTER JOIN dbo.T_Receipt_Header RH WITH(NOLOCK)
			ON IP.I_Invoice_Header_ID=RH.I_Invoice_Header_ID
			INNER JOIN dbo.T_Centre_Master CEM WITH(NOLOCK)
			ON FN1.CenterID=CEM.I_Centre_Id
			INNER JOIN dbo.T_Country_Master COM WITH(NOLOCK)
			ON CEM.I_Country_ID=COM.I_Country_ID
			INNER JOIN dbo.T_Currency_Master CUM WITH(NOLOCK)
			ON COM.I_Currency_ID=CUM.I_Currency_ID
		WHERE CAST(SUBSTRING(CAST(IP.Dt_Invoice_Date AS VARCHAR),1,11) as datetime)<= @dtUptoDate
		AND (CAST(SUBSTRING(CAST(RH.Dt_Receipt_Date AS VARCHAR),1,11) as datetime) <= @dtUptoDate OR RH.Dt_Receipt_Date IS NULL)
		AND IP.I_STATUS <> 0
		AND SD.I_STATUS= ISNULL(@StudentStatus,SD.I_STATUS)
		AND [SD].[I_Student_Detail_ID] NOT IN 
			(SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM)
		--AND RH.I_Status <> 0
		GROUP BY IP.I_Invoice_Header_ID,
			IP.I_Centre_Id,
			IP.I_Student_Detail_ID,
			SD.S_Student_ID,
			SD.S_Title,
			SD.S_First_Name,
			SD.S_Middle_Name,
			SD.S_Last_Name,
			IP.S_Invoice_No,
			IP.Dt_Invoice_Date,
			IP.N_Invoice_Amount,
			IP.N_Tax_Amount,
			IP.N_Discount_Amount,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code
				
		 SELECT TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--ICH.I_Course_ID,
				ICH.I_Invoice_Child_Header_ID,
				--CM.S_Course_Code AS Course_Code,
				--CM.S_Course_Name AS Course_Name,
				--SUM(ISNULL(RH.N_Receipt_Amount,0.00)) AS Last_Install_Amount,
				(Select SUM(ISNULL(N_Receipt_Amount,0.00)) FROM dbo.T_Receipt_Header WHERE I_Invoice_Header_ID=TMP.I_Invoice_Header_ID AND I_Status <> 0 AND Dt_Receipt_Date=TMP.Last_Install_Date)  AS Last_Install_Amount,
				[REPORT].[fnGetStudentStatusForReports](TMP.I_Student_Detail_ID,TMP.I_Centre_Id,@dtUptoDate) AS Student_Status
		   INTO #TmpOutStandingRpt2
		   FROM #TmpOutStandingRpt1 TMP
				INNER JOIN dbo.T_Invoice_Child_Header ICH WITH(NOLOCK)
				ON TMP.I_Invoice_Header_ID=ICH.I_Invoice_Header_ID
				--INNER JOIN dbo.T_Course_Master CM WITH(NOLOCK)
				--ON ICH.I_Course_ID=CM.I_Course_ID		
				LEFT OUTER JOIN dbo.T_Receipt_Header RH WITH(NOLOCK)
				ON TMP.I_Invoice_Header_ID=RH.I_Invoice_Header_ID
				AND TMP.Last_Install_Date=RH.Dt_Receipt_Date 
		  --WHERE [REPORT].[fnGetStudentStatusForReports](TMP.I_Student_Detail_ID,TMP.I_Centre_Id,@dtUptoDate)='Active'
		  --AND TMP.Outstanding_Amt>10
			WHERE TMP.Outstanding_Amt > 10
			--AND RH.I_Status <> 0
			GROUP BY TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--ICH.I_Course_ID,
				ICH.I_Invoice_Child_Header_ID--,
				--CM.S_Course_Code,
				--CM.S_Course_Name

		--Finding Last Date of the Month
		DECLARE @vOutputDate DATETIME
		SET @vOutputDate = CAST(YEAR(@dtUptoDate) AS VARCHAR(4)) + '/' + CAST(MONTH(@dtUptoDate) AS VARCHAR(2)) + '/01'
		SET @vOutputDate = DATEADD(DD, -1, DATEADD(M, 1, @vOutputDate))

		SELECT TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status,
				SUM(ISNULL(ICD.N_Amount_Due,0.00)) AS Amount_Due_LM
		INTO #TmpOutStandingRpt3
		FROM #TmpOutStandingRpt2 TMP
				INNER JOIN dbo.T_Invoice_Child_Detail ICD WITH(NOLOCK)
				ON TMP.I_Invoice_Child_Header_ID = ICD.I_Invoice_Child_Header_ID
				--AND DATEPART(month,ICD.Dt_Installment_Date) <= DATEPART(month, @dtUptoDate)
				--AND DATEPART(year,ICD.Dt_Installment_Date) <= DATEPART(year, @dtUptoDate)
				AND ICD.Dt_Installment_Date <=  @vOutputDate
		GROUP BY TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status

		--Finding Last Date of the Nes=xt Month
		SET @dtUptoDate=DATEADD(month,1,@dtUptoDate)
		DECLARE @vOutputDate1 DATETIME
		SET @vOutputDate1 = CAST(YEAR(@dtUptoDate) AS VARCHAR(4)) + '/' + CAST(MONTH(@dtUptoDate) AS VARCHAR(2)) + '/01'
		SET @vOutputDate1= DATEADD(DD, -1, DATEADD(M, 1, @vOutputDate1))

	SELECT TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status,
				SUM(ISNULL(ICD.N_Amount_Due,0.00)) AS Amount_Due_CM
		INTO #TmpOutStandingRpt4
		FROM #TmpOutStandingRpt2 TMP
				INNER JOIN dbo.T_Invoice_Child_Detail ICD WITH(NOLOCK)
				ON TMP.I_Invoice_Child_Header_ID = ICD.I_Invoice_Child_Header_ID
				--AND DATEPART(month,ICD.Dt_Installment_Date) <= DATEPART(month, (DATEADD(month,1,@dtUptoDate)))
				--AND DATEPART(year,ICD.Dt_Installment_Date) <= DATEPART(year, @dtUptoDate)
				AND ICD.Dt_Installment_Date <= @vOutputDate1
		GROUP BY TMP.I_Invoice_Header_ID,
				TMP.I_Centre_Id,
				TMP.I_Student_Detail_ID,
				TMP.S_Student_ID,
				TMP.S_Title,
				TMP.S_First_Name,
				TMP.S_Middle_Name,
				TMP.S_Last_Name,
				TMP.Invoice_No,
				TMP.Invoice_Date,
				TMP.Invoice_Amount,
				TMP.Tax_Amount,
				TMP.N_Discount_Amount,
				TMP.CenterCode,
				TMP.CenterName,
				TMP.InstanceChain,
				TMP.S_Currency_Code,
				TMP.Receipt_Amount,
				TMP.Outstanding_Amt,
				TMP.Last_Install_Date,
				--TMP.I_Course_ID,
				--TMP.Course_Code,
				--TMP.Course_Name,
				TMP.Last_Install_Amount,
				TMP.Student_Status

	SELECT		DISTINCT
				HRKY.I_Brand_ID AS BrandID,
				HRKY.S_Brand_Name AS BrandName,
				HRKY.I_Region_ID AS RegionID,
				HRKY.S_Region_Name AS RegionName,
				HRKY.I_Territory_ID AS TerritoryID,
				HRKY.S_Territiry_Name AS TerritiryName,
				HRKY.I_City_ID AS CityID,
				HRKY.S_City_Name AS CityName,
				TMP1.I_Centre_Id,
				TMP1.CenterCode,
				TMP1.CenterName,
				TMP1.I_Invoice_Header_ID,
				TMP1.I_Student_Detail_ID,
				TMP1.S_Student_ID,
				TMP1.S_Title,
				TMP1.S_First_Name,
				TMP1.S_Middle_Name,
				TMP1.S_Last_Name,
				ISNULL(TMP1.S_First_Name,'')+' '+ISNULL(TMP1.S_Middle_Name,'')+' '+ISNULL(TMP1.S_Last_Name,'') AS StudentName,
				TMP1.Invoice_No,
				TMP1.Invoice_Date,
				TMP1.Invoice_Amount,
				TMP1.Tax_Amount,
				TMP1.N_Discount_Amount,
				TMP1.InstanceChain,
				TMP1.S_Currency_Code,
				TMP1.Receipt_Amount,
				TMP1.Outstanding_Amt,
				TMP1.Last_Install_Date,
				--CM.I_Course_ID,
				--CM.S_Course_Code AS Course_Code,
				--CM.S_Course_Name AS Course_Name,
				TMP1.Last_Install_Amount,
				TMP1.Student_Status,
				TMP1.Amount_Due_LM,
				TMP2.Amount_Due_CM
		FROM #TmpOutStandingRpt3 TMP1
				INNER JOIN #TmpOutStandingRpt4 TMP2
				ON TMP1.I_Invoice_Header_ID = TMP2.I_Invoice_Header_ID
				AND TMP1.I_Centre_Id = TMP2.I_Centre_Id
				AND TMP1.I_Student_Detail_ID = TMP2.I_Student_Detail_ID				
				INNER JOIN dbo.T_Center_Hierarchy_Name_Details AS HRKY ON TMP1.I_CENTRE_ID=HRKY.I_Center_ID
		GROUP BY 
				HRKY.I_Brand_ID,
				HRKY.S_Brand_Name,
				HRKY.I_Region_ID,
				HRKY.S_Region_Name,
				HRKY.I_Territory_ID,
				HRKY.S_Territiry_Name,
				HRKY.I_City_ID,
				HRKY.S_City_Name,
				TMP1.I_Centre_Id,
				TMP1.CenterCode,
				TMP1.CenterName,
				TMP1.I_Invoice_Header_ID,
				TMP1.I_Student_Detail_ID,
				TMP1.S_Student_ID,
				TMP1.S_Title,
				TMP1.S_First_Name,
				TMP1.S_Middle_Name,
				TMP1.S_Last_Name,
				TMP1.Invoice_No,
				TMP1.Invoice_Date,
				TMP1.Invoice_Amount,
				TMP1.Tax_Amount,
				TMP1.N_Discount_Amount,
				TMP1.InstanceChain,
				TMP1.S_Currency_Code,
				TMP1.Receipt_Amount,
				TMP1.Outstanding_Amt,
				TMP1.Last_Install_Date,
				TMP1.Last_Install_Amount,
				TMP1.Student_Status,
				TMP1.Amount_Due_LM,
				TMP2.Amount_Due_CM

	 DROP TABLE #TmpOutStandingRpt1
	 DROP TABLE #TmpOutStandingRpt2
	 DROP TABLE #TmpOutStandingRpt3
	 DROP TABLE #TmpOutStandingRpt4

END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
