GO
-- =============================================
-- Author: Shankha Roy
-- Create date: 07/11/2007
-- Description: This sp return return list summary report for placment. 
--				
-- Parameter: @iBrandID ,@dtStartDate ,@dtEndDate , @sHierarchyList
-- =============================================


CREATE PROCEDURE [REPORT].[uspGetPlacementSummaryReport] 
(
-- Add the parameters for the stored procedure here
	@iBrandID INT = NULL,
	@sHierarchyList VARCHAR(MAX) = NULL,
	@dtStartDate DATETIME,
	@dtEndDate DATETIME
)
AS

BEGIN TRY
	BEGIN 

			
				SELECT
				ISNULL(FN1.CenterCode,'') AS CenterCode,
				ISNULL(FN1.CenterName,'') AS CenterName,
				ISNULL(FN2.InstanceChain,'') AS InstanceChain,
				COUNT(SS.I_Shortlisted_Student_ID) AS Placements
				FROM
				PLACEMENT.T_Shortlisted_Students SS
				INNER JOIN dbo.T_Student_Detail SD 
				ON SS.I_Student_Detail_ID = SD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Student_Center_Detail SCD 
				ON SS.I_Student_Detail_ID = SCD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Centre_Master CM 
				ON CM.I_Centre_Id = SCD.I_Centre_Id 
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON CM.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID

				WHERE 
				--SS.C_Interview_Status = 'S'
				 DATEDIFF(dd, ISNULL(@dtStartDate,SS.Dt_Crtd_On), SS.Dt_Crtd_On) >= 0
				AND DATEDIFF(dd, ISNULL(@dtEndDate,SS.Dt_Crtd_On), SS.Dt_Crtd_On) <= 0
				AND CM.I_Centre_Id IN 
				(
				SELECT centerID FROM [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID)
				)
				AND SS.C_Interview_Status = 'S'
				GROUP BY SCD.I_Centre_Id,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain				


	END
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetPlacementStudentRegistrationReport]...';


GO
-- =============================================
-- Author: Shankha Roy
-- Create date: 07/11/2007
-- Description: This sp return return list summary student registration report. 
--				
-- Parameter: @iBrandID ,@dtStartDate ,@dtEndDate , @sHierarchyList
-- =============================================


CREATE PROCEDURE [REPORT].[uspGetPlacementStudentRegistrationReport] 
(
-- Add the parameters for the stored procedure here
	@iBrandID INT = NULL,
	@sHierarchyList VARCHAR(MAX) = NULL,
	@dtStartDate DATETIME,
	@dtEndDate DATETIME
)
AS

BEGIN TRY
	BEGIN 

			
				SELECT
				SD.S_Student_ID AS StudentID,
				ISNULL(SD.S_Title,'') + ' ' + SD.S_First_Name + ' ' + LTRIM(isnull(SD.S_Middle_Name,'') + ' ' + SD.S_Last_Name) as StudentName,
				CONVERT(VARCHAR(12),PR.Dt_Crtd_On,106) AS RegistrationDate,
				CONVERT(VARCHAR(12),ISNULL(STCD.Dt_Course_Actual_End_Date,STCD.Dt_Course_Expected_End_Date),106) AS Dt_Course_Actual_End_Date,
				CONVERT(VARCHAR(12),STCD.Dt_Course_Expected_End_Date,106) AS Dt_Course_Expected_End_Date,
				PR.I_Job_Type_ID AS I_Job_Type_ID,				
				TCM.S_Course_Name AS S_Course_Name,
				FN1.CenterCode,
				FN1.CenterName,
				FN2.InstanceChain
				FROM
				
				PLACEMENT.T_Placement_Registration PR				
				INNER JOIN dbo.T_Student_Detail SD 
				ON PR.I_Student_Detail_ID = SD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Student_Center_Detail SCD 
				ON PR.I_Student_Detail_ID = SCD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Centre_Master CM 
				ON CM.I_Centre_Id = SCD.I_Centre_Id 
				INNER JOIN dbo.T_Brand_Center_Details BCD 
				ON CM.I_Centre_Id = BCD.I_Centre_Id 
				INNER JOIN dbo.T_Brand_Master BM
				ON BM.I_Brand_ID = BCD.I_Brand_ID				
				INNER JOIN dbo.T_Student_Course_Detail STCD
				ON PR.I_Student_Detail_ID = STCD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Course_Master TCM
				ON TCM.I_Course_ID =STCD.I_Course_ID
				INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON CM.I_Centre_Id=FN1.CenterID
				INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
				WHERE 
				DATEDIFF(dd, ISNULL(@dtStartDate,PR.Dt_Crtd_On), PR.Dt_Crtd_On) >= 0
				AND DATEDIFF(dd, ISNULL(@dtEndDate,PR.Dt_Crtd_On), PR.Dt_Crtd_On) <= 0
				AND CM.I_Centre_Id IN 
				(
				SELECT centerID FROM [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID)
				)
				


	END
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetPlacementJobOpeningReport]...';


GO
-- ===============================================================
-- Author: Shankha Roy
-- Create date: 07/11/2007
-- Description: This sp return return list summary Job Opening List. 
--				
-- Parameter: @CompanyName,@RoleDesignation,@dtStartDate,@dtEndDate
-- ================================================================

CREATE PROCEDURE [REPORT].[uspGetPlacementJobOpeningReport] 
(
	@dtStartDate DATETIME,
	@dtEndDate DATETIME,
	@sCompanyName VARCHAR(250)= NULL,
	@sRoleDesignation VARCHAR(50)= NULL,
	@iBrandID INT = null
)
AS
BEGIN TRY
	BEGIN 

DECLARE @CompanyName VARCHAR(250)
DECLARE @RoleDesignation VARCHAR(50)

IF(@sRoleDesignation IS NOT NULL)
SET @RoleDesignation = @sRoleDesignation +'%'


			SELECT   
			ED.S_Company_Name AS S_Company_Name,
			VD.S_Role_Designation AS S_Role_Designation,
			VD.I_No_Of_Openings AS Openings,
			(CONVERT(NUMERIC(18,2), VD.S_Pay_Scale)) AS S_Pay_Scale,
			Count(SS.I_Student_Detail_ID) AS VacancyFill
			FROM PLACEMENT.T_Vacancy_Detail VD
			INNER JOIN PLACEMENT.T_Employer_Detail ED
			ON VD.I_Employer_ID= ED.I_Employer_ID
			INNER JOIN dbo.T_User_Master UM
			ON UM.I_Reference_ID = ED.I_Employer_ID
			AND UM.S_User_Type = 'EM'
			LEFT OUTER JOIN PLACEMENT.T_Shortlisted_Students SS
			ON SS.I_Vacancy_ID =VD.I_Vacancy_ID
			AND [SS].[C_Interview_Status] = 'S'
			WHERE
			[ED].[I_Employer_ID] = ISNULL(@sCompanyName,[ED].[I_Employer_ID])
			AND S_Role_Designation LIKE COALESCE(@RoleDesignation,S_Role_Designation)
			AND DATEDIFF(dd, ISNULL(@dtStartDate,VD.Dt_Crtd_On), VD.Dt_Crtd_On) >= 0
			AND DATEDIFF(dd, ISNULL(@dtEndDate,VD.Dt_Crtd_On), VD.Dt_Crtd_On) <= 0 
			AND UM.I_User_ID IN (SELECT I_User_ID FROM [Placement].[fnGetUserIDFormBrand](@iBrandID))
			GROUP BY SS.I_Vacancy_ID,
			ED.S_Company_Name,
			VD.S_Role_Designation,
			VD.I_No_Of_Openings,
			VD.S_Pay_Scale

	END
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetPlacementDetailReport]...';


GO
-- =============================================
-- Author: Shankha Roy
-- Create date: 07/10/2007
-- Description: This sp return return list of student 
--				details who are selected in placment. 
--				It returns data for report placment 
--				details report.
-- Parameter: @iBrandID ,@dtStartDate ,@dtEndDate , @sHierarchyList
-- =============================================


CREATE PROCEDURE [REPORT].[uspGetPlacementDetailReport] 
(
-- Add the parameters for the stored procedure here
	@iBrandID INT,
	@sHierarchyList VARCHAR(MAX),
	@dtStartDate DATETIME,
	@dtEndDate DATETIME
)
AS

BEGIN TRY
	BEGIN



					DECLARE @cStudentID INT -- user in temp student id
					-- temp table to store selected student id
					DECLARE @temStudent TABLE 
					(
					 ID INT IDENTITY(1,1),
					 I_Student_Detail_ID INT,
					 I_Vacancy_ID INT
					)
					-- temp table for store student details
					DECLARE @temStudentDetail TABLE 
					(
					Dt_Placement DATETIME,
					S_Placement_Executive VARCHAR(50),
					S_Designation VARCHAR(50),
					S_StudentName VARCHAR(200),
					N_Annual_Salary NUMERIC(18,2),
					S_CompanyName VARCHAR(250),
					S_Courses VARCHAR(2000),
					S_Center_Name VARCHAR(100),
					CenterCode VARCHAR(100),			
					InstanceChain VARCHAR(5000)
					)

				
				INSERT INTO @temStudent
				SELECT				
				SS.I_Student_Detail_ID AS I_Student_Detail_ID,
				SS.I_Vacancy_ID AS  I_Vacancy_ID
				FROM
				PLACEMENT.T_Shortlisted_Students SS 
				INNER JOIN dbo.T_Student_Detail SD 
				ON SS.I_Student_Detail_ID = SD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Student_Center_Detail SCD 
				ON SS.I_Student_Detail_ID = SCD.I_Student_Detail_ID 
				INNER JOIN dbo.T_Centre_Master CM 
				ON CM.I_Centre_Id = SCD.I_Centre_Id 
				WHERE 
				DATEDIFF(dd, ISNULL(@dtStartDate,SS.[Dt_Crtd_On]), SS.[Dt_Crtd_On]) >= 0
				AND DATEDIFF(dd, ISNULL(@dtEndDate,SS.[Dt_Crtd_On]), SS.[Dt_Crtd_On]) <= 0
				AND CM.I_Centre_Id IN 
				(
				SELECT centerID FROM [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID)
				)
				AND SS.C_Interview_Status = 'S'

				DECLARE @iRow INT 
				DECLARE @iCount INT
				SET @iCount =1
				SET @iRow = (SELECT COUNT(I_Student_Detail_ID)AS I_Student_Detail_ID  FROM
				@temStudent)

				
						WHILE (@iCount <=  @iRow)
						BEGIN
						
							SET @cStudentID = (SELECT I_Student_Detail_ID FROM  @temStudent  WHERE ID = @iCount)
								
								INSERT INTO @temStudentDetail(Dt_Placement,S_Placement_Executive,
								S_Designation,N_Annual_Salary,S_StudentName,S_CompanyName,
								S_Center_Name,S_Courses,
								CenterCode,InstanceChain								
								)

								SELECT 
								SS.Dt_Placement AS Dt_Placement,
								SS.S_Placement_Executive AS S_Placement_Executive , 
								SS.S_Designation AS S_Designation,
								SS.N_Annual_Salary AS N_Annual_Salary,
								ISNULL(SD.S_Title,'') + ' ' + SD.S_First_Name + ' ' + LTRIM(isnull(SD.S_Middle_Name,'') + ' ' + SD.S_Last_Name) as StudentName,
								ED.S_Company_Name AS S_Company_Name, 
								CM.S_Center_Name AS S_Center_Name,
								FN3.Courses,
								FN1.CenterCode,				
								FN2.InstanceChain 
								FROM
								PLACEMENT.T_Shortlisted_Students SS 
								INNER JOIN dbo.T_Student_Detail SD 
								ON SS.I_Student_Detail_ID = SD.I_Student_Detail_ID 
								INNER JOIN [dbo].[fnGetStudentCoursesList](@cStudentID) FN3
								ON SS.I_Student_Detail_ID = FN3.I_Student_Detail_ID
								INNER JOIN dbo.T_Student_Center_Detail SCD 
								ON SS.I_Student_Detail_ID = SCD.I_Student_Detail_ID 
								INNER JOIN dbo.T_Centre_Master CM 
								ON CM.I_Centre_Id = SCD.I_Centre_Id
								INNER JOIN PLACEMENT.T_Vacancy_Detail VD
								ON VD.I_Vacancy_ID = SS.I_Vacancy_ID
								INNER JOIN PLACEMENT.T_Employer_Detail ED
								ON ED.I_Employer_ID = VD.I_Employer_ID
								INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
								ON CM.I_Centre_Id=FN1.CenterID
								INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
								ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
 
								WHERE 
								SS.I_Student_Detail_ID = @cStudentID
								AND SS.C_Interview_Status = 'S'

							SET @iCount = @iCount + 1
								
						END

				 
		-- select the data for report
				SELECT
				DISTINCT(S_StudentName) AS S_StudentName ,  
				--CONVERT(VARCHAR(12),Dt_Placement,106) AS Dt_Placement,
				--DATEPART(mm,Dt_Placement) AS Dt_Placement,
				(DATENAME(m,Dt_Placement) +'-'+ DATENAME(yy,Dt_Placement))AS Dt_Placement,
				S_Placement_Executive ,
				S_Designation ,				
				N_Annual_Salary ,
				S_CompanyName,
				S_Courses,
				S_Center_Name,
				CenterCode,
				InstanceChain
				FROM @temStudentDetail


	END
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetPerStudentBCReport]...';


GO
CREATE PROCEDURE [REPORT].[uspGetPerStudentBCReport] 
(
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@dtStartDate datetime,
	@dtEndDate datetime,
	@iCourseFamilyID int= NULL,
	@sCourseFamilyName varchar(50) = NULL
)

AS

BEGIN TRY
	SET NOCOUNT ON
---------------------------------------------------------	
	 SELECT IP.I_Invoice_Header_ID,
			IP.I_Student_Detail_ID,
			ICH.I_Invoice_Child_Header_ID,
			ICH.I_Course_ID,
			CM.S_Course_Code,
			CM.S_Course_Name,
			CFM.S_CourseFamily_Name,
			ICD.I_Invoice_Detail_ID,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code,
			ISNULL(ICD.N_Amount_Due,0.00) AS N_Amount_Due,
			SUM(ISNULL(IDT.N_Tax_Value,0.00)) AS N_Tax_Value
	   INTO #TmpBCRpt11

	   FROM dbo.T_Invoice_Parent IP
			INNER JOIN dbo.T_Invoice_Child_Header ICH
			ON IP.I_Invoice_Header_ID=ICH.I_Invoice_Header_ID
			INNER JOIN dbo.T_Invoice_Child_Detail ICD
			ON ICH.I_Invoice_Child_Header_ID=ICD.I_Invoice_Child_Header_ID
			LEFT OUTER JOIN dbo.T_Invoice_Detail_Tax IDT
			ON ICD.I_Invoice_Detail_ID=IDT.I_Invoice_Detail_ID
			INNER JOIN dbo.T_Course_Master CM
			ON ICH.I_Course_ID=CM.I_Course_ID
			INNER JOIN dbo.T_CourseFamily_Master CFM
			ON CM.I_CourseFamily_ID=CFM.I_CourseFamily_ID
			INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
			ON IP.I_Centre_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
			ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
			INNER JOIN dbo.T_Centre_Master CEM
			ON FN1.CenterID=CEM.I_Centre_Id
			INNER JOIN dbo.T_Country_Master COM
			ON CEM.I_Country_ID=COM.I_Country_ID
			INNER JOIN dbo.T_Currency_Master CUM
			ON COM.I_Currency_ID=CUM.I_Currency_ID
	  WHERE CFM.I_CourseFamily_ID=ISNULL(@iCourseFamilyID,CFM.I_CourseFamily_ID)
	AND CAST(SUBSTRING(CAST(IP.Dt_Invoice_Date AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
	AND [IP].[I_Student_Detail_ID] NOT IN (SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM)
   GROUP BY IP.I_Invoice_Header_ID,
			IP.I_Student_Detail_ID,
			ICH.I_Invoice_Child_Header_ID,
			ICH.I_Course_ID,
			CM.S_Course_Code,
			CM.S_Course_Name,
			CFM.S_CourseFamily_Name,
			ICD.I_Invoice_Detail_ID,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code,
			ICD.N_Amount_Due

	 SELECT IP.I_Invoice_Header_ID,
			IP.I_Student_Detail_ID,
			ICH.I_Invoice_Child_Header_ID,
			ICH.I_Course_ID,
			CM.S_Course_Code,
			CM.S_Course_Name,
			CFM.S_CourseFamily_Name,
			ICD.I_Invoice_Detail_ID,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code,
			-ISNULL(ICD.N_Amount_Due,0.00) AS N_Amount_Due,
			-SUM(ISNULL(IDT.N_Tax_Value,0.00)) AS N_Tax_Value
	   INTO #TmpBCRpt12
	   FROM dbo.T_Invoice_Parent IP
			INNER JOIN dbo.T_Invoice_Child_Header ICH
			ON IP.I_Invoice_Header_ID=ICH.I_Invoice_Header_ID
			INNER JOIN dbo.T_Invoice_Child_Detail ICD
			ON ICH.I_Invoice_Child_Header_ID=ICD.I_Invoice_Child_Header_ID
			LEFT OUTER JOIN dbo.T_Invoice_Detail_Tax IDT
			ON ICD.I_Invoice_Detail_ID=IDT.I_Invoice_Detail_ID
			INNER JOIN dbo.T_Course_Master CM
			ON ICH.I_Course_ID=CM.I_Course_ID
			INNER JOIN dbo.T_CourseFamily_Master CFM
			ON CM.I_CourseFamily_ID=CFM.I_CourseFamily_ID
			INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
			ON IP.I_Centre_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
			ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
			INNER JOIN dbo.T_Centre_Master CEM
			ON FN1.CenterID=CEM.I_Centre_Id
			INNER JOIN dbo.T_Country_Master COM
			ON CEM.I_Country_ID=COM.I_Country_ID
			INNER JOIN dbo.T_Currency_Master CUM
			ON COM.I_Currency_ID=CUM.I_Currency_ID
	  WHERE CFM.I_CourseFamily_ID=ISNULL(@iCourseFamilyID,CFM.I_CourseFamily_ID)
		AND IP.I_STATUS=0 
		AND CAST(SUBSTRING(CAST(IP.DT_UPD_ON AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
		AND [IP].[I_Student_Detail_ID] NOT IN (SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM)
   GROUP BY IP.I_Invoice_Header_ID,
			IP.I_Student_Detail_ID,
			ICH.I_Invoice_Child_Header_ID,
			ICH.I_Course_ID,
			CM.S_Course_Code,
			CM.S_Course_Name,
			CFM.S_CourseFamily_Name,
			ICD.I_Invoice_Detail_ID,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code,
			ICD.N_Amount_Due

SELECT T1.* INTO #TmpBCRpt1 FROM
(
	SELECT * FROM #TmpBCRpt11
	UNION ALL
	SELECT * FROM #TmpBCRpt12
) T1

---------------------------------------

	 SELECT TMP.I_Invoice_Header_ID,
			TMP.I_Student_Detail_ID,
			TMP.I_Invoice_Child_Header_ID,
			TMP.I_Course_ID,
			TMP.S_Course_Code,
			TMP.S_Course_Name,
			TMP.S_CourseFamily_Name,
			TMP.I_Invoice_Detail_ID,
			TMP.CenterCode,
			TMP.CenterName,
			TMP.InstanceChain,
			TMP.S_Currency_Code,
			TMP.N_Amount_Due,
			TMP.N_Tax_Value,
			RCD.I_Receipt_Comp_Detail_ID,
			ISNULL(RCD.N_Amount_Paid,0.00) AS N_Amount_Paid,
			SUM(ISNULL(RTD.N_Tax_Paid,0.00)) AS N_Tax_Paid
	   INTO #TmpBCRpt21
	   FROM #TmpBCRpt1 TMP
			LEFT OUTER JOIN dbo.T_Receipt_Header RH
			ON TMP.I_Invoice_Header_ID=RH.I_Invoice_Header_ID
			LEFT OUTER JOIN dbo.T_Receipt_Component_Detail RCD
			ON RH.I_Receipt_Header_ID=RCD.I_Receipt_Detail_ID
			AND TMP.I_Invoice_Detail_ID=RCD.I_Invoice_Detail_ID
			LEFT OUTER JOIN dbo.T_Receipt_Tax_Detail RTD
			ON RCD.I_Receipt_Comp_Detail_ID=RTD.I_Receipt_Comp_Detail_ID
	WHERE 
		 CAST(SUBSTRING(CAST( RH.Dt_Receipt_Date AS VARCHAR),1,11) as datetime) BETWEEN @dtStartDate AND @dtEndDate
	GROUP BY TMP.I_Invoice_Header_ID,
			TMP.I_Student_Detail_ID,
			TMP.I_Invoice_Child_Header_ID,
			TMP.I_Course_ID,
			TMP.S_Course_Code,
			TMP.S_Course_Name,
			TMP.S_CourseFamily_Name,
			TMP.I_Invoice_Detail_ID,
			TMP.CenterCode,
			TMP.CenterName,
			TMP.InstanceChain,
			TMP.S_Currency_Code,
			TMP.N_Amount_Due,
			TMP.N_Tax_Value,
			RCD.I_Receipt_Comp_Detail_ID,
			RCD.N_Amount_Paid



	SELECT TMP.I_Invoice_Header_ID,
			TMP.I_Student_Detail_ID,
			TMP.I_Invoice_Child_Header_ID,
			TMP.I_Course_ID,
			TMP.S_Course_Code,
			TMP.S_Course_Name,
			TMP.S_CourseFamily_Name,
			TMP.I_Invoice_Detail_ID,
			TMP.CenterCode,
			TMP.CenterName,
			TMP.InstanceChain,
			TMP.S_Currency_Code,
			TMP.N_Amount_Due,
			TMP.N_Tax_Value,
			RCD.I_Receipt_Comp_Detail_ID,
			-ISNULL(RCD.N_Amount_Paid,0.00) AS N_Amount_Paid,
			-SUM(ISNULL(RTD.N_Tax_Paid,0.00)) AS N_Tax_Paid
	   INTO #TmpBCRpt22
	   FROM #TmpBCRpt1 TMP
			LEFT OUTER JOIN dbo.T_Receipt_Header RH
			ON TMP.I_Invoice_Header_ID=RH.I_Invoice_Header_ID
			LEFT OUTER JOIN dbo.T_Receipt_Component_Detail RCD
			ON RH.I_Receipt_Header_ID=RCD.I_Receipt_Detail_ID
			AND TMP.I_Invoice_Detail_ID=RCD.I_Invoice_Detail_ID
			LEFT OUTER JOIN dbo.T_Receipt_Tax_Detail RTD
			ON RCD.I_Receipt_Comp_Detail_ID=RTD.I_Receipt_Comp_Detail_ID
	WHERE RH.I_STATUS=0 
	AND CAST(SUBSTRING(CAST( RH.DT_UPD_ON AS VARCHAR),1,11) AS DATETIME) BETWEEN @DTSTARTDATE AND @DTENDDATE
	GROUP BY TMP.I_Invoice_Header_ID,
			TMP.I_Student_Detail_ID,
			TMP.I_Invoice_Child_Header_ID,
			TMP.I_Course_ID,
			TMP.S_Course_Code,
			TMP.S_Course_Name,
			TMP.S_CourseFamily_Name,
			TMP.I_Invoice_Detail_ID,
			TMP.CenterCode,
			TMP.CenterName,
			TMP.InstanceChain,
			TMP.S_Currency_Code,
			TMP.N_Amount_Due,
			TMP.N_Tax_Value,
			RCD.I_Receipt_Comp_Detail_ID,
			RCD.N_Amount_Paid

	SELECT T2.* INTO #TmpBCRpt2 FROM
	(
		SELECT * FROM #TmpBCRpt21
		UNION ALL
		SELECT * FROM #TmpBCRpt22
	) T2

------------------------------------------------

	 SELECT TMP.I_Invoice_Header_ID,
			TMP.I_Student_Detail_ID,
			TMP.I_Invoice_Child_Header_ID,
			TMP.I_Course_ID,
			TMP.S_Course_Code,
			TMP.S_Course_Name,
			TMP.S_CourseFamily_Name,
			TMP.I_Invoice_Detail_ID,
			TMP.CenterCode,
			TMP.CenterName,
			TMP.InstanceChain,
			TMP.S_Currency_Code,
			TMP.N_Amount_Due,
			TMP.N_Tax_Value,
			SUM(N_Amount_Paid) AS N_Amount_Paid,
			SUM(N_Tax_Paid) AS N_Tax_Paid
	   INTO #TmpBCRpt3
	   FROM #TmpBCRpt2 TMP
   GROUP BY TMP.I_Invoice_Header_ID,
			TMP.I_Student_Detail_ID,
			TMP.I_Invoice_Child_Header_ID,
			TMP.I_Course_ID,
			TMP.S_Course_Code,
			TMP.S_Course_Name,
			TMP.S_CourseFamily_Name,
			TMP.I_Invoice_Detail_ID,
			TMP.CenterCode,
			TMP.CenterName,
			TMP.InstanceChain,
			TMP.S_Currency_Code,
			TMP.N_Amount_Due,
			TMP.N_Tax_Value


	 SELECT InstanceChain,
			CenterCode,
			CenterName,
			S_Currency_Code,
			S_CourseFamily_Name,
			S_Course_Code,
			S_Course_Name,
			COUNT(DISTINCT I_Student_Detail_ID) AS Enroll_Total,
			SUM(N_Amount_Due) AS N_Amount_Due,
			SUM(N_Tax_Value) AS N_Tax_Value,
			SUM(N_Amount_Paid) AS N_Amount_Paid,
			SUM(N_Tax_Paid) AS N_Tax_Paid
	   FROM #TmpBCRpt3
   GROUP BY InstanceChain,
			CenterCode,
			CenterName,
			S_Currency_Code,
			S_CourseFamily_Name,
			S_Course_Code,
			S_Course_Name
   ORDER BY InstanceChain,CenterName,S_CourseFamily_Name,S_Course_Name

END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
