PRINT N'Creating Procedure [REPORT].[UspGetPreAssessmentAnalysis]...';


GO
CREATE PROCEDURE [REPORT].[UspGetPreAssessmentAnalysis]
(
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@dtStartDate datetime,
	@dtEndDate datetime
)
AS
	Begin
		DECLARE @Assess TABLE
		(
			ID INT IDENTITY(1,1),
			CenterID INT,
			Center VARCHAR(250),
			CourseFamily Varchar(250),
			CourseID INT,
			CourseName Varchar(250),
			CourseFamilyName Varchar(250),
			NoOfEnquiry BIGINT,
			AssessedEnQ BIGINT,
			SuggestedSame BIGINT,
			SuggestedDifferent BIGINT,
			AdmittedSame BIGINT,
			AdmittedDifferent BIGINT
		)
		
		INSERT INTO @Assess
		(
		[CenterID],
		[Center],
		[CourseFamily],
		[CourseID],
		[CourseName],
		[CourseFamilyName]
		)
		Select distinct
			   FN1.centerID,
			   FN1.centerName,
			   CFM.S_CourseFamily_Name,
			   tacm.I_Course_ID,
			   CM.S_Course_Name,
			   CFM.S_CourseFamily_Name
		FROM ASSESSMENT.T_Student_Assessment_Map TSAM
				INNER JOIN ASSESSMENT.T_Assessment_Course_Map AS tacm ON tsam.I_PreAssessment_ID = tacm.I_PreAssessment_ID
				INNER JOIN dbo.T_Enquiry_Regn_Detail AS terd ON terd.I_Enquiry_Regn_ID = tsam.I_Enquiry_Regn_ID
				INNER JOIN [dbo].[fnGetCentersForReports](1, 2) FN1
				ON terd.I_Centre_Id=FN1.CenterID
				INNER JOIN dbo.T_Course_Master CM ON tacm.I_Course_ID=CM.I_Course_ID
				INNER JOIN dbo.T_CourseFamily_Master CFM ON CM.I_CourseFamily_ID=CFM.I_CourseFamily_ID
		WHERE TSAM.B_Is_Complete=1
		
		UPDATE @Assess SET NoOfEnquiry=ISNULL(ENQUIRY,0),
		AssessedEnQ=ISNULL(ASSESSED,0),
		SuggestedSame=ISNULL(SUGGESTED,0),
		SuggestedDifferent=ISNULL(SUGGESTDIFF,0),
		AdmittedSame=ISNULL(ADMITTED,0),
		AdmittedDifferent=ISNULL(ADMITDIFF,0)
		FROM @Assess A 
		Left JOIN
		(
			SELECT EC.I_Course_ID,ERD.I_Centre_Id,COUNT(distinct ERD.I_Enquiry_Regn_ID) AS ENQUIRY
			FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
			WHERE ERD.Dt_Crtd_On BETWEEN @dtStartDate AND @dtEndDate
			GROUP BY EC.I_Course_ID,ERD.I_Centre_Id
		)
		AS ENQ ON A.CenterID=ENQ.I_Centre_Id AND A.CourseID=ENQ.I_Course_ID
		LEFT JOIN
		(
			SELECT tacm.I_Course_ID,ERD.I_Centre_Id,COUNT(Distinct TSAM.I_Enquiry_Regn_ID) AS ASSESSED
			FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Map TSAM ON ERD.I_Enquiry_Regn_ID=TSAM.I_Enquiry_Regn_ID
			AND TSAM.B_Is_Complete=1
			INNER JOIN ASSESSMENT.T_Assessment_Course_Map AS tacm ON tsam.I_PreAssessment_ID = tacm.I_PreAssessment_ID
			AND EC.I_Course_ID=tacm.I_Course_ID
			WHERE ERD.Dt_Crtd_On BETWEEN @dtStartDate AND @dtEndDate
			GROUP BY tacm.I_Course_ID,ERD.I_Centre_Id
		)
		AS ASSESS ON A.CenterID=ASSESS.I_Centre_Id AND A.CourseID=ASSESS.I_Course_ID
		LEFT JOIN
		(
			SELECT TACCM.I_Course_ID,ERD.I_Centre_Id,COUNT(distinct TSAM.I_Enquiry_Regn_ID) AS SUGGESTED
			FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Suggestion TSAS ON ERD.I_Enquiry_Regn_ID=TSAS.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Map TSAM ON TSAS.I_Enquiry_Regn_ID=TSAM.I_Enquiry_Regn_ID
			AND TSAM.B_Is_Complete=1
			INNER JOIN ASSESSMENT.T_Assessment_CourseList_Course_Map TACCM ON TSAS.I_CourseList_ID=TACCM.I_Course_List_ID
			AND EC.I_Course_ID=TACCM.I_Course_ID
			WHERE ERD.Dt_Crtd_On BETWEEN @dtStartDate AND @dtEndDate
			GROUP BY TACCM.I_Course_ID,ERD.I_Centre_Id
		)
		AS SUGGEST ON A.CenterID=SUGGEST.I_Centre_Id AND A.CourseID=SUGGEST.I_Course_ID
		LEFT JOIN
		(
			SELECT EC.I_Course_ID,ERD.I_Centre_Id,COUNT(distinct TSAM.I_Enquiry_Regn_ID) AS SUGGESTDIFF
			FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Suggestion TSAS ON ERD.I_Enquiry_Regn_ID=TSAS.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Map TSAM ON TSAS.I_Enquiry_Regn_ID=TSAM.I_Enquiry_Regn_ID
			AND TSAM.B_Is_Complete=1
			INNER JOIN ASSESSMENT.T_Assessment_CourseList_Course_Map TACCM ON TSAS.I_CourseList_ID=TACCM.I_Course_List_ID
			AND EC.I_Course_ID<>TACCM.I_Course_ID
			AND TSAM.I_Enquiry_Regn_ID not in
			(
				SELECT distinct TSAM.I_Enquiry_Regn_ID
				FROM dbo.T_Enquiry_Regn_Detail ERD
				INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
				INNER JOIN ASSESSMENT.T_Student_Assessment_Suggestion TSAS ON ERD.I_Enquiry_Regn_ID=TSAS.I_Enquiry_Regn_ID
				INNER JOIN ASSESSMENT.T_Student_Assessment_Map TSAM ON TSAS.I_Enquiry_Regn_ID=TSAM.I_Enquiry_Regn_ID
				AND TSAM.B_Is_Complete=1
				INNER JOIN ASSESSMENT.T_Assessment_CourseList_Course_Map TACCM ON TSAS.I_CourseList_ID=TACCM.I_Course_List_ID
				AND EC.I_Course_ID=TACCM.I_Course_ID
			)
			--WHERE ERD.Dt_Crtd_On BETWEEN @dtStartDate AND @dtEndDate
			GROUP BY EC.I_Course_ID,ERD.I_Centre_Id
		)
		AS SUGGESTDIFF ON A.CenterID=SUGGESTDIFF.I_Centre_Id AND A.CourseID=SUGGESTDIFF.I_Course_ID
		LEFT JOIN
		(
			SELECT EC.I_Course_ID,ERD.I_Centre_Id,COUNT(distinct TSAM.I_Enquiry_Regn_ID) AS ADMITTED
			FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Suggestion TSAS ON ERD.I_Enquiry_Regn_ID=TSAS.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Map TSAM ON TSAS.I_Enquiry_Regn_ID=TSAM.I_Enquiry_Regn_ID
			AND TSAM.B_Is_Complete=1
			INNER JOIN ASSESSMENT.T_Assessment_CourseList_Course_Map TACCM ON TSAS.I_CourseList_ID=TACCM.I_Course_List_ID
			AND EC.I_Course_ID=TACCM.I_Course_ID
			INNER JOIN dbo.T_Student_Detail TSD ON TSAS.I_Enquiry_Regn_ID=TSD.I_Enquiry_Regn_ID
			INNER JOIN dbo.T_Student_Batch_Details TSBD ON TSD.I_Student_Detail_ID=TSBD.I_Student_ID
			INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID=TSBM.I_Batch_ID
			AND TACCM.I_Course_ID=TSBM.I_Course_ID
			WHERE ERD.Dt_Crtd_On BETWEEN @dtStartDate AND @dtEndDate
			GROUP BY EC.I_Course_ID,ERD.I_Centre_Id
		)
		AS ADMITSAME ON A.CenterID=ADMITSAME.I_Centre_Id AND A.CourseID=ADMITSAME.I_Course_ID
		LEFT JOIN
		(
			SELECT EC.I_Course_ID,ERD.I_Centre_Id,COUNT(distinct TSAM.I_Enquiry_Regn_ID) AS ADMITDIFF
			FROM dbo.T_Enquiry_Regn_Detail ERD
			INNER JOIN dbo.T_Enquiry_Course EC ON ERD.I_Enquiry_Regn_ID=EC.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Suggestion TSAS ON ERD.I_Enquiry_Regn_ID=TSAS.I_Enquiry_Regn_ID
			INNER JOIN ASSESSMENT.T_Student_Assessment_Map TSAM ON TSAS.I_Enquiry_Regn_ID=TSAM.I_Enquiry_Regn_ID
			AND TSAM.B_Is_Complete=1
			INNER JOIN ASSESSMENT.T_Assessment_CourseList_Course_Map TACCM ON TSAS.I_CourseList_ID=TACCM.I_Course_List_ID
			AND EC.I_Course_ID=TACCM.I_Course_ID
			INNER JOIN dbo.T_Student_Detail TSD ON TSAS.I_Enquiry_Regn_ID=TSD.I_Enquiry_Regn_ID
			INNER JOIN dbo.T_Student_Batch_Details TSBD ON TSD.I_Student_Detail_ID=TSBD.I_Student_ID
			INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID=TSBM.I_Batch_ID
			AND TACCM.I_Course_ID<>TSBM.I_Course_ID
			WHERE ERD.Dt_Crtd_On BETWEEN @dtStartDate AND @dtEndDate
			GROUP BY EC.I_Course_ID,ERD.I_Centre_Id
		)
		AS ADMITDIFF ON A.CenterID=ADMITDIFF.I_Centre_Id AND A.CourseID=ADMITDIFF.I_Course_ID

		SELECT TCHNM.S_Brand_Name,TCHNM.S_Region_Name,TCHNM.S_Territiry_Name,TCHNM.S_City_Name,TCHNM.S_Center_Name,A.* 
		FROM @Assess A
		INNER JOIN T_Center_Hierarchy_Name_Details TCHNM ON A.CenterID=TCHNM.I_Center_ID
		ORDER BY Center
	End
	
	
--Select * from ASSESSMENT.T_Assessment_CourseList_Course_Map WHERE I_Course_List_ID in
--(
--Select I_CourseList_ID from ASSESSMENT.T_Student_Assessment_Suggestion Where I_Enquiry_Regn_ID in
--(
--Select I_Enquiry_Regn_ID from ASSESSMENT.T_Student_Assessment_Map Where B_Is_Complete=1 --And I_Enquiry_Regn_ID=338338
--)
--)

--Select * from dbo.T_Course_Center_Detail
GO
PRINT N'Creating Procedure [REPORT].[uspGetQueryStatusReport]...';


GO
/*
-- =================================================================
-- Author: Ujjwal Sinha
-- Create date: 09/07/2007 
-- Description:  This sp for Customer care query status report ,
--				this return dataset of Customer Care Complaints
-- =================================================================
*/

CREATE PROCEDURE [REPORT].[uspGetQueryStatusReport]
(
	@iBrandID		INT		,
	@sHierarchyList 	varchar(MAX)	,
	@iStatusID		INT = NULL	,	
	@DtFrmDate		DATETIME = NULL	,
	@DtToDate		DATETIME = NULL	,
	@iRootCauseID		INT = NULL,
	@sStatusName varchar(50)= NULL,
	@sRootCauseName varchar(20) = NULL

)
AS
BEGIN TRY
   SELECT
	SM.S_Status_Desc	,
	(CM.S_Root_Cause_Code +' - '+ CM.S_Root_Cause_Desc) AS S_Root_Cause_Desc 	,
    COUNT(*) AS NUMBER,
	FN1.CenterCode,
	FN1.CenterName,
	FN2.InstanceChain
   FROM [CUSTOMERCARE].T_Complaint_Request_Detail CR
        INNER JOIN 
	[CUSTOMERCARE].T_Root_Cause_Master CM
        ON CR.I_Root_Cause_ID = CM.I_Root_Cause_ID
	INNER JOIN 
	[dbo].T_Status_Master SM
        ON CR.I_STATUS_ID = SM.I_Status_Value
        AND SM.S_Status_Type='CustomerCareStatus'
	INNER JOIN
	[dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
	ON CR.I_Center_Id=FN1.CenterID
	INNER JOIN
	[dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
	ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
   WHERE CR.I_Root_Cause_ID = COALESCE(@iRootCauseID,CR.I_Root_Cause_ID)
     AND CR.I_STATUS_ID = COALESCE(@iStatusID,CR.I_STATUS_ID)
     AND CR.Dt_Complaint_Date 
	 BETWEEN COALESCE(@DtFrmDate,CR.Dt_Complaint_Date) 
     AND DATEADD(dd,1,COALESCE(@DtToDate,CR.Dt_Complaint_Date))
   GROUP BY CR.I_Center_Id, FN1.CenterCode, FN1.CenterName, FN2.InstanceChain, SM.S_Status_Desc,
            CM.S_Root_Cause_Desc,S_Root_Cause_Code
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetQueryComplaintDetails]...';


GO
/*
-- =================================================================
-- Author: Shankha Roy
-- Create date: 10/07/2007 
-- Description: This sp used Query Detailed Reports of Customer care
-- Returns : DataSet
-- =================================================================
*/

CREATE PROCEDURE [REPORT].[uspGetQueryComplaintDetails]
(
	@iBrandID		INT		,
	@sHierarchyList 	varchar(MAX)	,
	@DtFrmDate		DATETIME=NULL	,
	@DtToDate		DATETIME=NULL

)
AS
BEGIN TRY

SELECT		DISTINCT
			CR.I_Complaint_Req_ID,
			CR.S_Complaint_Code	,
			CONVERT(VARCHAR(12),CR.Dt_Complaint_Date,106) AS Dt_Complaint_Date,
			CR.I_Complaint_Mode_ID,
			CM.S_Complaint_Mode_Value	,
			CT.S_Complaint_Desc	AS Category	,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			TBM.S_Brand_Name AS Product,
			TBM.S_Brand_Code,
			--ISNULL(TUM.S_Login_ID,'') AS ProcessOwner,
			ISNULL(TUM.[S_Title],'') + ' ' + ISNULL(TUM.[S_First_Name],'') + ' ' + ISNULL(TUM.[S_Middle_Name],'') + ' ' + ISNULL(TUM.[S_Last_Name],'')AS ProcessOwner,
			ISNULL((TUM.S_Title + ' '+TUM.S_First_Name + ' '+TUM.S_Middle_Name+' '+TUM.S_Last_Name),'') AS UserName,
  			ISNULL(TUM.S_Email_ID, '') AS S_Email_ID,
			ISNULL((SD.S_Title + ' '+SD.S_First_Name + ' '+SD.S_Middle_Name+' '+SD.S_Last_Name),'') AS StudentName,
			CR.S_Complaint_Details		,
			ISNULL(([REPORT].fnGetCycleTimeForCustomerCare(2,CR.I_Status_ID,CR.I_Complaint_Req_ID)),0) AS CycleTimeNew,
			--ISNULL(CONVERT(INT,(DATEDIFF(DD,CR.Dt_Complaint_Date,GETDATE()))),0) AS Cycle	,
			SM.S_Status_Desc AS Status,
			TCAT1.S_Remarks AS Feedback1,
			TCAT2.S_Remarks AS Feedback2,
			TCAT3.S_Remarks AS Feedback3
			FROM [CUSTOMERCARE].T_Complaint_Request_Detail CR
				INNER JOIN 
			[CUSTOMERCARE].T_Complaint_Mode_Master CM
				ON CM.I_Complaint_Mode_ID = CR.I_Complaint_Mode_ID
				INNER JOIN 
			[CUSTOMERCARE].T_Complaint_Category_Master CT
			ON CT.I_Complaint_Category_ID = CR.I_Complaint_Category_ID
				LEFT OUTER JOIN
			[CUSTOMERCARE].T_Complaint_Feedback CF
				ON CF.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			INNER JOIN
			[dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
			ON CR.I_Center_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
			ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
   			INNER JOIN dbo.T_Brand_Center_Details BCD
			ON CR.I_Center_Id=BCD.I_Centre_Id			
			INNER JOIN dbo.T_Brand_Master TBM
			ON BCD.I_Brand_ID = TBM.I_Brand_ID
			--LEFT OUTER JOIN dbo.T_Employee_Dtls ED
			--ON ED.I_Employee_ID = CR.I_User_ID	
			LEFT OUTER JOIN dbo.T_User_Master TUM
			--ON TUM.I_Reference_ID = ED.I_Employee_ID
			ON TUM.I_User_ID = CR.I_User_ID
			LEFT OUTER JOIN CUSTOMERCARE.T_Complaint_Audit_Trail TCAT1
			ON TCAT1.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			AND TCAT1.I_Complaint_Audit_ID = (SELECT MIN(T1.I_Complaint_Audit_ID) FROM 
			CUSTOMERCARE.T_Complaint_Audit_Trail T1 WHERE T1.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			AND T1.I_Status_ID IN(4,12)
			AND T1.S_Remarks IS NOT NULL
			)
			LEFT OUTER JOIN CUSTOMERCARE.T_Complaint_Audit_Trail TCAT2
			ON TCAT2.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			AND TCAT2.I_Complaint_Audit_ID = (SELECT (MIN(T2.I_Complaint_Audit_ID)+1) FROM 
			CUSTOMERCARE.T_Complaint_Audit_Trail T2 WHERE T2.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			AND T2.I_Status_ID IN (4,5,10,12)
			AND T2.S_Remarks IS NOT NULL)
			LEFT OUTER JOIN CUSTOMERCARE.T_Complaint_Audit_Trail TCAT3
			ON TCAT3.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			AND TCAT3.I_Complaint_Audit_ID = (SELECT (MIN(T3.I_Complaint_Audit_ID)+2) FROM 
			CUSTOMERCARE.T_Complaint_Audit_Trail T3 WHERE T3.I_Complaint_Req_ID = CR.I_Complaint_Req_ID
			AND T3.I_Status_ID IN (5,10,12)
			AND T3.S_Remarks IS NOT NULL 
			)	
			INNER JOIN dbo.T_Student_Detail SD
			ON SD.I_Student_Detail_ID = CR.I_Student_Detail_ID
			INNER JOIN dbo.T_Status_Master SM
			ON SM.I_Status_Value = CR.I_Status_ID
			AND SM.S_Status_Type = 'CustomerCareStatus'
			
		   WHERE CR.Dt_Complaint_Date BETWEEN COALESCE(@DtFrmDate,CR.Dt_Complaint_Date) 
		   AND COALESCE(DATEADD(dd,1,@DtToDate),CR.Dt_Complaint_Date) 


      
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetReportOnCancelInvoice]...';


GO
/*******************************************************
Author	:     Subhendu Chatterjee
Date	:	  28/04/2011
Description : This SP retrieves the Cancelled Invoice Data
				
*********************************************************/


CREATE PROCEDURE [REPORT].[uspGetReportOnCancelInvoice] 
(
	-- Add the parameters for the stored procedure here
	@dtStartDate datetime=NULL,
	@dtEndDate datetime=NULL,
	@iBrandID INT,
	@sHierarchyList varchar (MAX)
)
AS
BEGIN TRY
	
SELECT	TCM.[BrandID] AS I_BRAND_ID,[TBM].[S_Brand_Code],[TCM].[centerName] AS S_Center_Name,[TSD].[S_Student_ID],[TIP].[S_Invoice_No],
		[TIP].[N_Invoice_Amount],[TIP].[N_Discount_Amount],[TIP].[N_Tax_Amount],[TIP].[Dt_Invoice_Date],
		[TIP].[Dt_Upd_On] AS Invoice_Cancelled_On
FROM [dbo].[T_Invoice_Parent] AS TIP 
INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) TCM
ON [TIP].[I_Centre_Id] = [TCM].centerID
INNER JOIN dbo.T_Brand_Master TBM ON TCM.BrandID=TBM.I_Brand_ID
INNER JOIN [dbo].[T_Student_Detail] AS TSD
ON [TSD].[I_Student_Detail_ID] = [TIP].[I_Student_Detail_ID]
WHERE [TIP].[I_Status] = 0
AND DATEDIFF(dd,[TIP].[Dt_Upd_On],ISNULL(@dtStartDate,[TIP].[Dt_Upd_On])) <= 0
AND DATEDIFF(dd,[TIP].[Dt_Upd_On],ISNULL(@dtEndDate,[TIP].[Dt_Upd_On])) >= 0
AND TCM.brandID=@iBrandID
ORDER BY [TBM].[S_Brand_Code], [TIP].[I_Invoice_Header_ID]

			
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspGetRepeaterStudentList]...';


GO
CREATE PROCEDURE REPORT.uspGetRepeaterStudentList
    (
      @iBrandID INT ,
      @sHierarchyListID VARCHAR(MAX) ,
      @dtStartDate DATETIME ,
      @dtEndDate DATETIME ,
      @sBatchID VARCHAR(MAX) = NULL
    )
AS 
    BEGIN
        SELECT  TCHND.I_Center_ID ,
                TCHND.S_Center_Name ,
                DATENAME(MONTH, TSBD.Dt_Valid_From) + ' '
                + CAST(DATEPART(YYYY, TSBD.Dt_Valid_From) AS VARCHAR) AS MonthYear ,
                TCM.I_Course_ID ,
                TCM.S_Course_Name ,
                COUNT(DISTINCT TSD.S_Student_ID) AS CountofStudents
        FROM    dbo.T_Student_Detail TSD
                INNER JOIN dbo.T_Student_Batch_Details TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
                INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
        WHERE   TSBD.I_Status = 1
                AND TCHND.I_Center_ID IN (
                SELECT  FGCFR.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                   @iBrandID) FGCFR )
                AND TSBD.I_Batch_ID IN (
                SELECT  CAST(FSR.Val AS INT)
                FROM    dbo.fnString2Rows(@sBatchID, ',') FSR )
                AND DATEPART(YEAR, TSBM.Dt_BatchStartDate) != DATEPART(YEAR,
                                                              TSD.Dt_Crtd_On)
                AND TSBD.Dt_Valid_From BETWEEN @dtStartDate
                                       AND     @dtEndDate
                                       
                                       GROUP BY 
                                       TCHND.I_Center_ID ,
                TCHND.S_Center_Name ,
                DATENAME(MONTH, TSBD.Dt_Valid_From) + ' '
                + CAST(DATEPART(YYYY, TSBD.Dt_Valid_From) AS VARCHAR) ,
                TCM.I_Course_ID ,
                TCM.S_Course_Name 
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetRegistrationListingReport]...';


GO
CREATE PROCEDURE [REPORT].[uspGetRegistrationListingReport]
(
	-- Add the parameters for the stored procedure here
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@dtStartDate datetime,
	@dtEndDate datetime,
	@sCounselorCond varchar(20)
)
AS
SET NOCOUNT ON
BEGIN TRY

	IF (@dtEndDate IS NOT NULL)
	BEGIN
		SET @dtEndDate = DATEADD(dd,1,@dtEndDate)
	END
	
	IF @sCounselorCond='ALL'
	BEGIN
	 SELECT DISTINCT 
			ERD.I_Enquiry_Regn_ID,
			ERD.S_Enquiry_No,
			ERD.S_Title,
			ERD.S_First_Name,
			ERD.S_Middle_Name,
			ERD.S_Last_Name,
			ISNULL(RH.N_Receipt_Amount,0.00) AS N_Receipt_Amount,
			CAST (RH.Dt_Receipt_Date AS DATE) AS Dt_Receipt_Date,
			UM.S_Title AS Coun_Title,
			UM.S_First_Name AS Coun_FirstName,
			UM.S_Middle_Name AS Coun_MiddleName,
			UM.S_Last_Name AS Coun_LastName,
			CM.S_Course_Code,
			CM.S_Course_Name,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code
	   FROM	dbo.T_Enquiry_Regn_Detail ERD WITH(NOLOCK)
			INNER JOIN dbo.T_Receipt_Header RH WITH(NOLOCK)
			ON ERD.I_Enquiry_Regn_ID=RH.I_Enquiry_Regn_ID
			INNER JOIN dbo.T_User_Master UM WITH(NOLOCK)
			ON ERD.S_Crtd_By=UM.S_Login_ID
			INNER JOIN [dbo].[T_Student_Registration_Details] AS TSRD
			ON [TSRD].[I_Receipt_Header_ID] = [RH].[I_Receipt_Header_ID]
			AND [TSRD].[I_Enquiry_Regn_ID] = [RH].[I_Enquiry_Regn_ID]
			INNER JOIN [dbo].[T_Student_Batch_Master] AS TSBM
			ON [TSRD].[I_Batch_ID] = [TSBM].[I_Batch_ID]
			INNER JOIN dbo.T_Course_Master CM WITH(NOLOCK)
			ON [TSBM].[I_Course_ID] = [CM].[I_Course_ID]
			INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
			ON ERD.I_Centre_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
			ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
			INNER JOIN dbo.T_Centre_Master CEM WITH(NOLOCK)
			ON FN1.CenterID=CEM.I_Centre_Id
			INNER JOIN dbo.T_Country_Master COM WITH(NOLOCK)
			ON CEM.I_Country_ID=COM.I_Country_ID
			INNER JOIN dbo.T_Currency_Master CUM WITH(NOLOCK)
			ON COM.I_Currency_ID=CUM.I_Currency_ID
	  WHERE RH.I_Student_Detail_ID IS NULL
		AND	RH.I_Invoice_Header_ID IS NULL
		AND	RH.I_Receipt_Type=1
		AND	RH.I_Status=1
		AND RH.Dt_Receipt_Date BETWEEN @dtStartDate AND @dtEndDate
		AND [RH].[I_Student_Detail_ID] NOT IN 
		(SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM)
   ORDER BY FN2.InstanceChain,
			FN1.CenterName,
			UM.S_Title,
			UM.S_First_Name,
			UM.S_Middle_Name,
			UM.S_Last_Name,
			ERD.S_Enquiry_No

	END
	ELSE
	BEGIN
	 SELECT DISTINCT 
			ERD.I_Enquiry_Regn_ID,
			ERD.S_Enquiry_No,
			ERD.S_Title,
			ERD.S_First_Name,
			ERD.S_Middle_Name,
			ERD.S_Last_Name,
			ISNULL(RH.N_Receipt_Amount,0.00) AS N_Receipt_Amount,
			RH.Dt_Receipt_Date,
			UM.S_Title AS Coun_Title,
			UM.S_First_Name AS Coun_FirstName,
			UM.S_Middle_Name AS Coun_MiddleName,
			UM.S_Last_Name AS Coun_LastName,
			CM.S_Course_Code,
			CM.S_Course_Name,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			CUM.S_Currency_Code
	   FROM	dbo.T_Enquiry_Regn_Detail ERD WITH(NOLOCK)
			INNER JOIN dbo.T_Receipt_Header RH WITH(NOLOCK)
			ON ERD.I_Enquiry_Regn_ID=RH.I_Enquiry_Regn_ID
			INNER JOIN dbo.T_User_Master UM WITH(NOLOCK)
			ON ERD.S_Crtd_By=UM.S_Login_ID
			INNER JOIN [dbo].[T_Student_Registration_Details] AS TSRD
			ON [TSRD].[I_Receipt_Header_ID] = [RH].[I_Receipt_Header_ID]
			AND [TSRD].[I_Enquiry_Regn_ID] = [RH].[I_Enquiry_Regn_ID]
			INNER JOIN [dbo].[T_Student_Batch_Master] AS TSBM
			ON [TSRD].[I_Batch_ID] = [TSBM].[I_Batch_ID]
			INNER JOIN dbo.T_Course_Master CM WITH(NOLOCK)
			ON [TSBM].[I_Course_ID] = [CM].[I_Course_ID]
			INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
			ON ERD.I_Centre_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
			ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
			INNER JOIN dbo.T_Centre_Master CEM WITH(NOLOCK)
			ON FN1.CenterID=CEM.I_Centre_Id
			INNER JOIN dbo.T_Country_Master COM WITH(NOLOCK)
			ON CEM.I_Country_ID=COM.I_Country_ID
			INNER JOIN dbo.T_Currency_Master CUM WITH(NOLOCK)
			ON COM.I_Currency_ID=CUM.I_Currency_ID
	  WHERE RH.I_Student_Detail_ID IS NULL
		AND	RH.I_Invoice_Header_ID IS NULL
		AND	RH.I_Receipt_Type=1
		AND	RH.I_Status=1
		AND RH.Dt_Receipt_Date BETWEEN @dtStartDate AND @dtEndDate
		AND ERD.S_Crtd_By = @sCounselorCond
		AND [RH].[I_Student_Detail_ID] NOT IN 
		(SELECT [TCSIM].[I_Student_Detail_ID] FROM [dbo].[T_Corp_Student_Invoice_Map] AS TCSIM)
   ORDER BY FN2.InstanceChain,
			FN1.CenterName,
			UM.S_Title,
			UM.S_First_Name,
			UM.S_Middle_Name,
			UM.S_Last_Name,
			ERD.S_Enquiry_No

	END

END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
