            END
                        
        ELSE
            BEGIN                                                         
            
                INSERT  INTO #FINDATA
                        ( I_Brand_ID ,
                          S_Brand_Name ,
                          I_Center_ID ,
                          S_Center_Name ,
                          TypeofCentre ,
                          TransactionDate ,
                          MonthYear ,
                          I_Course_ID ,
                          S_Course_Name ,
                          I_FeeComponent_ID ,
                          FeeComponentName ,
                          TypeofComp ,
                          NValue,
                          Sequence,
