                        [TSBM].[Dt_Course_Actual_End_Date] ,
                        TSBM.Dt_BatchIntroductionDate ,
                        TDPM.S_Pattern_Name ,
                        TSBM.I_TimeSlot_ID ,
                        TCBD.Max_Strength ,
                        StudentCount.NoOfStudents ,
                        HistStudentCount.HistNoOfStudents ,
                        [TSBM].[b_IsHOBatch] ,
