CREATE PROCEDURE [REPORT].[uspGetStudentBatchList]-- [REPORT].[uspGetStudentBatchList] 107,'1','5'   
    (
      @iBrandId INT ,
      @sHierarchyList VARCHAR(MAX) ,
      @iBatchId VARCHAR(MAX) = NULL    
    )
AS 
    BEGIN    
    
    IF (@iBatchId IS NOT NULL AND  @iBatchId!='' AND @iBatchId!=0 AND @iBatchId!='--Select--' )
    BEGIN
        SELECT  E.S_Brand_Name ,
                C.S_Batch_Name ,
                A.S_Student_ID ,
                A.S_First_Name ,
                A.S_Middle_Name ,
                A.S_Last_Name ,
                I.S_Sex_Name ,
                a.Dt_Birth_Date AS DateOfBirth ,
                A.S_Mobile_No ,
                H.S_Father_Name ,
                H.S_Mother_Name ,
                H.S_Phone_No ,
                CASE WHEN F.I_Brand_ID = 107
                     THEN CASE WHEN H.S_Father_Name IS NOT NULL
                                    AND LTRIM(RTRIM(H.S_Father_Name)) <> ''
                               THEN H.S_Father_Name
                               ELSE H.S_Mother_Name
                          END
                     ELSE A.S_Guardian_Name
                END AS S_Guardian_Name ,
                A.S_Curr_Address1 ,
                A.S_Perm_Address1 ,
                G.S_House_Name ,
                K.S_Route_No ,
                J.S_PickupPoint_Name,
                A.S_Guardian_Phone_No AS S_Guardian_Mobile_No,
                CASE WHEN C.Dt_BatchStartDate>GETDATE() THEN 'Waiting'
                WHEN C.Dt_BatchStartDate<=GETDATE() AND T1.AttnCount IS NULL THEN 'Waiting'
                WHEN C.Dt_BatchStartDate<=GETDATE() AND T1.AttnCount IS NOT NULL THEN 'Active'
                END AS StdStatus
        FROM    T_Student_Detail A
                INNER JOIN T_Student_Batch_Details B ON A.I_Student_Detail_ID = B.I_Student_ID
                INNER JOIN T_Student_Batch_Master C ON C.I_Batch_ID = B.I_Batch_ID
                INNER JOIN T_Center_Batch_Details D ON C.I_Batch_ID = D.I_Batch_ID
                INNER JOIN T_Center_Hierarchy_Name_Details E ON E.I_Center_ID = D.I_Centre_Id
                INNER JOIN T_Course_Master F ON F.I_Course_ID = C.I_Course_ID    
--left join T_House_Master G    
--on A.I_House_ID=G.I_House_ID    
                INNER JOIN T_Enquiry_Regn_Detail H ON H.I_Enquiry_Regn_ID = A.I_Enquiry_Regn_ID
                LEFT JOIN T_User_Sex I ON I.I_Sex_ID = H.I_Sex_ID
                LEFT JOIN T_House_Master G ON A.I_House_ID = G.I_House_ID
                LEFT JOIN T_Transport_Master J ON J.I_PickupPoint_ID = A.I_Transport_ID
                LEFT JOIN T_BusRoute_Master K ON K.I_Route_ID = A.I_Route_ID
                LEFT JOIN
                (
                SELECT TSA.I_Student_Detail_ID,COUNT(DISTINCT TSA.I_TimeTable_ID) AS AttnCount FROM dbo.T_Student_Attendance TSA
                GROUP BY TSA.I_Student_Detail_ID
                ) T1 ON A.I_Student_Detail_ID = T1.I_Student_Detail_ID
                INNER JOIN T_Brand_Master L ON L.I_Brand_ID = E.I_Brand_ID    
--INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList,@iBrandID) TBCD2     
--ON [TBCD2].centerID = E.I_Center_ID    
        WHERE   B.I_Status = 1    
--and C.I_Batch_ID=5    
                AND C.I_Batch_ID = CAST(@iBatchId AS INT)
                AND E.I_Center_ID IN (
                SELECT  CenterList.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyList,
                                                   CAST(@iBrandID AS INT)) CenterList )
        ORDER BY A.S_First_Name
        
        END
        
        ELSE
        
        BEGIN
        	SELECT  E.S_Brand_Name ,
                C.S_Batch_Name ,
                A.S_Student_ID ,
                A.S_First_Name ,
                A.S_Middle_Name ,
                A.S_Last_Name ,
                I.S_Sex_Name ,
                a.Dt_Birth_Date AS DateOfBirth ,
                A.S_Mobile_No ,
                H.S_Father_Name ,
                H.S_Mother_Name ,
                H.S_Phone_No ,
                CASE WHEN F.I_Brand_ID = 107
                     THEN CASE WHEN H.S_Father_Name IS NOT NULL
                                    AND LTRIM(RTRIM(H.S_Father_Name)) <> ''
                               THEN H.S_Father_Name
                               ELSE H.S_Mother_Name
                          END
                     ELSE A.S_Guardian_Name
                END AS S_Guardian_Name ,
                A.S_Curr_Address1 ,
                A.S_Perm_Address1 ,
                G.S_House_Name ,
                K.S_Route_No ,
                J.S_PickupPoint_Name,
                A.S_Guardian_Phone_No AS S_Guardian_Mobile_No,
                CASE WHEN C.Dt_BatchStartDate>GETDATE() THEN 'Waiting'
                WHEN C.Dt_BatchStartDate<=GETDATE() AND T1.AttnCount IS NULL THEN 'Waiting'
                WHEN C.Dt_BatchStartDate<=GETDATE() AND T1.AttnCount IS NOT NULL THEN 'Active'
                END AS StdStatus
        FROM    T_Student_Detail A
                INNER JOIN T_Student_Batch_Details B ON A.I_Student_Detail_ID = B.I_Student_ID
                INNER JOIN T_Student_Batch_Master C ON C.I_Batch_ID = B.I_Batch_ID
                INNER JOIN T_Center_Batch_Details D ON C.I_Batch_ID = D.I_Batch_ID
                INNER JOIN T_Center_Hierarchy_Name_Details E ON E.I_Center_ID = D.I_Centre_Id
                INNER JOIN T_Course_Master F ON F.I_Course_ID = C.I_Course_ID    
--left join T_House_Master G    
--on A.I_House_ID=G.I_House_ID    
                INNER JOIN T_Enquiry_Regn_Detail H ON H.I_Enquiry_Regn_ID = A.I_Enquiry_Regn_ID
                LEFT JOIN T_User_Sex I ON I.I_Sex_ID = H.I_Sex_ID
                LEFT JOIN T_House_Master G ON A.I_House_ID = G.I_House_ID
                LEFT JOIN T_Transport_Master J ON J.I_PickupPoint_ID = A.I_Transport_ID
                LEFT JOIN T_BusRoute_Master K ON K.I_Route_ID = A.I_Route_ID
                LEFT JOIN
                (
                SELECT TSA.I_Student_Detail_ID,COUNT(DISTINCT TSA.I_TimeTable_ID) AS AttnCount FROM dbo.T_Student_Attendance TSA
                GROUP BY TSA.I_Student_Detail_ID
                ) T1 ON A.I_Student_Detail_ID = T1.I_Student_Detail_ID
                INNER JOIN T_Brand_Master L ON L.I_Brand_ID = E.I_Brand_ID    
--INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList,@iBrandID) TBCD2     
--ON [TBCD2].centerID = E.I_Center_ID    
        WHERE   B.I_Status = 1    
--and C.I_Batch_ID=5    
                --AND C.I_Batch_ID = CAST(@iBatchId AS INT)
                AND E.I_Center_ID IN (
                SELECT  CenterList.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyList,
                                                   CAST(@iBrandID AS INT)) CenterList )
        ORDER BY A.S_First_Name
        END
        
        
            
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetStudentBatchCourse]...';


GO
/*******************************************************  
Author :     SUBHENDU CHATTERJEE  
Date :   05/12/2011  
Description : This SP retrieves the Invigilator Report Detail  
      
*********************************************************/  
  
  
CREATE PROCEDURE [REPORT].[uspGetStudentBatchCourse]
    (
      -- Add the parameters for the stored procedure here  
      @dtStartDate DATETIME = NULL ,
      @dtEndDate DATETIME = NULL ,
      @sCourseID VARCHAR(MAX) ,
      @iBatchID INT = NULL ,
      @iBrandID INT ,
      @sHierarchyList VARCHAR(MAX)
    )
AS 
    BEGIN TRY  
   
        DECLARE @InstanceChain NVARCHAR(4000)= NULL  
    
        IF ( @iBatchID IS NOT NULL ) 
            BEGIN  
                SELECT  @InstanceChain = @InstanceChain + '; Batch: '
                        + A.S_Batch_Code
                FROM    [dbo].[T_Student_Batch_Master] AS A
                WHERE   A.I_Batch_ID = @iBatchID  
            END  
        ELSE 
            BEGIN  
                SET @InstanceChain = @InstanceChain + '; Batch: ALL'  
            END   
    
        DECLARE @tblCourse TABLE ( CourseID INT )  
    
        IF ( @sCourseID IS NOT NULL ) 
            BEGIN  
                INSERT  INTO @tblCourse
                        SELECT  CAST([Val] AS INT)
                        FROM    [dbo].[fnString2Rows](@sCourseID, ',') AS FSR  
                SELECT  @InstanceChain = @InstanceChain + 'Course: '
                        + A.S_Course_Name
                FROM    [dbo].[T_Course_Master] AS A
                WHERE   A.I_Course_ID IN ( SELECT   CourseID
                                           FROM     @tblCourse )  
            END  
        ELSE 
            BEGIN  
                INSERT  INTO @tblCourse
                        SELECT  I_Course_ID
                        FROM    DBO.T_Course_Master  
                SET @InstanceChain = @InstanceChain + 'Course: ALL'  
            END  
     
        SELECT DISTINCT
                TBCD2.brandID ,
                tsd.I_Student_Detail_ID ,
                [tsd].[S_Student_ID] ,
                [tsd].[S_Title] ,
                [tsd].[S_First_Name] ,
                [tsd].[S_Middle_Name] ,
                [tsd].[S_Last_Name] ,
                TSBM.I_Batch_ID ,
                [TSBM].[S_Batch_Code] ,
                [TSBM].S_Batch_Name ,
                [TCM].[S_Course_Name] ,
                [TCFM].[S_CourseFamily_Name] ,
                tsd.S_Phone_No ,
                tsd.S_Mobile_No ,
                [TSD].S_Email_ID ,
				Tsd.S_Curr_Address1 +' ' + tsd.S_Curr_Address2 as S_Curr_Stud_Address,
				Tsd.S_Perm_Address1 +' ' + tsd.S_Perm_Address2 as S_Perm_Stud_Address,
				Tsd.S_Guardian_Name,
                TBCD2.centerName AS S_Center_Name ,
                @InstanceChain AS InstanceChain
        FROM    [dbo].[T_Student_Detail] AS TSD
                INNER JOIN [dbo].[T_Student_Batch_Details] AS TSBD ON [TSD].[I_Student_Detail_ID] = [TSBD].[I_Student_ID]
                INNER JOIN [dbo].[T_Student_Batch_Master] AS TSBM ON [TSBD].[I_Batch_ID] = [TSBM].[I_Batch_ID]
                INNER JOIN [dbo].[T_Course_Master] AS TCM ON [TSBM].[I_Course_ID] = [TCM].[I_Course_ID]
                INNER JOIN [dbo].[T_CourseFamily_Master] AS TCFM ON [TCM].[I_CourseFamily_ID] = [TCFM].[I_CourseFamily_ID]
                INNER JOIN [dbo].[T_Student_Center_Detail] AS TSCD ON [TSCD].[I_Student_Detail_ID] = [tsd].[I_Student_Detail_ID]
                INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList,
                                                          @iBrandID) TBCD2 ON [TBCD2].centerID = [TSCD].[I_Centre_Id]
                INNER JOIN DBO.[T_Enquiry_Regn_Detail] AS TERD ON TERD.I_Enquiry_Regn_ID = TSD.I_Enquiry_Regn_ID
                INNER JOIN dbo.T_Invoice_Parent AS TIP ON TSD.I_Student_Detail_ID = TIP.I_Student_Detail_ID
                INNER JOIN dbo.T_Invoice_Child_Header AS tich ON TIP.I_Invoice_Header_ID = tich.I_Invoice_Header_ID
                INNER JOIN dbo.T_Invoice_Batch_Map AS tibm ON tibm.I_Invoice_Child_Header_ID = tich.I_Invoice_Child_Header_ID
                                                              AND TSBM.I_Batch_ID = tibm.I_Batch_ID
        WHERE   TSBD.I_Batch_ID = ISNULL(@iBatchID, TSBD.I_Batch_ID)
                AND TCM.I_Course_ID IN ( SELECT CourseID
                                         FROM   @tblCourse )
                AND DATEDIFF(dd, ISNULL(@dtStartDate, TIP.Dt_Invoice_Date),
                             TIP.Dt_Invoice_Date) >= 0
                AND DATEDIFF(dd, ISNULL(@dtEndDate, TIP.Dt_Invoice_Date),
                             TIP.Dt_Invoice_Date) <= 0                
        ORDER BY [TBCD2].[brandID] ,
                [tsd].[I_Student_Detail_ID]  
     
    END TRY  
  
    BEGIN CATCH  
   
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT  
  
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()  
  
        RAISERROR(@ErrMsg, @ErrSeverity, 1)  
    END CATCH
GO
