CREATE PROCEDURE [REPORT].[uspGetTeacherFreeTimeReport]
    (
      @iBrandID INT ,
      @HierarchyListID VARCHAR(MAX),
      @dtOnDate DATE,
      @sFacultyName VARCHAR(MAX)
    )
AS 
    BEGIN
		
		IF(@sFacultyName='ALL')
		BEGIN
        SELECT  T3.I_Employee_ID ,
                T3.FacultyName ,
                T3.Period ,
                CASE WHEN T4.I_Employee_ID IS NULL THEN 'YES'
                     WHEN T4.I_Employee_ID IS NOT NULL THEN 'NO'
                END AS Availability
        FROM    ( SELECT    T1.I_Employee_ID ,
                            T1.FacultyName ,
                            T2.Period
                  FROM      ( SELECT    TED.I_Employee_ID ,
                                        TED.S_First_Name + ' '
                                        + ISNULL(TED.S_Middle_Name, '') + ' '
                                        + TED.S_Last_Name AS FacultyName
                              FROM      dbo.T_Employee_Dtls TED
										INNER JOIN SMS.dbo.T_TimeTable_Faculty_Map TTTFM ON TED.I_Employee_ID = TTTFM.I_Employee_ID
                INNER JOIN SMS.dbo.T_TimeTable_Master TTTM ON TTTFM.I_TimeTable_ID = TTTM.I_TimeTable_ID
                INNER JOIN SMS.dbo.T_User_Master TUM ON TED.I_Employee_ID = TUM.I_Reference_ID
        WHERE   TED.I_Status = 3
                AND TTTM.I_Status = 1
                AND TTTFM.B_Is_Actual IN ( 0, 1 )
                AND TTTM.I_Center_ID IN (
                SELECT  FGCFR.centerID
                FROM    SMS.dbo.fnGetCentersForReports(@HierarchyListID,
                                                   @iBrandID) FGCFR )
                AND CONVERT(DATE, TTTM.Dt_Schedule_Date) = CONVERT(DATE, @dtOnDate)
                              --          INNER JOIN EOS.T_Employee_Role_Map TERM ON TED.I_Employee_ID = TERM.I_Employee_ID
                              --          INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TED.I_Centre_Id = TCHND.I_Center_ID
                              --WHERE     TED.I_Status = 3
                              --          AND TERM.I_Role_ID = 18
                              --          AND TCHND.I_Brand_ID = @iBrandID --AND TED.I_Employee_ID=410
                              --          --AND TED.I_Employee_ID IN (SELECT CAST(FSR.Val AS INT) FROM dbo.fnString2Rows(@sFacultyName,',') FSR)
                            ) T1
                            CROSS JOIN ( SELECT DISTINCT
                                                CAST(CAST(LEFT(CONVERT(TIME, TCTM.Dt_Start_Time),
                                                              5) AS VARCHAR)
                                                + '  to '
                                                + CAST(LEFT(CONVERT(TIME, TCTM.Dt_End_Time),
                                                            5) AS VARCHAR) AS VARCHAR) AS Period
                                         FROM   dbo.T_Center_Timeslot_Master TCTM
                                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCTM.I_Center_ID = TCHND.I_Center_ID
                                                INNER JOIN dbo.T_Centre_Master TCM ON TCHND.I_Center_ID = TCM.I_Centre_Id
                                         WHERE  TCHND.I_Brand_ID = @iBrandID
                                                AND TCTM.I_Status = 1
                                                AND TCM.S_Center_Code NOT LIKE 'FR-%'
                                       ) T2
                ) T3
                LEFT JOIN ( SELECT DISTINCT
                                    CAST(CAST(LEFT(CONVERT(TIME, TCTM.Dt_Start_Time),
                                                   5) AS VARCHAR) + '  to '
                                    + CAST(LEFT(CONVERT(TIME, TCTM.Dt_End_Time),
                                                5) AS VARCHAR) AS VARCHAR) AS Period ,
                                    TTTFM.I_Employee_ID
                            FROM    dbo.T_TimeTable_Faculty_Map TTTFM
                                    INNER JOIN dbo.T_TimeTable_Master TTTM ON TTTFM.I_TimeTable_ID = TTTM.I_TimeTable_ID
                                    INNER JOIN dbo.T_Center_Timeslot_Master TCTM ON TTTM.I_TimeSlot_ID = TCTM.I_TimeSlot_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TTTM.I_Center_ID = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Centre_Master TCM ON TCHND.I_Center_ID = TCM.I_Centre_Id
                            WHERE   TTTFM.B_Is_Actual IN ( 1, 0 )
                                    AND TTTM.I_Status = 1
                                    AND TCHND.I_Brand_ID = @iBrandID
                                    AND CONVERT(DATE, TTTM.Dt_Schedule_Date) = CONVERT(DATE, @dtOnDate)
                                    --AND TTTFM.I_Employee_ID IN (SELECT CAST(FSR.Val AS INT) FROM dbo.fnString2Rows(@sFacultyName,',') FSR)
                          ) T4 ON T3.I_Employee_ID = T4.I_Employee_ID
                                  AND T3.Period = T4.Period
        ORDER BY T3.I_Employee_ID
        END
        ELSE
        BEGIN
        	SELECT  T3.I_Employee_ID ,
                T3.FacultyName ,
                T3.Period ,
                CASE WHEN T4.I_Employee_ID IS NULL THEN 'YES'
                     WHEN T4.I_Employee_ID IS NOT NULL THEN 'NO'
                END AS Availability
        FROM    ( SELECT    T1.I_Employee_ID ,
                            T1.FacultyName ,
                            T2.Period
                  FROM      ( SELECT    TED.I_Employee_ID ,
                                        TED.S_First_Name + ' '
                                        + ISNULL(TED.S_Middle_Name, '') + ' '
                                        + TED.S_Last_Name AS FacultyName
                              FROM      dbo.T_Employee_Dtls TED
                                        INNER JOIN EOS.T_Employee_Role_Map TERM ON TED.I_Employee_ID = TERM.I_Employee_ID
                                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TED.I_Centre_Id = TCHND.I_Center_ID
                              WHERE     TED.I_Status = 3
                                        AND TERM.I_Role_ID = 18
                                        AND TCHND.I_Brand_ID = @iBrandID --AND TED.I_Employee_ID=410
                                        AND TED.I_Employee_ID IN (SELECT CAST(FSR.Val AS INT) FROM dbo.fnString2Rows(@sFacultyName,',') FSR)
                            ) T1
                            CROSS JOIN ( SELECT DISTINCT
                                                CAST(CAST(LEFT(CONVERT(TIME, TCTM.Dt_Start_Time),
                                                              5) AS VARCHAR)
                                                + '  to '
                                                + CAST(LEFT(CONVERT(TIME, TCTM.Dt_End_Time),
                                                            5) AS VARCHAR) AS VARCHAR) AS Period
                                         FROM   dbo.T_Center_Timeslot_Master TCTM
                                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCTM.I_Center_ID = TCHND.I_Center_ID
                                                INNER JOIN dbo.T_Centre_Master TCM ON TCHND.I_Center_ID = TCM.I_Centre_Id
                                         WHERE  TCHND.I_Brand_ID = @iBrandID
                                                AND TCTM.I_Status = 1
                                                AND TCM.S_Center_Code NOT LIKE 'FR-%'
                                       ) T2
                ) T3
                LEFT JOIN ( SELECT DISTINCT
                                    CAST(CAST(LEFT(CONVERT(TIME, TCTM.Dt_Start_Time),
                                                   5) AS VARCHAR) + '  to '
                                    + CAST(LEFT(CONVERT(TIME, TCTM.Dt_End_Time),
                                                5) AS VARCHAR) AS VARCHAR) AS Period ,
                                    TTTFM.I_Employee_ID
                            FROM    dbo.T_TimeTable_Faculty_Map TTTFM
                                    INNER JOIN dbo.T_TimeTable_Master TTTM ON TTTFM.I_TimeTable_ID = TTTM.I_TimeTable_ID
                                    INNER JOIN dbo.T_Center_Timeslot_Master TCTM ON TTTM.I_TimeSlot_ID = TCTM.I_TimeSlot_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TTTM.I_Center_ID = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Centre_Master TCM ON TCHND.I_Center_ID = TCM.I_Centre_Id
                            WHERE   TTTFM.B_Is_Actual IN ( 1, 0 )
                                    AND TTTM.I_Status = 1
                                    AND TCHND.I_Brand_ID = @iBrandID
                                    AND CONVERT(DATE, TTTM.Dt_Schedule_Date) = CONVERT(DATE, @dtOnDate)
                                    AND TTTFM.I_Employee_ID IN (SELECT CAST(FSR.Val AS INT) FROM dbo.fnString2Rows(@sFacultyName,',') FSR)
                                    --AND TTTM.I_Is_Complete = 0
                          ) T4 ON T3.I_Employee_ID = T4.I_Employee_ID
                                  AND T3.Period = T4.Period
        ORDER BY T3.I_Employee_ID
        END


    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetTop20StudentsReport]...';


GO
/****************************************************************      
Author :     Swagatam Sarkar      
Date :   02/Jan/2008      
Description : This SP retrieves the Top 20 Students of a Term      
          
****************************************************************/      
      
      
CREATE PROCEDURE [REPORT].[uspGetTop20StudentsReport]      
(      
 -- Add the parameters for the stored procedure here      
 @sHierarchyList varchar(MAX),      
 @iBrandID int,      
 @DtFrmDate datetime,      
 @DtToDate datetime,      
 @iCourseFamilyID int,      
 @svCourseFamilyName varchar(50),      
 @iCourseID int      
 --@svCourseName varchar(50),      
 --@iTermID int,      
 --@svTermName varchar(50)      
)      
AS      
BEGIN TRY      
 BEGIN      
        
  DECLARE @sCourseFamilyName VARCHAR(50)      
  SET @sCourseFamilyName = (SELECT S_CourseFamily_Name FROM dbo.T_CourseFamily_Master WHERE I_CourseFamily_ID = @iCourseFamilyID)      
      
  IF (@DtToDate IS NOT NULL)      
  BEGIN      
   SET @DtToDate = DATEADD(dd,1,@DtToDate)      
  END      
      
      
  SELECT DISTINCT TOP(20) TCM2.S_Center_Name,@sCourseFamilyName AS S_Course_Family_Name,CM.S_Course_Name,TM.S_Term_Name,      
      SD.I_Student_Detail_ID,SD.S_Title,SD.S_First_Name,SD.S_Middle_Name,SD.S_Last_Name,      
      SM.I_Exam_Total,FN2.InstanceChain, sd.S_Mobile_No,sd.S_Email_ID,ISNULL(sd.S_Guardian_Mobile_No,S_Guardian_Phone_No) AS S_Guardian_Mobile_No     
          
      FROM EXAMINATION.T_Batch_Exam_Map AS tbem        
    INNER JOIN dbo.T_Exam_Component_Master ECM        
     ON tbem.I_Exam_Component_ID=ECM.I_Exam_Component_ID        
    INNER JOIN dbo.T_Student_Batch_Master AS tsbm        
     ON tbem.I_Batch_ID = tsbm.I_Batch_ID        
    INNER JOIN dbo.T_Course_Master CM        
     ON tsbm.I_Course_ID=CM.I_Course_ID        
    INNER JOIN dbo.T_Term_Master TM        
     ON tbem.I_Term_ID=TM.I_Term_ID        
    INNER JOIN dbo.T_Term_Course_Map TCM        
     ON tsbm.I_Course_ID=TCM.I_Course_ID        
     AND tbem.I_Term_ID=TCM.I_Term_ID        
    INNER JOIN EXAMINATION.T_Student_Marks SM        
     ON tbem.I_Batch_Exam_ID = SM.I_Batch_Exam_ID        
    INNER JOIN dbo.T_Student_Detail SD        
     ON SM.I_Student_Detail_ID=SD.I_Student_Detail_ID        
    INNER JOIN dbo.T_Student_Center_Detail AS tscd        
     ON SD.I_Student_Detail_ID = tscd.I_Student_Detail_ID        
    INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1        
     ON tscd.I_Centre_Id=FN1.CenterID        
    INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2    
     ON FN1.HierarchyDetailID=FN2.HierarchyDetailID      
     INNER JOIN dbo.T_Centre_Master AS tcm2      
     ON tscd.I_Centre_Id = TCM2.I_Centre_Id        
    WHERE --sm.I_Exam_Total IS NOT NULL AND sm.I_Exam_Total < 100    
    SM.Dt_Exam_Date BETWEEN @DtFrmDate AND @DtToDate        
   AND tsbm.I_Course_ID =ISNULL(@iCourseID,tsbm.I_Course_ID)         
   ORDER BY SM.I_Exam_Total DESC     
       
        
 END      
END TRY      
      
BEGIN CATCH      
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int      
 SELECT @ErrMsg = ERROR_MESSAGE(),      
   @ErrSeverity = ERROR_SEVERITY()      
 RAISERROR(@ErrMsg, @ErrSeverity, 1)      
END CATCH
GO
