CREATE procedure [REPORT].[uspGetTop20StudentsBatchwise] -- exec [REPORT].[uspGetLast20Students] '2013-05-10',372,1
(
@examdate date,
@i_term_id int,
@i_batch_id int,
@i_rank int,
@iBrandId INT,    
@sHierarchyList VARCHAR(MAX)
)

as 
begin
IF ( UPPER(@i_batch_id) = '--SELECT--'
             OR UPPER(@i_batch_id) = 'ALL'
           ) 
            BEGIN
                SET @i_batch_id = NULL
            END

create table #getlast20students
(
I_Center_Id int,
S_Center_Name varchar(50),
I_Student_Detail_Id int,
S_Student_Id varchar(50),
S_Student_Name varchar(80),
S_Mob_No varchar(50),
I_Term_Id int,
S_Term_Name varchar(50),
F_Total_marks float,
I_Rank int,
I_Batch_Id int,
S_Batch_name varchar(50),
S_Course_Name varchar(50),
InstanceChain varchar(MAX)
)
insert into #getlast20students
(
I_Student_Detail_Id,I_Term_Id,F_Total_marks,I_Rank,I_Batch_Id,I_Center_Id,InstanceChain
)
select sm.I_Student_Detail_ID,bm.I_Term_ID, SUM(sm.I_Exam_Total) as Total_Marks_Obtained,
DENSE_RANK() over (partition by bm.I_Batch_ID order by SUM(sm.I_Exam_Total) desc ) as Overall_Rank,
bm.I_Batch_ID,sm.I_Center_ID,FN2.InstanceChain
from EXAMINATION.T_Student_Marks sm inner join EXAMINATION.T_Batch_Exam_Map bm
on bm.I_Batch_Exam_ID=sm.I_Batch_Exam_ID 
INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
ON sm.I_Center_Id=FN1.CenterID
INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
where DATEDIFF(dd,sm.Dt_Exam_Date,@examdate)=0
and bm.I_Term_ID= @i_term_id
and bm.I_Batch_ID=ISNULL(@i_batch_id,bm.I_Batch_ID)
--and bm.I_Batch_ID=@i_batch_id
--and sm.I_Center_ID IN(SELECT CenterList.centerID FROM dbo.fnGetCentersForReports(@sHierarchyList, CAST(@iBrandID AS INT)) CenterList) 
group by bm.I_Term_ID,bm.I_Batch_ID,sm.I_Student_Detail_ID,sm.I_Center_ID,InstanceChain
order by bm.I_Term_ID,bm.I_Batch_ID;

update #getlast20students
set S_Student_Id=
(select sd.S_Student_ID from T_Student_Detail sd
where sd.I_Student_Detail_ID=#getlast20students.I_Student_Detail_Id);

update #getlast20students
set S_Student_Name=
(select sd.S_First_Name +' '+  isnull(sd.S_Middle_Name,'')+' '+sd.S_Last_Name from T_Student_Detail sd
where sd.I_Student_Detail_ID=#getlast20students.I_Student_Detail_Id);


update #getlast20students
set S_Mob_No=
(select sd.S_Mobile_No from T_Student_Detail sd
where sd.I_Student_Detail_ID=#getlast20students.I_Student_Detail_Id);



update #getlast20students
set S_Batch_name=
(select sbm.S_Batch_Name from T_Student_Batch_Master sbm
where sbm.I_Batch_ID=#getlast20students.I_Batch_Id);

update #getlast20students
set S_Center_Name=
(select cm.S_Center_Name from T_Centre_Master cm
where cm.I_Centre_Id=#getlast20students.I_Center_Id);

update #getlast20students
set S_Term_Name=
(
select tm.S_Term_Name from T_Term_Master tm 
where tm.I_Term_ID=#getlast20students.I_Term_Id
);

update #getlast20students
set S_Course_Name=
(select cm.S_Course_Name from T_Student_Batch_Master sbm 
inner join T_Course_Master cm
on cm.I_Course_ID=sbm.I_Course_ID
where #getlast20students.I_Batch_Id=sbm.I_Batch_ID);



--delete #getlast20students where I_Center_Id!=@@sHierarchyList

select * from #getlast20students where I_Rank<=@i_rank AND #getlast20students.F_Total_marks IS NOT NULL ;

end
GO
PRINT N'Creating Procedure [REPORT].[uspGetUnutilizedRooms]...';


GO
CREATE procedure [REPORT].[uspGetUnutilizedRooms]
(
@FromDate as date,
@ToDate as date,
@iBrandId INT,    
@sHierarchyList VARCHAR(MAX)
)

as 
begin


declare @index int
create table #datetable 
(
id int identity primary key,
s_Date date
);

create table #unutilizedrm
(
sc_date date,
I_TimeSlot_ID int,
I_Center_ID int,
Dt_Start_Time varchar(50),
Dt_End_Time varchar(50),
I_Room_ID int,
S_Building_Name varchar(50),
S_Block_Name varchar(50),
S_Floor_Name varchar(50),
S_Room_No varchar(50),
S_Center_Name varchar(50),
flag int,
instance_chain varchar(MAX)
)

set @index=(DATEDIFF(DAY,@FromDate,@ToDate));
 
		while(@index>=0)
		begin
			if(@index=0)
			begin
				insert into #datetable(s_Date)
					values(@FromDate);
			end
								
		else
			begin
				insert into #datetable(s_Date)
					values(DATEADD(DAY,@index,@FromDate))
			end	
		set @index=@index-1;
		if @index=-1
		break;
	end
			
			
insert into #unutilizedrm( sc_date,I_TimeSlot_ID,I_Room_ID,S_Building_Name,S_Block_Name,S_Floor_Name,S_Room_No,I_Center_ID,instance_chain)
select dt.s_Date,ctsm.I_TimeSlot_ID, rm.I_Room_ID,rm.S_Building_Name,rm.S_Block_Name,rm.S_Floor_Name,rm.S_Room_No,rm.I_Centre_Id,FN2.instanceChain 
from #datetable dt
cross join  T_Center_Timeslot_Master ctsm
cross join T_Room_Master rm
INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
ON ctsm.I_Center_Id=FN1.CenterID
INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
where 
rm.I_Centre_Id IN (SELECT CenterList.centerID FROM dbo.fnGetCentersForReports(@sHierarchyList, CAST(@iBrandID AS INT)) CenterList) 

and ctsm.I_Center_ID IN (SELECT CenterList.centerID FROM dbo.fnGetCentersForReports(@sHierarchyList, CAST(@iBrandID AS INT)) CenterList) 


/* initial query*/
--update un
--set un.flag=1
--from #unutilizedrm un 
--inner join T_TimeTable_Master ttm
--on un.sc_date=ttm.Dt_Schedule_Date
--or un.sc_date=ttm.Dt_Actual_Date
--and un.I_TimeSlot_ID=ttm.I_TimeSlot_ID
--and un.I_Room_ID=ttm.I_Room_ID
--where 
--un.sc_date=ttm.Dt_Schedule_Date
--or un.sc_date=ttm.Dt_Actual_Date
--and un.I_TimeSlot_ID=ttm.I_TimeSlot_ID
--and un.I_Room_ID=ttm.I_Room_ID

/*based on actual date*/
update un
set un.flag=1
from #unutilizedrm un 
inner join T_TimeTable_Master ttm
on un.sc_date=ttm.Dt_Actual_Date
and un.I_TimeSlot_ID=ttm.I_TimeSlot_ID
and un.I_Room_ID=ttm.I_Room_ID
where 
 un.sc_date=ttm.Dt_Actual_Date
and un.I_TimeSlot_ID=ttm.I_TimeSlot_ID
and un.I_Room_ID=ttm.I_Room_ID
and ttm.I_Is_Complete=1


/*based on schedule date*/
update un
set un.flag=1
from #unutilizedrm un 
inner join T_TimeTable_Master ttm
on un.sc_date=ttm.Dt_Schedule_Date
and un.I_TimeSlot_ID=ttm.I_TimeSlot_ID
and un.I_Room_ID=ttm.I_Room_ID
where 
un.sc_date=ttm.Dt_Schedule_Date
and un.I_TimeSlot_ID=ttm.I_TimeSlot_ID
and un.I_Room_ID=ttm.I_Room_ID
and ttm.I_Is_Complete=0

/*cout of utilized room and deleting them*/
--select COUNT(*) from #unutilizedrm where flag =1;
delete from #unutilizedrm where flag=1;


/*time slot update*/

update #unutilizedrm 
set Dt_Start_Time=
(select convert(varchar(5),Dt_Start_Time,108)
 from T_Center_Timeslot_Master ctsm
where #unutilizedrm.I_TimeSlot_ID=ctsm.I_TimeSlot_ID)

update #unutilizedrm 
set Dt_End_Time=
(select convert(varchar(5),Dt_End_Time,108)
 from T_Center_Timeslot_Master ctsm
where #unutilizedrm.I_TimeSlot_ID=ctsm.I_TimeSlot_ID)


update #unutilizedrm 
set S_Center_Name
=(select chnd.S_Center_Name from T_Center_Hierarchy_Name_Details chnd
where #unutilizedrm.I_Center_ID=chnd.I_Center_Id);

select u.sc_date,u.Dt_Start_Time+'-'+u.Dt_End_Time Time_Slot,u.I_TimeSlot_ID,
u.S_Building_Name,u.S_Block_Name,u.S_Floor_Name,u.S_Room_No,u.S_Center_Name,u.I_Center_ID,instance_chain
 from #unutilizedrm u
order by u.sc_date,u.I_TimeSlot_ID;

drop table #datetable;
drop table #unutilizedrm;


end
GO
PRINT N'Creating Procedure [REPORT].[uspGetTrainingStatusReport]...';


GO
CREATE PROCEDURE [REPORT].[uspGetTrainingStatusReport] 
(
	-- Add the parameters for the stored procedure here
	@sHierarchyList varchar(MAX),
	@iBrandID int,
	@dtStartDate datetime,
	@dtEndDate datetime,
	@iTrainingProgramme int=NULL,
	@sTrainingProgrammeName varchar(200)=NULL
)
AS
BEGIN TRY

	 SELECT LTRIM(ISNULL(UM.S_Title,'') + ' ') + UM.S_First_Name + ' ' + LTRIM(ISNULL(UM.S_Middle_Name,'') + ' ') + ISNULL(UM.S_Last_Name,'') as Trainer_Name,
			TC.I_User_ID,
			TC.I_Training_ID,
			TC.S_Training_Name,
			TC.Dt_Training_Date,
			TC.Dt_Training_End_Date,
			FN.I_Employee_ID,
			ED.S_Emp_ID,
			LTRIM(ISNULL(ED.S_Title,'') + ' ') + ED.S_First_Name + ' ' + LTRIM(ISNULL(Ed.S_Middle_Name,'') + ' ' + Ed.S_Last_Name) as Participants,
			FN1.CenterCode,
			FN1.CenterName,
			FN2.InstanceChain,
			UM1.I_User_ID AS ParticipantsUserID,
			[REPORT].[fnGetTrainerFeedbackReports](TC.I_Training_ID,UM1.I_User_ID,2) AS AvgFeedbackTrainer,
			[REPORT].[fnGetTrainerFeedbackReports](TC.I_Training_ID,UM1.I_User_ID,3) AS AvgFeedbackCourseware,
			[REPORT].[fnGetTrainerFeedbackReports](TC.I_Training_ID,UM1.I_User_ID,4) AS AvgFeedbackInfrastructure,
			[REPORT].[fnGetTrainerFeedbackReports](TC.I_Training_ID,UM1.I_User_ID,5) AS AvgFeedbackDelivery,
			[REPORT].[fnGetTrainerFeedbackReports](TC.I_Training_ID,UM1.I_User_ID,6) AS AvgFeedbackDissemination
	   INTO #TmpTrainingStatus1	
	   FROM ACADEMICS.T_Training_Calendar TC
			INNER JOIN ACADEMICS.T_Faculty_Nomination FN
				ON TC.I_Training_ID = FN.I_Training_ID 
	        INNER JOIN dbo.T_Employee_Dtls ED
				ON FN.I_Employee_ID = ED.I_Employee_ID
			INNER JOIN dbo.T_User_Master UM
				ON TC.I_User_ID = UM.I_User_ID 
			INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
				ON FN.I_Centre_Id=FN1.CenterID
			INNER JOIN [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
				ON FN1.HierarchyDetailID=FN2.HierarchyDetailID
			INNER JOIN dbo.T_User_Master UM1
				ON FN.I_Employee_ID=UM1.I_Reference_ID
				AND UM1.I_Status<>0
				AND UM1.S_User_Type='CE'
	  WHERE TC.Dt_Training_Date BETWEEN @dtStartDate AND @dtEndDate
		AND FN.C_Approved='Y'
		AND FN.C_Attended='Y'
		AND TC.I_Training_ID=ISNULL(@iTrainingProgramme,TC.I_Training_ID)


	 SELECT *, (AvgFeedbackTrainer + AvgFeedbackCourseware + AvgFeedbackInfrastructure + AvgFeedbackDelivery + AvgFeedbackDissemination)/5 AS OverallGPA 
	   INTO #TmpTrainingStatus2
	   FROM #TmpTrainingStatus1

	 SELECT TMP1.*,
		    TT.AvgOverallGPA 
       FROM #TmpTrainingStatus2 TMP1,
			(SELECT I_Training_ID,Avg(OverallGPA) AS AvgOverallGPA FROM #TmpTrainingStatus2 GROUP BY I_Training_ID) TT
	  WHERE TMP1.I_Training_ID=TT.I_Training_ID

	 DROP TABLE #TmpTrainingStatus1
	 DROP TABLE #TmpTrainingStatus2

	 
END TRY

BEGIN CATCH
	
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int

	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[UspGetVideoAccessReport]...';


GO
CREATE PROCEDURE [REPORT].[UspGetVideoAccessReport]  
(  
 @sHierarchyList varchar(MAX),  
 @iBrandID int,  
 @sCourseLst Varchar(500)=NULL,  
 @sBatchLst Varchar(500)=NULL,  
 @dtStartDate datetime,  
 @dtEndDate datetime  
)  
AS  
 BEGIN
 
	IF @sCourseLst IS NOT NULL 
		BEGIN  
		IF @sBatchLst IS NOT NULL
			begin
				  SELECT SD.S_Student_ID USERID,   
					  ISNULL(UM.S_First_Name,'')+' '+ISNULL(UM.S_Middle_Name,'')+' '+ISNULL(UM.S_Last_Name,'') USERNAME,  
					  FN1.centerName,  
					  CM.S_Course_Name,  
					  SBM.S_Batch_Code,  
					  SBM.S_Batch_Name,
					  CASE WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 6 THEN 'Enrollment Full'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 5 THEN 'Completed'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 4 THEN 'Can Enroll'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 3 THEN 'Rejected'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 2 THEN 'Approved'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 1 THEN 'Created'
							ELSE 'Inactive' END AS I_Status,
					  BCD.S_Session_Topic, 
					  BCD.S_Session_Alias, 
					  UVAT.Dt_Login_Time,  
					  UVAT.Dt_Logout_Time,  
					  UVAT.S_IP_Address   
				  FROM dbo.T_USER_VIDEO_ACCESS_TRAIL UVAT  
				   INNER JOIN dbo.T_User_Master UM ON UVAT.I_User_ID=UM.I_User_ID  
				   INNER JOIN dbo.T_Student_Detail SD ON UM.I_Reference_ID=SD.I_Student_Detail_ID  
				   INNER JOIN dbo.T_Enquiry_Regn_Detail ERD ON SD.I_Enquiry_Regn_ID=ERD.I_Enquiry_Regn_ID  
					  INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1  
					  ON ERD.I_Centre_Id=FN1.CenterID    
				   INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID=SBD.I_Student_ID  
				   INNER JOIN dbo.T_Student_Batch_Master SBM ON SBD.I_Batch_ID=SBM.I_Batch_ID  
				   INNER JOIN dbo.T_Course_Master CM ON SBM.I_Course_ID=CM.I_Course_ID  
				   INNER JOIN dbo.T_Batch_Content_Details BCD ON UVAT.I_Batch_Content_Details_ID=BCD.I_Batch_Content_Details_ID  
				   INNER JOIN dbo.T_Center_Batch_Details AS tcbd ON BCD.I_Batch_ID = tcbd.I_Batch_ID AND ERD.I_Centre_Id = tcbd.I_Centre_Id
					Where SBD.I_Batch_ID in (SELECT CAST([Val] AS INT) FROM [dbo].[fnString2Rows](@sBatchLst, ','))  
					AND SBM.I_Course_ID IN (SELECT CAST([Val] AS INT) FROM [dbo].[fnString2Rows](@sCourseLst, ','))  
					AND UVAT.Dt_Login_Time BETWEEN @dtStartDate AND @dtEndDate
			end
		ELSE
			begin
				  SELECT SD.S_Student_ID USERID,   
					  ISNULL(UM.S_First_Name,'')+' '+ISNULL(UM.S_Middle_Name,'')+' '+ISNULL(UM.S_Last_Name,'') USERNAME,  
					  FN1.centerName,  
					  CM.S_Course_Name,  
					  SBM.S_Batch_Code,  
					  SBM.S_Batch_Name,
					  CASE WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 6 THEN 'Enrollment Full'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 5 THEN 'Completed'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 4 THEN 'Can Enroll'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 3 THEN 'Rejected'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 2 THEN 'Approved'
							WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 1 THEN 'Created'
							ELSE 'Inactive' END AS I_Status,
					  BCD.S_Session_Topic, 
					  BCD.S_Session_Alias,  
					  UVAT.Dt_Login_Time,  
					  UVAT.Dt_Logout_Time,  
					  UVAT.S_IP_Address   
				  FROM dbo.T_USER_VIDEO_ACCESS_TRAIL UVAT  
				   INNER JOIN dbo.T_User_Master UM ON UVAT.I_User_ID=UM.I_User_ID  
				   INNER JOIN dbo.T_Student_Detail SD ON UM.I_Reference_ID=SD.I_Student_Detail_ID  
				   INNER JOIN dbo.T_Enquiry_Regn_Detail ERD ON SD.I_Enquiry_Regn_ID=ERD.I_Enquiry_Regn_ID  
					  INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1  
					  ON ERD.I_Centre_Id=FN1.CenterID    
				   INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID=SBD.I_Student_ID  
				   INNER JOIN dbo.T_Student_Batch_Master SBM ON SBD.I_Batch_ID=SBM.I_Batch_ID  
				   INNER JOIN dbo.T_Course_Master CM ON SBM.I_Course_ID=CM.I_Course_ID  
				   INNER JOIN dbo.T_Batch_Content_Details BCD ON UVAT.I_Batch_Content_Details_ID=BCD.I_Batch_Content_Details_ID  
				   INNER JOIN dbo.T_Center_Batch_Details AS tcbd ON BCD.I_Batch_ID = tcbd.I_Batch_ID AND ERD.I_Centre_Id = tcbd.I_Centre_Id
					Where SBM.I_Course_ID IN (SELECT CAST([Val] AS INT) FROM [dbo].[fnString2Rows](@sCourseLst, ','))  
					AND UVAT.Dt_Login_Time BETWEEN @dtStartDate AND @dtEndDate
			end
		END
	ELSE
		BEGIN  
 		  SELECT SD.S_Student_ID USERID,   
			  ISNULL(UM.S_First_Name,'')+' '+ISNULL(UM.S_Middle_Name,'')+' '+ISNULL(UM.S_Last_Name,'') USERNAME,  
			  FN1.centerName,  
			  CM.S_Course_Name,  
			  SBM.S_Batch_Code,  
			  SBM.S_Batch_Name,
			  CASE WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 6 THEN 'Enrollment Full'
					WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 5 THEN 'Completed'
					WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 4 THEN 'Can Enroll'
					WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 3 THEN 'Rejected'
					WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 2 THEN 'Approved'
					WHEN ISNULL(tcbd.I_Status,SBM.I_Status) = 1 THEN 'Created'
					ELSE 'InacENDe' END AS I_Status,
			  BCD.S_Session_Topic,  
			  BCD.S_Session_Alias, 
			  UVAT.Dt_Login_Time,  
			  UVAT.Dt_Logout_Time,  
			  UVAT.S_IP_Address   
		  FROM dbo.T_USER_VIDEO_ACCESS_TRAIL UVAT  
		   INNER JOIN dbo.T_User_Master UM ON UVAT.I_User_ID=UM.I_User_ID  
		   INNER JOIN dbo.T_Student_Detail SD ON UM.I_Reference_ID=SD.I_Student_Detail_ID  
		   INNER JOIN dbo.T_Enquiry_Regn_Detail ERD ON SD.I_Enquiry_Regn_ID=ERD.I_Enquiry_Regn_ID  
			  INNER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1  
			  ON ERD.I_Centre_Id=FN1.CenterID    
		   INNER JOIN dbo.T_Student_Batch_Details SBD ON SD.I_Student_Detail_ID=SBD.I_Student_ID  
		   INNER JOIN dbo.T_Student_Batch_Master SBM ON SBD.I_Batch_ID=SBM.I_Batch_ID  
		   INNER JOIN dbo.T_Course_Master CM ON SBM.I_Course_ID=CM.I_Course_ID  
		   INNER JOIN dbo.T_Batch_Content_Details BCD ON UVAT.I_Batch_Content_Details_ID=BCD.I_Batch_Content_Details_ID  
		   INNER JOIN dbo.T_Center_Batch_Details AS tcbd ON BCD.I_Batch_ID = tcbd.I_Batch_ID AND ERD.I_Centre_Id = tcbd.I_Centre_Id
			Where UVAT.Dt_Login_Time BETWEEN @dtStartDate AND @dtEndDate
		END
 End
GO
