*/
CREATE PROCEDURE [REPORT].[uspMBPProductWiseReport]
(
	@sHierarchyList VARCHAR(MAX) = NULL
	,@iBrandID		INT = NULL
	,@iCenterID		INT = NULL
	,@startMonth	INT	
	,@startMonthName	VARCHAR(50)= NULL
	,@startYear		INT
	,@startYearName		VARCHAR(50)= NULL
	,@endMonth		INT
	,@endMonthName		VARCHAR(50)= NULL
)

AS
BEGIN TRY

DECLARE @BrandName VARCHAR (1000)
, @BrandCode VARCHAR (1000)
, @CenterName VARCHAR (1000)
, @CenterCode VARCHAR (1000)
, @InstanceChain VARCHAR(8000)
, @diff INT 
, @icount INT
,@iRow INT
,@ProductName VARCHAR (512)


/*Start GET Brand,Center*/
SELECT	DISTINCT
		 @BrandCode = BND.S_Brand_Code
		,@BrandName = BND.S_Brand_Name
		,@CenterName = CEN.S_Center_Name
		,@CenterCode = CEN.S_Center_Code
		,@InstanceChain = FN2.InstanceChain
		FROM MBP.T_MBP_Detail MBP

		LEFT OUTER JOIN dbo.T_Centre_Master CEN
		ON CEN.I_Centre_Id = MBP.I_Center_ID
		
		LEFT OUTER JOIN dbo.T_Brand_Center_Details BNDCEN
		ON BNDCEN.I_Centre_Id = CEN.I_Centre_ID
	
		LEFT OUTER JOIN dbo.T_Brand_Master BND
		ON BND.I_Brand_ID = BNDCEN.I_Brand_ID
		
		LEFT OUTER JOIN [dbo].[fnGetCentersForReports](@sHierarchyList, @iBrandID) FN1
		ON FN1.CenterID = MBP.I_Center_ID
		LEFT OUTER JOIN  [dbo].[fnGetInstanceNameChainForReports](@sHierarchyList, @iBrandID) FN2
		ON FN1.HierarchyDetailID=FN2.HierarchyDetailID

		WHERE MBP.I_Center_ID = @iCenterID
		
/*End GET Brand,Center*/


DECLARE @temTable TABLE
(
	ID INT IDENTITY(1,1)
	,ProductID	VARCHAR(255)
	,ProductName	VARCHAR(255)
	,Admission		VARCHAR(50)
	,Billing		VARCHAR(255)
)
INSERT INTO @temTable
SELECT 
PER.I_Product_ID
,PROD.S_Product_Name
,ISNULL(SUM(I_Actual_Enrollment),0)  AS Admission
,ISNULL(SUM(I_Actual_Billing),0) AS Billing
FROM MBP.T_MBPerformance PER

INNER JOIN MBP.T_Product_Master PROD
ON PER.I_Product_ID = PROD.I_Product_ID

WHERE PER.I_Month >= @startMonth
AND PER.I_Month <= @endMonth
AND PER.I_Year = @startYear
AND PER.I_Center_ID =@iCenterID

GROUP BY PER.I_Product_ID,PROD.S_Product_Name

DECLARE @tblReport TABLE
(
	 ID				INT IDENTITY(1,1)
	,InstanceChain			VARCHAR(1024)
	,Region			VARCHAR(255)
	,Center			VARCHAR(255)
	,ProductName	VARCHAR(255)
	,Admission		VARCHAR(50)
	,Billing		VARCHAR(255)
)

SET @iRow = (SELECT COUNT(*) FROM @temTable)
SET @icount =1
WHILE @icount<= @iRow
BEGIN
DECLARE @Pname VARCHAR(255)
,@Enrol VARCHAR(255)
,@Bill VARCHAR(255)

SET  @Pname = (SELECT ProductName FROM @temTable WHERE ID = @icount)
SET  @Enrol = (SELECT Admission FROM @temTable WHERE ID = @icount)
SET  @Bill =  (SELECT Billing FROM @temTable WHERE ID = @icount)
			INSERT INTO @tblReport
			(
				InstanceChain
				,Region	
				,Center
				,ProductName
				,Admission
				,Billing
			)
			VALUES
			(
				@InstanceChain	
				,''--(SUBSTRING(REPLACE((REPLACE(@InstanceChain,' ','')),' ',''),(CHARINDEX('n-',(REPLACE(@InstanceChain,' ','')),0) + 2),(CHARINDEX(';C',(REPLACE(@InstanceChain,' ','')),0) - (CHARINDEX('n-',(REPLACE(@InstanceChain,' ','')),0)+2)))) 
				,@CenterName
				,LTRIM(@Pname)
				,LTRIM(@Enrol)
				,LTRIM(@Bill)
			)

SET @icount = @icount + 1
END




--SELECT * FROM @tblReport

SELECT 
	 ID
	,InstanceChain
	,Region		
	,Center
	,ProductName	
	,CONVERT(INT,Admission) AS Admission		
	,CONVERT(NUMERIC(18,2),Billing ) AS Billing	
	FROM @tblReport	
END TRY

BEGIN CATCH
	--Error occurred:  

	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT	@ErrMsg = ERROR_MESSAGE(),
			@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [REPORT].[uspMarksTabulation]...';


GO
CREATE PROCEDURE [REPORT].[uspMarksTabulation] --[REPORT].[uspGetStudentsInternalMarks] 746,3,9,17,NULL,1,107,1       
    (
      @iBatchID INT ,
      @iTermID INT ,
      @iModuleID INT ,
      @iExamComponentID INT ,
      @iStudentDetailID INT ,    
      --@iCenterID INT,
      @iBrandId INT ,
      @sHierarchyList VARCHAR(MAX),
      @dCumulativeP DECIMAL(14,2)=NULL
    )
AS 
    BEGIN




        SELECT  S_Course_Name ,
                S_Term_Name ,
                S_Batch_Name ,
                E.S_First_Name + ' ' + E.S_Middle_Name + ' ' + E.S_Last_Name AS NAME ,
                E.I_Student_Detail_ID AS StdID ,
                S_Student_ID ,
                S_First_Name ,
                S_Module_Name ,
                A.I_Exam_Component_ID ,
                S_Component_Name ,
                I_Exam_Total ,
                I_TotMarks--,SUM(I_Exam_Total)
        INTO    #temp1
        FROM    T_Exam_Component_Master A
                INNER JOIN T_Module_Eval_Strategy B ON A.I_Exam_Component_ID = B.I_Exam_Component_ID
                                                       AND A.I_Status = 1
                                                       AND B.I_Status = 1
                INNER JOIN EXAMINATION.T_Batch_Exam_Map C ON C.I_Exam_Component_ID = A.I_Exam_Component_ID
                                                             AND A.I_Status = 1
                                                             AND B.I_Module_ID = C.I_Module_ID
                                                             AND B.I_Term_ID = C.I_Term_ID
                                                             AND C.I_Status = 1
                INNER JOIN EXAMINATION.T_Student_Marks D ON D.I_Batch_Exam_ID = C.I_Batch_Exam_ID
                INNER JOIN T_Student_Detail E ON E.I_Student_Detail_ID = D.I_Student_Detail_ID
                INNER JOIN T_Module_Master F ON F.I_Module_ID = B.I_Module_ID
                INNER JOIN T_Course_Master G ON G.I_Course_ID = B.I_Course_ID
                INNER JOIN T_Term_Master I ON I.I_Term_ID = C.I_Term_ID
--INNER JOIN T_Student_Batch_Details K ON K.I_Batch_ID=C.I_Batch_ID AND K.I_Status=1
                INNER JOIN T_Student_Batch_Master H ON H.I_Batch_ID = C.I_Batch_ID
                                                       AND H.I_Batch_ID IN (
                                                       SELECT I_Batch_ID
                                                       FROM   T_Student_Batch_Details
                                                       WHERE  I_Batch_ID = ISNULL(@iBatchID,
                                                              I_Batch_ID)
                                                              AND I_Status IN (1,2) )
        WHERE   E.I_Student_Detail_ID = ISNULL(@iStudentDetailID,
                                               E.I_Student_Detail_ID)
                AND H.I_Batch_ID = ISNULL(@iBatchID, C.I_Batch_ID)
                AND B.I_Term_ID = @iTermID--@iTermID
                AND B.I_Module_ID = ISNULL(@iModuleID, B.I_Module_ID)
                AND A.I_Exam_Component_ID = ISNULL(@iExamComponentID,
                                                   A.I_Exam_Component_ID)
                AND D.I_Center_ID IN (
                SELECT  CenterList.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyList,
                                                   CAST(@iBrandID AS INT)) CenterList )
        ORDER BY E.S_First_Name ,
                S_Module_Name

        SELECT  I_Student_Detail_ID ,
                x.I_Exam_Component_ID ,
                SUM(ISNULL(I_Exam_Total, 0)) AS MARKS ,
                CAST(SUM((ISNULL(C.N_Weightage,C.I_TotMarks)/C.I_TotMarks)*ISNULL(B.I_Exam_Total,0)) AS DECIMAL(14,2)) AS WeightedTotal,
                SUM(ISNULL(C.I_TotMarks, 0)) AS TOTAL
        INTO    #temp2
        FROM    T_Exam_Component_Master x
                INNER JOIN T_Module_Eval_Strategy C ON C.I_Exam_Component_ID = x.I_Exam_Component_ID
                                                       AND x.I_Status = 1
                                                       AND C.I_Status = 1
                INNER JOIN EXAMINATION.T_Batch_Exam_Map A ON x.I_Exam_Component_ID = A.I_Exam_Component_ID
                                                             AND x.I_Status = 1
                                                             AND C.I_Module_ID = A.I_Module_ID
                                                             AND A.I_Term_ID = C.I_Term_ID
                                                             AND C.I_Status = 1
                INNER JOIN EXAMINATION.T_Student_Marks B ON A.I_Batch_Exam_ID = B.I_Batch_Exam_ID
        WHERE   A.I_Batch_ID = ISNULL(@iBatchID, A.I_Batch_ID)
                AND A.I_Term_ID = @iTermID
                AND A.I_Module_ID = ISNULL(@iModuleID, A.I_Module_ID)
                AND A.I_Exam_Component_ID = ISNULL(@iExamComponentID,
                                                   A.I_Exam_Component_ID)
                AND B.I_Center_ID IN (
                SELECT  CenterList.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyList,
                                                   CAST(@iBrandID AS INT)) CenterList )
        GROUP BY I_Student_Detail_ID ,
                x.I_Exam_Component_ID



--SELECT C.I_Module_ID,I_Student_Detail_ID,A.I_Exam_Component_ID,SUM(isnull(I_Exam_Total,0)) as SUB_MARKS,SUM(C.I_TotMarks)AS SUB_TOTAL INTO #temp3
-- FROM 
-- T_Exam_Component_Master x inNER JOIN 
-- EXAMINATION.T_Batch_Exam_Map A on x.I_Exam_Component_ID=A.I_Exam_Component_ID AND x.I_Status=1
-- INNER JOIN EXAMINATION.T_Student_Marks B
--ON A.I_Batch_Exam_ID=B.I_Batch_Exam_ID INNER JOIN T_Module_Eval_Strategy C
--ON C.I_Module_ID=A.I_Module_ID AND A.I_Term_ID=C.I_Term_ID AND C.I_Status=1 AND X.I_Exam_Component_ID=C.I_Exam_Component_ID
--WHERE
--A.I_Batch_ID=ISNULL(@iBatchID,A.I_Batch_ID)
--AND
--A.I_Term_ID=@iTermID
--AND A.I_Module_ID= ISNULL(@iModuleID,A.I_Module_ID)
--AND A.I_Exam_Component_ID=ISNULL(@iExamComponentID,A.I_Exam_Component_ID)
--AND B.I_Center_ID IN (SELECT CenterList.centerID FROM dbo.fnGetCentersForReports(@sHierarchyList, CAST(@iBrandID AS INT)) CenterList) 
--GROUP BY
--C.I_Module_ID,A.I_Exam_Component_ID,I_Student_Detail_ID


SELECT  I_Student_Detail_ID ,
                CAST(SUM((ISNULL(C.N_Weightage,C.I_TotMarks)/C.I_TotMarks)*ISNULL(B.I_Exam_Total,0)) AS DECIMAL(14,2)) AS GrandWeightedTotal
        INTO    #temp3
        FROM    T_Exam_Component_Master x
                INNER JOIN T_Module_Eval_Strategy C ON C.I_Exam_Component_ID = x.I_Exam_Component_ID
                                                       AND x.I_Status = 1
                                                       AND C.I_Status = 1
                INNER JOIN EXAMINATION.T_Batch_Exam_Map A ON x.I_Exam_Component_ID = A.I_Exam_Component_ID
                                                             AND x.I_Status = 1
                                                             AND C.I_Module_ID = A.I_Module_ID
                                                             AND A.I_Term_ID = C.I_Term_ID
                                                             AND C.I_Status = 1
                INNER JOIN EXAMINATION.T_Student_Marks B ON A.I_Batch_Exam_ID = B.I_Batch_Exam_ID
        WHERE   A.I_Batch_ID = ISNULL(@iBatchID, A.I_Batch_ID)
                AND A.I_Term_ID = @iTermID
                AND A.I_Module_ID = ISNULL(@iModuleID, A.I_Module_ID)
                AND A.I_Exam_Component_ID = ISNULL(@iExamComponentID,
                                                   A.I_Exam_Component_ID)
                AND B.I_Center_ID IN (
                SELECT  CenterList.centerID
                FROM    dbo.fnGetCentersForReports(@sHierarchyList,
                                                   CAST(@iBrandID AS INT)) CenterList )
        GROUP BY I_Student_Detail_ID








        SELECT  A.*,B.MARKS,B.WeightedTotal,ROUND(CAST((ISNULL(@dCumulativeP,0.00)/100.00)*CAST(B.WeightedTotal AS DECIMAL(14,2)) AS DECIMAL(14,2)),0) 
        AS Cumulative
		,C.*
        FROM    #temp1 A
                INNER JOIN #temp2 B ON A.StdID = B.I_Student_Detail_ID
                                       AND A.I_Exam_Component_ID = B.I_Exam_Component_ID
				INNER JOIN
				#temp3 C ON  A.StdID = C.I_Student_Detail_ID
--INNER JOIN #temp3 C ON C.I_Student_Detail_ID=A.StdID



    END
GO
