PRINT N'Creating Procedure [REPORT].[uspStudentDetail]...';


GO

--EXEC REPORT.uspStudentDetail @iBatchID = 783, @iStudentID = 4695
--EXEC REPORT.uspStudentDetail @iBatchID = 1656
--EXEC REPORT.uspStudentDetail @iBatchID = 8058, @iStudentID = 6077
CREATE PROCEDURE [REPORT].[uspStudentDetail] 
	@iBatchID INT
	,@iStudentID INT = NULL
AS
BEGIN	
	
	SELECT DISTINCT
	TSD.I_Student_Detail_ID
	, TSD.S_First_Name + ' ' + ISNULL(TSD.S_Middle_Name, '') 
                        + ' ' + TSD.S_Last_Name AS [S_Student_Name]
	,TSD.S_Student_ID AS S_Roll_No
	,tcm.I_Course_ID
	,tcm.S_Course_Name
	,@iBatchId AS I_Batch_Id
	,tsbm.S_Batch_Name AS S_Batch_Name
	,S_Student_Photo
	,(SELECT 
			CONVERT(VARCHAR(4),YEAR(SBM.Dt_BatchStartDate)) +'-'+ RIGHT(CONVERT(VARCHAR(4),YEAR(SBM.Dt_BatchStartDate)+1),2)  
		FROM T_Student_Batch_Master SBM WITH (NOLOCK) WHERE I_Batch_ID = @iBatchID
		) AS S_Academic_Session
	FROM dbo.T_Student_Batch_Details TSBD WITH (NOLOCK)
	INNER JOIN dbo.T_Student_Detail AS TSD WITH (NOLOCK) ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
	INNER JOIN dbo.T_Student_Batch_Master AS tsbm WITH (NOLOCK) ON TSBM.I_Batch_ID = TSBD.I_Batch_ID
	INNER JOIN T_Course_Master tcm WITH (NOLOCK) ON tcm.I_Course_ID = tsbm.I_Course_ID
	INNER JOIN T_Enquiry_Regn_Detail E  WITH (NOLOCK) ON E.I_Enquiry_Regn_ID = TSD.I_Enquiry_Regn_ID
	WHERE TSBD.I_Batch_ID= @iBatchID
	AND I_Student_Id =ISNULL(@iStudentID, I_Student_Id)
	AND TSBD.I_Status IN ( 1, 2 ) 
END
GO
PRINT N'Creating Procedure [REPORT].[uspStudentMarksGraphicalAllTerms]...';


GO

--EXEC REPORT.uspStudentMarksGraphicalAllTerms @iBatchId = 783, @iStudentId = 4695
--EXEC REPORT.uspStudentMarksGraphicalAllTerms @iBatchId = 783, @iStudentId = 4695, @iTermId = 13
CREATE  PROCEDURE [REPORT].[uspStudentMarksGraphicalAllTerms] 
	@iBatchID INT
	,@iStudentID INT
	,@iTermID INT = NULL
AS
BEGIN	

  DECLARE @Terms AS TABLE (I_Term_ID INT,I_Sequence INT)

  DECLARE @iCourseID INT
	SET @iCourseID = (SELECT TOP 1 I_Course_ID FROM T_Student_Batch_Master AS tsbm WITH (NOLOCK) WHERE I_Batch_ID = @iBatchID)

	IF @iTermID IS NULL
		INSERT INTO @Terms(I_Term_ID,I_Sequence)
		SELECT
			TCM.I_Term_ID,TCM.I_Sequence
			FROM T_Term_Course_Map TCM WITH (NOLOCK)
			WHERE TCM.I_Course_ID = @iCourseID
			AND TCM.I_Status = 1
	ELSE
	   INSERT INTO @Terms(I_Term_ID,I_Sequence)
		SELECT
			TCM.I_Term_ID,TCM.I_Sequence
			FROM T_Term_Course_Map TCM WITH (NOLOCK)
			WHERE TCM.I_Course_ID = @iCourseID
			AND TCM.I_Status = 1
			AND TCM.I_Sequence <= (SELECT I_Sequence FROM  T_Term_Course_Map ITCM WITH (NOLOCK) 
										WHERE I_Course_ID = @iCourseID
										AND I_Term_ID = @iTermID 
										AND ITCM.I_Status = 1)


   DECLARE @Student AS TABLE(I_Student_ID INT
							,I_Course_ID INT 
							,I_Term_ID INT
							,S_Term_Name VARCHAR(250)
							,I_Exam_Component_ID INT
							,S_Exam_Component_Name VARCHAR(200)
							,I_Batch_Exam_ID INT
							,I_Sequence INT)

   INSERT INTO @Student(I_Student_ID
						,I_Course_ID
						,I_Term_ID
						,S_Term_Name
						,I_Exam_Component_ID
						,S_Exam_Component_Name
						,I_Batch_Exam_ID
						,I_Sequence)
	SELECT DISTINCT
		TSBD.I_Student_ID
		,TSBM.I_Course_ID
		,TM.I_Term_ID
		,TM.S_Term_Name
		,ECM.I_Exam_Component_ID
		,ECM.S_Component_Name
		,BEM.I_Batch_Exam_ID
		,tcm.I_Sequence
	FROM EXAMINATION.T_Batch_Exam_Map  BEM WITH (NOLOCK)
		INNER JOIN T_Term_Master TM WITH (NOLOCK) ON TM.I_Term_ID = BEM.I_Term_ID
		INNER JOIN @Terms TMS ON TMS.I_Term_ID = TM.I_Term_ID
		INNER JOIN T_Exam_Component_Master ECM WITH (NOLOCK) ON ECM.I_Exam_Component_ID = BEM.I_Exam_Component_ID
		INNER JOIN dbo.T_Student_Batch_Details TSBD WITH (NOLOCK) ON TSBD.I_Batch_ID = BEM.I_Batch_ID
		INNER JOIN dbo.T_Student_Batch_Master AS tsbm WITH (NOLOCK)  ON TSBM.I_Batch_ID = TSBD.I_Batch_ID
		--INNER JOIN T_Course_Master cm WITH (NOLOCK) ON cm.I_Course_ID = tsbm.I_Course_ID
		INNER JOIN T_Term_Course_Map tcm WITH (NOLOCK) ON tcm.I_Course_ID = tsbm.I_Course_ID 
				AND tcm.I_Term_ID = TM.I_Term_ID
		
	WHERE BEM.I_Batch_ID= @iBatchID
		AND TSBD.I_Student_ID = @iStudentID
		AND TSBD.I_Status IN (1, 2 ) 
		AND TM.I_Status = 1 
		AND tcm.I_Status = 1
		AND BEM.I_Status=1


	

	--Script 3
	DECLARE @bSecTop BIT = 0
	DECLARE @bAllSecTop BIT = 0

	DECLARE @Order AS TABLE(I_Order INT)

	INSERT INTO @Order(I_Order)
	VALUES(1),(2),(3),(4),(5)


	DECLARE @ReturnTable AS TABLE (I_Student_Detail_ID INT
						--,I_Batch_Exam_ID INT
						,I_Term_ID INT
						,I_Exam_Component_ID INT
						,I_Marks INT
						,I_Marks_Per INT
						,I_Order INT
						,B_Sec_Top BIT
						,B_All_Sec_Top BIT
						,I_Perm_Level INT) --1Up,2Down,3Same

	INSERT INTO @ReturnTable(I_Student_Detail_ID
							--,I_Batch_Exam_ID
							,I_Term_ID
							,I_Exam_Component_ID
							,I_Marks
							,I_Order
							,B_Sec_Top
							,B_All_Sec_Top)
	SELECT DISTINCT	    
		SM.I_Student_Detail_ID,
		--BEM.I_Batch_Exam_ID,
		BEM.I_Term_ID,
		BEM.I_Exam_Component_ID ,
		NULL AS I_Marks,
		O.I_Order, 
		0 AS B_Sec_Top, 
		0 AS B_All_Sec_Top
	FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
		CROSS JOIN @Order O
	WHERE BEM.I_Batch_ID = @iBatchID
		AND SM.I_Student_Detail_ID = @iStudentID	
	ORDER BY SM.I_Student_Detail_ID


	
	UPDATE T
	  SET I_Marks = (SELECT SUM(ROUND(I_Exam_Total ,0))
				FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
					INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
				WHERE SM.I_Student_Detail_ID = T.I_Student_Detail_ID
					AND BEM.I_Term_ID = T.I_Term_ID
					AND BEM.I_Exam_Component_ID = T.I_Exam_Component_ID)
	FROM @ReturnTable T
		WHERE I_Order = 3

	UPDATE T
	  SET I_Marks_Per = (SELECT (CAST(I_Marks AS NUMERIC(8,2))/SUM(MES.I_TotMarks))*100
				FROM T_Module_Eval_Strategy MES WITH (NOLOCK)  
					WHERE MES.I_Course_ID = @iCourseID 
					AND MES.I_Exam_Component_ID = T.I_Exam_Component_ID
					AND mes.I_Term_ID = T.I_Term_ID)
	FROM @ReturnTable T
		WHERE I_Order = 3

    DECLARE @MaxAvg AS TABLE (I_Batch_ID INT, I_Term_ID INT, I_Exam_Component_ID INT, I_MaxValue INT, I_AvgValue INT)

	INSERT INTO @MaxAvg(I_Batch_ID,I_Term_ID,I_Exam_Component_ID,I_MaxValue,I_AvgValue)
	SELECT I_Batch_ID
		  ,I_Term_ID
	      ,I_Exam_Component_ID  
		  ,MAX(Value) AS I_MaxValue
		  ,AVG(Value) AS I_AvgValue
	FROM (SELECT BEM.I_Batch_ID
		  ,I_Term_ID
	      ,I_Exam_Component_ID	
		  ,I_Student_Detail_ID	  
		  ,SUM(ROUND(SM.I_Exam_Total,0)) AS Value
	FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
		INNER JOIN T_Student_Batch_Master SBM WITH (NOLOCK)  ON SBM.I_Batch_ID = BEM.I_Batch_ID AND SBM.I_Course_ID = @iCourseId
	--WHERE BEM.I_Batch_Id = @iBatchId
	GROUP BY BEM.I_Batch_ID,I_Term_ID,I_Student_Detail_ID,I_Exam_Component_ID) T
	GROUP BY I_Batch_Id,I_Term_ID,I_Exam_Component_ID
	ORDER BY I_Batch_Id,I_Term_ID,I_Exam_Component_ID
	
		
    --Sec avg
    UPDATE T
		SET I_Marks =   I.Value
	FROM @ReturnTable T
		INNER JOIN (SELECT I_Exam_Component_ID,I_Term_Id,I_AvgValue AS Value
					FROM @MaxAvg
					WHERE I_Batch_Id = @iBatchId				
					) I ON I.I_Exam_Component_ID = T.I_Exam_Component_ID
					AND I.I_Term_ID =T.I_Term_ID 
		WHERE I_Order = 1

     --Sec Max
	 UPDATE T
		SET I_Marks = I.Value
	FROM @ReturnTable T
			INNER JOIN (SELECT I_Exam_Component_ID,I_Term_ID,I_MaxValue AS Value
					FROM @MaxAvg
					WHERE I_Batch_ID = @iBatchID					
					) I ON I.I_Exam_Component_ID = T.I_Exam_Component_ID
					AND I.I_Term_ID =T.I_Term_ID 
		WHERE I_Order = 2


		--All Sec Max
   UPDATE T
		SET I_Marks = (SELECT MAX(I_MaxValue)
						FROM @MaxAvg I
						WHERE I.I_Term_ID = T.I_Term_ID
							AND I.I_Exam_Component_ID = T.I_Exam_Component_ID) 
	FROM @ReturnTable T
		WHERE I_Order = 4

		--All Sec Avg
	 UPDATE T
		SET I_Marks = (SELECT AVG(I_AvgValue)
						FROM @MaxAvg I
						WHERE I.I_Term_ID = T.I_Term_ID
							AND I.I_Exam_Component_ID = T.I_Exam_Component_ID) 
	FROM @ReturnTable T
		WHERE I_Order = 5

	--HardCoded 
	 --UPDATE @ReturnTable SET B_Sec_Top = 1	 
	 --UPDATE @ReturnTable SET B_All_Sec_Top = 1
	
	 -- UPDATE @ReturnTable SET I_Perm_Level = 0 --1Up,2Down,3Same

	 --SELECT * FROM @ReturnTable

	
	 ------------------------------------------

	 
--Update sec max flag
DECLARE @Max AS TABLE (I_Term_ID INT, I_Exam_Component_ID INT,I_Marks INT) 

INSERT INTO @Max(I_Term_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT I_Term_ID
		,I_Exam_Component_ID
		,MAX(I_Marks)
FROM @ReturnTable
WHERE I_Order= 2
GROUP BY I_Term_ID
		,I_Exam_Component_ID


UPDATE T
	SET B_Sec_Top = (CASE WHEN M.I_Marks = (SELECT I_Marks FROM @ReturnTable
									WHERE I_Term_ID = T.I_Term_ID
									AND I_Exam_Component_ID = T.I_Exam_Component_ID
									AND I_Student_Detail_ID = T.I_Student_Detail_ID
									AND I_Order=3) THEN 1 ELSE 0 END)
FROM @ReturnTable T 
	INNER JOIN @Max M ON M.I_Term_ID = T.I_Term_ID
			AND M.I_Exam_Component_ID = T.I_Exam_Component_ID 

--Update all sec max flag
DELETE FROM @Max
INSERT INTO @Max(I_Term_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT I_Term_ID
		,I_Exam_Component_ID
		,MAX(I_Marks)
FROM @ReturnTable
WHERE I_Order= 4
GROUP BY I_Term_ID
		,I_Exam_Component_ID

UPDATE T
	SET B_All_Sec_Top = (CASE WHEN M.I_Marks = (SELECT I_Marks FROM @ReturnTable
									WHERE I_Term_ID = T.I_Term_ID
									AND I_Exam_Component_ID = T.I_Exam_Component_ID
									AND I_Student_Detail_ID = T.I_Student_Detail_ID
									AND I_Order = 3) THEN 1 ELSE 0 END)
FROM @ReturnTable T 
	INNER JOIN @Max M ON M.I_Term_ID = T.I_Term_ID
			AND M.I_Exam_Component_ID = T.I_Exam_Component_ID 



--UPDATE PERFORMANCE LEVEL
DECLARE @Check11 AS TABLE (I_Student_Detail_ID INT ,I_Exam_Component_ID INT,I_Marks INT) 
DECLARE @Check12 AS TABLE (I_Student_Detail_ID INT ,I_Exam_Component_ID INT,I_Marks INT) 
DECLARE @Check13 AS TABLE (I_Student_Detail_ID INT ,I_Exam_Component_ID INT,I_Marks INT) 

INSERT INTO @Check11(I_Student_Detail_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT  I_Student_Detail_ID
		,I_Exam_Component_ID
		,I_Marks_Per
FROM @ReturnTable
WHERE I_Order= 3
	AND I_Term_ID = (SELECT I_Term_ID FROM @Terms WHERE I_Sequence =1)

INSERT INTO @Check12(I_Student_Detail_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT  I_Student_Detail_ID
		,I_Exam_Component_ID
		,I_Marks_Per
FROM @ReturnTable
WHERE I_Order= 3
	AND I_Term_ID = (SELECT I_Term_ID FROM @Terms WHERE I_Sequence = 2)

INSERT INTO @Check13(I_Student_Detail_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT  I_Student_Detail_ID
		,I_Exam_Component_ID
		,I_Marks_Per
FROM @ReturnTable
WHERE I_Order= 3
	AND I_Term_ID = (SELECT I_Term_ID FROM @Terms WHERE I_Sequence = 3)


UPDATE T
	SET I_Perm_Level = (CASE WHEN M12 > M11  THEN 1 
							 WHEN M12 < M11  THEN 2
							 WHEN M12 = M11  THEN 3  	
						ELSE 0 END)
FROM @ReturnTable T 
	INNER JOIN (SELECT M11.I_Student_Detail_ID,M11.I_Exam_Component_ID , M11.I_Marks as M11,M12.I_Marks as M12
					FROM @Check11 M11 
					INNER JOIN @Check12 M12 ON M12.I_Student_Detail_ID = M11.I_Student_Detail_ID
						AND M12.I_Exam_Component_Id = M11.I_Exam_Component_ID ) M ON M.I_Student_Detail_ID = T.I_Student_Detail_ID
							AND M.I_Exam_Component_ID = T.I_Exam_Component_ID
WHERE T.I_Term_ID = (SELECT I_Term_ID FROM @Terms WHERE I_Sequence = 2)



UPDATE T
	SET I_Perm_Level = (CASE WHEN M13 > M12  THEN 1 
							 WHEN M13 < M12  THEN 2
							 WHEN M13 = M12  THEN 3  	
						ELSE 0 END)
FROM @ReturnTable T 
	INNER JOIN (SELECT M12.I_Student_Detail_ID,M12.I_Exam_Component_ID , M12.I_Marks as M12,M13.I_Marks as M13
					FROM @Check12 M12 
					INNER JOIN @Check13 M13 ON M12.I_Student_Detail_ID = M13.I_Student_Detail_ID
						AND M12.I_Exam_Component_Id = M13.I_Exam_Component_ID ) M ON M.I_Student_Detail_ID = T.I_Student_Detail_ID
							AND M.I_Exam_Component_ID = T.I_Exam_Component_ID
WHERE T.I_Term_ID = (SELECT I_Term_ID FROM @Terms WHERE I_Sequence = 3)
	
	

	--Return resultset
	SELECT     t2.I_Student_ID, t2.I_Term_ID, t2.S_Term_Name, t2.I_Exam_Component_ID, 
                      t2.S_Exam_Component_Name, t3.I_Marks,t3.I_Order, t3.B_Sec_Top, t3.B_All_Sec_Top, t3.I_Perm_Level, t2.I_Sequence
	FROM    (SELECT DISTINCT 
                          I_Student_ID, I_Term_ID, S_Term_Name, I_Exam_Component_ID, 
                          S_Exam_Component_Name, I_Sequence
                       FROM  @Student) AS t2 
                             INNER JOIN @ReturnTable AS t3 ON t2.I_Student_ID = t3.I_Student_Detail_ID AND t2.I_Term_ID = t3.I_Term_ID AND t2.I_Exam_Component_ID = t3.I_Exam_Component_ID
	WHERE I_Student_ID =@iStudentID
	ORDER BY t2.I_Term_ID,t2.I_Exam_Component_ID,t3.I_Order
END
GO
PRINT N'Creating Procedure [REPORT].[uspStudentMarksGraphicalForTerm]...';


GO
--EXEC REPORT.uspStudentMarksGraphicalForTerm @iBatchId = 783, @iStudentId = 4695,@iTermId =12
CREATE  PROCEDURE [REPORT].[uspStudentMarksGraphicalForTerm] 
	@iBatchID INT
	,@iStudentID INT
	,@iTermID INT
AS
BEGIN	

  --DECLARE @Terms AS TABLE (I_Term_ID INT,I_Sequence INT)

  DECLARE @iCourseID INT
  SET @iCourseID = (SELECT TOP 1 I_Course_ID FROM T_Student_Batch_Master AS tsbm WITH (NOLOCK) WHERE I_Batch_ID = @iBatchID)


   DECLARE @Student AS TABLE(I_Student_ID INT
							,I_Course_ID INT 
							,I_Module_ID INT
							,S_Module_Name VARCHAR(250)
							,I_Exam_Component_ID INT
							,S_Exam_Component_Name VARCHAR(200)
							,I_Batch_Exam_ID INT
							,I_Sequence INT)

   INSERT INTO @Student(I_Student_ID
						,I_Course_ID
						,I_Module_ID
						,S_Module_Name
						,I_Exam_Component_ID
						,S_Exam_Component_Name
						,I_Batch_Exam_ID
						,I_Sequence)
	SELECT DISTINCT
		TSBD.I_Student_ID
		,TSBM.I_Course_ID
		,BEM.I_Module_ID
		,MM.S_Module_Name
		,ECM.I_Exam_Component_ID
		,ECM.S_Component_Name
		,BEM.I_Batch_Exam_ID
		,MTM.I_Sequence
	FROM EXAMINATION.T_Batch_Exam_Map  BEM WITH (NOLOCK)
		INNER JOIN T_Exam_Component_Master ECM WITH (NOLOCK) ON ECM.I_Exam_Component_ID = BEM.I_Exam_Component_ID
		INNER JOIN dbo.T_Student_Batch_Details TSBD WITH (NOLOCK) ON TSBD.I_Batch_ID = BEM.I_Batch_ID
		INNER JOIN dbo.T_Student_Batch_Master AS TSBM WITH (NOLOCK)  ON TSBM.I_Batch_ID = TSBD.I_Batch_ID
		--INNER JOIN T_Course_Master TCM WITH (NOLOCK) ON TCM.I_Course_ID = TSBM.I_Course_ID
		INNER JOIN T_Module_Master MM  WITH (NOLOCK) ON MM.I_Module_ID = BEM.I_Module_ID
		INNER JOIN T_Module_Term_Map MTM WITH (NOLOCK) ON MTM.I_Module_ID = MM.I_Module_ID AND MTM.I_Module_ID = BEM.I_Module_ID
			
	WHERE BEM.I_Batch_ID= @iBatchID
		AND TSBD.I_Student_ID = @iStudentID
		AND TSBD.I_Status IN (1, 2 ) 
		AND MTM.I_Status = 1
		AND BEM.I_Term_ID = @iTermID
	UNION 
	SELECT DISTINCT
		TSBD.I_Student_ID
		,TSBM.I_Course_ID
		,0
		,'Total'
		,ECM.I_Exam_Component_ID
		,ECM.S_Component_Name
		,0
		,10 --Hard Coded
	FROM EXAMINATION.T_Batch_Exam_Map  BEM WITH (NOLOCK)
		INNER JOIN T_Exam_Component_Master ECM WITH (NOLOCK) ON ECM.I_Exam_Component_ID = BEM.I_Exam_Component_ID
		INNER JOIN dbo.T_Student_Batch_Details TSBD WITH (NOLOCK) ON TSBD.I_Batch_ID = BEM.I_Batch_ID
		INNER JOIN dbo.T_Student_Batch_Master AS TSBM WITH (NOLOCK)  ON TSBM.I_Batch_ID = TSBD.I_Batch_ID
		--INNER JOIN T_Course_Master TCM WITH (NOLOCK) ON TCM.I_Course_ID = TSBM.I_Course_ID
			
	WHERE BEM.I_Batch_ID= @iBatchID
		AND TSBD.I_Student_ID = @iStudentID
		AND TSBD.I_Status IN (1, 2 )
		AND BEM.I_Term_ID = @iTermID

	--Script 3
	DECLARE @bSecTop BIT = 0
	DECLARE @bAllSecTop BIT = 0

	DECLARE @Order AS TABLE(I_Order INT)

	INSERT INTO @Order(I_Order)
	VALUES(1),(2),(3),(4),(5)


	DECLARE @ReturnTable AS TABLE (I_Student_Detail_ID INT
						,I_Batch_Exam_ID INT
						,I_Module_ID INT
						,I_Exam_Component_ID INT
						,I_Marks INT
						,I_Order INT
						,B_Sec_Top BIT
						,B_All_Sec_Top BIT
						,I_Perm_Level INT) --1Up,2Down,3Same

	INSERT INTO @ReturnTable(I_Student_Detail_ID
							,I_Batch_Exam_ID
							,I_Module_ID
							,I_Exam_Component_ID
							,I_Marks
							,I_Order
							,B_Sec_Top
							,B_All_Sec_Top)
	SELECT DISTINCT	    
		SM.I_Student_Detail_ID,
		BEM.I_Batch_Exam_ID,
		BEM.I_Module_ID,
		BEM.I_Exam_Component_ID ,
		NULL AS I_Marks,
		O.I_Order, 
		0 AS B_Sec_Top, 
		0 AS B_All_Sec_Top
	FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
		CROSS JOIN @Order O
	WHERE BEM.I_Batch_ID = @iBatchID
		AND SM.I_Student_Detail_ID = @iStudentID	
	UNION
	SELECT DISTINCT	    
		SM.I_Student_Detail_ID,
		0,
		0 AS I_Module_ID,
		BEM.I_Exam_Component_ID ,
		NULL AS I_Marks,
		O.I_Order, 
		0 AS B_Sec_Top, 
		0 AS B_All_Sec_Top
	FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
		CROSS JOIN @Order O
	WHERE BEM.I_Batch_ID = @iBatchID
		AND SM.I_Student_Detail_ID = @iStudentID

	

	UPDATE T
	  SET I_Marks = (SELECT SUM(ROUND(I_Exam_Total ,0))
				FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
					INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
				WHERE SM.I_Student_Detail_ID = T.I_Student_Detail_ID
					AND BEM.I_Batch_Exam_ID = T.I_Batch_Exam_ID
					AND BEM.I_Exam_Component_ID = T.I_Exam_Component_ID)
	FROM @ReturnTable T
		WHERE I_Order =3
			AND T.I_Module_ID !=0

	UPDATE T
	  SET I_Marks = (SELECT SUM(ROUND(I_Exam_Total ,0))
				FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
					INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
				WHERE SM.I_Student_Detail_ID = T.I_Student_Detail_ID
					AND BEM.I_Batch_ID = @iBatchID
					AND BEM.I_Term_ID = @iTermID
					AND BEM.I_Exam_Component_ID = T.I_Exam_Component_ID)
	FROM @ReturnTable T
		WHERE I_Order =3
			AND T.I_Module_ID =0



    DECLARE @MaxAvg AS TABLE (I_Batch_ID INT, I_Term_ID INT, I_Module_ID INT,I_Exam_Component_ID INT, I_MaxValue INT, I_AvgValue INT)

	INSERT INTO @MaxAvg(I_Batch_ID,I_Term_ID,I_Module_ID,I_Exam_Component_ID,I_MaxValue,I_AvgValue)
	SELECT I_Batch_ID
		  ,I_Term_ID
		  ,I_Module_ID
	      ,I_Exam_Component_ID  
		  ,MAX(Value) AS I_MaxValue
		  ,AVG(Value) AS I_AvgValue
	FROM (SELECT BEM.I_Batch_ID
		  ,I_Term_ID
		  ,I_Module_ID
	      ,I_Exam_Component_ID	
		  ,I_Student_Detail_ID	  
		  ,SUM(ROUND(SM.I_Exam_Total,0)) AS Value
	FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
		INNER JOIN T_Student_Batch_Master SBM WITH (NOLOCK)  ON SBM.I_Batch_ID = BEM.I_Batch_ID AND SBM.I_Course_ID = @iCourseID
	--WHERE BEM.I_Batch_ID = @iBatchID
	GROUP BY BEM.I_Batch_ID,I_Term_ID,I_Module_ID,I_Student_Detail_ID,I_Exam_Component_ID) T
	GROUP BY I_Batch_ID,I_Term_ID,I_Module_ID,I_Exam_Component_ID
	

	INSERT INTO @MaxAvg(I_Batch_ID,I_Term_ID,I_Module_ID,I_Exam_Component_ID,I_MaxValue,I_AvgValue)
	SELECT I_Batch_ID
		  ,I_Term_ID
		  ,0
	      ,I_Exam_Component_ID  
		  ,MAX(Value) AS I_MaxValue
		  ,AVG(Value) AS I_AvgValue
	FROM (SELECT BEM.I_Batch_ID
		  ,I_Term_ID
	      ,I_Exam_Component_ID	
		  ,I_Student_Detail_ID	  
		  ,SUM(ROUND(SM.I_Exam_Total,0)) AS Value
	FROM EXAMINATION.T_Student_Marks SM WITH (NOLOCK)
		INNER JOIN EXAMINATION.T_Batch_Exam_Map BEM WITH (NOLOCK) ON SM.I_Batch_Exam_ID = BEM.I_Batch_Exam_ID
		INNER JOIN T_Student_Batch_Master SBM WITH (NOLOCK)  ON SBM.I_Batch_ID = BEM.I_Batch_ID AND SBM.I_Course_ID = @iCourseId
		WHERE BEM.I_Term_ID = @iTermId
	GROUP BY BEM.I_Batch_ID,I_Term_ID,I_Student_Detail_ID,I_Exam_Component_ID) T
	GROUP BY I_Batch_Id,I_Term_ID,I_Exam_Component_ID
	ORDER BY I_Batch_Id,I_Term_ID,I_Exam_Component_ID
	
		
    --Sec avg
    UPDATE T
		SET I_Marks =   I.Value
	FROM @ReturnTable T
		INNER JOIN (SELECT I_Exam_Component_ID,I_Module_ID,I_AvgValue AS Value
					FROM @MaxAvg
					WHERE I_Batch_ID = @iBatchID				
					) I ON I.I_Exam_Component_ID = T.I_Exam_Component_ID
					AND I.I_Module_ID =T.I_Module_ID 
		WHERE I_Order = 1

     --Sec Max
	 UPDATE T
		SET I_Marks = I.Value
	FROM @ReturnTable T
			INNER JOIN (SELECT I_Exam_Component_ID,I_Module_ID,I_MaxValue AS Value
					FROM @MaxAvg
					WHERE I_Batch_Id = @iBatchID					
					) I ON I.I_Exam_Component_ID = T.I_Exam_Component_ID
					AND I.I_Module_ID =T.I_Module_ID 
		WHERE I_Order = 2


		--All Sec Max
   UPDATE T
		SET I_Marks = (SELECT MAX(I_MaxValue)
						FROM @MaxAvg I
						WHERE I.I_Module_ID = T.I_Module_ID
							AND I.I_Exam_Component_ID = T.I_Exam_Component_ID) 
	FROM @ReturnTable T
		WHERE I_Order = 4

		--All Sec Avg
	 UPDATE T
		SET I_Marks = (SELECT AVG(I_AvgValue)
						FROM @MaxAvg I
						WHERE I.I_Module_ID = T.I_Module_ID
							AND I.I_Exam_Component_ID = T.I_Exam_Component_ID) 
	FROM @ReturnTable T
		WHERE I_Order = 5

	--HardCoded 
	 --UPDATE @ReturnTable SET B_Sec_Top = 1	 
	 --UPDATE @ReturnTable SET B_All_Sec_Top = 1
	
	  --UPDATE @ReturnTable SET I_Perm_Level = 0 --1Up,2Down,3Same

	 --SELECT * FROM @ReturnTable

	
	 ------------------------------------------

	 
--Update sec max flag
DECLARE @Max AS TABLE (I_Module_ID INT, I_Exam_Component_ID INT,I_Marks INT) 

INSERT INTO @Max(I_Module_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT I_Module_ID
		,I_Exam_Component_ID
		,MAX(I_Marks)
FROM @ReturnTable
WHERE I_Order= 2
GROUP BY I_Module_ID
		,I_Exam_Component_ID


UPDATE T
	SET B_Sec_Top = (CASE WHEN M.I_Marks = (SELECT I_Marks FROM @ReturnTable
									WHERE I_Module_ID = T.I_Module_ID
									AND I_Exam_Component_ID = T.I_Exam_Component_ID
									AND I_Student_Detail_ID = T.I_Student_Detail_ID
									AND I_Order=3) THEN 1 ELSE 0 END)
FROM @ReturnTable T 
	INNER JOIN @Max M ON M.I_Module_ID = T.I_Module_ID
			AND M.I_Exam_Component_ID = T.I_Exam_Component_ID 

--Update all sec max flag
DELETE FROM @Max
INSERT INTO @Max(I_Module_ID
				,I_Exam_Component_ID
				,I_Marks)
SELECT I_Module_ID
		,I_Exam_Component_ID
		,MAX(I_Marks)
FROM @ReturnTable
WHERE I_Order= 4
GROUP BY I_Module_ID
		,I_Exam_Component_ID

UPDATE T
	SET B_All_Sec_Top = (CASE WHEN M.I_Marks = (SELECT I_Marks FROM @ReturnTable
									WHERE I_Module_ID = T.I_Module_ID
									AND I_Exam_Component_ID = T.I_Exam_Component_ID
									AND I_Student_Detail_ID = T.I_Student_Detail_ID
									AND I_Order=3) THEN 1 ELSE 0 END)
FROM @ReturnTable T 
	INNER JOIN @Max M ON M.I_Module_ID = T.I_Module_ID
			AND M.I_Exam_Component_Id = T.I_Exam_Component_ID 

--PERFORMANCE LEVEL

	
	

	--Return resultset
	SELECT     t2.I_Student_ID, t2.I_Module_ID AS I_Term_ID, t2.S_Module_Name  AS S_Term_Name, t2.I_Exam_Component_ID, 
                      t2.S_Exam_Component_Name, t3.I_Marks, t3.I_Order, t3.B_Sec_Top, t3.B_All_Sec_Top, t3.I_Perm_Level,t2.I_Sequence
	FROM    (SELECT DISTINCT 
                          I_Student_ID,I_Module_ID ,S_Module_Name, I_Exam_Component_ID, 
                          S_Exam_Component_Name,I_Sequence
                       FROM  @Student) AS t2 
                             INNER JOIN @ReturnTable AS t3 ON t2.I_Student_ID = t3.I_Student_Detail_ID AND t2.I_Module_ID = t3.I_Module_ID AND t2.I_Exam_Component_ID = t3.I_Exam_Component_ID
	WHERE I_Student_ID =@iStudentID
	 AND t2.S_Module_Name NOT LIKE '%ADCHK%'--akash
	UNION 
	SELECT @iStudentId,MTM.I_Module_ID ,MM.S_Module_Name, EC.I_Exam_Component_ID,EC.S_Exam_Component_Name
	,NULL AS I_Marks, O.I_Order AS I_Order, 0 AS B_Sec_Top, 0 AS B_All_Sec_Top, NULL AS I_Perm_Level,MTM.I_Sequence AS I_Sequence
		FROM T_Module_Term_Map MTM WITH (NOLOCK)
	CROSS JOIN (SELECT DISTINCT I_Exam_Component_ID,S_Exam_Component_Name FROM @Student) EC
	LEFT JOIN (SELECT DISTINCT 
                I_Student_ID,I_Module_ID ,S_Module_Name, I_Exam_Component_ID, 
                S_Exam_Component_Name
            FROM  @Student) S  ON MTM.I_Module_ID = S.I_Module_ID AND S.I_Exam_Component_ID = EC.I_Exam_Component_ID
	INNER JOIN T_Module_master MM  WITH (NOLOCK) ON MM.I_Module_ID = MTM.I_Module_ID
	CROSS JOIN @Order O
	WHERE S.I_Exam_Component_ID IS NULL
		AND MTM.I_Term_ID = @iTermID
		AND MTM.I_Status =1
		AND MM.S_Module_Name NOT LIKE '%ADCHK%'--akash

	ORDER BY t2.I_Sequence,t2.I_Module_ID,t2.I_Exam_Component_ID,t3.I_Order
END
GO
