AS
BEGIN


	/*select DISTINCT A.StudentID,C.S_First_Name+' '+ISNULL(C.S_Middle_Name,'')+' '+C.S_Last_Name as StudentName,C.S_Mobile_No,D.I_Center_ID,D.S_Center_Name 
