	where
	A.StatusID=1 and A.DueOn<=GETDATE() and A.PaidOn IS NULL and A.ReceiptHeaderID IS NULL
	and A.StudentID=@StudentID and A.BrandID=@BrandID 
	*/
	



	select C.S_Student_ID,A.DueOn,B.S_Status_Desc,A.TotalAmount
