CREATE PROCEDURE [SMManagement].[uspGetCenterDispatchSchemeList]
(
@iCenterID INT,
@iCourseID INT
)

AS


BEGIN


SELECT DISTINCT TCDSM.CentreDispatchSchemeID,TDSM.DispatchSchemeName FROM SMManagement.T_Centre_Dispatch_Scheme_Map AS TCDSM
