              ItemTypeName VARCHAR(MAX) ,
              BarcodePrefix VARCHAR(MAX) ,
              CenterID INT ,
              S_Center_Name VARCHAR(MAX) ,
              CourseID INT ,
              S_Course_Name VARCHAR(MAX) ,
              IsScheduled BIT ,
              StockID INT ,
              ItemCode VARCHAR(MAX) ,
              ItemDesc VARCHAR(MAX) ,
