 S_Sibling_ID =@sSiblingID,    
     
     
 I_Seat_Type_ID =@iSeatType,    
 I_Enrolment_Type_ID =@iEnrolmentType,    
 S_Enrolment_No =@sEnrolmentNo,    
 I_Rank_Obtained =@iRankObtained,    
