CREATE Proc ERP_get_FEE_Structure_GST_Generation(  
@FeeStructureID int,  
@paymentTypeID int  
)  
As   
Begin  
--Declare @FeeStructureID int =44  
-----Creating Temp Table for Holding GST data------  
Create Table #GST_Component_Amount (  
