                        TEQD.S_University_Name ,      
                        TEQD.S_Year_From ,      
              TEQD.S_Year_To ,      
                        TEQD.S_Subject_Name ,      
                        TEQD.N_Marks_Obtained ,      
                        TEQD.N_Percentage ,      
                        TEQD.S_Division,  
                        TEQD.S_Institution      
                FROM    dbo.T_Enquiry_Qualification_Details AS TEQD      
                WHERE   I_Enquiry_Regn_ID = @iEnquiryRegnID      
                        AND TEQD.I_Status = 1                                                          
            END                                 
    END
