   @SReferal nvarchar(MAX)=null    
    )      
AS       
    BEGIN TRY                        
        SET NOCOUNT OFF ;                        
               
        DECLARE @iEnquiryID INT                        
                               
        DECLARE @iEmployeeId INT           
        DECLARE @sSelectedCourseIDs VARCHAR(100)           
      
  DECLARE @Centre INT    
    
  --DECLARE @FatherName VARCHAR(200) = NULL    
