                        FROM    dbo.T_Term_Course_Map A      
                        WHERE   A.I_Course_ID = @iCourseId      
                                AND A.I_Status <> 0                        
              
                INSERT  INTO T_Student_Module_Detail      
                        ( I_Term_ID ,      
                          I_Module_ID ,      
                          I_Course_ID ,      
                          I_Batch_ID ,      
                          I_Student_Detail_ID ,      
