    )                  
AS                   
    SET NOCOUNT ON                    
    BEGIN TRY                     
                    
        DECLARE @sLoginID VARCHAR(500)                     
        DECLARE @iStudentDetailId INT                    
        DECLARE @iCenterID INT                    
                    
        BEGIN TRANSACTION                    
        SELECT TOP 1                  
                @iCenterID = I_Destination_Center_ID                  
