   --SELECT  @sLoginID = [dbo].fnGetStudentNo(@iCenterID)  
  WITH NumberParts AS (
    SELECT
        S_Student_ID,
        CAST(SUBSTRING(S_Student_ID, 4, LEN(S_Student_ID) - 3) AS INT) AS NumericPart
    FROM
        T_Student_Detail
),
MaxNumber AS (
    SELECT
        MAX(NumericPart) AS MaxNumericPart
    FROM
        NumberParts
)

SELECT @sLoginID=
    '24-' + RIGHT('0000' + CAST(MaxNumericPart + 1 AS VARCHAR), 4) 
FROM
    MaxNumber;

-- Drop the temporary table after use
