                                                              AND I_Enquiry_Status_Code IS NULL        
                                                     ) = 1 THEN @DtCrtdOn        
                                       END ,        
                        S_Upd_By = CASE WHEN @iEnquiryStatus = 3        
                                             OR @iEnquiryStatus IS NULL        
                                             OR I_Enquiry_Status_Code = 1        
                                        THEN ISNULL(@CrtdBy, S_Crtd_By)        
                                   END ,        
                        Dt_Upd_On = CASE WHEN @iEnquiryStatus = 3        
