    I_Modified_By = @iUpdatedBy,    
    Dtt_Modified_At = GETDATE()    
   WHERE R_I_Enquiry_Regn_ID = @iEnquiryRegnID    
  END    
  ELSE    
  BEGIN    
   INSERT INTO [dbo].[T_ERP_PreEnq_Siblings]    
   (    
    R_I_Enquiry_Regn_ID,    
    S_StudentID,    
