    I_Created_By    
   )    
   VALUES    
   (    
     @iEnquiryRegnID,    
     @sSiblingStudentID,    
     @sSiblingStudentName,    
     @iSiblingIsRunningStudent,    
     @sSiblingPassoutYear,    
     @iUpdatedBy    
   );    
  END    
        
 -- Populate Enquiry Source Details         
        
        
   -- if (@iEnquiryRegnID > 0)        
   -- BEGIN        
        
   --if exists(        
   --select * from T_Information_Source_Master         
   --where I_Info_Source_ID=@InfoSourceID --and S_Info_Source_Name like '%Reference%'        
