AS

BEGIN TRY 

	DECLARE @MATERIAL_TEMP TABLE(BarCode NVARCHAR(255),CourseName NVARCHAR(255),ItemCode NVARCHAR(255),MoveOrderNo INT, Slno NVARCHAR(255),Defaulter NVARCHAR(255))
