GO
  
CREATE PROCEDURE [dbo].[KPMG_uspInsertReceiptMaterialsInCCW_renamed]
    @OraclePoId VARCHAR(100) ,
    @XMLData XML
AS
    BEGIN TRY   
  
        PRINT 1  
   
        DECLARE @TempTable TABLE
            (
              ID INT IDENTITY ,
              LineId VARCHAR(100) ,
              BarCode VARCHAR(100) ,
              ItemId VARCHAR(100)
            )
         
              
        DECLARE @ItemTable TABLE
            (
              ID INT IDENTITY ,
              ItemId VARCHAR(100)
            )  
        IF EXISTS ( SELECT  1
                    FROM    Tbl_KPMG_PoDetails
                    WHERE   OraclePoId = ISNULL(@OraclePoId, '')
                            AND Fld_KPMG_Status = 0 )
            BEGIN  
   
                INSERT  INTO @TempTable
                        ( LineId ,
                          BarCode ,
                          ItemId
                        )
                        SELECT  T.c.value('LineId[1]', 'NVARCHAR(255)') ,
                                T.c.value('SerialNo[1]', 'NVARCHAR(255)') ,
                                T.c.value('ItemId[1]', 'NVARCHAR(255)')
                        FROM    @XMLData.nodes('/Root/TestRTemp') T ( c )   
 
                DELETE  FROM @TempTable
                WHERE   BarCode IN ( SELECT Fld_KPMG_Barcode
                                     FROM   Tbl_KPMG_StockDetails
                                     WHERE  BarCode = Fld_KPMG_Barcode )    
    
                UPDATE  Tbl_KPMG_PoDetailItems
                SET     Fld_KPMG_Status = 1
                FROM    Tbl_KPMG_PoDetailItems (NOLOCK) A
                        JOIN @TempTable B ON A.OracleLinieId = B.LineId
                                             AND A.Fld_KPMG_Barcode = B.BarCode  
    
 
    
  --commented  update Tbl_KPMG_PoDetailItems set Fld_KPMG_Status = 4 where Fld_KPMG_Status= 1  
                
  -- commented   UPDATE Tbl_KPMG_PoDetails SET Fld_KPMG_Status = 1 FROM  Tbl_KPMG_PoDetails A  
  --commented  JOIN Tbl_KPMG_PoDetailItems B ON A.Fld_KPMG_PoPr_Id = B.Fld_KPMG_PoPr_Id     
            END  
   
        DECLARE @GENID INT  
        DECLARE @Row_Count INT  
        DECLARE @Counter INT  
        DECLARE @ItemCode VARCHAR(100)  
   
        INSERT  INTO @ItemTable
                ( ItemId
                )
                SELECT DISTINCT
                        ( ItemId )
                FROM    @TempTable  
   
        SELECT  @Row_Count = COUNT(DISTINCT ( ItemId ))
        FROM    @ItemTable  
        SET @Counter = 1  
   
        WHILE @Counter <= @Row_Count
            BEGIN  
    
                SELECT  @ItemCode = ItemId
                FROM    @ItemTable
                WHERE   ID = @Counter  
                IF ISNULL(@ItemCode, '') <> ''
                    BEGIN  
     
                        INSERT  INTO Tbl_KPMG_StockMaster
                                ( Fld_KPMG_ItemCode ,
                                  Fld_KPMG_Branch_Id ,
                                  Fld_KPMG_IsMo ,
                                  Fld_KPMG_FromBranch_Id ,
                                  Fld_KPMG_LastRecvDate ,
                                  Fld_KPMG_Mo_Id
                                )
                        VALUES  ( @ItemCode ,
                                  0 ,
                                  1 ,
                                  0 ,
                                  GETDATE() ,
                                  0
                                )  
                        SELECT  @GENID = @@IDENTITY  
     
                        INSERT  INTO Tbl_KPMG_StockDetails
                                ( Fld_KPMG_Stock_Id ,
                                  Fld_KPMG_Barcode
                                )
                                SELECT  @GENID ,
                                        BarCode
                                FROM    @TempTable
                                WHERE   ItemId = @ItemCode  
     
   --commented exec KPMG_uspInsertLoadAllocation @ItemCode  
    
                    END  
     
    
                SET @ItemCode = ''  
                SET @Counter = @Counter + 1   
            END  
   
        DECLARE @COUNT INT  
        DECLARE @TOTAL_COUNT INT  
        DECLARE @PO_PR_Id INT  
        SELECT  @PO_PR_Id = Fld_KPMG_PoPr_Id
        FROM    Tbl_KPMG_PoDetails
        WHERE   OraclePoId = @OraclePoId  
        SELECT  @COUNT = COUNT(*)
        FROM    Tbl_KPMG_PoDetailItems
        WHERE   Fld_KPMG_Status = 2
                OR Fld_KPMG_Status = 1
                AND Fld_KPMG_PoPr_Id = @PO_PR_Id  
        SELECT  @TOTAL_COUNT = COUNT(*)
        FROM    Tbl_KPMG_PoDetailItems
        WHERE   Fld_KPMG_PoPr_Id = @PO_PR_Id  
   
        IF ( @COUNT = @TOTAL_COUNT )
            BEGIN  
                UPDATE  Tbl_KPMG_PoDetails
                SET     Fld_KPMG_Status = 1
                WHERE   Fld_KPMG_PoPr_Id = @PO_PR_Id  
            END  
   
	DELETE FROM @TempTable
	DELETE FROM @ItemTable
  
    END TRY  
    BEGIN CATCH  
   
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT  
  
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()  
  
        RAISERROR(@ErrMsg, @ErrSeverity, 1)  
    END CATCH
GO
PRINT N'Creating Procedure [dbo].[KPMG_uspMO_LoadAllocation]...';


GO

CREATE PROCEDURE [dbo].[KPMG_uspMO_LoadAllocation] 
	
AS
BEGIN Try
			
	DECLARE @Qty INT
DECLARE @ItemCode VARCHAR(255)
DECLARE @idMap INT
DECLARE @idMaxLast INT
DECLARE @ItmAmount_TEMP TABLE([Amount_Id] [int] IDENTITY(1,1) NOT NULL,ItemCode VARCHAR(255),Qunty INT, Calc_Date DateTime, ItemStatus INT)

Insert Into @ItmAmount_TEMP(ItemCode,Qunty,Calc_Date,ItemStatus)
Select MvOd.Fld_KPMG_Itemcode,MvOd.Quantity-Qty.Quantity as AllotQty,GETDATE() as InsertDate, 0 as Itm_Status from (
Select Mi.Fld_KPMG_Itemcode,sum(Mi.Fld_KPMG_Quantity) AS Quantity from dbo.Tbl_KPMG_MoMaster Mm INNER JOIN dbo.Tbl_KPMG_MoItems Mi 
ON Mm.Fld_KPMG_Mo_Id = Mi.Fld_KPMG_Mo_Id Group By Mi.Fld_KPMG_Itemcode,Mm.Fld_KPMG_Status Having Mm.Fld_KPMG_Status = '0')MvOd INNER JOIN 

(Select SM.Fld_KPMG_ItemCode,COUNT(Fld_KPMG_StockDet_Id) AS Quantity from dbo.Tbl_KPMG_StockDetails Dtls 
INNER JOIN dbo.Tbl_KPMG_StockMaster SM ON SM.Fld_KPMG_Stock_Id = Dtls.Fld_KPMG_Stock_Id Group BY SM.Fld_KPMG_ItemCode)Qty ON MvOd.Fld_KPMG_Itemcode = Qty.Fld_KPMG_ItemCode 
-- AND MvOd.Quantity-Qty.Quantity < 0

Set @idMap = 0
Select @idMaxLast = MAX(Amount_Id) from @ItmAmount_TEMP

WHILE @idMap <=  @idMaxLast
	BEGIN
		-- Select @Qty = Qunty from @ItmAmount_TEMP where Amount_Id = @idMap
		Select @ItemCode = ItemCode from @ItmAmount_TEMP where Amount_Id = @idMap
		
		--if(@Qty < 0)
		--	Begin
		--		Set @Qty = @Qty -1
		--	End
		
		Exec KPMG_uspInsertLoadAllocation @ItemCode
		
		SET @idMap = @idMap + 1
	END

END TRY        
        
    BEGIN CATCH            
 --Error occurred:              
            
        DECLARE @ErrMsg NVARCHAR(4000) ,  
            @ErrSeverity INT            
        SELECT  @ErrMsg = ERROR_MESSAGE() ,  
                @ErrSeverity = ERROR_SEVERITY()            
        RAISERROR(@ErrMsg, @ErrSeverity, 1)            
    END CATCH
GO
