       UPDATE A SET A.Fld_KPMG_ItemCode=B.ItemCode ,A.Fld_KPMG_IsValid='Y' FROM Tbl_KPMG_SM_List A INNER JOIN  @TEMP_ORACLE_ITEMS B ON A.Fld_KPMG_Segment=B.ItemSegment 



