	  If NOT EXISTS (SELECT 1 FROM T_Student_Detail WHERE S_Student_ID=@RegistrationLoginId AND I_Status=1)
            Begin

			      SET @Status=-1
			        SET @Message = 'Invalid User'      
          
            End
	  								   
END	
	 	   
	
END
