 OR (TERSD.I_Period_No = @Post_Period)
 )  and @Prev_Period<>1 OR @Post_Period<>@LastPeriodNo
   
Begin  
 SELECT 1 AS StatusFlag, 'Faculty was already been assigned for Previous Period  '  AS Message        
  
End  
 Else  
 BEGIN        
