PRINT N'Creating Procedure [dbo].[Usp_ERP_Class_RoleMapping]...';


GO
--exec [dbo].[Usp_ERP_Class_RoleMapping] 2,107,null,null,null,null
CREATE Procedure [dbo].[Usp_ERP_Class_RoleMapping]
@iSessionID int,
@iBrandID int=null,
@iSchoolGroupID int=null,
@iClassID int=null,
@iStreamID int=null,
@iSectionID int=Null
as
SET NOCOUNT ON;  

select 
TSCS.I_School_Session_ID SchoolSessionID,
TSCS.I_School_Group_Class_ID SchoolGroupClassID	, 
TSCS.I_Section_ID SectionID,
TSCS.I_Stream_ID StreamID,
TC.S_Class_Name ClassName,
TSG.S_School_Group_Name SchoolGroupName,
ISNULL(TS.S_Section_Name,'NA') SectionName,
ISNULL(TST.S_Stream,'NA') Stream,
TSG.I_School_Group_ID SchoolGroupID,
TC.I_Class_ID ClassID,
TSASM.S_Label Label

from T_Student_Class_Section TSCS 
inner join T_School_Group_Class TSGS ON TSGS.I_School_Group_Class_ID = TSCS.I_School_Group_Class_ID
inner join T_School_Group TSG ON TSG.I_School_Group_ID = TSGS.I_School_Group_ID
inner join T_School_Academic_Session_Master TSASM ON TSASM.I_School_Session_ID = TSCS.I_School_Session_ID
inner join T_Class TC ON TC.I_Class_ID = TSGS.I_Class_ID
left join T_Section TS ON TS.I_Section_ID = TSCS.I_Section_ID
left join T_Stream TST ON TST.I_Stream_ID = TSCS.I_Stream_ID
where TSCS.I_School_Session_ID=@iSessionID
and TSG.I_School_Group_ID=ISNULL(@iSchoolGroupID,TSG.I_School_Group_ID)
and --TSCS.I_Section_ID = ISNULL(@iSectionID,TSCS.I_Section_ID)
(TSCS.I_Section_ID = @iSectionID OR @iSectionID IS NULL)
and TSG.I_Brand_Id = @iBrandID
and TC.I_Class_ID = ISNULL(@iClassID,TC.I_Class_ID)
and --TSCS.I_Stream_ID = ISNULL(@iStreamID,TSCS.I_Stream_ID)
(TSCS.I_Stream_ID = @iStreamID OR  @iStreamID IS NULL)

group by 
TSCS.I_School_Session_ID,
TSCS.I_School_Group_Class_ID,
TSCS.I_Section_ID,
TSCS.I_Stream_ID,
TC.S_Class_Name,
TSG.S_School_Group_Name,
TS.S_Section_Name,
TST.S_Stream,
TSG.I_School_Group_ID,
TC.I_Class_ID,
TSASM.S_Label
GO
PRINT N'Creating Procedure [dbo].[Usp_ERP_Course_batch_Map]...';


GO
CREATE Proc Usp_ERP_Course_batch_Map    
(    
    @ClassID Int,    
    @BrandID int,    
    @streamID Int = Null    
)    
as    
Begin    
    
    --Declare @ClassID Int=1,@ClassName Varchar(100),@BrandID int=1 ,@sessionID int    
    
    Declare @CourseID int,    
            @coursename varchar(50),    
            @Currentdate datetime = GETDATE(),    
            @SessionStartDt date,    
            @SessionEndDt date,    
            @ClassName Varchar(100),    
            @sessionID int,    
            @CurrentYear Varchar(5)    
    Set @CurrentYear = Year(@Currentdate)    
    --Select @CurrentYear    
    SET @sessionID =    
    (    
        select Top 1    
            I_School_Session_ID    
        from T_School_Academic_Session_Master    
        where I_Brand_ID = @BrandID    
              and Year(Dt_Session_Start_Date) = @CurrentYear    
    )    
    
    Select @SessionStartDt = Convert(date, Dt_Session_Start_Date),    
           @SessionEndDt = convert(date, Dt_Session_End_Date)    
    from T_School_Academic_Session_Master ASM    
        Inner Join T_Brand_Master BM    
            on Bm.I_Brand_ID = asm.I_Brand_ID    
    where I_School_Session_ID = @sessionID    
          and Bm.I_Brand_ID = @BrandID    
    
    Select @ClassName = S_Class_Name    
    from T_Class    
    where I_Class_ID = @ClassID    
    
    SET @coursename = Concat(@ClassName, ' ', '(', Year(@SessionStartDt), ')')    
    --Select @coursename    
    If Not Exists    
    (    
        select 1    
        from T_Course_Master    
        where S_Course_Name = @coursename    
              and I_Brand_ID = @BrandID    
    )    
    Begin    
        Insert Into T_Course_Master    
        (    
            I_Brand_ID,    
            I_CourseFamily_ID,    
            S_Course_Code,    
            S_Course_Name,    
            S_Course_Desc,    
            I_Document_ID,    
            I_Is_Editable,    
            I_Status,    
            S_Crtd_By,    
            S_Upd_By,    
            Dt_Crtd_On,    
            Dt_Upd_On    
        )    
        values    
        (@BrandID, 1    
  , @coursename    
  , @coursename    
  , @coursename    
  , 1    
  , 1    
  , 1    
  , 'dba'    
  , 'dba'    
  , Getdate()    
  , getdate()    
  )    
        Set @CourseID = SCOPE_IDENTITY()    
    End    
    ELSE    
    Begin    
        SET @CourseID =    
        (    
            select Top 1    
                I_Course_ID    
            from T_Course_Master    
            where S_Course_Name = @coursename    
                  and I_Brand_ID = @BrandID    
        )    
    End    
    -----------Checking batch Against Course-------------    
    Declare @BatchID Int,    
            @batchname varchar(50)    
    SET @batchname = @coursename    
    IF Not exists    
    (    
        select 1    
        from T_Student_Batch_Master    
        where S_Batch_Name = @batchname    
              and I_Course_ID = @CourseID    
    )    
    Begin    
        Insert Into T_Student_Batch_Master    
        (    
            S_Batch_Code,    
            I_Course_ID,    
            I_Delivery_Pattern_ID,    
            Dt_BatchStartDate,    
            I_Status,    
            Dt_Course_Expected_End_Date,    
            S_Crtd_By,    
            Dt_Crtd_On,    
            b_IsHOBatch,    
            S_Batch_Name,    
            b_IsApproved,    
            I_Admission_GraceDays,    
            b_IsCorporateBatch,    
            I_Latefee_Grace_Day,    
            Admission_AfterStartDate    
        )    
        Select @batchName,    
               @courseID,    
               1,    
               @SessionStartDt,    
               2,    
               @SessionEndDt,    
               'dba',    
               GETDATE(),    
               0,    
               @batchName,    
               1,    
               365,    
               0,    
               0,    
               0    
    
        SET @BatchID = SCOPE_IDENTITY()    
    End    
    ELSE    
    Begin    
        Set @BatchID =    
        (    
            select I_Batch_ID    
            from T_Student_Batch_Master    
            where S_Batch_Name = @batchname    
                  and I_Course_ID = @CourseID    
        )    
    End    
    
    IF NOT Exists    
    (    
        select 1    
        from T_Course_Group_Class_Mapping    
        where I_Course_ID = @CourseID    
              and I_Brand_ID = @BrandID    
              and I_Class_ID = @ClassID    
              and I_School_Session_ID = @sessionID    
              and I_Batch_ID = @BatchID    
              and (    
                      I_Stream_ID = @streamID    
                      Or @streamID IS NULL    
                  )    
    )    
    Begin    
        Insert Into T_Course_Group_Class_Mapping    
        (    
            I_Course_ID,    
            I_Brand_ID,    
            I_Class_ID,    
            Dt_Create_Dt,    
            I_School_Session_ID,    
            I_Stream_ID,    
            I_Batch_ID    
        )    
        Values    
        (@CourseID, @BrandID, @ClassID, Getdate(), @sessionID, @streamID, @BatchID)    
    End    
End
GO
PRINT N'Creating Procedure [dbo].[USP_ERP_Dash_AdmissionStatus]...';


GO
--EXEC [USP_ERP_Dash_AdmissionStatus] 2,2      
CREATE Proc [dbo].[USP_ERP_Dash_AdmissionStatus](        
@sessionID int=Null,        
@brandID int        
)        
As         
Begin        
Declare @Sdate date, @EDate date ,@Centerid int   
--Declare @sessionID int,@brandID int  
--SET @sessionID=2        
--SET @brandID=2    
SET @Centerid=(select top 1 I_Centre_Id from T_Brand_Center_Details where I_Brand_ID=@brandID)  
Select @Sdate= Convert(date,Dt_Session_Start_Date),@EDate=convert(date,Dt_Session_End_Date)        
from T_School_Academic_Session_Master         
where I_School_Session_ID=@sessionID         
and I_Brand_ID=@brandID        
--Select @Sdate,@EDate        
-----For Pre Enquiry--------------        
SELECT        
    MONTH(Dt_Crtd_On) AS MonthNumber,        
    DATENAME(MONTH, Dt_Crtd_On) AS MonthName,        
    COUNT(I_Enquiry_Regn_ID) AS RecordCount        
 Into #Temp_Pre_Enq        
FROM        
    T_Enquiry_Regn_Detail where I_ERP_Entry=1        
 and I_Enquiry_Status_Code is null         
And         
    convert(date,Dt_Crtd_On) >= @Sdate        
    AND convert(date,Dt_Crtd_On) < @EDate    
 and I_Centre_Id=@Centerid  
GROUP BY        
    MONTH(Dt_Crtd_On), DATENAME(MONTH, Dt_Crtd_On)        
ORDER BY        
    MonthNumber;  
	--select * from #Temp_Pre_Enq
 ------For Enquiry--------------        
 SELECT        
    MONTH(Dt_Crtd_On) AS MonthNumber,        
    DATENAME(MONTH, Dt_Crtd_On) AS MonthName,        
    COUNT(I_Enquiry_Regn_ID) AS RecordCount        
  Into #Temp_Enq        
FROM        
    T_Enquiry_Regn_Detail where I_ERP_Entry=1        
 and I_Enquiry_Status_Code =1        
And         
    convert(date,Dt_Crtd_On) >= @Sdate        
    AND convert(date,Dt_Crtd_On) < @EDate    
 and I_Centre_Id=@Centerid  
GROUP BY        
    MONTH(Dt_Crtd_On), DATENAME(MONTH, Dt_Crtd_On)        
ORDER BY        
    MonthNumber;    
	--select * from #Temp_Enq
 -----For Admission -------        
 SELECT        
    MONTH(Dt_Crtd_On) AS MonthNumber,        
    DATENAME(MONTH, Dt_Crtd_On) AS MonthName,        
    COUNT(I_Enquiry_Regn_ID) AS RecordCount        
 Into #Temp_Adm        
FROM        
    T_Enquiry_Regn_Detail where I_ERP_Entry=1        
 and I_Enquiry_Status_Code =3        
And         
    convert(date,Dt_Crtd_On) >= @Sdate        
    AND convert(date,Dt_Crtd_On) < @EDate   
 and I_Centre_Id=@Centerid  
GROUP BY        
    MONTH(Dt_Crtd_On), DATENAME(MONTH, Dt_Crtd_On)        
ORDER BY        
    MonthNumber; 
	--select * from #Temp_Adm
 ---------------------------        
 ;WITH Months AS (        
    SELECT DATEADD(MONTH, number, @Sdate) AS MonthStart        
    FROM master..spt_values        
    WHERE type = 'P'         
    AND number BETWEEN 0 AND 11 -- Months from April to March        
)        
select Convert(Varchar,(FORMAT(Months.MonthStart, 'MMMM'))) AS MonthName        
Into #AllMonth        
        
from Months   
--select * from #AllMonth
        
 Select SUBSTRING(am.MonthName,1,3) as Month_Name,a.RecordCount as Pre_Enq_Count,        
 b.RecordCount As Enq_Count,c.RecordCount As Adm_Count        
         
 from #AllMonth am        
 Left Join #Temp_Pre_Enq a on a.MonthName=am.MonthName        
 Left Join #Temp_Enq b on am.MonthName=b.MonthName        
 Left Join #Temp_Adm c on c.MonthName=am.MonthName        
         
        
 drop Table #Temp_Pre_Enq        
 drop table #Temp_Adm        
 DROP TABLE #Temp_Enq        
 drop table #AllMonth        
 End
GO
PRINT N'Creating Procedure [dbo].[USP_ERP_Dash_ClassList]...';


GO
   --EXEC USP_ERP_Dash_ClassList 107,35      
   CREATE Proc USP_ERP_Dash_ClassList(      
 @brandID int, @sessionID int      
 )      
 --Declare @brandID int, @sessionID int      
 --SET @brandID=107      
 --SEt @sessionID=35      
 As      
 Begin      
 CREATE table #RoutineWiseLogBook      
 (      
 BrandID int,      
 BrandName varchar(max),      
 RoutineStructureHeaderID INT,      
 TotalNoofPeriods INT,      
 RoutineSlotStart time,      
 RoutineDuration time,      
 PeriodGap time,      
 SchoolGroupID INT,      
 SchoolGroupName varchar(max),      
 ClassID INT,      
 ClassName varchar(max),      
 SectionID INT,      
 SectionName varchar(max),      
 SubjectID int,      
 SubjectName varchar(max),      
 RoutineStructureDetailID INT,      
 PeriodNo INT,      
 PeriodStart time,      
 PeriodEnd time,      
 ClassDayID INT,      
 ClassDayName varchar(max),      
 StudentClassRoutineID INT,      
 )      
      
 insert into #RoutineWiseLogBook      
 select       
 BM.I_Brand_ID as BrandID,      
 BM.S_Brand_Name as BrandName,      
 RSH.I_Routine_Structure_Header_ID as RoutineStructureHeaderID,      
 RSH.I_Total_Periods as TotalNoofPeriods,      
 RSH.T_Start_Slot as RoutineSlotStart,      
 RSH.T_Duration as RoutineDuration,      
 RSH.T_Period_Gap as PeriodGap,      
 ISNULL(SG.I_School_Group_ID,0) as SchoolGroupID,      
 ISNULL(SG.S_School_Group_Name,'NA') as SchoolGroupName,      
 ISNULL(C.I_Class_ID,0) as ClassID,      
 ISNULL(C.S_Class_Name,'NA') as ClassName,      
 ISNULL(S.I_Section_ID,0) as SectionID,      
 ISNULL(S.S_Section_Name,'--') as SectionName,      
 SM.I_Subject_ID as SubjectID,      
 SM.S_Subject_Name as SubjectName,      
 RSD.I_Routine_Structure_Detail_ID as RoutineStructureDetailID,      
 RSD.I_Period_No as PeriodNo,      
 RSD.T_FromSlot as PeriodStart,      
 RSD.T_ToSlot as PeriodEnd,      
 WDM.I_Day_ID as ClassDayID,      
 WDM.S_Day_Name as ClassDayName,      
 SCR.I_Student_Class_Routine_ID as StudentClassRoutineID      
       
 from      
 T_ERP_Routine_Structure_Header as RSH      
 inner join      
 T_ERP_Routine_Structure_Detail as RSD on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID      
 inner join      
 T_ERP_Student_Class_Routine as SCR on SCR.I_Routine_Structure_Detail_ID=RSD.I_Routine_Structure_Detail_ID      
 inner join      
 T_School_Group SG on SG.I_School_Group_ID=RSH.I_School_Group_ID      
 inner join      
 T_School_Group_Class as SGC on SGC.I_School_Group_ID=SG.I_School_Group_ID and SGC.I_Class_ID=RSH.I_Class_ID      
 inner join      
 T_Class as C on C.I_Class_ID=SGC.I_Class_ID and C.I_Class_ID=RSH.I_Class_ID      
 inner join      
 T_Week_Day_Master as WDM on WDM.I_Day_ID=RSD.I_Day_ID      
 inner join      
 T_Subject_Master as SM on SM.I_Subject_ID=SCR.I_Subject_ID      
 inner join      
 T_Brand_Master as BM on BM.I_Brand_ID=SM.I_Brand_ID      
 left join      
 T_Section as S on S.I_Section_ID=RSH.I_Section_ID      
      
 where  RSH.I_School_Session_ID=@sessionID      
       
 and SM.I_Brand_ID=@brandID       
 And WDM.S_Day_Name=DATENAME(WEEKDAY, GETDATE())       
    
 select maintemp.RoutineStructureHeaderID,maintemp.StudentClassRoutineID,    
 maintemp.PeriodNo,CONCAT((LEFT(Convert(varchar,Maintemp.PeriodStart),8)) ,'-',(LEFT(Convert(varchar,Maintemp.PeriodEnd),8))) As PeriodTiming , Maintemp.ClassName,Maintemp.SectionName,Maintemp.SubjectName,case when Att.Dt_Date is not null       
 then  1 else 0 end as Isattendance      
 --,Logbook.LookBookID,Logbook.ClassExecutedDate,Logbook.CompletionPercentage      
 ,Case when  I_Teacher_Time_Plan_ID Is not null Then 1 else 0 end as Logid      
 ,Case When  CRW.Dt_Date IS not null Then 1 Else 0 end Classwork      
 , 0 as Homework      
 from #RoutineWiseLogBook Maintemp      
 Left Join T_ERP_Attendance_Entry_Header Att       
 on Att.I_Student_Class_Routine_ID=Maintemp.StudentClassRoutineID      
 and  convert(date,Dt_Date)=CONVERT(date,getdate())      
  --Left join      
  -- (      
  -- select TTP.I_Teacher_Time_Plan_ID as LookBookID,      
  -- TTP.Dt_Plan_Date as ClassDate,SSP.I_Subject_Structure_Plan_ID as SubjectStructurePlanID,      
  -- TTP.I_Student_Class_Routine_ID as StudentClassRoutineID,SSP.I_Day_No as LessionPlanDayNo,      
  -- SSP.I_Month_No as LessionPlanMonthno,SSPER.I_Completion_Percentage as CompletionPercentage,SSPER.S_Remarks as Remarks      
  -- ,SSPER.Dt_ExecutedAt as ClassExecutedDate      
  -- from T_ERP_Teacher_Time_Plan as TTP       
  -- inner join      
  -- T_ERP_Subject_Structure_Plan as SSP on TTP.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID      
  -- inner join      
  -- T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID      
  -- left join      
  -- T_ERP_Subject_Structure_Plan_Execution_Remarks as SSPER       
  -- on SSPER.I_Teacher_Time_Plan_ID=TTP.I_Teacher_Time_Plan_ID      
         
  -- ) as Logbook on       
  -- Logbook.StudentClassRoutineID=Maintemp.StudentClassRoutineID      
  Left Join T_ERP_Teacher_Time_Plan TTP       
  ON TTP.I_Student_Class_Routine_ID=Maintemp.StudentClassRoutineID      
  and convert(date,TTP.Dt_Class_Date)=CONVERT(date,getdate())      
  Left Join T_ERP_Student_Class_Routine_Work CRW       
  on CRW.I_Student_Class_Routine_ID=Maintemp.StudentClassRoutineID      
  and Convert(Date,CRW.Dt_Date)=Convert(date,GETDATE())      
 order by Maintemp.PeriodNo,Maintemp.ClassID      
 --select * from #RoutineWiseLogBook      
 drop table #RoutineWiseLogBook      
      
 --select * from T_ERP_Teacher_Time_Plan      
 End
GO
