    RT.S_Status_Desc,
    TM.I_ERP_TransactionNo,
    CASE
        WHEN TID.I_ERP_Transaction_Master_ID IS NULL THEN 'Offline'
        ELSE 'Online'
    END AS PaymentMethod,
    CASE 
        WHEN TID.I_ERP_Transaction_Master_ID IS NULL THEN PMM.S_PaymentMode_Name 
