    TM.I_TransactionTotalAmount,
    RH.N_Receipt_Amount,
    RH.N_Tax_Amount,
    CASE 
        WHEN TM.S_TransactionStatus = 'Initiated' THEN 1
        WHEN TM.S_TransactionStatus = 'Initiated' AND DATEDIFF(MINUTE, TM.Dt_TransactionDate, GETDATE()) > 60 THEN 2
        WHEN TM.S_TransactionStatus = 'Success' THEN 3
        WHEN TM.S_TransactionStatus = 'Failure' THEN 4 
		WHEN TM.S_TransactionStatus IS NULL AND RH.I_Receipt_Header_ID IS NOT NULL THEN 3
        ELSE NULL
    END AS ExternalPaymentStatus,
    RH.I_Status,
    RH.Dt_Deposit_Date,
    RH.Bank_Account_Name,
	TM.I_ERP_Brand_PaymentGateway_Map_id,
	BCD.I_Brand_ID,
	TM.S_Mobile_No as ExternalPurchasedMobileNo
FROM 
    T_Receipt_Header AS RH
INNER JOIN 
    dbo.T_PaymentMode_Master PMM WITH (NOLOCK) ON RH.I_PaymentMode_ID = PMM.I_PaymentMode_ID
INNER JOIN 
    dbo.T_Status_Master RT WITH (NOLOCK) ON [S_Status_Type] = 'ReceiptType' AND RH.I_Receipt_Type = RT.I_Status_Value
INNER JOIN 
    dbo.T_Centre_Master CEM WITH (NOLOCK) ON RH.I_Centre_Id = CEM.I_Centre_Id
INNER JOIN 
    dbo.T_Brand_Center_Details AS BCD WITH (NOLOCK) ON CEM.I_Centre_Id = BCD.I_Centre_Id
INNER JOIN 
    dbo.T_Brand_Master AS BM WITH (NOLOCK) ON BCD.I_Brand_ID = BM.I_Brand_ID --AND BM.I_Brand_ID = ISNULL(@BrandID, BM.I_Brand_ID)
INNER JOIN 
    dbo.T_Student_Detail AS SD WITH (NOLOCK) ON RH.I_Student_Detail_ID = SD.I_Student_Detail_ID OR RH.I_Enquiry_Regn_ID=SD.I_Enquiry_Regn_ID
LEFT JOIN 
    dbo.T_Invoice_OnAccount_Details AS IOD WITH (NOLOCK) ON IOD.I_Receipt_Header_ID = RH.I_Receipt_Header_ID
LEFT JOIN 
    T_ERP_Transaction_Invoice_Details AS TID ON TID.ReceiptHeaderID = RH.I_Receipt_Header_ID
LEFT JOIN 
    T_ERP_Transaction_Master AS TM ON TM.I_ERP_Transaction_Master_ID = TID.I_ERP_Transaction_Master_ID
WHERE 
   RH.I_Receipt_Header_ID=@receiptHeaderID
   END
ELSE IF @receiptHeaderID IS NULL AND @transactionNo IS NOT NULL
   BEGIN
SELECT 
    DISTINCT
    SD.S_Student_ID,
    SD.S_First_Name,
    SD.S_Middle_Name,
    SD.S_Last_Name,
    SD.I_Enquiry_Regn_ID,
    NULL AS ReceiptHeaderID,
    NULL AS ReceiptNo,
    NULL AS ReceiptType,
    TM.I_ERP_TransactionNo,
    CASE
        WHEN TID.I_ERP_Transaction_Master_ID IS NULL THEN 'Offline'
        ELSE 'Online'
    END AS PaymentMethod,
    CASE 
        WHEN TID.I_ERP_Transaction_Master_ID IS NULL THEN NULL
        ELSE TM.S_TransactionMode 
    END AS PaymentMode,
    NULL AS SMSPaymentModeID,
    NULL AS SMSPaymentMode,
    NULL AS isAdhoc,
    NULL AS AdhocInvoiceNo,
    TM.Dt_TransactionDate,
    NULL AS ReceiptDate,
    TM.I_TransactionTotalAmount,
    0 AS AmountBreakupReceiptWise,
    0 AS TaxBreakupReceiptWise,
    CASE 
        WHEN TM.S_TransactionStatus = 'Initiated' THEN 1
        WHEN TM.S_TransactionStatus = 'Initiated' AND DATEDIFF(MINUTE, TM.Dt_TransactionDate, GETDATE()) > 60 THEN 2
        WHEN TM.S_TransactionStatus = 'Success' THEN 3
        WHEN TM.S_TransactionStatus = 'Failure' THEN 4 
        ELSE NULL
    END AS ExternalPaymentStatus,
    NULL AS ReceiptStatus,
    NULL AS SattlementDate,
    NULL AS SattlementBankAccount,
	TM.I_ERP_Brand_PaymentGateway_Map_id,
	TM.I_BrandID,
	TM.S_Mobile_No ExternalPurchasedMobileNo
FROM 
    T_ERP_Transaction_Invoice_Details AS TID 
INNER JOIN
    T_ERP_Transaction_Master AS TM ON TM.I_ERP_Transaction_Master_ID = TID.I_ERP_Transaction_Master_ID
INNER JOIN
    T_Invoice_Parent AS TIP ON TIP.I_Invoice_Header_ID = TID.I_Invoice_Header_ID
INNER JOIN
    T_Student_Detail AS SD ON SD.I_Student_Detail_ID = TIP.I_Student_Detail_ID
WHERE 
    TID.ReceiptHeaderID IS NULL 
   AND TM.I_ERP_TransactionNo=@transactionNo
	
END
	select 
	TH.*,
	ExternalStatus.StatusDescription,
	ExternalStatus.StatusColour
	from 
	#Transaction_History as TH
	LEFT join
	@PaymentStatusTable as ExternalStatus on TH.PaymentStatus=ExternalStatus.PaymentStatusID



END
GO
PRINT N'Creating Procedure [dbo].[usp_ERP_Get_TransactionCountAcademicSessionWise]...';


GO
-- =============================================
-- Author:		<Susmita Paul>
-- Create date: <2024-June-11>
-- Description:	<Get Total Transaction>
-- =============================================
CREATE PROCEDURE [dbo].[usp_ERP_Get_TransactionCountAcademicSessionWise] 
	-- Add the parameters for the stored procedure here
	@iBrandID INT,
	@dtStartDate DATETIME,
	@dtEndDate DATETIME

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.

	Create Table #SuccessEx_InternalTransaction
	(
	TransactionNo Varchar(max),
	ReceiptHeaderID INT,
	PaymentStatus varchar(max),
	TotalBaseAmount decimal(8,2),
	TotalTaxAmount decimal(8,2)
	)

	Create Table #UnSuccessFulExternalTransaction
	(
	TransactionNo Varchar(max),
	PaymentStatus varchar(max),
	TotalTransactionAmount decimal(8,2)
	)


--- Success Transaction
  insert into #SuccessEx_InternalTransaction
  select Distinct TM.I_ERP_TransactionNo,RH.I_Receipt_Header_ID,
  CASE WHEN 
  TM.I_ERP_Transaction_Master_ID IS NOT NULL THEN TM.S_TransactionStatus 
  ELSE 'Success'
  END as PaymentStatus,
  ISNULL(RH.N_Receipt_Amount,0),
  ISNULL(RH.N_Tax_Amount,0)
  from 
  T_Receipt_Header as RH
  inner join
  T_Brand_Center_Details as BD on RH.I_Centre_Id=BD.I_Centre_Id
  inner join
  T_Brand_Master as BM on BM.I_Brand_ID=BD.I_Brand_ID
  left join
  T_ERP_Transaction_Invoice_Details as TID on RH.I_Receipt_Header_ID=TID.ReceiptHeaderID and TID.IsCompleted='true'
  left join
  T_ERP_Transaction_Master as TM on TID.I_ERP_Transaction_Master_ID=TM.I_ERP_Transaction_Master_ID and TM.I_StatusID=1
  where RH.I_Status=1 
  and BM.I_Brand_ID=@iBrandID and  
  CONVERT(DATE,RH.Dt_Receipt_Date) between CONVERT(DATE,@dtStartDate) and CONVERT(DATE,@dtEndDate)
  


  select * from #SuccessEx_InternalTransaction

  insert into #UnSuccessFulExternalTransaction
  select I_ERP_TransactionNo,
  CASE WHEN  TM.S_TransactionStatus = 'Initiated' AND DATEDIFF(MINUTE, TM.Dt_TransactionDate, GETDATE()) > 60
  THEN 'Pending'
  ELSE TM.S_TransactionStatus END TransactionStatus,
  ISNULL(TM.I_TransactionTotalAmount,0)
  from T_ERP_Transaction_Master as TM
  inner join
  T_ERP_Transaction_Invoice_Details as TID on TID.I_ERP_Transaction_Master_ID=TM.I_ERP_Transaction_Master_ID 
  where (TM.IsCompleted ='false' OR TM.IsCompleted IS NULL)  --and TID.ReceiptHeaderID IS NULL
  

  select * from #UnSuccessFulExternalTransaction





END
GO
PRINT N'Creating Procedure [dbo].[Usp_ERP_get_User_Brand_List]...';


GO
----EXEC [Usp_ERP_get_User_Brand_List] 53    
CREATE  Proc [dbo].[Usp_ERP_get_User_Brand_List](                
@User_ID int    
    
)                
As                 
Begin     
    
--Declare @User_ID int=53    
                
DECLARE @CurrentYear Varchar(4)                
SELECT @CurrentYear= YEAR(GETDATE())     
------------Display Count--------------------    
    
Declare @centre as Table (CenterID int,brandID int,stdt date,enddt date)    
Insert Into @centre(CenterID,brandID,stdt,enddt)    
select b.I_Centre_Id,b.I_Brand_ID,convert(date,d.Dt_Session_Start_Date)  
,convert(date,d.Dt_Session_End_Date)     
from T_ERP_User_Brand a    
Inner Join T_Brand_Center_Details b on a.I_Brand_ID=b.I_Brand_ID    
Inner Join T_Brand_Master c on c.I_Brand_ID=b.I_Brand_ID and c.I_Status=1    
Inner Join T_School_Academic_Session_Master d on d.I_Brand_ID=c.I_Brand_ID    
where I_User_ID=@User_ID    
     
-------Pending Leads------------------    
     
                
                
                
                
 --Select * from T_School_Academic_Session_Master                
Select UM.I_User_ID,UB.I_Brand_ID ,BM.S_Brand_Name,ASM.I_School_Session_ID ,            
SPCH.N_Value as BrandLogo   ,        
ASM.I_School_Session_ID        
,Bm.S_location as Location      
,ISNULL(UB.Is_Teaching_Staff,'false') as IsTeachingStaff      
,Isnull(enq.RecordCount,0) as TotalEnq    
,isnull(classtot.Totalclass,0) as Total_class    
,isnull(adm.admRecordCount,0) as TotalAdm    
from T_ERP_User_Brand UB                
Inner Join T_ERP_User UM on UM.I_User_ID=UB.I_User_ID                
Inner Join T_Brand_Master BM on BM.I_Brand_ID=UB.I_Brand_ID                
Inner Join T_School_Academic_Session_Master ASM on ASM.I_Brand_ID=BM.I_Brand_ID             
Left Join T_ERP_Saas_Pattern_Header SPH on SPH.I_Brand_ID=BM.I_Brand_ID            
Left Join T_ERP_Saas_Pattern_Child_Header SPCH on SPCH.I_Pattern_HeaderID=SPH.I_Pattern_HeaderID            
Left Join @centre BCD on bcd.brandID=Bm.I_Brand_ID       
Left Join (    
SELECT              
    I_Centre_Id ,    
 b.brandID    
     
    ,COUNT(I_Enquiry_Regn_ID) AS RecordCount              
  --Into #Temp_Enq              
FROM              
    T_Enquiry_Regn_Detail a    
 Inner Join @centre b on a.I_Centre_Id=b.CenterID    
     
 where I_ERP_Entry=1              
 and I_Enquiry_Status_Code =1              
And               
    convert(date,Dt_Crtd_On) >= stdt              
    AND convert(date,Dt_Crtd_On) < enddt          
 --and I_Centre_Id=@Centerid        
GROUP BY              
    I_Centre_Id      
 ,b.brandID    
    
) enq on enq.I_Centre_Id=bcd.CenterID and enq.brandID=bm.I_Brand_ID    
Left Join     
(    
select count(tc.I_Class_ID) as Totalclass,bm.I_Brand_ID as classBrand from T_Class TC     
Inner Join T_Brand_Master bm on tc.I_Brand_ID=bm.I_Brand_ID and tc.I_Status=1    
Group By bm.I_Brand_ID    
) classtot on classtot.classBrand=bm.I_Brand_ID    
    
Left Join (    
SELECT              
    I_Centre_Id     
 ,b.brandID    
 ,            
    COUNT(I_Enquiry_Regn_ID) AS admRecordCount              
  --Into #Temp_Enq              
FROM              
    T_Enquiry_Regn_Detail a    
 Inner Join @centre b on a.I_Centre_Id=b.CenterID    
     
 where I_ERP_Entry=1              
 and I_Enquiry_Status_Code =3              
--And               
--    convert(date,Dt_Crtd_On) >= stdt              
--    AND convert(date,Dt_Crtd_On) < enddt          
 --and I_Centre_Id=@Centerid        
GROUP BY              
    I_Centre_Id ,b.brandID             
    
) adm on adm.I_Centre_Id=bcd.CenterID and adm.brandID=bm.I_Brand_ID    
    
where UM.I_User_ID=@User_ID                
And BM.I_Status=1 and UM.I_Status=1 and UB.Is_Active=1 and ASM.I_Status=1             
And SPH.S_Property_Name='BRAND_LOGO'            
and Year(asm.Dt_Session_Start_Date)=@CurrentYear             
and SPH.Is_Active=1 and SPCH.Is_Active=1          
End
GO
