GO


-- =============================================
-- Author:		<Susmita Paul>
-- Create date: <2023-Nov-23>
-- Description:	<Get Log Book View Details>
-- =============================================
CREATE PROCEDURE  [dbo].[usp_ERP_GetDateWiseLogBookMappedDetailsAPI]
	-- Add the parameters for the stored procedure here
	@stoken varchar(max),
	@iClassRoutineID INT,
	@DtClassDate datetime,
	@iSubjectID INT=null

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here


	DECLARE @iFacultyID INT=NULL
	DECLARE @ErrMessage NVARCHAR(4000)


	IF NOT EXISTS
	(
	select * from 
	T_Faculty_Master as FM 
	inner join
	T_ERP_User as UM on UM.I_User_ID=FM.I_User_ID where 
	UM.S_Token=@sToken and FM.I_Status=1
	)
	BEGIN

		SELECT @ErrMessage='Invalid Token'

		RAISERROR(@ErrMessage,11,1)

	END

	ELSE

	BEGIN

	IF NOT EXISTS
	(
	select * from 
	T_Faculty_Master as FM 
	inner join
	T_ERP_User as UM on UM.I_User_ID=FM.I_User_ID
	inner join
	T_ERP_Student_Class_Routine as SCR on SCR.I_Faculty_Master_ID=FM.I_Faculty_Master_ID
	inner join
	T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
	inner join
	T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
	inner join
	T_Subject_Master as SM on SM.I_Subject_ID=SCR.I_Subject_ID and RSH.I_Class_ID=SM.I_Class_ID and SM.I_School_Group_ID=RSH.I_School_Group_ID
	where 
	UM.S_Token=@sToken and SCR.I_Subject_ID=@iSubjectID and SCR.I_Student_Class_Routine_ID=@iClassRoutineID
	and RSD.I_Day_ID = DATEPART(WEEKDAY,@DtClassDate) and FM.I_Status=1
	)
	BEGIN

		SELECT @ErrMessage='Invalid Request'

		RAISERROR(@ErrMessage,11,1)

	END

	END


	select @iFacultyID=FM.I_Faculty_Master_ID from 
	T_Faculty_Master as FM 
	inner join
	T_ERP_User as UM on UM.I_User_ID=FM.I_User_ID where 
	UM.S_Token=@sToken and FM.I_Status=1









	DECLARE @RoutineHeaderID INT=null

	select @RoutineHeaderID=RSH.I_Routine_Structure_Header_ID from 
	T_ERP_Student_Class_Routine as SCR 
	inner join
	T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
	inner join
	T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
	where SCR.I_Student_Class_Routine_ID=@iClassRoutineID

	IF @RoutineHeaderID IS NOT NULL

	BEGIN

	CREATE table #LogBookDetail
	(
	ClassDate datetime,
	SubjectStructurePlanID int,
	StudentClassRoutineID int,
	RoutineHeaderID int,
	LessionPlanDayNo int,
	LessionPlanMonthno int,
	TeacherTimePlanID int,
	CompletionPercentage decimal(4,1),
	Remarks varchar(max),
	LearningOutcomeAchieved varchar(max),
	ClassExecutedDate datetime,
	IsDayCompleted bit,
	BrandID int,
	IsEditable bit,
	TotalCompletionPercentage decimal(4,1),
	IsRemarksRegister bit,
	
	)



	insert into #LogBookDetail
	select DISTINCT
	Logbook.* ,
	CASE WHEN ISNULL(LogRegisterAfter.TotalRegisteredAfter,0) > 0 OR (config.S_config_Value like 'No') OR Logbook.IsDayCompleted = 'True'
	then 'false'
	ELSE
	'true'
	END as IsEditable,
	TotalCompletionPercentage.TotalCompletionPercentage,1 IsRemarksRegister
	

	from 
	(
	select CAST(TTP.Dt_Class_Date as DATE) as ClassDate,SSP.I_Subject_Structure_Plan_ID as SubjectStructurePlanID ,
	TTP.I_Student_Class_Routine_ID as StudentClassRoutineID,RSH.I_Routine_Structure_Header_ID as RoutineHeaderID,
	SSP.I_Day_No as LessionPlanDayNo,
	SSP.I_Month_No as LessionPlanMonthno,TTP.I_Teacher_Time_Plan_ID as TeacherTimePlanID,
	SSPER.I_Completion_Percentage as CompletionPercentage,
	SSPER.S_Remarks as Remarks,SSPER.S_Learning_Outcome_Achieved as LearningOutcomeAchieved
	,SSPER.Dt_ExecutedAt as ClassExecutedDate,ISNULL(SSPER.Is_Completed,'false')  as IsDayCompleted,SM.I_Brand_ID as BrandID
	from T_ERP_Teacher_Time_Plan as TTP 
	inner join
	T_ERP_Subject_Structure_Plan as SSP on TTP.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
	inner join
	T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
	inner join
	T_ERP_Student_Class_Routine as SCR on SCR.I_Student_Class_Routine_ID=TTP.I_Student_Class_Routine_ID
	inner join
	T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
	inner join
	T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
	inner join
	T_ERP_Subject_Structure_Plan_Execution_Remarks as SSPER on SSPER.I_Teacher_Time_Plan_ID=TTP.I_Teacher_Time_Plan_ID
	inner join
	T_Subject_Master as SM on SM.I_Subject_ID = SCR.I_Subject_ID
	where TTP.I_Student_Class_Routine_ID=@iClassRoutineID and 
	SCR.I_Subject_ID=@iSubjectID 
	and CONVERT(DATE,TTP.Dt_Class_Date)=CONVERT(DATE,@DtClassDate)
	) as Logbook 
	inner join
	(
	select I_Subject_Structure_Plan_ID,I_Routine_Structure_Header_ID
	,SUM(ISNULL(lessionPercentage,0.0)) as TotalCompletionPercentage

	from 
	(
	select DISTINCT SSP.I_Subject_Structure_Plan_ID,RSH.I_Routine_Structure_Header_ID
	,ISNULL(SSPER.I_Completion_Percentage,0.0) as lessionPercentage
	,SCR.I_Student_Class_Routine_ID,TTP.Dt_Class_Date

	from T_ERP_Teacher_Time_Plan as TTP
		inner join
		T_ERP_Subject_Structure_Plan as SSP on TTP.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
		inner join
		T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
		inner join
		T_ERP_Subject_Structure_Plan_Execution_Remarks as SSPER on SSPER.I_Teacher_Time_Plan_ID=TTP.I_Teacher_Time_Plan_ID
		inner join
		T_ERP_Student_Class_Routine as SCR on SCR.I_Student_Class_Routine_ID=TTP.I_Student_Class_Routine_ID
		inner join
		T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
		inner join
		T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
		where RSH.I_Routine_Structure_Header_ID=@RoutineHeaderID
	) as t
	group by I_Routine_Structure_Header_ID,I_Subject_Structure_Plan_ID
	) TotalCompletionPercentage on TotalCompletionPercentage.I_Subject_Structure_Plan_ID=Logbook.SubjectStructurePlanID
	
	
	
	left join
	(
	select
	I_Subject_Structure_Plan_ID,I_Routine_Structure_Header_ID,count(*) as TotalRegisteredAfter

	from 
	(
	select DISTINCT SSP.I_Subject_Structure_Plan_ID,RSH.I_Routine_Structure_Header_ID


	from T_ERP_Teacher_Time_Plan as TTP
		inner join
		T_ERP_Subject_Structure_Plan as SSP on TTP.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
		inner join
		T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
		inner join
		T_ERP_Subject_Structure_Plan_Execution_Remarks as SSPER on SSPER.I_Teacher_Time_Plan_ID=TTP.I_Teacher_Time_Plan_ID
		inner join
		T_ERP_Student_Class_Routine as SCR on SCR.I_Student_Class_Routine_ID=TTP.I_Student_Class_Routine_ID
		inner join
		T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
		inner join
		T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
		where RSH.I_Routine_Structure_Header_ID=@RoutineHeaderID and 
		SCR.I_Subject_ID=@iSubjectID 
	and CONVERT(DATE,TTP.Dt_Class_Date)>CONVERT(DATE,@DtClassDate) 

	) as t
	group by I_Routine_Structure_Header_ID,I_Subject_Structure_Plan_ID
	) as LogRegisterAfter on LogRegisterAfter.I_Subject_Structure_Plan_ID=Logbook.SubjectStructurePlanID

	left join
	(
	select ECM.S_config_code,ECM.S_config_Value,ECM.I_Brand_ID from 
	T_ERP_Configuration_Master as ECM
	inner join
	T_ERP_Configuration_Type as ECT on ECM.I_Config_Type_ID=ECT.I_Config_Type_ID
	where 
	ECT.S_Config_Type='Validation' and ECM.S_Screen='LogBook' and ECM.S_config_code='IS_MODIFIED_DAY_ALLOWED'
	and ECM.I_Status=1
	) as config on config.I_Brand_ID=Logbook.BrandID


	order by Logbook.LessionPlanDayNo,Logbook.IsDayCompleted

	
	select DISTINCT
	--@DtClassDate,
	ISNULL(SG.I_School_Group_ID,0) as SchoolGroupID,
	ISNULL(SG.S_School_Group_Name,'NA') as SchoolGroupName,
	ISNULL(C.I_Class_ID,0) as ClassID,
	ISNULL(C.S_Class_Name,'NA') as ClassName,
	ISNULL(S2.I_Section_ID,0) as SectionID,
	ISNULL(S2.S_Section_Name,'--') as SectionName,
	ISNULL(S.I_Stream_ID,0) as StreamID,
	ISNULL(S.S_Stream,'NA') as Stream,
	SM.I_Subject_ID as SubjectID,
	SM.S_Subject_Name as SubjectName,
	RSD.I_Period_No as PeriodNo,
	RSD.T_FromSlot as PeriodStart,
	RSD.T_ToSlot as PeriodEnd,
	WDM.I_Day_ID as ClassDayID,
	WDM.S_Day_Name as ClassDayName,
	SG.I_Brand_Id as BrandID,

	CASE WHEN config.S_config_code IS NULL OR config.S_config_Value = 'Yes' THEN 'true'
	ELSE
	'false' END as IsMultipleIncompleteDaysAllowed

	from 
	T_ERP_Student_Class_Routine as SCR 
	inner join
	T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
	inner join
	T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
	inner join
	T_Subject_Master as SM on SM.I_Subject_ID=SCR.I_Subject_ID and SM.I_Status=1
	inner join
	T_Week_Day_Master as WDM on WDM.I_Day_ID=RSD.I_Day_ID
	left join
	T_School_Group as SG on SG.I_School_Group_ID=RSH.I_School_Group_ID
	left join
	T_Class as C on C.I_Class_ID=RSH.I_Class_ID
	left join
	T_Stream as S on S.I_Stream_ID=RSH.I_Stream_ID
	left join
	T_Section as S2 on S2.I_Section_ID=RSH.I_Section_ID
	left join
	(
	select ECM.S_config_code,ECM.S_config_Value,ECM.I_Brand_ID from 
	T_ERP_Configuration_Master as ECM
	inner join
	T_ERP_Configuration_Type as ECT on ECM.I_Config_Type_ID=ECT.I_Config_Type_ID
	where 
	ECT.S_Config_Type='Validation' and ECM.S_Screen='LogBook' and ECM.S_config_code='IS_MULTIPLE_INCOMPLETE_DAYS_ALLOWED'
	and ECM.I_Status=1
	) as config on config.I_Brand_ID=SG.I_Brand_Id
	where SCR.I_Student_Class_Routine_ID=@iClassRoutineID
	
	
	
	select * from #LogBookDetail

	


	select mappedlessionPlan.SubjectStructurePlanID,SSPD.I_Subject_Structure_ID as LeafSubjectStructureID from 
	#LogBookDetail as mappedlessionPlan
	inner join
	T_ERP_Subject_Structure_Plan as SSP on mappedlessionPlan.SubjectStructurePlanID=SSP.I_Subject_Structure_Plan_ID
	inner join
	T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
	inner join
	T_ERP_Subject_Structure as SS on SSPD.I_Subject_Structure_ID=SS.I_Subject_Structure_ID and I_Status=1
	
	
	--order by remainglessionPlan.SubjectStructurePlanID


	drop table #LogBookDetail
	
	END

END
GO
PRINT N'Creating Procedure [dbo].[usp_ERP_GetDayWiseSubjectPlanDetailsForSubject]...';


GO

-- =============================================
-- Author:		<Susmita Paul>
-- Create date: <2023-Nov-02>
-- Description:	<Get Subject mapped with structure>
-- =============================================
CREATE PROCEDURE [dbo].[usp_ERP_GetDayWiseSubjectPlanDetailsForSubject] 
	-- Add the parameters for the stored procedure here
	@iAcademicSessionID INT=NULL,
	@iBrandID INT,
	@iSubject INT=NULL
	,@iMonthNo INT=NULL
	,@iUserID INT=NULL
	,@iSchoolGroup INT=NULL
	,@iClass INT = NULL
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;


	Create Table #SubjectStructurePlan
			(
			SubjectID int,
			SubjectName varchar(max),
			MonthNo INT,
			DayNo INT,
			SubjectStructurePlanID int,
			SubjectStructurePlanDetailID int,
			LeafSubjectStructureID int,
			LeafSubjectLevelDesc varchar(max),
			IsPlanedMappedwithRoutine bit
			)


	insert into #SubjectStructurePlan
	 select 
	 SM.I_Subject_ID as SubjectID
	,SM.S_Subject_Name as SubjectName
	,subjectStructurePlan.I_Month_No as MonthNo
	,subjectStructurePlan.I_Day_No as DayNo
	,subjectStructurePlan.I_Subject_Structure_Plan_ID as SubjectStructurePlanID
	,subjectStructurePlan.I_Subject_Structure_Plan_Detail_ID as SubjectStructurePlanDetailID
	,subjectStructurePlan.I_Subject_Structure_ID as LeafSubjectStructureID
	,subjectStructurePlan.S_Name as LeafSubjectLevelDesc
	,CASE 
	WHEN SubjectTimePlan.Dt_Class_Date IS NULL THEN 0
	ELSE 1
	END as IsPlanedMappedwithRoutine
	 from 
	T_Subject_Master as SM 
	inner join
	T_School_Group as SG on SG.I_School_Group_ID=SM.I_School_Group_ID and SG.I_Status=1
	inner join
	T_Class as TC on TC.I_Class_ID=SM.I_Class_ID and TC.I_Status=1
	left join
	(
		select SSP.*,SSPD.I_Subject_Structure_Plan_Detail_ID,SSPD.I_Subject_Structure_ID,ESS.S_Name  from 
		T_ERP_Subject_Structure_Plan as SSP 
		inner join
		T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
		inner join
		T_ERP_Subject_Structure as ESS on ESS.I_Subject_Structure_ID=SSPD.I_Subject_Structure_ID
		inner join
		T_ERP_Subject_Structure_Header as ESSH on ESSH.I_Subject_Structure_Header_ID=ESS.I_Subject_Structure_Header_ID
		inner join
		T_ERP_Subject_Template_Header as ESTH on ESTH.I_Subject_Template_Header_ID=ESSH.I_Subject_Template_Header_ID
		inner join
		T_ERP_Subject_Template as EST on EST.I_Subject_Template_Header_ID=ESTH.I_Subject_Template_Header_ID
		and EST.I_Subject_Template_ID=ESS.I_Subject_Template_ID
		where SSP.I_Month_No=ISNULL(@iMonthNo,SSP.I_Month_No) and (SSP.I_School_Session_ID=ISNULL(@iAcademicSessionID,SSP.I_School_Session_ID)) 
	) as subjectStructurePlan on subjectStructurePlan.I_Subject_ID=SM.I_Subject_ID

	left join
	(
	select SSP.I_Subject_Structure_Plan_ID,SSP.I_Subject_ID,TTP.Dt_Class_Date,SSP.I_Day_No from 
	T_ERP_Subject_Structure_Plan as SSP
	inner join
	T_ERP_Subject_Structure_Plan_Detail as SSPD on SSPD.I_Subject_Structure_Plan_ID=SSP.I_Subject_Structure_Plan_ID
	inner join
	T_ERP_Teacher_Time_Plan as TTP on SSP.I_Subject_Structure_Plan_ID=TTP.I_Subject_Structure_Plan_ID
	inner join
	T_ERP_Student_Class_Routine as SCR on SCR.I_Student_Class_Routine_ID=TTP.I_Student_Class_Routine_ID
	inner join
	T_ERP_Routine_Structure_Detail as RSD on RSD.I_Routine_Structure_Detail_ID=SCR.I_Routine_Structure_Detail_ID
	inner join
	T_ERP_Routine_Structure_Header as RSH on RSH.I_Routine_Structure_Header_ID=RSD.I_Routine_Structure_Header_ID
	inner join
	T_School_Academic_Session_Master as SASM on SASM.I_School_Session_ID=RSH.I_School_Session_ID
	where SSP.I_Month_No=ISNULL(@iMonthNo,SSP.I_Month_No) and (SSP.I_School_Session_ID=ISNULL(@iAcademicSessionID,SSP.I_School_Session_ID))
	) as SubjectTimePlan on --SubjectTimePlan.I_Subject_Structure_Plan_ID=subjectStructurePlan.I_Subject_Structure_Plan_ID
	SubjectTimePlan.I_Subject_ID=SM.I_Subject_ID
	and
	SubjectTimePlan.I_Day_No=subjectStructurePlan.I_Day_No
	where SM.I_Brand_ID=@iBrandID 
	and SG.I_School_Group_ID=ISNULL(@iSchoolGroup,SG.I_School_Group_ID) 
	and TC.I_Class_ID=ISNULL(@iClass,TC.I_Class_ID)
	and SM.I_Subject_ID= ISNULL(@iSubject,SM.I_Subject_ID)
	and SM.I_Status=1

	select DISTINCT * from #SubjectStructurePlan where MonthNo IS NOT NULL

	drop table #SubjectStructurePlan



END
GO
PRINT N'Creating Procedure [dbo].[usp_ERP_GetEnquiryAndFollowUpDetails]...';


GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- exec usp_ERP_GetEnquiryAndFollowUpDetails 234995
CREATE PROCEDURE [dbo].[usp_ERP_GetEnquiryAndFollowUpDetails]  
	@I_Enquiry_Regn_ID INT 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here

	--------------------------------------------------------------------------------------------
	------------------------  Get the Enquiry Info ---------------------------------
	--------------------------------------------------------------------------------------------
	SELECT TEERD.[I_Enquiry_Regn_ID] AS EnquiryRegnID
      ,[I_Enquiry_Status_Code] AS EnquiryStatusCode
      ,TEERD.[I_Enquiry_Type_ID] AS EnquiryType
	  ,TEET.[S_Enquiry_Type_Desc] AS EnquiryTypeDesc 
      ,[S_Enquiry_No] AS EnquiryNo
	  ,CONCAT(ISNULL(TEERD.S_First_Name, ''),' ',ISNULL(TEERD.S_Middle_Name, ''),' ',ISNULL(TEERD.S_Last_Name, '')) AS Full_Name
      ,TEERD.S_Email_ID AS Email
      ,TEERD.S_Mobile_No AS Mobile
	  ,TEERD.R_I_School_Session_ID AS AcademicSessionID
	  ,TSASM.S_Label AS AcademicSessionName
      ,[S_Student_Photo] AS Photo
	  ,CAST(TEERD.[Dt_Crtd_On] AS DATE) AS EnquiryDate
      ,[Enquiry_Crtd_By] AS EnquiryCretedBy
	  ,CAST(TEERD.[PreEnquiryDate] AS DATE) AS PreEnquiryDate
      ,[PreEnquiry_Crtd_By] AS PreEnquiryCreatedBy
	  ,TEERD.App_Payment_Status AS AppPaymentStatus
	  ,TEERD.S_Father_Name as FatherName
	  ,TEERD.S_Mother_Name AS MotherName
	  ,ISNULL(TEISM.S_Info_Source_Name,'NA') S_Info_Source_Name,
	  TEISM.I_Info_Source_ID
	  ,ISNULL(TECD.S_Name,'NA') S_Name
	  ,ISNULL(TEECD.S_Referal,'NA')S_Referal


	  FROM [T_Enquiry_Regn_Detail] AS TEERD 
	  left join T_Enquiry_Type AS TEET ON TEERD.I_Enquiry_Type_ID = TEET.I_Enquiry_Type_ID
	  left join T_School_Academic_Session_Master as TSASM on TEERD.R_I_School_Session_ID = TSASM.I_School_Session_ID
	  left join T_ERP_Enquiry_CRM_Details TEECD on TEECD.I_Enquiry_ID=TEERD.I_Enquiry_Regn_ID
	  left join T_ERP_CRMSource_Details TECD on TECD.I_Source_DetailsID = TEECD.I_Source_DetailsID
	  left join T_ERP_EnqType_Source_Mapping TEESM ON TEESM.I_EnqType_Source_Mapping_ID=TECD.I_EnqType_Source_Mapping_ID
	  left join T_Information_Source_Master TEISM ON TEISM.I_Info_Source_ID = TEESM.I_Info_Source_ID
	  

	  WHERE
		(TEERD.I_Enquiry_Regn_ID = @I_Enquiry_Regn_ID) AND I_ERP_Entry = 1
	



		--------------------------------------------------------------------------------------------
		------------------------  Get the FolllowUp Info ---------------------------------
		--------------------------------------------------------------------------------------------

		SELECT 		
		TEERF.ERP_R_I_FollowupType_ID AS FollowUpType --
		,TEFM.S_Followup_Name AS FollowUpTypeName
		,TEERF.Dt_Followup_Date AS FollowUpDate
		,TEERF.Dt_Next_Followup_Date AS NextFollowUpDate
		,TEERF.S_Followup_Status AS FollowUpStatus
		,TEFSM.S_FollowupStatus_Desc AS FollowUpStatusDesc
		,TEERF.S_Followup_Remarks AS FollowUpRemark

		FROM
		T_Enquiry_Regn_Followup AS TEERF 
		inner join [dbo].[T_ERP_Followup_StatusM] as TEFSM on TEFSM.[I_FollowupStatus_ID] = TEERF.S_Followup_Status
		left join T_ERP_FollowupType_Master AS TEFM ON TEERF.ERP_R_I_FollowupType_ID = TEFM.I_FollowupType_ID

		
		WHERE (TEERF.I_Enquiry_Regn_ID = @I_Enquiry_Regn_ID )
		order by TEERF.I_Followup_ID desc
END
GO
