PRINT N'Creating Procedure [dbo].[usp_ERP_GetFacultySubjectMatrix]...';


GO
-- =============================================  
-- Author:  <Author,,Name>  
-- Create date: <Create Date,,>  
-- Description: <Description,,>  

-- exec usp_ERP_GetFacultySubjectMatrix 24
-- =============================================  
CREATE PROCEDURE [dbo].[usp_ERP_GetFacultySubjectMatrix]  
 -- Add the parameters for the stored procedure here  
 (  
  @RHeaderId int  
 )  
AS  
BEGIN  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 SET NOCOUNT ON;  
  
    -- Insert statements for procedure here  
Declare @SchoolGroupID int, @ClassID int, @SessionID int
select top 1 @SchoolGroupID=I_School_Group_ID, @SessionID=I_School_Session_ID,@ClassID= I_Class_ID 
from T_ERP_Routine_Structure_Header where I_Routine_Structure_Header_ID = @RHeaderId

select distinct TESCR.I_Subject_ID,
TSm.S_Subject_Name
--into #subjectData
from T_ERP_Student_Class_Routine TESCR
inner join T_ERP_Routine_Structure_Detail TERSD on TESCR.I_Routine_Structure_Detail_ID = TERSD.I_Routine_Structure_Detail_ID
inner join T_Subject_Master TSM on TESCR.I_Subject_ID = TSM.I_Subject_ID
where TERSD.I_Routine_Structure_Header_ID = @RHeaderId and TESCR.I_Faculty_Master_ID IS NOT NULL and TESCR.I_Faculty_Master_ID <> 0
 
--Select @SessionID  
-----------Day Wise Count -------------------  
DECLARE @StartDate DATE = (Select Convert(date,Dt_Session_Start_Date )  
from T_School_Academic_Session_Master where I_School_Session_ID=@SessionID)  
DECLARE @EndDate DATE =( Select Convert(date,Dt_Session_End_Date )  
from T_School_Academic_Session_Master where I_School_Session_ID=@SessionID)  
--Select @StartDate,@EndDate  
;WITH DateRange AS (  
    SELECT @StartDate AS Date  
    UNION ALL  
    SELECT DATEADD(DAY, 1, Date)  
    FROM DateRange  
    WHERE Date < @EndDate  
)  
SELECT   
    Date,DATENAME(WEEKDAY, Date) AS DayName  
Into #DayCount  
FROM   
    DateRange  
--LEFT JOIN   
--    YourTable ON YourTable.DateColumn = Date  
GROUP BY   
    Date  
ORDER BY   
    Date  
  option (maxrecursion 0)  
  Select COUNT([DayName]) as Daycount,[DayName] as Day_Name   
  Into #DaywiseCount  
  from #DayCount  
  group by [DayName]  
  Declare @TotalWkCount int =(  
    Select top 1 Daycount from #DaywiseCount  
  )
select 
count(TESCR.I_Subject_ID) SubjectWkCount,
count(TESCR.I_Subject_ID)*@TotalWkCount as SubjectTotalCount ,
TERSD.I_Routine_Structure_Header_ID RHeaderID,
TESCR.I_Faculty_Master_ID FacultyID,
TFM.S_Faculty_Name,
TESCR.I_Subject_ID SubjectID,
TSM.S_Subject_Name

from T_ERP_Routine_Structure_Detail TERSD
left join T_ERP_Student_Class_Routine TESCR on TERSD.I_Routine_Structure_Detail_ID = TESCR.I_Routine_Structure_Detail_ID 
inner join T_Faculty_Master TFM on TESCR.I_Faculty_Master_ID = TFM.I_Faculty_Master_ID
inner join T_Subject_Master TSM on TESCR.I_Subject_ID = TSM.I_Subject_ID
--right join #subjectData t1 on t1.I_Subject_ID = TESCR.I_Subject_ID
where I_Routine_Structure_Header_ID = @RHeaderId and TESCR.I_Faculty_Master_ID IS NOT NULL
Group by TESCR.I_Faculty_Master_ID, I_Routine_Structure_Header_ID,
TESCR.I_Subject_ID, TFM.S_Faculty_Name, TSM.S_Subject_Name
--drop table #subjectData
drop table #DayCount
drop table #DaywiseCount

END
GO
PRINT N'Creating Procedure [dbo].[usp_ERP_GetFeeComponent_Master]...';


GO
    
-- =============================================    
-- Author:  <Susmita Paul>    
-- Create date: <2024-Jan-20>    
-- Description: <to get Fee components Master from Old to new>    
  
-- exec [dbo].[usp_ERP_GetFeeComponent_Master] null, 107, null, null  
-- =============================================    
    
CREATE PROCEDURE [dbo].[usp_ERP_GetFeeComponent_Master]    
 @FeeHeadId int null,    
 @iBrand int,    
 @isindividual bit = NULL,    
 @isadhoc bit =NULL    
    
    
AS     
    BEGIN      
     
    
 DECLARE @sFeeComponentTypeID INT=NULL;    
     
 IF @isindividual IS NOT NULL    
  BEGIN    
    
   IF @isindividual ='true'    
   BEGIN    
    SET @sFeeComponentTypeID=2    
   END    
   ELSE    
   BEGIN    
    SET @sFeeComponentTypeID=1    
   END    
    
    
  END    
    
  SELECT   
    FeeHeadID,    
    FeeComponentCode,    
    FeeComponent,    
    FeeComponentTypeID,    
    FeeComponentTypeName,    
    TypeOfComponent,    
    Activestatus,    
    Createdby,    
    updatedby,    
    CreatedOn,    
    UpdatedOn,    
    BrandID,  
    Is_GST_Applicable,  
    GST_config,  
 CONVERT(date, Valid_from) AS Valid_from,  
 CONVERT(date, Valid_from) AS Valid_to  
FROM  
(  
    SELECT   
        a.I_Fee_Component_ID AS FeeHeadID,    
        S_Component_Code AS FeeComponentCode,    
        S_Component_Name AS FeeComponent,    
        A.I_Fee_Component_Type_ID AS FeeComponentTypeID,    
        TFCT.S_Fee_Component_Type_Name AS FeeComponentTypeName,    
        A.S_Type_Of_Component AS TypeOfComponent,    
        A.I_Status AS Activestatus,    
        A.S_Crtd_By AS Createdby,    
        A.S_Upd_By AS updatedby,    
        A.Dt_Crtd_On AS CreatedOn,    
        A.Dt_Upd_On AS UpdatedOn,    
        a.I_Brand_ID AS BrandID,  
        Is_GST_Applicable,  
        I_GST_FeeComponent_Catagory_ID AS GST_config,  
        ROW_NUMBER() OVER (PARTITION BY a.I_Fee_Component_ID ORDER BY Dt_Valid_From) AS RowNum,  
        --Dt_Valid_From AS Valid_from,  
        --Dt_Valid_To AS Valid_to  
  CONVERT(date, Dt_Valid_From) AS Valid_from,  
        CONVERT(date, Dt_Valid_To) AS Valid_to  
    FROM      
        dbo.T_Fee_Component_Master A    
    INNER JOIN   
        dbo.T_Fee_Component_Type AS TFCT ON A.I_Fee_Component_Type_ID = TFCT.I_Fee_Component_Type_ID  
    LEFT JOIN   
        T_ERP_GST_Item_Category AS TEGIC ON a.I_Fee_Component_ID = TEGIC.I_Fee_Component_ID  
    LEFT JOIN   
        T_Tax_Country_Fee_Component AS TTCFC ON a.I_Fee_Component_ID = TTCFC.I_Fee_Component_ID  
    WHERE     
        A.I_Status = 1   
        AND A.I_Brand_ID = @iBrand   
        AND a.I_Fee_Component_ID = ISNULL(@FeeHeadId, a.I_Fee_Component_ID)  
        AND A.I_Fee_Component_Type_ID = ISNULL(@sFeeComponentTypeID, A.I_Fee_Component_Type_ID)    
) AS Subquery  
WHERE  
    RowNum = 1  
ORDER BY   
    FeeComponentCode,    
    FeeComponent;  
  
    
  --SELECT a.I_Fee_Component_ID FeeHeadID ,    
  --   S_Component_Code FeeComponentCode,    
  --              S_Component_Name FeeComponent,    
  --              A.I_Fee_Component_Type_ID  as FeeComponentTypeID,    
  --  TFCT.S_Fee_Component_Type_Name FeeComponentTypeName,    
  --  A.S_Type_Of_Component as TypeOfComponent,    
  --              A.I_Status Activestatus,    
  --              A.S_Crtd_By Createdby,    
  --              A.S_Upd_By updatedby,    
  --              A.Dt_Crtd_On CreatedOn,    
  --              A.Dt_Upd_On UpdatedOn,    
  --              a.I_Brand_ID as BrandID,  
  --  Is_GST_Applicable,  
  --  I_GST_FeeComponent_Catagory_ID as GST_config,  
  --  offset(Dt_Valid_From as Valid_from),  
  --  Dt_Valid_To as Valid_to  
  --      FROM    dbo.T_Fee_Component_Master A    
  --              INNER JOIN dbo.T_Fee_Component_Type AS TFCT ON A.I_Fee_Component_Type_ID = TFCT.I_Fee_Component_Type_ID  
  --  left join T_ERP_GST_Item_Category as TEGIC on a.I_Fee_Component_ID = TEGIC.I_Fee_Component_ID  
  --  left join T_Tax_Country_Fee_Component as TTCFC on a.I_Fee_Component_ID = TTCFC.I_Fee_Component_ID  
  --      WHERE   A.I_Status <> 0 and A.I_Brand_ID=@iBrand AND a.I_Fee_Component_ID = ISNULL(@FeeHeadId, a.I_Fee_Component_ID)  
  --  and  A.I_Fee_Component_Type_ID = ISNULL(@sFeeComponentTypeID, A.I_Fee_Component_Type_ID)    
  --      ORDER BY S_Component_Code ,    
  --              S_Component_Name        
        
    END
