where RH.I_Receipt_Header_ID=@iReceiptID  
  
  
  ------ Tax --------  
  
   select  
   RH.I_Receipt_Header_ID as ReceiptHeaderID,  
    ORTD.I_Tax_ID as TaxID,  
    TM.S_Tax_Code as TaxCode,  
