   inner join  
   T_Tax_Master as TM on TM.I_Tax_ID=ORTD.I_Tax_ID  
   where RH.I_Receipt_Header_ID=@iReceiptID  
  
  -------------------  
  
/* -------------- */  
 --select CGCM.I_Course_ID as CourseID,    
