Update T_ERP_InvGenerateRepository set I_IncrementID=@IncrementPart ,
Dtt_Lst_Update=getdate()  
where I_Brand_ID=@brandID and I_School_Session_ID=@SessionID and Type=@type   
--Commit Tran    
end
