CREATE PROCEDURE [dbo].[uspAddSalesOrganizationsToBrand] 
(
	@iBrandID int,
	@sSalesOrganizationList varchar(500),
	@sTransactionBy varchar(20),
	@dTransactionOn datetime
)

AS
SET NOCOUNT OFF
BEGIN TRY

DECLARE @iSalesOrgID int
DECLARE @iGetIndex int
DECLARE @sSalesOrgID varchar(20)
DECLARE @iLength int

BEGIN TRANSACTION
UPDATE dbo.T_Hierarchy_Brand_Details
SET Dt_Valid_To = GETDATE(),
I_Status = 0,
S_Upd_By = @sTransactionBy,
Dt_Upd_On = @dTransactionOn
WHERE I_Brand_ID = @iBrandID


SET @iGetIndex = CHARINDEX(',',LTRIM(RTRIM(@sSalesOrganizationList)),1)

IF @iGetIndex > 1
BEGIN
	WHILE LEN(@sSalesOrganizationList) > 0
	BEGIN
		SET @iGetIndex = CHARINDEX(',',@sSalesOrganizationList,1)
		SET @iLength = LEN(@sSalesOrganizationList)
		SET @iSalesOrgID = CAST(LTRIM(RTRIM(LEFT(@sSalesOrganizationList,@iGetIndex-1))) AS int)

		INSERT INTO dbo.T_Hierarchy_Brand_Details
		( I_Hierarchy_Master_ID, 
		  I_Brand_ID, 
		  I_Status,
		  Dt_Valid_From, 
		  S_Crtd_By, 
		  Dt_Crtd_On )
		VALUES
		( @iSalesOrgID, 
		  @iBrandID, 
		  1, 
		  GETDATE(),
		  @sTransactionBy, 
		  @dTransactionOn )
		
		SELECT @sSalesOrganizationList = SUBSTRING(@sSalesOrganizationList,@iGetIndex + 1, @iLength - @iGetIndex)
		SELECT @sSalesOrganizationList = LTRIM(RTRIM(@sSalesOrganizationList))

	END

END
COMMIT TRANSACTION
END TRY
BEGIN CATCH    
 ROLLBACK TRANSACTION   
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int    
 SELECT @ErrMsg = ERROR_MESSAGE(),    
   @ErrSeverity = ERROR_SEVERITY()    
    
 RAISERROR(@ErrMsg, @ErrSeverity, 1)    
    
END CATCH
GO
PRINT N'Creating Procedure [dbo].[uspAddSchoolGroup]...';


GO
-- =============================================  
-- Author:  <Parichoy Nandi>  
-- Create date: <18th Sept 2023>  
-- Description: <to add school group>  
-- =============================================  
CREATE PROCEDURE [dbo].[uspAddSchoolGroup]  
 -- Add the parameters for the stored procedure here  
 @iGroupid int = null,  
 @sGroupCode varchar(25),  
 @sGroupName varchar(255),  
 @iGroupStatus int,  
 @tStartTime time(0)=null,  
 @tEndTime time(0)=null,  
 @UTRecipient UT_Recipient readonly,  
 @iBrandid int,  
 @sUpdatedBy varchar(255),  
 @iSessionID int   
  
AS  
begin transaction  
BEGIN TRY  
BEGIN  
SET NOCOUNT ON;  
 DECLARE @iLsatID int  
 if(@iGroupid>0)  
 BEGIN  
 create table #ClassSection(  
  id  int identity(1,1) ,  
 ClassID int,  
 SchoolGroupID int)  
 Insert into #ClassSection( ClassID,SchoolGroupID)  
 select   
 Recipient,  
 @iGroupid  
 from @UTRecipient  
   
 Declare @fstV int =1, @lstV int = (Select Max(id) from #ClassSection)  
 while(@fstV <= @lstV)  
 BEGIN   
 dECLARE @IDGroup int, @IDClass int  
 --Set @IDGroup= (Select Top 1 SchoolGroupID  from  #ClassSection)  
 Set @IDClass =  (Select Top 1 ClassID  from  #ClassSection where id=@fstV)   
 if not Exists (select 1 from dbo.[T_School_Group_Class] where I_School_Group_ID= @iGroupid AND I_Class_ID=@IDClass)  
 BEGIN  
