) 
AS  
BEGIN  
	SET NOCOUNT ON 
	DECLARE @B_DeliveryPatternFlag BIT  

	IF (SELECT COUNT(*) FROM dbo.T_Student_Batch_Master AS TSBM
		INNER JOIN dbo.T_Delivery_Pattern_Master AS TDPM
		ON TSBM.I_Delivery_Pattern_ID = TDPM.I_Delivery_Pattern_ID
