CREATE PROCEDURE [dbo].[uspCopyTimeTableForTimeSlot] 
    (    
      @ICenterID INT ,    
      @DtSelected DATETIME ,   
      @SCopyTimeTableForTimeSlotXML XML = NULL ,   
      @ISrcTimeSlotID INT ,    
      @sCrtdBy VARCHAR(20) ,    
      @DtCrtdOn DATETIME          
    )    
AS     
    BEGIN TRY                        
  BEGIN TRANSACTION T1  
          
        -- Create Temporary Table To TimeTable source Information              
        CREATE TABLE #tempTimeTable  
            (  
     I_TimeSlot_ID int ,  
     I_Batch_ID int ,  
     I_Room_ID int ,  
     S_Remarks varchar(500) ,  
     I_Session_ID int ,  
     S_SessionName VARCHAR(500) ,  
     S_SessionTopic VARCHAR(500) ,  
     I_ModuleId INT ,  
     I_TermId INT        
            )    
     
   -- Insert Values into Temporary Table              
        INSERT  INTO #tempTimeTable  
                SELECT  T.c.value('@I_TimeSlot_ID', 'int') ,  
      T.c.value('@I_Batch_ID', 'int') ,  
                        T.c.value('@I_Room_ID', 'int') ,                         
                        CASE WHEN T.c.value('@S_Remarks','varchar(500)') = '' THEN NULL ELSE T.c.value('@S_Remarks','varchar(500)') END,  
                        T.c.value('@I_Session_ID', 'int') ,  
                        T.c.value('@S_SessionName', 'VARCHAR(500)') ,  
                        CASE WHEN T.c.value('@S_SessionTopic', 'varchar(500)') = '' THEN NULL ELSE T.c.value('@S_SessionTopic', 'varchar(500)') END,  
                        T.c.value('@I_ModuleId', 'INT') ,                          
                        T.c.value('@I_TermId', 'INT')  
                FROM    @SCopyTimeTableForTimeSlotXML.nodes('/Root/TimeTableCopy') T ( c )                 
                  
                  
        IF ( SELECT COUNT(*)    
             FROM   T_TimeTable_Master    
             WHERE  I_Center_ID = @ICenterID    
                    AND Dt_Schedule_Date = @DtSelected    
                    AND I_TimeSlot_ID = @ISrcTimeSlotID    
                    AND I_Status = 1  
           ) > 0     
            BEGIN        
  
                DELETE  FROM dbo.T_TimeTable_Faculty_Map    
                WHERE   I_TimeTable_ID IN (    
                        SELECT  I_TimeTable_ID    
                        FROM    dbo.T_TimeTable_Master AS TTTM    
                        WHERE  
                        I_TimeSlot_ID IN (  SELECT  I_TimeSlot_ID FROM #tempTimeTable )  
                        AND I_Center_ID = @ICenterID    
                        AND Dt_Schedule_Date = @DtSelected )    
       
                UPDATE  dbo.T_TimeTable_Master    
                SET     I_Status = 0 ,    
                        S_Updt_By = @sCrtdBy ,    
                        Dt_Updt_On = @DtCrtdOn    
                WHERE    
                        I_TimeSlot_ID IN (  SELECT  I_TimeSlot_ID FROM #tempTimeTable )   
                        AND I_Center_ID = @ICenterID    
                        AND Dt_Schedule_Date = @DtSelected    
                          
                          
                --DELETE  FROM dbo.T_TimeTable_Faculty_Map    
                --WHERE   I_TimeTable_ID IN (    
                --        SELECT  I_TimeTable_ID    
                --      FROM    dbo.T_TimeTable_Master AS TTTM    
                --        WHERE  
                --        I_Batch_ID IN (  SELECT  I_Batch_ID FROM #tempTimeTable )   
                --        AND I_Session_ID IN (  SELECT  I_Session_ID FROM #tempTimeTable )   
                --        AND I_Center_ID = @ICenterID    
                --        AND Dt_Schedule_Date = @DtSelected   
                --        AND I_TimeSlot_ID <> @ISrcTimeSlotID )  
                          
                --UPDATE  dbo.T_TimeTable_Master    
                --SET     I_Status = 0 ,    
                --        S_Updt_By = @sCrtdBy ,    
                --        Dt_Updt_On = @DtCrtdOn    
                --WHERE    
                --        I_Batch_ID IN (  SELECT  I_Batch_ID FROM #tempTimeTable )   
                --        AND I_Session_ID IN (  SELECT  I_Session_ID FROM #tempTimeTable )   
                --        AND I_Center_ID = @ICenterID    
                --        AND Dt_Schedule_Date = @DtSelected  
                --        AND I_TimeSlot_ID <> @ISrcTimeSlotID   
                          
                INSERT  INTO dbo.T_TimeTable_Master    
                        ( I_Center_ID ,    
                          Dt_Schedule_Date ,    
                          I_TimeSlot_ID ,    
                          I_Batch_ID ,    
                          I_Room_ID ,    
                          I_Skill_ID ,    
                          I_Status ,    
                          S_Crtd_By ,    
                          Dt_Crtd_On ,  
                          S_Remarks ,  
                          I_Session_ID ,  
                          I_Term_ID ,   
        I_Module_ID ,  
        S_Session_Name ,  
        S_Session_Topic ,  
        Dt_Actual_Date ,  
        I_Is_Complete     
               
                        )         
                        SELECT  @ICenterID ,    
                                @DtSelected ,    
                                I_TimeSlot_ID ,    
                                I_Batch_ID ,    
                                I_Room_ID ,    
                                NULL ,    
                                1 ,    
                                @sCrtdBy ,    
                                @DtCrtdOn ,  
                                S_Remarks ,  
                                I_Session_ID ,  
                                I_TermId ,  
                                I_ModuleId ,  
                                S_SessionName ,  
        S_SessionTopic ,  
        null ,  
        0  
                                  
                        FROM    #tempTimeTable    
                          
         
                INSERT  INTO dbo.T_TimeTable_Faculty_Map    
                        ( I_TimeTable_ID ,    
                          I_Employee_ID,
                          B_Is_Actual     
                        )    
                        SELECT  I_TimeTable_ID ,    
                                I_Employee_ID,
                                0    
                        FROM    ( SELECT    I_Employee_ID ,    
                                            TTTM.I_Center_ID ,    
                                            TTTM.Dt_Schedule_Date ,    
                                            TTTM.I_Batch_ID ,    
                                            TTTM.I_Room_ID  
                                  FROM      dbo.T_TimeTable_Faculty_Map AS TTTFM    
                                            INNER JOIN dbo.T_TimeTable_Master    
                                            AS TTTM ON TTTFM.I_TimeTable_ID = TTTM.I_TimeTable_ID    
                                  WHERE     I_TimeSlot_ID = @ISrcTimeSlotID    
                                            AND I_Center_ID = @ICenterID    
                                            AND Dt_Schedule_Date = @DtSelected    
                                            AND TTTM.I_Status = 1    
                                ) T1    
                                INNER JOIN ( SELECT TTTM.I_TimeTable_ID ,    
                                                    TTTM.I_Center_ID ,    
                                                    TTTM.Dt_Schedule_Date ,    
                                                    TTTM.I_Batch_ID ,    
                                                    TTTM.I_Room_ID    
                                             FROM   dbo.T_TimeTable_Master AS TTTM    
                                             WHERE    
             I_TimeSlot_ID IN (  SELECT  I_TimeSlot_ID FROM #tempTimeTable )  
                                                    AND I_Center_ID = @ICenterID    
                                                    AND Dt_Schedule_Date = @DtSelected    
                                                    AND TTTM.I_Status = 1    
                                           ) T2 ON T1.I_Center_ID = T2.I_Center_ID    
                                                   AND T1.Dt_Schedule_Date = T2.Dt_Schedule_Date    
                                                   AND T1.I_Batch_ID = T2.I_Batch_ID    
                                                   AND T1.I_Room_ID = T2.I_Room_ID  
            END      
        ELSE     
            BEGIN      
                RAISERROR('No classes are scheduled on this time slot for this date.',11,1)        
            END            
            COMMIT TRANSACTION T1        
    END TRY                        
    BEGIN CATCH                        
 --Error occurred:                          
        ROLLBACK TRANSACTION T1                       
        DECLARE @ErrMsg NVARCHAR(4000) ,    
            @ErrSeverity INT                        
        SELECT  @ErrMsg = ERROR_MESSAGE() ,    
                @ErrSeverity = ERROR_SEVERITY()                        
                        
        RAISERROR(@ErrMsg, @ErrSeverity, 1)                        
    END CATCH
GO
PRINT N'Creating Procedure [dbo].[uspCopyTimeTableForWeek]...';


GO
CREATE PROCEDURE [dbo].[uspCopyTimeTableForWeek]     
    (      
      @ICenterID INT ,      
      @SCopyTimeTableForDateXML XML = NULL ,            
      @sCrtdBy VARCHAR(20) ,        
      @DtCrtdOn DATETIME               
    )      
AS       
    BEGIN TRY                              
        BEGIN TRANSACTION T1      
    print '#1'          
        -- Create Temporary Table To TimeTable source Information                  
        CREATE TABLE #tempTimeTable      
            (      
     I_TimeSlot_ID int ,      
     I_Batch_ID int ,      
     I_Room_ID int ,      
     S_Remarks varchar(500) ,      
     I_Session_ID int ,      
     Dt_DestDate DATETIME ,  
     DtSelected DATETIME ,     
     S_SessionName VARCHAR(500) ,      
     S_SessionTopic VARCHAR(500) ,      
     I_ModuleId INT ,      
     I_TermId INT      
            )        
         
   -- Insert Values into Temporary Table                  
        INSERT  INTO #tempTimeTable      
                SELECT  T.c.value('@I_TimeSlot_ID', 'int') ,      
      T.c.value('@I_Batch_ID', 'int') ,      
                        T.c.value('@I_Room_ID', 'int') ,                             
                        CASE WHEN T.c.value('@S_Remarks','varchar(500)') = '' THEN NULL ELSE T.c.value('@S_Remarks','varchar(500)') END,      
                        T.c.value('@I_Session_ID', 'int'),      
                        T.c.value('@Dt_DestDate', 'DATETIME') , 
                        T.c.value('@DtSelected', 'DATETIME') ,     
                        T.c.value('@S_SessionName', 'VARCHAR(500)') ,      
                        CASE WHEN T.c.value('@S_SessionTopic', 'varchar(500)') = '' THEN NULL ELSE T.c.value('@S_SessionTopic', 'varchar(500)') END,      
                        T.c.value('@I_ModuleId', 'INT') ,                              
                        T.c.value('@I_TermId', 'INT')                               
                FROM    @SCopyTimeTableForDateXML.nodes('/Root/MonthWiseCopy') T ( c )      
        print '#2'              
        IF ( SELECT COUNT(*)      
             FROM   T_TimeTable_Master      
             WHERE I_Center_ID = @ICenterID      
                    AND Dt_Schedule_Date IN (SELECT  DtSelected FROM #tempTimeTable )   
                    AND I_Status = 1      
           ) > 0       
            BEGIN              
                  print '#3'  
                        DELETE  FROM dbo.T_TimeTable_Faculty_Map      
                        WHERE   I_TimeTable_ID IN (      
                                SELECT  I_TimeTable_ID      
                                FROM    dbo.T_TimeTable_Master AS TTTM      
                                WHERE   Dt_Schedule_Date IN (SELECT  Dt_DestDate FROM #tempTimeTable )      
                                        AND I_Center_ID = @ICenterID )          
             
                        UPDATE  dbo.T_TimeTable_Master      
                        SET     I_Status = 0 ,      
                                S_Updt_By = @sCrtdBy ,      
                                Dt_Updt_On = @DtCrtdOn      
                        WHERE   Dt_Schedule_Date IN (SELECT  Dt_DestDate FROM #tempTimeTable )      
                                AND I_Center_ID = @ICenterID      
                              
                        INSERT  INTO dbo.T_TimeTable_Master      
                                ( I_Center_ID ,      
                                  Dt_Schedule_Date ,      
                                  I_TimeSlot_ID ,      
                                  I_Batch_ID ,      
                                  I_Room_ID ,      
                                  I_Skill_ID ,      
                                  I_Status ,      
                                  S_Crtd_By ,      
                                  Dt_Crtd_On ,      
                                  S_Remarks ,      
                                  I_Session_ID ,      
                                  I_Term_ID ,       
								  I_Module_ID ,      
								  S_Session_Name ,      
								  S_Session_Topic ,      
								  Dt_Actual_Date ,      
								  I_Is_Complete            
                     
                                )      
                                SELECT  @ICenterID ,      
                                        Dt_DestDate ,      
                                    I_TimeSlot_ID ,      
                                        I_Batch_ID ,      
                                        I_Room_ID ,      
                                        NULL ,      
                                        1 ,      
                                        @sCrtdBy ,      
                                        @DtCrtdOn ,      
                                        S_Remarks ,      
                                        I_Session_ID ,      
                                        I_TermId ,      
										I_ModuleId ,      
										S_SessionName ,      
										S_SessionTopic ,      
										null ,      
										0      
                                FROM    #tempTimeTable           
             print '#4'  
                        INSERT  INTO dbo.T_TimeTable_Faculty_Map      
                                ( I_TimeTable_ID ,      
                                  I_Employee_ID,    
                                  B_Is_Actual           
                                )      
                                SELECT distinct I_TimeTable_ID ,      
                                        I_Employee_ID,    
                                        0      
                                FROM    ( SELECT    I_Employee_ID ,      
                                                    TTTM.I_Center_ID ,      
                                                    TTTM.I_Batch_ID ,      
                                                    TTTM.I_Room_ID ,                                                          
                                                    TTTM.I_TimeSlot_ID      
                                          FROM      dbo.T_TimeTable_Faculty_Map      
                                                    AS TTTFM      
                                                    INNER JOIN dbo.T_TimeTable_Master      
                                                    AS TTTM ON TTTFM.I_TimeTable_ID = TTTM.I_TimeTable_ID      
                                          WHERE     I_Center_ID = @ICenterID      
                                                    AND Dt_Schedule_Date IN (SELECT distinct DtSelected FROM #tempTimeTable )      
                                                    AND TTTM.I_Status = 1     
                                                    --added by sudipta  
                                                    AND TTTFM.B_Is_Actual=0   
                                                      
                                                    -- end adition  
										) T1      
                                        INNER JOIN ( SELECT TTTM.I_TimeTable_ID ,      
                                                            TTTM.I_Center_ID ,      
                                                            TTTM.I_TimeSlot_ID ,      
                                                            TTTM.I_Batch_ID ,      
                                                            TTTM.I_Room_ID                                                                   
                                                     FROM   dbo.T_TimeTable_Master      
                                                            AS TTTM      
                                                     WHERE  Dt_Schedule_Date IN ( SELECT distinct Dt_DestDate FROM #tempTimeTable )      
                                                            AND I_Center_ID = @ICenterID      
                                                            AND TTTM.I_Status = 1      
                                                   ) T2 ON T1.I_Center_ID = T2.I_Center_ID      
                                                           AND T1.I_Batch_ID = T2.I_Batch_ID      
                                                           AND T1.I_Room_ID = T2.I_Room_ID                                                  
                                                           AND T1.I_TimeSlot_ID = T2.I_TimeSlot_ID      
                                                               
               print '#5'                 
            END            
        ELSE       
            BEGIN            
                RAISERROR('No classes are scheduled for the selected date.',11,1)              
            END                  
                        
        COMMIT TRANSACTION T1                
    END TRY                              
    BEGIN CATCH                              
 --Error occurred:                                
        ROLLBACK TRANSACTION T1                             
        DECLARE @ErrMsg NVARCHAR(4000) ,      
            @ErrSeverity INT                              
        SELECT  @ErrMsg = ERROR_MESSAGE() ,      
                @ErrSeverity = ERROR_SEVERITY()                              
                              
        RAISERROR(@ErrMsg, @ErrSeverity, 1)                              
    END CATCH
GO
PRINT N'Creating Procedure [dbo].[uspCourseExistATDC]...';


GO
CREATE PROCEDURE [dbo].[uspCourseExistATDC]  
(           
  @iDestinationCenterId INT          
 ,@sCourseList VARCHAR(max)        
          
)          
AS          
BEGIN        
        
DECLARE @iDCCourseCount INT        
DECLARE @iOCCourseCount INT        
        
--set @sCourseList =         
--'         
--<COURSE>         
--  <COURSEIDTABLE>         
--    <I_Course_Id>1</I_Course_Id>          
-- <I_Course_Id>20</I_Course_Id>         
--  </COURSEIDTABLE>         
--</COURSE>         
--'        
declare @hDoc int         
exec sp_xml_preparedocument @hDoc OUTPUT,@sCourseList        
        
SELECT @iOCCourseCount = COUNT(I_Course_Id)        
FROM OPENXML (@hDoc,'/COURSE/COURSEIDTABLE',2)         
WITH ( I_Course_Id INT )        
        
SELECT @iDCCourseCount = COUNT(DISTINCT(tsbm.I_Course_Id))  
FROM [dbo].[T_Center_Batch_Details] AS tcbd  
INNER JOIN [dbo].[T_Student_Batch_Master] AS tsbm  
ON tcbd.[I_Batch_ID] = tsbm.[I_Batch_ID]  
LEFT OUTER JOIN [dbo].[T_Student_Batch_Details] AS tsbd  
ON tsbm.[I_Batch_ID] = tsbd.[I_Batch_ID]  
WHERE tcbd.I_Centre_Id = @iDestinationCenterId        
AND tsbm.I_Course_Id in        
(        
 SELECT I_Course_Id        
 FROM OPENXML (@hDoc,'/COURSE/COURSEIDTABLE',2)         
 WITH ( I_Course_Id INT )        
)      
AND GETDATE() >= ISNULL(tsbd.Dt_Valid_From, GETDATE())      
AND GETDATE() <= ISNULL(tsbd.Dt_Valid_To, GETDATE())      
AND (tsbd.I_Status <> 0 OR  tsbd.I_Status IS NULL)  
        
IF ( @iOCCourseCount = @iDCCourseCount )        
BEGIN        
 SELECT 'TRUE'        
END        
ELSE        
BEGIN        
 SELECT 'FALSE'        
END        
        
END
GO
PRINT N'Creating Procedure [dbo].[uspCreateAdjustmentReceipts]...';


GO
CREATE PROCEDURE [dbo].[uspCreateAdjustmentReceipts]
    (
      @iPositiveAdjustmentCenterID INT ,
      @iNegativeAdjustmentCenterID INT ,
      @nAmount DECIMAL(18, 2) ,
      @iEnquiryRegnID INT ,
      @iReceiptTypeID INT ,
      @sAdjustmentText VARCHAR(500),
      @iBrandID INT
    )
AS 
    BEGIN  
        DECLARE @CompanyShare NUMERIC(8, 4)  
        DECLARE @TaxShare NUMERIC(18, 2)  
        DECLARE @bUseCenterServiceTax BIT  
    
        DECLARE @nTaxRate DECIMAL(18, 2)  
  
        SELECT  @nTaxRate = SUM(ISNULL(N_Tax_Rate, 0))
        FROM    dbo.T_Tax_Country_ReceiptType
        WHERE   I_Receipt_Type = @iReceiptTypeID
                AND I_Status = 1
                AND ISNULL(Dt_Valid_From, GETDATE()) <= GETDATE()
                AND ISNULL(Dt_Valid_To, GETDATE()) >= GETDATE()  
  
        SET @nTaxRate = ISNULL(@nTaxRate, 0)  
  
        DECLARE @nReceiptAmount DECIMAL(18, 2)  
        SET @nReceiptAmount = @nAmount * 100 / ( @nTaxRate + 100 ) ;  
  
--Insert positive receipt   
        SELECT  @CompanyShare = [dbo].fnGetCompanyShareOnAccountReceipts(GETDATE(),
                                                              CM.I_Country_ID,
                                                              CM.I_Centre_Id,
                                                              @iReceiptTypeID,
                                                              BCD.I_Brand_ID)
        FROM    dbo.T_Centre_Master CM
                INNER JOIN dbo.T_Brand_Center_Details BCD ON BCD.I_Centre_Id = CM.I_Centre_Id
                                                             AND BCD.I_Status = 1
        WHERE   CM.I_Centre_ID = @iPositiveAdjustmentCenterID  
   
        SELECT  @bUseCenterServiceTax = ISNULL(CM.I_Is_Center_Serv_Tax_Reqd,
                                               'False')
        FROM    dbo.T_Centre_Master CM WITH ( NOLOCK )
        WHERE   CM.I_Centre_ID = @iPositiveAdjustmentCenterID  
   
        IF ( @bUseCenterServiceTax = 'TRUE' ) 
            BEGIN  
                SET @TaxShare = @CompanyShare  
            END  
        ELSE 
            BEGIN  
                SET @TaxShare = 100  
            END  
  
        INSERT  INTO T_RECEIPT_HEADER
                ( I_Centre_Id ,
                  N_Receipt_Amount ,
                  Dt_Receipt_Date ,
                  I_PaymentMode_ID ,
                  I_Enquiry_Regn_ID ,
                  S_Crtd_By ,
                  Dt_Crtd_On ,
                  I_Status ,
                  S_Fund_Transfer_Status ,
                  I_Receipt_Type ,
                  N_Tax_Amount ,
                  N_Amount_Rff ,
                  N_Receipt_Tax_Rff ,
                  S_AdjustmentRemarks
                )
        VALUES  ( @iPositiveAdjustmentCenterID ,
                  @nReceiptAmount ,
                  GETDATE() ,
                  1 ,--Hardcoded cash  
                  @iEnquiryRegnID ,
                  'system' ,
                  GETDATE() ,
                  1 ,
                  'N' ,
                  @iReceiptTypeID ,
                  @nAmount - @nReceiptAmount ,
                  @nReceiptAmount * @CompanyShare / 100 ,
                  @CompanyShare * ( @nAmount - @nReceiptAmount ) / 100 ,
                  @sAdjustmentText
                )  
   
        DECLARE @iReceiptIDnew INT  
        SET @iReceiptIDnew = SCOPE_IDENTITY()  
  
        DECLARE @iReceiptNo BIGINT  
  
        SELECT  @iReceiptNo = MAX(CAST(S_Receipt_No AS BIGINT))
        FROM    T_RECEIPT_HEADER TRH
        WHERE   S_Receipt_No NOT LIKE '%[A-Z]'  
		AND TRH.I_Centre_Id IN (SELECT I_Centre_Id FROM dbo.T_Brand_Center_Details AS TBCD WHERE I_Brand_ID = @iBrandID AND I_Status = 1)        
  
        SET @iReceiptNo = ISNULL(@iReceiptNo, 0) + 1  
  
        UPDATE  T_RECEIPT_HEADER
        SET     S_Receipt_No = @iReceiptNo
        WHERE   I_Receipt_Header_ID = @iReceiptIDnew  
  
        INSERT  INTO dbo.T_OnAccount_Receipt_Tax
                SELECT  @iReceiptIDnew ,
                        I_Tax_ID ,
                        @nReceiptAmount * N_Tax_Rate / 100 ,
                        ( @nReceiptAmount * N_Tax_Rate / 100 ) * @TaxShare
                        / 100
                FROM    dbo.T_Tax_Country_ReceiptType
                WHERE   I_Receipt_Type = @iReceiptTypeID
                        AND I_Status = 1
                        AND ISNULL(Dt_Valid_From, GETDATE()) <= GETDATE()
                        AND ISNULL(Dt_Valid_To, GETDATE()) >= GETDATE()  
  
--Insert negative receipt   
        SELECT  @CompanyShare = [dbo].fnGetCompanyShareOnAccountReceipts(GETDATE(),
                                                              CM.I_Country_ID,
                                                              CM.I_Centre_Id,
                                                              @iReceiptTypeID,
                                                              BCD.I_Brand_ID)
        FROM    dbo.T_Centre_Master CM
                INNER JOIN dbo.T_Brand_Center_Details BCD ON BCD.I_Centre_Id = CM.I_Centre_Id
                                                             AND BCD.I_Status = 1
        WHERE   CM.I_Centre_ID = @iNegativeAdjustmentCenterID  
   
        SELECT  @bUseCenterServiceTax = ISNULL(CM.I_Is_Center_Serv_Tax_Reqd,
                                               'False')
        FROM    dbo.T_Centre_Master CM WITH ( NOLOCK )
        WHERE   CM.I_Centre_ID = @iNegativeAdjustmentCenterID  
   
        IF ( @bUseCenterServiceTax = 'TRUE' ) 
            BEGIN  
                SET @TaxShare = @CompanyShare  
            END  
        ELSE 
            BEGIN  
                SET @TaxShare = 100  
            END  
  
        INSERT  INTO T_RECEIPT_HEADER
                ( I_Centre_Id ,
                  N_Receipt_Amount ,
                  Dt_Receipt_Date ,
                  I_PaymentMode_ID ,
                  I_Enquiry_Regn_ID ,
                  S_Crtd_By ,
                  Dt_Crtd_On ,
                  I_Status ,
                  S_Fund_Transfer_Status ,
                  I_Receipt_Type ,
                  N_Tax_Amount ,
                  N_Amount_Rff ,
                  N_Receipt_Tax_Rff ,
                  S_AdjustmentRemarks
                )
        VALUES  ( @iNegativeAdjustmentCenterID ,
                  ( -1 ) * @nReceiptAmount ,
                  GETDATE() ,
                  1 ,--Hardcoded cash  
                  @iEnquiryRegnID ,
                  'system' ,
                  GETDATE() ,
                  1 ,
                  'N' ,
                  @iReceiptTypeID ,
                  ( -1 ) * ( @nAmount - @nReceiptAmount ) ,
                  ( -1 ) * ( @nReceiptAmount * @CompanyShare / 100 ) ,
                  ( -1 ) * ( @CompanyShare * ( @nAmount - @nReceiptAmount )
                             / 100 ) ,
                  @sAdjustmentText
                )  
   
        SET @iReceiptIDnew = SCOPE_IDENTITY()  
  
        SELECT  @iReceiptNo = MAX(CAST(S_Receipt_No AS BIGINT))
        FROM    T_RECEIPT_HEADER TRH
        WHERE   S_Receipt_No NOT LIKE '%[A-Z]'
        AND TRH.I_Centre_Id IN (SELECT I_Centre_Id FROM dbo.T_Brand_Center_Details AS TBCD WHERE I_Brand_ID = @iBrandID AND I_Status = 1)  
  
        SET @iReceiptNo = ISNULL(@iReceiptNo, 0) + 1  
  
        UPDATE  T_RECEIPT_HEADER
        SET     S_Receipt_No = @iReceiptNo
        WHERE   I_Receipt_Header_ID = @iReceiptIDnew  
  
        INSERT  INTO dbo.T_OnAccount_Receipt_Tax
                SELECT  @iReceiptIDnew ,
                        I_Tax_ID ,
                        ( -1 ) * ( @nReceiptAmount * N_Tax_Rate / 100 ) ,
                        ( -1 ) * ( ( @nReceiptAmount * N_Tax_Rate / 100 )
                                   * @TaxShare / 100 )
                FROM    dbo.T_Tax_Country_ReceiptType
                WHERE   I_Receipt_Type = @iReceiptTypeID
                        AND I_Status = 1
                        AND ISNULL(Dt_Valid_From, GETDATE()) <= GETDATE()
                        AND ISNULL(Dt_Valid_To, GETDATE()) >= GETDATE()  
  
   
  
    END
GO
