CREATE PROCEDURE dbo.uspDemoteStudents ( @studentdetID INT )
AS 
    BEGIN


        CREATE TABLE #temp
            (
              studentbatchid INT ,
              studentid INT ,
              istatus INT
            )

        INSERT  INTO #temp
                ( studentbatchid ,
                  studentid ,
                  istatus 
                )
                SELECT TOP 2
                        I_Student_Batch_ID ,
                        I_Student_ID ,
                        TSBD.I_Status AS Sts
                FROM    dbo.T_Student_Batch_Details TSBD
                WHERE   I_Student_ID = @studentdetID
                ORDER BY I_Student_Batch_ID DESC


        IF ( ( ( SELECT TOP 1
                        istatus
                 FROM   #temp
                 WHERE  studentid = @studentdetID
               ) <> 1 )
             AND ( ( SELECT TOP 1
                            istatus
                     FROM   #temp
                     WHERE  studentid = @studentdetID
                   ) <> 2 )
           ) 
            BEGIN
                UPDATE  TT
                SET     TT.I_Status = 1
                FROM    dbo.T_Student_Batch_Details TT
                        INNER JOIN #temp T ON T.studentbatchid = TT.I_Student_Batch_ID
                                              AND T.studentid = TT.I_Student_ID
                WHERE   T.istatus = 2
	
                UPDATE  TT
                SET     TT.I_Status = 0
                FROM    dbo.T_Student_Batch_Details TT
                        INNER JOIN #temp T ON T.studentbatchid = TT.I_Student_Batch_ID
                                              AND T.studentid = TT.I_Student_ID
                WHERE   T.istatus = 3
	
            END

    END
GO
PRINT N'Creating Procedure [dbo].[uspDemoteStudentsToBatch]...';


GO
CREATE PROCEDURE [dbo].[uspDemoteStudentsToBatch]  
-- Add the parameters for the stored procedure here  
    @iTobatchId INT ,  
    @iFrombatchId INT ,  
    @istudentIdsStr varchar(500)  
AS   
    BEGIN TRY  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
 -- 2 stands for promoted out / 3 stands for promoted in  
        SET NOCOUNT ON  
   
        IF EXISTS (SELECT  *  
                    FROM    dbo.T_Student_Batch_Details  
                    WHERE   I_Batch_ID = @iFrombatchId  
                            AND I_Student_ID IN ( SELECT  Val  
        FROM    fnString2Rows(@istudentIdsStr, ','))  
                            AND I_Status = 3 AND I_FromBatch_ID=@iTobatchId )   
            BEGIN  
                UPDATE  dbo.T_Student_Batch_Details  
                SET     I_Status = 0,I_FromBatch_ID=NULL 
                WHERE   I_Batch_ID = @iFrombatchId  
                        AND I_Student_ID IN (SELECT  Val  
       FROM    fnString2Rows(@istudentIdsStr, ','))  
                        AND I_Status = 3 
                        
       END                  
   
    IF EXISTS (SELECT  *  
                    FROM    dbo.T_Student_Batch_Details  
                    WHERE   I_Batch_ID = @iTobatchId  
                            AND I_Student_ID IN ( SELECT  Val  
        FROM    fnString2Rows(@istudentIdsStr, ','))  
                            AND I_Status = 2 AND I_ToBatch_ID=@iFrombatchId )  
   BEGIN 
   
            UPDATE  dbo.T_Student_Batch_Details  
                SET     I_Status = 1,I_ToBatch_ID=NULL 
                WHERE   I_Batch_ID = @iTobatchId  
                        AND I_Student_ID IN (SELECT  Val  
       FROM    fnString2Rows(@istudentIdsStr, ','))  
                        AND I_Status = 2  
   END
   ELSE
   RAISERROR('Wrong Destination Batch',11,1)
    END TRY  
    BEGIN CATCH  
 --Error occurred:    
  
        DECLARE @ErrMsg NVARCHAR(4000) ,  
            @ErrSeverity INT  
        SELECT  @ErrMsg = ERROR_MESSAGE() ,  
                @ErrSeverity = ERROR_SEVERITY()  
  
        RAISERROR(@ErrMsg, @ErrSeverity, 1)  
    END CATCH
GO
