CREATE PROCEDURE [dbo].[uspGetAllSchoolGroup]
(
@iBrandId INT = NULL
)
AS
BEGIN
SELECT  [I_School_Group_ID] GroupID
      ,[I_Brand_Id] BrandId
      ,[S_School_Group_Code] SchoolGroupCode
      ,[S_School_Group_Name] SchoolGroupName
      ,[I_Status]
    
