CREATE PROCEDURE [dbo].[uspGetCompanyUsers] 
	
AS
BEGIN

	SET NOCOUNT ON;
	
	select U.I_User_ID,U.S_Login_ID,U.S_Password,U.S_Title,U.S_First_Name,
	U.S_Middle_Name,U.S_Last_Name,U.S_Email_ID,U.S_User_Type,U.I_Status,
