GO
CREATE PROC [dbo].[uspGetCurrencyHistory]
(
@sCurrencyList VARCHAR(50)
)

AS 
BEGIN
DECLARE @iCount INT
DECLARE @iStatus INT

    SELECT @iCount=COUNT(DISTINCT Val) FROM dbo.fnString2Rows(@sCurrencyList,',')


	IF (@iCount > 1)
	BEGIN		 
			SELECT 
            CM.S_Currency_Code [Currency Code],CM.S_Currency_Name [Currency Name],'USD' [Base Currency],
            CR.N_Conversion_Rate [Conversion Rate],
            'Effective Start Date' = CASE 
            WHEN CR.Dt_Effective_Start_Date IS NULL THEN ''
            WHEN ISDATE(CR.Dt_Effective_Start_Date)=1 THEN CAST(CR.Dt_Effective_Start_Date AS VARCHAR(11))
            END,
            'Effective End Date' = CASE 
            WHEN CR.Dt_Effective_End_Date IS NULL THEN ''
            WHEN ISDATE(CR.Dt_Effective_End_Date)=1 THEN CAST(CR.Dt_Effective_End_Date AS VARCHAR(11))
            END,
            'Status' =CASE 
            WHEN CR.I_Status=1 THEN 'Active'
            WHEN CR.I_Status=0 THEN 'Deleted'
            END
            FROM T_Currency_Rate CR
            INNER JOIN  T_Currency_Master CM
            ON CR.I_Currency_ID = CM.I_Currency_ID
			WHERE CR.I_Currency_ID IN (SELECT DISTINCT * FROM dbo.fnString2Rows(@sCurrencyList,','))
			AND CM.I_Status <> 0
			ORDER BY CM.S_Currency_Code
	END
	ELSE
	BEGIN
		IF ((SELECT DISTINCT * FROM dbo.fnString2Rows(@sCurrencyList,','))=0)
		BEGIN
			SELECT 
            CM.S_Currency_Code [Currency Code],CM.S_Currency_Name [Currency Name],'USD' [Base Currency],
            CR.N_Conversion_Rate [Conversion Rate],
            'Effective Start Date' = CASE 
            WHEN CR.Dt_Effective_Start_Date IS NULL THEN ''
            WHEN ISDATE(CR.Dt_Effective_Start_Date)=1 THEN CAST(CR.Dt_Effective_Start_Date AS VARCHAR(11))
            END,
            'Effective End Date' = CASE 
            WHEN CR.Dt_Effective_End_Date IS NULL THEN ''
            WHEN ISDATE(CR.Dt_Effective_End_Date)=1 THEN CAST(CR.Dt_Effective_End_Date AS VARCHAR(11))
            END,
            'Status' =CASE 
            WHEN CR.I_Status=1 THEN 'Active'
            WHEN CR.I_Status=0 THEN 'Deleted'
            END
            FROM T_Currency_Rate CR
            INNER JOIN  T_Currency_Master CM
            ON CR.I_Currency_ID = CM.I_Currency_ID
			WHERE CM.I_Status <> 0
			ORDER BY CM.S_Currency_Code
		END
		
	END
	
END
GO
PRINT N'Creating Procedure [dbo].[uspGetCurrencyRate]...';


GO
CREATE PROCEDURE [dbo].[uspGetCurrencyRate] 

AS
BEGIN

DECLARE @DtCurrentDate DATETIME
SET @DtCurrentDate = CAST(CAST(GETDATE() AS VARCHAR(11)) AS DATETIME)

	SELECT DISTINCT A.I_Currency_Rate_ID, B.S_Currency_Code, B.S_Currency_Name, A.I_Currency_ID, 
    A.Dt_Effective_Start_Date,A.N_Conversion_Rate, A.Dt_Effective_End_Date, A.I_Status,
    A.S_Crtd_By, A.S_Upd_By, A.Dt_Crtd_On, A.Dt_Upd_On
    FROM dbo.T_Currency_Rate A
    INNER JOIN dbo.T_Currency_Master B
    ON A.I_Currency_ID = B.I_Currency_ID
    WHERE A.I_Status <> 0
    AND B.I_Status <> 0
    AND A.Dt_Effective_End_Date IS NULL
    UNION    
    SELECT A.I_Currency_Rate_ID, B.S_Currency_Code, B.S_Currency_Name, A.I_Currency_ID, 
    A.Dt_Effective_Start_Date,A.N_Conversion_Rate, A.Dt_Effective_End_Date, A.I_Status,
    A.S_Crtd_By, A.S_Upd_By, A.Dt_Crtd_On, A.Dt_Upd_On
    FROM dbo.T_Currency_Rate A
    INNER JOIN dbo.T_Currency_Master B
    ON A.I_Currency_ID = B.I_Currency_ID
    WHERE A.I_Status <> 0
    AND B.I_Status <> 0    
    AND @DtCurrentDate >= A.Dt_Effective_Start_Date
    AND @DtCurrentDate <= A.Dt_Effective_End_Date
    AND A.Dt_Effective_End_Date IS NOT NULL 
    ORDER BY A.I_Currency_ID

END
GO
