  ON TECM.I_Exam_Component_ID = T.I_Exam_Component_ID    
  AND TECM.I_Status = 1    
  LEFT JOIN dbo.T_Exam_Type_Master ETM WITH(NOLOCK)    
  ON TECM.I_Exam_Type_Master_ID = ETM.I_Exam_Type_Master_ID    
