PRINT N'Creating Procedure [dbo].[uspGetFeePlanDetails]...';


GO
CREATE PROCEDURE [dbo].[uspGetFeePlanDetails] ( @iFeePlanID INT )
AS 
    BEGIN      
        SET NOCOUNT ON      
       
 -- Fee Plan List      
 -- Table [0]      
        SELECT  I_Course_Fee_Plan_ID ,
                I_Course_ID ,
                I_Course_Delivery_ID ,
                I_Currency_ID ,
                S_Fee_Plan_Name ,
                C_Is_LumpSum ,
                N_TotalLumpSum ,
                N_TotalInstallment ,
                I_Status ,
                Dt_Valid_To
        FROM    dbo.T_Course_Fee_Plan
        WHERE   I_Course_Fee_Plan_ID = @iFeePlanID
                AND I_Status = 1      
       
 -- Fee Component List      
 -- Table [1]      
        SELECT  I_Course_Fee_Plan_Detail_ID ,
                I_Fee_Component_ID ,
                I_Course_Fee_Plan_ID ,
                I_Item_Value ,
                ISNULL(N_CompanyShare, 0) AS N_CompanyShare ,
                I_Installment_No ,
                I_Sequence ,
                C_Is_LumpSum ,
                I_Display_Fee_Component_ID
        FROM    dbo.T_Course_Fee_Plan_Detail
        WHERE   I_Course_Fee_Plan_ID = @iFeePlanID
                AND I_Status = 1
        ORDER BY I_Installment_No,I_Sequence      
      
    END
GO
PRINT N'Creating Procedure [dbo].[uspGetFeePlanDetailsForOldInvoice]...';


GO
CREATE PROCEDURE [dbo].[uspGetFeePlanDetailsForOldInvoice] --uspGetFeePlanDetailsForOldInvoice 168864, 37602
( 
	@iOldInvoiceHeaderID INT,
	@iFeePlanID INT 
)
AS 
BEGIN      
    SET NOCOUNT ON    
    
    CREATE TABLE #CFPD
    (
		I_Course_Fee_Plan_Detail_ID int
	   ,I_Fee_Component_ID int
       ,I_Course_Fee_Plan_ID int
       ,I_Item_Value numeric(18,2)
       ,N_CompanyShare numeric(18,2)
       ,I_Sequence int
       ,I_Installment_No int
       ,C_Is_LumpSum char(1)
       ,I_Display_Fee_Component_ID int
    ) 
    
    CREATE TABLE #CFPDR
    (
		ID INT IDENTITY(1,1)
	   ,I_Course_Fee_Plan_Detail_ID int
	   ,I_Fee_Component_ID int
       ,I_Course_Fee_Plan_ID int
       ,I_Item_Value numeric(18,2)
       ,N_CompanyShare numeric(18,2)
       ,I_Sequence int
       ,I_Installment_No int
       ,Dt_Installment_Date DATETIME
       ,C_Is_LumpSum char(1)
       ,I_Display_Fee_Component_ID int
    ) 
    
    CREATE TABLE #IWFPD
    (
		ID INT IDENTITY(1,1),
		I_Invoice_Detail_ID int, 
		I_Invoice_Child_Header_ID int, 
		I_Course_Fee_Plan_ID int,
		I_Fee_Component_ID int, 
		I_Installment_No int, 
		Dt_Installment_Date DATETIME, 
		N_Amount_Due numeric(18,2)
    ) 
    
    CREATE TABLE #IWFPI
    (
		ID INT IDENTITY(1,1),
		I_Installment_No int, 
		Dt_Installment_Date DATETIME
    ) 
       
 -- Fee Component List      
 -- Table [1] 
	INSERT INTO #CFPD
	(
		I_Course_Fee_Plan_Detail_ID ,
        I_Fee_Component_ID ,
        I_Course_Fee_Plan_ID ,
        I_Item_Value ,
        N_CompanyShare ,
        I_Installment_No ,
        I_Sequence ,
        C_Is_LumpSum ,
        I_Display_Fee_Component_ID
	)   
    SELECT  I_Course_Fee_Plan_Detail_ID ,
            I_Fee_Component_ID ,
            I_Course_Fee_Plan_ID ,
            I_Item_Value ,
            ISNULL(N_CompanyShare, 0) AS N_CompanyShare ,
            I_Installment_No ,
            I_Sequence ,
            C_Is_LumpSum ,
            I_Display_Fee_Component_ID
    FROM    dbo.T_Course_Fee_Plan_Detail
    WHERE   I_Course_Fee_Plan_ID = @iFeePlanID
            AND I_Status = 1
    ORDER BY I_Installment_No,I_Sequence
    
    INSERT INTO #IWFPD
    (
		I_Invoice_Detail_ID, 
		I_Invoice_Child_Header_ID, 
		I_Course_Fee_Plan_ID,
		I_Fee_Component_ID, 
		I_Installment_No, 
		Dt_Installment_Date, 
		N_Amount_Due
    )     
    SELECT B.I_Invoice_Detail_ID, B.I_Invoice_Child_Header_ID, B.I_Course_FeePlan_ID, B.I_Fee_Component_ID, B.I_Installment_No, B.Dt_Installment_Date, 
    --(ISNULL(B.N_Amount_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)) N_Amount_Due  --Before Discount Akash 5.10.2021
	(ISNULL(B.N_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)) N_Amount_Due
	FROM 
	(SELECT ICD.I_Invoice_Detail_ID, ICD.I_Invoice_Child_Header_ID, ICH.I_Course_FeePlan_ID, 
	ICD.I_Fee_Component_ID, ICD.I_Installment_No, ICD.Dt_Installment_Date, ICD.N_Amount_Due,ICD.N_Due,ICD.N_Discount_Amount
	FROM T_Invoice_Child_Detail ICD 
	INNER JOIN T_Invoice_Child_Header ICH ON ICD.I_Invoice_Child_Header_ID = ICH.I_Invoice_Child_Header_ID
	INNER JOIN T_Invoice_Parent IP ON ICH.I_Invoice_Header_ID = IP.I_Invoice_Header_ID 
	WHERE IP.I_Invoice_Header_ID = @iOldInvoiceHeaderID
	AND ISNULL(ICD.Flag_IsAdvanceTax,'N') <> 'Y') B
	LEFT JOIN 
	(SELECT RCD.I_Invoice_Detail_ID, SUM(ISNULL(RCD.N_Amount_Paid,0)) N_Amount_Paid
	FROM T_Receipt_Header RH
	INNER JOIN T_Receipt_Component_Detail RCD ON RH.I_Receipt_Header_ID = RCD.I_Receipt_Detail_ID
	WHERE RH.I_Invoice_Header_ID = @iOldInvoiceHeaderID
	AND ISNULL(RH.I_Status,0) <> 0
	GROUP BY RCD.I_Invoice_Detail_ID) A	ON B.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
	INNER JOIN T_Invoice_Child_Header ICH1 ON B.I_Invoice_Child_Header_ID = ICH1.I_Invoice_Child_Header_ID
	AND (ISNULL(B.N_Amount_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)) > 0
	ORDER BY B.I_Installment_No
	
	INSERT INTO #IWFPI
    (
		I_Installment_No, 
		Dt_Installment_Date
    ) 
	SELECT DISTINCT I_Installment_No, Dt_Installment_Date
	FROM #IWFPD
	
	IF EXISTS
	(
		SELECT 1 FROM #IWFPI
	)
	BEGIN
	
		DECLARE @row INT = 1
		DECLARE @count INT
		
		DECLARE @I_Invoice_Detail_ID int
		DECLARE @I_Invoice_Child_Header_ID int
		DECLARE @I_Fee_Component_ID int
		DECLARE @I_Installment_No int
		DECLARE @Dt_Installment_Date DATETIME
		DECLARE @N_Amount_Due numeric(18,2)	
		DECLARE @N_Amount_Paid numeric(18,2)
		
		DECLARE @I_Course_Fee_Plan_Detail_ID int
		DECLARE @I_Course_Fee_Plan_ID int
		DECLARE @I_Item_Value numeric(18,2)
		DECLARE @N_CompanyShare numeric(18,2)
		DECLARE @I_Sequence int
		DECLARE @C_Is_LumpSum char(1)
		DECLARE @I_Display_Fee_Component_ID int
		
		SELECT @count = COUNT(*) FROM #IWFPI
		
		WHILE (@row<=@count)
		BEGIN
			SELECT @I_Installment_No = I_Installment_No
				  ,@Dt_Installment_Date = Dt_Installment_Date
			FROM #IWFPI
			WHERE ID = @row
			
			INSERT INTO #CFPDR
			(
				I_Course_Fee_Plan_Detail_ID
			   ,I_Fee_Component_ID
			   ,I_Course_Fee_Plan_ID 
			   ,I_Item_Value
			   ,N_CompanyShare
			   ,I_Sequence
			   ,I_Installment_No
			   ,Dt_Installment_Date
			   ,C_Is_LumpSum
			   ,I_Display_Fee_Component_ID
			)
			SELECT  CF.I_Course_Fee_Plan_Detail_ID
					,CF.I_Fee_Component_ID 
					,CF.I_Course_Fee_Plan_ID
					,ISNULL((SELECT IW.N_Amount_Due FROM #IWFPD IW WHERE IW.I_Course_Fee_Plan_ID = CF.I_Course_Fee_Plan_ID 
											  AND IW.I_Installment_No = CF.I_Installment_No AND IW.I_Fee_Component_ID = CF.I_Fee_Component_ID),0) AS I_Item_Value
					,CF.N_CompanyShare
					,CF.I_Sequence				
					,@I_Installment_No
					,@Dt_Installment_Date
					,CF.C_Is_LumpSum
					,CF.I_Display_Fee_Component_ID
			FROM #CFPD CF
			WHERE I_Installment_No = @I_Installment_No
			
			SET @row = @row + 1
		END
		
		-- Fee Plan List      
		-- Table [0]      
		SELECT  I_Course_Fee_Plan_ID ,
				I_Course_ID ,
				I_Course_Delivery_ID ,
				I_Currency_ID ,
				S_Fee_Plan_Name ,
				C_Is_LumpSum ,
				ISNULL((SELECT SUM(ISNULL(I_Item_Value,0))FROM #CFPDR),0) N_TotalLumpSum ,
				ISNULL((SELECT SUM(ISNULL(I_Item_Value,0))FROM #CFPDR),0) N_TotalInstallment ,
				I_Status ,
				Dt_Valid_To
		FROM    dbo.T_Course_Fee_Plan
		WHERE   I_Course_Fee_Plan_ID = @iFeePlanID
				AND I_Status = 1
	            
		SELECT	0 AS I_Course_Fee_Plan_Detail_ID
				,CF.I_Fee_Component_ID 
				,CF.I_Course_Fee_Plan_ID 
				,A.I_Item_Value 
				,CF.N_CompanyShare
				,CF.I_Sequence  
				,CF.I_Installment_No 			
				,CF.C_Is_LumpSum 
				,CF.I_Display_Fee_Component_ID
		FROM #CFPD CF
		INNER JOIN (SELECT  CFR.I_Fee_Component_ID
						   ,SUM(ISNULL(CFR.I_Item_Value,0)) AS I_Item_Value
					FROM #CFPDR CFR
					GROUP BY CFR.I_Fee_Component_ID) A ON CF.I_Fee_Component_ID = A.I_Fee_Component_ID
		WHERE CF.I_Installment_No = 0 AND CF.C_Is_LumpSum = 'Y'
		UNION ALL
		SELECT 0 AS I_Course_Fee_Plan_Detail_ID
			   ,A.I_Fee_Component_ID
			   ,A.I_Course_Fee_Plan_ID 
			   ,SUM(ISNULL(A.I_Item_Value,0)) AS I_Item_Value
			   ,A.N_CompanyShare
			   ,A.I_Sequence
			   ,A.I_Installment_No
			   ,A.C_Is_LumpSum
			   ,A.I_Display_Fee_Component_ID
		FROM(
		SELECT  I_Fee_Component_ID
			   ,I_Course_Fee_Plan_ID 
			   ,I_Item_Value
			   ,N_CompanyShare
			   ,I_Sequence
			   ,CASE WHEN CONVERT(DATE, GETDATE()) >= CONVERT(DATE, Dt_Installment_Date) THEN 1
					 ELSE I_Installment_No
				END I_Installment_No
			   ,CASE WHEN CONVERT(DATE, GETDATE()) >= CONVERT(DATE, Dt_Installment_Date) THEN DATEADD(d,DATEDIFF(d,0,getdate()),0)
					 ELSE Dt_Installment_Date
				END Dt_Installment_Date
			   ,C_Is_LumpSum
			   ,I_Display_Fee_Component_ID
		FROM #CFPDR) A
		GROUP BY A.I_Installment_No, A.I_Fee_Component_ID, A.N_CompanyShare, A.I_Sequence, A.C_Is_LumpSum, A.I_Display_Fee_Component_ID, A.I_Course_Fee_Plan_ID 
		ORDER BY I_Installment_No ASC
	END
	ELSE
	BEGIN
		-- Fee Plan List      
		-- Table [0]      
		SELECT  I_Course_Fee_Plan_ID ,
				I_Course_ID ,
				I_Course_Delivery_ID ,
				I_Currency_ID ,
				S_Fee_Plan_Name ,
				C_Is_LumpSum ,
				ISNULL((SELECT SUM(ISNULL(I_Item_Value,0))FROM #CFPDR),0) N_TotalLumpSum ,
				ISNULL((SELECT SUM(ISNULL(I_Item_Value,0))FROM #CFPDR),0) N_TotalInstallment ,
				I_Status ,
				Dt_Valid_To
		FROM    dbo.T_Course_Fee_Plan
		WHERE   I_Course_Fee_Plan_ID = @iFeePlanID
				AND I_Status = 1
				
		SELECT * FROM #CFPD
	END
		
	DROP TABLE #CFPD
	DROP TABLE #IWFPD
	DROP TABLE #CFPDR
	DROP TABLE #IWFPI
END
GO
PRINT N'Creating Procedure [dbo].[uspGetFeePlanDetailsOtherForOldInvoice]...';


GO
Create PROCEDURE [dbo].[uspGetFeePlanDetailsOtherForOldInvoice] --uspGetFeePlanDetailsOtherForOldInvoice 150978
( 
	@iOldInvoiceHeaderID INT
)
AS 
BEGIN      
    SET NOCOUNT ON    
    
    CREATE TABLE #IWFPD
    (
		ID INT IDENTITY(1,1),
		I_Invoice_Detail_ID int, 
		I_Invoice_Child_Header_ID int, 
		I_Course_Fee_Plan_ID int,
		I_Fee_Component_ID int, 
		I_Installment_No int, 
		Dt_Installment_Date DATETIME, 
		N_Amount_Due numeric(18,0)
    ) 
    
    INSERT INTO #IWFPD
    (
		I_Invoice_Detail_ID, 
		I_Invoice_Child_Header_ID, 
		I_Course_Fee_Plan_ID,
		I_Fee_Component_ID, 
		I_Installment_No, 
		Dt_Installment_Date, 
		N_Amount_Due
    )     
    SELECT B.I_Invoice_Detail_ID, B.I_Invoice_Child_Header_ID, B.I_Course_FeePlan_ID, B.I_Fee_Component_ID, B.I_Installment_No, B.Dt_Installment_Date, 
    (ISNULL(B.N_Amount_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)) N_Amount_Due
	FROM (SELECT ICD.I_Invoice_Detail_ID, ICD.I_Invoice_Child_Header_ID, ICH.I_Course_FeePlan_ID, ICD.I_Fee_Component_ID, ICD.I_Installment_No, ICD.Dt_Installment_Date, ICD.N_Amount_Due
	FROM T_Invoice_Child_Detail ICD 
	INNER JOIN T_Invoice_Child_Header ICH ON ICD.I_Invoice_Child_Header_ID = ICH.I_Invoice_Child_Header_ID
	INNER JOIN T_Invoice_Parent IP ON ICH.I_Invoice_Header_ID = IP.I_Invoice_Header_ID 
	WHERE IP.I_Invoice_Header_ID = @iOldInvoiceHeaderID
	AND ISNULL(ICD.Flag_IsAdvanceTax,'N') <> 'Y') B
	LEFT JOIN 
	(SELECT RCD.I_Invoice_Detail_ID, SUM(ISNULL(RCD.N_Amount_Paid,0)) N_Amount_Paid
	FROM T_Receipt_Header RH
	INNER JOIN T_Receipt_Component_Detail RCD ON RH.I_Receipt_Header_ID = RCD.I_Receipt_Detail_ID
	WHERE RH.I_Invoice_Header_ID = @iOldInvoiceHeaderID
	AND ISNULL(RH.I_Status,0) <> 0
	GROUP BY RCD.I_Invoice_Detail_ID) A	ON B.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
	INNER JOIN T_Invoice_Child_Header ICH1 ON B.I_Invoice_Child_Header_ID = ICH1.I_Invoice_Child_Header_ID
	WHERE ISNULL(ICH1.I_Course_FeePlan_ID,0) = 0
	AND (ISNULL(B.N_Amount_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)) > 0
	ORDER BY B.I_Installment_No
	
	SELECT 0 AS I_Invoice_Detail_ID
		   ,A.I_Fee_Component_ID
		   ,A.I_Installment_No
		   ,A.Dt_Installment_Date
		   ,SUM(ISNULL(A.N_Amount_Due,0)) AS N_Amount_Due
		   ,0 N_Amount_Paid
	FROM (SELECT I_Fee_Component_ID
		   ,CASE WHEN CONVERT(DATE, GETDATE()) >= CONVERT(DATE, Dt_Installment_Date) THEN 1
				 ELSE I_Installment_No
			END I_Installment_No
		   ,CASE WHEN CONVERT(DATE, GETDATE()) >= CONVERT(DATE, Dt_Installment_Date) THEN DATEADD(d,DATEDIFF(d,0,getdate()),0)
				 ELSE Dt_Installment_Date
			END Dt_Installment_Date
		   ,N_Amount_Due
	FROM #IWFPD) A
	GROUP BY A.I_Fee_Component_ID,A.I_Installment_No,A.Dt_Installment_Date
	ORDER BY A.I_Installment_No ASC
	
	DROP TABLE #IWFPD
END
GO
PRINT N'Creating Procedure [dbo].[uspGetFeePlanDiscountDetails]...';


GO
CREATE procedure [dbo].[uspGetFeePlanDiscountDetails]
(
@feeplanid int,
@paymentmode int,
@discountschemeid int,
@batchstartdate datetime=NULL
)
AS
BEGIN

	declare @discountperc decimal(14,2)=0
	declare @discountamount decimal(14,2)=0
	declare @sfromInstalment varchar(2)
	declare @ifromInstalment int=0
	declare @dincrement INT=1
	declare @dcount INT=0
	declare @i int=0
	declare @c int=0
	declare @instalmentstartdate Datetime

	--IF(@batchstartdate IS NULL)
	--	set @batchstartdate=GETDATE()

	--if(@batchstartdate>=CONVERT(DATE,GETDATE()))
	--	set @instalmentstartdate=@batchstartdate
	--else
	--	set @instalmentstartdate=CONVERT(DATE,GETDATE())


	DECLARE @TblFeePlan TABLE
		(
			ID INT IDENTITY(1,1),
			I_Course_Fee_Plan_Detail_ID INT ,
			I_Fee_Component_ID INT,
			I_Course_Fee_Plan_ID INT,
			I_Item_Value Decimal(14,2),
			N_Discount decimal(14,2),
			I_Installment_No INT,
			I_Sequence INT,
			C_Is_LumpSum varchar(1),
			I_Display_Fee_Component_ID INT,
			InstalmentDate Datetime,
			ActualInstalmentNo INT
		)

	DECLARE @TblFeePlanDtl TABLE
	(
	ID INT IDENTITY(1,1),
	DiscountDetailID INT,
	DiscountSchemeID INT,
	DiscountRate Decimal(14,2),
	DiscountAmount decimal(14,2),
	IsApplicableOn INT,
	sFormInstalment Varchar(2),
	sFeeComponent varchar(max)
	)

	DECLARE @TblFeePlanTaxDtl TABLE
	(
	I_Course_Fee_Plan_Detail_ID INT,
	TaxID INT,
	TaxAmount DECIMAL(14,2)
	)


	Insert into @TblFeePlan
	(
		I_Course_Fee_Plan_Detail_ID,
		I_Fee_Component_ID,
		I_Course_Fee_Plan_ID,
		I_Item_Value,
		N_Discount,
		I_Installment_No,
		I_Sequence,
		C_Is_LumpSum,
		I_Display_Fee_Component_ID
	)
	SELECT  I_Course_Fee_Plan_Detail_ID ,
			I_Fee_Component_ID ,
			I_Course_Fee_Plan_ID ,
			I_Item_Value ,
			ISNULL(N_CompanyShare, 0) AS N_CompanyShare ,
			I_Installment_No ,
			I_Sequence ,
			C_Is_LumpSum ,
			I_Display_Fee_Component_ID
	FROM    dbo.T_Course_Fee_Plan_Detail
	WHERE   I_Course_Fee_Plan_ID = @feeplanid
			AND I_Status = 1
	ORDER BY I_Installment_No,I_Sequence

	insert into @TblFeePlanDtl
	select * from T_Discount_Scheme_Details where I_Discount_Scheme_ID=@discountschemeid and I_IsApplicableOn=@paymentmode

	select @dcount=COUNT(*) from @TblFeePlanDtl

	while(@dincrement<=@dcount)
	begin

		declare @sFeeComponent varchar(max)=''

		declare @tblFeeComponent TABLE
		(
			FeeComponentID INT
		)

		select @discountperc=ISNULL(DiscountRate,0),@discountamount=ISNULL(DiscountAmount,0),@sfromInstalment=ISNULL(sFormInstalment,'F'),
				@sFeeComponent=ISNULL(sFeeComponent,'')
		from 
		@TblFeePlanDtl 
		where 
		DiscountSchemeID=@discountschemeid and IsApplicableOn=@paymentmode

		if(@sFeeComponent='')
		begin

			insert into @tblFeeComponent
			select Distinct I_Fee_Component_ID from @TblFeePlan
	
		end
		else
		begin

			insert into @tblFeeComponent
			select CAST(@sFeeComponent as INT)

		end




		IF(@sfromInstalment='F')
			select @ifromInstalment=MIN(I_Installment_No) from @TblFeePlan where C_Is_LumpSum='N'
		ELSE IF(@sfromInstalment='L')
			select @ifromInstalment=MAX(I_Installment_No) from @TblFeePlan where C_Is_LumpSum='N'
		ELSE
			set @ifromInstalment=cast(ISNULL(@sfromInstalment,'0') as INT)

		if(@sFeeComponent='')
		begin

			if(@paymentmode=1)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (N_TotalLumpSum*@discountperc)/100
					FROM    dbo.T_Course_Fee_Plan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							AND I_Status = 1 

				end

				--select @discountamount

			end
			else if(@paymentmode=2)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (N_TotalInstallment*@discountperc)/100
					FROM    dbo.T_Course_Fee_Plan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							AND I_Status = 1 

				end

				--select @discountamount

			end

		end
		else
		begin

			if(@paymentmode=1)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (SUM(I_Item_Value)*@discountperc)/100
					FROM    @TblFeePlan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							and I_Fee_Component_ID in
								(
									select FeeComponentID from @tblFeeComponent
								)
							and C_Is_LumpSum='Y'

				end

				--select @discountamount

			end
			else if(@paymentmode=2)
			begin

				if(@discountamount=0 and @discountperc>0)
				begin

				SELECT @discountamount= (SUM(I_Item_Value)*@discountperc)/100
					FROM    @TblFeePlan
					WHERE   I_Course_Fee_Plan_ID = @feeplanid
							and I_Fee_Component_ID in
								(
									select FeeComponentID from @tblFeeComponent
								)
							and C_Is_LumpSum='N'

				end

				--select @discountamount

			end

		end

		if(@discountamount>0)
		begin

			declare @tempDiscount decimal(14,2)=@discountamount
	

			IF(@sfromInstalment='L')
			Begin

				select @c=1
				select @i=count(*) from @TblFeePlan

				while(@i>=@c)
				begin

					if(@paymentmode=1)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='Y' 
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='Y'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end
					else if(@paymentmode=2)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end

					set @i=@i-1

				end

			end
			else
			Begin
		
				set @i=@ifromInstalment
				select @c=count(*) from @TblFeePlan
	
				while(@i<=@c)
				begin

					if(@paymentmode=1)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='Y'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='Y'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end
					else if(@paymentmode=2)
					begin

						update @TblFeePlan set N_Discount=CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

						select @tempDiscount=@tempDiscount-ISNULL(CASE WHEN I_Item_Value=0 THEN 0
																WHEN I_Item_Value<=@tempDiscount and I_Item_Value>0 THEN I_Item_Value 
																ELSE @tempDiscount END,0)
						from @TblFeePlan 
						where
						ID=@i and C_Is_LumpSum='N'
						and I_Fee_Component_ID in
						(
							select FeeComponentID from @tblFeeComponent
						)

					end

					set @i=@i+1

				end

			end

		

		end

		--drop table #tblFeeComponent

		set @dincrement=@dincrement+1

	end

	insert into @TblFeePlanTaxDtl
	select A.I_Course_Fee_Plan_Detail_ID,B.I_Tax_ID,((A.I_Item_Value-A.N_Discount)*B.N_Tax_Rate)/100 as TaxAmount 
	from @TblFeePlan A
	inner join T_Tax_Country_Fee_Component B on A.I_Fee_Component_ID=B.I_Fee_Component_ID
	where
	B.Dt_Valid_To>=GETDATE() and B.I_Status=1


	DECLARE @dtDate DATETIME=CONVERT(DATE,GETDATE())
	SET @instalmentstartdate=@dtDate


	update @TblFeePlan set InstalmentDate=@dtDate where I_Installment_No=0
	update @TblFeePlan set InstalmentDate=@dtDate where I_Installment_No=1
	--update @TblFeePlan set InstalmentDate=DATEADD(m,I_Installment_No-1,DATEADD(m,datediff(m,0,@batchstartdate),0)) where I_Installment_No>1

	update @TblFeePlan set InstalmentDate=DATEADD(d,30*(I_Installment_No-1),@dtDate) where I_Installment_No>1

	update @TblFeePlan set ActualInstalmentNo=CASE WHEN @instalmentstartdate>=InstalmentDate and I_Installment_No=0 THEN 1 
												   WHEN @instalmentstartdate>=InstalmentDate and I_Installment_No>0 THEN 1 
												   ELSE I_Installment_No END

	update @TblFeePlan set InstalmentDate=CONVERT(DATE,@instalmentstartdate) where ActualInstalmentNo=1



	select * from @TblFeePlan
	select * from @TblFeePlanTaxDtl where TaxAmount>0 order by I_Course_Fee_Plan_Detail_ID,TaxID

	

	--drop table #TblFeePlan
	--drop table #TblFeePlanDtl

END
GO
