CREATE PROCEDURE [dbo].[uspGetPaidAmountArchive] 
(    @iInvoiceDetailID INT,
     @dtReceiptDate datetime    
)    
    
AS    
BEGIN    
    

 SELECT SUM(rcd.N_Amount_Paid)N_Amount_Paid FROM T_Receipt_Component_Detail RCD    
INNER JOIN T_Receipt_Header RH    
