CREATE PROCEDURE [dbo].[uspGetReceiptFromReceiptID]
(
	@iReceiptID int
)

AS
BEGIN
SET TRANSACTION ISOLATION LEVEL READ COMMITTED

SELECT * FROM T_Receipt_Header WITH (NOLOCK)
