SELECT RCD.* FROM T_Receipt_Component_Detail RCD WITH (NOLOCK)
INNER JOIN T_Receipt_Header RH WITH (NOLOCK)
ON RCD.I_Receipt_Detail_ID = RH.I_Receipt_Header_ID
