CREATE PROCEDURE [dbo].[uspGetStudentForMultipleBatch ] -- [dbo].[uspGetStudentForMultipleBatch] '178,'
( 
	@iBatchID VARCHAR(MAX) 
)
AS 
    BEGIN          
       
        SELECT DISTINCT
                STD.S_Student_ID ,
                STD.I_RollNo ,
                STD.S_First_Name ,
                ISNULL(STD.S_Middle_Name, '') AS S_Middle_Name ,
                STD.S_Last_Name ,
