			U.I_Status,
			U.S_Forget_Pwd_Answer,
			U.Dt_Crtd_On,
			H.I_Hierarchy_Master_ID
	FROM dbo.T_User_Master U, dbo.T_User_Hierarchy_Details H 
	WHERE H.I_User_ID = U.I_User_ID
