	SET NOCOUNT OFF

	SELECT  A.I_ZRD_Zone_Region_Detail_ID, A.I_ZRD_Rgn_ID, A.I_ZRD_Country_Zone_Detail_ID,
	B.I_CZD_Brand_Country_Detail_ID, B.I_CZD_Zone_Id,
