--drop PROCEDURE [dbo].[uspImportCourseStructure_changeBySoma]
create PROCEDURE [dbo].[uspImportCourseStructure_FOR_RICE] ( @iBrandID INT )
AS 
    BEGIN
        DECLARE @Course NVARCHAR(MAX) ,
            @CourseID INT ,
            @Term NVARCHAR(MAX) ,
            @TermID INT ,
            @TotalSessionCount INT ,
            @Module NVARCHAR(MAX) ,
            @ModuleID INT ,
            @Session NVARCHAR(MAX) ,
            @SessionID INT ,
            @SkillID INT ,
            @SessionDuration INT ,
            @SessionTypeID INT ,
            @Cid INT ,
            @Tid INT ,
            @Mid INT ,
            @Sid INT
	
	
        DECLARE @MaxTermSeq INT ,
            @MaxModuleSeq INT ,
            @MaxSessionSeq INT
	
	
        DECLARE DataPopulator1 CURSOR
        FOR
        SELECT * FROM dbo.T_Import_Course_Structure TICS WHERE Course IS NOT NULL
	
        OPEN DataPopulator1
	
        FETCH NEXT FROM DataPopulator1
		INTO
		@Course,
		@CourseID,
		@Term,
		@TermID,
		@TotalSessionCount,
		@Module,
		@ModuleID,
		@Session,
		@SessionID,
		@SkillID,
		@SessionDuration,
		@SessionTypeID
	
        WHILE @@FETCH_STATUS = 0 
            BEGIN
                IF ( @CourseID IS NOT NULL ) 
                    BEGIN
                        IF ( @TermID IS NULL ) 
                            BEGIN
                                INSERT  INTO dbo.T_Term_Master
                                        ( I_Brand_ID ,
                                          S_Term_Code ,
                                          S_Term_Name ,
                                          S_Crtd_By ,
                                          Dt_Crtd_On ,
                                          I_Is_Editable ,
                                          I_Status ,
                                          I_Total_Session_Count
				                )
                                VALUES  ( @iBrandID , -- I_Brand_ID - int
                                          @Term , -- S_Term_Code - varchar(50)
                                          @Term , -- S_Term_Name - varchar(250)
                                          'dba' , -- S_Crtd_By - varchar(20)
                                          GETDATE() , -- Dt_Crtd_On - datetime
