I_Language_Name) --added by susmita on 30-07-2022 for language
VALUES
( @CourseFamilyID,
@iBrandID,
@sCourseCode,
@sCourseName,
@sCourseDescription,
@sCreatedBy,
@dCreatedOn,
1,
1,
@iUploadDocID,
@sLanguageID, --added by susmita on 30-07-2022 for language
@sLanguageName ) --added by susmita on 30-07-2022 for language

SELECT @iCourseID = @@IDENTITY

COMMIT TRAN T3
END
ELSE
BEGIN

BEGIN TRAN T4

INSERT INTO T_Course_Master
( I_CourseFamily_ID,
I_Brand_ID,
S_Course_Code,
S_Course_Name,
S_Course_Desc,
S_Crtd_By,
Dt_Crtd_On,
I_Is_Editable,
I_Status,
I_Document_ID,
I_Language_ID, --added by susmita on 30-07-2022 for language
I_Language_Name) --added by susmita on 30-07-2022 for language
VALUES
( @iCourseFamilyID,
@iBrandID,
@sCourseCode,
@sCourseName,
@sCourseDescription,
@sCreatedBy,
@dCreatedOn,
1,
1,
@iUploadDocID ,
@sLanguageID, --added by susmita on 30-07-2022 for language
@sLanguageName ) --added by susmita on 30-07-2022 for language

SELECT @iCourseID = @@IDENTITY

COMMIT TRAN T4

SELECT @iCourseID CourseID
END
END TRY
