				  @iBrandID , -- I_Brand_ID - int
				  @iUserID , -- I_User_ID - int
				  @dtExpiryDate , -- Dt_Expiry_Date - datetime
				  1 , -- I_Status_Id - int
				  @sCreatedBy , -- S_Crtd_By - varchar(50)
				  NULL , -- S_Upd_By - varchar(50)
				  @dtCreatedOn , -- Dt_Crtd_On - datetime
				  NULL  -- Dt_Upd_On - datetime
				)  
	    
			 SELECT @@IDENTITY        

          END    
    
  
     
      
  
END
