                        UPDATE  dbo.T_Exam_Component_Master
                        SET     I_Status = 0 ,
                                S_Upd_By = @sExamBy ,
                                Dt_Upd_On = @dExamOn
                        WHERE   I_Exam_Component_ID = @iExamID    
