--			FROM dbo.T_Centre_Master A,dbo.fnString2Rows(@sFeeCompIDs,',') B
--			WHERE A.I_Country_ID = @iCountryID
						
		END

	ELSE IF(@iFlag = 3)
		BEGIN
--			DELETE FROM dbo.T_Fee_Component_Tax
--			WHERE I_Centre_Id in 
--			(SELECT I_Centre_Id FROM dbo.T_Centre_Master
