		( I_Centre_Id,S_TimeSlot_Code,S_TimeSlot_Desc,
		  I_Status,S_Crtd_By,Dt_Crtd_On)
		VALUES
		(@iCenterID,@sTimeSlotCode,@sTimeSlotDesc,
		 1,@sCreatedBy,@dtCreatedOn)
