  ,I_Hierarchy_Master_ID                  
  ,S_Hierarchy_Chain                  
  ,I_Status                  
  ,Dt_Due_date                  
  ,Dt_Created_Date                  
 )                  
VALUES                  
 (                  
   @iTaskMasterId                  
  ,@info               
  ,''                  
  ,1                  
  ,''                  
  ,1                  
  ,GETDATE()                  
  ,GETDATE()                  
 )

SET @ID = SCOPE_IDENTITY() 

INSERT INTO dbo.T_Task_Assignment(I_Task_ID,I_To_User_ID,S_From_User)              
SELECT @ID,I_User_Id,@sUserID FROM @USERID 

END
