CREATE PROCEDURE [dbo].[uspPopulateCourse]  
	@iCourseID int
AS
BEGIN

	SET NOCOUNT OFF;

	DECLARE @iGradingPatternID int;
	DECLARE @iGradingPatternDetailID int;
	DECLARE @iCourseFeePlanID int;

	SELECT 
	@iGradingPatternID = CM.I_Grading_Pattern_ID
	FROM dbo.T_COURSE_MASTER CM 
	WHERE CM.I_Course_ID = @iCourseID
	AND CM.I_Status=1
	

	SELECT 
	CM.I_Course_ID,CM.I_CourseFamily_ID,CM.I_Brand_ID,CM.S_Course_Code,
	CM.S_Course_Name,CM.I_Grading_Pattern_ID,CM.S_Course_Desc,
	CM.I_Certificate_ID,CM.S_Crtd_By,CM.I_No_Of_Session,CM.S_Upd_By,
	CM.C_AptitudeTestReqd,CM.Dt_Crtd_On,CM.Dt_Upd_On,CM.I_Status,
	CR.S_Certificate_Name,
	CF.S_CourseFamily_Name
	FROM dbo.T_Course_Master CM
    LEFT OUTER JOIN dbo.T_Certificate_Master CR
	ON CM.I_Certificate_ID = CR.I_Certificate_ID
	LEFT OUTER JOIN dbo.T_CourseFamily_Master CF	
	ON CM.I_CourseFamily_ID = CF.I_courseFamily_ID
	WHERE CM.I_Course_ID = @iCourseID
	AND CM.I_Status=1


	SELECT 
	I_Grading_Pattern_ID,S_Pattern_Name,I_Status,
	S_Crtd_By,S_Upd_By,Dt_Crtd_On,Dt_Upd_On
	FROM dbo.T_Grading_Pattern_Master 
	WHERE I_Grading_Pattern_ID = @iGradingPatternID
	AND I_Status=1

	SELECT 
	I_Grading_Pattern_Detail_ID,I_Grading_Pattern_Detail_ID,
	S_Grade_Type,I_MinMarks,I_MaxMarks
	FROM dbo.T_Grading_Pattern_Detail
	WHERE I_Grading_Pattern_Detail_ID = @iGradingPatternDetailID 


	SELECT
	DPM.I_Delivery_Pattern_ID,DPM.S_Pattern_Name,DPM.I_Status,DPM.I_No_Of_Session,
	DPM.N_Session_Day_Gap,DPM.S_Crtd_By,DPM.S_Upd_By,DPM.Dt_Crtd_On,DPM.Dt_Upd_On
	FROM dbo.T_Delivery_Pattern_Master DPM
	INNER JOIN dbo.T_Course_Delivery_Map CDM
	ON DPM.I_Delivery_Pattern_ID = CDM.I_Delivery_Pattern_ID
	AND CDM.I_Course_ID = @iCourseID 
	AND DPM.I_Status=1
	AND CDM.I_Status=1
			

	SELECT
	I_Course_Fee_Plan_ID,S_Fee_Plan_Name,I_Course_Delivery_ID,
	I_Course_ID,I_Currency_ID,S_Crtd_By,C_Is_LumpSum,N_TotalLumpSum,
	S_Upd_By,Dt_Crtd_On,N_TotalInstallment,Dt_Upd_On
	FROM dbo.T_Course_Fee_Plan
	WHERE I_Course_ID = @iCourseID


	SELECT 
	FD.I_Fee_Component_ID,FD.I_Course_Fee_Plan_ID,FD.I_Item_Value,
	FD.N_CompanyShare,FD.I_Installment_No,I_Sequence,C_Is_LumpSum,I_Display_Fee_Component_ID, 
	FD.S_Crtd_By,Dt_Crtd_On,S_Upd_By,Dt_Upd_On
	FROM dbo.T_Course_Fee_Plan_Detail FD
	WHERE I_Course_Fee_Plan_ID = @iCourseFeePlanID

    SELECT * FROM dbo.T_Term_Master 
	WHERE I_Term_ID IN
	(SELECT I_Term_ID FROM dbo.T_Term_Course_Map
	 WHERE I_Course_ID = @iCourseID
	 AND I_Status <> 0
	 AND GETDATE() >= ISNULL(Dt_Valid_From,GETDATE())
	 AND GETDATE() <= ISNULL(Dt_Valid_To,GETDATE()))

END
GO
PRINT N'Creating Procedure [dbo].[uspPopulateCourseCenterDetails]...';


GO
-- =============================================    
-- Author:  Debarshi Basu    
-- Create date: 26/03/2006    
-- Description: GETS the different Courses,course family,    
--    certificate,duration of course related to     
--    a particular center    
-- =============================================    
CREATE PROCEDURE [dbo].[uspPopulateCourseCenterDetails]     
 @iHierarchyID int,    
 @iBrandID int    
AS    
BEGIN    
    
 SET NOCOUNT OFF    
 DECLARE @iCenterID int    
     
 SELECT @iCenterID = I_Center_Id FROM     
 dbo.T_Center_Hierarchy_Details WHERE    
 I_Hierarchy_Detail_ID = @iHierarchyID    
     
 --table 1(for courses related to a center)    
 SELECT DISTINCT A.I_Course_ID,B.S_Course_Code,B.S_Course_Name    
 FROM dbo.T_Course_Center_Detail A     
 INNER JOIN  dbo.T_Course_Master B    
 ON A.I_Course_ID = B.I_Course_ID    
 WHERE A.I_Centre_Id = @iCenterID    
 AND B.I_Brand_Id = @iBrandID    
 AND A.I_Status = 1    
 AND B.I_Status = 1    
 AND A.I_Course_ID IN    
 (    
  SELECT A1.I_Course_ID     
  FROM dbo.T_Course_Center_Detail A1    
  INNER JOIN dbo.T_Course_Center_Delivery_FeePlan B    
  ON A1.I_Course_Center_ID = B.I_Course_Center_ID    
  AND GETDATE() >= ISNULL(B.Dt_Valid_From, GETDATE())    
  AND GETDATE() <= ISNULL(B.Dt_Valid_To, GETDATE())    
  AND B.I_Status = 1    
  AND A1.I_Course_ID = A.I_Course_ID     
  AND A1.I_Centre_Id = @iCenterID    
 )    
    
 --table 2(for course family related to a center)    
 SELECT DISTINCT B.I_CourseFamily_ID,C.S_CourseFamily_Name    
 FROM dbo.T_Course_Center_Detail A    
 INNER JOIN dbo.T_Course_Master B    
 ON A.I_Course_ID = B.I_Course_ID    
 INNER JOIN dbo.T_CourseFamily_Master C    
 ON B.I_CourseFamily_ID = C.I_CourseFamily_ID    
 WHERE A.I_Centre_Id = @iCenterID    
 AND B.I_Brand_Id = @iBrandID    
 AND A.I_Status = 1    
 AND B.I_Status = 1    
 AND C.I_Status = 1    
 AND A.I_Course_ID IN    
 (    
  SELECT A1.I_Course_ID     
  FROM dbo.T_Course_Center_Detail A1    
  INNER JOIN dbo.T_Course_Center_Delivery_FeePlan B    
  ON A1.I_Course_Center_ID = B.I_Course_Center_ID    
  AND GETDATE() >= ISNULL(B.Dt_Valid_From, GETDATE())    
  AND GETDATE() <= ISNULL(B.Dt_Valid_To, GETDATE())    
  AND B.I_Status = 1    
  AND A1.I_Course_ID = A.I_Course_ID     
  AND A1.I_Centre_Id = @iCenterID    
 )    
     
    
 --table 3(for Certificates related to the center)    
 SELECT DISTINCT C.I_Certificate_ID,C.S_Certificate_Name    
 FROM dbo.T_Course_Center_Detail A    
 INNER JOIN dbo.T_Course_Master B    
 ON A.I_Course_ID = B.I_Course_ID    
 INNER JOIN dbo.T_Certificate_Master C    
 ON B.I_Certificate_ID = C.I_Certificate_ID    
 WHERE A.I_Centre_Id = @iCenterID    
 AND B.I_Brand_Id = @iBrandID    
 AND A.I_Status = 1    
 AND B.I_Status = 1    
 AND A.I_Course_ID IN    
 (    
  SELECT A1.I_Course_ID     
  FROM dbo.T_Course_Center_Detail A1    
  INNER JOIN dbo.T_Course_Center_Delivery_FeePlan B    
  ON A1.I_Course_Center_ID = B.I_Course_Center_ID    
  AND GETDATE() >= ISNULL(B.Dt_Valid_From, GETDATE())    
  AND GETDATE() <= ISNULL(B.Dt_Valid_To, GETDATE())    
  AND B.I_Status = 1    
  AND A1.I_Course_ID = A.I_Course_ID     
  AND A1.I_Centre_Id = @iCenterID    
 )    
    
 --table 4(for different Course Durations related with the center)    
 --SELECT CEILING((B.N_Course_Duration*7)/(dbo.fnGetSessionInWeek(D.I_No_Of_Session,D.S_DaysOfWeek)*30)) AS MONTHS,
 --SUBSTRING(  
 SELECT * INTO #temp FROM
 (SELECT DISTINCT B.N_Course_Duration AS DURATION,CEILING((B.N_Course_Duration*7)/(dbo.fnGetSessionInWeek(D.I_No_Of_Session,D.S_DaysOfWeek)*30)) AS MONTHS    
 FROM dbo.T_Course_Center_Detail A    
 INNER JOIN dbo.T_Course_Center_Delivery_FeePlan Y      
 ON A.I_Course_Center_ID = Y.I_Course_Center_ID     
 INNER JOIN dbo.T_Course_Delivery_Map B    
 ON Y.I_Course_Delivery_ID = B.I_Course_Delivery_ID      
 INNER JOIN dbo.T_Course_Master C    
 ON A.I_Course_ID = C.I_Course_ID    
 INNER JOIN dbo.T_Delivery_Pattern_Master D
 ON B.I_Delivery_Pattern_ID = D.I_Delivery_Pattern_ID 
 WHERE A.I_Centre_Id = @iCenterID    
 AND A.I_Status = 1    
 AND B.I_Status = 1    
 AND Y.I_Status = 1    
 AND A.I_Course_ID IN    
 (    
  SELECT A1.I_Course_ID     
  FROM dbo.T_Course_Center_Detail A1    
  INNER JOIN dbo.T_Course_Center_Delivery_FeePlan B    
  ON A1.I_Course_Center_ID = B.I_Course_Center_ID    
  AND GETDATE() >= ISNULL(B.Dt_Valid_From, GETDATE())    
  AND GETDATE() <= ISNULL(B.Dt_Valid_To, GETDATE())    
  AND B.I_Status = 1    
  AND A1.I_Course_ID = A.I_Course_ID     
  AND A1.I_Centre_Id = @iCenterID    
 )) T1
 
 
 SELECT DISTINCT MONTHS,STUFF((
 SELECT ','+CAST(DURATION AS varchar(10))
 FROM #temp
 WHERE MONTHS = A.MONTHS
 FOR XML PATH('')
 ),1,1,'') AS DURATION_LIST
 FROM #temp AS A 
 

     
     
END
GO
PRINT N'Creating Procedure [dbo].[uspPopulateCourseDetailsForCenter]...';


GO
CREATE PROCEDURE [dbo].[uspPopulateCourseDetailsForCenter]     
 @iHierarchyID int,    
 @sCourseIDs varchar(100),    
 @sCourseFamilyIDs varchar(100),    
 @sDurationIDs varchar(1000),    
 @sCertificateIDs varchar(100)    
AS    
BEGIN   
 SET NOCOUNT OFF    
 DECLARE @iCenterID int     
  
 IF LEN(@sCourseIDs) = 0    
 BEGIN    
  SET @sCourseIDs = null    
 END    
 IF LEN(@sCourseFamilyIDs) = 0    
 BEGIN    
  SET @sCourseFamilyIDs = null    
 END    
 IF LEN(@sDurationIDs) = 0    
 BEGIN    
  SET @sDurationIDs = null    
 END    
 IF LEN(@sCertificateIDs) = 0    
 BEGIN    
  SET @sCertificateIDs = null    
 END    
    
 SELECT @iCenterID = I_Center_Id FROM     
 dbo.T_Center_Hierarchy_Details WHERE    
 I_Hierarchy_Detail_ID = @iHierarchyID     
    
 SELECT DISTINCT X.I_Course_ID,A.S_Course_Code,A.S_Course_Name,C.I_Delivery_Pattern_ID,B.I_Course_Fee_Plan_ID ,  
 B.N_TotalLumpSum,B.N_TotalInstallment,Z.S_Pattern_Name,C.N_Course_Duration , dbo.GetDiscountSchemeforCenter(X.I_Course_ID, @iCenterID) AS DiscountSchemes   
 FROM dbo.T_Course_Center_Detail X     
 INNER JOIN dbo.T_Course_Center_Delivery_FeePlan Y   
 ON X.I_Course_Center_ID = Y.I_Course_Center_ID    
 INNER JOIN dbo.T_Course_Delivery_Map C    
 ON Y.I_Course_Delivery_ID = C.I_Course_Delivery_ID   
 INNER JOIN dbo.T_Delivery_Pattern_Master Z  
 ON Z.I_Delivery_Pattern_ID = C.I_Delivery_Pattern_ID  
 INNER JOIN dbo.T_Course_Fee_Plan B    
 ON Y.I_Course_Fee_Plan_ID = B.I_Course_Fee_Plan_ID    
 INNER JOIN dbo.T_Course_Master A    
 ON X.I_Course_ID = A.I_Course_ID     
 WHERE X.I_Centre_Id = @iCenterID    
 AND CHARINDEX(','+ CONVERT(VARCHAR(20), X.I_Course_ID  ) + ',', ISNULL(@sCourseIDs, ','+CONVERT(VARCHAR(20), X.I_Course_ID  )+',')) > 0     
 AND CHARINDEX(','+ CONVERT(VARCHAR(20), ISNULL(A.I_Certificate_ID,'') ) + ',', ISNULL(@sCertificateIDs, ','+ CONVERT(VARCHAR(20), ISNULL(A.I_Certificate_ID,'') )+',')) > 0    
 AND CHARINDEX(','+ CONVERT(VARCHAR(20), A.I_CourseFamily_ID  ) + ',', ISNULL(@sCourseFamilyIDs, ','+CONVERT(VARCHAR(20), A.I_CourseFamily_ID)+',')) > 0     
 AND CHARINDEX(','+ CONVERT(VARCHAR(20), C.N_Course_Duration ) + ',', ISNULL(@sDurationIDs, ','+CONVERT(VARCHAR(20), C.N_Course_Duration)+',')) > 0    
 AND X.I_STATUS <> 0 AND Y.I_STATUS <> 0 AND C.I_STATUS <> 0 AND B.I_STATUS <> 0 AND A.I_STATUS <> 0  
 AND GETDATE() >= ISNULL(Y.Dt_Valid_From,GETDATE()) AND GETDATE() <= ISNULL(Y.Dt_Valid_To,GETDATE())
 AND GETDATE() <= ISNULL(B.Dt_Valid_To,GETDATE())
 ORDER BY A.S_Course_Code  
END
