	DECLARE
	
	@iTransferRequestId int
	
	
	INSERT INTO T_Student_Transfer_Request
	(I_Source_Centre_ID,
	 I_Destination_Centre_ID,
	 I_Student_Detail_ID,
	 Dt_Request_Date,
     S_Workflow_GUID_ID,
	 I_Status,
	 S_Crtd_By,
	 Dt_Crtd_On
	)
	VALUES
	(@iSourceCenterHId,@iDestinationCenterHId,@iStudentDetailId,@dRequestDate,@sWorkflowInstanceID,1,@sCrtdBy,@dCrtdOn)
	
