)

AS
BEGIN TRY 
	UPDATE dbo.T_EMPLOYEE_APTITUDE_TEST SET
		
			I_EAT_ROLE_SKILL_TEST_ID = @iEatRoleSkillTestId ,
			I_EAT_PROS_EMPLOYEE_ID = @iEatProsEmloyeeId ,
