CREATE PROCEDURE [dbo].[uspUpdateSMSDetails]
(
	@iSMSDetailsID INT
	,@iIsSuccess INT
	,@iNoOfAttempt INT = NULL
	,@sReturnCodeFromProvider VARCHAR(250) = NULL
)
AS
BEGIN	
	
	UPDATE [T_SMS_SEND_DETAILS] 
		SET [I_IS_SUCCESS] =@iIsSuccess
		,[I_Status]=(1-@iIsSuccess)
		,[I_NO_OF_ATTEMPT]= (CASE WHEN @iNoOfAttempt IS NULL THEN [I_NO_OF_ATTEMPT]  ELSE ISNULL([I_NO_OF_ATTEMPT],0)+1 END)
		,[Dt_SMS_SEND_ON] = (CASE WHEN @iIsSuccess =1 THEN GETDATE() ELSE NULL END)
		,[Dt_Upd_On]=GETDATE()
		,[S_Upd_By] = [S_Crtd_By] 
		,[S_RETURN_CODE_FROM_PROVIDER]=(CASE WHEN @sReturnCodeFromProvider IS NULL THEN [S_RETURN_CODE_FROM_PROVIDER] ELSE @sReturnCodeFromProvider END)
	WHERE [I_SMS_SEND_DETAILS_ID] = @iSMSDetailsID
	 
	
END
GO
PRINT N'Creating Procedure [dbo].[uspUpdateSMSSendDetails]...';


GO
CREATE procedure [dbo].[uspUpdateSMSSendDetails](@SMSDetailsID INT, @IsCompleted INT, @ConfigNoofAttempts INT, @ResponseText VARCHAR(MAX))
AS
BEGIN

	DECLARE @NoofAttempts INT
	DECLARE @Status INT=1
	DECLARE @SendDate DATETIME=NULL

	select @NoofAttempts=I_NO_OF_ATTEMPT from T_SMS_SEND_DETAILS where I_SMS_SEND_DETAILS_ID=@SMSDetailsID and I_Status=1

	if((@NoofAttempts+1)>=@ConfigNoofAttempts)
		set @Status=0

	if(@IsCompleted=1)
	BEGIN

		set @Status=0
		set @SendDate=GETDATE()

	END

	update T_SMS_SEND_DETAILS 
	set 
	I_IS_SUCCESS=@IsCompleted,
	I_NO_OF_ATTEMPT=@NoofAttempts+1,
	S_RETURN_CODE_FROM_PROVIDER=@ResponseText,
	Dt_SMS_SEND_ON=@SendDate,
	S_Upd_By='rice-group-admin',
	Dt_Upd_On=GETDATE(),
	I_Status=@Status
	where
	I_SMS_SEND_DETAILS_ID=@SMSDetailsID and I_Status=1
	


END
GO
