CREATE PROCEDURE [ACADEMICS].[uspGetStudentLeaveStatus]

AS 
    BEGIN
    
    DECLARE @dtDate DATE=GETDATE()
    
        CREATE TABLE #temp
            (
              id INT IDENTITY(1, 1) ,
              StudentID INT
            )

        INSERT  INTO #temp
                ( StudentID 
                )
                SELECT  DISTINCT
                        TSSD.I_Student_Detail_ID
                FROM    dbo.T_Student_Status_Details TSSD
                        INNER JOIN dbo.T_Student_Status_Master TSSM ON TSSD.I_Student_Status_ID = TSSM.I_Student_Status_ID
                WHERE   TSSD.I_Status = 1
                        AND TSSM.I_Status = 1
                        AND TSSD.IsEditable <> 0
                        --AND TSSM.I_Student_Status_ID = 2
                        
                        
        DECLARE @i INT= 1
        DECLARE @std INT
        
        
        
        WHILE ( @i <= ( SELECT  COUNT(*)
                        FROM    #temp
                      ) ) 
            BEGIN
            
                SELECT  @std = StudentID
                FROM    #temp
                WHERE   id = @i
                
                IF EXISTS ( SELECT  *
                            FROM    dbo.T_Student_Status_Details TSSD
                                    INNER JOIN dbo.T_Student_Status_Master TSSM ON TSSD.I_Student_Status_ID = TSSM.I_Student_Status_ID
                            WHERE   TSSD.I_Status = 1
                                    AND TSSM.I_Status = 1
                                    AND TSSD.IsEditable <> 0
                                    AND TSSM.I_Student_Status_ID = 6
                                    AND TSSD.I_Student_Detail_ID = @std ) 
                    BEGIN
                        IF EXISTS ( SELECT  *
                                    FROM    dbo.T_Student_Leave_Request TSLR
                                    WHERE   I_Student_Detail_ID = @std
                                            AND TSLR.I_Status = 1
                                            AND @dtDate BETWEEN TSLR.Dt_From_Date
                                                          AND TSLR.Dt_To_Date ) 
                            BEGIN
                                EXEC ACADEMICS.uspInsertIntoStudentStatusArchive @StudentStatusID = 6, -- int
                                    @StudentID = @std -- int
                                    
                                UPDATE  dbo.T_Student_Status_Details
                                SET     Dt_Crtd_On = GETDATE() ,
                                        S_Crtd_By = 'dba'
                                WHERE   I_Student_Detail_ID = @std
                                        AND I_Status = 1
                                        AND IsEditable = 1
                                        AND I_Student_Status_ID = 6
                            END
					
                        ELSE 
                            BEGIN
                                EXEC ACADEMICS.uspInsertIntoStudentStatusArchive @StudentStatusID = 6, -- int
                                    @StudentID = @std -- int
                         
                                UPDATE  dbo.T_Student_Status_Details
                                SET     I_Status = 0 ,
                                        Dt_Upd_On = GETDATE() ,
                                        S_Upd_By = 'dba'
                                WHERE   I_Student_Detail_ID = @std
                                        AND I_Status = 1
                                        AND IsEditable = 1
                                        AND I_Student_Status_ID = 6
                            END
                    END
                    
                ELSE 
                    BEGIN
                        IF EXISTS ( SELECT  *
                                    FROM    dbo.T_Student_Leave_Request TSLR
                                    WHERE   I_Student_Detail_ID = @std
                                            AND TSLR.I_Status = 1
                                            AND @dtDate BETWEEN TSLR.Dt_From_Date
                                                          AND TSLR.Dt_To_Date ) 
                            BEGIN
                                INSERT  INTO dbo.T_Student_Status_Details
                                        ( I_Student_Detail_ID ,
                                          I_Student_Status_ID ,
                                          I_Status ,
                                          N_Due ,
                                          Dt_Crtd_On ,
                                          S_Crtd_By ,
                                          IsEditable
        		                      
                                        )
                                VALUES  ( @std , -- I_Student_Detail_ID - int
                                          6 , -- I_Student_Status_ID - int
                                          1 , -- I_Status - int
                                          NULL , -- N_Due - decimal
                                          GETDATE() , -- Dt_Crtd_On - datetime
                                          'dba' , -- S_Crtd_By - varchar(50)
                                          1  -- IsEditable - bit
        		                      
                                        )
                            END                                  
                    END
                    
                SET @i = @i + 1                    
                
            END    
    END
GO
PRINT N'Creating Procedure [ACADEMICS].[uspModifyStudentAcademicDropoutStatus]...';


GO
CREATE PROCEDURE [ACADEMICS].[uspModifyStudentAcademicDropoutStatus]  
AS  
  
BEGIN TRY  
BEGIN TRAN T1  
  
 SET NOCOUNT ON;  
  
 Declare @I_Process_ID_Max Int  
 Declare @Comments Varchar(2000)  
 Declare @Center_Name Varchar(500)  
 Declare @Student_Name Varchar(500)  
 DECLARE @iCenterID INT  
 DECLARE @iPreviousCourseID INT  
 DECLARE @iStudentID INT  
 DECLARE @iAllowableNonAttendedDays INT  
 DECLARE @iStatus INT  
 DECLARE @cAcademicDropout CHAR(1)  
 DECLARE @iCourseID INT  
 DECLARE @iBatchID INT  
 DECLARE @dDate DATETIME  
  
 SET @iPreviousCourseID=0  
 SET @dDate=CAST(SUBSTRING(CAST(GETDATE() AS VARCHAR),1,11) as datetime)  
  
 Declare @S_Batch_Process_Name VARCHAR(500)  
   
 DECLARE @tblDropoutStudent TABLE(I_Student_Detail_ID INT, I_Center_ID INT, I_Course_ID INT, I_Batch_ID INT)  
 DECLARE @tblReactivatedStudent TABLE(I_Student_Detail_ID INT, I_Center_ID INT, I_Course_ID INT, I_Batch_ID INT)  
   
 SET @S_Batch_Process_Name='STUDENT_ACADEMICS_DROPOUT'  
    
 Declare @I_Batch_Process_ID Int  
 Select @I_Batch_Process_ID=I_Batch_Process_ID From dbo.T_Batch_Master WITH (NOLOCK) Where S_Batch_Process_Name='STUDENT_ACADEMIC_DROPOUT' And I_Status=1  
   
 SET @cAcademicDropout = ''  
 SET @iAllowableNonAttendedDays = 0  
   
 DECLARE @tblList TABLE (ID INT IDENTITY(1,1),I_Student_Detail_ID INT,I_Centre_Id INT, I_Course_ID INT, I_Batch_ID INT)  
   
 INSERT INTO @tblList  
 SELECT DISTINCT SCD.I_Student_Detail_ID,  
   SCD.I_Centre_Id,  
   tsbm.I_Course_ID,  
   tsbm.I_Batch_ID  
 FROM    dbo.T_Student_Center_Detail SCD WITH ( NOLOCK )  
   INNER JOIN dbo.T_Student_Batch_Details AS tsbd   
   ON tsbd.I_Student_ID = SCD.I_Student_Detail_ID  
   INNER JOIN dbo.T_Student_Batch_Master AS tsbm ON tsbm.I_Batch_ID = tsbd.I_Batch_ID  
   INNER JOIN [T_Brand_Center_Details] BCD WITH ( NOLOCK ) ON BCD.I_Centre_Id = SCD.I_Centre_Id  
   INNER JOIN dbo.T_Center_Batch_Details AS tcbd ON tcbd.I_Centre_Id = SCD.I_Centre_Id AND tcbd.I_Batch_ID = tsbd.I_Batch_ID  
 WHERE   SCD.I_Status = 1  
   AND BCD.I_Status=1  
   AND DATEDIFF(dd,ISNULL(SCD.Dt_Valid_From,GETDATE()),GETDATE()) >= 0  
   AND DATEDIFF(dd,ISNULL(SCD.Dt_Valid_To,GETDATE()),GETDATE()) <= 0  
   AND DATEDIFF(dd,ISNULL(tsbd.Dt_Valid_From,GETDATE()),GETDATE()) >= 0     
   AND SCD.I_Student_Detail_ID NOT IN  
   (SELECT I_Student_Detail_ID FROM dbo.T_Student_Leave_Request AS tslr   
   WHERE DATEDIFF(DAY, ISNULL(tslr.Dt_From_Date,GETDATE()), GETDATE()) >= 0  
            AND DATEDIFF(DAY, GETDATE(), ISNULL(tslr.Dt_To_Date,GETDATE())) >= 0  
            AND I_Status = 1)  
            AND ISNULL(tcbd.I_Status, tsbm.I_Status) <> 5  
            AND tsbd.I_Status = 1  
            AND tsbd.I_Batch_ID IN   
            (SELECT I_Batch_ID FROM dbo.T_Student_Batch_Master AS tsbm  
            WHERE DATEDIFF(dd, tsbm.Dt_BatchStartDate, GETDATE()) >= 0  
            AND DATEDIFF(dd,tsbm.Dt_Course_Expected_End_Date,GETDATE()) <= 0)  
 ORDER BY tsbm.I_Course_ID  
  
 --WHILE @@FETCH_STATUS = 0      
 --BEGIN  
 DECLARE @iIndex INT, @iRowCount INT  
 SELECT @iIndex = 1, @iRowCount = COUNT('1') FROM @tblList  
   
 WHILE (@iIndex <= @iRowCount)  
 BEGIN  
   
  SELECT @iStudentID = I_Student_Detail_ID, @iCenterID = I_Centre_Id,   
    @iCourseID = I_Course_ID, @iBatchID = I_Batch_ID  
  FROM @tblList WHERE ID = @iIndex  
   
  IF(@iPreviousCourseID <> @iCourseID)  
  BEGIN  
   SELECT @cAcademicDropout= ISNULL(I_Is_Dropout_Allowed,'N') FROM [dbo].[T_Course_Master] CM WITH(NOLOCK) WHERE CM.I_Course_ID = @iCourseID  
   SELECT @iAllowableNonAttendedDays = ISNULL(I_No_Of_Days,0) FROM [dbo].[T_Course_Master] WHERE I_Course_ID = @iCourseID  
  END    
    
  IF @cAcademicDropout = 'Y'  
  BEGIN  
   SET @iStatus = 0  
   IF [ACADEMICS].ufnGetStudentAcademicDropoutStatusBatch(@iStudentID,@iBatchID,@iCenterID, @iAllowableNonAttendedDays, @dDate) = 'Y'  
   BEGIN  
    SET @iStatus = 1  
   END    
  
   IF (@iStatus = 1)  
   BEGIN  
    IF NOT EXISTS (SELECT 'TRUE' FROM ACADEMICS.T_Dropout_Details WITH (NOLOCK)  
     WHERE I_Student_Detail_ID = @iStudentID  
     AND I_Center_Id = @iCenterID  
     AND I_Dropout_Status = 1  
     AND I_Batch_ID = @iBatchID
     AND I_Dropout_Type_ID = 1)  
    BEGIN  
      
     INSERT INTO @tblDropoutStudent VALUES (@iStudentID, @iCenterID, @iCourseID, @iBatchID)  
	 UPDATE dbo.T_Student_Batch_Details SET I_Status = 0 WHERE I_Batch_ID = @iBatchID AND I_Student_ID = @iStudentID
    
    END  
   END  
   ELSE IF @iStatus = 0  -- ACTIVATE THE STUDENT WHO IS NOT ACADEMIC DROPOUT  
   BEGIN  
    INSERT INTO @tblReactivatedStudent VALUES (@iStudentID, @iCenterID, @iCourseID, @iBatchID)  
    UPDATE dbo.T_Student_Batch_Details SET I_Status = 1 WHERE I_Batch_ID = @iBatchID AND I_Student_ID = @iStudentID  
   END   
  END    
  
  SET @iPreviousCourseID = @iCourseID  
  
 -- FETCH NEXT FROM DROPOUT_CURSOR INTO @iStudentID, @iSelectedCenterID, @iCourseID  
 --END   
  
 --CLOSE DROPOUT_CURSOR  
 --DEALLOCATE DROPOUT_CURSOR  
   
  SET @iIndex = @iIndex + 1  
   
 END  
   
 SELECT tcm.S_Center_Name, tcm2.S_Course_Name, tsbm.S_Batch_Code, tsd.S_Student_ID,   
   tsd.S_First_Name, tsd.S_Middle_Name, tsd.S_Last_Name, t.*  
 FROM @tblDropoutStudent t  
 INNER JOIN dbo.T_Student_Detail AS tsd ON t.I_Student_Detail_ID = tsd.I_Student_Detail_ID  
 INNER JOIN dbo.T_Student_Batch_Master AS tsbm ON t.I_Batch_ID = tsbm.I_Batch_ID  
 INNER JOIN dbo.T_Centre_Master AS tcm ON tcm.I_Centre_Id = t.I_Center_ID  
 INNER JOIN dbo.T_Course_Master AS tcm2 ON t.I_Course_ID = tcm2.I_Course_ID  
 ORDER BY tcm2.I_Course_ID, I_Centre_Id, I_Batch_ID  
   
 SELECT * FROM @tblReactivatedStudent  
   
 EXEC uspUpdateBatchProcessesDataBrandWise @S_Batch_Process_Name,'Success'  
COMMIT TRAN T1  
END TRY  
  
BEGIN CATCH  
--Error occurred:  
 ROLLBACK  TRAN T1  
 Declare @S_Batch_Process_Name_ERROR VARCHAR(500)  
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity INT,@Description VARCHAR(4000)  
 SELECT @ErrMsg = ERROR_MESSAGE(),@ErrSeverity = ERROR_SEVERITY()  
   
 SET @S_Batch_Process_Name_ERROR='STUDENT_ACADEMICS_DROPOUT'  
  
 SET @Description='Error : '+CAST(@ErrMsg AS VARCHAR)  
 --EXEC uspWriteBatchProcessLog_New NULL,@S_Batch_Process_Name,@Description,'Faliure',1  
 EXEC uspUpdateBatchProcessesDataBrandWise @S_Batch_Process_Name_ERROR,'Faliure'  
 --RAISERROR(@ErrMsg, @ErrSeverity, 1)  
END CATCH
GO
PRINT N'Creating Procedure [ACADEMICS].[uspModifyStudentFinancialDropoutStatus]...';


GO
--MODIFIED STORED PROCEDURE FOR FINANCIAL DROPOUT (BRANDWISE)    
CREATE PROCEDURE [ACADEMICS].[uspModifyStudentFinancialDropoutStatus]         
(            
 @iBrandID int = NULL    
)            
AS            
            
BEGIN TRY            
BEGIN TRAN T1            
            
 SET NOCOUNT ON;            
            
 Declare @I_Process_ID_Max Int            
 Declare @Comments Varchar(2000)            
 Declare @Center_Name Varchar(500)            
 Declare @Student_Name Varchar(500)            
            
 DECLARE @iSelectedCenterID INT            
 DECLARE @iStudentID INT            
 DECLARE @iAllowableNonPaymentDays INT            
 DECLARE @iNoOfRelaxedInstallments INT                 
 DECLARE @cFinancialDropout CHAR(1)            
 DECLARE @dDate DATETIME            
 DECLARE @iInvoiceCount INT              
 DECLARE @iDropoutInvoiceCount INT         
----------------------        
DECLARE @min INT            
DECLARE @max INT            
DECLARE @iInvoiceHeaderId INT            
DECLARE @sIsDropoutInvoice CHAR(1)        
DECLARE @sIsReactivationFeesPaid VARCHAR(10)            
DECLARE @TEMPTABLE TABLE        
(ROWID INT IDENTITY(1,1)        
,I_Invoice_Header_Id INT        
,S_Is_Dropout_Invoice CHAR(1)        
,S_Is_Reactivation_Fees_Paid VARCHAR(10)        
)            
         
----------------------             
            
 DECLARE @iPreviousCenterID INT            
 SET @iPreviousCenterID=0            
             
 SET @dDate=CAST(SUBSTRING(CAST(GETDATE() AS VARCHAR),1,11) as datetime)            
            
 DECLARE  @InvoiceWiseDropoutTable TABLE            
      (              
       I_Student_Detail_ID INT              
      ,I_Center_Id INT              
      ,I_Invoice_Header_Id INT              
      ,S_Is_Dropout_Invoice CHAR(1)         
   ,S_Is_Reactivation_Fees_Paid VARCHAR(10)               
      )              
            
 DECLARE @tmpDropout TABLE            
 (            
  centerID INT,            
  centerHierarchyDetailID INT,            
  studentID INT,            
  studentCode VARCHAR(500),            
  studentFirstName VARCHAR(50),            
  studentMiddleName VARCHAR(50),            
  studentLastName VARCHAR(50)            
 )            
            
 Declare @S_Batch_Process_Name VARCHAR(500)            
             
 SET @S_Batch_Process_Name='STUDENT_FINANCIAL_DROPOUT'    
            
 Declare @I_Batch_Process_ID Int            
 Select @I_Batch_Process_ID=I_Batch_Process_ID From dbo.T_Batch_Master WITH (NOLOCK) Where S_Batch_Process_Name=@S_Batch_Process_Name And I_Status=1            
            
 Select @I_Process_ID_Max=ISNULL(Max(I_Process_ID),0)+1 From dbo.T_Batch_Log WITH (NOLOCK) Where S_Batch_Process_Name=@S_Batch_Process_Name            
            
 SET @cFinancialDropout = ''            
 SET @iAllowableNonPaymentDays = 0            
            
 DECLARE DROPOUT_CURSOR CURSOR FOR            
 SELECT SCD.I_Student_Detail_ID, SCD.I_Centre_Id            
 FROM dbo.T_Student_Center_Detail SCD WITH (NOLOCK)            
 INNER JOIN dbo.T_Centre_Master CM WITH (NOLOCK) ON SCD.I_Centre_Id = CM.I_Centre_Id            
 INNER JOIN [T_Brand_Center_Details] BCD WITH (NOLOCK) ON BCD.I_Centre_Id =CM.I_Centre_Id            
 WHERE BCD.I_Brand_Id= ISNULL(@iBrandID,BCD.I_Brand_Id)    
 --AND SCD.I_Status = 1            
 AND @dDate>= ISNULL(SCD.Dt_Valid_From, @dDate)            
 AND @dDate <= ISNULL(SCD.Dt_Valid_To, @dDate)            
 ORDER BY SCD.I_Centre_Id            
            
 OPEN DROPOUT_CURSOR            
 FETCH NEXT FROM DROPOUT_CURSOR INTO @iStudentID, @iSelectedCenterID            
            
 WHILE @@FETCH_STATUS = 0                
 BEGIN              
              
  IF(@iPreviousCenterID<>@iSelectedCenterID)            
  BEGIN            
   SELECT @cFinancialDropout=ISNULL(S_CONFIG_VALUE,'') FROM [dbo].[ufnPopulateCenterConfigDetailsBatch](@iSelectedCenterID,'ACADS_CHECK_FINANCIAL_DROPOUT_YN')            
   SELECT @iAllowableNonPaymentDays=ISNULL(S_CONFIG_VALUE,0) FROM [dbo].[ufnPopulateCenterConfigDetailsBatch](@iSelectedCenterID,'LIMIT_NON_PAYMENT_FEE_DAYS')            
   SELECT @iNoOfRelaxedInstallments = ISNULL(S_CONFIG_VALUE,3) FROM [dbo].[ufnPopulateCenterConfigDetailsBatch](@iSelectedCenterID,'CENTER_NO_OF_INSTALLMENT_RELAXED')              
  END            
              
  IF @cFinancialDropout = 'Y'              
  BEGIN                   
      ------------------------------------------------------------              
                     
      INSERT INTO @InvoiceWiseDropoutTable              
      SELECT * FROM [ACADEMICS].[ufnGetStudentFinancialDropoutStatusBatch](@iStudentID, @iSelectedCenterID, @iAllowableNonPaymentDays, @dDate, @iNoOfRelaxedInstallments)                   
                     
       SELECT @CENTER_NAME=S_CENTER_NAME FROM dbo.T_CENTRE_MASTER WITH (NOLOCK) WHERE I_CENTRE_ID=@iSelectedCenterID            
       SELECT @Student_Name=ISNULL(S_FIRST_NAME,'')+' '+ISNULL(S_MIDDLE_NAME,'')+' '+ISNULL(S_LAST_NAME,'') FROM dbo.T_STUDENT_DETAIL WITH (NOLOCK) WHERE I_STUDENT_DETAIL_ID = @iStudentID            
      --------------------------         
    INSERT INTO @TEMPTABLE             
    SELECT I_Invoice_Header_Id,S_Is_Dropout_Invoice,S_Is_Reactivation_Fees_Paid             
    FROM @InvoiceWiseDropoutTable      
    
    SELECT @min = MIN(ROWID), @max = MAX(ROWID) FROM @TEMPTABLE            
                
    WHILE @min <= @max             
    BEGIN        
        
    SELECT   @iInvoiceHeaderId = I_Invoice_Header_Id        
      ,@sIsDropoutInvoice = S_Is_Dropout_Invoice        
      ,@sIsReactivationFeesPaid = S_Is_Reactivation_Fees_Paid        
    FROM @TEMPTABLE WHERE ROWID = @min         
      
    SELECT I_Batch_ID INTO #temp FROM dbo.T_Invoice_Batch_Map AS TIBM
			 INNER JOIN dbo.T_Invoice_Child_Header AS TICH
			 ON TIBM.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
			 INNER JOIN dbo.T_Invoice_Parent AS TIP
			 ON TICH.I_Invoice_Header_ID = TIP.I_Invoice_Header_ID
			 WHERE TICH.I_Invoice_Header_ID = @iInvoiceHeaderId       
         
          IF (@sIsDropoutInvoice = 'Y')            
          BEGIN            
                    
        IF NOT EXISTS (SELECT I_Dropout_ID FROM ACADEMICS.T_Dropout_Details WITH (NOLOCK)            
         WHERE I_Student_Detail_ID = @iStudentID            
         AND I_Center_Id = @iSelectedCenterID            
         AND I_Dropout_Type_ID = 2      
   AND I_Invoice_Header_Id = @iInvoiceHeaderId      
   )            
          BEGIN            
           
            
            
           UPDATE dbo.T_Student_Batch_Details
           SET I_Status = 0
           WHERE I_Student_ID = @iStudentID 
           AND I_Batch_ID IN 
           (
			 SELECT I_Batch_ID FROM #temp
           )          
           --UPDATE dbo.T_Student_Detail            
           --SET I_Status = 0,             
           --S_Upd_By = 'SYSTEM_BATCH',            
           --Dt_Upd_On = @dDate            
           --WHERE I_Student_Detail_ID = @iStudentID            
                     
           INSERT INTO ACADEMICS.T_Dropout_Details            
           (            
            I_Student_Detail_ID,            
            I_Center_Id,            
            I_Dropout_Type_ID,            
            I_Dropout_Status,            
            Dt_Dropout_Date,            
            Dt_Crtd_On,            
            S_Crtd_By,        
            I_Invoice_Header_Id            
           )            
           VALUES            
           (            
            @iStudentID ,            
            @iSelectedCenterID ,            
            2,            
            1,            
            @dDate ,            
            @dDate,            
            'SYSTEM_BATCH'        
            ,@iInvoiceHeaderId           
           )            
          END           
         ELSE          
          BEGIN          
          IF EXISTS ( SELECT  'TRUE'        
            FROM    ACADEMICS.T_Dropout_Details        
              WITH ( NOLOCK )        
            WHERE   I_Student_Detail_ID = @iStudentID        
              AND I_Center_Id = @iSelectedCenterID        
              AND I_Dropout_Type_ID = 2 AND [I_Dropout_Status]=0         
              AND I_Invoice_Header_Id = @iInvoiceHeaderId        
             )         
            BEGIN             
               UPDATE ACADEMICS.T_Dropout_Details          
               SET I_Dropout_Status = 1,      
    Dt_Dropout_Date = @dDate,          
                S_Upd_By = 'SYSTEM_BATCH',          
                Dt_Upd_On = @dDate          
               WHERE I_Student_Detail_ID = @iStudentID          
               AND I_Center_Id = @iSelectedCenterID          
               AND I_Dropout_Type_ID = 2        
               AND  I_Invoice_Header_Id = @iInvoiceHeaderId        
            END        
          END           
                
         Set @Comments=@Center_Name+'('+cast(@iSelectedCenterID as varchar)+')> '+@Student_Name+'('+cast(@iStudentID as varchar)+') - Dropped out'       
      + ' [InvoiceHeaderId:'+CAST(@iInvoiceHeaderId AS VARCHAR)+']' +'[ReactFeeStatus:'+ @sIsReactivationFeesPaid+']'        
         EXEC uspWriteBatchProcessLog_New @I_Process_ID_Max,@S_Batch_Process_Name,@Comments,'Success',@I_Batch_Process_ID            
                
        END              
       ELSE IF (@sIsDropoutInvoice = 'N') -- ACTIVATE THE STUDENT WHO IS NOT FINANCIAL DROPOUT            
        BEGIN            
                    
         IF EXISTS (SELECT I_Dropout_ID FROM ACADEMICS.T_Dropout_Details WITH (NOLOCK)            
              WHERE I_Student_Detail_ID = @iStudentID            
              AND I_Center_Id = @iSelectedCenterID            
              AND I_Dropout_Status = 1            
              AND I_Dropout_Type_ID = 2        
              AND I_Invoice_Header_Id = @iInvoiceHeaderId        
            )            
             BEGIN            
               UPDATE ACADEMICS.T_Dropout_Details            
               SET I_Dropout_Status = 0,            
                S_Upd_By = 'SYSTEM_BATCH',            
                Dt_Upd_On = @dDate            
               WHERE I_Student_Detail_ID = @iStudentID            
               AND I_Center_Id = @iSelectedCenterID            
               AND I_Dropout_Type_ID = 2            
               AND I_Dropout_Status = 1         
               AND I_Invoice_Header_Id = @iInvoiceHeaderId           
                     
             END            
                    
             Set @Comments=@Center_Name+'('+cast(@iSelectedCenterID as varchar)+')> '+@Student_Name+'('+cast(@iStudentID as varchar)+') - Activated'            
       + ' [InvoiceHeaderId:'+CAST(@iInvoiceHeaderId AS VARCHAR)+']' +'[ReactFeeStatus:'+ @sIsReactivationFeesPaid+']'        
             EXEC uspWriteBatchProcessLog_New @I_Process_ID_Max,@S_Batch_Process_Name,@Comments,'Success',@I_Batch_Process_ID            
        
        
         END         
     SET @min = @min + 1        
    END        
    -------------------------------------------------        
    --- updating the student status in dbo.T_Student_Detail         
        
    IF EXISTS(SELECT 'TRUE' FROM @InvoiceWiseDropoutTable WHERE S_Is_Dropout_Invoice = 'Y')        
             BEGIN  
				UPDATE dbo.T_Student_Batch_Details
					   SET I_Status = 0
					   WHERE I_Student_ID = @iStudentID 
					   AND I_Batch_ID IN 
					   (
						 SELECT I_Batch_ID FROM #temp
					   )        
                --  UPDATE dbo.T_Student_Detail            
                --SET I_Status = 0,             
                --S_Upd_By = 'SYSTEM_BATCH',            
                --Dt_Upd_On = @dDate            
                --WHERE I_Student_Detail_ID = @iStudentID         
             END        
    ELSE        
       BEGIN        
            IF NOT EXISTS (SELECT 'TRUE' FROM ACADEMICS.T_Dropout_Details WITH (NOLOCK)              
               WHERE I_Student_Detail_ID = @iStudentID              
               AND I_Center_Id = @iSelectedCenterID            
               AND I_Dropout_Status = 1)              
            BEGIN  
				UPDATE dbo.T_Student_Batch_Details
					   SET I_Status = 1
					   WHERE I_Student_ID = @iStudentID 
					   AND I_Batch_ID IN 
					   (
						 SELECT I_Batch_ID FROM #temp
					   )              
              --UPDATE dbo.T_Student_Detail              
              --SET I_Status = 1,               
              --S_Upd_By = 'SYSTEM_BATCH',              
              --Dt_Upd_On = @dDate              
              --WHERE I_Student_Detail_ID = @iStudentID              
            END              
       END        
               
     ---end of updating the student status in dbo.T_Student_Detail         
    -------------------------------------------------        
    DELETE @InvoiceWiseDropoutTable        
        
    DELETE @TEMPTABLE            
    ---------------------------------------------------            
   END -- end of  @cFinancialDropout = 'Y'             
              
  SET @iPreviousCenterID=@iSelectedCenterID            
         
  FETCH NEXT FROM DROPOUT_CURSOR INTO @iStudentID, @iSelectedCenterID            
 END             
            
 CLOSE DROPOUT_CURSOR            
 DEALLOCATE DROPOUT_CURSOR            
             
 --SELECT * FROM @tmpDropout            
 EXEC uspUpdateBatchProcessesDataBrandWise @S_Batch_Process_Name,'Success'            
            
COMMIT TRAN T1            
END TRY            
            
BEGIN CATCH            
--Error occurred:            
 ROLLBACK  TRAN T1            
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity INT,@Description VARCHAR(4000)            
 Declare @S_Batch_Process_Name_ERROR VARCHAR(500)            
            
 SELECT @ErrMsg = ERROR_MESSAGE(),@ErrSeverity = ERROR_SEVERITY()                  
     
 SET @S_Batch_Process_Name_ERROR='STUDENT_FINANCIAL_DROPOUT'    
            
 SET @Description='Error : '+CAST(@ErrMsg AS VARCHAR)            
 EXEC uspWriteBatchProcessLog_New 2000,@S_Batch_Process_Name_ERROR,@Description,'Faliure',2            
 EXEC uspUpdateBatchProcessesDataBrandWise @S_Batch_Process_Name_ERROR,'Faliure'            
-- RAISERROR(@ErrMsg, @ErrSeverity, 1)            
END CATCH
GO
PRINT N'Creating Procedure [ACADEMICS].[uspUpdateConcernAreasForNonCompliance]...';


GO
CREATE PROCEDURE [ACADEMICS].[uspUpdateConcernAreasForNonCompliance] 
(
	@sConcernAreas VARCHAR(1000),
	@dtCurrentDate DATETIME
)
AS

BEGIN TRY
BEGIN TRAN T1

	SET NOCOUNT ON;
		
		UPDATE Academics.T_Concern_Areas
		SET I_Is_Notified = 1,
		S_Upd_By = 'SYSTEM_BATCH',
		Dt_Upd_On = @dtCurrentDate
		WHERE I_Concern_Areas_ID IN
		(
			SELECT * FROM [dbo].[fnString2Rows](@sConcernAreas, ',')
		)
		
		Declare @iActualRowCount Int
		Declare @iCount Int
		Declare @I_Process_ID_Max Int
		Declare @Comments Varchar(2000)
		Declare @ConcernAreasName Varchar(2000)
		Select @I_Process_ID_Max=ISNULL(Max(I_Process_ID),0)+1 From dbo.T_Batch_Log Where S_Batch_Process_Name='CONCERN_AREA_NC'
	
		SELECT IDENTITY(int, 1,1) AS ID_Num,*  INTO #ConcernAreas FROM [dbo].[fnString2Rows](@sConcernAreas, ',')
		Set @iCount=1
		SELECT @iActualRowCount = COUNT(*) FROM #ConcernAreas

		WHILE (@iCount <= @iActualRowCount)
		BEGIN
			SELECT @ConcernAreasName=CA.S_Description FROM Academics.T_Concern_Areas CA INNER JOIN #ConcernAreas TCA ON CA.I_Concern_Areas_ID=TCA.Val
			WHERE TCA.ID_Num=@iCount

			Set @Comments=@ConcernAreasName +' updated successfully'
			EXEC uspWriteBatchProcessLog @I_Process_ID_Max,'CONCERN_AREA_NC',@Comments,'Success'

			SET @iCount = @iCount + 1
		END

COMMIT TRAN T1
END TRY

BEGIN CATCH
--Error occurred:
	ROLLBACK  TRAN T1
	DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int
	SELECT @ErrMsg = ERROR_MESSAGE(),
	@ErrSeverity = ERROR_SEVERITY()

	RAISERROR(@ErrMsg, @ErrSeverity, 1)
END CATCH
GO
PRINT N'Creating Procedure [ACADEMICS].[uspUpdateStudentStatus]...';


GO

CREATE PROCEDURE [ACADEMICS].[uspUpdateStudentStatus]
AS 
    BEGIN
	--EXEC ACADEMICS.uspStudentWaitingStatus----2
	--EXEC ACADEMICS.uspGetStudentDefaulterStatus---3
	--EXEC ACADEMICS.uspGetStudentDropoutStatus-----4
	--EXEC ACADEMICS.uspGetStudentCompletedStatus---5
	--EXEC ACADEMICS.uspGetStudentLeaveStatus-------6
	--EXEC ACADEMICS.uspGetStudentDiscontinueStatus--7
	--EXEC ACADEMICS.uspStudentActiveStatus-----1
        DECLARE @dtDate DATETIME= GETDATE() ;

        CREATE TABLE #temp
            (
              I_Student_Detail_ID INT ,
              S_Mobile_No VARCHAR(50) ,
              S_Student_ID VARCHAR(100) ,
              I_Roll_No INT ,
              S_Student_Name VARCHAR(200) ,
              S_Invoice_No VARCHAR(100) ,
              S_Receipt_No VARCHAR(100) ,
              Dt_Invoice_Date DATETIME ,
              I_Fee_Component_ID INT,
              S_Component_Name VARCHAR(100) ,
              I_Batch_ID INT,
              S_Batch_Name VARCHAR(100) ,
              S_Course_Name VARCHAR(100) ,
              I_Center_ID INT ,
              S_Center_Name VARCHAR(100) ,
              TypeofCentre VARCHAR(MAX),
              S_Brand_Name VARCHAR(100) ,
              S_Cost_Center VARCHAR(100) ,
              Due_Value REAL ,
              Dt_Installment_Date DATETIME ,
              I_Installment_No INT ,
              I_Parent_Invoice_ID INT ,
              I_Invoice_Detail_ID INT ,
              Revised_Invoice_Date DATETIME ,
              Tax_Value DECIMAL(14, 2) ,
              Total_Value DECIMAL(14, 2) ,
              Amount_Paid DECIMAL(14, 2) ,
              Tax_Paid DECIMAL(14, 2) ,
              Total_Paid DECIMAL(14, 2) ,
              Total_Due DECIMAL(14, 2) ,
              IsGSTImplemented INT,
              Age INT,
              instanceChain VARCHAR(MAX)
            )

        INSERT  INTO #temp
                EXEC REPORT.uspGetDueReport_History @sHierarchyList = '54', -- varchar(max)
                    @iBrandID = 109, -- int
                    @dtUptoDate = @dtDate, -- datetime
                    @sStatus = 'ALL' -- varchar(100)
                    
        --INSERT  INTO #temp
        --        EXEC REPORT.uspGetDueReport_History @sHierarchyList = '93', -- varchar(max)
        --            @iBrandID = 111, -- int
        --            @dtUptoDate = @dtDate, -- datetime
        --            @sStatus = 'ALL' -- varchar(100)
                    
                                
	
	
	
	
	
        CREATE TABLE #temp1
            (
              ID INT IDENTITY(1, 1) ,
              I_Student_Detail_ID INT ,
              S_Student_ID VARCHAR(MAX) ,
              S_Title VARCHAR(MAX) ,
              StudentName VARCHAR(MAX) ,
              S_Batch_Name VARCHAR(MAX) ,
              I_Center_ID INT ,
              S_Center_Name VARCHAR(MAX) ,
              S_Brand_Name VARCHAR(MAX) ,
              N_Due DECIMAL(14, 2) ,
              Discontinued INT ,
              Dropout INT ,
              IsOnLeave INT ,
              Defaulter INT,
              Waiting INT,
              Completed INT,
			  PreDefaulter INT,
			  DefaulterDate DATETIME,
			  PayDue INT,
			  PayDueDate Datetime
            )
	
        INSERT  INTO #temp1
                ( I_Student_Detail_ID ,
                  S_Student_ID ,
                  S_Title ,
                  StudentName ,
                  S_Batch_Name ,
                  I_Center_ID ,
                  S_Center_Name ,
                  S_Brand_Name ,
                  N_Due ,
                  Discontinued ,
                  Dropout ,
                  IsOnLeave ,
                  Defaulter,
                  Waiting,
                  Completed,
				  PreDefaulter,
				  DefaulterDate,
				  PayDue,
				  PayDueDate
	          )
                SELECT  T1.I_Student_Detail_ID ,
                        T1.S_Student_ID ,
                        T1.S_Title ,
                        T1.StudentName ,
                        T1.S_Batch_Name ,
                        T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.S_Brand_Name ,
                        ISNULL(T3.TotalDue, 0.0) AS NDue ,
                        T1.Discontinued ,
                        T1.Dropout ,
                        CASE WHEN T2.IsOnLeave IS NULL THEN 0
                             WHEN T2.IsOnLeave = 1 THEN 1
                        END AS IsOnLeave ,
                        CASE WHEN T3.Defaulter IS NULL THEN 0
                             WHEN T3.Defaulter = 1 THEN 1
                        END AS Defaulter,
                        T1.Waiting,
                        T1.Completed,
						CASE WHEN T4.PreDefaulter IS NULL THEN 0
                             WHEN T4.PreDefaulter = 1 THEN 1
                        END AS PreDefaulter,
						T4.PreDefaulterDate,
						CASE WHEN T5.PayDue IS NULL THEN 0
                             WHEN T5.PayDue = 1 THEN 1
                        END AS PayDue,
						T5.InstalmentDate
                FROM    ( SELECT    TSD.I_Student_Detail_ID ,
                                    TSD.S_Student_ID ,
                                    CASE WHEN TERD.I_Sex_ID = 1 THEN 'Mr.'
                                         WHEN TERD.I_Sex_ID = 2 THEN 'Ms.'
                                    END AS S_Title ,
                                    TSD.S_First_Name + ' '
                                    + ISNULL(TSD.S_Middle_Name, '') + ' '
                                    + TSD.S_Last_Name AS StudentName ,
                                    TSBM.S_Batch_Name ,
                                    TCHND.I_Center_ID ,
                                    TCHND.S_Center_Name ,
                                    TCHND.S_Brand_Name ,
                                    1 - TSD.I_Status AS Discontinued ,
                                    --dbo.fnGetAcademicDropOutStatus(TSBM.I_Batch_ID,
                                    --                          TSD.I_Student_Detail_ID,
                                    --                          NULL) AS Dropout,
									1 AS Dropout,
                                    --dbo.fnGetWaitingStatus(TSD.I_Student_Detail_ID) AS Waiting,
									1 AS Waiting,
                                    dbo.fnGetCompletedStatus(TSD.I_Student_Detail_ID) AS Completed                         
                          FROM      dbo.T_Student_Detail TSD
                                    INNER JOIN ( SELECT T1.I_Student_ID ,
                                                        T2.I_Batch_ID
                                                 FROM   ( SELECT
                                                              TSBD2.I_Student_ID ,
                                                              MAX(TSBD2.I_Student_Batch_ID) AS ID
                                                          FROM
                                                              dbo.T_Student_Batch_Details TSBD2
                                                          WHERE
                                                              TSBD2.I_Status IN (
                                                              1, 3 )
                                                          GROUP BY TSBD2.I_Student_ID
                                                        ) T1
                                                        INNER JOIN ( SELECT
                                                              TSBD3.I_Student_ID ,
                                                              TSBD3.I_Student_Batch_ID AS ID ,
                                                              TSBD3.I_Batch_ID
                                                              FROM
                                                              dbo.T_Student_Batch_Details TSBD3
                                                              WHERE
                                                              TSBD3.I_Status IN (
                                                              1, 3 )
                                                              ) T2 ON T1.I_Student_ID = T2.I_Student_ID
                                                              AND T1.ID = T2.ID
                                               ) TSBD ON TSD.I_Student_Detail_ID = TSBD.I_Student_ID
                                    INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD.I_Batch_ID = TSBM.I_Batch_ID
                                    INNER JOIN dbo.T_Center_Batch_Details TCBD ON TSBM.I_Batch_ID = TCBD.I_Batch_ID
                                    INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TCBD.I_Centre_Id = TCHND.I_Center_ID
                                    INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                          WHERE     TCHND.I_Brand_ID IN ( 109 )
                                    AND (TSD.S_Student_ID LIKE '%/RICE/%') 
									AND LEN(TSD.S_Student_ID)<=16
                        ) T1
                        LEFT JOIN ( SELECT  TSLR.I_Student_Detail_ID ,
                                            1 AS IsOnLeave
                                    FROM    dbo.T_Student_Leave_Request TSLR
                                    WHERE   TSLR.I_Status = 1
                                            AND @dtDate BETWEEN TSLR.Dt_From_Date
                                                        AND   TSLR.Dt_To_Date
                                  ) T2 ON T1.I_Student_Detail_ID = T2.I_Student_Detail_ID
                        LEFT JOIN ( SELECT  DISTINCT
                                            XX.S_Student_ID ,
                                            XX.TotalDue ,
                                            1 AS Defaulter
                                    FROM    ( SELECT    S_Student_ID ,
                                                        SUM(ISNULL(Total_Due,
                                                              0)) AS TotalDue
                                              FROM      #temp TTT
											  inner join T_Student_Batch_Master TSBM on TTT.I_Batch_ID=TSBM.I_Batch_ID
                                              WHERE     DATEDIFF(d,
                                                              CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END,
                                                              GETDATE()) >= 31
                                                        --AND T1.S_Student_ID=@Sstudentid      
                                              GROUP BY  S_Student_ID
                                            ) XX
                                    WHERE   XX.TotalDue >= 100
                                  ) T3 ON T1.S_Student_ID = T3.S_Student_ID
						LEFT JOIN ( SELECT  DISTINCT
                                            XX.S_Student_ID ,
                                            XX.TotalDue ,
											XX.PreDefaulterDate,
                                            1 AS PreDefaulter
                                    FROM    ( SELECT    S_Student_ID ,
                                                        SUM(ISNULL(Total_Due,
                                                              0)) AS TotalDue,
														MIN(DATEADD(d,31-DATEDIFF(d,
                                                              CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END,
                                                              GETDATE()),GETDATE())) as PreDefaulterDate
                                              FROM      #temp TTT
											  inner join T_Student_Batch_Master TSBM on TTT.I_Batch_ID=TSBM.I_Batch_ID
                                              WHERE     
												DATEDIFF(d,
                                                              CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END,
                                                              GETDATE()) >= 11
														AND
														DATEDIFF(d,
                                                              CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END,
                                                              GETDATE()) < 31
                                                        --AND T1.S_Student_ID=@Sstudentid      
                                              GROUP BY  S_Student_ID
                                            ) XX
                                    WHERE   XX.TotalDue >= 100
                                  ) T4 ON T1.S_Student_ID = T4.S_Student_ID
								  LEFT JOIN ( SELECT  DISTINCT
                                            XX.S_Student_ID ,
                                            XX.TotalDue ,
											XX.InstalmentDate,
                                            1 AS PayDue
                                    FROM    ( SELECT    S_Student_ID ,
                                                        SUM(ISNULL(Total_Due,
                                                              0)) AS TotalDue,
														MIN(CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END) as InstalmentDate
                                              FROM      #temp TTT
											  inner join T_Student_Batch_Master TSBM on TTT.I_Batch_ID=TSBM.I_Batch_ID
                                              WHERE     DATEDIFF(d,
                                                              CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END,
                                                              GETDATE()) >=1
														and
														DATEDIFF(d,
                                                              CASE WHEN TSBM.Dt_BatchStartDate>TTT.Dt_Installment_Date THEN TSBM.Dt_BatchStartDate
															  ELSE TTT.Dt_Installment_Date END,
                                                              GETDATE()) <=10
                                                        --AND T1.S_Student_ID=@Sstudentid      
                                              GROUP BY  S_Student_ID
                                            ) XX
                                    WHERE   XX.TotalDue >= 100
                                  ) T5 ON T1.S_Student_ID = T5.S_Student_ID
                                              
        DECLARE @std INT
        DECLARE @due INT
        DECLARE @discon INT
        DECLARE @drop INT
        DECLARE @leave INT
        DECLARE @defaulter INT
        DECLARE @waiting INT
        DECLARE @completed INT
		DECLARE @predefaulter INT
		DECLARE @defaulterdate DATETIME=NULL
		DECLARE @paydue INT
		DECLARE @payduedate datetime
        
        DROP TABLE #temp
		
        DECLARE StatusUpdator CURSOR
        FOR
        SELECT I_Student_Detail_ID,N_Due,Discontinued,Dropout,IsOnLeave,Defaulter,Waiting,
		Completed,PreDefaulter,DefaulterDate,PayDue,PayDueDate
		FROM #temp1 T1 
		
        OPEN StatusUpdator
        FETCH NEXT FROM StatusUpdator
		INTO
		@std,@due,@discon,@drop,@leave,@defaulter,@waiting,@completed,@predefaulter,@defaulterdate,@paydue,@payduedate
		
        WHILE ( @@FETCH_STATUS = 0 ) 
            BEGIN
                INSERT  INTO dbo.T_Student_Status_Details_Archive
                        ( I_Student_Detail_ID ,
                          I_Student_Status_ID ,
                          I_Status ,
                          N_Due ,
                          Dt_Crtd_On ,
                          Dt_Upd_On ,
                          S_Crtd_By ,
                          S_Upd_By ,
                          IsEditable,
						  DefaulterDate
                        )
                        SELECT  I_Student_Detail_ID ,
                                I_Student_Status_ID ,
                                I_Status ,
                                N_Due ,
                                Dt_Crtd_On ,
                                Dt_Upd_On ,
                                S_Crtd_By ,
                                S_Upd_By ,
                                IsEditable,
								DefaulterDate
                        FROM    dbo.T_Student_Status_Details TSSD
                        WHERE   TSSD.I_Status = 1
                                AND TSSD.I_Student_Detail_ID = @std
                                AND CONVERT(DATE, TSSD.Dt_Crtd_On) < CONVERT(DATE, @dtDate)
			
                DELETE  FROM dbo.T_Student_Status_Details
                WHERE   I_Student_Detail_ID = @std
                        AND IsEditable = 1
			
                IF ( 
						@discon = 0
                     AND @drop = 0
      --               AND @leave = 0
      --               AND @waiting=0
      --               AND @completed=0
					 AND @defaulter = 0
                   ) 
                    BEGIN
                        INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  1 , -- I_Student_Status_ID - int
                                  1 , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )
				        
                    END
			
                ELSE 
                    BEGIN
                    
                    
						INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  2 , -- I_Student_Status_ID - int
                                  @waiting , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )
                    
                        INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  3 , -- I_Student_Status_ID - int
                                  @defaulter , -- I_Status - int
                                  @due , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )
				        
				        
                        INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  4 , -- I_Student_Status_ID - int
                                  @drop , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )
				        
                        INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  6 , -- I_Student_Status_ID - int
                                  @leave , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )
				        
				        
                        INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  7 , -- I_Student_Status_ID - int
                                  @discon , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )
				        
				        INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  5 , -- I_Student_Status_ID - int
                                  @completed , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1  -- IsEditable - bit
				        )


						IF((@defaulter=0 OR @defaulter is NULL) and @defaulterdate is not null)
						BEGIN

							INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable,
								  DefaulterDate
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  8 , -- I_Student_Status_ID - int
                                  @predefaulter , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1,  -- IsEditable - bit
								  @defaulterdate
				        )


						END

						----
						IF((@defaulter=0 OR @defaulter is NULL) and (@predefaulter=0 OR @predefaulter is null) and @payduedate is not null)
						BEGIN

							INSERT  INTO dbo.T_Student_Status_Details
                                ( I_Student_Detail_ID ,
                                  I_Student_Status_ID ,
                                  I_Status ,
                                  N_Due ,
                                  Dt_Crtd_On ,
                                  Dt_Upd_On ,
                                  S_Crtd_By ,
                                  S_Upd_By ,
                                  IsEditable,
								  DefaulterDate
				        )
                        VALUES  ( @std , -- I_Student_Detail_ID - int
                                  9 , -- I_Student_Status_ID - int
                                  @paydue , -- I_Status - int
                                  NULL , -- N_Due - decimal
                                  @dtDate , -- Dt_Crtd_On - datetime
                                  NULL , -- Dt_Upd_On - datetime
                                  'dba' , -- S_Crtd_By - varchar(50)
                                  NULL , -- S_Upd_By - varchar(50)
                                  1,  -- IsEditable - bit
								  @payduedate
				        )


						END

						--DECLARE @studentID VARCHAR(MAX)

						--SELECT @studentID=S_Student_ID FROM T_Student_Detail WHERE I_Student_Detail_ID=@std

						--EXEC [LMS].[uspUpdateStudentStatus] @studentID,'Defaulter',@defaulter,@due,NULL
						--EXEC [LMS].[uspUpdateStudentStatus] @studentID,'Completed',@completed,NULL,NULL
						--EXEC [LMS].[uspUpdateStudentStatus] @studentID,'Discontinued',@discon,NULL,NULL
						----EXEC [LMS].[uspUpdateStudentStatus] @studentID,'Leave',@leave,NULL,NULL
						--EXEC [LMS].[uspUpdateStudentStatus] @studentID,'PreDefaulter',@predefaulter,NULL,@defaulterdate
						--EXEC [LMS].[uspUpdateStudentStatus] @studentID,'PaymentDue',@paydue,NULL,@payduedate

				        
                    END
                    
                    FETCH NEXT FROM StatusUpdator
                    INTO
                    @std,@due,@discon,@drop,@leave,@defaulter,@waiting, @completed, @predefaulter,@defaulterdate,@paydue,@payduedate
			
            END
		
        CLOSE StatusUpdator ;
        DEALLOCATE StatusUpdator ;  
        
        
        DROP TABLE #temp1                                       
	
	
    END
