PRINT N'Creating Procedure [ECOMMERCE].[uspGenerateCouponForCampaign]...';


GO

CREATE procedure [ECOMMERCE].[uspGenerateCouponForCampaign]
(
	@CampaignName VARCHAR(MAX),
	@MarksObtained DECIMAL(14,2),
	@CustomerID VARCHAR(MAX),
	@ValidFrom DATETIME=NULL,
	@ValidTo DATETIME=NULL,
	@LanguageID INT=NULL --susmita
)
AS
BEGIN

	DECLARE @CampaignID INT=0
	DECLARE @DiscountID INT=0
	DECLARE @MapID INT=0
	DECLARE @CouponName VARCHAR(MAX),
			@CouponPrefix VARCHAR(MAX),
			@CouponTypeID INT,
			@CouponCount INT,
			@GenerationCount INT
	DECLARE @CouponCode VARCHAR(MAX)=''
	DECLARE @sBrandID VARCHAR(MAX)=''
	DECLARE @DiscountLumpsumPerc DECIMAL(14,2)=0
	DECLARE @DiscountInstalmentPerc DECIMAL(14,2)=0
	DECLARE @MessageDesc VARCHAR(MAX)=''
	DECLARE @MobileNo VARCHAR(MAX)=''
	DECLARE @RegID INT


	DECLARE @Coupon TABLE
	(
		CouponID INT
	)

	DECLARE @Brand TABLE
	(
		ID INT IDENTITY(1,1),
		BrandID INT
	)

	DECLARE @Plan TABLE
	(
		ID INT IDENTITY(1,1),
		PlanID INT
	)


	BEGIN TRY

		BEGIN TRANSACTION


		IF NOT EXISTS (select * from ECOMMERCE.T_Registration where CustomerID=@CustomerID and StatusID=1)
		BEGIN

			RAISERROR('Invalid CustomerID',11,1)

		END


		SELECT @MobileNo=MobileNo,@RegID=RegID FROM ECOMMERCE.T_Registration WHERE CustomerID=@CustomerID

		select @CampaignID=ISNULL(CampaignID,0) 
		from ECOMMERCE.T_Campaign_Master 
		where 
		StatusID=1 and CampaignName=@CampaignName and CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,ValidTo)>=CONVERT(DATE,GETDATE())

		IF(@CampaignID IS NULL OR @CampaignID=0)
		BEGIN

			RAISERROR('No such campaign exists',11,1)

		END


		IF(@ValidFrom IS NULL and @CampaignID>0)
		BEGIN

			select @ValidFrom=ValidFrom
			from ECOMMERCE.T_Campaign_Master 
			where CampaignID=@CampaignID

		END

		IF(@ValidTo IS NULL and @CampaignID>0)
		BEGIN

			select @ValidTo=ValidTo
			from ECOMMERCE.T_Campaign_Master 
			where CampaignID=@CampaignID

		END


		select @DiscountID=ISNULL(DiscountID,0),@MapID=ISNULL(ID,0) 
		from ECOMMERCE.T_Campaign_Discount_Map
		where
		CampaignID=@CampaignID and StatusID=1 and CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE()) and CONVERT(DATE,ValidTo)>=CONVERT(DATE,GETDATE())
		and
		FromMarks<=@MarksObtained and ToMarks>=@MarksObtained

		--IF((@DiscountID IS NULL OR @DiscountID=0) and @MapID>0)
		--BEGIN

		--	select '' as CouponCode, 0 as LumpsumDiscount,0 as InstalmentDiscount, @MessageDesc as MessageDesc

		--END


		IF(@DiscountID>0 and @MapID>0)
		BEGIN

			DECLARE @i INT=1
			DECLARE @c INT=0


			select @DiscountLumpsumPerc=SUM(ISNULL(N_Discount_Rate,0)) from T_Discount_Scheme_Details where I_Discount_Scheme_ID=@DiscountID and I_IsApplicableOn=1
			select @DiscountInstalmentPerc=SUM(ISNULL(N_Discount_Rate,0)) from T_Discount_Scheme_Details where I_Discount_Scheme_ID=@DiscountID and I_IsApplicableOn=2


			select 
			@CouponPrefix=CouponPrefix,
			@CouponName=CouponName,
			@CouponCount=CouponCount,
			@CouponTypeID=CouponTypeID,
			@GenerationCount=ISNULL(GenerationCount,0),
			@MessageDesc=ISNULL(MessageDesc,'')
			from ECOMMERCE.T_Campaign_Discount_Map where ID=@MapID

			--select * from ECOMMERCE.T_Campaign_Discount_Map where ID=@MapID

			--select 
			--@CouponPrefix,
			--@CouponName,
			--@CouponCount,
			--@CouponTypeID,
			--@GenerationCount


			insert into @Brand
			select BrandID from ECOMMERCE.T_Campaign_Brand_Map where CampaignID=@CampaignID and StatusID=1


			select @c=COUNT(*) from @Brand

			while(@i<=@c)
			BEGIN

				set @sBrandID=@sBrandID+(select CAST(BrandID as VARCHAR(MAX)) from @Brand where ID=@i)


				set @i=@i+1

			END


			set @GenerationCount=@GenerationCount+1

			update ECOMMERCE.T_Campaign_Discount_Map set GenerationCount=@GenerationCount where ID=@MapID

			set @CouponCode=@CouponPrefix+CAST(@GenerationCount as VARCHAR(MAX))

			insert into @Coupon
			exec [ECOMMERCE].[uspSaveCoupon] @CouponCode,@CouponName,@CouponName,@sBrandID,@DiscountID,3,@CouponTypeID,@CouponCount,0,@CustomerID,@ValidFrom,@ValidTo,@MapID

			--select * from @Coupon

			IF((select COUNT(*) from @Coupon)=1)
			BEGIN

				DECLARE @CouponID INT=0

				select @CouponID=ISNULL(CouponID,0) from @Coupon

				IF (@CouponID IS NULL OR @CouponID=0)
				BEGIN

					RAISERROR('No coupon could be generated',11,1)

				END

				IF(@CouponID>0)
				BEGIN

					insert into @Plan
					select DISTINCT PlanID from
					(
						select A.I_Discount_Scheme_ID,A.I_Centre_ID,B.I_Course_ID
						from 
						T_Discount_Center_Detail A
						inner join T_Discount_Course_Detail B on A.I_Discount_Center_Detail_ID=B.I_Discount_Centre_Detail_ID
						where
						A.I_Discount_Scheme_ID=@DiscountID and A.I_Status=1 and B.I_Status=1
					) T1
					inner join
					(
						select A.PlanID,C.CourseID,D.CenterID 
						from ECOMMERCE.T_Plan_Master A
						inner join ECOMMERCE.T_Plan_Product_Map B on A.PlanID=B.PlanID and B.StatusID=1
						inner join ECOMMERCE.T_Product_Master C on B.ProductID=C.ProductID
						inner join ECOMMERCE.T_Product_Center_Map D on B.ProductID=D.ProductID
						where
						C.StatusID=1 and D.StatusID=1 and A.StatusID=1 and CONVERT(DATE,ISNULL(A.ValidTo,GETDATE()))>=CONVERT(DATE,GETDATE())
						and A.IsPublished=1 and C.IsPublished=1
						and A.I_Language_ID=@LanguageID--susmita
					) T2 on T1.I_Centre_ID=T2.CenterID and T1.I_Course_ID=T2.CourseID


					DECLARE @j INT=1
					DECLARE @cc INT=0

					select @cc=COUNT(*) from @Plan

					IF (@cc=0)
					BEGIN

						RAISERROR('No suitable Plans present',11,1)

					END
					ELSE
					BEGIN

						insert into ECOMMERCE.T_Campaign_Coupon_Details
						(
							CamapaignID,
							CampaignDiscountMapID,
							CouponID,
							CustomerID,
							MarksObtained,
							MessageDesc,
							CreatedOn,
							CreatedBy
						)
						select 
						@CampaignID,
						@MapID,
						@CouponID,
						@CustomerID,
						@MarksObtained,
						REPLACE(MessageDesc,'[mark%]',CAST(@MarksObtained as NVARCHAR(10))+'%') as MessageDesc,
						GETDATE(),
						'rice-group-admin'
						from 
						ECOMMERCE.T_Campaign_Discount_Map where ID=@MapID

					END

					WHILE(@j<=@cc)
					BEGIN
					
						DECLARE @PlanID INT

						select @PlanID=PlanID from @Plan where ID=@j

						exec [ECOMMERCE].[uspSaveCouponPlanMap] @CouponID,@PlanID,NULL,NULL

						set @j=@j+1


					END


					if(@cc>0)
					BEGIN

					IF ((SELECT SMSTypeID FROM ECOMMERCE.T_Campaign_Discount_Map WHERE ID=@MapID) IS NOT NULL)
					BEGIN

						INSERT INTO dbo.T_SMS_SEND_DETAILS
						(
						    S_MOBILE_NO,
						    I_SMS_STUDENT_ID,
						    I_SMS_TYPE_ID,
						    S_SMS_BODY,
						    I_IS_SUCCESS,
						    I_NO_OF_ATTEMPT,
						    S_RETURN_CODE_FROM_PROVIDER,
						    I_REFERENCE_ID,
						    I_REFERENCE_TYPE_ID,
						    Dt_SMS_SEND_ON,
						    I_Status,
						    S_Crtd_By,
						    S_Upd_By,
						    Dt_Crtd_On,
						    Dt_Upd_On
						)
						
						SELECT 
							@MobileNo,
							@RegID,
							A.SMSTypeID,
							REPLACE(REPLACE(B.S_SMS_BODY_TEMPLATE,'[MARK]',CAST(@MarksObtained as NVARCHAR(10))+'%'),'[CODE]',@CouponCode),
							0,
							0,
							'',
							@RegID,
							B.I_REFERENCE_TYPE_ID,
							NULL,
							1,
							'rice-group-admin',
							NULL,
							GETDATE(),
							NULL
						FROM 
						ECOMMERCE.T_Campaign_Discount_Map A
						INNER JOIN dbo.T_SMS_TYPE_MASTER B ON A.SMSTypeID=B.I_SMS_TYPE_ID AND B.I_Status=1
						WHERE A.ID=@MapID

						END


						select @CouponCode as CouponCode, @DiscountLumpsumPerc as LumpsumDiscount,@DiscountInstalmentPerc as InstalmentDiscount, @MessageDesc as MessageDesc
					END
					else
						select '' as CouponCode, @DiscountLumpsumPerc as LumpsumDiscount,@DiscountInstalmentPerc as InstalmentDiscount, @MessageDesc as MessageDesc

				END
			END


		END

		ELSE IF (@DiscountID=0 and @MapID>0)
		BEGIN

			select 
			@MessageDesc=ISNULL(MessageDesc,'')
			from ECOMMERCE.T_Campaign_Discount_Map where ID=@MapID

			select 'N/A' as CouponCode, 0 as LumpsumDiscount,0 as InstalmentDiscount, @MessageDesc as MessageDesc

		END

		COMMIT TRANSACTION

	END TRY
    BEGIN CATCH
	--Error occurred:  
        ROLLBACK TRANSACTION
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()

        RAISERROR(@ErrMsg, @ErrSeverity, 1)
    END CATCH

	

END
GO
PRINT N'Creating Procedure [ECOMMERCE].[uspGetPrintFeeScheduleDetails]...';


GO
CREATE procedure [ECOMMERCE].[uspGetPrintFeeScheduleDetails](@FeeScheduleID INT)
AS
BEGIN

	DECLARE @StudentDetailID INT
	DECLARE @CenterID INT
	DECLARE @BatchID INT
	DECLARE @InvoiceNo VARCHAR(MAX)
	DECLARE @FeeScheduleDate DATETIME

	CREATE TABLE #InvSummary
	(
		S_Course_Name VARCHAR(MAX),
		S_SAC_Code VARCHAR(MAX),
		Course_Amt DECIMAL(14,2),
		Discount DECIMAL(14,2),
		OLD_TAX DECIMAL(14,2),
		S_SGST_Tax DECIMAL(14,2),
		S_CGST_Tax DECIMAL(14,2),
		S_IGST_Tax DECIMAL(14,2),
		TaxAmt DECIMAL(14,2),
		Total DECIMAL(14,2)
	)

	CREATE TABLE #InvDetails
	(
		I_Invoice_Header_ID INT, 
		I_Installment_No INT,   
		Dt_Installment_Date DATETIME,  
		N_Amount_Due DECIMAL(14,2),   
		N_Discount_Amount DECIMAL(14,2),   
		N_Advance_Amount DECIMAL(14,2),  
		N_Net_Amount DECIMAL(14,2),  
		S_Invoice_Number VARCHAR(MAX),  
		Invoice_Type VARCHAR(10),
		CGST DECIMAL(14,2),
		SGST DECIMAL(14,2),
		IGST DECIMAL(14,2)
	)


	select TOP 1 @StudentDetailID=A.I_Student_Detail_ID,@CenterID=A.I_Centre_Id,@BatchID=C.I_Batch_ID,@InvoiceNo=A.S_Invoice_No,@FeeScheduleDate=A.Dt_Invoice_Date
	from T_Invoice_Parent A
	inner join T_Invoice_Child_Header B on A.I_Invoice_Header_ID=B.I_Invoice_Header_ID
	inner join T_Invoice_Batch_Map C on B.I_Invoice_Child_Header_ID=C.I_Invoice_Child_Header_ID
	where
	A.I_Invoice_Header_ID=@FeeScheduleID

	insert into #InvSummary
	exec [dbo].[uspGetInvoiceSummary] @FeeScheduleID

	insert into #InvDetails
	(
		I_Invoice_Header_ID, 
		I_Installment_No,   
		Dt_Installment_Date,  
		N_Amount_Due,   
		N_Discount_Amount,   
		N_Advance_Amount,  
		N_Net_Amount,  
		S_Invoice_Number,  
		Invoice_Type
	)
	exec [dbo].[uspGetInvoiceDetailRevisedGST] @iInvoiceHeaderID=@FeeScheduleID


	update T1
	set
	T1.CGST=T2.CGST
	from
	#InvDetails T1
	inner join
	(
		select C.I_Invoice_Header_ID,B.S_Invoice_Number,A.N_Tax_Value as CGST
		from T_Invoice_Detail_Tax A
		inner join T_Invoice_Child_Detail B on A.I_Invoice_Detail_ID=B.I_Invoice_Detail_ID
		inner join T_Invoice_Child_Header C on B.I_Invoice_Child_Header_ID=C.I_Invoice_Child_Header_ID
		inner join T_Tax_Master D on A.I_Tax_ID=D.I_Tax_ID and D.I_Status=1
		where
		B.I_Installment_No>0 and D.S_Tax_Code COLLATE DATABASE_DEFAULT='CGST' COLLATE DATABASE_DEFAULT
	) T2 on T1.I_Invoice_Header_ID=T2.I_Invoice_Header_ID and T1.S_Invoice_Number COLLATE DATABASE_DEFAULT=T2.S_Invoice_Number COLLATE DATABASE_DEFAULT


	update T1
	set
	T1.SGST=T2.SGST
	from
	#InvDetails T1
	inner join
	(
		select C.I_Invoice_Header_ID,B.S_Invoice_Number,A.N_Tax_Value as SGST
		from T_Invoice_Detail_Tax A
		inner join T_Invoice_Child_Detail B on A.I_Invoice_Detail_ID=B.I_Invoice_Detail_ID
		inner join T_Invoice_Child_Header C on B.I_Invoice_Child_Header_ID=C.I_Invoice_Child_Header_ID
		inner join T_Tax_Master D on A.I_Tax_ID=D.I_Tax_ID and D.I_Status=1
		where
		B.I_Installment_No>0 and D.S_Tax_Code COLLATE DATABASE_DEFAULT='SGST' COLLATE DATABASE_DEFAULT
	) T2 on T1.I_Invoice_Header_ID=T2.I_Invoice_Header_ID and T1.S_Invoice_Number COLLATE DATABASE_DEFAULT=T2.S_Invoice_Number COLLATE DATABASE_DEFAULT




	--Table 0
	SELECT CHND.S_Brand_Name,CHND.I_Center_ID,CHND.S_Center_Name,NCA.S_Center_Address1,TCM.S_City_Name,
				TSM.S_State_Name,TCM2.S_Country_Name,NCA.S_Pin_Code,NCA.S_Email_ID,NCA.S_Telephone_No,GCM.*,
				ISNULL(TBM.S_CIN,'NA') AS CIN,
				ISNULL(TBM.S_PAN,'NA') AS PAN
	FROM 
	dbo.T_GST_Code_Master AS GCM
	INNER JOIN dbo.T_State_Master AS SM ON GCM.I_State_ID = SM.I_State_ID AND GCM.I_Status = 1 AND SM.I_Status = 1
	INNER JOIN NETWORK.T_Center_Address AS NCA ON SM.I_State_ID = NCA.I_State_ID
	INNER JOIN dbo.T_Invoice_Parent AS IP ON NCA.I_Centre_Id = IP.I_Centre_Id
	INNER JOIN T_Center_Hierarchy_Name_Details CHND ON IP.I_Centre_Id = CHND.I_Center_ID AND GCM.I_Brand_ID = CHND.I_Brand_ID
	inner join T_City_Master TCM on NCA.I_City_ID=TCM.I_City_ID
	inner join T_State_Master TSM on NCA.I_State_ID=TSM.I_State_ID
	inner join T_Country_Master TCM2 on NCA.I_Country_ID=TCM2.I_Country_ID
	inner join T_Brand_Master TBM on CHND.I_Brand_ID=TBM.I_Brand_ID
	WHERE IP.I_Invoice_Header_ID = @FeeScheduleID


	--Table 1
	select NCA.I_Student_Detail_ID,NCA.S_Student_ID,NCA.S_First_Name+' '+ISNULL(NCA.S_Middle_Name,'')+' '+NCA.S_Last_Name as StudentName,NCA.S_Curr_Address1,
			TCM.S_City_Name,TSM.S_State_Name,TCM2.S_Country_Name,NCA.S_Curr_Pincode,TR.CustomerID,NCA.S_Email_ID,NCA.S_Mobile_No
	from T_Student_Detail NCA
	inner join T_City_Master TCM on NCA.I_Curr_City_ID=TCM.I_City_ID
	inner join T_State_Master TSM on NCA.I_Curr_State_ID=TSM.I_State_ID
	inner join T_Country_Master TCM2 on ISNULL(NCA.I_Curr_Country_ID,1)=TCM2.I_Country_ID
	inner join ECOMMERCE.T_Registration_Enquiry_Map TREM on NCA.I_Enquiry_Regn_ID=TREM.EnquiryID
	inner join ECOMMERCE.T_Registration TR on TREM.RegID=TR.RegID
	where
	NCA.I_Student_Detail_ID=@StudentDetailID


	--Table 2
	select I_Batch_ID,S_Batch_Name,@InvoiceNo as InvoiceNo, @FeeScheduleDate as FeeScheduleDate 
	from T_Student_Batch_Master where I_Batch_ID=@BatchID

	--Table 3
	select * from #InvSummary


	--Table 4
	select I_Invoice_Header_ID,I_Installment_No,Dt_Installment_Date,S_Invoice_Number,Invoice_Type,
	SUM(N_Amount_Due) as DueAmount,
	SUM(N_Discount_Amount) as DiscountAmount,
	SUM(N_Advance_Amount) as AdvanceAmount,
	SUM(N_Net_Amount) as NetAmount,
	SUM(CGST) as CGST,
	SUM(SGST) as SGST
	from #InvDetails
	group by I_Invoice_Header_ID,I_Installment_No,Dt_Installment_Date,S_Invoice_Number,Invoice_Type

	--Table 5
	select C.PlanName,D.ProductName 
	from ECOMMERCE.T_Transaction_Product_Details A
	inner join ECOMMERCE.T_Transaction_Plan_Details B on A.TransactionPlanDetailID=B.TransactionPlanDetailID
	inner join ECOMMERCE.T_Plan_Master C on B.PlanID=C.PlanID
	inner join ECOMMERCE.T_Product_Master D on D.ProductID=A.ProductID
	where
	A.FeeScheduleID=@FeeScheduleID


END
GO
