GO
/*  
-- =================================================================  
-- Author:Chandan Dey  
-- Modified By :   
-- Create date:06/18/2007   
-- Description:Select List StudentCertificateRequestList record in T_Student_Certificate_Request table   
-- =================================================================  
*/  
  
CREATE PROCEDURE [PSCERTIFICATE].[uspGetStudentCertificateRequestListCF]  
    (  
      @iCenterID INT = null,  
      @iHierarchyDetailID INT = null,  
      @iCourseID INT = null,  
      @iTermID INT = null,  
      @iPSCert INT = null,  
      @iStatusID INT,  
      @iBrandID INT = null,  
      @iFlag INT = NULL,  
      @iCourseFamilyID INT = NULL,  
      @iTemplate INT = NULL,
      @CertificateType CHAR(1) = NULL
   
    )  
AS   
    BEGIN  
  
-- This check for course family   
  
        IF ( @iCourseFamilyID IS NULL )   
            BEGIN  
                EXEC [PSCERTIFICATE].[uspGetStudentCertificateRequestList] @iCenterID,  
                    @iHierarchyDetailID, @iCourseID, @iTermID, @iPSCert,  
                    @iStatusID, @iBrandID, @iFlag  
            END  
        ELSE   
            BEGIN  
  
-- For Get the center using hierarchy id   
  
                DECLARE @sSearchCriteria varchar(20)  
                DECLARE @TempCenter TABLE ( I_Center_ID int )  
  
                IF @iHierarchyDetailID IS NOT NULL   
                    BEGIN  
  
                        SELECT  @sSearchCriteria = S_Hierarchy_Chain  
                        from    T_Hierarchy_Mapping_Details  
                        where   I_Hierarchy_detail_id = @iHierarchyDetailID    
    
                        IF @iBrandId = 0   
                            BEGIN  
                                INSERT  INTO @TempCenter  
                                        SELECT  TCHD.I_Center_Id  
                                        FROM    T_CENTER_HIERARCHY_DETAILS TCHD  
                                        WHERE   TCHD.I_Hierarchy_Detail_ID IN (  
                                                SELECT  I_HIERARCHY_DETAIL_ID  
                                                FROM    T_Hierarchy_Mapping_Details  
                                                WHERE   I_Status = 1  
                                                        AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())  
                                                        AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())  
                                                        AND S_Hierarchy_Chain LIKE @sSearchCriteria  
                                                        + '%' )   
                            END  
                        ELSE   
                            BEGIN  
                                INSERT  INTO @TempCenter  
                                        SELECT  TCHD.I_Center_Id  
                                        FROM    T_CENTER_HIERARCHY_DETAILS TCHD,  
                                                T_BRAND_CENTER_DETAILS TBCD  
                                        WHERE   TCHD.I_Hierarchy_Detail_ID IN (  
                                                SELECT  I_HIERARCHY_DETAIL_ID  
                                                FROM    T_Hierarchy_Mapping_Details  
                                                WHERE   I_Status = 1  
                                                        AND GETDATE() >= ISNULL(Dt_Valid_From, GETDATE())  
                                                        AND GETDATE() <= ISNULL(Dt_Valid_To, GETDATE())  
                                                        AND S_Hierarchy_Chain LIKE @sSearchCriteria  
                                                        + '%' )  
                                                AND TBCD.I_Brand_ID = @iBrandId  
                                                AND TBCD.I_Centre_Id = TCHD.I_Center_Id       
                            END  
                    END  
                ELSE   
                    BEGIN  
                        INSERT  INTO @TempCenter  
                                SELECT  I_Centre_ID  
                         FROM    T_Centre_Master  
                                WHERE   I_Status = 1  
                                        AND I_Centre_ID = @iCenterID    
                    END  
  
  
  
-- For course family  
  
                DECLARE @TemCourse TABLE ( I_Course_ID INT )  
  
  
--IF(@iCourseID IS NULL)  
--BEGIN  
-- INSERT INTO @TemCourse   
-- SELECT I_Course_ID FROM dbo.T_Course_Master  
-- WHERE I_CourseFamily_ID = @iCourseFamilyID  
--END  
--ELSE  
--BEGIN  
-- INSERT INTO @TemCourse(I_Course_ID) VALUES(@iCourseID)  
--END  
                DECLARE @iGetFlag INT  
  
                IF ( @iFlag IS NOT NULL  
                     AND @iPSCert = 0  
                   )   
                    BEGIN  
                        SET @iGetFlag = 2  
                    END  
                ELSE   
                    IF ( @iPSCert = 1 )   
                        BEGIN  
                            SET @iGetFlag = 1  
                        END  
                    ELSE   
                        BEGIN  
                            SET @iGetFlag = 0  
                        END  
  
                IF ( @iCourseID IS NULL )   
                    BEGIN  
                        INSERT  INTO @TemCourse  
                                SELECT  I_Course_ID  
                                FROM    dbo.T_Course_Master  
                                WHERE   I_CourseFamily_ID = @iCourseFamilyID  
                                        AND I_Course_ID IN (  
                                        SELECT  I_Course_ID  
                                        from    [dbo].[fnCourseListFromTemplateID](@iTemplate, @iGetFlag) )  
                    END  
                ELSE   
                    BEGIN  
                        IF EXISTS ( SELECT  I_Course_ID  
                                    from    [dbo].[fnCourseListFromTemplateID](@iTemplate, @iGetFlag)  
                                    WHERE   I_Course_ID = @iCourseID )   
                            BEGIN  
                                INSERT  INTO @TemCourse ( I_Course_ID )  
                                VALUES  ( @iCourseID )  
                            END  
                        ELSE   
                            BEGIN  
                                INSERT  INTO @TemCourse ( I_Course_ID )  
                                VALUES  ( 0 )  
                            END   
                    END  
  
  
  
  
-- For Term   
                DECLARE @TemTermCourse TABLE ( I_Term_ID INT )  
  
  
                IF ( @iTermID IS NULL )   
                    BEGIN  
                        INSERT  INTO @TemTermCourse  
                                SELECT DISTINCT  
                                        I_Term_ID  
                                FROM    dbo.T_Term_Course_Map  
                                WHERE   I_Course_ID IN ( SELECT I_Course_ID  
                                                         FROM   @TemCourse )   
                    END  
                ELSE   
                    BEGIN  
                        INSERT  INTO @TemTermCourse ( I_Term_ID )  
                        VALUES  ( @iTermID )  
                    END  
  
  
                IF ( @iPSCert = 0  
                     AND @iTermID IS NULL  
                     AND @iFlag IS NULL  
                   )   
                    BEGIN  
                        SELECT DISTINCT ISNULL(A.I_Student_Cert_Request_ID, 0) AS I_Student_Cert_Request_ID,  
                                ISNULL(A.I_Student_Certificate_ID, 0) AS I_Student_Certificate_ID,  
                                ( ISNULL(A.S_Student_FName, ' ')  
                                  + ISNULL(A.S_Student_MName, ' ')  
                                  + ISNULL(A.S_Student_LName, ' ') ) AS S_Student_Name,  
                                ISNULL(A.S_Reiss_Reason, ' ') AS S_Reiss_Reason,  
                                ISNULL(A.I_Status, 0) AS I_Status,  
                                ISNULL(A.S_Crtd_By, ' ') AS S_Crtd_By,  
                                ISNULL(A.S_Upd_By, ' ') AS S_Upd_By,  
                                ISNULL(A.Dt_Crtd_On, ' ') AS Dt_Crtd_On,  
                                ISNULL(A.Dt_Upd_On, ' ') AS Dt_Upd_On,  
                                ISNULL(B.I_Student_Detail_ID, 0) AS I_Student_Detail_ID,  
                                ISNULL(C.S_First_Name, '') AS S_First_Name,  
                                ISNULL(C.S_Middle_Name, '') AS S_Middle_Name,  
                                ISNULL(C.S_Last_Name, '') AS S_Last_Name,  
                                ISNULL(B.S_Certificate_Serial_No, '') AS S_Certificate_Serial_No,  
                                ISNULL(CM.S_Center_Name, '') AS S_Center_Name,  
                                CM.I_Centre_ID AS I_Center_ID,  
                                ISNULL(COM.S_Course_Name, '') AS S_Course_Name,  
                                ISNULL(TM.S_Term_Name, '') AS S_Term_Name,  
                                SCD.I_Batch_ID  
                        FROM    [PSCERTIFICATE].T_Student_Certificate_Request A  
                                INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate B ON A.I_Student_Certificate_ID = B.I_Student_Certificate_ID  
                                INNER JOIN [dbo].T_Student_Detail C ON B.I_Student_Detail_ID = C.I_Student_Detail_ID  
                                INNER JOIN [dbo].T_Student_Center_Detail F ON C.I_Student_Detail_ID = F.I_Student_Detail_ID  
                                INNER JOIN dbo.T_Centre_Master CM ON CM.I_Centre_Id = F.I_Centre_Id  
                                INNER JOIN dbo.T_Student_Course_Detail SCD ON SCD.I_Student_Detail_ID = B.I_Student_Detail_ID   
                                AND [SCD].[I_Course_ID] = [B].[I_Course_ID]  
                                INNER JOIN dbo.T_Course_Master COM ON COM.I_Course_ID = SCD.I_Course_ID  
                                LEFT OUTER JOIN [dbo].T_Term_Master TM ON TM.I_Term_ID = B.I_Term_ID  
                        WHERE   --  AND F.I_Centre_ID = COALESCE(@iCenterID, F.I_Centre_ID)  
                                F.I_Centre_ID IN ( SELECT   I_Center_ID  
                                                   FROM     @TempCenter )  
  --AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)  
                                AND B.I_Course_ID IN ( SELECT   I_Course_ID  
                                                       FROM     @TemCourse )  
                                AND B.I_Term_ID IS NULL --= COALESCE(@iTermID, B.I_Term_ID)  
                                AND A.I_Status = COALESCE(@iStatusID,  
                                                          A.I_Status)  
                                AND B.B_PS_Flag = 0  
                                AND B.C_Certificate_Type = ISNULL(@CertificateType,B.C_Certificate_Type)
    
                    END  
                ELSE   
                    IF ( @iPSCert = 1 )   
                        BEGIN  
                            SELECT DISTINCT ISNULL(A.I_Student_Cert_Request_ID, 0) AS I_Student_Cert_Request_ID,  
                                    ISNULL(A.I_Student_Certificate_ID, 0) AS I_Student_Certificate_ID,  
                                    ( ISNULL(A.S_Student_FName, ' ')  
                                      + ISNULL(A.S_Student_MName, ' ')  
                                      + ISNULL(A.S_Student_LName, ' ') ) AS S_Student_Name,  
                                    ISNULL(A.S_Reiss_Reason, ' ') AS S_Reiss_Reason,  
                                    ISNULL(A.I_Status, 0) AS I_Status,  
                                    ISNULL(A.S_Crtd_By, ' ') AS S_Crtd_By,  
                                    ISNULL(A.S_Upd_By, ' ') AS S_Upd_By,  
                                    ISNULL(A.Dt_Crtd_On, ' ') AS Dt_Crtd_On,  
                                    ISNULL(A.Dt_Upd_On, ' ') AS Dt_Upd_On,  
                                    ISNULL(B.I_Student_Detail_ID, 0) AS I_Student_Detail_ID,  
                                    ISNULL(C.S_First_Name, '') AS S_First_Name,  
                                    ISNULL(C.S_Middle_Name, '') AS S_Middle_Name,  
     ISNULL(C.S_Last_Name, '') AS S_Last_Name,  
                                    ISNULL(B.S_Certificate_Serial_No, '') AS S_Certificate_Serial_No,  
                                    ISNULL(CM.S_Center_Name, '') AS S_Center_Name,  
                                    CM.I_Centre_ID AS I_Center_ID,  
                                    ISNULL(COM.S_Course_Name, '') AS S_Course_Name,  
                                    ISNULL(TM.S_Term_Name, '') AS S_Term_Name,  
                                    SCD.I_Batch_ID  
                            FROM    [PSCERTIFICATE].T_Student_Certificate_Request A  
                                    INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate B ON A.I_Student_Certificate_ID = B.I_Student_Certificate_ID  
                                    INNER JOIN [dbo].T_Student_Detail C ON B.I_Student_Detail_ID = C.I_Student_Detail_ID  
                                    INNER JOIN [dbo].T_Student_Center_Detail F ON C.I_Student_Detail_ID = F.I_Student_Detail_ID  
                                    INNER JOIN dbo.T_Centre_Master CM ON CM.I_Centre_Id = F.I_Centre_Id  
                                    INNER JOIN dbo.T_Student_Course_Detail SCD ON SCD.I_Student_Detail_ID = B.I_Student_Detail_ID  
                                    AND [SCD].[I_Course_ID] = [B].[I_Course_ID]  
                                    INNER JOIN dbo.T_Course_Master COM ON COM.I_Course_ID = SCD.I_Course_ID  
                                    LEFT OUTER JOIN [dbo].T_Term_Master TM ON TM.I_Term_ID = B.I_Term_ID  
                            WHERE   --AND F.I_Centre_ID = COALESCE(@iCenterID, F.I_Centre_ID)  
                                    F.I_Centre_ID IN ( SELECT   I_Center_ID  
                                                       FROM     @TempCenter )  
  --AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)  
                                    AND B.I_Course_ID IN (  
                                    SELECT  I_Course_ID  
                                    FROM    @TemCourse )  
  --AND B.I_Term_ID = COALESCE(@iTermID, B.I_Term_ID)  
                                    AND B.I_Term_ID IN ( SELECT I_Term_ID  
                                                         FROM   @TemTermCourse )  
                                    AND A.I_Status = COALESCE(@iStatusID, A.I_Status)  
                                    AND B.B_PS_Flag = 1 
                                    AND B.C_Certificate_Type = ISNULL(@CertificateType,B.C_Certificate_Type) 
    
                        END  
                    ELSE   
                        BEGIN  
                            SELECT DISTINCT ISNULL(A.I_Student_Cert_Request_ID, 0) AS I_Student_Cert_Request_ID,  
                                    ISNULL(A.I_Student_Certificate_ID, 0) AS I_Student_Certificate_ID,  
                                    ( ISNULL(A.S_Student_FName, ' ')  
                                      + ISNULL(A.S_Student_MName, ' ')  
                                      + ISNULL(A.S_Student_LName, ' ') ) AS S_Student_Name,  
                                    ISNULL(A.S_Reiss_Reason, ' ') AS S_Reiss_Reason,  
                                    ISNULL(A.I_Status, 0) AS I_Status,  
                                    ISNULL(A.S_Crtd_By, ' ') AS S_Crtd_By,  
                                    ISNULL(A.S_Upd_By, ' ') AS S_Upd_By,  
                                    ISNULL(A.Dt_Crtd_On, ' ') AS Dt_Crtd_On,  
                                    ISNULL(A.Dt_Upd_On, ' ') AS Dt_Upd_On,  
                                    ISNULL(B.I_Student_Detail_ID, 0) AS I_Student_Detail_ID,  
                                    ISNULL(C.S_First_Name, '') AS S_First_Name,  
                                    ISNULL(C.S_Middle_Name, '') AS S_Middle_Name,  
                                    ISNULL(C.S_Last_Name, '') AS S_Last_Name,  
                                    ISNULL(B.S_Certificate_Serial_No, '') AS S_Certificate_Serial_No,  
                                    ISNULL(CM.S_Center_Name, '') AS S_Center_Name,  
                                    CM.I_Centre_ID AS I_Center_ID,  
               ISNULL(COM.S_Course_Name, '') AS S_Course_Name,  
                                    ISNULL(TM.S_Term_Name, '') AS S_Term_Name,  
                                    SCD.I_Batch_ID  
                            FROM    [PSCERTIFICATE].T_Student_Certificate_Request A  
                                    INNER JOIN [PSCERTIFICATE].T_Student_PS_Certificate B ON A.I_Student_Certificate_ID = B.I_Student_Certificate_ID  
                                    INNER JOIN [dbo].T_Student_Detail C ON B.I_Student_Detail_ID = C.I_Student_Detail_ID  
                                    INNER JOIN [dbo].T_Student_Center_Detail F ON C.I_Student_Detail_ID = F.I_Student_Detail_ID  
                                    INNER JOIN dbo.T_Centre_Master CM ON CM.I_Centre_Id = F.I_Centre_Id  
                                    INNER JOIN dbo.T_Student_Course_Detail SCD ON SCD.I_Student_Detail_ID = B.I_Student_Detail_ID  
                                    AND [SCD].[I_Course_ID] = [B].[I_Course_ID]  
                                    INNER JOIN dbo.T_Course_Master COM ON COM.I_Course_ID = SCD.I_Course_ID  
                                    LEFT OUTER JOIN [dbo].T_Term_Master TM ON TM.I_Term_ID = B.I_Term_ID  
                            WHERE   --  AND F.I_Centre_ID = COALESCE(@iCenterID, F.I_Centre_ID)  
                                    F.I_Centre_ID IN ( SELECT   I_Center_ID  
                                                       FROM     @TempCenter )  
  --AND B.I_Course_ID = COALESCE(@iCourseID, B.I_Course_ID)  
                                    AND B.I_Term_ID IS NOT NULL--= COALESCE(@iTermID, B.I_Term_ID)  
                                    AND A.I_Status = COALESCE(@iStatusID, A.I_Status)  
                                    AND B.B_PS_Flag = 0  
                                    AND B.C_Certificate_Type = ISNULL(@CertificateType,B.C_Certificate_Type)
                        END   
  
            END  
  
   
   
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetDailySalesReportNewI]...';


GO
CREATE PROCEDURE [REPORT].[uspGetDailySalesReportNewI]
    (
      @iBrandID INT ,
      @sHierarchyListID VARCHAR(MAX) ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS
    BEGIN
    
        CREATE TABLE #temp
            (
              I_Center_ID INT ,
              S_Center_Name VARCHAR(MAX) ,
              MonthYear VARCHAR(MAX) ,
              I_Course_ID INT ,
              S_Course_Name VARCHAR(MAX) ,
              NValue DECIMAL(14, 2) ,
              I_FeeComponent_ID INT ,
              I_Instalment_No INT ,
              InstalmentDate DATETIME ,
              TypeofPayment CHAR(2)
            )
            
        IF ( @iBrandID = 109
             OR @iBrandID = 111
           )
            BEGIN    

                INSERT  INTO #temp
                        ( I_Center_ID ,
                          S_Center_Name ,
                          MonthYear ,
                          I_Course_ID ,
                          S_Course_Name ,
                          I_Instalment_No ,
                          InstalmentDate ,
                          I_FeeComponent_ID ,
                          TypeofPayment ,
                          NValue
                        )
                        SELECT  TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END AS S_Center_Name ,
                                DATENAME(MONTH, TRH.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum ,
                                SUM(ISNULL(TRCD.N_Amount_Paid, 0.0)) AS VALUE
                        FROM    dbo.T_Receipt_Header TRH WITH ( NOLOCK )
                                INNER JOIN dbo.T_Receipt_Component_Detail TRCD
                                WITH ( NOLOCK ) ON TRH.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Detail TICD
                                WITH ( NOLOCK ) ON TRCD.I_Invoice_Detail_ID = TICD.I_Invoice_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Header TICH
                                WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND
                                WITH ( NOLOCK ) ON TRH.I_Centre_Id = TCHND.I_Center_ID
                                INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                        --INNER JOIN dbo.T_Student_Course_Detail TSCD WITH ( NOLOCK ) ON TRH.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                LEFT JOIN dbo.T_Course_Master TCM WITH ( NOLOCK ) ON TICH.I_Course_ID = TCM.I_Course_ID
                        WHERE   TRH.I_Status IN ( 0, 1 )
                                AND TICD.I_Installment_No > 0
                                AND TRH.I_Receipt_Type = 2
                                AND ( TRH.Dt_Crtd_On >= @dtStartDate
                                      AND TRH.Dt_Crtd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                    )
                                AND TRH.I_Centre_Id IN (
                                SELECT  FGCFR.centerID
                                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) FGCFR )
                        GROUP BY TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END ,
                                DATENAME(MONTH, TRH.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Crtd_On) AS VARCHAR) ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum
                        UNION ALL
                        SELECT  TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END AS S_Center_Name ,
                                DATENAME(MONTH, TRH.Dt_Upd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Upd_On) AS VARCHAR) AS MonthYear ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum ,
                                -SUM(ISNULL(TRCD.N_Amount_Paid, 0.0)) AS VALUE
                        FROM    dbo.T_Receipt_Header TRH WITH ( NOLOCK )
                                INNER JOIN dbo.T_Receipt_Component_Detail TRCD
                                WITH ( NOLOCK ) ON TRH.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Detail TICD
                                WITH ( NOLOCK ) ON TRCD.I_Invoice_Detail_ID = TICD.I_Invoice_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Header TICH
                                WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND
                                WITH ( NOLOCK ) ON TRH.I_Centre_Id = TCHND.I_Center_ID
                                INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                        --INNER JOIN dbo.T_Student_Course_Detail TSCD WITH ( NOLOCK ) ON TRH.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                LEFT JOIN dbo.T_Course_Master TCM WITH ( NOLOCK ) ON TICH.I_Course_ID = TCM.I_Course_ID
                        WHERE   TRH.I_Status = 0
                                AND TICD.I_Installment_No > 0
                                AND TRH.I_Receipt_Type = 2
                                AND ( TRH.Dt_Upd_On >= @dtStartDate
                                      AND TRH.Dt_Upd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                    )
                                AND TRH.I_Centre_Id IN (
                                SELECT  FGCFR.centerID
                                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) FGCFR )
                        GROUP BY TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END ,
                                DATENAME(MONTH, TRH.Dt_Upd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Upd_On) AS VARCHAR) ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum
                            
                            --SELECT * FROM #temp T1
                            
                            
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'Form/Prospectus(Old Reg)' AS Category ,
                        COUNT(DISTINCT TRH.I_Receipt_Header_ID) AS Value
                FROM    dbo.T_Receipt_Header TRH
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TRH.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TRH.I_Status = 1
                        AND TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TRH.I_Receipt_Type IN ( 31, 32, 50, 51, 57, 85 )
                        AND TRH.Dt_Crtd_On >= @dtStartDate
                        AND TRH.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID = 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'Form/Prospectus(New)' AS Category ,
                        COUNT(DISTINCT TRH.I_Receipt_Header_ID) AS Value
                FROM    dbo.T_Receipt_Header TRH
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TRH.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TRH.I_Status = 1
                        AND TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TRH.I_Receipt_Type IN ( 31, 32, 50, 51, 57, 85 )
                        AND TRH.Dt_Crtd_On >= @dtStartDate
                        AND TRH.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID != 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TERD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TERD.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'PreEnquiry/Enquiry(Old Reg)' AS Category ,
                        COUNT(DISTINCT TERD.I_Enquiry_Regn_ID) AS Value
                FROM    dbo.T_Enquiry_Regn_Detail TERD
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TERD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TERD.Dt_Crtd_On >= @dtStartDate
                        AND TERD.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID = 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TERD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TERD.Dt_Crtd_On) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TERD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TERD.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'PreEnquiry/Enquiry(New)' AS Category ,
                        COUNT(DISTINCT TERD.I_Enquiry_Regn_ID) AS Value
                FROM    dbo.T_Enquiry_Regn_Detail TERD
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TERD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TERD.Dt_Crtd_On >= @dtStartDate
                        AND TERD.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID != 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TERD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TERD.Dt_Crtd_On) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name ,
                        'Registration (Old)' AS Category ,
                        COUNT(DISTINCT TSD.S_Student_ID) AS Value
                FROM    dbo.T_Student_Detail TSD
                        INNER JOIN dbo.T_Student_Center_Detail TSCD ON TSD.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                                              AND CONVERT(DATE, TSD.Dt_Crtd_On) = CONVERT(DATE, TSCD.Dt_Valid_From)
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TSCD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN ( SELECT TSBD.I_Student_ID ,
                                            MIN(TSBD.I_Student_Batch_ID) AS MinBatchID
                                     FROM   dbo.T_Student_Batch_Details TSBD
                                     GROUP BY TSBD.I_Student_ID
                                   ) TSBD1 ON TSD.I_Student_Detail_ID = TSBD1.I_Student_ID
                        INNER JOIN dbo.T_Student_Batch_Details TSBD2 ON TSBD1.I_Student_ID = TSBD2.I_Student_ID
                                                              AND TSBD2.I_Student_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD1.MinBatchID = TSBD2.I_Student_Batch_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD2.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM2 ON TSBM.I_Course_ID = TCM2.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM3 WITH ( NOLOCK ) ON TCM3.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TSD.Dt_Crtd_On >= @dtStartDate
                        AND TSD.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TERD.I_Enquiry_Status_Code = 3
                        AND TISM.I_Info_Source_ID = 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name ,
                        'Registration (New)' AS Category ,
                        COUNT(DISTINCT TSD.S_Student_ID) AS Value
                FROM    dbo.T_Student_Detail TSD
                        INNER JOIN dbo.T_Student_Center_Detail TSCD ON TSD.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                                              AND CONVERT(DATE, TSD.Dt_Crtd_On) = CONVERT(DATE, TSCD.Dt_Valid_From)
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TSCD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN ( SELECT TSBD.I_Student_ID ,
                                            MIN(TSBD.I_Student_Batch_ID) AS MinBatchID
                                     FROM   dbo.T_Student_Batch_Details TSBD
                                     GROUP BY TSBD.I_Student_ID
                                   ) TSBD1 ON TSD.I_Student_Detail_ID = TSBD1.I_Student_ID
                        INNER JOIN dbo.T_Student_Batch_Details TSBD2 ON TSBD1.I_Student_ID = TSBD2.I_Student_ID
                                                              AND TSBD2.I_Student_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD1.MinBatchID = TSBD2.I_Student_Batch_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD2.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM2 ON TSBM.I_Course_ID = TCM2.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM3 WITH ( NOLOCK ) ON TCM3.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TSD.Dt_Crtd_On >= @dtStartDate
                        AND TSD.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TERD.I_Enquiry_Status_Code = 3
                        AND TISM.I_Info_Source_ID != 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'Promotion/Conversion' AS Category ,
        --TSD.S_Student_ID
                        COUNT(DISTINCT TIP.I_Invoice_Header_ID) AS Value
                FROM    dbo.T_Invoice_Parent TIP
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   ( TCHND.I_Center_ID IN ( 19, 18 )
                          AND TCHND.I_Center_ID IN (
                          SELECT    FGCFR.centerID
                          FROM      dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR )
                        )
                        AND TIP.I_Parent_Invoice_ID IS NULL
                        AND ( TIP.Dt_Crtd_On >= @dtStartDate
                              AND TIP.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                            )
                        AND CONVERT(DATE, TIP.Dt_Crtd_On) != CONVERT(DATE, TSD.Dt_Crtd_On)
                        AND TCM.I_Course_ID IN ( 519, 520, 11, 12 )
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Fresh Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   ( ( TFCM.S_Type_Of_Component = 'A'
                            --AND T1.TypeofPayment = 'N'
                          )
                          --OR ( T1.TypeofPayment = 'Y' )
                        )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                  AND TFCM.S_Type_Of_Component = 'M'
                                )
        --T1.I_FeeComponent_ID NOT IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
        --UNION ALL
        --SELECT  T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name ,
        --        'MTF Collection' AS Category ,
        --        SUM(T1.NValue) AS Value
        --FROM    #temp T1
        --INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID=T1.I_FeeComponent_ID
        --WHERE TFCM.S_Type_Of_Component='M'
        ----WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        --GROUP BY T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Total Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Conversion Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        AND T1.I_Instalment_No = 1
                        AND T1.I_Course_ID IN ( 519, 520, 11, 12 )
                        AND ( T1.I_Center_ID IN ( 19, 18 )
                              AND T1.I_Center_ID IN (
                              SELECT    FGCFR.centerID
                              FROM      dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR )
                            )
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
        --UNION ALL
        --SELECT  T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name ,
        --        'MTF Collection From Lumpsum' AS Category ,
        --        SUM(T1.NValue) AS Value
        --FROM    #temp T1
        --INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID=T1.I_FeeComponent_ID
        --WHERE TFCM.S_Type_Of_Component='M' AND T1.TypeofPayment='Y' --AND T1.I_Instalment_No=1
        ----WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        --GROUP BY T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name                
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'MTF Collection (Dues)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        --AND T1.TypeofPayment != 'Y' --AND T1.I_Instalment_No=1
                        AND T1.InstalmentDate <= DATEADD(d, -DAY(@dtStartDate),
                                                         @dtStartDate)
                        AND T1.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) AS FGCFR )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                )
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'MTF Collection (Current)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        --AND T1.TypeofPayment != 'Y' --AND T1.I_Instalment_No=1
                        AND ( T1.InstalmentDate >= DATEADD(d,
                                                           -DAY(@dtStartDate)
                                                           + 1, @dtStartDate)
                              AND T1.InstalmentDate < DATEADD(d,
                                                              -DAY(DATEADD(m,
                                                              1, @dtEndDate))
                                                              + 1,
                                                              DATEADD(m, 1,
                                                              @dtEndDate))
                            )
                        --AND T1.TypeofPayment = 'N'
                        AND T1.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) AS FGCFR )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                )
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'MTF Collection (Advance)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        --AND T1.TypeofPayment = 'N' --AND T1.I_Instalment_No=1
                        AND T1.InstalmentDate >= DATEADD(d,
                                                         -DAY(DATEADD(m, 1,
                                                              @dtEndDate)) + 1,
                                                         DATEADD(m, 1,
                                                              @dtEndDate)) --AND T1.InstalmentDate<DATEADD(d,1,@dtEndDate))
                        AND T1.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) AS FGCFR )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                )
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name               
        
			OPTION (RECOMPILE);
            END
        
        ELSE
            BEGIN
        
                DROP TABLE #temp
        
                EXEC REPORT.uspGetDailySalesReportAISAWS @iBrandID = @iBrandID, -- int
                    @sHierarchyListID = @sHierarchyListID, -- varchar(max)
                    @dtStartDate = @dtStartDate, -- date
                    @dtEndDate = @dtEndDate -- date
        
        
            END
        
      
	
    END
GO
PRINT N'Creating Procedure [REPORT].[uspGetDailySalesReportNew]...';


GO
CREATE PROCEDURE [REPORT].[uspGetDailySalesReportNew]
    (
      @iBrandID INT ,
      @sHierarchyListID VARCHAR(MAX) ,
      @dtStartDate DATE ,
      @dtEndDate DATE
    )
AS
    BEGIN
    
        CREATE TABLE #temp
            (
              I_Center_ID INT ,
              S_Center_Name VARCHAR(MAX) ,
			  AdmissionDate VARCHAR(MAX),
              MonthYear VARCHAR(MAX) ,
              I_Course_ID INT ,
              S_Course_Name VARCHAR(MAX) ,
              NValue DECIMAL(14, 2) ,
              I_FeeComponent_ID INT ,
              I_Instalment_No INT ,
              InstalmentDate DATETIME ,
              TypeofPayment CHAR(2)
            )
            
        IF ( @iBrandID = 109
             OR @iBrandID = 111
           )
            BEGIN    

                INSERT  INTO #temp
                        ( I_Center_ID ,
                          S_Center_Name ,
						  AdmissionDate,
                          MonthYear ,
                          I_Course_ID ,
                          S_Course_Name ,
                          I_Instalment_No ,
                          InstalmentDate ,
                          I_FeeComponent_ID ,
                          TypeofPayment ,
                          NValue
                        )
                        SELECT  TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END AS S_Center_Name ,
								DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) AS AdmMonthYear,
                                DATENAME(MONTH, TRH.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum ,
                                SUM(ISNULL(TRCD.N_Amount_Paid, 0.0)) AS VALUE
                        FROM    dbo.T_Receipt_Header TRH WITH ( NOLOCK )
                                INNER JOIN dbo.T_Receipt_Component_Detail TRCD
                                WITH ( NOLOCK ) ON TRH.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Detail TICD
                                WITH ( NOLOCK ) ON TRCD.I_Invoice_Detail_ID = TICD.I_Invoice_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Header TICH
                                WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND
                                WITH ( NOLOCK ) ON TRH.I_Centre_Id = TCHND.I_Center_ID
                                INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                        --INNER JOIN dbo.T_Student_Course_Detail TSCD WITH ( NOLOCK ) ON TRH.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                LEFT JOIN dbo.T_Course_Master TCM WITH ( NOLOCK ) ON TICH.I_Course_ID = TCM.I_Course_ID
								INNER JOIN T_Student_Detail TSD ON TSD.I_Student_Detail_ID=TRH.I_Student_Detail_ID
                        WHERE   TRH.I_Status IN ( 0, 1 )
                                AND TICD.I_Installment_No > 0
                                AND TRH.I_Receipt_Type = 2
                                AND ( TRH.Dt_Crtd_On >= @dtStartDate
                                      AND TRH.Dt_Crtd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                    )
                                AND TRH.I_Centre_Id IN (
                                SELECT  FGCFR.centerID
                                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) FGCFR )
                        GROUP BY TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END ,
								DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR),
                                DATENAME(MONTH, TRH.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Crtd_On) AS VARCHAR) ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum
                        UNION ALL
                        SELECT  TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END AS S_Center_Name ,
								DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) AS AdmissionMonthYear,
                                DATENAME(MONTH, TRH.Dt_Upd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Upd_On) AS VARCHAR) AS MonthYear ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum ,
                                -SUM(ISNULL(TRCD.N_Amount_Paid, 0.0)) AS VALUE
                        FROM    dbo.T_Receipt_Header TRH WITH ( NOLOCK )
                                INNER JOIN dbo.T_Receipt_Component_Detail TRCD
                                WITH ( NOLOCK ) ON TRH.I_Receipt_Header_ID = TRCD.I_Receipt_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Detail TICD
                                WITH ( NOLOCK ) ON TRCD.I_Invoice_Detail_ID = TICD.I_Invoice_Detail_ID
                                INNER JOIN dbo.T_Invoice_Child_Header TICH
                                WITH ( NOLOCK ) ON TICD.I_Invoice_Child_Header_ID = TICH.I_Invoice_Child_Header_ID
                                INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND
                                WITH ( NOLOCK ) ON TRH.I_Centre_Id = TCHND.I_Center_ID
                                INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                        --INNER JOIN dbo.T_Student_Course_Detail TSCD WITH ( NOLOCK ) ON TRH.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                LEFT JOIN dbo.T_Course_Master TCM WITH ( NOLOCK ) ON TICH.I_Course_ID = TCM.I_Course_ID
								INNER JOIN T_Student_Detail TSD ON TSD.I_Student_Detail_ID=TRH.I_Student_Detail_ID
                        WHERE   TRH.I_Status = 0
                                AND TICD.I_Installment_No > 0
                                AND TRH.I_Receipt_Type = 2
                                AND ( TRH.Dt_Upd_On >= @dtStartDate
                                      AND TRH.Dt_Upd_On < DATEADD(d, 1,
                                                              @dtEndDate)
                                    )
                                AND TRH.I_Centre_Id IN (
                                SELECT  FGCFR.centerID
                                FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) FGCFR )
                        GROUP BY TCHND.I_Center_ID ,
                                CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                                     THEN TCHND.S_Center_Name + ' (Franchise)'
                                     ELSE TCHND.S_Center_Name + ' (Own)'
                                END ,
								DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                                + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR),
                                DATENAME(MONTH, TRH.Dt_Upd_On) + ' '
                                + CAST(DATEPART(YYYY, TRH.Dt_Upd_On) AS VARCHAR) ,
                                TCM.I_Course_ID ,
                                TCM.S_Course_Name ,
                                TICD.I_Installment_No ,
                                TICD.Dt_Installment_Date ,
                                TICD.I_Fee_Component_ID ,
                                TICH.C_Is_LumpSum
                            
                            --SELECT * FROM #temp T1
                            
                            
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'Form/Prospectus(Old Reg)' AS Category ,
                        COUNT(DISTINCT TRH.I_Receipt_Header_ID) AS Value
                FROM    dbo.T_Receipt_Header TRH
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TRH.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TRH.I_Status = 1
                        AND TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TRH.I_Receipt_Type IN ( 31, 32, 50, 51, 57, 85 )
                        AND TRH.Dt_Crtd_On >= @dtStartDate
                        AND TRH.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID = 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'Form/Prospectus(New)' AS Category ,
                        COUNT(DISTINCT TRH.I_Receipt_Header_ID) AS Value
                FROM    dbo.T_Receipt_Header TRH
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TRH.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TRH.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TRH.I_Status = 1
                        AND TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TRH.I_Receipt_Type IN ( 31, 32, 50, 51, 57, 85 )
                        AND TRH.Dt_Crtd_On >= @dtStartDate
                        AND TRH.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID != 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TRH.Dt_Receipt_Date) + ' '
                        + CAST(DATEPART(YYYY, TRH.Dt_Receipt_Date) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) + ' '
                        + CAST(DATEPART(YYYY, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'PreEnquiry/Enquiry(Old Reg)' AS Category ,
                        COUNT(DISTINCT TERD.I_Enquiry_Regn_ID) AS Value
                FROM    dbo.T_Enquiry_Regn_Detail TERD
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TERD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On) >= @dtStartDate
                        AND ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On) < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID = 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) + ' '
                        + CAST(DATEPART(YYYY, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) + ' '
                        + CAST(DATEPART(YYYY, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'PreEnquiry/Enquiry(New)' AS Category ,
                        COUNT(DISTINCT TERD.I_Enquiry_Regn_ID) AS Value
                FROM    dbo.T_Enquiry_Regn_Detail TERD
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TERD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN (SELECT TEC.I_Enquiry_Regn_ID,MIN(TEC.I_Course_ID) AS I_Course_ID FROM dbo.T_Enquiry_Course AS TEC GROUP BY TEC.I_Enquiry_Regn_ID) TEC ON TERD.I_Enquiry_Regn_ID = TEC.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TEC.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On) >= @dtStartDate
                        AND ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On) < DATEADD(d, 1, @dtEndDate)
                        AND TISM.I_Info_Source_ID != 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) + ' '
                        + CAST(DATEPART(YYYY, ISNULL(TERD.PreEnquiryDate,TERD.Dt_Crtd_On)) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name ,
                        'Registration (Old)' AS Category ,
                        COUNT(DISTINCT TSD.S_Student_ID) AS Value
                FROM    dbo.T_Student_Detail TSD
                        INNER JOIN dbo.T_Student_Center_Detail TSCD ON TSD.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                                              AND CONVERT(DATE, TSD.Dt_Crtd_On) = CONVERT(DATE, TSCD.Dt_Valid_From)
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TSCD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN ( SELECT TSBD.I_Student_ID ,
                                            MIN(TSBD.I_Student_Batch_ID) AS MinBatchID
                                     FROM   dbo.T_Student_Batch_Details TSBD
                                     GROUP BY TSBD.I_Student_ID
                                   ) TSBD1 ON TSD.I_Student_Detail_ID = TSBD1.I_Student_ID
                        INNER JOIN dbo.T_Student_Batch_Details TSBD2 ON TSBD1.I_Student_ID = TSBD2.I_Student_ID
                                                              AND TSBD2.I_Student_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD1.MinBatchID = TSBD2.I_Student_Batch_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD2.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM2 ON TSBM.I_Course_ID = TCM2.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM3 WITH ( NOLOCK ) ON TCM3.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TSD.Dt_Crtd_On >= @dtStartDate
                        AND TSD.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TERD.I_Enquiry_Status_Code = 3
                        AND TISM.I_Info_Source_ID = 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name ,
                        'Registration (New)' AS Category ,
                        COUNT(DISTINCT TSD.S_Student_ID) AS Value
                FROM    dbo.T_Student_Detail TSD
                        INNER JOIN dbo.T_Student_Center_Detail TSCD ON TSD.I_Student_Detail_ID = TSCD.I_Student_Detail_ID
                                                              AND CONVERT(DATE, TSD.Dt_Crtd_On) = CONVERT(DATE, TSCD.Dt_Valid_From)
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TSCD.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Enquiry_Regn_Detail TERD ON TSD.I_Enquiry_Regn_ID = TERD.I_Enquiry_Regn_ID
                        INNER JOIN dbo.T_Information_Source_Master TISM ON TERD.I_Info_Source_ID = TISM.I_Info_Source_ID
                        INNER JOIN ( SELECT TSBD.I_Student_ID ,
                                            MIN(TSBD.I_Student_Batch_ID) AS MinBatchID
                                     FROM   dbo.T_Student_Batch_Details TSBD
                                     GROUP BY TSBD.I_Student_ID
                                   ) TSBD1 ON TSD.I_Student_Detail_ID = TSBD1.I_Student_ID
                        INNER JOIN dbo.T_Student_Batch_Details TSBD2 ON TSBD1.I_Student_ID = TSBD2.I_Student_ID
                                                              AND TSBD2.I_Student_ID = TSD.I_Student_Detail_ID
                                                              AND TSBD1.MinBatchID = TSBD2.I_Student_Batch_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TSBD2.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM2 ON TSBM.I_Course_ID = TCM2.I_Course_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM3 WITH ( NOLOCK ) ON TCM3.I_Centre_Id = TCHND.I_Center_ID
                WHERE   TCHND.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) FGCFR )
                        AND TSD.Dt_Crtd_On >= @dtStartDate
                        AND TSD.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                        AND TERD.I_Enquiry_Status_Code = 3
                        AND TISM.I_Info_Source_ID != 3
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM3.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TSD.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TSD.Dt_Crtd_On) AS VARCHAR) ,
                        TCM2.I_Course_ID ,
                        TCM2.S_Course_Name
                UNION ALL
                SELECT  TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END AS S_Center_Name ,
                        DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) AS MonthYear ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name ,
                        'Promotion/Conversion' AS Category ,
        --TSD.S_Student_ID
                        COUNT(DISTINCT TIP.I_Invoice_Header_ID) AS Value
                FROM    dbo.T_Invoice_Parent TIP
                        INNER JOIN dbo.T_Invoice_Child_Header TICH ON TIP.I_Invoice_Header_ID = TICH.I_Invoice_Header_ID
                        INNER JOIN dbo.T_Invoice_Batch_Map TIBM ON TICH.I_Invoice_Child_Header_ID = TIBM.I_Invoice_Child_Header_ID
                        INNER JOIN dbo.T_Student_Batch_Master TSBM ON TIBM.I_Batch_ID = TSBM.I_Batch_ID
                        INNER JOIN dbo.T_Course_Master TCM ON TSBM.I_Course_ID = TCM.I_Course_ID
                        INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TIP.I_Centre_Id = TCHND.I_Center_ID
                        INNER JOIN dbo.T_Student_Detail TSD ON TIP.I_Student_Detail_ID = TSD.I_Student_Detail_ID
                        INNER JOIN dbo.T_Centre_Master AS TCM2 WITH ( NOLOCK ) ON TCM2.I_Centre_Id = TCHND.I_Center_ID
                WHERE   ( TCHND.I_Center_ID IN ( 19, 18 )
                          AND TCHND.I_Center_ID IN (
                          SELECT    FGCFR.centerID
                          FROM      dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR )
                        )
                        AND TIP.I_Parent_Invoice_ID IS NULL
                        AND ( TIP.Dt_Crtd_On >= @dtStartDate
                              AND TIP.Dt_Crtd_On < DATEADD(d, 1, @dtEndDate)
                            )
                        AND CONVERT(DATE, TIP.Dt_Crtd_On) != CONVERT(DATE, TSD.Dt_Crtd_On)
                        AND TCM.I_Course_ID IN ( 519, 520, 11, 12,728,730 )
                GROUP BY TCHND.I_Center_ID ,
                        CASE WHEN TCM2.S_Center_Code LIKE 'FR-%'
                             THEN TCHND.S_Center_Name + ' (Franchise)'
                             ELSE TCHND.S_Center_Name + ' (Own)'
                        END ,
                        DATENAME(MONTH, TIP.Dt_Crtd_On) + ' '
                        + CAST(DATEPART(YYYY, TIP.Dt_Crtd_On) AS VARCHAR) ,
                        TCM.I_Course_ID ,
                        TCM.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Fresh Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   ( ( TFCM.S_Type_Of_Component = 'A'
                            AND T1.TypeofPayment = 'N'
                          )
                          OR ( T1.TypeofPayment = 'Y' AND (TFCM.S_Type_Of_Component = 'A'))
						  --OR ( T1.TypeofPayment = 'Y' AND (TFCM.S_Type_Of_Component = 'A' OR TFCM.S_Type_Of_Component = 'M'))
                        )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12 ,728,730)
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                  AND TFCM.S_Type_Of_Component = 'M'
                                )
						AND T1.AdmissionDate=T1.MonthYear
        --T1.I_FeeComponent_ID NOT IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
        --UNION ALL
        --SELECT  T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name ,
        --        'MTF Collection' AS Category ,
        --        SUM(T1.NValue) AS Value
        --FROM    #temp T1
        --INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID=T1.I_FeeComponent_ID
        --WHERE TFCM.S_Type_Of_Component='M'
        ----WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        --GROUP BY T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name
				UNION ALL
				SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'PartPayment Adm Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   ( ( TFCM.S_Type_Of_Component = 'A'
                            AND T1.TypeofPayment = 'N'
                          )
						  OR ( T1.TypeofPayment = 'Y' AND (TFCM.S_Type_Of_Component = 'A'))
                          --OR ( T1.TypeofPayment = 'Y' AND (TFCM.S_Type_Of_Component = 'A' OR TFCM.S_Type_Of_Component = 'M'))
                        )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12 ,728,730)
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                  AND TFCM.S_Type_Of_Component = 'M'
                                )
						AND T1.AdmissionDate!=T1.MonthYear
        --T1.I_FeeComponent_ID NOT IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL

				SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Promotion' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   (  ( T1.TypeofPayment = 'Y' AND TFCM.S_Type_Of_Component = 'M' )
                        )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12,728,730 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                  AND TFCM.S_Type_Of_Component = 'M'
                                )
						AND T1.AdmissionDate!=T1.MonthYear
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name

				UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Total Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Conversion Collection' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        AND T1.I_Instalment_No = 1
                        AND T1.I_Course_ID IN ( 519, 520, 11, 12,728,730 )
						AND T1.I_FeeComponent_ID!=109
                        AND ( T1.I_Center_ID IN ( 19, 18 )
                              AND T1.I_Center_ID IN (
                              SELECT    FGCFR.centerID
                              FROM      dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR )
                            )
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
				UNION ALL
				SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'Conversion Collection (NEW)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   T1.I_FeeComponent_ID=109
                        AND ( T1.I_Center_ID IN ( 19, 18 )
                              AND T1.I_Center_ID IN (
                              SELECT    FGCFR.centerID
                              FROM      dbo.fnGetCentersForReports(@sHierarchyListID,
                                                              @iBrandID) AS FGCFR )
                            )
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
        --UNION ALL
        --SELECT  T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name ,
        --        'MTF Collection From Lumpsum' AS Category ,
        --        SUM(T1.NValue) AS Value
        --FROM    #temp T1
        --INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID=T1.I_FeeComponent_ID
        --WHERE TFCM.S_Type_Of_Component='M' AND T1.TypeofPayment='Y' --AND T1.I_Instalment_No=1
        ----WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
        --GROUP BY T1.I_Center_ID ,
        --        T1.S_Center_Name ,
        --        T1.MonthYear ,
        --        T1.I_Course_ID ,
        --        T1.S_Course_Name                
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'MTF Collection (Dues)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        AND T1.TypeofPayment != 'Y' --AND T1.I_Instalment_No=1
                        AND T1.InstalmentDate <= DATEADD(d, -DAY(@dtStartDate),
                                                         @dtStartDate)
                        AND T1.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) AS FGCFR )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12,728,730 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                )
						AND T1.I_FeeComponent_ID!=109
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'MTF Collection (Current)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        AND T1.TypeofPayment != 'Y' --AND T1.I_Instalment_No=1
                        AND ( T1.InstalmentDate >= DATEADD(d,
                                                           -DAY(@dtStartDate)
                                                           + 1, @dtStartDate)
                              AND T1.InstalmentDate < DATEADD(d,
                                                              -DAY(DATEADD(m,
                                                              1, @dtEndDate))
                                                              + 1,
                                                              DATEADD(m, 1,
                                                              @dtEndDate))
                            )
                        AND T1.TypeofPayment = 'N'
                        AND T1.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) AS FGCFR )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12,728,730 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                )
						AND T1.I_FeeComponent_ID!=109
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name
                UNION ALL
                SELECT  T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name ,
                        'MTF Collection (Advance)' AS Category ,
                        SUM(T1.NValue) AS Value
                FROM    #temp T1
                        INNER JOIN dbo.T_Fee_Component_Master AS TFCM ON TFCM.I_Fee_Component_ID = T1.I_FeeComponent_ID
                WHERE   TFCM.S_Type_Of_Component = 'M'
                        AND T1.TypeofPayment = 'N' --AND T1.I_Instalment_No=1
                        AND T1.InstalmentDate >= DATEADD(d,
                                                         -DAY(DATEADD(m, 1,
                                                              @dtEndDate)) + 1,
                                                         DATEADD(m, 1,
                                                              @dtEndDate)) --AND T1.InstalmentDate<DATEADD(d,1,@dtEndDate))
                        AND T1.I_Center_ID IN (
                        SELECT  FGCFR.centerID
                        FROM    dbo.fnGetCentersForReports(@sHierarchyListID,
                                                           @iBrandID) AS FGCFR )
                        AND NOT ( T1.I_Instalment_No = 1
                                  AND T1.I_Course_ID IN ( 519, 520, 11, 12,728,730 )
                                  AND ( T1.I_Center_ID IN ( 19, 18 ) )
                                )
						AND T1.I_FeeComponent_ID!=109
        --WHERE   T1.I_FeeComponent_ID IN ( 50, 57, 58,49 )
                GROUP BY T1.I_Center_ID ,
                        T1.S_Center_Name ,
                        T1.MonthYear ,
                        T1.I_Course_ID ,
                        T1.S_Course_Name               
        
			OPTION (RECOMPILE);
            END
        
        ELSE
            BEGIN
        
                DROP TABLE #temp
        
                EXEC REPORT.uspGetDailySalesReportAISAWS @iBrandID = @iBrandID, -- int
                    @sHierarchyListID = @sHierarchyListID, -- varchar(max)
                    @dtStartDate = @dtStartDate, -- date
                    @dtEndDate = @dtEndDate -- date
        
        
            END
        
      
	
    END
GO
