GO
CREATE PROCEDURE [dbo].[uspInsertCreditNoteForInvoice] --exec uspInsertCreditNoteForInvoice 153624
(
    @iInvoiceId INT
)
AS
BEGIN   
    SET NOCOUNT ON;
   
    CREATE TABLE #ICHNX(
        ID INT IDENTITY(1,1),
        I_Invoice_Detail_ID INT,
        I_Invoice_Header_ID INT,
        N_Amount NUMERIC(18,2)
    )

    CREATE TABLE #ICTNX(
        ID INT IDENTITY(1,1),
        I_Tax_ID INT,
        I_Invoice_Detail_ID INT,
        N_Tax_Value NUMERIC(18,2)
    )

    CREATE TABLE #ITAX(
        ID INT IDENTITY(1,1),
        I_Tax_ID INT,
        I_Invoice_Detail_ID INT,
        N_Tax_Value NUMERIC(18,2)
    )

    CREATE TABLE #RTAX(
        ID INT IDENTITY(1,1),
        I_Tax_ID INT,
        I_Invoice_Detail_ID INT,
        N_Tax_Value NUMERIC(18,2)
    )

    CREATE TABLE #TAXDiff(
        ID INT IDENTITY(1,1),
        IInv INT,
        ITax INT,
        ITaxDue NUMERIC(18,2),
        RInv INT,
        RTax INT,
        RTaxPaid NUMERIC(18,2),
        TaxDiff NUMERIC(18,2)
    )

    CREATE TABLE #ICHNW(
        ID INT IDENTITY(1,1),
        I_Invoice_Detail_ID INT,
        I_Fee_Component_ID INT,
        I_Invoice_Child_Header_ID INT,
        I_Invoice_Header_ID INT,
        I_Installment_No INT,
        Dt_Installment_Date DATETIME,
        N_Amount_Due NUMERIC(18,2),
        N_Amount_Adv NUMERIC(18,2),
        S_Invoice_Number VARCHAR(100),
        Flag_IsAdvanceTax VARCHAR(10)
    )

    INSERT INTO #ICHNW(I_Invoice_Detail_ID,I_Fee_Component_ID,I_Invoice_Child_Header_ID,I_Invoice_Header_ID,I_Installment_No,
                Dt_Installment_Date,N_Amount_Due,N_Amount_Adv,S_Invoice_Number,Flag_IsAdvanceTax)
    SELECT B.I_Invoice_Detail_ID,B.I_Fee_Component_ID,B.I_Invoice_Child_Header_ID,B.I_Invoice_Header_ID,B.I_Installment_No,B.Dt_Installment_Date,
           ISNULL(B.N_Amount_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)-ISNULL(B.N_Discount_Amount,0.00),B.N_Amount_Adv_Coln, B.S_Invoice_Number, ISNULL(B.Flag_IsAdvanceTax,'N')
    FROM 
	(SELECT ICD.I_Invoice_Detail_ID,ICD.I_Fee_Component_ID,ICD.I_Invoice_Child_Header_ID,ICH.I_Invoice_Header_ID,ICD.I_Installment_No,ICD.Dt_Installment_Date,
           ICD.N_Amount_Due,ICD.N_Discount_Amount,ICD.N_Due,ICD.I_Display_Fee_Component_ID,ICD.I_Sequence,ICD.N_Amount_Adv_Coln,ICD.Flag_IsAdvanceTax,ICD.S_Invoice_Number,ICD.Tmp_AutoIdTag
           --,SUM(ITax.N_Tax_Value) AS N_Tax_Value
    FROM T_Invoice_Child_Detail ICD
    INNER JOIN T_Invoice_Child_Header ICH ON ICD.I_Invoice_Child_Header_ID = ICH.I_Invoice_Child_Header_ID
    INNER JOIN T_Invoice_Parent IP ON ICH.I_Invoice_Header_ID = IP.I_Invoice_Header_ID
    --INNER JOIN T_Invoice_Detail_Tax AS ITax ON ICD.I_Invoice_Detail_ID=ITax.I_Invoice_Detail_ID
    WHERE IP.I_Invoice_Header_ID = @iInvoiceId
    AND ISNULL(ICD.Flag_IsAdvanceTax,'N') <> 'Y'
    ) B
    LEFT JOIN
    (SELECT RCD.I_Invoice_Detail_ID, SUM(ISNULL(RCD.N_Amount_Paid,0)) N_Amount_Paid
    FROM T_Receipt_Header RH
    INNER JOIN T_Receipt_Component_Detail RCD ON RH.I_Receipt_Header_ID = RCD.I_Receipt_Detail_ID
    --INNER JOIN T_Receipt_Tax_Detail AS RTax ON RCD.I_Invoice_Detail_ID=RTax.I_Invoice_Detail_ID
    WHERE RH.I_Invoice_Header_ID = @iInvoiceId
    AND ISNULL(RH.I_Status,0)<>0
    GROUP BY RCD.I_Invoice_Detail_ID) A   
    ON B.I_Invoice_Detail_ID = A.I_Invoice_Detail_ID
    WHERE (ISNULL(B.N_Amount_Due,0.00) - ISNULL(A.N_Amount_Paid,0.00)-ISNULL(B.N_Discount_Amount,0.00)) >= 0
    ORDER BY B.I_Installment_No ASC

    INSERT INTO #ICHNX(I_Invoice_Detail_ID,I_Invoice_Header_ID,N_Amount)
    SELECT IC.I_Invoice_Detail_ID, IC.I_Invoice_Header_ID,SUM(ISNULL(N_Amount,0))
    FROM #ICHNW IC
    INNER JOIN T_Credit_Note_Invoice_Child_Detail CN ON (IC.I_Invoice_Header_ID = CN.I_Invoice_Header_ID AND IC.I_Invoice_Detail_ID = CN.I_Invoice_Detail_ID)
    GROUP BY IC.I_Invoice_Detail_ID, IC.I_Invoice_Header_ID

    INSERT INTO #ICTNX(I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
    SELECT CNT.I_Tax_ID, CNT.I_Invoice_Detail_ID,SUM(ISNULL(CNT.N_Tax_Value,0))
    FROM T_Credit_Note_Invoice_Child_Detail_Tax CNT
    INNER JOIN T_Credit_Note_Invoice_Child_Detail CN ON CNT.I_Credit_Note_Invoice_Child_Detail_ID = CN.I_Credit_Note_Invoice_Child_Detail_ID
    INNER JOIN #ICHNW IC ON (IC.I_Invoice_Header_ID = CN.I_Invoice_Header_ID AND IC.I_Invoice_Detail_ID = CN.I_Invoice_Detail_ID)
    GROUP BY CNT.I_Tax_ID, CNT.I_Invoice_Detail_ID

    INSERT INTO #ITAX(I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
    SELECT ITax.I_Tax_ID, ICD.I_Invoice_Detail_ID,SUM(ISNULL(ITax.N_Tax_Value,0))
    FROM
    T_Invoice_Child_Detail ICD
    INNER JOIN T_Invoice_Child_Header ICH ON ICD.I_Invoice_Child_Header_ID = ICH.I_Invoice_Child_Header_ID
    INNER JOIN T_Invoice_Parent IP ON ICH.I_Invoice_Header_ID = IP.I_Invoice_Header_ID
    INNER JOIN T_Invoice_Detail_Tax AS ITax ON ICD.I_Invoice_Detail_ID=ITax.I_Invoice_Detail_ID
    --INNER JOIN #ICHNW IC ON (IC.I_Invoice_Header_ID = ICH.I_Invoice_Header_ID AND IC.I_Invoice_Detail_ID = ITax.I_Invoice_Detail_ID)
    WHERE ICH.I_Invoice_Header_ID = @iInvoiceId
    AND ISNULL(ICD.Flag_IsAdvanceTax,'N') <> 'Y'
    GROUP BY ITax.I_Tax_ID, ICD.I_Invoice_Detail_ID
    order by ICD.I_Invoice_Detail_ID

    --select * from #ITAX

    INSERT INTO #RTAX(I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
    SELECT RTax.I_Tax_ID, RCD.I_Invoice_Detail_ID,SUM(ISNULL(RTax.N_Tax_Paid,0))
    FROM T_Receipt_Header RH
    INNER JOIN T_Receipt_Component_Detail RCD ON RH.I_Receipt_Header_ID = RCD.I_Receipt_Detail_ID
    INNER JOIN T_Receipt_Tax_Detail AS RTax ON RCD.I_Invoice_Detail_ID=RTax.I_Invoice_Detail_ID
    AND RCD.I_Receipt_Comp_Detail_ID=RTax.I_Receipt_Comp_Detail_ID
    --INNER JOIN #ICHNW IC ON (IC.I_Invoice_Header_ID = RH.I_Invoice_Header_ID AND IC.I_Invoice_Detail_ID = RTax.I_Invoice_Detail_ID)
    WHERE RH.I_Invoice_Header_ID = @iInvoiceId
    AND ISNULL(RH.I_Status,0)<>0
    GROUP BY RTax.I_Tax_ID, RCD.I_Invoice_Detail_ID
    order by RCD.I_Invoice_Detail_ID

    --select * from #RTAX

    INSERT INTO #TAXDiff(IInv,ITax,ITaxDue,RInv,RTax,RTaxPaid,TaxDiff)
    SELECT IT.I_Invoice_Detail_ID AS IInv,IsNull(IT.I_Tax_ID,0) AS ITax,ISNULL(IT.N_Tax_Value,0) AS ITaxDue
    ,RT.I_Invoice_Detail_ID AS RInv,IsNull(RT.I_Tax_ID,0) AS RTax,ISNULL(RT.N_Tax_Value,0) AS RTaxPaid
    --,(CASE WHEN IT.N_Tax_Value=0 THEN (IsNull(RT.N_Tax_Value,0)-IsNull(IT.N_Tax_Value,0)) ELSE (IsNull(IT.N_Tax_Value,0)-IsNull(RT.N_Tax_Value,0)) END)  AS TaxDiff
    ,IsNull((IsNull(IT.N_Tax_Value,0)-IsNull(RT.N_Tax_Value,0)),0)  AS TaxDiff
    FROM #ITAX AS IT
    LEFT OUTER JOIN #RTAX AS RT ON IT.I_Invoice_Detail_ID=RT.I_Invoice_Detail_ID and IT.I_Tax_ID=RT.I_Tax_ID
    --Where (CASE WHEN IT.N_Tax_Value=0 THEN (IsNull(RT.N_Tax_Value,0)-IsNull(IT.N_Tax_Value,0)) ELSE (IsNull(IT.N_Tax_Value,0)-IsNull(RT.N_Tax_Value,0)) END)>0
    --Where IsNull((IsNull(IT.N_Tax_Value,0)-IsNull(RT.N_Tax_Value,0)),0)>0
    Where IsNull((IsNull(IT.N_Tax_Value,0)-IsNull(RT.N_Tax_Value,0)),0)<>0
    --where IT.I_Invoice_Detail_ID=595301
    order by IT.I_Invoice_Detail_ID

    --select * from #TAXDiff

    DECLARE @row INT = 1
    DECLARE @count INT

    DECLARE @I_Invoice_Detail_ID INT
    DECLARE @I_Fee_Component_ID INT
    DECLARE @I_Invoice_Child_Header_ID INT
    DECLARE @I_Invoice_Header_ID INT
    DECLARE @I_Installment_No INT
    DECLARE @Dt_Installment_Date DATETIME
    DECLARE @N_Amount_Due NUMERIC(18,2)
    DECLARE @N_Amount_Adv NUMERIC(18,2)
    DECLARE @S_Invoice_Number VARCHAR(100)
    DECLARE @Flag_IsAdvanceTax VARCHAR(10)

    ----- TAX DIFF -----
    --Declare @TotalInvTax NUMERIC(18,2)
    --Declare @TotalRcvTax NUMERIC(18,2)
    Declare @TaxDiff NUMERIC(18,2)
    Declare @ZeroTaxID INT
    Declare @TotalTaxID INT
    SET @TotalTaxID=0
    SET @ZeroTaxID=0
    ----- TAX DIFF -----

    DECLARE @N_CN_Amount NUMERIC(18,2)
    DECLARE @I_Credit_Note_Invoice_Child_Detail_ID INT


    SELECT @count = COUNT(ID) FROM #ICHNW

    WHILE (@row <= @count)
    BEGIN
        SELECT @I_Invoice_Detail_ID = I_Invoice_Detail_ID,
               @I_Fee_Component_ID = I_Fee_Component_ID,
               @I_Invoice_Child_Header_ID = I_Invoice_Child_Header_ID,
               @I_Invoice_Header_ID = I_Invoice_Header_ID,
               @I_Installment_No = I_Installment_No,
               @Dt_Installment_Date = Dt_Installment_Date,
               @N_Amount_Due = N_Amount_Due,
               @N_Amount_Adv = N_Amount_Adv,
               @S_Invoice_Number = S_Invoice_Number,
               @Flag_IsAdvanceTax = Flag_IsAdvanceTax
        FROM #ICHNW WHERE ID = @row
        AND ((N_Amount_Due>0 AND N_Amount_Adv>0) OR (N_Amount_Due>=0 AND N_Amount_Adv=0))
       
        Select @TaxDiff= SUM(TaxDiff) From #TAXDiff Where IInv=@I_Invoice_Detail_ID

        SET @ZeroTaxID=(Select COUNT(*) From #TAXDiff Where IInv=@I_Invoice_Detail_ID AND RTax=0)
        SET @TotalTaxID=(Select COUNT(*) From #TAXDiff Where IInv=@I_Invoice_Detail_ID)

       

        SET @N_CN_Amount = 0
        SELECT @N_CN_Amount = SUM(ISNULL(N_Amount,0.00)) FROM #ICHNX
        WHERE I_Invoice_Header_ID = @I_Invoice_Header_ID AND I_Invoice_Detail_ID = @I_Invoice_Detail_ID
       
        IF(((ISNULL(@N_Amount_Due,0) - ISNULL(@N_CN_Amount,0))>0) or @TaxDiff>0)
        BEGIN
           
            EXEC dbo.uspGenerateInvoiceNumberForCreditNote @I_Invoice_Header_ID, @I_Installment_No, @Dt_Installment_Date, @S_Invoice_Number OUTPUT       
           

           
            INSERT INTO T_Credit_Note_Invoice_Child_Detail(I_Invoice_Header_ID,I_Invoice_Detail_ID,S_Invoice_Number, Dt_Crtd_On, N_Amount, N_Amount_Due, N_Amount_Adv)
            VALUES(@I_Invoice_Header_ID,@I_Invoice_Detail_ID, @S_Invoice_Number, GETDATE(), (ISNULL(@N_Amount_Due,0) - ISNULL(@N_CN_Amount,0)), (ISNULL(@N_Amount_Due,0) - ISNULL(@N_CN_Amount,0)), @N_Amount_Adv)
           
           
            SET @I_Credit_Note_Invoice_Child_Detail_ID = SCOPE_IDENTITY()           
           
            IF(@Flag_IsAdvanceTax = 'Y')
                BEGIN
                    INSERT INTO T_Credit_Note_Invoice_Child_Detail_Tax(I_Credit_Note_Invoice_Child_Detail_ID,I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
                    SELECT @I_Credit_Note_Invoice_Child_Detail_ID, IDT.I_Tax_ID, IDT.I_Invoice_Detail_ID, SUM(IDT.N_Tax_Value_Scheduled) - SUM(ISNULL(ICT.N_Tax_Value,0))
                    FROM T_Invoice_Detail_Tax IDT
                    LEFT JOIN #ICTNX ICT  ON (IDT.I_Tax_ID = ICT.I_Tax_ID AND IDT.I_Invoice_Detail_ID = ICT.I_Invoice_Detail_ID)
                    WHERE IDT.I_Invoice_Detail_ID = @I_Invoice_Detail_ID
                    GROUP BY IDT.I_Tax_ID, IDT.I_Invoice_Detail_ID
                    HAVING (SUM(IDT.N_Tax_Value_Scheduled) - SUM(ISNULL(ICT.N_Tax_Value,0))) > 0
                END
            ELSE
                BEGIN
                    --INSERT INTO T_Credit_Note_Invoice_Child_Detail_Tax(I_Credit_Note_Invoice_Child_Detail_ID,I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
                    --SELECT @I_Credit_Note_Invoice_Child_Detail_ID, B.I_Tax_ID, B.I_Invoice_Detail_ID, ISNULL(SUM(B.N_Tax_Value),0)
                    --FROM(
                    --    SELECT TAX.I_Tax_ID, @I_Invoice_Detail_ID AS I_Invoice_Detail_ID,
                    --    CAST((ISNULL(@N_Amount_Due,0) - ISNULL(@N_CN_Amount,0)) * TAX.N_Tax_Rate / 100.00 AS NUMERIC(18,2)) AS N_Tax_Value
                    --    FROM
                    --    (SELECT TCFC.N_Tax_Rate, TM.I_Tax_ID
                    --    FROM (select * from dbo.T_Tax_Master) AS TM
                    --    INNER JOIN (select * from dbo.T_Tax_Country_Fee_Component where I_Fee_Component_ID=@I_Fee_Component_ID) AS TCFC
                    --        ON (TM.I_Tax_ID = TCFC.I_Tax_ID
                    --            AND TM.I_Country_ID = TCFC.I_Country_ID AND TCFC.N_Tax_Rate > 0
                    --            AND @Dt_Installment_Date BETWEEN TCFC.Dt_Valid_From AND TCFC.Dt_Valid_To
                    --            )
                    --    ) TAX
                    --) B
                    --GROUP BY B.I_Tax_ID, B.I_Invoice_Detail_ID

                    IF(@N_Amount_Due>0 and @TaxDiff>0)
                      BEGIN
                   
                       

                        --IF(@ZeroTaxID>0)
                        IF(@ZeroTaxID=@TotalTaxID)
                        BEGIN
                             INSERT INTO T_Credit_Note_Invoice_Child_Detail_Tax(I_Credit_Note_Invoice_Child_Detail_ID,I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
                             select @I_Credit_Note_Invoice_Child_Detail_ID,(CASE WHEN ITax=0 THEN RTax ELSE ITax END),IInv
                            ,CAST((((ISNULL(@N_Amount_Due,0) - ISNULL(@N_CN_Amount,0))*(tcfc.N_Tax_Rate))/100) AS NUMERIC(18,2)) AS TaxDiff--,TaxDiff 
                            from #TAXDiff as tf Inner Join dbo.T_Tax_Master as tm on (CASE WHEN ITax=0 THEN RTax ELSE ITax END)=tm.I_Tax_ID
                            Inner Join T_Tax_Country_Fee_Component AS tcfc on TM.I_Tax_ID = tcfc.I_Tax_ID
                            AND TM.I_Country_ID = tcfc.I_Country_ID AND tcfc.N_Tax_Rate > 0
                            AND I_Fee_Component_ID=@I_Fee_Component_ID
                            AND @Dt_Installment_Date BETWEEN tcfc.Dt_Valid_From AND tcfc.Dt_Valid_To
                            WHERE IInv=@I_Invoice_Detail_ID


                        END
                       ELSE
                        BEGIN
                            INSERT INTO T_Credit_Note_Invoice_Child_Detail_Tax(I_Credit_Note_Invoice_Child_Detail_ID,I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
                            select @I_Credit_Note_Invoice_Child_Detail_ID,(CASE WHEN ITax=0 THEN RTax ELSE ITax END),IInv,TAXDiff  from #TAXDiff
                            WHERE IInv=@I_Invoice_Detail_ID

                        END

                       

                      END
                    IF(@N_Amount_Due=0 and @TaxDiff>0)
                      BEGIN

                        INSERT INTO T_Credit_Note_Invoice_Child_Detail_Tax(I_Credit_Note_Invoice_Child_Detail_ID,I_Tax_ID,I_Invoice_Detail_ID,N_Tax_Value)
                        select @I_Credit_Note_Invoice_Child_Detail_ID,(CASE WHEN ITax=0 THEN RTax ELSE ITax END),IInv,TAXDiff   from #TAXDiff
                        WHERE IInv=@I_Invoice_Detail_ID

                      END

                END
        END

        SET @row = @row + 1
    END
    DROP TABLE #ICHNW   
    DROP TABLE #ICHNX
    DROP TABLE #ICTNX
   
    DROP TABLE #ITAX
    DROP TABLE #RTAX
    DROP TABLE #TAXDiff
END
GO
PRINT N'Creating Procedure [dbo].[uspInsertInvoice]...';


GO

/**************************************************************************************************************          
Created by  : Debarshi Basu          
Date  : 01.05.2007          
Description : This SP will save the Invoice Details          
Parameters  :  @sInvoice xml          
**************************************************************************************************************/          
          
          
CREATE PROCEDURE [dbo].[uspInsertInvoice] 
(
	@sInvoice XML,
	@iBrandID INT = NULL,
	@iParentInvoiceID INT = NULL
)
AS 
    BEGIN TRY           
          
        DECLARE @iInvoiceID INT          
        DECLARE @iInvoiceChildID INT          
        DECLARE @iInvoiceChildDetailsID INT          
           
        BEGIN TRANSACTION   
        --  CREATE INVOICE NUMBER

		DECLARE @StudentDetailID INT=0
		DECLARE @BatchID INT=0
        
         CREATE TABLE #tempInvoiceNOChildDetail
            (
			  I_Invoice_Header_ID INT ,             
              I_Fee_Component_ID INT ,
              I_Invoice_Detail_ID INT ,
              I_Installment_No INT ,
              Dt_Installment_Date DATETIME ,
              N_Amount_Due NUMERIC(18, 2) ,
			  N_Amount_Discount NUMERIC(18, 2) ,
			  N_Amount_Payable NUMERIC(18, 2) ,
              I_Display_Fee_Component_ID INT ,
              I_Sequence INT,
              ID INT IDENTITY(1,1)
            ) 
               
-- Create Temporary Table To store Invoice Parent Information          
        CREATE TABLE #tempInvoice
            (
              I_Invoice_Header_ID INT ,
              I_Student_Detail_ID INT ,
              I_Centre_Id INT ,
              N_Invoice_Amount NUMERIC(18, 2) ,
              N_Discount_Amount NUMERIC(18, 2) ,
              I_Coupon_Discount INT ,
              N_Tax_Amount NUMERIC(18, 2) ,
              Dt_Invoice_Date DATETIME ,
              I_Status INT ,
              I_Discount_Scheme_ID INT ,
              I_Discount_Applied_At INT ,
              S_Crtd_By VARCHAR(20) ,
              Dt_Crtd_On DATETIME
            )          
          
-- Insert Values into Temporary Table          
        INSERT  INTO #tempInvoice
                SELECT  T.c.value('@I_Invoice_Header_ID', 'int') ,
                        T.c.value('@I_Student_Detail_ID', 'int') ,
                        T.c.value('@I_Centre_Id', 'int') ,
                        T.c.value('@N_Invoice_Amount', 'numeric(18, 2)') ,
                        T.c.value('@N_Discount_Amount', 'numeric(18, 2)') ,
                        T.c.value('@I_Coupon_Discount', 'INT') ,
                        T.c.value('@N_Tax_Amount', 'numeric(18, 2)') ,
                        T.c.value('@Dt_Invoice_Date', 'datetime') ,
                        T.c.value('@I_Status', 'int') ,
                        T.c.value('@I_Discount_Scheme_ID', 'int') ,
                        T.c.value('@I_Discount_Applied_At', 'int') ,
                        T.c.value('@S_Crtd_By', 'varchar(20)') ,
                        T.c.value('@Dt_Crtd_On', 'datetime')
                FROM    @sInvoice.nodes('/Invoice') T ( c )          
          
-- create temporary table for storing Invoice Child Header Information           
        CREATE TABLE #tempInvoiceChild
            (
              I_Invoice_Child_Header_ID INT ,
              I_Invoice_Header_ID INT ,
              I_Course_ID INT ,
              I_Batch_ID INT ,
              I_Course_FeePlan_ID INT ,
              C_Is_LumpSum CHAR(1) ,
              N_Discount_Amount NUMERIC(18, 2) ,
              I_Discount_Scheme_ID INT ,
              I_Discount_Applied_At INT
            )          
          
-- insert value for the invoice child           
        INSERT  INTO #tempInvoiceChild
                SELECT  T.c.value('@I_Invoice_Child_Header_ID', 'int') ,
                        T.c.value('@I_Invoice_Header_ID', 'int') ,
                        CASE WHEN T.c.value('@I_Course_ID', 'int') = 0
                             THEN NULL
                             ELSE T.c.value('@I_Course_ID', 'int')
                        END ,
                        CASE WHEN T.c.value('@I_Batch_ID', 'int') = 0
                             THEN NULL
                             ELSE T.c.value('@I_Batch_ID', 'int')
                        END ,
                        CASE WHEN T.c.value('@I_Course_FeePlan_ID', 'int') = 0
                             THEN NULL
                             ELSE T.c.value('@I_Course_FeePlan_ID', 'int')
                        END ,
                        T.c.value('@C_Is_LumpSum', 'char(1)') ,
                        T.c.value('@N_Discount_Amount', 'numeric(18, 2)') ,
                        T.c.value('@I_Discount_Scheme_ID', 'int') ,
                        T.c.value('@I_Discount_Applied_At', 'int')
                FROM    @sInvoice.nodes('/Invoice/InvoiceChild') T ( c )          
           
-- create temporary table for the insertion of invoice child details          
        CREATE TABLE #tempInvoiceChildDetail
            (
              I_Invoice_Detail_ID INT ,
              I_Fee_Component_ID INT ,
              I_Invoice_Child_Header_ID INT ,
              I_Installment_No INT ,
              Dt_Installment_Date DATETIME ,
              N_Amount_Due NUMERIC(18, 2) ,
			  N_Amount_Discount NUMERIC(18, 2) ,
			  N_Amount_Payable NUMERIC(18, 2) ,
              I_Display_Fee_Component_ID INT ,
              I_Sequence INT,
              ID INT IDENTITY(1,1)
            )          
-- insert values for the invoice child details          
        INSERT  INTO #tempInvoiceChildDetail
                SELECT  T.c.value('@I_Invoice_Detail_ID', 'int') ,
                        T.c.value('@I_Fee_Component_ID', 'int') ,
                        T.c.value('@I_Invoice_Child_Header_ID', 'int') ,
                        T.c.value('@I_Installment_No', 'int') ,
                        T.c.value('@Dt_Installment_Date', 'datetime') ,
                        T.c.value('@N_Amount_Due', 'numeric(18, 2)') ,
						T.c.value('@N_Amount_Discount', 'numeric(18, 2)') ,
						T.c.value('@N_Amount_Payable', 'numeric(18, 2)') ,
                        T.c.value('@I_Display_Fee_Component_ID', 'int') ,
                        T.c.value('@I_Sequence', 'int')
                FROM    @sInvoice.nodes('/Invoice/InvoiceChild/InvoiceChildDetails/Installment') T ( c )          
          
-- create table to store tax details for the invoice          
        CREATE TABLE #tempInvoiceTax
            (
              I_Tax_ID INT ,
              I_Invoice_Detail_ID INT ,
              N_Tax_Value NUMERIC(18, 2)
            )          
          
-- insert the details of the tax components in the temp table           
        INSERT  INTO #tempInvoiceTax
                SELECT  T.c.value('@I_Tax_ID', 'int') ,
                        T.c.value('@I_Invoice_Detail_ID', 'int') ,
                        T.c.value('@N_Tax_Value', 'numeric(18, 2)')
                FROM    @sInvoice.nodes('/Invoice/InvoiceChild/InvoiceChildDetails/Installment/InvoiceChildTaxDetails/TaxDetails') T ( c )          
          
--- start the insertion process          
--- using cursors          
--          
-- START THE DEFINATIONS FOR THE VARIABLES          
-- defination of the variables of the invoice parent          
        DECLARE @ipI_Invoice_Header_ID INT          
        DECLARE @ipI_Student_Detail_ID INT          
        DECLARE @ipI_Centre_Id INT          
        DECLARE @ipN_Invoice_Amount NUMERIC(18, 2)          
        DECLARE @ipN_Discount_Amount NUMERIC(18, 2)          
        DECLARE @ipI_Coupon_Discount INT          
        DECLARE @ipN_Tax_Amount NUMERIC(18, 2)          
        DECLARE @ipDt_Invoice_Date DATETIME          
        DECLARE @ipI_Status INT          
        DECLARE @ipI_Discount_Scheme_ID INT          
        DECLARE @ipI_Discount_Applied_At INT          
        DECLARE @ipS_Crtd_By VARCHAR(20)          
        DECLARE @ipDt_Crtd_On DATETIME           
--defination of the variables of the invoice child          
        DECLARE @icI_Invoice_Child_Header_ID INT          
        DECLARE @icI_Invoice_Header_ID INT          
        DECLARE @icI_Course_ID INT          
        DECLARE @icI_Batch_ID INT          
        DECLARE @icI_Course_FeePlan_ID INT          
        DECLARE @icC_Is_LumpSum CHAR(1)        
        DECLARE @icN_Discount_Amount NUMERIC(18, 2)    
        DECLARE @icI_Discount_Scheme_ID INT    
        DECLARE @icI_Discount_Applied_At INT            
--DEFINATION OF THE VARIABLES OF THE INVOICE CHILD DETAILS          
        DECLARE @icdI_Invoice_Detail_ID INT          
        DECLARE @icdI_Fee_Component_ID INT          
        DECLARE @icdI_Invoice_Child_Header_ID INT          
        DECLARE @icdI_Installment_No INT          
        DECLARE @icdDt_Installment_Date DATETIME          
        DECLARE @icdN_Amount_Due NUMERIC(18, 2)  
		DECLARE @icdN_Amount_Discount NUMERIC(18, 2)
		DECLARE @icdN_Amount_Payable NUMERIC(18, 2)
        DECLARE @icdI_Display_Fee_Component_ID INT          
        DECLARE @icdI_Sequence INT 
        
        DECLARE @insertedI_InstallmentNo INT
        DECLARE @insertedPre_InstallmentNo INT
        DECLARE @insertedDt_Installment_Date DATETIME
        DECLARE @insertedN_Amount_Due NUMERIC(18,2)
        DECLARE @InvoiceType VARCHAR(10)
        DECLARE @InvoiceNumber VARCHAR(10)
        DECLARE @insertedI_Invoice_Header_ID INT
                 
-- DEFINATION OF THE VARIABLE TO INSERT TAX DETAILS          
        DECLARE @itdI_Tax_ID INT          
        DECLARE @itdI_Invoice_Detail_ID INT          
        DECLARE @itdN_Tax_Value NUMERIC(18, 2)          
          
       
        
   --SELECT * FROM #tempInvoiceChildDetail   
  
          
 -- declare cursor for invoice details          
        DECLARE UPLOADINVOICEPARENT_CURSOR CURSOR FOR           
        SELECT I_Invoice_Header_ID,          
        I_Student_Detail_ID,          
        I_Centre_Id,          
        N_Invoice_Amount,          
        N_Discount_Amount,          
        I_Coupon_Discount,          
        N_Tax_Amount,          
        Dt_Invoice_Date,          
        I_Status,          
        I_Discount_Scheme_ID,          
        I_Discount_Applied_At,          
        S_Crtd_By,            
        Dt_Crtd_On          
        FROM #tempInvoice          
          
        OPEN UPLOADINVOICEPARENT_CURSOR           
        FETCH NEXT FROM UPLOADINVOICEPARENT_CURSOR           
 INTO @ipI_Invoice_Header_ID,          
 @ipI_Student_Detail_ID,          
 @ipI_Centre_Id,          
 @ipN_Invoice_Amount,          
 @ipN_Discount_Amount,          
 @ipI_Coupon_Discount,          
 @ipN_Tax_Amount,          
 @ipDt_Invoice_Date,          
 @ipI_Status,          
 @ipI_Discount_Scheme_ID,          
 @ipI_Discount_Applied_At,          
 @ipS_Crtd_By,          
 @ipDt_Crtd_On          
              
        WHILE @@FETCH_STATUS = 0 
            BEGIN           
                INSERT  INTO dbo.T_Invoice_Parent
                        ( I_Student_Detail_ID ,
                          I_Centre_Id ,
                          N_Invoice_Amount ,
                          N_Discount_Amount ,
                          I_Coupon_Discount ,
                          N_Tax_Amount ,
                          Dt_Invoice_Date ,
                          I_Status ,
                          I_Discount_Scheme_ID ,
                          I_Discount_Applied_At ,
                          S_Crtd_By ,
                          Dt_Crtd_On,
                          I_Parent_Invoice_ID
                        )
                VALUES  ( @ipI_Student_Detail_ID ,
                          @ipI_Centre_Id ,
                          @ipN_Invoice_Amount ,
                          @ipN_Discount_Amount ,
                          @ipI_Coupon_Discount ,
                          @ipN_Tax_Amount ,
                          DATEADD(minute,-1,@ipDt_Invoice_Date) ,--susmita:decrease invoice date -1 min
                          @ipI_Status ,
                          @ipI_Discount_Scheme_ID ,
                          @ipI_Discount_Applied_At ,
                          @ipS_Crtd_By ,
                          DATEADD(minute,-1,@ipDt_Crtd_On),--susmita:decrease invoice date -1 min
                          @iParentInvoiceID
                        )          
          
                SET @iInvoiceID = SCOPE_IDENTITY()          
                DECLARE @iInvoiceNo BIGINT          
            
                SELECT  @iInvoiceNo = MAX(CAST(S_Invoice_No AS BIGINT))
                FROM    T_Invoice_Parent TIP
                WHERE   I_Invoice_Header_ID NOT IN (
                        SELECT  I_Invoice_Header_ID
                        FROM    T_Invoice_Parent
                        WHERE   @iInvoiceNo LIKE '%[A-Z]' )          
				AND TIP.I_Centre_Id IN (SELECT I_Centre_Id FROM dbo.T_Brand_Center_Details AS TBCD WHERE I_Brand_ID = @iBrandID AND I_Status = 1)        
          
                SET @iInvoiceNo = ISNULL(@iInvoiceNo, 0) + 1          
          
                UPDATE  T_INVOICE_PARENT
                SET     S_Invoice_No = CAST(@iInvoiceNo AS VARCHAR(20))
                WHERE   I_Invoice_Header_ID = @iInvoiceID 
				
				SET @StudentDetailID=@ipI_Student_Detail_ID
          
             
   -- open cursor for invoice child          
                DECLARE UPLOADINVOICECHILD_CURSOR CURSOR FOR           
                SELECT I_Invoice_Child_Header_ID,          
                I_Invoice_Header_ID,          
                I_Course_ID,          
                I_Batch_ID,          
                I_Course_FeePlan_ID,          
                C_Is_LumpSum ,        
                N_Discount_Amount,    
                I_Discount_Scheme_ID,    
                I_Discount_Applied_At         
                FROM #tempInvoiceChild          
                WHERE I_Invoice_Header_ID = @ipI_Invoice_Header_ID          
          
                OPEN UPLOADINVOICECHILD_CURSOR           
                FETCH NEXT FROM UPLOADINVOICECHILD_CURSOR           
   INTO @icI_Invoice_Child_Header_ID,          
    @icI_Invoice_Header_ID,          
    @icI_Course_ID,          
    @icI_Batch_ID,          
    @icI_Course_FeePlan_ID,          
    @icC_Is_LumpSum ,         
    @icN_Discount_Amount,    
    @icI_Discount_Scheme_ID,    
    @icI_Discount_Applied_At            
            
                WHILE @@FETCH_STATUS = 0 
                    BEGIN           
                        INSERT  INTO dbo.T_Invoice_Child_Header
                                ( I_Invoice_Header_ID ,
                                  I_Course_ID ,
                                  I_Course_FeePlan_ID ,
                                  C_Is_LumpSum ,
                                  N_Discount_Amount ,
                                  I_Discount_Scheme_ID ,
                                  I_Discount_Applied_At
                                )
                        VALUES  ( @iInvoiceID ,
                                  @icI_Course_ID ,
                                  @icI_Course_FeePlan_ID ,
                                  @icC_Is_LumpSum ,
                                  @icN_Discount_Amount ,
                                  @icI_Discount_Scheme_ID ,
                                  @icI_Discount_Applied_At
                                )          
              
                        SET @iInvoiceChildID = SCOPE_IDENTITY()          
          
                        IF @icI_Batch_ID IS NOT NULL 
                            BEGIN      
                                INSERT  INTO dbo.T_Invoice_Batch_Map
                                        ( I_Invoice_Child_Header_ID ,
                                          I_Batch_ID ,
                                          I_Status ,
                                          S_Crtd_By ,
                                          Dt_Crtd_On
                                        )
                                VALUES  ( @iInvoiceChildID ,
                                          @icI_Batch_ID ,
                                          @ipI_Status ,
                                          @ipS_Crtd_By ,
                                          DATEADD(minute,-1,@ipDt_Crtd_On) --susmita: invoice creation date decrease by 1 min
                                        )
										
								SET @BatchID=@icI_Batch_ID
								
                            END        
              
    -- START INSERTION PROCESS FOR INVOICE CHILD DETAILS          
          
                        DECLARE UPLOADINVOICECHILDDETAILS_CURSOR CURSOR FOR           
                        SELECT I_Invoice_Detail_ID,          
                        I_Fee_Component_ID,          
                        I_Invoice_Child_Header_ID,          
                        I_Installment_No,          
                        Dt_Installment_Date,          
                        N_Amount_Due,
						N_Amount_Discount,
						N_Amount_Payable,
                        I_Display_Fee_Component_ID,          
                        I_Sequence          
                        FROM #tempInvoiceChildDetail          
                        WHERE I_Invoice_Child_Header_ID = @icI_Invoice_Child_Header_ID          
          
                        OPEN UPLOADINVOICECHILDDETAILS_CURSOR           
                        FETCH NEXT FROM UPLOADINVOICECHILDDETAILS_CURSOR           
    INTO @icdI_Invoice_Detail_ID,          
      @icdI_Fee_Component_ID,          
      @icdI_Invoice_Child_Header_ID,          
      @icdI_Installment_No,          
      @icdDt_Installment_Date,          
      @icdN_Amount_Due,
	  @icdN_Amount_Discount,
	  @icdN_Amount_Payable,
      @icdI_Display_Fee_Component_ID,          
      @icdI_Sequence          
                 
                        WHILE @@FETCH_STATUS = 0 
                            BEGIN           
                                INSERT  INTO dbo.T_Invoice_Child_Detail
                                        ( I_Fee_Component_ID ,
                                          I_Invoice_Child_Header_ID ,
                                          I_Installment_No ,
                                          Dt_Installment_Date ,
                                          N_Amount_Due ,
										  N_Discount_Amount,
										  N_Due,
                                          I_Display_Fee_Component_ID ,
                                          I_Sequence
                                        )
                                VALUES  ( @icdI_Fee_Component_ID ,
                                          @iInvoiceChildID ,
                                          @icdI_Installment_No ,
                                          @icdDt_Installment_Date ,
                                          @icdN_Amount_Due ,
										  @icdN_Amount_Discount,
										  @icdN_Amount_Payable,
                                          @icdI_Display_Fee_Component_ID ,
                                          @icdI_Sequence
                                        )  
          
                                SET @iInvoiceChildDetailsID = SCOPE_IDENTITY() 
                                
                                INSERT  INTO #tempInvoiceNOChildDetail    
                                                            
                                 VALUES  (
										  @iInvoiceID,
										  @icdI_Fee_Component_ID ,
                                          @iInvoiceChildDetailsID ,
                                          @icdI_Installment_No ,
                                          @icdDt_Installment_Date ,
                                          @icdN_Amount_Due ,
										  @icdN_Amount_Discount,
										  @icdN_Amount_Payable,
                                          @icdI_Display_Fee_Component_ID ,
                                          @icdI_Sequence
                                        )  
                                       
          
--     -- INITIATE PROCESS TO ENTER THE TAX DETAILS FOR THE INVOICE          
          
                                DECLARE UPLOADINVOICECHILDDETAILSTAX_CURSOR CURSOR FOR           
                                SELECT I_Tax_ID,          
                                I_Invoice_Detail_ID,          
                                N_Tax_Value          
                                FROM #tempInvoiceTax          
                                WHERE I_Invoice_Detail_ID = @icdI_Invoice_Detail_ID          
          
                                OPEN UPLOADINVOICECHILDDETAILSTAX_CURSOR           
                                FETCH NEXT FROM UPLOADINVOICECHILDDETAILSTAX_CURSOR           
     INTO @itdI_Tax_ID,          
      @itdI_Invoice_Detail_ID,          
      @itdN_Tax_Value          
                  
                                WHILE @@FETCH_STATUS = 0 
                                    BEGIN           
                                        INSERT  INTO dbo.T_Invoice_Detail_Tax
                                                ( I_Tax_ID ,
                                                  I_Invoice_Detail_ID ,
                                                  N_Tax_Value,
                                                  N_Tax_Value_Scheduled
                                                )
                                        VALUES  ( @itdI_Tax_ID ,
                                                  @iInvoiceChildDetailsID ,
                                                  @itdN_Tax_Value,
                                                  @itdN_Tax_Value
                                                )          
          
          
                                        FETCH NEXT FROM UPLOADINVOICECHILDDETAILSTAX_CURSOR           
      INTO @itdI_Tax_ID,          
       @itdI_Invoice_Detail_ID,          
       @itdN_Tax_Value          
                                    END          
                                CLOSE UPLOADINVOICECHILDDETAILSTAX_CURSOR           
                                DEALLOCATE UPLOADINVOICECHILDDETAILSTAX_CURSOR           
           
--     -- END OF PROCESS TO ENTER THE TAX DETAILS              
          
          
                                FETCH NEXT FROM UPLOADINVOICECHILDDETAILS_CURSOR           
     INTO @icdI_Invoice_Detail_ID,          
       @icdI_Fee_Component_ID,          
       @icdI_Invoice_Child_Header_ID,          
       @icdI_Installment_No,          
       @icdDt_Installment_Date,          
       @icdN_Amount_Due, 
	   @icdN_Amount_Discount,
	   @icdN_Amount_Payable,
       @icdI_Display_Fee_Component_ID,          
       @icdI_Sequence          
                            END          
                        CLOSE UPLOADINVOICECHILDDETAILS_CURSOR           
                        DEALLOCATE UPLOADINVOICECHILDDETAILS_CURSOR           
          
    -- FETCH NEXT FOR INVOICE CHILD CURSOR          
                        FETCH NEXT FROM UPLOADINVOICECHILD_CURSOR           
    INTO @icI_Invoice_Child_Header_ID,          
     @icI_Invoice_Header_ID,          
     @icI_Course_ID,          
     @icI_Batch_ID,          
     @icI_Course_FeePlan_ID,               
     @icC_Is_LumpSum,      
     @icN_Discount_Amount,    
     @icI_Discount_Scheme_ID,    
     @icI_Discount_Applied_At          
                    END          
                CLOSE UPLOADINVOICECHILD_CURSOR           
                DEALLOCATE UPLOADINVOICECHILD_CURSOR           
          
  -- FETCH NEXT FOR INVOICE PARENT CURSOR          
                FETCH NEXT FROM UPLOADINVOICEPARENT_CURSOR           
    INTO @ipI_Invoice_Header_ID,          
    @ipI_Student_Detail_ID,          
    @ipI_Centre_Id,          
    @ipN_Invoice_Amount,          
    @ipN_Discount_Amount,          
    @ipI_Coupon_Discount,          
    @ipN_Tax_Amount,          
    @ipDt_Invoice_Date,          
    @ipI_Status,          
    @ipI_Discount_Scheme_ID,          
    @ipI_Discount_Applied_At,          
    @ipS_Crtd_By,          
    @ipDt_Crtd_On          
            END          
          
        CLOSE UPLOADINVOICEPARENT_CURSOR           
        DEALLOCATE UPLOADINVOICEPARENT_CURSOR           
          
-- Update Course wise fees paid for the invoice          
        DECLARE @iInvoiceChildHeaderID INT           
        DECLARE @iCourseFee NUMERIC(18, 2)          
        DECLARE @iCourseTax NUMERIC(18, 2)          
          
          
        DECLARE UPDATE_COURSEFEE CURSOR FOR          
        SELECT I_Invoice_Child_Header_ID FROM dbo.T_Invoice_Child_Header          
        WHERE I_Invoice_Header_ID = @iInvoiceID          
          
          
        OPEN UPDATE_COURSEFEE           
        FETCH NEXT FROM UPDATE_COURSEFEE INTO @iInvoiceChildHeaderID          
            
        WHILE @@FETCH_STATUS = 0 
            BEGIN           
                SELECT  @iCourseFee = SUM(N_Amount_Due)
                FROM    dbo.T_Invoice_Child_Detail
                WHERE   I_Invoice_Child_Header_ID = @iInvoiceChildHeaderID          
          
                SELECT  @iCourseTax = SUM(IDT.N_Tax_Value)
                FROM    dbo.T_Invoice_Detail_Tax IDT
                        INNER JOIN dbo.T_Invoice_Child_Detail ICD ON IDT.I_Invoice_Detail_ID = ICD.I_Invoice_Detail_ID
                WHERE   ICD.I_Invoice_Child_Header_ID = @iInvoiceChildHeaderID          
          
                UPDATE  dbo.T_Invoice_Child_Header
                SET     N_Amount = @iCourseFee ,
                        N_Tax_Amount = @iCourseTax
                WHERE   I_Invoice_Child_Header_ID = @iInvoiceChildHeaderID          
          
                FETCH NEXT FROM UPDATE_COURSEFEE INTO @iInvoiceChildHeaderID                
              
            END          
            
        CLOSE UPDATE_COURSEFEE           
        DEALLOCATE UPDATE_COURSEFEE
		
		
        PRINT @StudentDetailID
		PRINT @BatchID
		IF(@StudentDetailID>0 and @BatchID>0)
		BEGIN
			EXEC LMS.uspInsertStudentBatchDetailsForInterface @StudentDetailID,@BatchID,NULL,NULL
		END


         SELECT  @iInvoiceID AS I_Invoice_ID   
        
         -- INSERT Invoice Number
						DECLARE @row INT = 1
						DECLARE @count INT
						DECLARE @I_Invoice_Header_ID INT
						DECLARE @Dt_Installment_Date DATETIME
						DECLARE @I_Invoice_Detail_ID INT
						DECLARE @I_Installment_No INT
						DECLARE @INVN VARCHAR(256)
						
						SELECT @count = COUNT(I_Invoice_Detail_ID) FROM #tempInvoiceChildDetail
						
						
						WHILE (@row <= @count)
				BEGIN

					SELECT 
						@I_Invoice_Header_ID = I_Invoice_Header_ID,
						@Dt_Installment_Date = Dt_Installment_Date,
						@I_Invoice_Detail_ID = I_Invoice_Detail_ID,
						@I_Installment_No = I_Installment_No ,
						@InvoiceType = 'I' 
					FROM #tempInvoiceNOChildDetail
					WHERE ID = @row	
						
					EXEC dbo.uspGenerateInvoiceNumber  @I_Invoice_Header_ID,@I_Installment_No,@Dt_Installment_Date,@InvoiceType, @INVN OUTPUT							
						
					UPDATE T_Invoice_Child_Detail SET S_Invoice_Number = @INVN WHERE I_Invoice_Detail_ID = @I_Invoice_Detail_ID

					
				SET @row = @row + 1
				END
				--SELECT * FROM #tempInvoiceNOChildDetail
       -- END TO INSERT INVOICE NUMBER 

	   


		--SELECT  @iInvoiceID AS I_Invoice_ID 
                
          
              
        COMMIT TRANSACTION          
    END TRY          
    BEGIN CATCH          
--Error occurred:            
        ROLLBACK TRANSACTION          
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT          
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()          
          
        RAISERROR(@ErrMsg, @ErrSeverity, 1)          
    END CATCH
GO
PRINT N'Creating Procedure [dbo].[uspInsertPreEnquiryDetails]...';


GO
CREATE PROCEDURE [dbo].[uspInsertPreEnquiryDetails]  
    (  
      @Centre INT ,  
      @IEnquiryStatusCode INT = NULL ,  
      @FirstName VARCHAR(50) ,  
      @MiddleName VARCHAR(50) ,  
      @LastName VARCHAR(50) ,  
      @DtBirthDate DATETIME ,  
      @Age VARCHAR(20) ,  
      @casteID INT = NULL ,  
      @MobileNo VARCHAR(20) ,  
      @CurrCityID INT ,  
      @CurrStateID INT ,  
      @CurrCountryID INT ,  
      @CurrAddress1 VARCHAR(200) ,  
      @CurrAddress2 VARCHAR(200) ,  
      @CurrPincode VARCHAR(20) ,  
      @FatherName VARCHAR(200) ,  
      @MotherName VARCHAR(200) ,  
      @EnquiryDesc VARCHAR(500) ,  
      @IsPreEnquiry BIT ,  
      @CrtdBy VARCHAR(20) ,  
      @DtCrtdOn DATETIME ,  
      @sSelectedCourseID VARCHAR(100) = NULL ,  
      @InfoSourceID INT = NULL ,  
      @bHasGivenOtherExam BIT = NULL ,  
      @sQualificationXML XML = NULL ,  
      @iSeatType INT = NULL ,  
      @iEnrolmentType INT = NULL ,  
      @sEnrolmentNo VARCHAR(50) = NULL ,  
      @iRankObtained INT = NULL ,  
      @dtFirstFollowUpDate DATETIME,  
      @IsLateral BIT = NULL ,  
      @IPreEnquiryFor INT = NULL,
      @GuardianName VARCHAR(200)=NULL,
      @GuardianPhoneNo VARCHAR(20)=NULL,
      @iFatherIncomeGroup INT=NULL,
      --@iMotherIncomeGroup INT=NULL,
      @EducationCurrentStatus INT=NULL,
	  @EmailID VARCHAR(MAX)=NULL,
	  @GenderID INT=NULL
	  ,@sRefererName varchar(max)=null,
	@sRefererMobileNo varchar(20)=null
    )  
AS   
    BEGIN TRY                    
        SET NOCOUNT OFF ;                    
           
        DECLARE @iEnquiryID INT                    
                           
        DECLARE @iEmployeeId INT       
        DECLARE @sSelectedCourseIDs VARCHAR(100)                      
           
        BEGIN TRANSACTION                    
                     
                  
        IF ( SELECT COUNT(*)  
             FROM   dbo.T_Enquiry_Regn_Detail AS TERD  
             WHERE  I_Centre_Id=  @Centre AND S_Mobile_No = @MobileNo  
           ) = 0   
            BEGIN        
                INSERT  INTO dbo.T_Enquiry_Regn_Detail  
                        ( I_Centre_Id ,  
                          I_Enquiry_Status_Code ,  
                          S_First_Name ,  
                          S_Middle_Name ,  
                          S_Last_Name ,  
                          Dt_Birth_Date ,  
                          S_Age ,  
                          I_Caste_ID ,  
                          S_Mobile_No ,  
                          I_Curr_City_ID ,  
                          I_Curr_State_ID ,  
                          I_Curr_Country_ID ,  
                          S_Curr_Address1 ,  
                          S_Curr_Address2 ,  
                          S_Curr_Pincode ,  
                          S_Father_Name ,  
                          S_Mother_Name ,
                          S_Guardian_Name,
                          S_Guardian_Phone_No,  
                          S_Enquiry_Desc ,  
                          B_IsPreEnquiry ,  
                          I_Info_Source_ID ,  
                          B_Has_Given_Exam ,  
                          I_Seat_Type_ID ,  
                          I_Enrolment_Type_ID ,  
                          S_Enrolment_No ,  
                          I_Rank_Obtained ,  
                          S_Crtd_By ,  
                          Dt_Crtd_On,  
                          B_IsLateral,  
                          I_PreEnquiryFor,
                          I_Relevence_ID,
                          I_Monthly_Family_Income_ID,
                          PreEnquiryDate,
                          PreEnquiry_Crtd_By,
						  S_Email_ID,
						  I_Sex_ID
                          --I_Mother_Income_Group_ID               
                        )  
                VALUES  ( @Centre ,  
                          @IEnquiryStatusCode ,  
                          @FirstName ,  
                          @MiddleName ,  
                          @LastName ,  
                          @DtBirthDate ,  
                          @Age ,  
                          @casteID , -- I_Caste_ID - int      
                          @MobileNo ,  
                          @CurrCityID ,  
                          @CurrStateID ,  
                          @CurrCountryID ,  
       @CurrAddress1 ,  
                          @CurrAddress2 ,  
                          @CurrPincode ,  
                          @FatherName ,  
                          @MotherName ,
                          @GuardianName,
                          @GuardianPhoneNo,  
                          @EnquiryDesc ,  
                          @IsPreEnquiry ,  
                          @InfoSourceID , -- I_Info_Source_ID - int        
                          @bHasGivenOtherExam ,  
    @iSeatType ,  
                          @iEnrolmentType ,  
                          @sEnrolmentNo ,  
                          @iRankObtained ,  
                          @CrtdBy ,  
                          @DtCrtdOn,  
                          @IsLateral,  
                          @IPreEnquiryFor,
                          1,
                          @iFatherIncomeGroup,
                          @DtCrtdOn,
                          @CrtdBy,
						  @EmailID,
						  @GenderID
                          --@iMotherIncomeGroup          
                        )                    
          
                SELECT  @iEnquiryID = @@IDENTITY   
				
  -- Populate Enquiry Source Details 


		  if (@iEnquiryID > 0)
		  BEGIN

			if exists(
			select * from T_Information_Source_Master 
			where I_Info_Source_ID=@InfoSourceID and S_Info_Source_Name like '%Reference%'
			)

			BEGIN

				exec uspInsertUpdateEnquirySourceDetails @InfoSourceID,@iEnquiryID,@sRefererName,@sRefererMobileNo,@CrtdBy

			END

		  END
                       
  -- Update the Enquiry No                     
                UPDATE  dbo.T_Enquiry_Regn_Detail  
                SET     S_Enquiry_No = CAST(@iEnquiryID AS VARCHAR(20))  
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID                    
                   
  -- Get the Employee Id of the Councellor                     
                SELECT  @iEmployeeId = I_Employee_ID  
                FROM    dbo.T_Employee_Dtls  
                WHERE   I_Employee_ID = ( SELECT    I_Reference_ID  
                                          FROM      dbo.T_User_Master  
                                          WHERE     S_Login_ID = @CrtdBy  
                                        )        
  -- Update the Courses for the Enquiry                    
                INSERT  INTO dbo.T_Enquiry_Course  
                        ( I_Course_ID ,  
                          I_Enquiry_Regn_ID        
                        )  
                        SELECT  * ,  
                                @iEnquiryID  
                        FROM    dbo.fnString2Rows(@sSelectedCourseID, ',')                     
   --Update enquiry Qualification Information           
                INSERT  INTO dbo.T_Enquiry_Qualification_Details  
                        ( I_Enquiry_Regn_ID ,  
                          S_Name_Of_Exam ,  
                          S_University_Name ,  
                          S_Year_From ,  
                          S_Year_To ,  
                          S_Subject_Name ,  
                          N_Marks_Obtained ,  
                          N_Percentage ,  
                          S_Division ,  
                          I_Status ,  
                          S_Crtd_By ,  
                          Dt_Crtd_On,
                          S_Institution        
                        )  
                        SELECT  @iEnquiryID ,  
                                T.c.value('@S_Name_Of_Exam', 'varchar(200)') ,  
                                T.c.value('@S_University_Name', 'varchar(200)') ,  
                                T.c.value('@S_Year_From', 'varchar(4)') ,  
                                T.c.value('@S_Year_To', 'varchar(4)') ,  
                                T.c.value('@S_Subject_Name', 'varchar(200)') ,  
                                T.c.value('@N_Marks_Obtained', 'decimal(18,2)') ,  
                                T.c.value('@N_Percentage', 'decimal(18, 2)') ,  
                                T.c.value('@S_Division', 'varchar(50)') ,  
                                1 ,  
                                @CrtdBy ,  
                                @DtCrtdOn,
                                T.c.value('@S_Institution','varchar(MAX)') 
                        FROM    @sQualificationXML.nodes('/Root/Qualification') T ( c )         
  -- Update the first followup information for the enquiry                    
                INSERT  INTO dbo.T_Enquiry_Regn_FollowUp  
                        ( I_Enquiry_Regn_ID ,  
                          I_Employee_ID ,  
                          Dt_Followup_Date ,  
                          Dt_Next_Followup_Date ,  
                          S_Followup_Remarks        
                        )  
                VALUES  ( @iEnquiryID ,  
                          @iEmployeeId ,  
                          @DtCrtdOn ,  
                          @dtFirstFollowUpDate ,  
                          'First FollowUp after Enquiry'                      
                        )
                        
                 INSERT  INTO dbo.T_Enquiry_Education_CurrentStatus
                        ( I_Enquiry_Regn_ID ,
                          I_Education_CurrentStatus_ID ,
                          S_Crtd_By ,
                          Dt_Crtd_On 
                        )
                VALUES  ( @iEnquiryID , -- I_Enquiry_Regn_ID - int
                          @EducationCurrentStatus , -- I_Education_CurrentStatus_ID - int
                          @CrtdBy , -- S_Crtd_By - varchar(max)
                          @DtCrtdOn -- Dt_Crtd_On - datetime
           
                        ) 
						
				EXEC [LMS].[uspInsertEnquiryDataForInterface] @iEnquiryID,'ADD'
                       
                SELECT  @iEnquiryID AS EnquiryNumber          
            END        
        ELSE   
            BEGIN        
                RAISERROR('Entry with the same mobile no. already exists',11,1)        
            END                  
        COMMIT TRANSACTION        
                
    END TRY                    
    BEGIN CATCH                    
 --Error occurred:                      
        ROLLBACK TRANSACTION                     
        DECLARE @ErrMsg NVARCHAR(4000) ,  
            @ErrSeverity INT                    
        SELECT  @ErrMsg = ERROR_MESSAGE() ,  
                @ErrSeverity = ERROR_SEVERITY()                    
                    
        RAISERROR(@ErrMsg, @ErrSeverity, 1)                    
    END CATCH
GO
