                                                       WHERE  S_Mobile_No = @MobileNo
                                                              AND I_Centre_Id = @Centre
                                                              AND I_Enquiry_Regn_ID = @iEnquiryID
                                                              AND I_Enquiry_Status_Code IS NULL
                                                     ) = 1 THEN @DtCrtdOn
