                        FROM    dbo.fnString2Rows(@sSelectedFocusID, ',') FSR
 
 
                DELETE  FROM dbo.T_Enquiry_Education_CurrentStatus
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID
 
                INSERT  INTO dbo.T_Enquiry_Education_CurrentStatus
