                        )
          
                DELETE  FROM dbo.T_Enquiry_Employment_Details
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID
  
                INSERT  INTO dbo.T_Enquiry_Employment_Details
                        ( I_Enquiry_Regn_ID ,
                          I_Employment_Details_ID ,
                          S_Crtd_By ,
                          Dt_Crtd_On
                        )
                VALUES  ( @iEnquiryID , -- I_Enquiry_Regn_ID - int
                          @IndustryType , -- I_Employment_Details_ID - int
                          @CrtdBy , -- S_Crtd_By - varchar(max)
                          @DtCrtdOn  -- Dt_Crtd_On - datetime
            
                        )                      
 
                UPDATE  dbo.T_Enquiry_Employment_Details
                SET     S_Experience = @YrsofExp
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID
                UPDATE  dbo.T_Enquiry_Employment_Details
                SET     S_Role = @JobRole
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID
                UPDATE  dbo.T_Enquiry_Employment_Details
                SET     S_Salary = @JobSalary
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID
 
                DELETE  FROM dbo.T_Enquiry_IT_Skills
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID
 
                INSERT  INTO dbo.T_Enquiry_IT_Skills
                        ( I_Enquiry_Regn_ID ,
                          I_IT_Skills_ID ,
                          S_Crtd_By ,
                          Dt_Crtd_On
                        )
                VALUES  ( @iEnquiryID , -- I_Enquiry_Regn_ID - int
                          @ITSkills , -- I_IT_Skills_ID - int
                          @CrtdBy , -- S_Crtd_By - varchar(max)
                          @DtCrtdOn -- Dt_Crtd_On - datetime
           
                        )
                        
                         
                DELETE  FROM dbo.T_Enquiry_Reference_Details
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID 
                
                INSERT  INTO dbo.T_Enquiry_Reference_Details
                        ( I_Enquiry_Regn_ID ,
                          S_Name ,
                          S_Contact_No ,
                          S_Address
                        )
                        SELECT  @iEnquiryID ,
                                T.c.value('@S_Name', 'varchar(MAX)') ,
                                T.c.value('@S_Contact_No', 'varchar(MAX)') ,
                                T.c.value('@S_Address', 'varchar(MAX)')
                        FROM    @sReferenceXML.nodes('/Root/Reference') T ( c )
                        
                        
                DELETE  FROM dbo.T_Enquiry_PostCounselling_Feedback_Details
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID 
                
                INSERT  INTO dbo.T_Enquiry_PostCounselling_Feedback_Details
                        ( I_Enquiry_Regn_ID ,
                          S_Question ,
                          I_Points
                        )
                        SELECT  @iEnquiryID ,
                                T.c.value('@S_Question', 'varchar(MAX)') ,
                                CAST(T.c.value('@S_Points', 'varchar(MAX)') AS INT)
                        FROM    @sFeedbackXML.nodes('/Root/Feedback') T ( c )    
                   
      
        
                 
 
 --akash                           
     
     
 --Delete enquiry Qualification Information    
                DELETE  FROM dbo.T_Enquiry_Qualification_Details
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID    
      
 --Update enquiry Qualification Information       
                INSERT  INTO dbo.T_Enquiry_Qualification_Details
                        ( I_Enquiry_Regn_ID ,
                          S_Name_Of_Exam ,
                          S_University_Name ,
                          S_Year_From ,
                          S_Year_To ,
                          S_Subject_Name ,
                          N_Marks_Obtained ,
                          N_Percentage ,
                          S_Division ,
                          I_Status ,
                          S_Crtd_By ,
                          Dt_Crtd_On ,
                          S_Institution   
                        )
                        SELECT  @iEnquiryID ,
                                T.c.value('@S_Name_Of_Exam', 'varchar(200)') ,
                                T.c.value('@S_University_Name', 'varchar(200)') ,
                                T.c.value('@S_Year_From', 'varchar(4)') ,
                                T.c.value('@S_Year_To', 'varchar(4)') ,
                                T.c.value('@S_Subject_Name', 'varchar(200)') ,
                                T.c.value('@N_Marks_Obtained', 'decimal(18,2)') ,
                                T.c.value('@N_Percentage', 'decimal(18, 2)') ,
                                T.c.value('@S_Division', 'varchar(50)') ,
                                1 ,
                                @CrtdBy ,
                                @DtCrtdOn ,
                                T.c.value('@S_Institution', 'varchar(MAX)')
                        FROM    @sQualificationXML.nodes('/Root/Qualification') T ( c )     
                    
                IF @iPreEnquiryUpdate = 1
                    BEGIN                  
 -- Get the Employee Id of the Councellor                 
                        SELECT  @iEmployeeId = I_Employee_ID
                        FROM    dbo.T_Employee_Dtls
                        WHERE   I_Employee_ID = ( SELECT    I_Reference_ID
                                                  FROM      dbo.T_User_Master
                                                  WHERE     S_Login_ID = @CrtdBy
                                                )                
                   
 -- Update the first followup information for the enquiry                
                        INSERT  INTO dbo.T_Enquiry_Regn_Followup
                                ( I_Enquiry_Regn_ID ,
                                  I_Employee_ID ,
                                  Dt_Followup_Date ,
                                  Dt_Next_Followup_Date ,
                                  S_Followup_Remarks    
                                )
                        VALUES  ( @iEnquiryID ,
                                  @iEmployeeId ,
                                  @DtCrtdOn ,
                                  @dtFirstFollowUpDate ,
                                  'First FollowUp after Enquiry'                  
                                )                      
                    END    
				
-- update language details in student language table : by susmita
			   
			   if exists(select * from T_Brand_Center_Details where I_Brand_ID=109 and I_Centre_Id in (@Centre))--only execute for 109
				BEGIN
					Exec uspUpdateEnquiryLanguageDetails @iEnquiryID,@iEnquiryStatus
				END

                SELECT  S_Enquiry_No
                FROM    T_Enquiry_Regn_Detail
                WHERE   I_Enquiry_Regn_ID = @iEnquiryID     
            END    
        ELSE
            BEGIN    
                RAISERROR('Entry with the same mobile no. already exists',11,1)    
            END    
             
        COMMIT TRANSACTION            
    END TRY            
    BEGIN CATCH            
 --Error occurred:              
        ROLLBACK TRANSACTION            
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT            
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()            
            
        RAISERROR(@ErrMsg, @ErrSeverity, 1)            
    END CATCH
GO
PRINT N'Creating Procedure [ACADEMICS].[uspSaveStudentAttendance]...';


GO
CREATE PROCEDURE [ACADEMICS].[uspSaveStudentAttendance]
(    
 @iTimeTableID INT,  
 @sStudentsList VARCHAR(MAX),  
 @sCrtdBy VARCHAR(20),  
 @dtCrtdOn DATETIME   
)    
AS    
    
BEGIN TRY     
   
  SELECT CAST(Val AS INT) AS Val INTO #TempTable FROM dbo.fnString2Rows(@sStudentsList,',')  
  
  DELETE FROM #TempTable WHERE   Val IN  
  (  
   --SELECT SAD.I_Attendance_Detail_ID
   SELECT SAD.I_Student_Detail_ID--akash
   FROM dbo.T_Student_Attendance SAD  
   INNER JOIN dbo.T_TimeTable_Master SBS  ON SBS.I_TimeTable_ID=SAD.I_TimeTable_ID
											   --AND  SBS.I_Term_ID = SAD.I_Term_ID  
											   --AND SBS.I_Module_ID = SAD.I_Module_ID  
											   --AND SBS.I_Session_ID = SAD.I_Session_ID  
   WHERE SBS.I_TimeTable_ID = @iTimeTableID  
  )  
  
 --IF (
 --(select CONVERT(DATE,DATEADD(DAY,2,ISNULL(Dt_Actual_Date,Dt_Schedule_Date))) from T_TimeTable_Master where I_TimeTable_ID=@iTimeTableID) <= CONVERT(DATE,GETDATE())
 --and 
 --((SELECT Top 1 TCHND.I_Brand_ID FROM dbo.T_TimeTable_Master TTTM
 -- INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TTTM.I_Center_ID = TCHND.I_Center_ID
 -- WHERE TTTM.I_TimeTable_ID=@iTimeTableID) = 109
 --)
 --) --added by susmita Paul : 2023-Dec-08:Attendence Restrict If day has crossed D+2 on Attendence Day
 --BEGIN

			  INSERT INTO dbo.T_Student_Attendance (  
			   I_Student_Detail_ID,  
			   I_TimeTable_ID,  
			   S_Crtd_By,  
			   Dt_Crtd_On  
			  )   
			  SELECT Val,@iTimeTableID,@sCrtdBy,@dtCrtdOn    
			  FROM #TempTable    
  
  --END --added by susmita Paul : 2023-Dec-08:Attendence Restrict If day has crossed D+2 on Attendence Day

   
  DROP TABLE #TempTable 
  --akash
  
  DECLARE @BatchID INT;
  DECLARE @SchDate DATE;
  DECLARE @BrandID INT;
  
  SET @BrandID=(SELECT TCHND.I_Brand_ID FROM dbo.T_TimeTable_Master TTTM
  INNER JOIN dbo.T_Center_Hierarchy_Name_Details TCHND ON TTTM.I_Center_ID = TCHND.I_Center_ID
  WHERE TTTM.I_TimeTable_ID=@iTimeTableID)
  SET @BatchID=(SELECT I_Batch_ID FROM dbo.T_TimeTable_Master WHERE I_TimeTable_ID=@iTimeTableID)
  SET @SchDate=(SELECT Dt_Schedule_Date FROM dbo.T_TimeTable_Master WHERE I_TimeTable_ID=@iTimeTableID)
  
  IF(@BrandID=107)
  BEGIN
  EXEC dbo.uspInsertAttendanceDataForEntireDay @iBatchID = @BatchID, -- int
      @dtScheduleDate = @SchDate, -- date
      @sCrtdBy = @sCrtdBy, -- varchar(20)
      @dtCrtd = @dtCrtdOn -- datetime
      
      END
  
   --akash
    
END TRY    
    
BEGIN CATCH    
 --Error occurred:      
    
 DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity int    
 SELECT @ErrMsg = ERROR_MESSAGE(),    
   @ErrSeverity = ERROR_SEVERITY()    
    
 RAISERROR(@ErrMsg, @ErrSeverity, 1)    
END CATCH
GO
