GO

CREATE procedure [ECOMMERCE].[uspGetEnquiryDetails](@RegID INT, @CenterID INT, @BatchID INT, @ProspectusAmount DECIMAL(14,2)=0)
AS
BEGIN

	DECLARE @EnquiryNumber INT=0
	DECLARE @iReceiptHeader INT=0
	DECLARE @iBrandID INT
	DECLARE @dtDate DATETIME=GETDATE()
	DECLARE @FollowupDate DATETIME

	DECLARE @sCourseID VARCHAR(MAX)
	DECLARE @CountryID INT
	DECLARE @StateID INT
	DECLARE @CityID INT
	DECLARE @GenderID INT
	DECLARE @Address VARCHAR(MAX)
	DECLARE @Pincode VARCHAR(MAX)
	DECLARE @MobileNo VARCHAR(MAX)
	DECLARE @FirstName VARCHAR(MAX)
	DECLARE @MiddleName VARCHAR(MAX)
	DECLARE @LastName VARCHAR(MAX)
	DECLARE @EducationStatusID INT
	DECLARE @DateofBirth DATETIME
	DECLARE @EmailID VARCHAR(MAX)
	DECLARE @Age INT
	--61

	DECLARE @Gender VARCHAR(MAX),
			@HighestEducationQualification VARCHAR(MAX),
			@City VARCHAR(MAX)=NULL,
			@State VARCHAR(MAX) =NULL,
			@Country VARCHAR(MAX)=NULL


	select @iBrandID=I_Brand_ID from T_Center_Hierarchy_Name_Details where I_Center_ID=@CenterID


	select 
	@FirstName=FirstName,
	@MiddleName=ISNULL(MiddleName,NULL),
	@LastName=LastName,
	@MobileNo=MobileNo,
	@Address=ISNULL(Address,'NA'),
	@Pincode=ISNULL(Pincode,''),
	@DateofBirth=DateofBirth,
	@EmailID=EmailID,
	@HighestEducationQualification=HighestEducationQualification,
	@Gender=Gender,
	@City=City,
	@State=[State],
	@Country=Country
	from 
	ECOMMERCE.T_Registration where RegID=@RegID



	SELECT @EducationStatusID=ISNULL(TECS.I_Education_CurrentStatus_ID ,0)
	FROM dbo.T_Education_CurrentStatus AS TECS WHERE UPPER(TECS.S_Education_CurrentStatus_Description)=UPPER(@HighestEducationQualification)
	and TECS.I_Status=1 and TECS.I_Brand_ID=@iBrandID

	IF(@EducationStatusID=0)
	BEGIN

		insert into T_Education_CurrentStatus
		select @HighestEducationQualification,1,'rice-group-admin',NULL,GETDATE(),NULL,@iBrandID

		SET @EducationStatusID=SCOPE_IDENTITY()

	END

	SELECT @GenderID=ISNULL(TECS.I_Sex_ID ,0)
	FROM dbo.T_User_Sex AS TECS 
	WHERE UPPER(TECS.S_Sex_Name)=UPPER(@Gender)
	and TECS.I_Status=1

	IF(@GenderID=0)
	BEGIN

		RAISERROR('Invalid Gender',11,1)

	END


	SELECT @CountryID=ISNULL(TCM.I_Country_ID ,0)
	FROM dbo.T_Country_Master AS TCM WHERE UPPER(TCM.S_Country_Name)=UPPER(ISNULL(@Country,'')) AND TCM.I_Status=1

	SELECT @StateID=ISNULL(TSM.I_State_ID ,0)
	FROM dbo.T_State_Master AS TSM WHERE UPPER(TSM.S_State_Name)=UPPER(ISNULL(@State,'')) AND TSM.I_Status=1

	SELECT @CityID=ISNULL(TCM.I_City_ID,0) FROM dbo.T_City_Master AS TCM WHERE UPPER(TCM.S_City_Name)=UPPER(ISNULL(@City,'')) AND TCM.I_Status=1

	
	IF (ISNULL(@CountryID,0)=0 AND @Country NOT LIKE '%NOT AVAILABLE%')
	BEGIN

		SET @CountryID=1

	END

	IF (ISNULL(@StateID,0)=0 AND @State NOT LIKE '%NOT AVAILABLE%' AND @CountryID>0)
	BEGIN

		INSERT INTO T_State_Master
		SELECT SUBSTRING(@State,0,3),@State,@CountryID,1,'dba',NULL,GETDATE(),NULL

		SET @StateID=SCOPE_IDENTITY()

	END

	IF (ISNULL(@CityID,0)=0 AND @City NOT LIKE '%NOT AVAILABLE%' AND @StateID>0)
	BEGIN

		INSERT INTO dbo.T_City_Master
		(
			S_City_Code,
			S_City_Name,
			I_Country_ID,
			I_Status,
			S_Crtd_By,
			S_Upd_By,
			Dt_Crtd_On,
			Dt_Upd_On,
			I_State_ID
		)
		VALUES
		(   SUBSTRING(@City,0,3),        -- S_City_Code - varchar(10)
			@City,        -- S_City_Name - varchar(50)
			@CountryID,         -- I_Country_ID - int
			1,        -- I_Status - char(1)
			'rice-group-admin',        -- S_Crtd_By - varchar(20)
			NULL,        -- S_Upd_By - varchar(20)
			GETDATE(), -- Dt_Crtd_On - datetime
			NULL, -- Dt_Upd_On - datetime
			@StateID          -- I_State_ID - int
			)

			SET @CityID=SCOPE_IDENTITY()

	END









	SET @FollowupDate=DATEADD(d,10,@dtDate)
	SET @Age=(CONVERT(int,CONVERT(char(8),@dtDate,112))-CONVERT(char(8),@DateofBirth,112))/10000
	SET @sCourseID=CAST((select I_Course_ID from T_Student_Batch_Master where I_Batch_ID=@BatchID) AS varchar(max))

	--select @Age



	IF NOT EXISTS
	(
		select * from ECOMMERCE.T_Registration_Enquiry_Map A
		inner join T_Enquiry_Regn_Detail B on A.EnquiryID=B.I_Enquiry_Regn_ID
		where
		A.RegID=@RegID and B.I_Centre_Id=@CenterID
	)
	BEGIN

	--CREATE Pre-Enquiry

	exec ECOMMERCE.uspInsertPreEnquiryDetailsFromRegistration 
		@Centre=@CenterID,
		@FirstName=@FirstName,
		@MiddleName=@MiddleName,
		@LastName=@LastName,
		@DtBirthDate=@DateofBirth,
		@Age=@Age,
		@MobileNo=@MobileNo,
		@CurrCityID=@CityID,
		@CurrStateID=@StateID,
		@CurrCountryID=@CountryID,
		@CurrAddress1=@Address,
		@CurrAddress2=N'',
		@CurrPincode=@Pincode,
		@FatherName=NULL,
		@MotherName=NULL,
		@EnquiryDesc=NULL,
		@IsPreEnquiry=1,
		@sQualificationXML=N'<Root><Qualification S_Name_Of_Exam="Class X" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /><Qualification S_Name_Of_Exam="Class XII" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /><Qualification S_Name_Of_Exam="Graduation" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /><Qualification S_Name_Of_Exam="Post-Graduation" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /></Root>',
		@bHasGivenOtherExam=0,
		@InfoSourceID=61,
		@CrtdBy=N'rice-group-admin',
		@DtCrtdOn=@dtDate,
		@iSeatType=NULL,
		@iEnrolmentType=NULL,
		@sEnrolmentNo=NULL,
		@iRankObtained=NULL,
		@dtFirstFollowUpDate=@FollowupDate,
		@sSelectedCourseID=@sCourseID,
		@casteID=NULL,
		@IEnquiryStatusCode=NULL,
		@IsLateral=NULL,
		@IPreEnquiryFor=1,
		@GuardianName=NULL,
		@GuardianPhoneNo=NULL,
		@iFatherIncomeGroup=1,
		@EducationCurrentStatus=@EducationStatusID,
		@EnquiryNumber=@EnquiryNumber OUTPUT


		EXEC [LMS].[uspInsertEnquiryDataForInterface] @EnquiryNumber,'ADD'

		----- Start : added by Susmita : for adding language details 02-08-2022 ------

				DECLARE @LanguageID INT,@LanguageName VARCHAR(200)
				SELECT TOP 1 @LanguageID=I_Language_ID,@LanguageName=I_Language_Name from T_Student_Tags where I_Enquiry_Regn_ID=@EnquiryNumber

				
				if exists(select * from ECOMMERCE.T_Registration_Language_Map where RegID=@RegID)
						
					BEGIN 

						update ECOMMERCE.T_Registration_Language_Map set I_Language_ID=@LanguageID,I_Language_Name=@LanguageName where RegID=@RegID

					END

		
		----- End : added by Susmita : for adding language details 02-08-2022 ------


	END
	ELSE
	BEGIN

		select @EnquiryNumber=I_Enquiry_Regn_ID 
		from 
		ECOMMERCE.T_Registration_Enquiry_Map A
		inner join T_Enquiry_Regn_Detail B on A.EnquiryID=B.I_Enquiry_Regn_ID
		where
		A.RegID=@RegID and B.I_Centre_Id=@CenterID

	END

	--select @EnquiryNumber as No1

	IF(@EnquiryNumber>0)
	BEGIN

		Update T_Enquiry_Regn_Detail set RegID=@RegID where I_Enquiry_Regn_ID=@EnquiryNumber and RegID IS NULL

		IF NOT EXISTS(select * from ECOMMERCE.T_Registration_Enquiry_Map where RegID=@RegID and EnquiryID=@EnquiryNumber and StatusID=1)
		BEGIN

			insert into ECOMMERCE.T_Registration_Enquiry_Map
			select @RegID,@EnquiryNumber,1,GETDATE(),'rice-group-admin',NULL,NULL

		END

		IF NOT EXISTS
		(
			select * 
			from 
			T_Enquiry_Regn_Detail A
			where
			A.I_Enquiry_Status_Code in (1,3) and I_Enquiry_Regn_ID=@EnquiryNumber
		)
		BEGIN

			exec ECOMMERCE.uspUpdateEnquiryDetails 
					@iEnquiryID=@EnquiryNumber,
					@Centre=@CenterID,
					@OccupationID=NULL,
					@PrefCareerID=NULL,
					@InfoSourceID=61,
					@EnquiryTypeID=NULL,
					@IsCorporate=NULL,
					@EnquiryDesc=NULL,
					@Title=NULL,
					@FirstName=@FirstName,
					@MiddleName=@MiddleName,
					@LastName=@LastName,
					@DtBirthDate=@DateofBirth,
					@Age=@Age,
					@casteID=1,
					@QualificationNameID=NULL,
					@SkipTest=NULL,
					@StreamID=NULL,
					@EmailID=@EmailID,
					@PhoneNo=NULL,
					@MobileNo=@MobileNo,
					@CurrCityID=@CityID,
					@CurrStateID=@StateID,
					@CurrCountryID=@CountryID,
					@GuardianName=NULL,
					@GuardianOccupationID=NULL,
					@GuardianEmailID=NULL,
					@GuardianPhoneNo=@MobileNo,
					@GuardianMobileNo=NULL,
					@IncomeGroupID=NULL,
					@CurrAddress1=@Address,
					@CurrAddress2=NULL,
					@CurrPincode=@Pincode,
					@CurrArea=NULL,
					@PermAddress1=@Address,
					@PermAddress2=N'',
					@PermPincode=@Pincode,
					@PermCityID=@CityID,
					@PermStateID=@StateID,
					@PermCountryID=@CountryID,
					@PermArea=N'',
					@CrtdBy=N'rice-group-admin',
					@DtCrtdOn=@dtDate,
					@sSelectedCourseID=@sCourseID,
					@dtFirstFollowUpDate=@FollowupDate,
					@iCorporateID=NULL,
					@iCorporatePlanID=NULL,
					@sStudentPhoto=NULL,
					@iResidenceArea=NULL,
					@sFatherName=N'NA',
					@sMotherName=N'NA',
					@iSex=@GenderID,
					@iNativeLanguage=1,
					@iNationality=1,
					@iReligion=1,
					@iMaritalStatus=1,
					@iBloodGroup=1,
					@iFatherQualification=NULL,
					@iFatherOccupation=NULL,
					@iFatherBusinessType=NULL,
					@sFatherCompany=NULL,
					@sFatherDesignation=NULL,
					@sFatherOfficePhone=NULL,
					@sFatherOfficeAddress=NULL,
					@iFatherIncomeGroup=1,
					@sFatherPhoto=NULL,
					@iMotherQualification=NULL,
					@iMotherOccupation=NULL,
					@iMotherBusinessType=NULL,
					@sMotherCompany=NULL,
					@sMotherDesignation=NULL,
					@sMotherOfficePhone=NULL,
					@iMotherIncomeGroup=NULL,
					@sMotherPhoto=NULL,
					@sMotherOfficeAddress=NULL,
					@sGuardianRelation=NULL,
					@sGuardianAddress=NULL,
					@iMonthlyFamilyIncome=NULL,
					@bCanSponsorEducation=0,
					@sSiblingID=NULL,
					@bHasGivenOtherExam=0,
					@iNoOfAttempts=NULL,
					@sOtherInstitute=NULL,
					@nDuration=NULL,
					@iSeatType=NULL,
					@iEnrolmentType=NULL,
					@sEnrolmentNo=NULL,
					@iRankObtained=NULL,
					@sUniversityRegnNo=NULL,
					@sUnivRollNo=NULL,
					@iScholarType=NULL,
					@sSecondLanguageOpted=NULL,
					@sQualificationXML=N'<Root><Qualification 
					S_Name_Of_Exam="Class X" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="NA" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /><Qualification S_Name_Of_Exam="Class XII" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="NA" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /><Qualification S_Name_Of_Exam="Graduation" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="NA" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /><Qualification S_Name_Of_Exam="Post-Graduation" S_University_Name="" S_Institution="" S_Year_From="" S_Year_To="" S_Subject_Name="NA" N_Marks_Obtained="0" N_Percentage="0" S_Division="" /></Root>',@sPhysicalAilment=NULL,@IsLateral=NULL,@EducationCurrentStatus=12,@EducationStream=NULL,@EducationPostGrad=NULL,@IndustryType=NULL,@ITSkills=NULL,@YrsofExp=NULL,@JobRole=NULL,@JobSalary=NULL,@sSelectedAimID=NULL,@sSelectedFocusID=NULL,@sReferenceXML=N'<Root><Reference S_Name="" S_Contact_No="" S_Address="" /><Reference S_Name="" S_Contact_No="" S_Address="" /></Root>',@sFeedbackXML=N'<Root><Feedback S_Question="Front office ambience" S_Points="0" /><Feedback S_Question="Relevant Information Brochures Availability" S_Points="0" /><Feedback S_Question="Queries were handled to my satisfaction" S_Points="0" /><Feedback S_Question="RICE can provide me with the product that I need and is best suited for my career" S_Points="0" /></Root>',
					@TestScore=NULL,
					@iEnquiryStatus=1,
					@iPreEnquiryUpdate=1,
					@EnquiryNumber=@EnquiryNumber OUTPUT


					--select @EnquiryNumber as No2

				END

				IF(@EnquiryNumber IS NOT NULL and @EnquiryNumber>0 and @ProspectusAmount=0)
				BEGIN

					IF NOT EXISTS(select * from T_Receipt_Header where I_Status=1 and I_Receipt_Type=32 and I_Enquiry_Regn_ID=@EnquiryNumber)
					BEGIN

					DECLARE @sFormNo VARCHAR(MAX)
					SET @sFormNo='CU'+CAST(@RegID as VARCHAR(MAX))+CAST(@CenterID as varchar(max))

						EXEC uspGenerateReceiptForOnAccountAPI @iCenterId = @CenterID,
															@iAmount = 0,
															@iStudentDetailId = NULL,
															@iReceiptDate = @dtDate,
															@iPaymentModeId = 27,
															@sChequeDDno = NULL,
															@dChequeDate = NULL,
															@sBankName = NULL,
															@sBranchName = NULL,
															@iCreditCardNo = NULL,
															@sCreditCardIssuer = NULL,
															@dCardExpiryDate = NULL,
															@sCrtdBy = 'rice-group-admin',
															@iReceiptType = 32,
															@dTaxAmount = 0,
															@TaxXML = '<ReceiptTax />',
															@iBrandID = @iBrandID,
															@iEnquiryID = @EnquiryNumber,
															@sFormNo = @sFormNo,
															@sNarration = '',
															@iReceiptHeader = @iReceiptHeader OUTPUT

					END
					ELSE
					BEGIN

						select @iReceiptHeader=I_Receipt_Header_ID 
						from T_Receipt_Header 
						where I_Status=1 and I_Receipt_Type=32 and I_Enquiry_Regn_ID=@EnquiryNumber

					END

				END

	END

	IF(@iReceiptHeader>0)
		select @EnquiryNumber as EnquiryID
	ELSE
		select 0 as EnquiryID

END
GO
PRINT N'Creating Procedure [LMS].[uspCalculateStudentStatusForAPI_temp]...';


GO

CREATE PROCEDURE [LMS].[uspCalculateStudentStatusForAPI_temp](@Status VARCHAR(MAX)=NULL,@StudentDetailID INT=NULL)
AS 
    BEGIN

        DECLARE @dtDate DATETIME= GETDATE() ;
		DECLARE @i INT=1
		DECLARE @c INT=0

        CREATE TABLE #Due
		(
			S_Brand_Name VARCHAR(MAX),
			I_Center_ID INT,
			S_Center_Name VARCHAR(MAX),
			S_Course_Name VARCHAR(MAX),
			I_Batch_ID INT,
			S_Batch_Name VARCHAR(MAX),
			I_Student_Detail_ID INT,
			S_Student_ID VARCHAR(MAX),
			S_Student_Name VARCHAR(MAX),
			InvoiceHeaderID INT,
			S_Invoice_No VARCHAR(MAX),
			I_Invoice_Detail_ID INT,
			Dt_Installment_Date DATETIME,
			I_Installment_No INT,
			I_Fee_Component_ID INT,
			S_Component_Name VARCHAR(MAX),
			BaseAmountDue DECIMAL(14,2),
			TaxDue DECIMAL(14,2),
			TotalAmtPayable DECIMAL(14,2),
			Amount_Paid DECIMAL(14,2),
			Tax_Paid DECIMAL(14,2),
			Total_Paid DECIMAL(14,2),
			CurrentDue DECIMAL(14,2)
		)

		CREATE TABLE #Std
		(
			ID INT IDENTITY(1,1),
			StudentDetailID INT,
			InvoiceHeaderID INT,
			DueAmount DECIMAL(14,2),
			IsDefaulter INT,
			IsPaymentDue INT,
			IsPreDefaulter INT,
			IsDiscontinued INT,
			IsCompleted INT,
			DefaulterDate DATETIME,
			PaymentDueDate DATETIME,
			PreDefaulterDate DATETIME
		)

		IF(@StudentDetailID IS NULL)
		BEGIN

		INSERT  INTO #Due
        EXEC [LMS].[uspGetDueReportForDate] '54',109,@dtDate,'ALL'

		END
		ELSE
		BEGIN

			INSERT  INTO #Due
			EXEC [LMS].[uspGetDueReportForDate] '54',109,@dtDate,'ALL',@StudentDetailID

		END



		IF(@StudentDetailID IS NULL)
		BEGIN

			insert into #Std(StudentDetailID,InvoiceHeaderID,DueAmount)
			select A.I_Student_Detail_ID,T1.InvoiceHeaderID,T1.Due--,dbo.fnGetCompletedStatus(A.I_Student_Detail_ID)
			from T_Student_Detail A
			left join
			(
				select T.I_Student_Detail_ID,T.InvoiceHeaderID,T.Due from
				(
					select I_Student_Detail_ID,InvoiceHeaderID,SUM(CurrentDue) as Due
					from #Due
					group by I_Student_Detail_ID,InvoiceHeaderID
					having SUM(CurrentDue)>=100
				) T
			) T1 on A.I_Student_Detail_ID=T1.I_Student_Detail_ID
			where A.S_Student_ID like '%RICE%'		

		END
		ELSE
		BEGIN

			insert into #Std(StudentDetailID,InvoiceHeaderID,DueAmount)
			select A.I_Student_Detail_ID,T1.InvoiceHeaderID,T1.Due--,dbo.fnGetCompletedStatus(A.I_Student_Detail_ID)
			from T_Student_Detail A
			left join
			(
				select T.I_Student_Detail_ID,T.InvoiceHeaderID,T.Due from
				(
					select I_Student_Detail_ID,InvoiceHeaderID,SUM(CurrentDue) as Due
					from #Due
					group by I_Student_Detail_ID,InvoiceHeaderID
					having SUM(CurrentDue)>=100
				) T
			) T1 on A.I_Student_Detail_ID=T1.I_Student_Detail_ID
			where A.S_Student_ID like '%RICE%' and A.I_Student_Detail_ID=@StudentDetailID

		END


		update T1
		set
		T1.IsDefaulter=ISNULL(T2.Defaulter,0),
		T1.DefaulterDate=T2.DefaulterDate
		from
		#Std T1
		inner join
		(
			SELECT  DISTINCT
					XX.I_Student_Detail_ID ,
					XX.InvoiceHeaderID,
					DATEADD(d,30,XX.InstalmentDate) as DefaulterDate,
					1 AS Defaulter
			FROM    ( SELECT    I_Student_Detail_ID ,
								InvoiceHeaderID,
								SUM(ISNULL(CurrentDue,0)) AS TotalDue,
								MIN(TTT.Dt_Installment_Date) as InstalmentDate
						FROM      #Due TTT
						WHERE     DATEDIFF(d,TTT.Dt_Installment_Date,GETDATE()) >= 30     
						GROUP BY  I_Student_Detail_ID,InvoiceHeaderID
						HAVING SUM(ISNULL(CurrentDue,0))>=100

					) XX
		) T2 on T1.StudentDetailID=T2.I_Student_Detail_ID and T1.InvoiceHeaderID=T2.InvoiceHeaderID


		update T1
		set
		T1.IsPaymentDue=ISNULL(T2.PayDue,0),
		T1.PaymentDueDate=T2.InstalmentDate
		from
		#Std T1
		inner join
		(
			SELECT  DISTINCT
					XX.I_Student_Detail_ID ,
					XX.InvoiceHeaderID,
					XX.InstalmentDate,
					1 AS PayDue
			FROM    ( SELECT    I_Student_Detail_ID ,
								TTT.InvoiceHeaderID,
								SUM(ISNULL(CurrentDue,0)) AS TotalDue,
								MIN(TTT.Dt_Installment_Date) as InstalmentDate
						FROM    #Due TTT
						WHERE   DATEDIFF(d,TTT.Dt_Installment_Date,GETDATE()) >=1
								and
								DATEDIFF(d,TTT.Dt_Installment_Date,GETDATE()) <=10     
						GROUP BY  I_Student_Detail_ID ,TTT.InvoiceHeaderID
						HAVING SUM(ISNULL(CurrentDue,0))>=100
					) XX
		) T2 on T1.StudentDetailID=T2.I_Student_Detail_ID and T1.InvoiceHeaderID=T2.InvoiceHeaderID


		update T1
		set
		T1.IsPreDefaulter=ISNULL(T2.PreDefaulter,0),
		T1.PreDefaulterDate=T2.PreDefaulterDate
		from
		#Std T1
		inner join
		(
			SELECT  DISTINCT
					XX.I_Student_Detail_ID ,
					XX.InvoiceHeaderID,
					XX.PreDefaulterDate,
					1 AS PreDefaulter
			FROM    ( SELECT    I_Student_Detail_ID,
								InvoiceHeaderID,
								SUM(ISNULL(CurrentDue,0)) AS TotalDue,
								MIN(DATEADD(d,30-DATEDIFF(d,TTT.Dt_Installment_Date,GETDATE()),GETDATE())) as PreDefaulterDate
						FROM    #Due TTT
						WHERE     
						DATEDIFF(d,TTT.Dt_Installment_Date,GETDATE()) >= 11
						AND
						DATEDIFF(d,TTT.Dt_Installment_Date,GETDATE()) <= 30      
						GROUP BY  I_Student_Detail_ID,InvoiceHeaderID
						HAVING SUM(ISNULL(CurrentDue,0))>=100
					) XX
		) T2 on T1.StudentDetailID=T2.I_Student_Detail_ID and T1.InvoiceHeaderID=T2.InvoiceHeaderID


		update T1
		set
		T1.IsDiscontinued=ISNULL(T2.Discontinued,0)
		from
		#Std T1
		inner join
		(
			select I_Student_Detail_ID, 1 AS Discontinued 
			from T_Student_Detail 
			where S_Student_ID like '%RICE%' and I_Status=0
		) T2 on T1.StudentDetailID=T2.I_Student_Detail_ID


		update T1
		set
		T1.IsCompleted=T2.Completed
		from
		#Std T1
		inner join
		(
			select E.I_Student_Detail_ID, 1 AS Completed 
			from 
			T_Invoice_Parent A
			inner join T_Invoice_Child_Header B on A.I_Invoice_Header_ID=B.I_Invoice_Header_ID
			inner join T_Invoice_Batch_Map C on B.I_Invoice_Child_Header_ID=C.I_Invoice_Child_Header_ID and C.I_Status=1
			inner join T_Student_Batch_Master D on C.I_Batch_ID=D.I_Batch_ID
			inner join T_Student_Detail E on A.I_Student_Detail_ID=E.I_Student_Detail_ID
			where
			CONVERT(DATE,GETDATE())>=DATEADD(m,2,CONVERT(DATE,D.Dt_Course_Expected_End_Date)) and A.I_Status=1 and E.I_Status=1
		) T2 on T1.StudentDetailID=T2.I_Student_Detail_ID


		select @c=COUNT(*) from #Std
		
		WHILE(@i<=@c)
		BEGIN

			DECLARE @StdID INT
			DECLARE @InvID INT
			DECLARE @disc INT
			DECLARE @def INT
			DECLARE @predef INT
			DECLARE @paydue INT
			DECLARE @due DECIMAL(14,2)
			DECLARE @comp INT

			DECLARE @defdate DATETIME
			DECLARE @payduedate DATETIME
			DECLARE @predefdate DATETIME

			select 
			@StdID=StudentDetailID,
			@InvID=ISNULL(InvoiceHeaderID,0),
			@disc=ISNULL(IsDiscontinued,0),
			@def=ISNULL(IsDefaulter,0),
			@predef=ISNULL(IsPreDefaulter,0),
			@paydue=ISNULL(IsPaymentDue,0),
			@defdate=DefaulterDate,
			@payduedate=PaymentDueDate,
			@due=DueAmount,
			@predefdate=PreDefaulterDate
			from 
			#Std where ID=@i


			---DISCONTINUED (7)---
			IF(@Status IS NULL OR @Status='DISCONTINUED')
			BEGIN

				IF(@disc=1)
				BEGIN

					IF NOT EXISTS
					(
						select * from T_Student_Status where I_Status_ID=7 and I_Student_Detail_ID=@StdID and I_Status=1 and ValidTo IS NULL
					)
					BEGIN

						insert into T_Student_Status
						(
							I_Student_Detail_ID,
							I_Status_ID,
							I_Status,
							ValidFrom,
							Dt_Crtd_On,
							S_Crtd_By
						)
						VALUES
						(
							@StdID,
							7,
							@disc,
							GETDATE(),
							GETDATE(),
							'rice-group-admin'
						)

					END
					ELSE IF(ISNULL(@disc,0)=0)
					BEGIN

						UPDATE T_Student_Status 
						set 
						ValidTo=GETDATE(),
						Dt_Updt_On=GETDATE(),
						S_Updt_By='rice-group-admin',
						B_IsInQueue=0
						where
						I_Status_ID=7 and I_Student_Detail_ID=@StdID and I_Status=1 and ValidTo IS NULL

					END


				END

			END


			---COMPLETED (5)---
			IF(@Status IS NULL OR @Status='COMPLETED')
			BEGIN

				IF(@comp=1)
				BEGIN

					IF NOT EXISTS
					(
						select * from T_Student_Status where I_Status_ID=5 and I_Student_Detail_ID=@StdID and I_Status=1 and ValidTo IS NULL
					)
					BEGIN

						insert into T_Student_Status
						(
							I_Student_Detail_ID,
							I_Status_ID,
							I_Status,
							ValidFrom,
							Dt_Crtd_On,
							S_Crtd_By
						)
						VALUES
						(
							@StdID,
							5,
							@comp,
							GETDATE(),
							GETDATE(),
							'rice-group-admin'
						)

					END
					ELSE IF(ISNULL(@comp,0)=0)
					BEGIN

						UPDATE T_Student_Status 
						set 
						ValidTo=GETDATE(),
						Dt_Updt_On=GETDATE(),
						S_Updt_By='rice-group-admin',
						B_IsInQueue=0
						where
						I_Status_ID=5 and I_Student_Detail_ID=@StdID and I_Status=1 and ValidTo IS NULL

					END


				END

			END

			---DEFAULTER (3)---
			IF((@Status IS NULL OR @Status='DEFAULTER' OR @Status='FINANCIAL') and @InvID IS NOT NULL)
			BEGIN

				IF(@def=1)
				BEGIN

					IF NOT EXISTS
					(
						select * from T_Student_Status where I_Status_ID=3 and I_Student_Detail_ID=@StdID and I_Status=1 
																and ValidTo IS NULL and StatusDate=@defdate and InvoiceHeaderID=@InvID
					)
					BEGIN

						insert into T_Student_Status
						(
							I_Student_Detail_ID,
							I_Status_ID,
							I_Status,
							ValidFrom,
							Dt_Crtd_On,
							S_Crtd_By,
							InvoiceHeaderID,
							StatusDate,
							N_Due
						)
						VALUES
						(
							@StdID,
							3,
							@def,
							@defdate,
							GETDATE(),
							'rice-group-admin',
							@InvID,
							@defdate,
							@due
						)

					END
					ELSE IF(ISNULL(@def,0)=0)
					BEGIN

						UPDATE T_Student_Status 
						set 
						ValidTo=GETDATE(),
						Dt_Updt_On=GETDATE(),
						S_Updt_By='rice-group-admin',
						B_IsInQueue=0
						where
						I_Status_ID=3 and I_Student_Detail_ID=@StdID and I_Status=1 
						and ValidTo IS NULL and StatusDate=@defdate and InvoiceHeaderID=@InvID
						and CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE())

					END


				END

			END

			---PAYMENT DUE (9)---
			IF((@Status IS NULL OR @Status='PAYMENTDUE' OR @Status='FINANCIAL') and @InvID IS NOT NULL)
			BEGIN

				IF(@paydue=1)
				BEGIN

					IF NOT EXISTS
					(
						select * from T_Student_Status where I_Status_ID=9 and I_Student_Detail_ID=@StdID and I_Status=1 
																and ValidTo IS NULL and StatusDate=@payduedate and InvoiceHeaderID=@InvID
					)
					BEGIN

						insert into T_Student_Status
						(
							I_Student_Detail_ID,
							I_Status_ID,
							I_Status,
							ValidFrom,
							Dt_Crtd_On,
							S_Crtd_By,
							InvoiceHeaderID,
							StatusDate,
							N_Due
						)
						VALUES
						(
							@StdID,
							9,
							@paydue,
							@payduedate,
							GETDATE(),
							'rice-group-admin',
							@InvID,
							@payduedate,
							@due
						)

					END
					ELSE IF(ISNULL(@paydue,0)=0)
					BEGIN

						UPDATE T_Student_Status 
						set 
						ValidTo=GETDATE(),
						Dt_Updt_On=GETDATE(),
						S_Updt_By='rice-group-admin',
						B_IsInQueue=0
						where
						I_Status_ID=9 and I_Student_Detail_ID=@StdID and I_Status=1 
						and ValidTo IS NULL and InvoiceHeaderID=@InvID
						and CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE())

					END


				END

			END


			---PREDEFAULTER (8)---
			IF((@Status IS NULL OR @Status='PREDEFAULTER' OR @Status='FINANCIAL') and @InvID IS NOT NULL)
			BEGIN

				IF(@predef=1)
				BEGIN

					IF NOT EXISTS
					(
						select * from T_Student_Status where I_Status_ID=8 and I_Student_Detail_ID=@StdID and I_Status=1 
																and ValidTo IS NULL and StatusDate=@payduedate and InvoiceHeaderID=@InvID
					)
					BEGIN

						insert into T_Student_Status
						(
							I_Student_Detail_ID,
							I_Status_ID,
							I_Status,
							ValidFrom,
							Dt_Crtd_On,
							S_Crtd_By,
							InvoiceHeaderID,
							StatusDate,
							N_Due
						)
						VALUES
						(
							@StdID,
							8,
							@predef,
							@predefdate,
							GETDATE(),
							'rice-group-admin',
							@InvID,
							@predefdate,
							@due
						)

					END
					ELSE IF(ISNULL(@predef,0)=0)
					BEGIN

						UPDATE T_Student_Status 
						set 
						ValidTo=GETDATE(),
						Dt_Updt_On=GETDATE(),
						S_Updt_By='rice-group-admin',
						B_IsInQueue=0
						where
						I_Status_ID=8 and I_Student_Detail_ID=@StdID and I_Status=1 
						and ValidTo IS NULL and InvoiceHeaderID=@InvID
						and CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE())

					END


				END

			END


			SET @i=@i+1

		END
        
		

		IF(@StudentDetailID IS NULL)
		BEGIN

			UPDATE T_Student_Status
			set
			ValidTo=GETDATE(),
			Dt_Updt_On=GETDATE(),
			S_Updt_By='rice-group-admin',
			B_IsInQueue=0
			where
			CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE())
			and
			I_Status_ID IN (3,8,9)
			and
			InvoiceHeaderID NOT IN
			(
				select DISTINCT InvoiceHeaderID from #Std
			)

		END
		ELSE
		BEGIN

			UPDATE T_Student_Status
			set
			ValidTo=GETDATE(),
			Dt_Updt_On=GETDATE(),
			S_Updt_By='rice-group-admin',
			B_IsInQueue=0
			where
			CONVERT(DATE,ValidFrom)<=CONVERT(DATE,GETDATE())
			and
			I_Status_ID IN (3,8,9)
			and
			InvoiceHeaderID NOT IN
			(
				select DISTINCT InvoiceHeaderID from #Std
			)
			and I_Student_Detail_ID=@StudentDetailID


		END
        
		IF(@Status IS NULL)
		BEGIN

			EXEC [LMS].[uspCalculateFutureStudentStatusForAPI] 'PAYMENTDUE',10
			EXEC [LMS].[uspCalculateFutureStudentStatusForAPI] 'DEFAULTER',0
			EXEC [LMS].[uspCalculateFutureStudentStatusForAPI] 'PREDEFAULTER',0

		END


        --select * from #Std
        
        DROP TABLE #Due                                       
	
	
    END
GO
PRINT N'Creating Procedure [SelfService].[uspUpdateOnAccTransactionStatus]...';


GO
CREATE procedure [SelfService].[uspUpdateOnAccTransactionStatus]
(
	@DueID INT,
	@TransactionNo VARCHAR(MAX),
	@TransactionStatus VARCHAR(MAX)
)
AS
BEGIN TRY


	DECLARE @CentreID INT,
			@Amount DECIMAL(14,2)=0,
			@iStudentDetailID INT,
			@dtDate DATETIME,
			@PaymentModeID INT,
			@OnAccReceiptTypeID INT,
			@Tax DECIMAL(14,2)=0,
			@OnAccTaxXML XML='<ReceiptTax />',
			@BrandID INT,
			@iReceiptHeader INT=0,
			@CurrTransactionStatus VARCHAR(MAX)

	BEGIN TRANSACTION

	IF NOT EXISTS(select * from SelfService.T_Online_Payment_Master where TransactionNo=@TransactionNo and StatusID=1 and OnAccDueID=@DueID and TransactionStatus!='Success')
	BEGIN

		RAISERROR('Invalid Tranaction No',11,1)

	END
	ELSE
	BEGIN

		select @CurrTransactionStatus=TransactionStatus from SelfService.T_Online_Payment_Master where TransactionNo=@TransactionNo and StatusID=1 and OnAccDueID=@DueID and TransactionStatus!='Success'

	END

	IF(@TransactionStatus='Success' and @CurrTransactionStatus='Pending')
	BEGIN

		select @CentreID=CenterID,@BrandID=BrandID,@Amount=Amount,@Tax=Tax,@OnAccReceiptTypeID=OnAccReceiptTypeID,
		@PaymentModeID=CASE WHEN TransactionSource='Online-SelfService' THEN 27 ELSE 0 END,
		@iStudentDetailID=B.I_Student_Detail_ID,@dtDate=GETDATE()
		from SelfService.T_Online_Payment_Master A
		inner join T_Student_Detail B on A.StudentID=B.S_Student_ID
		inner join T_Student_Center_Detail C on A.CenterID=C.I_Centre_Id and B.I_Student_Detail_ID=C.I_Student_Detail_ID and C.I_Status=1
		where 
		TransactionNo=@TransactionNo and StatusID=1 and OnAccDueID=@DueID


		IF(@PaymentModeID>0 and @iStudentDetailID>0)
			BEGIN

				DECLARE @cgst DECIMAL(14,2)=0
				DECLARE @sgst DECIMAL(14,2)=0

				IF (@Tax IS NOT NULL AND @Tax>0)                                    
                BEGIN
					SET @cgst=ROUND((@Tax/2),2)
					SET @sgst=@Tax-@cgst
														
					SET @OnAccTaxXML='<ReceiptTax><TaxDetails TaxID="7" TaxPaid="'+CAST(@cgst AS VARCHAR)+'"/>
					<TaxDetails TaxID="8" TaxPaid="'+CAST(@sgst AS VARCHAR)+'"/></ReceiptTax>'
														
				END


				EXEC uspGenerateReceiptForOnAccountAPI @iCenterId = @CentreID,
													@iAmount = @Amount,
													@iStudentDetailId = @iStudentDetailID,
													@iReceiptDate = @dtDate,
													@iPaymentModeId = @PaymentModeID,
													@sChequeDDno = NULL,
													@dChequeDate = NULL,
													@sBankName = NULL,
													@sBranchName = NULL,
													@iCreditCardNo = NULL,
													@sCreditCardIssuer = NULL,
													@dCardExpiryDate = NULL,
													@sCrtdBy = 'rice-group-admin',
													@iReceiptType = @OnAccReceiptTypeID,
													@dTaxAmount = @Tax,
													@TaxXML = @OnAccTaxXML,
													@iBrandID = @BrandID,
													@iEnquiryID = NULL,
													@sFormNo = NULL,
													@sNarration = '',
													@iReceiptHeader = @iReceiptHeader OUTPUT


				IF(@iReceiptHeader>0)
				BEGIN

					UPDATE SelfService.T_Online_Payment_Master set ReceiptHeaderID=@iReceiptHeader,ReceiptDate=@dtDate,TransactionStatus=@TransactionStatus 
					where 
					TransactionNo=@TransactionNo and OnAccDueID=@DueID and StatusID=1


					UPDATE SelfService.T_OnAccount_Due set ReceiptHeaderID=@iReceiptHeader,PaidOn=@dtDate where ID=@DueID and StatusID=1

				END


			END

			


	END
	ELSE
	BEGIN

		UPDATE SelfService.T_Online_Payment_Master set TransactionStatus=@TransactionStatus 
		where 
		TransactionNo=@TransactionNo and OnAccDueID=@DueID and StatusID=1

	END



	EXEC [SelfService].[uspGetStudentOnAccDuePaymentDetails] @DueID

	COMMIT TRANSACTION


END TRY

BEGIN CATCH

 --Error occurred:      
        ROLLBACK TRANSACTION    
        DECLARE @ErrMsg NVARCHAR(4000) ,
            @ErrSeverity INT    
        SELECT  @ErrMsg = ERROR_MESSAGE() ,
                @ErrSeverity = ERROR_SEVERITY()    
    
        RAISERROR(@ErrMsg, @ErrSeverity, 1) 

END CATCH
