            END                        
        ELSE
            BEGIN             
                UPDATE  T_Invoice_Parent
                SET     I_Status = 3
                WHERE   I_Invoice_Header_ID = @iInvoiceHeaderId                          
            END                          
        DECLARE @iStdDetailId INT                       
                          
