PRINT N'Creating Procedure [LMS].[uspInsertTeacherDetailsForInterface]...';


GO
CREATE procedure [LMS].[uspInsertTeacherDetailsForInterface]
(
	@EmployeeID INT,
	@EntryType VARCHAR(MAX)=NULL
)
AS
BEGIN

	if (@EntryType is not null)
	begin

		DECLARE @subjectid int
		DECLARE @subjects varchar(max)=''
		

		IF(@EntryType='ADD')
		begin

			

			DECLARE bcursor CURSOR FOR 
			select DISTINCT I_Skill_ID from EOS.T_Employee_Skill_Map where I_Employee_ID=@EmployeeID and I_Status=2--where CreatedOn>='2021-05-27'

			OPEN bcursor  
			FETCH NEXT FROM bcursor INTO @subjectid  

			WHILE @@FETCH_STATUS = 0  
			BEGIN  

				  set @subjects=@subjects+CAST(@subjectid as varchar(10))+','

				  FETCH NEXT FROM bcursor INTO @subjectid
			END 

			CLOSE bcursor  
			DEALLOCATE bcursor


			insert into [LMS].[T_Teacher_Details_Interface_API]
			select TCHND.I_Brand_ID,TCHND.S_Brand_Name,TED.I_Employee_ID,TED.S_First_Name+' '+ISNULL(TED.S_Middle_Name,'')+' '+TED.S_Last_Name as EmployeeName,TED.S_Email_ID,
			'' as TimeSlots,'' as CentreCodes,'' as CentreIDs,ISNULL(TED.S_LeaveDay,'') as DayofLeave,1 as ForOnline,1 as ForOffline,
			@subjects as Subjects,@EntryType,0,0,1,GETDATE(),NULL,''
			from T_Employee_Dtls TED
			inner join T_Center_Hierarchy_Name_Details TCHND on TED.I_Centre_Id=TCHND.I_Center_ID
			where TED.I_Employee_ID=@EmployeeID 
			and TED.I_Status=3

		end

		IF(@EntryType='UPDATE')
		begin

			

			DECLARE bcursor CURSOR FOR 
			select DISTINCT I_Skill_ID from EOS.T_Employee_Skill_Map where I_Employee_ID=@EmployeeID and I_Status=2--where CreatedOn>='2021-05-27'

			OPEN bcursor  
			FETCH NEXT FROM bcursor INTO @subjectid  

			WHILE @@FETCH_STATUS = 0  
			BEGIN  

				  set @subjects=@subjects+CAST(@subjectid as varchar(10))+','

				  FETCH NEXT FROM bcursor INTO @subjectid
			END 

			CLOSE bcursor  
			DEALLOCATE bcursor


			insert into [LMS].[T_Teacher_Details_Interface_API]
			select TCHND.I_Brand_ID,TCHND.S_Brand_Name,TED.I_Employee_ID,TED.S_First_Name+' '+ISNULL(TED.S_Middle_Name,'')+' '+TED.S_Last_Name as EmployeeName,TED.S_Email_ID,
			'' as TimeSlots,'' as CentreCodes,'' as CentreIDs,ISNULL(TED.S_LeaveDay,'') as DayofLeave,1 as ForOnline,1 as ForOffline,
			@subjects as Subjects,@EntryType,0,0,1,GETDATE(),NULL,''
			from T_Employee_Dtls TED
			inner join T_Center_Hierarchy_Name_Details TCHND on TED.I_Centre_Id=TCHND.I_Center_ID
			where TED.I_Employee_ID=@EmployeeID 
			and TED.I_Status=3


			EXEC [LMS].[uspUpdateTeacherCentreForInterface] @EmployeeID

		end

	end

END
GO
PRINT N'Creating Procedure [LMS].[uspUpdateTeacherCentreForInterface]...';


GO
CREATE procedure [LMS].[uspUpdateTeacherCentreForInterface]
(
@EmployeeID INT
)
AS
BEGIN

	DECLARE @ID INT
	DECLARE @centreids VARCHAR(MAX)=''
	DECLARE @centrecodes VARCHAR(MAX)=''
	DECLARE @timeslots VARCHAR(MAX)=''


	DECLARE @centreid int
	DECLARE @centrecode varchar(max)
	DECLARE @timeslot varchar(max)

	IF EXISTS (select * from [LMS].[T_Teacher_Details_Interface_API] 
				where StatusID=1 and NoofAttempts=0 and ActionStatus=0 and ActionType='ADD' and FacultyID=@EmployeeID)
	BEGIN
		PRINT 1
		
		select @ID=ID from [LMS].[T_Teacher_Details_Interface_API] 
				where StatusID=1 and NoofAttempts=0 and ActionStatus=0 and ActionType='ADD' and FacultyID=@EmployeeID

		delete from [LMS].[T_Teacher_CentreMap_Details_API] where ID=@ID

		insert into [LMS].[T_Teacher_CentreMap_Details_API]
		select @ID,A.S_DayofWeek,A.I_Centre_ID,B.S_Center_Code,B.S_Center_Name,A.S_TimeSlots,1 
		from T_Faculty_Day_Centre_Map A
		inner join T_Centre_Master B on A.I_Centre_ID=B.I_Centre_Id
		where A.I_Employee_ID=@EmployeeID and A.I_Status=1



		

		DECLARE bcursor CURSOR FOR 
		select DISTINCT CentreID,CentreCode,TimeSlot from [LMS].[T_Teacher_CentreMap_Details_API] 
		where ID=@ID and StatusID=1

		OPEN bcursor  
		FETCH NEXT FROM bcursor INTO @centreid,@centrecode,@timeslot

		WHILE @@FETCH_STATUS = 0  
		BEGIN  

				set @centreids=@centreids+CAST(@centreid as varchar(10))+','
				set @centrecodes=@centrecodes+@centrecode+','
				set @timeslots=@timeslots+@timeslot

				FETCH NEXT FROM bcursor INTO @centreid,@centrecode,@timeslot
		END 

		CLOSE bcursor  
		DEALLOCATE bcursor

		update [LMS].[T_Teacher_Details_Interface_API] set TimeSlots=@timeslots,CentreCodes=@centrecodes,CentreIDs=@centreids
		where ID=@ID


	END

	ELSE IF EXISTS (select * from [LMS].[T_Teacher_Details_Interface_API] 
				where StatusID=1 and NoofAttempts=0 and ActionStatus=0 and ActionType='UPDATE' and FacultyID=@EmployeeID)
	BEGIN

		PRINT 2

		select @ID=ID from [LMS].[T_Teacher_Details_Interface_API] 
				where StatusID=1 and NoofAttempts=0 and ActionStatus=0 and ActionType='UPDATE' and FacultyID=@EmployeeID

		delete from [LMS].[T_Teacher_CentreMap_Details_API] where ID=@ID

		insert into [LMS].[T_Teacher_CentreMap_Details_API]
		select @ID,A.S_DayofWeek,A.I_Centre_ID,B.S_Center_Code,B.S_Center_Name,A.S_TimeSlots,1 
		from T_Faculty_Day_Centre_Map A
		inner join T_Centre_Master B on A.I_Centre_ID=B.I_Centre_Id
		where A.I_Employee_ID=@EmployeeID and A.I_Status=1


		DECLARE bcursor CURSOR FOR 
		select DISTINCT CentreID,CentreCode,TimeSlot from [LMS].[T_Teacher_CentreMap_Details_API] 
		where ID=@ID and StatusID=1

		OPEN bcursor  
		FETCH NEXT FROM bcursor INTO @centreid,@centrecode,@timeslot

		WHILE @@FETCH_STATUS = 0  
		BEGIN  

				set @centreids=@centreids+CAST(@centreid as varchar(10))+','
				set @centrecodes=@centrecodes+@centrecode+','
				set @timeslots=@timeslots+@timeslot

				FETCH NEXT FROM bcursor INTO @centreid,@centrecode,@timeslot
		END 

		CLOSE bcursor  
		DEALLOCATE bcursor

		print @centreids
		print @centrecodes
		print @timeslots

		update [LMS].[T_Teacher_Details_Interface_API] set TimeSlots=@timeslots,CentreCodes=@centrecodes,CentreIDs=@centreids
		where ID=@ID

	END

	ELSE

	BEGIN

		PRINT 3

		EXEC [LMS].[uspInsertTeacherDetailsForInterface] @EmployeeID,'UPDATE'

	END


END
GO
